    #region Store
    public bool SSaveMovementData(UpdateActionDataCommand command)
    {
        string cmd = $"""
            UPDATE tbl_MovementActions SET MovementActionData = N'{command.Data}' WHERE MovementActionId = {command.ActionId}
            """;

        return dataAccess.CmdSqlExecuteNonQuery(cmd) > 0;
    }

    public DataTable SGetGateProductsByTruckCrossId(int truckCrossId)
    {
        string command =
            $"""
            SELECT tbl_TagsMovement.ProductCode ,COALESCE(tbl_Products.ProductTitle,'') as ProductName,
            	   COALESCE(tbl_Products.ProductTechnicalCode,'' ) as RegCode, SUM(tbl_TagsMovement.ProductCount) as SumCount
            FROM tbl_TagsMovement INNER JOIN tbl_MovementActions ON tbl_MovementActions.MovementActionId = tbl_TagsMovement.RMovementActionId
            					  INNER JOIN tbl_Products ON tbl_Products.ProductCode = tbl_TagsMovement.ProductCode
            WHERE tbl_TagsMovement.ProductCode is not null and tbl_MovementActions.MovementActionTruckCrossId = {truckCrossId}
            Group By tbl_TagsMovement.ProductCode,tbl_Products.ProductTitle,tbl_Products.ProductTechnicalCode
            """;

        return dataAccess.SqlDataAdapter(command);
    }

    public DataTable SGetCargoByTruckCrossId(List<int> truckCrossIds)
    {
        string command =
           @$"SELECT        '' AS ProductCode, COALESCE (tbl_ProductGroup.fld_ProductGroupTitle, N'') AS ProductName, COALESCE (tbl_MovementActions.MovementActionDocumentId, N'') 
                         AS DocumentCode, COALESCE (tbl_MovementActions.MovementActionTruckCrossId, 0) AS TruckCrossId,Cast(SUM(tbl_TagsMovement.ProductCount) as int) AS SumCount
FROM            tbl_ProductGroup RIGHT OUTER JOIN
                         tbl_Products ON tbl_ProductGroup.fld_ProductGroupCode = tbl_Products.fld_ProductGroup RIGHT OUTER JOIN
                         tbl_TagsMovement ON tbl_Products.ProductCode = tbl_TagsMovement.ProductCode RIGHT OUTER JOIN
                         tbl_MovementActions ON tbl_MovementActions.MovementActionId = tbl_TagsMovement.RMovementActionId
WHERE        (tbl_MovementActions.MovementActionTruckCrossId IN ({string.Join(',', truckCrossIds)}))
GROUP BY tbl_MovementActions.MovementActionDocumentId, tbl_MovementActions.MovementActionTruckCrossId, tbl_ProductGroup.fld_ProductGroupTitle
              ";
        return dataAccess.SqlDataAdapter(command);
    }

    public DataTable SGetCollectProuductsOrderFromStore(string documentKey, string documentType)
    {
        DataTable _dtResult;

        string cmd =
            $"""
            SELECT DISTINCT
            COALESCE (tbl_DocumentItem.fld_DocumentItemProductCode, N'') AS ProductCode, 
            COALESCE (tbl_DocumentItem.fld_DocumentItemProductTitle, N'') AS ProductName,
            COALESCE (tbl_DocumentItem.fld_DocumentItemCount, 0) AS SumValue,
            tbl_DocumentHeader.fld_DocumentImportDatetime   AS Date ,
            '0' AS ProductPackValue,
            '0' AS ProductTechnicalCode,
            '0' AS CountProduct,
            '0' AS CountProductDesc,
            '0' AS ProductValue
            FROM tbl_DocumentHeader INNER JOIN 
            	 tbl_DocumentItem ON tbl_DocumentHeader.fld_DocumentKey = tbl_DocumentItem.fld_DocumentKey
            					 AND tbl_DocumentHeader.fld_DocumentType = tbl_DocumentItem.fld_DocumentType
            WHERE tbl_DocumentHeader.fld_DocumentParent = '0' 
              AND tbl_DocumentItem.fld_DocumentItemProductCode <> ''
              AND tbl_DocumentHeader.fld_DocumentKey = '{documentKey}'  
              AND  ( tbl_DocumentHeader.fld_DocumentType = '{documentType}' OR tbl_DocumentHeader.fld_DocumentType1 = '{documentType}' OR tbl_DocumentHeader.fld_DocumentType2 = '{documentType}')
            """;

        _dtResult = dataAccess.SqlDataAdapter(cmd);

        foreach (DataRow dr in _dtResult.Rows)
        {
            var cmdProductInfo = @" SELECT   ProductPackValue, ProductTechnicalCode,ProductValue 
FROM tbl_Products
WHERE(ProductCode = '" + @dr["ProductCode"].ToString() + "')";

            var _resultProductInfo = dataAccess.SqlDataReaders(cmdProductInfo);
            if (_resultProductInfo != null)
            {
                string CountProduct = "0";
                string CountProductDesc = "0";
                decimal _tempSumValue = Convert.ToDecimal(dr["SumValue"].ToString());
                decimal _tempProductPackValue = Convert.ToDecimal(_resultProductInfo[0].Value.ToString());
                decimal _tempProductValue = Convert.ToDecimal(_resultProductInfo[2].Value.ToString());
                if (_tempSumValue < _tempProductPackValue)
                {
                    CountProductDesc = (Math.Round(((_tempSumValue) / _tempProductValue), MidpointRounding.ToEven).ToString() + " کارتن") + ((((_tempSumValue) % _tempProductValue) > 0) ? (" و " + ((_tempSumValue) % _tempProductValue) + " مترمربع") : "").ToString();
                    CountProduct = "0 : " + (_tempSumValue).ToString();
                }
                else
                {
                    if (_tempSumValue % _tempProductPackValue > 0)
                    {
                        CountProductDesc = Math.Round((_tempSumValue / _tempProductPackValue), MidpointRounding.ToZero).ToString() + " پالت کامل و" + (Math.Round(((_tempSumValue % _tempProductPackValue) / _tempProductValue), MidpointRounding.ToEven).ToString() + " کارتن") + ((((_tempSumValue % _tempProductPackValue) % _tempProductValue) > 0) ? (" و " + ((_tempSumValue % _tempProductPackValue) % _tempProductValue) + " مترمربع") : "").ToString();
                        CountProduct = Math.Round((_tempSumValue / _tempProductPackValue), MidpointRounding.ToZero).ToString() + " : " + (_tempSumValue % _tempProductPackValue).ToString();
                    }
                    else
                    {
                        CountProductDesc = Math.Round((_tempSumValue / _tempProductPackValue), MidpointRounding.ToZero).ToString() + " پالت کامل  ";
                        CountProduct = Math.Round((_tempSumValue / _tempProductPackValue), MidpointRounding.ToZero).ToString();
                    }
                }

                dr["ProductPackValue"] = _resultProductInfo[0].Value.ToString();
                dr["ProductTechnicalCode"] = _resultProductInfo[1].Value.ToString();
                dr["CountProduct"] = CountProduct.ToString();
                dr["CountProductDesc"] = CountProductDesc.ToString();
                dr["ProductValue"] = _tempProductValue.ToString();
            }
        }
        return _dtResult;
    }

