    public bool SPlacementMissionResult(string[] PMCode
        , string Status
        , string ToStoreCode
        , string ToZoneId)
    {
        //Status Todo : 0 & doing : 1 & Do : 2 & Cancel : 3
        List<KeyValuePair<string, KeyValuePair<string, object>[]>> commands = new();

        foreach (string _pmCode in PMCode)
        {
            var parametersUpdatePM = new List<KeyValuePair<string, object>>();
            var commandUpdatePM = string.Format(@" UPDATE     tbl_ProductPlacementMissions
SET         fld_PPMStatus =" + Status + @", fld_PPMToZoneId_Edited ='" + ToZoneId + @"', fld_PPMDateTime =GETDATE() where fld_PPMId=" + _pmCode);
            commands.Add(new(commandUpdatePM, parametersUpdatePM.ToArray()));


            if (Status == "2")
            {
                var parametersUpdatetbl_Tags = new List<KeyValuePair<string, object>>();
                var commandUpdatetbl_Tags = string.Format(@"  UPDATE       tbl_Tags
SET                TagZone = '" + ToZoneId + @"'
FROM            tbl_Tags RIGHT OUTER JOIN
                         tbl_ProductPlacementMissions ON tbl_Tags.ProductSerial = tbl_ProductPlacementMissions.fld_PPMProductSerial
WHERE         tbl_ProductPlacementMissions.fld_PPMId = " + _pmCode);
                commands.Add(new(commandUpdatetbl_Tags, parametersUpdatetbl_Tags.ToArray()));

            }


        }
        if (dataAccess.CmdSqlExecuteNonQueryWithTransaction(commands) > 0)
        {
            return true;
        }
        else
        {
            return false;
        }
    }

    #region General Reports
    public int SGetMaxActionId(int Type)
    {
        // type 1= enter
        // type 2=exit
        var command = "SELECT Coalesce(MAX(MovementActionId),0) AS MaxId FROM tbl_MovementActions " + ((Type != -1) ? " where MovementActionTp= " + Type.ToString() : "");

        var result = int.Parse(dataAccess.SqlDataReaders(command)[0].Value.ToString());
        if (result != 0)
            return result + 1;
        return 1;
    }

    public bool SChangeProductStatusBySerial(string ProductTagEPC, int statusCode, int actionId, string destId, string userToken, string productLocationId)
    {
        var command = " UPDATE tbl_Tags SET TagStatus= @StCd, TagInActionId = @ActId, TagInDestinationId = @DestId,TagZone=@TagZone WHERE (ProductSerial = @ProductSerial ) OR (TagEpc=@ProductSerial)";

        return dataAccess.CmdSqlExecuteNonQuery(command
            , new KeyValuePair<string, object>("epc", ProductTagEPC)
, new KeyValuePair<string, object>("StCd", statusCode)
, new KeyValuePair<string, object>("ProductSerial", ProductTagEPC)
, new KeyValuePair<string, object>("ActId", actionId)
, new KeyValuePair<string, object>("DestId", destId)
, new KeyValuePair<string, object>("TagZone", productLocationId)) > 0;

    }

    public bool SSaveProductEnterAction(string[] tagEPCList, string storeCode, string locationCode, string desc, string userToken)
    {
        string RActionId = SGetMaxActionId(1).ToString();
        var childrenCommands = new List<KeyValuePair<string, KeyValuePair<string, object>[]>>();

        var commandHMovementAction = "INSERT INTO tbl_MovementActions " +
            "(MovementActionId, MovementActionTp, MovementActionStore, MovementActionUserId, MovementActionDate, MovementActionTime, MovementActionCountTags, MovementActionDestinationId,MovementActionCarPlaque,MovementActionDriverName,MovementActionDriverMobile,MovementActionData) " +
            "VALUES " +
            "(@MovementActionId, @type, MovementActionStore,@UserId,@Date,@Time,@CountTags,@DestinationId,@CarPlaque,@DriverName,@DriverMobile,@MovementActionData)";

        var parameters = new List<KeyValuePair<string, object>>();
        parameters.Add(new("MovementActionId", RActionId));
        parameters.Add(new("UserId", userToken));
        parameters.Add(new("Date", DateTimeTools.GetPersianDate()));
        parameters.Add(new("Time", DateTimeTools.GetTime()));
        parameters.Add(new("CountTags", tagEPCList.Count()));
        parameters.Add(new("MovementActionStore", storeCode));
        parameters.Add(new("DestinationId", locationCode));
        parameters.Add(new("CarPlaque", "0"));
        parameters.Add(new("DriverName", "0"));
        parameters.Add(new("DriverName", "0"));
        parameters.Add(new("MovementActionData", ""));
        parameters.Add(new("type", 1));
        childrenCommands.Add(new(commandHMovementAction, parameters.ToArray()));

        foreach (string EPC in tagEPCList)
        {
            var commandRTagMovementActionInsert = @"INSERT INTO tbl_TagsMovement (
                            TagEpc,
                            ProductCode,
                            ProductSerial,
                            ProductCount,
                            RMovementActionId,
                            RTagsMovementDate,
                            RTagsMovementTime,
                            RTagsMovementDateTime ,
                            RTagsMovementSt,
                            MovementActionStore)
                          VALUES (
                            (SELECT TagEpc FROM tbl_tags AS T WHERE (T.ProductSerial = @productSerial) OR (T.TagEpc = @productSerial)),
                            (SELECT ProductCode FROM tbl_tags AS T WHERE (T.ProductSerial = @productSerial) OR (T.TagEpc = @productSerial) ),
                            (SELECT ProductSerial FROM tbl_tags AS T WHERE (T.ProductSerial = @productSerial) OR (T.TagEpc = @productSerial) ),
                            (SELECT ProductCount FROM tbl_tags AS T WHERE (T.ProductSerial = @productSerial) OR (T.TagEpc = @productSerial) ),
                            @ActionId,
                            @Date,
                            @Time,
                            @DateTime,
                            1,
                            @MovementActionStore)";
            var param = new List<KeyValuePair<string, object>>();

            param.Add(new("productSerial", EPC));
            param.Add(new("ActionId", RActionId));
            param.Add(new("MovementActionStore", storeCode));
            param.Add(new("Date", DateTimeTools.GetPersianDate()));
            param.Add(new("Time", DateTimeTools.GetTime()));
            param.Add(new("DateTime", DateTime.Now));
            childrenCommands.Add(new(commandRTagMovementActionInsert, param.ToArray()));
        }





        if (dataAccess.CmdSqlExecuteNonQueryWithTransaction(childrenCommands) > 0)
        {
            foreach (string EPC in tagEPCList)
            {
                var resultChangeStatus = SChangeProductStatusBySerial(EPC, 1, Convert.ToInt32(RActionId), storeCode, userToken, locationCode);
            }
            return true;
        }
        else
            return false;


    }

    public int SSetProductImage(int productGalleryId, string productCode, string userToken)
    {
        var cmd = $" UPDATE tbl_Products SET ProductGalleryId = N'{productGalleryId}' WHERE ProductCode = N'{productCode}'";

        return dataAccess.CmdSqlExecuteNonQuery(cmd);
    }

    public int SaveProduct(SaveProductCommand product)
    {
        string userId = httpContext.User.GetUserId();

        logger.LogInformation("SaveProduct" + Environment.NewLine +
                              "product" + JsonConvert.SerializeObject(product) + Environment.NewLine +
                              "userId" + userId);

        var commandProductExist = "SELECT ProductCode FROM tbl_Products WHERE ProductCode = N'" + product.ProductCode + "'";

        var hasValue = dataAccess.SqlDataReaders(commandProductExist);

        var command = "";
        var finalResult = false;
        if (hasValue == null)
        {
            command = "INSERT INTO tbl_Products " +
                "(ProductCode, ProductTitle, ProductENTitle, ProductPackValue, ProductPackWeight, ProductPackVolume, ProductCountInPack, ProductValue, ProductTechnicalCode, ProductProperties, ProductType, ProductStatus, ProductSize," +
                "ProductUnit,ProductRegUser,ProductRegDateTime,fld_ProductBrand,fld_ProductGroup ,ProductTechnicalData)" +
                "VALUES(@ProductCode, @ProductTitle, @ProductENTitle, @ProductPackValue, @ProductPackWeight, @ProductPackVolume, @ProductCountInPack, @ProductValue, @ProductTechnicalCode, @ProductProperties, @ProductType, @ProductStatus, @ProductSize," +
                "@ProductUnit,@ProductRegUser,@ProductRegDateTime,@ProductBrand,@ProductGroup,@ProductTechnicalData)";


            if (configuration.GetSection("ProjectConfigs").GetSection("WmsConfigs")["CreateNewProductTitle"].ToString() != "")
            {
                product.ProductTitle = SCreateProductTitle(product);
            }

            if (configuration.GetSection("ProjectConfigs").GetSection("WmsConfigs")["CreateNewProductCode"].ToString() != "")
            {
                if (product.ProductCode.HasNoValue())
                {
                    product.ProductCode = SCreateProductCode(product);
                }
            }

            finalResult = dataAccess.CmdSqlExecuteNonQuery(command
                , new KeyValuePair<string, object>("ProductCode", product.ProductCode)
                , new KeyValuePair<string, object>("ProductTitle", product.ProductTitle)
                , new KeyValuePair<string, object>("ProductENTitle", product.ProductENTitle)
                , new KeyValuePair<string, object>("ProductPackValue", product.ProductPackValue)
                , new KeyValuePair<string, object>("ProductPackWeight", product.ProductPackWeight)
                , new KeyValuePair<string, object>("ProductPackVolume", product.ProductPackVolume)
                , new KeyValuePair<string, object>("ProductCountInPack", product.ProductCountInPack)
                , new KeyValuePair<string, object>("ProductValue", product.ProductValue)
                , new KeyValuePair<string, object>("ProductTechnicalCode", product.ProductTechnicalCode)
                , new KeyValuePair<string, object>("ProductProperties", product.ProductProperties)
                , new KeyValuePair<string, object>("ProductType", product.ProductType)
                , new KeyValuePair<string, object>("ProductStatus", product.ProductStatus)
                , new KeyValuePair<string, object>("ProductSize", product.ProductSize)
                , new KeyValuePair<string, object>("ProductUnit", product.ProductUnit)
                , new KeyValuePair<string, object>("ProductRegUser", userId)
                , new KeyValuePair<string, object>("ProductRegDateTime", DateTime.Now)
                , new KeyValuePair<string, object>("ProductBrand", product.ProductBrand)
                , new KeyValuePair<string, object>("ProductGroup", product.ProductGroup)
                , new KeyValuePair<string, object>("ProductTechnicalData", product.ProductTechnicalData ?? (object)DBNull.Value)) > 0;

        }
        else
        {
            command = @"UPDATE tbl_Products SET 
										ProductTitle = @ProductTitle,
														ProductENTitle = @ProductENTitle,
														ProductPackValue = @ProductPackValue,
														ProductPackWeight = @ProductPackWeight,
														ProductPackVolume = @ProductPackVolume,
														ProductCountInPack = @ProductCountInPack,
														ProductValue = @ProductValue,
														ProductTechnicalCode = @ProductTechnicalCode,
														ProductProperties = @ProductProperties,
														ProductType = @ProductType,
														ProductStatus = @ProductStatus,
                                                        ProductSize = @ProductSize,
														ProductUnit = @ProductUnit,
                                                        fld_ProductBrand = @ProductBrand,
                                                        fld_ProductGroup = @ProductGroup,
                                                        ProductTechnicalData = @ProductTechnicalData
									WHERE
										(ProductCode = @ProductCode)";

            finalResult = dataAccess.CmdSqlExecuteNonQuery(command
                , new KeyValuePair<string, object>("ProductCode", product.ProductCode)
                , new KeyValuePair<string, object>("ProductTitle", product.ProductTitle)
                , new KeyValuePair<string, object>("ProductENTitle", product.ProductENTitle)
                , new KeyValuePair<string, object>("ProductPackValue", product.ProductPackValue)
                , new KeyValuePair<string, object>("ProductPackWeight", product.ProductPackWeight)
                , new KeyValuePair<string, object>("ProductPackVolume", product.ProductPackVolume)
                , new KeyValuePair<string, object>("ProductCountInPack", product.ProductCountInPack)
                , new KeyValuePair<string, object>("ProductValue", product.ProductValue)
                , new KeyValuePair<string, object>("ProductTechnicalCode", product.ProductTechnicalCode)
                , new KeyValuePair<string, object>("ProductProperties", product.ProductProperties)
                , new KeyValuePair<string, object>("ProductType", product.ProductType)
                , new KeyValuePair<string, object>("ProductStatus", product.ProductStatus)
                , new KeyValuePair<string, object>("ProductSize", product.ProductSize)
                , new KeyValuePair<string, object>("ProductUnit", product.ProductUnit)
                , new KeyValuePair<string, object>("ProductBrand", product.ProductBrand)
                , new KeyValuePair<string, object>("ProductGroup", product.ProductGroup)
                , new KeyValuePair<string, object>("ProductTechnicalData", product.ProductTechnicalData ?? (object)DBNull.Value)) > 0;

        }

        if (finalResult && product.ProductGalleryId.NotEquals(0))
        {
            SSetProductImage(product.ProductGalleryId, product.ProductCode, "");
        }

        if (finalResult)
        {
            return int.Parse(GetLatestIdOfIdentityTable("tbl_Products"));
        }

        return -1;
    }

    public int SSaveProductBatch(List<SaveProductCommand> products)
    {
        string userId = httpContext.User.GetUserId();
        var strElements = "";
        try
        {
            strElements = products.Select(p => p.ProductCode).Aggregate(string.Empty, (first, next) =>
            {
                return first + (string.IsNullOrEmpty(next) ? string.Empty : (",N'" + next + "'"));
            }).Remove(0, 1);
        }
        catch
        {

        }

        if (!SCheckBatchProductUniqueness(products))
        {
            return -2;
        }

        var cmdProducts = (strElements != "") ? $" SELECT ProductCode FROM tbl_Products WHERE  ProductCode IN ({strElements}) " : "";


        var codes = (cmdProducts != "") ? dataAccess.SqlDataAdapter(cmdProducts).Select().Select(p => p.ItemArray[0].ToString()).ToList() : null;

        var childrenCommands = new List<string>();

        foreach (SaveProductCommand item in products)
        {
            if (codes == null || !codes.Any(p => p.Equals(item.ProductCode)))
            {
                if (configuration["ProjectConfigs:WmsConfigs:CreateNewProductCode"].ToString() != "")
                {
                    item.ProductCode = SCreateProductCode(item);
                }

                if (configuration["ProjectConfigs:WmsConfigs:CreateNewProductTitle"].ToString() != "")
                {
                    item.ProductTitle = SCreateProductTitle(item);
                }

                var command = @$"INSERT INTO tbl_Products
                         (ProductCode, ProductTitle, ProductENTitle, ProductPackValue, ProductPackWeight, 
                          ProductPackVolume, ProductCountInPack, ProductValue, ProductTechnicalCode, ProductProperties,
                         ProductType, ProductStatus, ProductSize, ProductUnit,ProductRegUser,ProductRegDateTime,
                         ProductGalleryId,fld_ProductGroup,fld_ProductBrand,fld_ProductIsActive,fld_ProductSubGroup,fld_ProductClass,ProductTechnicalData)
                        VALUES(N'{item.ProductCode}', N'{item.ProductTitle}', N'{item.ProductENTitle}',
                               {item.ProductPackValue}, {item.ProductPackWeight},N'{item.ProductPackVolume}', 
                               {item.ProductCountInPack}, N'{item.ProductValue}', N'{item.ProductTechnicalCode}', 
                               N'{item.ProductProperties}', N'{item.ProductType}', N'{item.ProductStatus}', N'{item.ProductSize}',
                               N'{item.ProductUnit}',N'{userId}',Getdate(),N'{item.ProductGalleryId}',
                               N'{item.ProductGroup}',N'{item.ProductBrand}',{(item.IsActive ? "1" : "0")},N'{item.ProductSubGroup}',N'{item.ProductClass}' , N'{item.ProductTechnicalData}')";

                childrenCommands.Add(command);
            }
            else
            {
                var command = $@"UPDATE tbl_Products SET 
										ProductTitle = N'{item.ProductTitle}',
														ProductENTitle = N'{item.ProductENTitle}',
														ProductPackValue = {item.ProductPackValue},
														ProductPackWeight = {item.ProductPackWeight},
														ProductPackVolume = N'{item.ProductPackVolume}',
														ProductCountInPack = {item.ProductCountInPack},
														ProductValue = {item.ProductValue},
														ProductTechnicalCode = N'{item.ProductTechnicalCode}',
														ProductProperties = N'{item.ProductProperties}',
														ProductType = N'{item.ProductType}',
														ProductStatus = N'{item.ProductStatus}',
                                                        ProductSize = N'{item.ProductSize}',
														ProductUnit = N'{item.ProductUnit}',
                                                        ProductGalleryId = N'{item.ProductGalleryId}',
                                                        fld_ProductGroup = N'{item.ProductGroup}',
                                                        fld_ProductBrand = N'{item.ProductBrand}',
                                                        fld_ProductIsActive = {(item.IsActive ? "1" : "0")},
                                                        fld_ProductSubGroup = N'{item.ProductSubGroup}',
                                                        fld_ProductClass = N'{item.ProductClass}',
                                                        ProductTechnicalData = N'{item.ProductTechnicalData}'

									WHERE
										(ProductCode = N'{item.ProductCode}')";

                childrenCommands.Add(command);
            }
        }

        return dataAccess.CmdSqlExecuteNonQueryWithTransaction(childrenCommands) == 1 ? 1 : 0;
    }

    public int SSaveProductByQc(SaveProductCommand command)
    {
        var qcs = SGetAllQcs();

        List<string> commands = new();

        List<SaveProductCommand> products = new();

        foreach (ProductQc qc in qcs)
        {
            if (command.ProductStatus == qc.Code)
            {
                continue;
            }

            SaveProductCommand newCommand = (SaveProductCommand)command.Clone();
            newCommand.ProductStatus = qc.Code;

            if (configuration["ProjectConfigs:WmsConfigs:CreateNewProductCode"].ToString().HasValue())
            {
                newCommand.ProductCode = SCreateProductCode(newCommand);
            }

            if (newCommand.ProductTitle.Contains('('))
            {
                newCommand.ProductTitle = newCommand.ProductTitle.Split(" (")[0];
            }
            if (configuration.GetSection("ProjectConfigs").GetSection("WmsConfigs")["CreateNewProductTitle"].ToString() != "")
            {
                newCommand.ProductTitle = SCreateProductTitle(newCommand);
            }


            products.Add(newCommand);
        }

        return SSaveProductBatch(products);
    }

    public bool SCheckProductUniqueness(SaveProductCommand command)
    {
        string fieldStr = configuration.GetSection("ProjectConfigs").GetSection("WmsConfigs")["ProductUniquenessOn"];

        if (fieldStr.HasNoValue())
        {
            return true;
        }

        string[] fields = fieldStr.Contains(",") ? fieldStr.Split(',') : new string[] { fieldStr };

        string commandStr = @" SELECT ProductCode FROM tbl_Products WHERE ";

        string whereStr = $" ProductCode != N'{command.ProductCode}' ";

        List<KeyValuePair<string, object>> parameters = new();

        var type = command.GetType();

        foreach (string field in fields)
        {
            if (whereStr.HasValue())
            {
                whereStr += " AND ";
            }

            whereStr += $" {field} = @{field} ";

            var prop = type.GetProperties().FirstOrDefault(p => p.Name.Equals(field));

            parameters.Add(new(field, prop.GetValue(command).ToString()));
        }

        return dataAccess.SqlDataAdapter(commandStr + whereStr, parameters.ToArray())
                         .Rows
                         .Count == 0;
    }

    public bool SCheckBatchProductUniqueness(List<SaveProductCommand> commands)
    {
        string fieldStr = configuration["ProjectConfigs:WmsConfigs:ProductUniquenessOn"];

        if (fieldStr.HasNoValue())
        {
            return true;
        }

        string[] fields = fieldStr.Contains(",") ? fieldStr.Split(',') : new string[] { fieldStr };

        foreach (SaveProductCommand command in commands)
        {

            string commandStr = $" SELECT ProductCode FROM tbl_Products WHERE ";

            string whereStr = $"ProductCode != N'{command.ProductCode}'";

            List<KeyValuePair<string, object>> parameters = new();

            var type = command.GetType();

            foreach (string field in fields)
            {
                if (whereStr.HasValue())
                {
                    whereStr += " AND ";
                }

                whereStr += $" {field} = @{field} ";

                var prop = type.GetProperties().FirstOrDefault(p => p.Name.Equals(field));

                parameters.Add(new(field, prop.GetValue(command).ToString()));
            }

            bool result = dataAccess.SqlDataAdapter(commandStr + whereStr, parameters.ToArray())
                             .Rows
                             .Count == 0;

            if (!result)
            {
                return false;
            }
        }

        return true;
    }


    public string SCreateProductTitle(SaveProductCommand command)
    {
        string NewProductTitle = "";

        switch (configuration.GetSection("ProjectConfigs").GetSection("WmsConfigs")["CreateNewProductTitle"].ToString())
        {
            case "sina":
                var qclist = SGetAllQcs();
                var productTypeList = SGetAllProductType("", false);
                var sizeList = SGetAllProductPropertyC("", false);


                if (command.ProductTitle.Contains('('))
                {
                    command.ProductTitle = command.ProductTitle.Split('(')[0];
                }


                var BrandList = SGetAllProductBrands();
                var ProudctTypeTitle = "";
                var ProudctSizeTitle = "";


                if (command.ProductTitle.ToString().ToLower().Contains(" (".ToLower()))
                {
                    command.ProductTitle = command.ProductTitle.Split(" (")[0];
                }
                foreach (DataRow dr in productTypeList.Rows)
                {
                    if (dr["Code"].ToString() == command.ProductType)
                    {
                        ProudctTypeTitle = dr["Title"].ToString();
                        break;
                    }
                }

                foreach (DataRow dr in sizeList.Rows)
                {
                    if (dr["Code"].ToString() == command.ProductSize)
                    {
                        ProudctSizeTitle = dr["Title"].ToString();
                        break;
                    }
                }

                NewProductTitle = command.ProductTitle + " (" + command.ProductTechnicalCode + ") " + BrandList.FirstOrDefault(p => p.Code == command.ProductBrand).Title + " " + ProudctSizeTitle + " درجه " + qclist.FirstOrDefault(p => p.Code == command.ProductStatus).Title + " Jet SQ - سالن " + ProudctTypeTitle;
                break;
        }
        return NewProductTitle;
    }

    public string SCreateProductCode(SaveProductCommand command)
    {
        string NewProductCode = "";
        switch (configuration.GetSection("ProjectConfigs").GetSection("WmsConfigs")["CreateNewProductCode"].ToString())
        {
            case "sina":
                NewProductCode = command.ProductType.PadRight(2, '0').Substring(0, 2) + command.ProductSize.PadLeft(2, '0').Substring(0, 2) + command.ProductTechnicalCode.PadLeft(4, '0').Substring(0, 4) + command.ProductBrand.PadLeft(1, '0').Substring(0, 1) + command.ProductStatus.Substring(0, 1);
                break;
        }
        return NewProductCode;
    }

    public int SRemoveProduct(string productCode, string userToken)
    {
        var tagDt = dataAccess.SqlDataAdapter($" SELECT COUNT(*) FROM [tbl_Tags] WHERE [ProductCode] = N'{productCode}' ").Select();

        if ((int)tagDt.First().ItemArray.First() != 0)
        {
            return -2;
        }

        return dataAccess
            .CmdSqlExecuteNonQuery($" DELETE FROM tbl_Products WHERE [ProductCode] = N'{productCode}' ");
    }

    public bool SSaveProductExitAction(SaveExitActionCommand exitAction)
    {
        string userToken = httpContext.User.GetUserId();

        if (exitAction.Gate == "-1" || exitAction.Gate.HasNoValue())
        {
            exitAction.Gate = configuration.GetSection("ProjectConfigs").GetSection("WmsConfigs").GetSection("TruckCrossGate")["GateNumber"].ToString();
        }

        var cmdcheckinvId = @"SELECT MovementActionId FROM tbl_MovementActions where ( MovementActionUHFLogId=" + exitAction.GateOperationCode + " ) ";
        var checkinvId = dataAccess.SqlDataAdapter(cmdcheckinvId).Select();

        if (checkinvId.Count() == 0)
        {
            return SSaveMovementAction2(exitAction.GateOperationCode.ToString()
                , exitAction.SourceWarehouseCode
                , exitAction.DestinationWarehouseCode
                , exitAction.Gate
                , userToken
                , "0"
                , JToken.Parse(exitAction.MovementActionData)
                , "0"
                , exitAction.MovementActionDesc
                , exitAction.DocumentId
                , exitAction.TruckCrossId, new List<string> { "" }, new List<int> { exitAction.GateOperationCode });
        }
        else
        {
            return false;
        }
    }

    public DocumentCheckType SGetDefaultDocumentCheckType()
    {
        int documentCheckType = 1;

        if (int.TryParse(configuration[$"ProjectConfigs:WmsConfigs:DocumentRemain"], out int remainCheck))
        {
            documentCheckType = remainCheck;
        }

        return (DocumentCheckType)documentCheckType;
    }

    public List<GetDocProductDataByDocKeyVm> SGetDocProductDataByDocKey(string documentKey)
    => apiContext.DocumentItems
                 .Include(p => p.DocumentHeader)
                 .Where(p => p.Key.Equals(documentKey))
                 .Select(p => new GetDocProductDataByDocKeyVm()
                 {
                     ProductCode = p.ProductCode,
                     ProductName = p.ProductTitle,
                     SumValue = p.Count,
                     DocumentHeaderData = p.DocumentHeader.HeaderData
                 })
                 .ToList();

    public List<GetDocProductDataByDocKeyVm> SGetDocumentItemData(string documentKey, string sourceWarehouse, string destinationWarehouse)
    {
        var documentType = GetActionType(sourceWarehouse, destinationWarehouse);

        DocumentCheckType docCheckType = SGetDefaultDocumentCheckType();

        var data = apiContext.DocumentItems
            .Include(p => p.DocumentHeader)
            .Where(p => p.Key == documentKey &&
                        (p.DocumentType == documentType.ToString() ||
                        p.DocumentType1 == documentType.ToString() ||
                        p.DocumentType2 == documentType.ToString())
                        &&
                        (p.DocumentHeader.DocumentType == documentType.ToString() ||
                        p.DocumentHeader.DocumentType1 == documentType.ToString() ||
                        p.DocumentHeader.DocumentType2 == documentType.ToString()))
            .Select(p => new GetDocProductDataByDocKeyVm()
            {
                ProductCode = p.ProductCode,
                ProductName = p.ProductTitle,
                SumValue = p.Count,
                DocumentHeaderData = p.DocumentHeader.HeaderData,
                DocumentCheckType = (DocumentCheckType)p.DocumentHeader.DocumentCheckType
            }).ToList();

        foreach (var item in data)
        {
            if (item.DocumentCheckType == DocumentCheckType.ProductCodeAndDocCodeRemain)
            {
                item.DocumentUsedCount = SGetDocumentItemUsedCountByDocKeyAndProductCode(documentKey, documentType, item.ProductCode);
            }
            else if (item.DocumentCheckType == DocumentCheckType.DocCodeRemain)
            {
                item.DocumentUsedCount = SGetDocumentItemUsedCountByDocKey(documentKey, documentType);
            }
            else
            {
                item.DocumentUsedCount = null;
            }
        }

        return data;
    }

    public decimal SGetDocumentItemUsedCountByDocKeyAndProductCode(string key, int type, string productCode)
    {
        string command = $"""
        SELECT COALESCE(SUM(tbl_Tags.ProductCount),0)
        FROM tbl_Tags 
        WHERE tbl_Tags.ProductSerial IN(
        SELECT DISTINCT tbl_TagsMovement.ProductSerial
        FROM tbl_TagsMovement
        WHERE tbl_TagsMovement.ProductCode = N'{productCode}'  
        AND tbl_TagsMovement.RMovementActionType = N'{type}'
        AND tbl_TagsMovement.RMovementActionDocumentId = N'{key}')
        """;

        var result = dataAccess.SqlDataAdapter(command);

        if (result.Rows.Count != 0)
        {
            return (decimal)result.Select()
                  .First()
                  .ItemArray[0];
        }

        return 0;
    }

    public decimal SGetDocumentItemUsedCountByDocKey(string key, int type)
    {
        string command = $"""
        SELECT COALESCE(SUM(tbl_Tags.ProductCount),0)
        FROM tbl_Tags 
        WHERE tbl_Tags.ProductSerial IN(
        SELECT DISTINCT tbl_TagsMovement.ProductSerial
        FROM tbl_TagsMovement
        WHERE tbl_TagsMovement.RMovementActionType = N'{type}'
        AND tbl_TagsMovement.RMovementActionDocumentId = N'{key}'
        )
        """;

        var result = dataAccess.SqlDataAdapter(command);

        if (result.Rows.Count != 0)
        {
            return (decimal)result.Select()
                  .First()
                  .ItemArray[0];
        }

        return 0;
    }

    public List<GetDocProductDataByDocKeyVm> SGetDocumentItemDataByDocType(string documentKey, string documentType)
    {
        DocumentCheckType defaultDocCheckType = SGetDefaultDocumentCheckType();

        var data = apiContext.DocumentItems
        .Include(p => p.DocumentHeader)
        .Where(p => p.Key == documentKey &&
                    (p.DocumentType == documentType.ToString() ||
                    p.DocumentType1 == documentType.ToString() ||
                    p.DocumentType2 == documentType.ToString())
                    &&
                    (p.DocumentHeader.DocumentType == documentType.ToString() ||
                    p.DocumentHeader.DocumentType1 == documentType.ToString() ||
                    p.DocumentHeader.DocumentType2 == documentType.ToString()))
        .Select(p => new GetDocProductDataByDocKeyVm()
        {
            ProductCode = p.ProductCode,
            ProductName = p.ProductTitle,
            SumValue = p.Count,
            DocumentHeaderData = p.DocumentHeader.HeaderData,
            DocumentCheckType = p.DocumentHeader.DocumentCheckType != null ? (DocumentCheckType)p.DocumentHeader.DocumentCheckType : defaultDocCheckType
        })
        .ToList();

        foreach (var item in data)
        {
            if (item.DocumentCheckType == DocumentCheckType.ProductCodeAndDocCodeRemain)
            {
                item.DocumentUsedCount = SGetDocumentItemUsedCountByDocKeyAndProductCode(documentKey, int.Parse(documentType), item.ProductCode);
            }
            else if (item.DocumentCheckType == DocumentCheckType.DocCodeRemain)
            {
                item.DocumentUsedCount = SGetDocumentItemUsedCountByDocKey(documentKey, int.Parse(documentType));
            }
            else
            {
                item.DocumentUsedCount = null;
            }
        }

        return data;
    }

    public List<CeramicAggregateResult> SPSecurityGateReport(string gate, int gateOperationCode)
    {
        var whereString = string.Empty;
        var innerWhereString = string.Empty;
        if (!gate.Equals("-1"))
        {
            whereString += " AND (fld_Reader_Gate = N'" + gate + "') ";
            innerWhereString += " AND (U.fld_Reader_Gate = N'" + gate + "') ";
        }

        if (!gateOperationCode.Equals(-1))
        {
            whereString += " AND (fld_InventoryId = " + gateOperationCode + ")";
            innerWhereString += " AND (U.fld_InventoryId = " + gateOperationCode + ")";
        }


        string TruckCrossGateNumber = configuration.GetSection("ProjectConfigs").GetSection("WmsConfigs").GetSection("TruckCrossGate")["GateNumber"].ToString();
        var cmd =
            @"SELECT DISTINCT 
'0' AS [Desc],
tbl_UHF_ReaderLog.fld_TagSerial as Epc,
COALESCE(tbl_Tags.ProductSerial,N'-1') as [ProductSerial] ,
tbl_Tags.ProductCode,
tbl_Tags.ProductName,
tbl_Tags.RegCode,
1 as [Count] ,
Coalesce(tbl_Tags.ProductCount,0) AS SumValue ,
(select MAX(U.fld_TagRead_DateTime)  from tbl_UHF_ReaderLog as U " +
            $" WHERE U.fld_TagSerial is not null {innerWhereString} "
            + @")as MaxDate,
tbl_Tags.TagStatus as Qc,
 COALESCE (tbl_Tags.Freeze, 0) AS Freeze,
COALESCE (tbl_Tags.Lock, 0)                          AS Lock, 
COALESCE (tbl_Tags.fld_LastInspectResult, N'[]') AS fld_LastInspectResult,
COALESCE(tbl_Products.ProductUnit,N'') as ProductUnit,
COALESCE(tbl_Tags.TagInDestinationId,N'') as SourceWarehouseCode

               
FROM            tbl_UHF_ReaderLog LEFT OUTER JOIN
                                         tbl_Tags ON tbl_UHF_ReaderLog.fld_TagSerial = tbl_Tags.TagEpc LEFT OUTER JOIN 
										 tbl_Products ON tbl_Tags.ProductCode = tbl_Products.ProductCode
                "
        + ($" WHERE tbl_UHF_ReaderLog.fld_TagSerial is not null AND fld_Reader_Gate = N'{TruckCrossGateNumber}' {whereString} "
                                              ///   + " GROUP BY tbl_Tags.TagEpc, tbl_Tags.ProductSerial, tbl_Tags.ProductCode,tbl_Tags.ProductName ")
                                              );
        //9 tagStatus  10 freez  11 lock  12 last
        var finalList = new List<CeramicAggregateResult>();
        var strTags = string.Empty;
        var listTag = dataAccess.SqlDataAdapter(cmd, 120);
        decimal sumValueCorrectProduct = 0;
        string MaxDate = "";
        decimal countCorrectProduct = 0;
        decimal sumValueIncorrectProduct = 0;
        decimal countIncorrectProduct = 0;

        foreach (DataRow tag in listTag.Rows)
        {
            if (tag[2].ToString() != "-1") //  registered
            {

                if (tag[10].ToString() != "1") // Freeze
                {

                    if (!bool.Parse(configuration.GetSection("ProjectConfigs").GetSection("WmsConfigs")["QcCheck"]) || tag[12].ToString() != "[]") // Not Inspect
                    {
                        if (tag[11].ToString() != "1") // Lock
                        {
                            if (tag[9].ToString() == "1") // entered
                            {
                                if (!string.IsNullOrEmpty(strTags))
                                    strTags += ",";
                                strTags += ($"N'{tag[1].ToString()}'");
                                sumValueCorrectProduct += decimal.Parse(tag[7].ToString());
                                countCorrectProduct++;
                                MaxDate = tag[8].ToString();
                            }
                            else if (tag[9].ToString() == "0") // not entered
                            {
                                sumValueIncorrectProduct += decimal.Parse(tag[7].ToString());
                                countIncorrectProduct++;
                                MaxDate = tag[8].ToString();
                                finalList.Add(new CeramicAggregateResult()
                                {
                                    Error = "4",
                                    ProductCode = tag[3].ToString(),
                                    ProductCount = Convert.ToDecimal(tag[6].ToString()),
                                    ProductName = tag[4].ToString(),
                                    ProductSerial = tag[2].ToString(),
                                    SumCount = Convert.ToDecimal(tag[7].ToString()),
                                    TagEpc = "کالا وارد انبار نشده است",
                                    MaxDate = "",
                                    Regcode = tag[5].ToString(),
                                    ProductUnit = tag[13].ToString(),
                                    SourceWarehouseCode = tag[14].ToString()
                                });
                            }
                            else if (tag[9].ToString() == "2") // exited
                            {
                                sumValueIncorrectProduct += decimal.Parse(tag[7].ToString());
                                countIncorrectProduct++;
                                MaxDate = tag[8].ToString();
                                finalList.Add(new CeramicAggregateResult()
                                {
                                    Error = "4",
                                    ProductCode = tag[3].ToString(),
                                    ProductCount = Convert.ToDecimal(tag[6].ToString()),
                                    ProductName = tag[4].ToString(),
                                    ProductSerial = tag[2].ToString(),
                                    SumCount = Convert.ToDecimal(tag[7].ToString()),
                                    TagEpc = "کالا از انبار خارج شده است",
                                    MaxDate = "",
                                    Regcode = tag[5].ToString(),
                                    ProductUnit = tag[13].ToString(),
                                    SourceWarehouseCode = tag[14].ToString()
                                });
                            }
                        }
                        else
                        {
                            sumValueIncorrectProduct += decimal.Parse(tag[7].ToString());
                            countIncorrectProduct++;
                            MaxDate = tag[8].ToString();
                            finalList.Add(new CeramicAggregateResult()
                            {
                                Error = "4",
                                ProductCode = tag[3].ToString(),
                                ProductCount = Convert.ToDecimal(tag[6].ToString()),
                                ProductName = tag[4].ToString(),
                                ProductSerial = tag[2].ToString(),
                                SumCount = Convert.ToDecimal(tag[7].ToString()),
                                TagEpc = "بازرسی کالا مردود است",
                                MaxDate = "",
                                Regcode = tag[5].ToString(),
                                ProductUnit = tag[13].ToString(),
                                SourceWarehouseCode = tag[14].ToString()
                            });
                        }
                    }
                    else
                    {
                        sumValueIncorrectProduct += decimal.Parse(tag[7].ToString());
                        countIncorrectProduct++;
                        MaxDate = tag[8].ToString();
                        finalList.Add(new CeramicAggregateResult()
                        {
                            Error = "4",
                            ProductCode = tag[3].ToString(),
                            ProductCount = Convert.ToDecimal(tag[6].ToString()),
                            ProductName = tag[4].ToString(),
                            ProductSerial = tag[2].ToString(),
                            SumCount = Convert.ToDecimal(tag[7].ToString()),
                            TagEpc = "کالا بازرسی نشده است",
                            MaxDate = "",
                            Regcode = tag[5].ToString(),
                            ProductUnit = tag[13].ToString(),
                            SourceWarehouseCode = tag[14].ToString()
                        });
                    }
                }
                else
                {
                    sumValueIncorrectProduct += decimal.Parse(tag[7].ToString());
                    countIncorrectProduct++;
                    MaxDate = tag[8].ToString();
                    finalList.Add(new CeramicAggregateResult()
                    {
                        Error = "4",
                        ProductCode = tag[3].ToString(),
                        ProductCount = Convert.ToDecimal(tag[6].ToString()),
                        ProductName = tag[4].ToString(),
                        ProductSerial = tag[2].ToString(),
                        SumCount = Convert.ToDecimal(tag[7].ToString()),
                        TagEpc = "کالا فریز شده است",
                        MaxDate = "",
                        Regcode = tag[5].ToString(),
                        ProductUnit = tag[13].ToString(),
                        SourceWarehouseCode = tag[14].ToString()
                    });
                }
            }
            else
            {
                sumValueIncorrectProduct += decimal.Parse(tag[7].ToString());
                countIncorrectProduct++;
                MaxDate = tag[8].ToString();
                if (tag[1].ToString().Contains("E2000"))
                {
                    finalList.Add(new CeramicAggregateResult()
                    {
                        Error = "4",
                        ProductCode = "",
                        ProductCount = 0,
                        ProductName = "",
                        ProductSerial = "",
                        SumCount = 0,
                        TagEpc = tag[1].ToString() + " تگ ثبت نشده ",
                        MaxDate = ""
                    });
                }
            }

        }


        finalList.Add(new CeramicAggregateResult()
        {
            Error = "1",
            TagEpc = "",
            ProductCode = "",
            ProductSerial = "",
            ProductName = "",
            ProductCount = countCorrectProduct,
            SumCount = sumValueCorrectProduct,
            MaxDate = MaxDate
        });
        if (string.IsNullOrEmpty(strTags))
        {
            return finalList;
        }
        var cmdGetTajamoee =
            @" SELECT DISTINCT tbl_Tags.ProductCode, tbl_Products.ProductTitle, SUM(tbl_Tags.ProductCount) AS SumValue, COUNT(tbl_Tags.ProductSerial) AS Count, tbl_Products.ProductUnit,
                               COALESCE(String_Agg(tbl_Tags.TagInDestinationId,','),N'') as SourceWarehouseCode
FROM   tbl_Tags LEFT OUTER JOIN
             tbl_Products ON tbl_Tags.ProductCode = tbl_Products.ProductCode
 WHERE TagEpc IN(" + strTags + ") GROUP BY tbl_Tags.ProductCode, tbl_Products.ProductTitle,tbl_Products.ProductUnit  ";
        logger.LogInformation("SPSecurityGateReport",
new KeyValuePair<string, string>("gate", gate),
new KeyValuePair<string, string>("gateOperationCode", gateOperationCode.ToString()),
new KeyValuePair<string, string>("cmd", cmd),
new KeyValuePair<string, string>("cmdGetTajamoee", cmdGetTajamoee)
);


        var listTajamoee = dataAccess.SqlDataAdapter(cmdGetTajamoee);
        foreach (DataRow Rowdata in listTajamoee.Rows)
        {
            var data = new CeramicAggregateResult()
            {
                Error = "3",
                //     TagEpc = Rowdata[4].ToString(),
                ProductCode = Rowdata[0].ToString(),
                ProductSerial = "",
                ProductName = Rowdata[1].ToString(),
                ProductCount = decimal.Parse(Rowdata[2].ToString()),
                SumCount = decimal.Parse(Rowdata[3].ToString()),
                MaxDate = MaxDate,
                ProductUnit = Rowdata[4].ToString(),
                SourceWarehouseCode = Rowdata[5].ToString().Split(',').First()
            };
            //if (!finalList.Any(p => p.ProductCode.Equals(data.ProductCode)))
            finalList.Add(data);
        }

        //finalList = finalList.GroupBy(p => p.ProductCode)
        //                     .Select(p=> new CeramicAggregateResult()
        //                     {
        //                         Error = p.First().Error,
        //                         ProductSerial = "",
        //                         ProductName = p.First().ProductName,
        //                         ProductCount = p.Sum(ps=>ps.ProductCount),
        //                         SumCount = p.Sum(ps => ps.SumCount),
        //                         MaxDate = p.First().MaxDate
        //                     })
        //                     .ToList();

        return finalList;
    }

    public List<CeramicAggregateResult> SPSecurityGateByTruckCrossReport(string gate, int gateOperationCode)
    {
        var whereString = string.Empty;
        var innerWhereString = string.Empty;
        if (!gate.Equals("-1"))
        {
            whereString += " AND (fld_Reader_Gate = N'" + gate + "') ";
            innerWhereString += " AND (U.fld_Reader_Gate = N'" + gate + "') ";
        }

        if (!gateOperationCode.Equals(-1))
        {
            whereString += " AND (fld_InventoryId = " + gateOperationCode + ")";
            innerWhereString += " AND (U.fld_InventoryId = " + gateOperationCode + ")";
        }


        string TruckCrossGateNumber =
            gate.HasNoValue() ?
            configuration["ProjectConfigs:WmsConfigs:TruckCrossGate:GateNumber"].ToString() : gate;
        var cmd =
            @$"SELECT DISTINCT 
                         '0' AS [Desc], tbl_UHF_ReaderLog.fld_TagSerial AS Epc, COALESCE (tbl_Tags.ProductSerial, N'-1') AS ProductSerial, tbl_Tags.ProductCode, tbl_Tags.ProductName, tbl_Tags.RegCode, 1 AS Count, 
                         COALESCE (tbl_Tags.ProductCount, 0) AS SumValue,
                             (SELECT        MAX(fld_TagRead_DateTime) AS Expr1
                               FROM            tbl_UHF_ReaderLog AS U 
             WHERE U.fld_TagSerial is not null {innerWhereString} ) AS MaxDate, tbl_Destination.DestinationType, COALESCE (tbl_Tags.Freeze, 0) AS Freeze, COALESCE (tbl_Tags.Lock, 0) AS Lock, COALESCE (tbl_Tags.fld_InspectActionId, N'0') 
                         AS fld_InspectActionId, COALESCE (tbl_Products.ProductUnit, N'') AS ProductUnit, COALESCE (tbl_Tags.TagInDestinationId, N'') AS SourceWarehouseCode
FROM            tbl_Destination RIGHT OUTER JOIN
