    public DataTable SReportSecurityTags(string gate, string destinationCode)
    {



        string UHFGateActionDestinationCode = "";
        var whereString = "";

        if (gate != "")
        {
            whereString = $" AND tbl_UHF_ReaderLog.fld_Reader_Gate = N'{gate}' ";
        }

        if (destinationCode != "")
        {
            UHFGateActionDestinationCode = destinationCode;
        }

        string command = $@"SELECT DISTINCT TOP (100) tbl_UHF_ReaderLog.fld_InventoryId AS Code, 
COUNT(tbl_UHF_ReaderLog.fld_TagSerial) AS Count, 
                             COALESCE((SELECT        TOP (1) fld_TagRead_DateTime
                                 FROM            tbl_UHF_ReaderLog AS ReaderLog
                                 WHERE        (fld_InventoryId = tbl_UHF_ReaderLog.fld_InventoryId)
                                 ORDER BY fld_TagRead_DateTime DESC), N'') AS DateTime,
        " + ((UHFGateActionDestinationCode != "") ? ($@" Case (SELECT        COUNT(DISTINCT tbl_UHF_ReaderLog_3.fld_TagSerial) AS Expr1 FROM            tbl_UHF_ReaderLog as tbl_UHF_ReaderLog_3  LEFT OUTER JOIN                          tbl_Tags ON tbl_UHF_ReaderLog_3.fld_TagSerial = tbl_Tags.TagEpc WHERE        (tbl_UHF_ReaderLog_3.fld_InventoryId = tbl_UHF_ReaderLog.fld_InventoryId) AND (tbl_UHF_ReaderLog_3.fld_TagSerial <> '000') AND (tbl_Tags.ProductSerial IS NOT NULL) AND                              ((SELECT   TOP(1)    TagsMovementId                                 FROM            tbl_TagsMovement AS tbl_TagsMovement_1                                  WHERE        (RMovementActionDestinationId = '" + UHFGateActionDestinationCode + $@"') AND (TagEpc = tbl_UHF_ReaderLog_3.fld_TagSerial)) IS NULL)) when 0 then N'ثبت شده' else N'ثبت نشده' end ")
            : ($@" CASE SELECT      Count(MovementActionId)  FROM            tbl_MovementActions WHERE        (MovementActionUHFLogId = tbl_UHF_ReaderLog.fld_InventoryId) WHEN >0 THEN N'ثبت شده' ELSE N'نامشخص' END")) + $@"  AS Status,
                                        COALESCE(tbl_UHF_ReaderLog.fld_Reader_Gate,N'') as GateCode
            FROM            tbl_UHF_ReaderLog LEFT OUTER JOIN
                                     tbl_Tags ON tbl_UHF_ReaderLog.fld_TagSerial = tbl_Tags.TagEpc LEFT OUTER JOIN
                                     tbl_MovementActions ON tbl_UHF_ReaderLog.fld_InventoryId = tbl_MovementActions.MovementActionUHFLogId
            WHERE        (tbl_Tags.Id IS NOT NULL) {whereString}
            GROUP BY tbl_UHF_ReaderLog.fld_InventoryId, tbl_MovementActions.MovementActionId,tbl_UHF_ReaderLog.fld_Reader_Gate

            ORDER BY Code DESC             
            ";


        logger.LogInformation("SReportSecurityTags" + Environment.NewLine +
                           $"gate:{gate}" + Environment.NewLine +
                           $"destinationCode:{destinationCode}" + Environment.NewLine +
                           " Command: " + command);






        //string command = $"""

        //                SELECT DISTINCT TOP (100) tbl_UHF_ReaderLog.fld_InventoryId AS Code, COUNT(tbl_UHF_ReaderLog.fld_TagSerial) AS Count, COALESCE
        //                                 ((SELECT        TOP (1) fld_TagRead_DateTime
