    public bool SRemoveUser(string username)
    {
        var childrenCommands = new List<KeyValuePair<string, KeyValuePair<string, object>[]>>();
        var parametersUser = new List<KeyValuePair<string, object>>();
        var parametersRole = new List<KeyValuePair<string, object>>();

        var deleteUser = " Delete FROM tbl_User WHERE Username = @Usr ";
        parametersUser.Add(new("Usr", username));
        var deleteRole = " Delete FROM tbl_UserRole WHERE UserId = (SELECT Id FROM tbl_User WHERE Username = @Usr) ";
        parametersRole.Add(new("Usr", username));
        childrenCommands.Add(new(deleteUser, parametersUser.ToArray()));
        childrenCommands.Add(new(deleteRole, parametersRole.ToArray()));

        return dataAccess.CmdSqlExecuteNonQueryWithTransaction(childrenCommands) > 0;
    }

    public bool SAddUserToRole(string username, string rolename)
    {
        try
        {
            var childrenCommands = new List<KeyValuePair<string, KeyValuePair<string, object>[]>>();

            var delete = " Delete FROM tbl_UserRole WHERE UserId = (SELECT Id FROM tbl_User WHERE Username = @Usr) ";
            var parameters = new List<KeyValuePair<string, object>>();

            parameters.Add(new("Usr", username));
            childrenCommands.Add(new(delete, parameters.ToArray()));

            foreach (DataRow row in GetAllRoles("Ceramic client").Rows)
            {
                //if (!rolename.ToLower().Equals("admin"))
                //    if (row.ItemArray[2].ToString().ToLower().Equals("admin"))
                //        continue;
                if (row.ItemArray[2].ToString().Equals(rolename))
                {
                    var add =
                            " INSERT INTO tbl_UserRole (UserId,RoleId) VALUES ((SELECT Id FROM tbl_User WHERE Username = @Usr),@Rle)  ";
                    var param = new List<KeyValuePair<string, object>>();

                    param.Add(new("Rle", row.ItemArray[0].ToString()));
                    param.Add(new("Usr", username));
                    childrenCommands.Add(new(add, param.ToArray()));
                }
            }
            return dataAccess.CmdSqlExecuteNonQueryWithTransaction(childrenCommands) > 0;
        }
        catch (Exception e)
        {
            Console.WriteLine(e);
            throw;
        }
    }

    public List<DataElement> SGetDataMiningElements(string DataMiningElementsId, string DataMiningElementsTitle)
    {
        var whereString = string.Empty;
        var innerWhereString = string.Empty;
        if (!DataMiningElementsId.Equals("-1"))
        {
            whereString += (whereString == "") ? " Where " : " AND ";
            whereString += "  (tbl_DataMiningElements.fld_DataMiningElementsId =  " + DataMiningElementsId + ") ";
        }

        if (!DataMiningElementsTitle.Equals("-1"))
        {
            whereString += (whereString == "") ? " Where " : " AND ";
            whereString += "   (tbl_DataMiningElements.fld_DataMiningElementsTitle Like N'%" + DataMiningElementsTitle + "%')";
        }


        var cmd = @$" SELECT       fld_DataMiningElementsId, fld_DataMiningElementsTitle,
                                        fld_DataMiningElementsCommand, fld_DataMiningElementsDesc,fld_DataMiningElementsType FROM   
                                    tbl_DataMiningElements {whereString}";

        var elements = new List<DataElement>();
        var _dtDataMiningElements = dataAccess.SqlDataAdapter(cmd);

        foreach (DataRow _DataMiningElement in _dtDataMiningElements.Rows)
        {
            elements.Add(new DataElement()
            {
                DataMiningElementsCommand = _DataMiningElement["fld_DataMiningElementsCommand"].ToString(),
                DataMiningElementsDesc = _DataMiningElement["fld_DataMiningElementsDesc"].ToString(),
                DataMiningElementsId = Convert.ToInt32(_DataMiningElement["fld_DataMiningElementsId"].ToString()),
                DataMiningElementsTitle = _DataMiningElement["fld_DataMiningElementsTitle"].ToString(),
                DataMiningElementsType = _DataMiningElement["fld_DataMiningElementsType"].ToString(),
            });
        }

        return elements;
    }

