    public GetDataMiningElementIdsAndTitlesVm SGetDataMiningElementIdsAndTitles(GetDataMiningElementIdsAndTitlesQuery request)
    {
        var whereString = string.Empty;

        if (request.UsageType > 0)
        {
            whereString += " WHERE tbl_DataMiningElements.fld_DataMiningElementsUsageType = " + request.UsageType;
        }

        var cmd = @$" SELECT fld_DataMiningElementsId AS Id, fld_DataMiningElementsTitle AS Title
                  FROM tbl_DataMiningElements {whereString}";

        var elements = new List<GetDataMiningElementIdsAndTitlesDto>();
        var _dtDataMiningElements = dataAccess.SqlDataAdapter(cmd);

        foreach (DataRow row in _dtDataMiningElements.Rows)
        {
            elements.Add(new GetDataMiningElementIdsAndTitlesDto()
            {
                Id = Convert.ToInt32(row["Id"]),
                Title = row["Title"].ToString(),
            });
        }

        return new GetDataMiningElementIdsAndTitlesVm
        {
            Elements = elements
        };
    }

