    public List<Rule> SGetcheckingrules(string CheckingRulesId, string CheckingRulesTitle, string CheckingRulesType, string CheckingRulesStationCode)
    {
        var childrenCommands = new List<KeyValuePair<string, KeyValuePair<string, object>[]>>();

        var whereString = string.Empty;
        if (!CheckingRulesId.Equals("-1"))
        {
            whereString += (whereString == "") ? " Where " : " AND ";
            whereString += "  (tbl_DataMiningElements.fld_CheckingRulesId =  " + CheckingRulesId + ") ";
        }

        if (!CheckingRulesTitle.Equals("-1"))
        {
            whereString += (whereString == "") ? " Where " : " AND ";
            whereString += "   (tbl_DataMiningElements.fld_CheckingRulesTitle Like N'%" + CheckingRulesTitle + "%')";
        }

        if (!CheckingRulesType.Equals("-1"))
        {
            whereString += (whereString == "") ? " Where " : " AND ";
            whereString += "   (tbl_CheckingRules.fld_CheckingRulesType =  " + CheckingRulesType + ") ";
        }

        if (!CheckingRulesStationCode.Equals("-1"))
        {
            whereString += (whereString == "") ? " Where " : " AND ";
            whereString += "   (tbl_CheckingRules.fld_CheckingRulesStationCode =  " + CheckingRulesStationCode + ") ";
        }

        var cmd = @$"SELECT        fld_CheckingRulesId, fld_CheckingRulesTitle, fld_CheckingRulesCommand, fld_CheckingRulesStatus, fld_CheckingRulesType, fld_CheckingRulesStationCode, fld_CheckingRulesReturnResultTrue, 
fld_CheckingRulesReturnResultFalse, fld_CheckingRulesRegUser, fld_CheckingRulesRegDate ,fld_CheckingRulesResultType, tbl_User.[Name] as [Username]
,fld_CheckingRulesDefaultTypes as [DefaultTypes]
FROM tbl_CheckingRules 
INNER JOIN tbl_User ON tbl_CheckingRules.fld_CheckingRulesRegUser = tbl_User.Id {whereString}";

        var finalList = new List<Rule>();
        var dtcheckingrules = dataAccess.SqlDataAdapter(cmd);

        foreach (DataRow checkingrule in dtcheckingrules.Rows)
        {
            finalList.Add(new Rule()
            {
                Command = checkingrule["fld_CheckingRulesCommand"].ToString(),
                Id = checkingrule["fld_CheckingRulesId"].ToString(),
                RegDate = checkingrule["fld_CheckingRulesRegDate"].ToString(),
                RegUser = checkingrule["fld_CheckingRulesRegUser"].ToString(),
                ReturnResultFalse = checkingrule["fld_CheckingRulesReturnResultFalse"].ToString(),
                ReturnResultTrue = checkingrule["fld_CheckingRulesReturnResultTrue"].ToString(),
                StationCode = checkingrule["fld_CheckingRulesStationCode"].ToString(),
                Status = checkingrule["fld_CheckingRulesStatus"].ToString(),
                Title = checkingrule["fld_CheckingRulesTitle"].ToString(),
                Type = checkingrule["fld_CheckingRulesType"].ToString(),
                Username = checkingrule["Username"].ToString(),
                ResultType = checkingrule["fld_CheckingRulesResultType"].ToString(),
                DefaultTypes = checkingrule["DefaultTypes"].ToString()
            });
        }

        return finalList;
    }



