    public int SSavecheckingrules(Rule rule)
    {
        var commandProductTypeCodeExist = "SELECT fld_CheckingRulesId FROM  tbl_CheckingRules WHERE(fld_CheckingRulesId = " + rule.Id + ")";

        var hasValue = dataAccess.SqlDataReaders(commandProductTypeCodeExist);
        if (hasValue == null)
        {

            var command = @" INSERT INTO tbl_CheckingRules
                         (fld_CheckingRulesTitle, fld_CheckingRulesCommand, fld_CheckingRulesStatus, fld_CheckingRulesType, fld_CheckingRulesStationCode, fld_CheckingRulesReturnResultTrue, 
                         fld_CheckingRulesReturnResultFalse, fld_CheckingRulesRegUser, fld_CheckingRulesRegDate,fld_CheckingRulesResultType)
VALUES        (@fld_CheckingRulesTitle, @fld_CheckingRulesCommand, @fld_CheckingRulesStatus, @fld_CheckingRulesType, @fld_CheckingRulesStationCode, @fld_CheckingRulesReturnResultTrue, 
                         @fld_CheckingRulesReturnResultFalse, @fld_CheckingRulesRegUser, @fld_CheckingRulesRegDate,@fld_CheckingRulesResultType) ";

            return dataAccess.CmdSqlExecuteNonQuery(command
            , new KeyValuePair<string, object>("fld_CheckingRulesTitle", rule.Title)
            , new KeyValuePair<string, object>("fld_CheckingRulesCommand", rule.Command)
            , new KeyValuePair<string, object>("fld_CheckingRulesStatus", rule.Status)
            , new KeyValuePair<string, object>("fld_CheckingRulesType", rule.Type)
            , new KeyValuePair<string, object>("fld_CheckingRulesStationCode", rule.StationCode)
            , new KeyValuePair<string, object>("fld_CheckingRulesReturnResultTrue", rule.ReturnResultTrue)
            , new KeyValuePair<string, object>("fld_CheckingRulesReturnResultFalse", rule.ReturnResultFalse)
            , new KeyValuePair<string, object>("fld_CheckingRulesRegUser", rule.RegUser)
            , new KeyValuePair<string, object>("fld_CheckingRulesRegDate", rule.RegDate)
            , new KeyValuePair<string, object>("fld_CheckingRulesResultType", rule.ResultType)
            ) > 0
                ? int.Parse(GetLatestIdOfIdentityTable("tbl_CheckingRules")) : -1;
        }
        else
        {
            var commandUpdate = @"UPDATE       tbl_CheckingRules
SET             fld_CheckingRulesTitle = @fld_CheckingRulesTitle, fld_CheckingRulesCommand = @fld_CheckingRulesCommand, fld_CheckingRulesStatus = @fld_CheckingRulesStatus, 
                         fld_CheckingRulesType = @fld_CheckingRulesType, fld_CheckingRulesStationCode = @fld_CheckingRulesStationCode, fld_CheckingRulesReturnResultTrue = @fld_CheckingRulesReturnResultTrue, 
                         fld_CheckingRulesReturnResultFalse = @fld_CheckingRulesReturnResultFalse, fld_CheckingRulesRegUser = @fld_CheckingRulesRegUser, fld_CheckingRulesRegDate = @fld_CheckingRulesRegDate
,fld_CheckingRulesResultType = @fld_CheckingRulesResultType
where    fld_CheckingRulesId = @fld_CheckingRulesId";


            return dataAccess.CmdSqlExecuteNonQuery(commandUpdate
            , new KeyValuePair<string, object>("fld_CheckingRulesId", rule.Id)
            , new KeyValuePair<string, object>("fld_CheckingRulesTitle", rule.Title)
            , new KeyValuePair<string, object>("fld_CheckingRulesCommand", rule.Command)
            , new KeyValuePair<string, object>("fld_CheckingRulesStatus", rule.Status)
            , new KeyValuePair<string, object>("fld_CheckingRulesType", rule.Type)
            , new KeyValuePair<string, object>("fld_CheckingRulesStationCode", rule.StationCode)
            , new KeyValuePair<string, object>("fld_CheckingRulesReturnResultTrue", rule.ReturnResultTrue)
            , new KeyValuePair<string, object>("fld_CheckingRulesReturnResultFalse", rule.ReturnResultFalse)
            , new KeyValuePair<string, object>("fld_CheckingRulesRegUser", rule.RegUser)
            , new KeyValuePair<string, object>("fld_CheckingRulesRegDate", rule.RegDate)
            , new KeyValuePair<string, object>("fld_CheckingRulesResultType", rule.ResultType)
            ) > 0
                ? int.Parse(rule.Id) : -1;
        }

    }

