    public bool SSaveGateLogNew(string username, string actionId, string deviceId, List<string> listTagsForInsert, string gateType, DateTime? saveDateTime = null)
    {
        List<GateResult> _listGateResult = new List<GateResult>();
        List<KeyValuePair<string, KeyValuePair<string, object>[]>> commands = new();

        if (listTagsForInsert != null && listTagsForInsert.Count > 0 && actionId != "" && actionId != "0")
        {
            const int batchSize = 1000; // حداکثر تعداد رکورد در هر کوئری
            int totalTags = listTagsForInsert.Count;
            int processedTags = 0;

            while (processedTags < totalTags)
            {
                var commandTagMovementAction = @"INSERT INTO tbl_UHF_ReaderLog 
                                            (fld_TagSerial, 
                                             fld_Reader_Gate, 
                                             fld_ReaderIp, 
                                             fld_TagRead_DateTime, 
                                             fld_TagSelectedFlag,
                                             fld_InventoryId,
                                             fld_Reader_GateType,
                                             ActionStatus,
                                             fld_InventoryPackage,
                                             fld_DocumentId,
                                             fld_WMUserId,
                                             fld_ProductSerial) 
                                            VALUES ";

                int currentBatchSize = Math.Min(batchSize, totalTags - processedTags);
                int LengthMainCommand = commandTagMovementAction.Length;

                for (int i = 0; i < currentBatchSize; i++)
                {
                    string tagInfo = listTagsForInsert[processedTags++];
                    try
                    {
                        string[] tagParts = tagInfo.Split('*');
                        if (tagParts.Length == 3)
                        {
                            string TagEpc = tagParts[0];
                            string ActionStatus = tagParts[1];
                            string ProductSerial = tagParts[2];

                            commandTagMovementAction += $"('{TagEpc}','{deviceId}','','{(saveDateTime is null ? DateTimeTools.GetUnixPersianTime(DateTime.Now) : DateTimeTools.GetUnixPersianTime(saveDateTime))}','0',{actionId},'{gateType}',{ActionStatus},1,-1,'{username}','{ProductSerial}') ,";
                        }
                    }
                    catch (Exception ex)
                    {
                        logger.LogWarning(ex, ex.Message);
                    }
                }

                if (commandTagMovementAction.Length > LengthMainCommand)
                {
                    commandTagMovementAction = commandTagMovementAction.TrimEnd(','); // حذف ویرگول آخر

                    commands.Add(new(commandTagMovementAction, []));
                }
            }
        }

        return dataAccess.CmdSqlExecuteNonQueryWithTransaction(commands) > 0;
    }


    public List<GateResult> SSaveGateLogAndShowResult
       (
           string username,
               string actionId,
               string deviceId,
               List<string> listTagsForInsert,
                          List<string> listTagsForUpdateActionStatus,

            string gateType
       )
    {
        List<GateResult> _listGateResult = new List<GateResult>();
        var childrenCommands = new List<KeyValuePair<string, KeyValuePair<string, object>[]>>();
        string GateNumber = deviceId;
        string TagEpcListForSelect = "";
        if (listTagsForInsert.Count > 0)
        {
            foreach (string tag in listTagsForInsert)
            {
                if (tag != "" && tag.Contains('*'))
                {
                    string[] tagSplited = tag.Split('*');

                    var commandTagMovementAction = string.Format(@"INSERT INTO tbl_UHF_ReaderLog (
													fld_TagSerial, 
													fld_Reader_Gate, 
													fld_ReaderIp, 
													fld_TagRead_DateTime, 
													fld_TagSelectedFlag,
													fld_InventoryId,
                                                    fld_Reader_GateType,
                                                    ActionStatus,
fld_InventoryPackage,
fld_DocumentId,
fld_WMUserId
												)
												VALUES 
												(
													@tag,
													@Reader_Gate,
													N'',
													@Date,
													1,
													@InventoryId,
                                                    @GateType,
                                                    0,@fld_InventoryPackage,@fld_DocumentId,@fld_WMUserId )");
                    //tag.TagEPC+"*"+tag.TagPackageId+"*"+tag.DocumentId+"*"+tag.WMUsertId
                    TagEpcListForSelect += "N'" + tagSplited[0] + "',";
                    var parameters = new List<KeyValuePair<string, object>>();

                    parameters.Add(new("tag", tagSplited[0]));


                    parameters.Add(new("Reader_Gate", GateNumber));
                    parameters.Add(new("GateType", gateType));
                    parameters.Add(new("InventoryId", actionId));
                    parameters.Add(new("Date", DateTimeTools.GetUnixPersianTime()));
                    parameters.Add(new("fld_InventoryPackage", tagSplited[1]));
                    parameters.Add(new("fld_DocumentId", tagSplited[2]));
                    parameters.Add(new("fld_WMUserId", tagSplited[3]));
                    childrenCommands.Add(new(commandTagMovementAction, parameters.ToArray()));
                }
            }
        }

        if (listTagsForUpdateActionStatus.Count > 0)
        {
            foreach (string tag in listTagsForUpdateActionStatus)
            {
                if (tag != "" && tag.Contains('*'))
                {
                    string[] tagSplited = tag.Split('*');

                    var commandTagUpdate = string.Format(@"UPDATE        tbl_UHF_ReaderLog
                                                  SET            ActionStatus =@ActionStatus
                                             where     fld_TagSerial =@tag  AND  ActionStatus =0   AND  fld_InventoryId =@InventoryId AND fld_Reader_Gate =@GateNumber");


                    var parameters2 = new List<KeyValuePair<string, object>>();
                    parameters2.Add(new("tag", tagSplited[0]));
                    parameters2.Add(new("ActionStatus", tagSplited[1]));


                    parameters2.Add(new("GateNumber", GateNumber));
                    parameters2.Add(new("GateType", gateType));
                    parameters2.Add(new("InventoryId", actionId));

                    childrenCommands.Add(new(commandTagUpdate, parameters2.ToArray()));


                }
                else if (tag != "")
                {
                    var commandTagUpdate = string.Format(@"UPDATE        tbl_UHF_ReaderLog
                                                  SET            ActionStatus =1 
                                             where     fld_TagSerial =@tag   AND  fld_InventoryId =@InventoryId AND fld_Reader_Gate =@GateNumber");


                    var parameters2 = new List<KeyValuePair<string, object>>();

                    parameters2.Add(new("tag", tag));


                    parameters2.Add(new("GateNumber", GateNumber));
                    parameters2.Add(new("GateType", gateType));
                    parameters2.Add(new("InventoryId", actionId));

                    childrenCommands.Add(new(commandTagUpdate, parameters2.ToArray()));
                }
            }
        }

        if (childrenCommands.Count > 0)
        {
            if (dataAccess.CmdSqlExecuteNonQueryWithTransaction(childrenCommands) > 0)
            {
                if (TagEpcListForSelect.Length > 0)
                {
                    TagEpcListForSelect = TagEpcListForSelect.Substring(0, TagEpcListForSelect.Length - 1);

                    var dtGateResult = new DataTable();
                    //                    var command = @"SELECT DISTINCT 
                    //                         COALESCE (tbl_Tags_1.ProductCode, N'') AS ProductCode, COALESCE (tbl_Tags_1.ProductName, N'') AS ProductName, COALESCE (tbl_Tags_1.RegCode, N'') AS ProductTechnicalCode, '1' AS Count, 
                    //                         COALESCE (tbl_Tags_1.ProductCount, 0) AS SumValue, COALESCE (tbl_Tags_1.ProductType, N'') AS ProductType, COALESCE (tbl_Tags_1.ProductStatus, N'') AS ProductStatus, COALESCE (tbl_Tags_1.TagStatus, N'') 
                    //                         AS TagStatus, COALESCE (tbl_Tags_1.TagInDestinationId, N'0') AS TagInDestinationId, COALESCE (tbl_Tags_1.Lock, N'0') AS Lock, COALESCE (tbl_Tags_1.fld_ProductPropertyAId, N'') AS ProductLine, 
                    //                         COALESCE (tbl_Tags_1.fld_ProductPropertyBId, N'') AS ProductShift, tbl_UHF_ReaderLog_1.fld_TagSerial AS TagSerial, COALESCE (tbl_Tags_1.ProductSerial, N'') AS ProductSerial, COALESCE (tbl_Tags_1.ContractStatus, N'0') 
                    //                         AS DocumentId, COALESCE (tbl_Tags_1.Freeze, 0) AS Freeze, COALESCE (tbl_Tags_1.DeviceIp, N'') AS ProductOldSerial, COALESCE (tbl_Tags_1.fld_LastInspectResult, N'[]') AS LastInspectResult, 
                    //                         tbl_Tags_1.TagRegisterDateTime
                    //FROM            tbl_UHF_ReaderLog AS tbl_UHF_ReaderLog_1 LEFT OUTER JOIN
                    //                         tbl_Tags AS tbl_Tags_1 ON tbl_UHF_ReaderLog_1.fld_TagSerial = tbl_Tags_1.TagEpc
                    //WHERE         (tbl_UHF_ReaderLog_1.ActionStatus=0) AND  (tbl_UHF_ReaderLog_1.fld_Reader_Gate = " + GateNumber + @") AND (tbl_UHF_ReaderLog_1.fld_InventoryId = " + actionId + @") AND   
                    //                         (tbl_UHF_ReaderLog_1.fld_TagSerial IN (" + TagEpcListForSelect + ")) ";


                    var command = @"SELECT DISTINCT 
                         COALESCE (ProductCode, N'') AS ProductCode, COALESCE (ProductName, N'') AS ProductName, COALESCE (RegCode, N'') AS ProductTechnicalCode, '1' AS Count, 
                         COALESCE (ProductCount, 0) AS SumValue, COALESCE (ProductType, N'') AS ProductType, COALESCE (ProductStatus, N'') AS ProductStatus, COALESCE (TagStatus, 
                         N'') AS TagStatus, COALESCE (TagInDestinationId, N'0') AS TagInDestinationId, COALESCE (Lock, N'0') AS Lock, COALESCE (fld_ProductPropertyAId, N'') 
                         AS ProductLine, COALESCE (fld_ProductPropertyBId, N'') AS ProductShift, TagEpc AS TagSerial, COALESCE (ProductSerial, N'') AS ProductSerial, 
                         COALESCE (ContractStatus, N'0') AS DocumentId, COALESCE (Freeze, 0) AS Freeze, COALESCE (DeviceIp, N'') AS ProductOldSerial, 
                         COALESCE (fld_LastInspectResult, N'[]') AS LastInspectResult, TagRegisterDateTime
FROM            tbl_Tags AS tbl_Tags_1
where ( TagEpc  in (" + TagEpcListForSelect + ")) ";

                    dtGateResult = dataAccess.SqlDataAdapter(command);
                    int RowIndex = 1;


                    //            var CargoTruckPlacements = SGetPlacementMission(null, null, "", "", actionId, GateNumber, "", "2", "", "0", false, false);
                    //  List<CargoProduct> _CargoProductList = new List<CargoProduct>();

                    ////List<CargoProduct> _CargoProductList = JsonConvert.DeserializeObject<List<CargoProduct>>(CargoTruckPlacements.Products.ToString());
                    //if (CargoTruckPlacements != null && _CargoProductList.Count > 0 && CargoTruckPlacements.Products != null)
                    //{
                    //    foreach (CargoProduct carpro in CargoTruckPlacements.Products)
                    //    {
                    //        _CargoProductList.Add(carpro);
                    //    }
                    //}
                    foreach (DataRow dr in dtGateResult.Rows)
                    {
                        GateResult _gateResult = new GateResult();


                        _gateResult.ProductName = dr["ProductName"].ToString();
                        _gateResult.ProductCode = dr["ProductCode"].ToString();
                        _gateResult.Row = RowIndex.ToString();
                        _gateResult.Count = dr["Count"].ToString();
                        _gateResult.SumValue = dr["SumValue"].ToString();
                        _gateResult.ProductTechnicalCode = dr["ProductTechnicalCode"].ToString();
                        _gateResult.TagSerial = dr["TagSerial"].ToString();
                        _gateResult.ProductSerial = dr["ProductSerial"].ToString();
                        _gateResult.ProductType = dr["ProductType"].ToString();
                        _gateResult.ProductStatus = dr["ProductStatus"].ToString();
                        _gateResult.TagStatus = dr["TagStatus"].ToString();
                        _gateResult.TagInDestinationId = dr["TagInDestinationId"].ToString();
                        _gateResult.Lock = dr["Lock"].ToString();
                        _gateResult.ProductLine = dr["ProductLine"].ToString();
                        _gateResult.ProductShift = dr["ProductShift"].ToString();
                        _gateResult.DocumentId = dr["DocumentId"].ToString();
                        _gateResult.PMToStoreCode = "0";//(CargoTruckPlacements != null && _CargoProductList.Count > 0) ? _CargoProductList.FirstOrDefault(p => p.ProductSerial == dr["ProductSerial"].ToString()).PmToStoreCode : "";
                        _gateResult.PMToStoreTitle = "0";//(CargoTruckPlacements != null && _CargoProductList.Count > 0) ? _CargoProductList.FirstOrDefault(p => p.ProductSerial == dr["ProductSerial"].ToString()).PmToStoreTitle : "";
                        _gateResult.PMToZoneCode = "0";//(CargoTruckPlacements != null && _CargoProductList.Count > 0) ? _CargoProductList.FirstOrDefault(p => p.ProductSerial == dr["ProductSerial"].ToString()).PmToZoneCode : "";
                        _gateResult.Freeze = dr["Freeze"].ToString();
                        _gateResult.ProductOldSerial = dr["ProductOldSerial"].ToString();
                        _gateResult.LastInspectResult = dr["LastInspectResult"].ToString();
                        _gateResult.TagRegisterDateTime = (dr["TagRegisterDateTime"].ToString() != "") ? Convert.ToDateTime(dr["TagRegisterDateTime"]) : DateTime.Now;


                        RowIndex++;
                        _listGateResult.Add(_gateResult);
                    }
                }
            }
        }

        return _listGateResult;


    }






    public List<GateResult> ChangeActionIdGetEpcList
  (
      string username,
          string actionId,
          string deviceId
  )
    {
        List<GateResult> _listGateResult = new List<GateResult>();
        string GateNumber = deviceId;

        var dtGateResult = new DataTable();

        var command = @"SELECT Distinct  fld_TagSerial FROM            tbl_UHF_ReaderLog WHERE        (fld_Reader_Gate = N'" + GateNumber + @"') AND (fld_InventoryId = " + actionId + @") AND  (fld_TagSerial<>'000') ";

        dtGateResult = dataAccess.SqlDataAdapter(command);
        int RowIndex = 1;
        foreach (DataRow dr in dtGateResult.Rows)
        {
            GateResult _gateResult = new GateResult();


            _gateResult.TagSerial = dr["fld_TagSerial"].ToString();
            RowIndex++;
            _listGateResult.Add(_gateResult);

        }


        return _listGateResult;


    }


