    public DataTable SReportOnProductDate(IndexSearch search)
    {
        var whereString = SGetWhereStringSearchIndex(search);
        var whereStringForSubQuery = SGetWhereStringSearchIndexForSubQuery(search, "tbl_Tags_1");
        if (!string.IsNullOrEmpty(whereString))
            whereString = (" WHERE  (tbl_Tags.fld_ProductPropertyAId > 0) AND " + whereString);

        if (!string.IsNullOrEmpty(whereStringForSubQuery))
            whereStringForSubQuery = (" where  (tbl_Tags_1.fld_ProductPropertyAId > 0)  AND " + whereStringForSubQuery);
        var cmdData = $@" 
SELECT        SUBSTRING(TagRegisterShamsiUnixDate,0,5)+'/'+ SUBSTRING(TagRegisterShamsiUnixDate,5,2)+'/'+ SUBSTRING(TagRegisterShamsiUnixDate,7,2) as [Date],
COUNT(ProductSerial) AS CountSerial, SUM(ProductCount) AS SumValue, COUNT(DISTINCT ProductCode) AS CountProductCode, SUM(ProductCount) * 100 /
                             (SELECT        SUM(ProductCount) AS Expr1
                               FROM            tbl_Tags AS tbl_Tags_1  
{whereStringForSubQuery}   ) AS [Percent]
FROM            tbl_Tags
LEFT OUTER JOIN tbl_ProductPropertyB ON tbl_Tags.fld_ProductPropertyBId = tbl_ProductPropertyB.fld_ProductPropertyBId
LEFT OUTER JOIN tbl_ProductStatus ON tbl_Tags.ProductStatus = tbl_ProductStatus.ProductStatusCode
LEFT OUTER JOIN tbl_ProductPropertyA ON tbl_Tags.fld_ProductPropertyAId = tbl_ProductPropertyA.fld_ProductPropertyAId
{whereString}
GROUP BY SUBSTRING(TagRegisterShamsiUnixDate,0,5)+'/'+ SUBSTRING(TagRegisterShamsiUnixDate,5,2)+'/'+ SUBSTRING(TagRegisterShamsiUnixDate,7,2)
";
        var mainData = dataAccess.SqlDataAdapter(cmdData);
        if (mainData.Select().Any())
        {
            return mainData;
        }
        return dataAccess.SqlDataAdapter(
            @" SELECT N'نامشخص' as [Date], 0 AS CountSerial,0 as CountProductCode,0 AS SumValue,0 AS[Percent]");
    }



    public DataTable SReportOnBrief()
    {
        var fullDate = PersianCalendarTools.GregorianToPersianWithManualSeprator(DateTime.Now, "/");
        var dateSplited = fullDate.Split('/');
        var today = dateSplited[0] + dateSplited[1] + dateSplited[2];
        var month = dateSplited[0] + dateSplited[1];
        var year = dateSplited[0];
        var cmdData = $@" 
SELECT COALESCE((SELECT SUM(COALESCE(ProductCount,0))FROM tbl_Tags WHERE SUBSTRING(TagRegisterShamsiUnixDate,0,9) = {today}  GROUP BY SUBSTRING(TagRegisterShamsiUnixDate,0,9) ),0)  as Today,
COALESCE((SELECT SUM(COALESCE(ProductCount,0))FROM tbl_Tags  WHERE SUBSTRING(TagRegisterShamsiUnixDate,0,7) =  {month}      GROUP BY SUBSTRING(TagRegisterShamsiUnixDate,0,7) ),0)  as Monthly,
COALESCE((SELECT SUM(COALESCE(ProductCount,0))FROM tbl_Tags WHERE SUBSTRING(TagRegisterShamsiUnixDate,0,5) =  {year}       GROUP BY SUBSTRING(TagRegisterShamsiUnixDate,0,5)  ),0)  as Yearly
";
        return dataAccess.SqlDataAdapter(cmdData,
            new KeyValuePair<string, object>("Today", today)
            , new KeyValuePair<string, object>("Month", month)
            , new KeyValuePair<string, object>("Year", year)
            );
    }
    public DataTable SReportOnDetails(IndexSearch search)
    {
        var whereString = SGetWhereStringSearchIndex(search);
        if (!string.IsNullOrEmpty(whereString))
            whereString = (" WHERE " + whereString);
        var cmdData = @" 
SELECT        tbl_Tags.ProductSerial, tbl_Tags.ProductCode, tbl_Tags.ProductName, tbl_Tags.RegCode, tbl_Tags.ProductCount as [Value], tbl_ProductStatus.ProductStatusTitle as [StatusTitle], SUBSTRING(tbl_Tags.TagRegisterShamsiUnixDate,0,5)+'/'+SUBSTRING(tbl_Tags.TagRegisterShamsiUnixDate,5,2)+'/'+SUBSTRING(tbl_Tags.TagRegisterShamsiUnixDate,7,2) as [Date], tbl_ProductType.ProductTypeTitle, 
                         COALESCE(tbl_ProductPropertyA.fld_ProductPropertyATitle,N'') as LineTitle, COALESCE(tbl_ProductPropertyB.fld_ProductPropertyBTitle,N'') as [Shift],
                         tbl_Tags.Username as [Username]
FROM            tbl_Tags LEFT OUTER JOIN
                         tbl_ProductPropertyB ON tbl_Tags.fld_ProductPropertyBId = tbl_ProductPropertyB.fld_ProductPropertyBId LEFT OUTER JOIN
                         tbl_ProductPropertyA ON tbl_Tags.fld_ProductPropertyAId = tbl_ProductPropertyA.fld_ProductPropertyAId LEFT OUTER JOIN
                         tbl_ProductType ON tbl_Tags.ProductType = tbl_ProductType.ProductTypeCode LEFT OUTER JOIN
                         tbl_ProductStatus ON tbl_Tags.ProductStatus = tbl_ProductStatus.ProductStatusCode " + whereString;
        var mainData = dataAccess.SqlDataAdapter(cmdData);
        if (mainData.Select().Any())
        {
            return mainData;
        }
        return dataAccess.SqlDataAdapter(@" SELECT N'' as [ProductSerial], N'' as ProductCode, N'' as  ProductName,N'' as  RegCode,0 as [Value], N'' as [StatusTitle], N''  as [Date],N'' as  ProductTypeTitle, 
                         N'' as LineTitle, N'' as  [Shift]");
    }

    public DataTable SPGetProductInfo(string tagEpc)
    {
        var dtProductInfo = new DataTable();
        dtProductInfo.Columns.Add("TagEpc", typeof(string));//شناسه تگ  0
        dtProductInfo.Columns.Add("ProductSerial", typeof(string));// سریال محموله  1
        dtProductInfo.Columns.Add("ProductCode", typeof(string));//کد کالا  2
        dtProductInfo.Columns.Add("ProductCount", typeof(string));//مقدار محموله   3
        dtProductInfo.Columns.Add("ProductName", typeof(string));//عنوان کالا       4
        dtProductInfo.Columns.Add("ProductTypeTitle", typeof(string));//نوع کالا   5
        dtProductInfo.Columns.Add("ProductStatusTitle", typeof(string));//وضعیت کالا    6
        dtProductInfo.Columns.Add("TagStatus", typeof(string));//وضعیت تگ   7
        dtProductInfo.Columns.Add("TagRegisterShamsiUnixDate", typeof(string));//تاریخ شمسی و ساعت تولید   8
        dtProductInfo.Columns.Add("ProductProperties", typeof(string));//سایر مشخصات محموله   9
        dtProductInfo.Columns.Add("RegCode", typeof(string));// کد فنی محموله    10
        dtProductInfo.Columns.Add("fld_ProductPropertyATitle", typeof(string)); // خط تولید    11
        dtProductInfo.Columns.Add("fld_ProductPropertyBTitle", typeof(string));// شیفت تولید    12
        dtProductInfo.Columns.Add("ProductENTitle", typeof(string));//  عنوان لاتین کالا    13
        dtProductInfo.Columns.Add("ProductPackWeight", typeof(string));// وزن محموله    14
        dtProductInfo.Columns.Add("ProductPackVolume", typeof(string));// حجم محموله    15
        dtProductInfo.Columns.Add("ProductCountInPack", typeof(string));//تعداد کالا در محموله    16
        dtProductInfo.Columns.Add("ProductValue", typeof(string));// مقدار کالا    17
        dtProductInfo.Columns.Add("ProductSize", typeof(string));//سایز کالا    18
        dtProductInfo.Columns.Add("ProductUnit", typeof(string));  //  واحد کالا             19
        dtProductInfo.Columns.Add("fld_ProductPropertyAId", typeof(string));  // کد خط تولید             20
        dtProductInfo.Columns.Add("fld_ProductPropertyBId", typeof(string));  // کد شیفت تولید            21
        dtProductInfo.Columns.Add("TagZone", typeof(string));  //  محل قرارگیری            22
        dtProductInfo.Columns.Add("PlacementZoneId", typeof(string));  //  کد محل قرارگیری جدید           23
        dtProductInfo.Columns.Add("TagStatusTitle", typeof(string));  //  عنوان وضعیت تگ           24
        dtProductInfo.Columns.Add("Username", typeof(string));  //  نام کاربری ثبت کننده           25
        dtProductInfo.Columns.Add("TagInDestinationId", typeof(string));  //  انبار قرارگیری           25
        dtProductInfo.Columns.Add("FreezeStatusTitle", typeof(string));  //  انبار قرارگیری           25
        dtProductInfo.Columns.Add("InspectStatusTitle", typeof(string));  //  انبار قرارگیری           25
        var command = @"
                      SELECT        TOP (1) COALESCE (tbl_Tags.TagEpc, N'-1') AS TagEpc, COALESCE (tbl_Tags.ProductSerial, N'0') AS ProductSerial, COALESCE (tbl_Tags.ProductCode, N'0') AS ProductCode, COALESCE (tbl_Tags.ProductCount, 0) 
                         AS ProductCount, COALESCE (tbl_Tags.ProductName, N'-1') AS ProductName, COALESCE (tbl_ProductType.ProductTypeTitle, N'-1') AS ProductTypeTitle, COALESCE (tbl_ProductStatus.ProductStatusTitle, N'-1') 
                         AS ProductStatusTitle, COALESCE (tbl_Tags.TagStatus, 0) AS TagStatus, COALESCE (tbl_Tags.TagRegisterShamsiUnixDate, N'-1') AS TagRegisterShamsiUnixDate, COALESCE (tbl_Tags.ProductProperties, N'') 
                         AS ProductProperties, COALESCE (tbl_Tags.RegCode, N'0') AS RegCode, COALESCE (tbl_ProductPropertyA.fld_ProductPropertyATitle, N'-1') AS fld_ProductPropertyATitle, 
                         COALESCE (tbl_ProductPropertyB.fld_ProductPropertyBTitle, N'-1') AS fld_ProductPropertyBTitle, COALESCE (tbl_Products.ProductENTitle, N'-1') AS ProductENTitle, COALESCE (tbl_Products.ProductPackWeight, 0) 
                         AS ProductPackWeight, COALESCE (tbl_Products.ProductPackVolume, 0) AS ProductPackVolume, COALESCE (tbl_Products.ProductCountInPack, 0) AS ProductCountInPack, COALESCE (tbl_Products.ProductValue, 0) 
                         AS ProductValue, COALESCE (tbl_Products.ProductSize, N'-1') AS ProductSize, COALESCE (tbl_Products.ProductUnit, N'-1') AS ProductUnit, tbl_Tags.fld_ProductPropertyAId, tbl_Tags.fld_ProductPropertyBId, 
                         COALESCE (tbl_Tags.TagZone, N'') AS TagZone, COALESCE
                             ((SELECT        TOP (1) tbl_ProductPlacementMissions.fld_PPMToZoneId + '*' + CAST(tbl_PlacementOrders.fld_POStatus AS nvarchar(50)) AS Expr1
                                 FROM            tbl_ProductPlacementMissions LEFT OUTER JOIN
                                                          tbl_PlacementOrders ON tbl_ProductPlacementMissions.fld_PPMActionId = tbl_PlacementOrders.fld_POCode
                                 WHERE        (tbl_ProductPlacementMissions.fld_PPMProductSerial = tbl_Tags.ProductSerial) AND (tbl_ProductPlacementMissions.fld_PPMStatus = 0) AND (tbl_ProductPlacementMissions.fld_PPMType = 1)), N'0*0') 
                         AS PlacementZoneId, CASE WHEN tbl_Tags.TagStatus = 0 THEN N'انبارهای تولید' WHEN tbl_Tags.TagStatus = 1 THEN N'انبارهای محصول' WHEN tbl_Tags.TagStatus = 2 THEN N'انبارهای بارگیری' ELSE N'-' END AS TagStatusTitle, 
                         COALESCE (tbl_Tags.Username, N'') AS Username,  COALESCE (tbl_Tags.TagInDestinationId,'0') as TagInDestinationId,
                        CASE WHEN tbl_Tags.Freeze = 0 THEN N'عدم فریز' WHEN tbl_Tags.TagStatus = 1 THEN N'فریز شده' ELSE N'-' END AS FreezeStatusTitle, CASE WHEN (tbl_Tags.Lock = 0 AND fld_LastInspectResult = N'[]') 
                         THEN N'بازرسی نشده' WHEN (tbl_Tags.Lock = 0 AND fld_LastInspectResult <> N'[]') THEN N'بازرسی تأیید' WHEN (tbl_Tags.Lock = 1 AND fld_LastInspectResult <> N'[]') THEN N'بازرسی مردود' ELSE N'-' END AS InspectStatusTitle
FROM            tbl_Tags LEFT OUTER JOIN
                         tbl_Products ON tbl_Tags.ProductCode = tbl_Products.ProductCode LEFT OUTER JOIN
                         tbl_ProductType ON tbl_Tags.ProductType = tbl_ProductType.ProductTypeCode LEFT OUTER JOIN
                         tbl_ProductStatus ON tbl_Tags.ProductStatus = tbl_ProductStatus.ProductStatusCode LEFT OUTER JOIN
                         tbl_ProductPropertyA ON tbl_Tags.fld_ProductPropertyAId = tbl_ProductPropertyA.fld_ProductPropertyAId LEFT OUTER JOIN
                         tbl_ProductPropertyB ON tbl_Tags.fld_ProductPropertyBId = tbl_ProductPropertyB.fld_ProductPropertyBId
WHERE        (tbl_Tags.TagEpc = @tagEpc) OR
                         (tbl_Tags.ProductSerial = @tagEpc)";

        dtProductInfo = dataAccess.SqlDataAdapter(command, new KeyValuePair<string, object>("tagEpc", tagEpc));
        return dtProductInfo;
    }


    public bool SChangeRegisterDate(string ProductSerial, string NewDate, string NewTime)
    {
        string NewDateUnix = NewDate.Replace("/", "") + NewTime.Replace(":", "") + "01";


        var childrenCommands = new List<KeyValuePair<string, KeyValuePair<string, object>[]>>();

        var command1 = @"UPDATE       tbl_Print         SET PrintActionDateTime = dbo.JalaliDateToGeorgianDate('" + NewDate + "', '" + NewTime + "'), RegisterDate = '" + NewDateUnix + "' where ProductSerial = '" + ProductSerial + "'";

        childrenCommands.Add(new(command1, null));


        var command2 = @"UPDATE       tbl_Tags         SET TagRegisterShamsiUnixDate ='" + NewDateUnix + "', TagRegisterDateTime =dbo.JalaliDateToGeorgianDate('" + NewDate + "', '" + NewTime + "') where ProductSerial = '" + ProductSerial + "' ";

        childrenCommands.Add(new(command2, null));

        var command3 = @" UPDATE       tbl_TagsMovement         SET RTagsMovementDate ='" + NewDate + "', RTagsMovementTime ='" + NewTime + "', RTagsMovementDateTime =dbo.JalaliDateToGeorgianDate('" + NewDate + "', '" + NewTime + "')         WHERE (RMovementActionType = 1) AND(ProductSerial = '" + ProductSerial + "')";

        childrenCommands.Add(new(command3, null));

        bool resultTag = dataAccess.CmdSqlExecuteNonQueryWithTransaction(childrenCommands) == 1;

        return resultTag;
    }

    public Dictionary<string, object> SPGetProductAllDataAndHistory(string code)
    {
        var _resultDic = new Dictionary<string, object>();

        var dtProductInfo = new DataTable();
        var command = @"SELECT        TOP (1) COALESCE (tbl_Tags.TagEpc, N'-1') AS TagEpc, COALESCE (tbl_Tags.ProductSerial, N'0') AS ProductSerial, COALESCE (tbl_Tags.ProductCode, N'0') AS ProductCode, COALESCE (tbl_Tags.ProductCount, 0) 
                         AS ProductCount, COALESCE (tbl_Tags.ProductName, N'-1') AS ProductName, COALESCE (tbl_ProductType.ProductTypeTitle, N'-1') AS ProductTypeTitle, COALESCE (tbl_ProductStatus.ProductStatusTitle, N'-1') 
                         AS ProductStatusTitle, COALESCE (tbl_Tags.TagStatus, 0) AS TagStatus, COALESCE (tbl_Tags.TagRegisterShamsiUnixDate, N'-1') AS TagRegisterShamsiUnixDate, COALESCE (tbl_Tags.ProductProperties, N'') 
                         AS ProductProperties, COALESCE (tbl_Tags.RegCode, N'0') AS RegCode, COALESCE (tbl_ProductPropertyA.fld_ProductPropertyATitle, N'-1') AS fld_ProductPropertyATitle, 
                         COALESCE (tbl_ProductPropertyB.fld_ProductPropertyBTitle, N'-1') AS fld_ProductPropertyBTitle, COALESCE (tbl_Products.ProductENTitle, N'-1') AS ProductENTitle, COALESCE (tbl_Products.ProductPackWeight, 0) 
                         AS ProductPackWeight, COALESCE (tbl_Products.ProductPackVolume, 0) AS ProductPackVolume, COALESCE (tbl_Products.ProductCountInPack, 0) AS ProductCountInPack, COALESCE (tbl_Products.ProductValue, 0) 
                         AS ProductValue, COALESCE (tbl_Products.ProductSize, N'-1') AS ProductSize, COALESCE (tbl_Products.ProductUnit, N'-1') AS ProductUnit, tbl_Tags.fld_ProductPropertyAId, tbl_Tags.fld_ProductPropertyBId, 
                         COALESCE (tbl_Tags.TagZone, N'') AS TagZone, COALESCE
                             ((SELECT        TOP (1) tbl_ProductPlacementMissions.fld_PPMToZoneId + '*' + CAST(tbl_PlacementOrders.fld_POStatus AS nvarchar(50)) AS Expr1
                                 FROM            tbl_ProductPlacementMissions LEFT OUTER JOIN
                                                          tbl_PlacementOrders ON tbl_ProductPlacementMissions.fld_PPMActionId = tbl_PlacementOrders.fld_POCode
                                 WHERE        (tbl_ProductPlacementMissions.fld_PPMProductSerial = tbl_Tags.ProductSerial) AND (tbl_ProductPlacementMissions.fld_PPMStatus = 0) AND (tbl_ProductPlacementMissions.fld_PPMType = 1)), N'0*0') 
                         AS PlacementZoneId, CASE WHEN tbl_Tags.TagStatus = 0 THEN N'انبارهای تولید' WHEN tbl_Tags.TagStatus = 1 THEN N'انبارهای محصول' WHEN tbl_Tags.TagStatus = 2 THEN N'انبارهای بارگیری' ELSE N'-' END AS TagStatusTitle, 
                         COALESCE (tbl_Tags.Username,N'') as Username
FROM            tbl_Tags LEFT OUTER JOIN
                         tbl_Products ON tbl_Tags.ProductCode = tbl_Products.ProductCode LEFT OUTER JOIN
                         tbl_ProductType ON tbl_Tags.ProductType = tbl_ProductType.ProductTypeCode LEFT OUTER JOIN
                         tbl_ProductStatus ON tbl_Tags.ProductStatus = tbl_ProductStatus.ProductStatusCode LEFT OUTER JOIN
                         tbl_ProductPropertyA ON tbl_Tags.fld_ProductPropertyAId = tbl_ProductPropertyA.fld_ProductPropertyAId LEFT OUTER JOIN
                         tbl_ProductPropertyB ON tbl_Tags.fld_ProductPropertyBId = tbl_ProductPropertyB.fld_ProductPropertyBId
WHERE        (tbl_Tags.TagEpc = @Code) OR
                         (tbl_Tags.ProductSerial = @Code)";


        dtProductInfo = dataAccess.SqlDataAdapter(command, new KeyValuePair<string, object>("Code", code));

        _resultDic.Add("ProductInfo", JsonConvert.SerializeObject(dtProductInfo));


        var cmd = $@" SELECT        TOP (10) RMovementActionId, RTagsMovementDate, RTagsMovementTime, COALESCE (MovementData, N' ') AS MovementData, ProductSerial,N'ورود به انبار' as ActionType
FROM            tbl_TagsMovement
WHERE     (   (ProductSerial = N'{code}') OR
                          (TagEpc = N'{code}') ) and RMovementActionId>0 and RTagsMovementSt=1
						 union
						SELECT        TOP (10) tbl_TagsMovement.HMovementActionId as  RMovementActionId, tbl_TagsMovement.HTagsMovementDate as RTagsMovementDate, tbl_TagsMovement.HTagsMovementTime as RTagsMovementTime, COALESCE (tbl_TagsMovement.MovementData, N' ') AS MovementData, 
                         tbl_TagsMovement.ProductSerial,N'برگشت از انبار' as ActionType
FROM            tbl_TagsMovement LEFT OUTER JOIN
                         tbl_MovementActions ON tbl_TagsMovement.HMovementActionId = tbl_MovementActions.MovementActionId
WHERE       ( (tbl_TagsMovement.ProductSerial = N'{code}') OR
                         (tbl_TagsMovement.TagEpc = N'{code}') ) and   HMovementActionId>0 and HTagsMovementSt=1 and (tbl_MovementActions.MovementActionTp = 6) AND (tbl_MovementActions.MovementActionData LIKE N'%برگشت کالا%')  ";

        var _dtMovementActionTp1 = dataAccess.SqlDataAdapter(cmd);

        _resultDic.Add("ProductStoreTransactions", JsonConvert.SerializeObject(_dtMovementActionTp1));



        var cmd3 = $@"SELECT        TOP (1) tbl_MovementActions.MovementActionId, tbl_MovementActions.MovementActionDate + N' - ' + tbl_MovementActions.MovementActionTime AS DateTime, COALESCE (tbl_MovementActions.MovementActionCarPlaque, N'') 
                         AS Plaque, COALESCE (tbl_MovementActions.MovementActionDriverName, N'') AS Driver, tbl_MovementActions.MovementActionUHFLogId, tbl_MovementActions.MovementActionData, 
                         tbl_MovementActions.MovementActionDriverMobile, COALESCE (tbl_User.Username, N'') AS Username
                         FROM            tbl_MovementActions LEFT OUTER JOIN
                                                 tbl_User ON tbl_MovementActions.MovementActionUserId = tbl_User.Id LEFT OUTER JOIN
                                                 tbl_TagsMovement ON tbl_MovementActions.MovementActionId = tbl_TagsMovement.HMovementActionId
                         WHERE           (MovementActionTp = 6) AND (MovementActionData NOT LIKE N'%برگشت کالا%')  and (tbl_TagsMovement.ProductSerial = N'{code}' )";


        var _dtExit = dataAccess.SqlDataAdapter(cmd3);
        _resultDic.Add("ProductExitInfo", JsonConvert.SerializeObject(_dtExit));



        var cmd4 = $@"SELECT        tbl_ProductPlacementMissions.fld_PPMProductSerial, tbl_ProductPlacementMissions.fld_PPMFromZoneId, tbl_ProductPlacementMissions.fld_PPMToZoneId, tbl_ProductPlacementMissions.fld_PPMDateTime, 
                         tbl_User.Username
FROM            tbl_ProductPlacementMissions LEFT OUTER JOIN
                         tbl_User ON tbl_ProductPlacementMissions.fld_PPMWMDriverUserId = tbl_User.Id
WHERE        (tbl_ProductPlacementMissions.fld_PPMStatus = 2) AND (tbl_ProductPlacementMissions.fld_PPMProductSerial  = N'{code}' )";


        var _dtPlacement = dataAccess.SqlDataAdapter(cmd4);
        _resultDic.Add("ProductPlacementInfo", JsonConvert.SerializeObject(_dtPlacement));


        var cmd5 = $@"SELECT DISTINCT tbl_InventoryTags.fld_InventoryProductSerial, tbl_InventoryTags.fld_InventoryDate, tbl_InventoryTags.fld_InventoryProductDesc
FROM            tbl_InventoryTags RIGHT OUTER JOIN
                         tbl_Tags ON tbl_InventoryTags.fld_InventoryTagEPC = tbl_Tags.TagEpc
WHERE        (tbl_Tags.ProductSerial =   N'{code}' )";


        var _dtinventory = dataAccess.SqlDataAdapter(cmd5);
        _resultDic.Add("ProductInventoryInfo", JsonConvert.SerializeObject(_dtinventory));


        var cmd6 = $@"SELECT DISTINCT 
                         SUBSTRING(tbl_UHF_ReaderLog.fld_TagRead_DateTime, 0, 5) + '/' + SUBSTRING(tbl_UHF_ReaderLog.fld_TagRead_DateTime, 5, 2) + '/' + SUBSTRING(tbl_UHF_ReaderLog.fld_TagRead_DateTime, 7, 2) AS LogDate, 
                         tbl_UHF_ReaderLog.fld_InventoryId AS LogId, CASE WHEN tbl_UHF_ReaderLog.fld_Reader_GateType = 3 THEN N'حراست' WHEN tbl_UHF_ReaderLog.fld_Reader_GateType = 1 THEN N'ورود' END AS LogType
FROM            tbl_UHF_ReaderLog RIGHT OUTER JOIN
                         tbl_Tags ON tbl_UHF_ReaderLog.fld_TagSerial = tbl_Tags.TagEpc
WHERE        (tbl_Tags.ProductSerial = N'{code}')";


        var _dtUHFReaderLog = dataAccess.SqlDataAdapter(cmd6);
        _resultDic.Add("ProductReadByGateLog", JsonConvert.SerializeObject(_dtUHFReaderLog));



        return _resultDic;
    }
    public DataTable SGetProductHistoryLight(List<string> codes)
    {
        var epcString = codes.Aggregate(string.Empty, (first, next) =>
        {
            return first + (string.IsNullOrEmpty(next) ? string.Empty : (",N'" + next + "'"));
        }).Remove(0, 1);

        var _resultDic = new Dictionary<string, object>();
        var dtProductInfo = new DataTable();
        var command = $@"SELECT  Distinct      COALESCE (tbl_Tags.TagEpc, N'') AS TagEpc, COALESCE (tbl_Tags.ProductSerial, N'') AS ProductSerial, COALESCE (tbl_Tags.ProductCode, N'') AS ProductCode, COALESCE (tbl_Tags.ProductCount, 0) AS ProductCount, 
                         COALESCE (tbl_Tags.ProductName, N'') AS ProductName, COALESCE (tbl_Tags.TagStatus, N'') AS TagStatus, COALESCE (tbl_Tags.TagRegisterShamsiUnixDate, N'') AS TagRegisterShamsiUnixDate, 
                         COALESCE (tbl_Tags.ProductProperties, N'') AS ProductProperties, dbo.GetProductAnalyseAge(tbl_Tags.TagRegisterShamsiUnixDate) AS ProductAgeAnalysis, COALESCE (tbl_Tags.RegCode, N'') AS RegCode, 
                         COALESCE (tbl_Products.ProductPackWeight, 0) AS ProductPackWeight, COALESCE (tbl_Products.ProductPackVolume, 0) AS ProductPackVolume, COALESCE (tbl_Products.ProductCountInPack, 0) AS ProductCountInPack, 
                         COALESCE (tbl_Products.ProductValue, 0) AS ProductValue, COALESCE (tbl_Products.ProductSize, N'') AS ProductSize, COALESCE (tbl_Products.ProductUnit, N'') AS ProductUnit, tbl_Tags.fld_ProductPropertyAId, 
                         tbl_Tags.fld_ProductPropertyBId, COALESCE (tbl_Tags.TagZone, N'') AS TagZone, 
                         CASE WHEN tbl_Tags.TagStatus = 0 THEN N'انبارهای تولید' WHEN tbl_Tags.TagStatus = 1 THEN N'انبارهای محصول' WHEN tbl_Tags.TagStatus = 2 THEN N'انبارهای بارگیری' ELSE N'-' END AS TagStatusTitle, COALESCE (tbl_Tags.Username,
                          N'') AS Username, COALESCE (tbl_Products.ProductGalleryId, 0) AS ProductGalleryId,COALESCE(DeviceIp,'') as OldProductSerial,COALESCE(ContractStatus,'') as DocumentCode
FROM            tbl_Tags INNER JOIN
                         tbl_Products ON tbl_Tags.ProductCode = tbl_Products.ProductCode
WHERE        (tbl_Tags.TagEpc IN ({epcString}))";
        dtProductInfo = dataAccess.SqlDataAdapter(command);

        return dtProductInfo;
    }
    public Dictionary<string, object> SGetProductHistory(string code)
    {
        Dictionary<string, object> resultDic = new();

        DataTable dtProductInfo = new();
        string command = $@" SELECT        TOP (1) COALESCE (tbl_Tags.TagEpc, N'') AS TagEpc, COALESCE (tbl_Tags.ProductSerial, N'') AS ProductSerial, COALESCE (tbl_Tags.ProductCode, N'') AS ProductCode, COALESCE (tbl_Tags.ProductCount, 0) AS ProductCount, 
                         COALESCE (tbl_Tags.ProductName, N'') AS ProductName, COALESCE (tbl_ProductType.ProductTypeTitle, N'-1') AS ProductTypeTitle, COALESCE (tbl_ProductStatus.ProductStatusTitle, N'') AS ProductStatusTitle, 
                         COALESCE (tbl_Tags.TagStatus, N'') AS TagStatus, COALESCE (tbl_Tags.TagRegisterShamsiUnixDate, N'') AS TagRegisterShamsiUnixDate, COALESCE (tbl_Tags.ProductProperties, N'') AS ProductProperties, 
                         dbo.GetProductAnalyseAge(tbl_Tags.TagRegisterShamsiUnixDate) AS ProductAgeAnalysis, COALESCE (tbl_Tags.RegCode, N'') AS RegCode, COALESCE (tbl_ProductPropertyA.fld_ProductPropertyATitle, N'') 
                         AS fld_ProductPropertyATitle, COALESCE (tbl_ProductPropertyB.fld_ProductPropertyBTitle, N'') AS fld_ProductPropertyBTitle, COALESCE (tbl_Products.ProductENTitle, N'') AS ProductENTitle, (CASE WHEN tbl_Tags.Freeze = 1 THEN N'فریز' ELSE N'عدم فریز' END) AS FreezeStatus, 
                         COALESCE (tbl_Products.ProductPackWeight, 0) AS ProductPackWeight, COALESCE (tbl_Products.ProductPackVolume, 0) AS ProductPackVolume, COALESCE (tbl_Products.ProductCountInPack, 0) AS ProductCountInPack, 
                         COALESCE (tbl_Products.ProductValue, 0) AS ProductValue, COALESCE (tbl_Products.ProductSize, N'') AS ProductSize, COALESCE (tbl_Products.ProductUnit, N'') AS ProductUnit, tbl_Tags.fld_ProductPropertyAId, 
                         tbl_Tags.fld_ProductPropertyBId, COALESCE (tbl_Zones.ZoneTitle, N'') AS TagZone, COALESCE (tbl_Destination.DestinationTitle, N'') AS Warehouse, COALESCE
                             ((SELECT        TOP (1) tbl_ProductPlacementMissions.fld_PPMToZoneId + '*' + CAST(tbl_PlacementOrders.fld_POStatus AS nvarchar(50)) AS Expr1
                                 FROM            tbl_ProductPlacementMissions LEFT OUTER JOIN
                                                          tbl_PlacementOrders ON tbl_ProductPlacementMissions.fld_PPMActionId = tbl_PlacementOrders.fld_POCode
                                 WHERE        (tbl_ProductPlacementMissions.fld_PPMProductSerial = tbl_Tags.ProductSerial) AND (tbl_ProductPlacementMissions.fld_PPMStatus = 0) AND (tbl_ProductPlacementMissions.fld_PPMType = 1)), N'0*0') 
                         AS PlacementZoneId, 
                         CASE WHEN tbl_Tags.TagStatus = 0 THEN N'انبارهای تولید' WHEN tbl_Tags.TagStatus = 1 THEN N'انبارهای محصول' WHEN tbl_Tags.TagStatus = 2 THEN N'انبارهای بارگیری' WHEN tbl_Tags.TagStatus = 3 THEN N'خروج از کارخانه' ELSE
                          N'-' END AS TagStatusTitle, COALESCE (tbl_Tags.Username, N'') AS Username, CAST(DATEDIFF(day, tbl_Tags.TagRegisterDateTime, GETDATE()) AS NVARCHAR(10)) + N' روز' AS ProductAge, 
                         COALESCE (tbl_Products.ProductGalleryId, 0) AS ProductGalleryId, COALESCE (tbl_Tags.DeviceIp, N'') AS OldProductSerial, COALESCE (CAST(tbl_Tags.ContractStatus AS nvarchar(100)), N'') AS DocumentCode, 
                         COALESCE (tbl_Products.ProductTechnicalData, N'') AS ProductTechnicalData,
(SELECT CASE WHEN COUNT(value) = 0 THEN N'مشخص نشده' WHEN STRING_AGG(JSON_VALUE(value,'$.InspectElementValue'),N'|') LIKE N'%False%' THEN N'مردود' ELSE N'پذیرفته' END FROM tbl_Tags AS [INNERTAGS] CROSS APPLY OPENJSON([INNERTAGS].fld_LastInspectResult, '$') WHERE [INNERTAGS].ProductSerial = tbl_Tags.ProductSerial) as LastInspectResult,
						 COALESCE(tbl_ProductBrand.fld_ProductBrandTitle, N'') AS [ProductBrand],
						 COALESCE(tbl_ProductGroup.fld_ProductGroupTitle, N'') AS ProductGroup,
CASE tbl_Tags.DeviceId WHEN N'0' THEN N'کیوسک رجیستر' WHEN N'' THEN N'هند هلد' ELSE N'مشخص نشده' END AS [RegisterDevice]
FROM            tbl_Tags LEFT OUTER JOIN
                         tbl_Zones ON tbl_Tags.TagInDestinationId = tbl_Zones.ZoneStoreCode AND tbl_Zones.ZoneCode = tbl_Tags.TagZone LEFT OUTER JOIN
                         tbl_Products ON tbl_Tags.ProductCode = tbl_Products.ProductCode LEFT OUTER JOIN
                         tbl_ProductType ON tbl_Tags.ProductType = tbl_ProductType.ProductTypeCode LEFT OUTER JOIN
                         tbl_ProductStatus ON tbl_Tags.ProductStatus = tbl_ProductStatus.ProductStatusCode LEFT OUTER JOIN
                         tbl_ProductPropertyA ON tbl_Tags.fld_ProductPropertyAId = tbl_ProductPropertyA.fld_ProductPropertyAId LEFT OUTER JOIN
                         tbl_ProductPropertyB ON tbl_Tags.fld_ProductPropertyBId = tbl_ProductPropertyB.fld_ProductPropertyBId LEFT OUTER JOIN
                         tbl_Destination ON tbl_Destination.DestinationCode = tbl_Tags.TagInDestinationId LEFT OUTER JOIN
						 tbl_ProductBrand ON tbl_ProductBrand.fld_ProductBrandCode = tbl_Tags.fld_ProductBrand LEFT OUTER JOIN
						 tbl_ProductGroup ON tbl_ProductGroup.fld_ProductGroupCode = tbl_Tags.fld_ProductGroup
WHERE        (tbl_Tags.TagEpc = N'{code}') OR
                         (tbl_Tags.ProductSerial = N'{code}') OR (tbl_Tags.DeviceIp = N'{code}')";
        dtProductInfo = dataAccess.SqlDataAdapter(command);
        resultDic.Add("ProductInfo", DataTableTools.DataTableToObjects(dtProductInfo));

        var cmd = $@"SELECT        TOP (10) RMovementActionId, COALESCE(tbl_Destination.DestinationTitle,N'') AS WarehouseTitle,
					   RTagsMovementDate, RTagsMovementTime,COALESCE(tbl_MovementActions.MovementActionUHFLogId,N'') as MovementActionUHFLogId,
					   CASE WHEN ISJSON(tbl_MovementActions.MovementActionData) = 1 THEN Json_Value(tbl_MovementActions.MovementActionData,'$.MovementActionDesc') ELSE N'' END as Description
                    FROM            tbl_TagsMovement LEFT OUTER JOIN
                                                tbl_MovementActions ON tbl_TagsMovement.RMovementActionId = tbl_MovementActions.MovementActionId LEFT OUTER JOIN
						                        tbl_Destination ON tbl_MovementActions.MovementActionStore = tbl_Destination.DestinationCode
                    WHERE     (   (ProductSerial = N'{code}') OR (TagEpc = N'{code}') )
				                    and RMovementActionId>0 
				                    and RTagsMovementSt=1
                    union
                    SELECT        TOP (10) tbl_TagsMovement.HMovementActionId as  RMovementActionId,
					                        COALESCE(tbl_Destination.DestinationTitle,N'') as WarehouseTitle,
					                        tbl_TagsMovement.HTagsMovementDate as RTagsMovementDate,
					                        tbl_TagsMovement.HTagsMovementTime as RTagsMovementTime,
					                        COALESCE(tbl_MovementActions.MovementActionUHFLogId,N'') as MovementActionUHFLogId,
					                        CASE WHEN ISJSON(tbl_MovementActions.MovementActionData) = 1 THEN Json_Value(tbl_MovementActions.MovementActionData,'$.MovementActionDesc') ELSE N'' END as Description
                    FROM            tbl_TagsMovement LEFT OUTER JOIN
                                                tbl_MovementActions ON tbl_TagsMovement.HMovementActionId = tbl_MovementActions.MovementActionId LEFT OUTER JOIN
						                        tbl_Destination ON tbl_MovementActions.MovementActionStore = tbl_Destination.DestinationCode

                    WHERE       ( (tbl_TagsMovement.ProductSerial = N'{code}') OR (tbl_TagsMovement.TagEpc = N'{code}') )
			                    and   HMovementActionId>0 and HTagsMovementSt=1 
			                    and (tbl_MovementActions.MovementActionTp = 6) 
			                    AND (tbl_MovementActions.MovementActionData LIKE N'%برگشت کالا%')  ";

        var _dtMovementActionTp1 = dataAccess.SqlDataAdapter(cmd);
        resultDic.Add("ProductStoreTransactions", DataTableTools.DataTableToObjects(_dtMovementActionTp1));

        var cmd3 = $@"SELECT        TOP (1) tbl_MovementActions.MovementActionId, 
tbl_MovementActions.MovementActionDate + N' - ' + tbl_MovementActions.MovementActionTime AS DateTime, 
tbl_MovementActions.MovementActionDate  AS [Date],
tbl_MovementActions.MovementActionTime AS [Time],
COALESCE (tbl_MovementActions.MovementActionCarPlaque, N'') AS Plaque,
COALESCE (tbl_MovementActions.MovementActionDriverName, N'') AS Driver, 
COALESCE (tbl_MovementActions.MovementActionUHFLogId,0) as GateOpCode, tbl_MovementActions.MovementActionData, 
tbl_MovementActions.MovementActionDriverMobile as Mobile, COALESCE (tbl_User.Username, N'') AS Username,N''as [AgeAnalsys],
(SELECT tbl_Tags.TagRegisterShamsiUnixDate FROM tbl_Tags WHERE tbl_Tags.ProductSerial = N'{code}') as [ProductDate]
FROM            tbl_MovementActions LEFT OUTER JOIN
                        tbl_User ON tbl_MovementActions.MovementActionUserId = tbl_User.Id LEFT OUTER JOIN
                        tbl_TagsMovement ON tbl_MovementActions.MovementActionId = tbl_TagsMovement.HMovementActionId
WHERE           (MovementActionTp = 6) AND (MovementActionData NOT LIKE N'%برگشت کالا%')  and (tbl_TagsMovement.ProductSerial = N'{code}' )";
        //(SELECT COALESCE (dbo.GetExitProductAnalyseAge(dbo.tbl_Tags.TagRegisterShamsiUnixDate, dbo.tbl_TagsMovement.HTagsMovementDate), N'نامشخص')  FROM tbl_tags WHERE tbl_tags.ProductSerial = tbl_TagsMovement.ProductSerial)
        var _dtExit = dataAccess.SqlDataAdapter(cmd3);

        for (int i = 0; i < _dtExit.Rows.Count; i++)
        {
            DataRow row = _dtExit.Rows[i];

            string exitAgeAnalysis =
                GetExitAgeAnalysis(row["ProductDate"].ToString(), row["Date"].ToString());

            _dtExit.Rows[i]["AgeAnalsys"] = exitAgeAnalysis;
        }

        resultDic.Add("ProductExitInfo", DataTableTools.DataTableToObjects(_dtExit));

        var cmd4 = $@"SELECT  COALESCE(tbl_Destination.DestinationTitle,N'') as [WarehouseTitle],
		COALESCE(tbl_Zones.ZoneTitle,N'') as [Location],
        COALESCE(dbo.GeorgianDateToJalaliDate(tbl_ProductPlacementMissions.fld_PPMDateTime),N'') as [Date], 
		COALESCE(CAST(CAST(fld_PPMDateTime as Time) as nvarchar(5)),N'') as [Time], 
        COALESCE(tbl_User.Username,N'') as Username
        FROM            tbl_ProductPlacementMissions LEFT OUTER JOIN
                                 tbl_User ON tbl_ProductPlacementMissions.fld_PPMWMDriverUserId = tbl_User.Id LEFT OUTER JOIN
						         tbl_Destination ON tbl_ProductPlacementMissions.fld_PPMStoreCode = tbl_Destination.DestinationCode LEFT OUTER JOIN
						         tbl_Zones ON tbl_ProductPlacementMissions.fld_PPMToZoneId = tbl_Zones.ZoneCode
        WHERE    (tbl_ProductPlacementMissions.fld_PPMStatus = 2) AND (tbl_ProductPlacementMissions.fld_PPMProductSerial  = N'{code}' )";

        var _dtPlacement = dataAccess.SqlDataAdapter(cmd4);
        resultDic.Add("ProductPlacementInfo", DataTableTools.DataTableToObjects(_dtPlacement));

        var cmd5 = $@"SELECT DISTINCT COALESCE(tbl_InventoryTags.fld_InventoryId,0) as [OperationCode],
				COALESCE(tbl_Destination.DestinationTitle,N'') as [WarehouseTitle],
				COALESCE(tbl_InventoryTags.fld_InventoryDate,N'') as [Date],
				CASE WHEN tbl_Tags.TagStatus = 0 THEN N'انبارهای تولید'
					 WHEN tbl_Tags.TagStatus = 1 THEN N'انبارهای محصول' 
					 WHEN tbl_Tags.TagStatus = 2 THEN N'انبارهای بارگیری' 
					 ELSE N'-' END AS [Status],
				COALESCE(tbl_InventoryTags.fld_InventoryProductDesc,N'') as [Description]
                FROM            tbl_InventoryTags INNER JOIN
                                         tbl_Tags ON tbl_InventoryTags.fld_InventoryTagEPC = tbl_Tags.TagEpc LEFT OUTER JOIN
						                 tbl_Destination ON tbl_InventoryTags.fld_InventoryStoreCode =  tbl_Destination.DestinationCode
                WHERE        (tbl_Tags.ProductSerial =   N'{code}')
                ";

        var _dtinventory = dataAccess.SqlDataAdapter(cmd5);
        resultDic.Add("ProductInventoryInfo", DataTableTools.DataTableToObjects(_dtinventory));

        var cmd6 = $@"SELECT DISTINCT COALESCE(tbl_UHF_ReaderLog.fld_Reader_Gate,N'') AS [GateCode],
                COALESCE(tbl_UHF_ReaderLog.fld_InventoryId,0) AS LogId,
                COALESCE(SUBSTRING(tbl_UHF_ReaderLog.fld_TagRead_DateTime, 0, 5) + '/' + SUBSTRING(tbl_UHF_ReaderLog.fld_TagRead_DateTime, 5, 2) + '/' + SUBSTRING(tbl_UHF_ReaderLog.fld_TagRead_DateTime, 7, 2),N'') AS LogDate, 
                COALESCE(SUBSTRING(tbl_UHF_ReaderLog.fld_TagRead_DateTime, 9, 2) + ':' + SUBSTRING(tbl_UHF_ReaderLog.fld_TagRead_DateTime, 11, 2) + ':' + SUBSTRING(tbl_UHF_ReaderLog.fld_TagRead_DateTime, 13, 2),N'') AS LogTime
                FROM            tbl_UHF_ReaderLog RIGHT OUTER JOIN
                                         tbl_Tags ON tbl_UHF_ReaderLog.fld_TagSerial = tbl_Tags.TagEpc
                WHERE        (tbl_Tags.ProductSerial = N'{code}')";


        var _dtUHFReaderLog = dataAccess.SqlDataAdapter(cmd6);
        resultDic.Add("ProductReadByGateLog", DataTableTools.DataTableToObjects(_dtUHFReaderLog));

        resultDic.Add("InspectResults", SReportInspects(new()
        {
            ProductCode = "-1",
            ElementFilters = new(),
            FromDate = "-1",
            ToDate = "-1",
            ProductSerial = code,
            InspectResult = -1,
            Line = "-1",
            RegCode = "-1",
            UserId = "-1",
            DynamicFilters = new()
        }));

        resultDic.Add("FreezeHeaders", SGetFreezeHeadersBySerial(code));

        return resultDic;
    }

    public DataTable SGetTagHistoryTimeLine(string serial)
    {
        string command =
            $"""
        

        			 WITH TagEpcCTE AS (
            SELECT TOP (1) TagEpc FROM tbl_Tags WHERE ProductSerial = N'{serial}'
        )
        SELECT TagEventType, TagEventDescription, TagEventDateTime,TagEventUserId,
               COALESCE(TagEventDateTimeShamsi, N'') as TagEventDateTimeShamsi
        FROM (

            SELECT 1 AS TagEventType, 
                   CAST(N'تولید توسط کاربر : ' + COALESCE((SELECT Name FROM tbl_User WHERE Username = tbl_Tags.Username), N'') AS nvarchar) AS TagEventDescription, 
                   tbl_Tags.TagRegisterDateTime AS TagEventDateTime, 
                   N'' AS TagEventDateTimeShamsi,
        		   tbl_Tags.TagRegisterUser AS TagEventUserId
            FROM tbl_Tags
            WHERE tbl_Tags.TagRegisterDateTime IS NOT NULL 
              AND tbl_Tags.ProductSerial = N'{serial}'

        UNION


            SELECT DISTINCT 2 AS TagEventType, 
                   CAST((CASE WHEN tbl_Inspect.fld_InspectResult = 0 THEN N'بازرسی مردود' 
                              WHEN tbl_Inspect.fld_InspectResult = 1 THEN N'بازرسی تایید' END) 
                        + N' - توسط : ' + COALESCE((SELECT Name FROM tbl_User WHERE Id = tbl_Inspect.fld_InspectUser), N'') AS nvarchar) AS TagEventDescription, 
                   CAST(tbl_Inspect.fld_InspectDateTime AS DATETIME) AS TagEventDateTime, 
                   N'' AS TagEventDateTimeShamsi,
        		   tbl_Inspect.fld_InspectUser AS TagEventUserId
            FROM tbl_Inspect
            WHERE tbl_Inspect.fld_InspectDateTime IS NOT NULL 
              AND tbl_Inspect.fld_InspectSerial = N'{serial}'

        UNION


            SELECT DISTINCT 3 AS TagEventType, 
                   CASE WHEN tbl_FreezeHeader.fld_FreezeResult = 0 THEN CAST(N'عدم فریز' AS nvarchar) 
                        WHEN tbl_FreezeHeader.fld_FreezeResult = 1 THEN CAST(N'فریز' AS nvarchar) END 
                   + N' - توسط : ' + COALESCE((SELECT Name FROM tbl_User WHERE Id = tbl_FreezeHeader.fld_FreezeUserId), N'') AS TagEventDescription, 
                   CAST(tbl_FreezeHeader.fld_FreezeSaveDateTime AS DATETIME) AS TagEventDateTime, 
                   N'' AS TagEventDateTimeShamsi,
        		   tbl_FreezeHeader.fld_FreezeUserId AS TagEventUserId
            FROM tbl_FreezeItem
            INNER JOIN tbl_FreezeHeader ON tbl_FreezeHeader.fld_FreezeHeaderId = tbl_FreezeItem.fld_FreezeHeaderId
            WHERE tbl_FreezeHeader.fld_FreezeSaveDateTime IS NOT NULL 
              AND tbl_FreezeItem.fld_FreezeProductSerial = N'{serial}'

        UNION


            SELECT 4 AS TagEventType,
               CAST(N'جابجایی - ' + COALESCE(tbl_ActionTypes.fld_ActionTypeTitle, N'نامشخص') AS nvarchar) AS TagEventDescription,
               tbl_TagsMovement.RTagsMovementDateTime AS TagEventDateTime,
               tbl_TagsMovement.RTagsMovementDate AS TagEventDateTimeShamsi,
               tbl_MovementActions.MovementActionUserId  AS TagEventUserId
             FROM tbl_TagsMovement 
             INNER JOIN tbl_MovementActions  
             ON tbl_MovementActions.MovementActionId = tbl_TagsMovement.RMovementActionId
             LEFT JOIN tbl_ActionTypes 
             ON tbl_ActionTypes.fld_ActionTypeId = tbl_MovementActions.MovementActionTp
             WHERE tbl_TagsMovement.ProductSerial = N'{serial}'
             AND tbl_ActionTypes.fld_ActionTypeId <> 6

        UNION


            SELECT 5 AS TagEventType, 
                   CAST(N'انبارگردانی ' AS NVARCHAR) AS TagEventDescription, 
                   CAST(tbl_InventoryTags.fld_InventoryDateTime AS DATETIME) AS TagEventDateTime, 
                   N'' AS TagEventDateTimeShamsi,
        		   tbl_InventoryTags.fld_InventoryUser AS TagEventUserId
            FROM tbl_InventoryTags
            INNER JOIN tbl_Tags ON tbl_InventoryTags.fld_InventoryTagEPC = tbl_Tags.TagEpc
            WHERE tbl_InventoryTags.fld_InventoryDateTime IS NOT NULL 
              AND tbl_Tags.ProductSerial = N'{serial}'

        UNION


            SELECT 6 as TagEventType, 
                   CAST(N'جانمایی در لوکیشن : ' + fld_PPMToZoneId AS nvarchar) as TagEventDescription,
                   tbl_ProductPlacementMissions.fld_PPMRegDateTime as TagEventDateTime,
                   N'' AS TagEventDateTimeShamsi,
             tbl_ProductPlacementMissions.fld_PPMUserId AS TagEventUserId
            FROM tbl_ProductPlacementMissions
            WHERE tbl_ProductPlacementMissions.fld_PPMRegDateTime IS NOT NULL 
              AND tbl_ProductPlacementMissions.fld_PPMStatus = N'2' 
              AND tbl_ProductPlacementMissions.fld_PPMProductSerial = N'{serial}'


        


        UNION

            SELECT 8 as TagEventType, 
                   CAST(N'ابطال توسط کاربر :' + COALESCE((SELECT [Name] FROM tbl_User WHERE Username = SoftDeleteUser), N'') AS nvarchar) as TagEventDescription,
                   CAST(0 AS DATETIME) as TagEventDateTime,
                   SoftDeleteDate AS TagEventDateTimeShamsi,
        		  tbl_Print.RegisterUser AS TagEventUserId
            FROM tbl_Print
            WHERE SoftDeleteDate IS NOT NULL 
              AND SoftDelete = N'1' 
              AND ProductSerial = N'{serial}'

        UNION

            SELECT DISTINCT 9 AS TagEventType,
                   CAST(N'آلارم ایستگاه شناسایی : ' + CAST(fld_AlarmLogGateNumber as nvarchar(50)) + '- ' + fld_AlarmLogType AS nvarchar) AS TagEventDescription,
                   CAST(fld_AlarmLogDateTime AS DATETIME) AS TagEventDateTime, 
                   dbo.GeorgianDateToJalaliDate(fld_AlarmLogDateTime) AS TagEventDateTimeShamsi,
        		   tbl_AlarmLog.fld_AlarmLogUserId AS TagEventUserId
            FROM tbl_AlarmLog
            WHERE fld_AlarmLogSerial = N'{serial}'

        UNION

            SELECT 10 AS TagEventType, 
                   CAST(N'فروش' AS nvarchar) AS TagEventDescription, 
                   tbl_TagsMovement.RTagsMovementDateTime AS TagEventDateTime, 
                   N'' AS TagEventDateTimeShamsi,
        		   NULL AS TagEventUserId
            FROM tbl_TagsMovement
            WHERE tbl_TagsMovement.RMovementActionType = 6 
              AND tbl_TagsMovement.ProductSerial = N'{serial}'

        UNION

            SELECT 11 AS TagEventType, 
                   CAST(N'گارانتی' AS nvarchar) AS TagEventDescription, 
                   Guarantee.fld_ProductGuaranteeLastModifiedDateTime AS TagEventDateTime, 
                   N'' AS TagEventDateTimeShamsi,
        		   Guarantee.fld_ProductGuaranteeLastModifiedUserId AS TagEventUserId
            FROM tbl_ProductGuarantee AS Guarantee
            WHERE Guarantee.fld_ProductGuaranteeProductSerial = N'{serial}'
              AND Guarantee.fld_ProductGuaranteeStatus > 0

        UNION

            SELECT 12 AS TagEventType, 
                   CAST(N'انقضا' AS nvarchar) AS TagEventDescription, 
                   Expire.fld_ProductExpireLastModifiedDateTime AS TagEventDateTime, 
                   N'' AS TagEventDateTimeShamsi,
        		   Expire.fld_ProductExpireLastModifiedUserId AS TagEventUserId
            FROM tbl_ProductExpire AS Expire
            WHERE Expire.fld_ProductExpireProductSerial = N'{serial}' 
              AND Expire.fld_ProductExpireStatus > 0

        ) as NESTED
        ORDER BY TagEventDateTime
        """;



        //SELECT 7 AS TagEventType,
        //    CAST(N'شناسایی در ایستگاه شماره:' + ReaderLog.fld_Reader_Gate AS nvarchar) AS TagEventDescription,

        //    ISNULL(
        //        ReaderLog.fld_TagRead_DateTimeMiladi,
        //        CAST(
        //           dbo.JalaliDateToGeorgianDate(
        //               SUBSTRING(ReaderLog.fld_TagRead_DateTime, 1, 4) + '/' +
        //               SUBSTRING(ReaderLog.fld_TagRead_DateTime, 5, 2) + '/' +
        //               SUBSTRING(ReaderLog.fld_TagRead_DateTime, 7, 2),
        //               SUBSTRING(ReaderLog.fld_TagRead_DateTime, 9, 2) + ':' +
        //               SUBSTRING(ReaderLog.fld_TagRead_DateTime, 11, 2) + ':' +
        //               SUBSTRING(ReaderLog.fld_TagRead_DateTime, 13, 2)
        //           ) AS datetime)) AS TagEventDateTime,

        //    COALESCE( CONVERT(nvarchar(19), ReaderLog.fld_TagRead_DateTimeMiladi, 120),
        //    STUFF(STUFF(ReaderLog.fld_TagRead_DateTime, 9, 0, ':'), 12, 0, ':')) AS TagEventDateTimeShamsi,
        //    ReaderLog.fld_WMUserId AS TagEventUserId
        //     FROM(
        //      SELECT fld_Reader_Gate, fld_TagRead_DateTimeMiladi, fld_TagRead_DateTime, fld_TagSerial, fld_WMUserId
        //      FROM tbl_UHF_ReaderLog

        //     UNION ALL

        //     SELECT fld_Reader_Gate, fld_TagRead_DateTimeMiladi, fld_TagRead_DateTime, fld_TagSerial, fld_WMUserId
        //     FROM tbl_UHF_ReaderLogMain) AS ReaderLog
        //     JOIN TagEpcCTE T ON ReaderLog.fld_TagSerial = T.TagEpc
        //     WHERE ReaderLog.fld_TagSerial<> N'000'
        //     AND ReaderLog.fld_Reader_Gate<> N'0'


        return dataAccess.SqlDataAdapter(command, 660);
    }

    public DataTable SGetGateAlertsBySerial(string serial)
    {
        string command = $"""
        SELECT DISTINCT 
            fld_AlarmLogGateNumber AS GateCode,
            dbo.GeorgianDateToJalaliDate(fld_AlarmLogDateTime) AS Date,
            CAST(fld_AlarmLogDateTime AS TIME) AS [Time], 
            fld_AlarmLogType AS Type,
            COALESCE((SELECT fld_StationName 
                      FROM tbl_Station 
                      WHERE fld_StationCode = tbl_AlarmLog.fld_AlarmLogGateNumber), N'') AS StationName
        FROM tbl_AlarmLog
        WHERE fld_AlarmLogSerial = '{serial}'
        """;

        return dataAccess.SqlDataAdapter(command);
    }

    public DataTable SGetGateAlertsBySerialNew(string serial)
    {
        string command = $"""
        SELECT DISTINCT 
        CAST(fld_AlarmLogGateNumber AS NVARCHAR(50)) AS GateCode,
        fld_AlarmLogDateTime AS Date,
            CAST(fld_AlarmLogDateTime AS TIME) AS [Time], 
            fld_AlarmLogType AS Type,
            COALESCE((SELECT fld_StationName 
                      FROM tbl_Station 
                      WHERE fld_StationCode = tbl_AlarmLog.fld_AlarmLogGateNumber), N'') AS StationName,
         COALESCE((SELECT tbl_User.[Name] 
          FROM tbl_User 
          WHERE (TRY_CONVERT(uniqueidentifier, tbl_AlarmLog.fld_AlarmLogUserId) IS NOT NULL AND tbl_User.Id = tbl_AlarmLog.fld_AlarmLogUserId) OR
          (tbl_User.Username = tbl_AlarmLog.fld_AlarmLogUserId)), N'') AS Username
        FROM tbl_AlarmLog
        WHERE fld_AlarmLogSerial = '{serial}'
        ORDER BY fld_AlarmLogDateTime ASC
        """;

        return dataAccess.SqlDataAdapter(command);
    }

    public DataTable SGetTagHistoryProductInfo(string serial)
    {
        string command = $@" SELECT        TOP (1) COALESCE (tbl_Tags.TagEpc, N'') AS TagEpc, COALESCE (tbl_Tags.ProductSerial, N'') AS ProductSerial, COALESCE (tbl_Tags.ProductCode, N'') AS ProductCode, COALESCE (tbl_Tags.ProductCount, 0) AS ProductCount, 
                         COALESCE (tbl_Products.ProductTitle, N'') AS ProductName, COALESCE (tbl_ProductType.ProductTypeTitle, N'-1') AS ProductTypeTitle, COALESCE (tbl_ProductStatus.ProductStatusTitle, N'') AS ProductStatusTitle, 
                         COALESCE (tbl_Tags.TagStatus, N'') AS TagStatus, COALESCE (tbl_Tags.TagRegisterShamsiUnixDate, N'') AS TagRegisterShamsiUnixDate, COALESCE (tbl_Tags.ProductProperties, N'') AS ProductProperties, 
                         dbo.GetProductAnalyseAge(tbl_Tags.TagRegisterShamsiUnixDate) AS ProductAgeAnalysis, dbo.GeorgianDateToJalaliDate(DATEADD(hour, - 6, tbl_Tags.TagRegisterDateTime)) AS [RegisterActionDate], COALESCE (tbl_Products.ProductTechnicalCode, N'') AS RegCode, COALESCE (tbl_ProductPropertyA.fld_ProductPropertyATitle, N'') 
                         AS fld_ProductPropertyATitle, COALESCE (tbl_ProductPropertyB.fld_ProductPropertyBTitle, N'') AS fld_ProductPropertyBTitle, COALESCE (tbl_Products.ProductENTitle, N'') AS ProductENTitle, 
                         (CASE WHEN tbl_Tags.Freeze = 1 THEN N'فریز' ELSE N'عدم فریز' END) AS FreezeStatus, COALESCE (tbl_Products.ProductPackWeight, 0) AS ProductPackWeight, COALESCE (tbl_Products.ProductPackVolume, 0) 
                         AS ProductPackVolume, COALESCE (tbl_Products.ProductCountInPack, 0) AS ProductCountInPack, COALESCE (tbl_Products.ProductValue, 0) AS ProductValue, COALESCE (tbl_ProductPropertyC.fld_ProductPropertyCTitle, N'') AS ProductSize, 
                         COALESCE (tbl_Products.ProductUnit, N'') AS ProductUnit, tbl_Tags.fld_ProductPropertyAId, tbl_Tags.fld_ProductPropertyBId, COALESCE (tbl_Zones.ZoneTitle, N'') AS TagZone, COALESCE (tbl_Destination.DestinationTitle, N'') 
                         AS Warehouse, N'0*0' AS PlacementZoneId, 
                         CASE WHEN tbl_Tags.TagStatus = 0 THEN N'انبارهای تولید' WHEN tbl_Tags.TagStatus = 1 THEN N'انبارهای محصول' WHEN tbl_Tags.TagStatus = 2 THEN N'انبارهای بارگیری' WHEN tbl_Tags.TagStatus = 3 THEN N'خروج از کارخانه' ELSE
                         N'-' END AS TagStatusTitle, COALESCE((SELECT tbl_User.[Name] FROM tbl_User 
                         WHERE (TRY_CONVERT(uniqueidentifier, tbl_Tags.TagRegisterUser) IS NOT NULL AND tbl_User.Id = tbl_Tags.TagRegisterUser) OR
                        (tbl_User.Username = tbl_Tags.TagRegisterUser) ), N'') AS Username, CAST(DATEDIFF(day, tbl_Tags.TagRegisterDateTime, GETDATE()) AS NVARCHAR(10)) + N' روز' AS ProductAge, 
                         COALESCE (tbl_Products.ProductGalleryId, 0) AS ProductGalleryId, COALESCE (tbl_Tags.DeviceIp, N'') AS OldProductSerial, COALESCE (CAST(tbl_Tags.ContractStatus AS nvarchar(100)), N'') AS DocumentCode, 
                         COALESCE (tbl_Products.ProductTechnicalData, N'') AS ProductTechnicalData, CASE WHEN (tbl_Tags.Lock = 0 AND tbl_Tags.fld_InspectActionId = 0) THEN N'بازرسی نشده' WHEN (tbl_Tags.Lock = 0 AND tbl_Tags.fld_InspectActionId > 0) 
                         THEN N'بازرسی تأیید' WHEN (tbl_Tags.Lock = 1 AND tbl_Tags.fld_InspectActionId > 0) THEN N'بازرسی مردود' ELSE N'-' END AS LastInspectResult, COALESCE (tbl_ProductBrand.fld_ProductBrandTitle, N'') AS ProductBrand, 
                         COALESCE (tbl_ProductGroup.fld_ProductGroupTitle, N'') AS ProductGroup,
						 COALESCE (tbl_ProductSubGroup.fld_ProductSubGroupTitle, N'') AS ProductSubGroup,
                         CASE tbl_Tags.DeviceId WHEN N'0' THEN N'کیوسک رجیستر' WHEN N'' THEN N'هند هلد' ELSE N'مشخص نشده' END AS RegisterDevice,
                        COALESCE((SELECT tbl_User.[Name] 
                        FROM tbl_User 
                        WHERE (TRY_CONVERT(uniqueidentifier, tbl_Tags.TagRegisterUser) IS NOT NULL AND tbl_User.Id = tbl_Tags.TagRegisterUser) OR
                        (tbl_User.Username = tbl_Tags.TagRegisterUser) ), N'') AS RegisterUserName
FROM            tbl_ProductStatus INNER JOIN
                         tbl_Products ON tbl_ProductStatus.ProductStatusCode = tbl_Products.ProductStatus LEFT OUTER JOIN
                         tbl_ProductGroup ON tbl_Products.fld_ProductGroup = tbl_ProductGroup.fld_ProductGroupCode LEFT OUTER JOIN
                         tbl_ProductSubGroup ON tbl_Products.fld_ProductSubGroup = tbl_ProductSubGroup.fld_ProductSubGroupCode LEFT OUTER JOIN
                         tbl_ProductBrand ON tbl_Products.fld_ProductBrand = tbl_ProductBrand.fld_ProductBrandCode LEFT OUTER JOIN
                         tbl_ProductPropertyC ON tbl_Products.ProductSize = tbl_ProductPropertyC.fld_ProductPropertyCId LEFT OUTER JOIN
                         tbl_ProductType ON tbl_Products.ProductType = tbl_ProductType.ProductTypeCode RIGHT OUTER JOIN
                         tbl_Tags LEFT OUTER JOIN
                         tbl_Zones ON tbl_Tags.TagInDestinationId = tbl_Zones.ZoneStoreCode AND tbl_Zones.ZoneCode = tbl_Tags.TagZone ON tbl_Products.ProductCode = tbl_Tags.ProductCode LEFT OUTER JOIN
                         tbl_ProductPropertyA ON tbl_Tags.fld_ProductPropertyAId = tbl_ProductPropertyA.fld_ProductPropertyAId LEFT OUTER JOIN
                         tbl_ProductPropertyB ON tbl_Tags.fld_ProductPropertyBId = tbl_ProductPropertyB.fld_ProductPropertyBId LEFT OUTER JOIN
                         tbl_Destination ON tbl_Destination.DestinationCode = tbl_Tags.TagInDestinationId
   WHERE        (tbl_Tags.TagEpc = N'{serial}') OR
                                                 (tbl_Tags.ProductSerial = N'{serial}') OR (tbl_Tags.DeviceIp = N'{serial}')";

        return dataAccess.SqlDataAdapter(command, 120);
    }

    public DataTable SGetTagRelatedTags(string serial)
    {
        string command = $"""
            SELECT
                tbl_Tags.ProductSerial,
                COALESCE(tbl_Tags.TagEpc, N'') AS TagEpc,
                COALESCE(tbl_Products.ProductTitle, N'') AS ProductName,
                COALESCE(tbl_Tags.ProductCode, N'') AS ProductCode,
                COALESCE(tbl_Tags.ProductCount, 0) AS ProductCount,
                CASE tbl_Tags.TagStatus
                    WHEN 0 THEN N'انبارهای تولید'
                    WHEN 1 THEN N'انبارهای محصول'
                    WHEN 2 THEN N'انبارهای بارگیری'
                    WHEN 3 THEN N'خروج از کارخانه'
                    ELSE N'-'
                END AS TagStatusTitle,
                COALESCE(dbo.GeorgianDateToJalaliDate(tbl_Tags.TagRegisterDateTime), N'') AS RegisterDate,
                N'والد' AS RelationType
            FROM tbl_Tags
            LEFT JOIN tbl_Products ON tbl_Products.ProductCode = tbl_Tags.ProductCode
            WHERE tbl_Tags.ProductSerial = (
                SELECT TOP 1 TagTreeParentsId
                FROM tbl_Tags
                WHERE ProductSerial = N'{serial}'
                  AND TagTreeParentsId IS NOT NULL
                  AND TagTreeParentsId <> N''
            )

            UNION ALL

            SELECT
                tbl_Tags.ProductSerial,
                COALESCE(tbl_Tags.TagEpc, N'') AS TagEpc,
                COALESCE(tbl_Products.ProductTitle, N'') AS ProductName,
                COALESCE(tbl_Tags.ProductCode, N'') AS ProductCode,
                COALESCE(tbl_Tags.ProductCount, 0) AS ProductCount,
                CASE tbl_Tags.TagStatus
                    WHEN 0 THEN N'انبارهای تولید'
                    WHEN 1 THEN N'انبارهای محصول'
                    WHEN 2 THEN N'انبارهای بارگیری'
                    WHEN 3 THEN N'خروج از کارخانه'
                    ELSE N'-'
                END AS TagStatusTitle,
                COALESCE(dbo.GeorgianDateToJalaliDate(tbl_Tags.TagRegisterDateTime), N'') AS RegisterDate,
                N'فرزند' AS RelationType
            FROM tbl_Tags
            LEFT JOIN tbl_Products ON tbl_Products.ProductCode = tbl_Tags.ProductCode
            WHERE tbl_Tags.TagTreeParentsId = N'{serial}'
            """;

        return dataAccess.SqlDataAdapter(command, 120);
    }

    public DataTable SGetTagHistoryMovement(string serial)
    {
        var command = $@"SELECT 
        COALESCE(tbl_ActionTypes.fld_ActionTypeTitle, N'') as ActionTypeTitle, 
        tbl_TagsMovement.RMovementActionId AS ActionId, 
        COALESCE((SELECT DestinationTitle FROM tbl_Destination WHERE DestinationCode = tbl_MovementActions.MovementActionStore), N'') AS SourceStoreTitle, 
        COALESCE((SELECT DestinationTitle FROM tbl_Destination WHERE DestinationCode = tbl_MovementActions.MovementActionDestinationId), N'') AS DestinationStoreTitle, 
        tbl_TagsMovement.RTagsMovementDate as ActionDate, 
        FORMAT(tbl_TagsMovement.RTagsMovementDateTime, 'HH:mm:ss') AS ActionTime,
        COALESCE(tbl_MovementActions.MovementActionUHFLogId, N'') AS ActionUHFLogId, 
        COALESCE(tbl_MovementActions.MovementActionDesc, N'') AS ActionDescription, 
        COALESCE(tbl_MovementActions.MovementActionDocumentId, N'') as ActionDocumentId,
       COALESCE((SELECT tbl_User.[Name] 
         FROM tbl_User 
         WHERE (TRY_CONVERT(uniqueidentifier, tbl_MovementActions.MovementActionUserId) IS NOT NULL AND tbl_User.Id = tbl_MovementActions.MovementActionUserId) OR
         (tbl_User.Username = tbl_MovementActions.MovementActionUserId)), N'') AS ActionUserName
    FROM tbl_TagsMovement
    INNER JOIN tbl_MovementActions ON tbl_MovementActions.MovementActionId = tbl_TagsMovement.RMovementActionId
    LEFT OUTER JOIN tbl_ActionTypes ON tbl_MovementActions.MovementActionTp = tbl_ActionTypes.fld_ActionTypeId
    WHERE tbl_TagsMovement.ProductSerial = N'{serial}' 
      AND tbl_ActionTypes.fld_ActionTypeId <> 6
    ORDER BY tbl_TagsMovement.RTagsMovementDateTime";

        return dataAccess.SqlDataAdapter(command);
    }


    public DataTable SGetTagMovementHistory(string serial)
    {
        var command = $@"SELECT        TOP (10) RMovementActionId, COALESCE(tbl_Destination.DestinationTitle,N'') AS WarehouseTitle,
					   RTagsMovementDate, RTagsMovementTime,COALESCE(tbl_MovementActions.MovementActionUHFLogId,N'') as MovementActionUHFLogId,
					   COALESCE(CASE WHEN ISJSON(tbl_MovementActions.MovementActionData) = 1 THEN Json_Value(tbl_MovementActions.MovementActionData,'$.MovementActionDesc') ELSE N'' END,N'') as Description
                    FROM            tbl_TagsMovement LEFT OUTER JOIN
                                                tbl_MovementActions ON tbl_TagsMovement.RMovementActionId = tbl_MovementActions.MovementActionId LEFT OUTER JOIN
						                        tbl_Destination ON tbl_MovementActions.MovementActionStore = tbl_Destination.DestinationCode
                    WHERE     (   (ProductSerial = N'{serial}') OR (TagEpc = N'{serial}') )
				                    and RMovementActionId>0 
				                    and RTagsMovementSt=1
                    union
                    SELECT        TOP (10) tbl_TagsMovement.HMovementActionId as  RMovementActionId,
					                        COALESCE(tbl_Destination.DestinationTitle,N'') as WarehouseTitle,
					                        tbl_TagsMovement.HTagsMovementDate as RTagsMovementDate,
					                        tbl_TagsMovement.HTagsMovementTime as RTagsMovementTime,
					                        COALESCE(tbl_MovementActions.MovementActionUHFLogId,N'') as MovementActionUHFLogId,
					                        COALESCE(CASE WHEN ISJSON(tbl_MovementActions.MovementActionData) = 1 THEN Json_Value(tbl_MovementActions.MovementActionData,'$.MovementActionDesc') ELSE N'' END,N'') as Description
                    FROM            tbl_TagsMovement LEFT OUTER JOIN
                                                tbl_MovementActions ON tbl_TagsMovement.HMovementActionId = tbl_MovementActions.MovementActionId LEFT OUTER JOIN
						                        tbl_Destination ON tbl_MovementActions.MovementActionStore = tbl_Destination.DestinationCode

                    WHERE       ( (tbl_TagsMovement.ProductSerial = N'{serial}') OR (tbl_TagsMovement.TagEpc = N'{serial}') )
			                    and   HMovementActionId>0 and HTagsMovementSt=1 
			                    and (tbl_MovementActions.MovementActionTp = 6) 
			                    AND (tbl_MovementActions.MovementActionData LIKE N'%برگشت کالا%')  ";

        return dataAccess.SqlDataAdapter(command);
    }

    public DataTable SGetTagPlacementHistory(string serial)
    {
        var command = $@"
        SELECT 
            COALESCE((SELECT DestinationTitle 
                      FROM tbl_Destination 
                      WHERE DestinationCode = tbl_ProductPlacementMissions.fld_PPMStoreCode), N'') AS WarehouseTitle,
            COALESCE((SELECT ZoneTitle 
                      FROM tbl_Zones 
                      WHERE ZoneCode = tbl_ProductPlacementMissions.fld_PPMToZoneId), N'') AS Location,
            COALESCE(dbo.GeorgianDateToJalaliDate(tbl_ProductPlacementMissions.fld_PPMRegDateTime), N'') AS Date,
            COALESCE(CAST(CAST(tbl_ProductPlacementMissions.fld_PPMRegDateTime AS Time) AS nvarchar(5)), N'') AS Time,
            COALESCE((SELECT Username 
                      FROM tbl_User 
                      WHERE Id = tbl_ProductPlacementMissions.fld_PPMWMDriverUserId), N'') AS Username
        FROM tbl_ProductPlacementMissions
        WHERE tbl_ProductPlacementMissions.fld_PPMStatus = 2 
          AND tbl_ProductPlacementMissions.fld_PPMProductSerial = N'{serial}'";

        return dataAccess.SqlDataAdapter(command);
    }

    public DataTable SGetTagInventoryHistory(string serial)
    {
        var command = $@"
        SELECT  
            COALESCE(tbl_InventoryTags.fld_InventoryId, 0) as [OperationCode],
            COALESCE((SELECT DestinationTitle 
                      FROM tbl_Destination 
                      WHERE DestinationCode = tbl_InventoryTags.fld_InventoryStoreCode), N'') as [WarehouseTitle],
            COALESCE(tbl_InventoryTags.fld_InventoryDate, N'') as [Date],
            CASE WHEN tbl_Tags.TagStatus = 0 THEN N'انبارهای تولید'
                 WHEN tbl_Tags.TagStatus = 1 THEN N'انبارهای محصول' 
                 WHEN tbl_Tags.TagStatus = 2 THEN N'انبارهای بارگیری' 
                 ELSE N'-' 
            END AS [Status],
            COALESCE(tbl_InventoryTags.fld_InventoryProductDesc, N'') as [Description],
            COALESCE((SELECT tbl_User.[Name] 
          FROM tbl_User 
          WHERE (TRY_CONVERT(uniqueidentifier, tbl_InventoryTags.fld_InventoryUser) IS NOT NULL AND tbl_User.Id = tbl_InventoryTags.fld_InventoryUser) OR
          (tbl_User.Username = tbl_InventoryTags.fld_InventoryUser)
          ), N'') AS UserName
        FROM tbl_InventoryTags
        INNER JOIN tbl_Tags ON tbl_InventoryTags.fld_InventoryTagEPC = tbl_Tags.TagEpc
        WHERE tbl_Tags.ProductSerial = N'{serial}'
        ORDER BY tbl_InventoryTags.fld_InventoryId";

        return dataAccess.SqlDataAdapter(command);
    }

    public DataTable SGetTagHistoryReadByGate(string serial)
    {
        var command = $@"
        WITH TagEpcCTE AS (
            SELECT TagEpc 
            FROM tbl_Tags 
            WHERE ProductSerial = N'{serial}'
        ),
        LogStatusCTE AS (
            SELECT 0 AS StatusCode, N'شناسایی صحیح' AS StatusText UNION ALL
            SELECT 1, N'نادیده گرفتن' UNION ALL
            SELECT 2, N'نادیده گرفتن به دلیل عدم وجود در مبدأ' UNION ALL
            SELECT 3, N'شناسایی بصورت رجیستر نشده' UNION ALL
            SELECT 4, N'خطا شناسایی بصورت فریز شده' UNION ALL
            SELECT 5, N'خطا شناسایی بصورت بازرسی مردود' UNION ALL
            SELECT 6, N'خطا شناسایی بصورت بدون بازرسی' UNION ALL
            SELECT 7, N'نادیده گرفتن به دلیل عبور قبل از تایم مشخص' UNION ALL
            SELECT 8, N'نادیده گرفتن' UNION ALL
            SELECT 9, N'حذف توسط کاربر'
        )
        SELECT DISTINCT
            COALESCE(fld_Reader_Gate, N'') AS GateCode,
            COALESCE(fld_InventoryId, 0) AS LogId,
            COALESCE(
                SUBSTRING(fld_TagRead_DateTime, 0, 5) + '/' + 
                SUBSTRING(fld_TagRead_DateTime, 5, 2) + '/' + 
                SUBSTRING(fld_TagRead_DateTime, 7, 2), N''
            ) AS LogDate,
            COALESCE(
                SUBSTRING(fld_TagRead_DateTime, 9, 2) + ':' + 
                SUBSTRING(fld_TagRead_DateTime, 11, 2) + ':' + 
                SUBSTRING(fld_TagRead_DateTime, 13, 2), N''
            ) AS LogTime,
            COALESCE(LogStatusCTE.StatusText, N'نامخشص') AS LogStatus,

            COALESCE((SELECT tbl_User.[Name] 
              FROM tbl_User 
              WHERE (TRY_CONVERT(uniqueidentifier, ReaderLog.fld_WMUserId) IS NOT NULL AND tbl_User.Id = ReaderLog.fld_WMUserId) OR
              (tbl_User.Username = ReaderLog.fld_WMUserId)), N'') AS Username,

            COALESCE(( SELECT tbl_ActionTypes.fld_ActionTypeTitle
              FROM tbl_Station 
              JOIN tbl_ActionTypes  ON tbl_ActionTypes.fld_ActionTypeId = tbl_Station.fld_StationActionType
              WHERE tbl_Station.fld_StationCode = ReaderLog.fld_Reader_Gate),N'') AS OperationType,
            COALESCE((SELECT fld_StationName 

                      FROM tbl_Station 
                      WHERE fld_StationCode = ReaderLog.fld_Reader_Gate), N'') AS StationName
        FROM (
            SELECT 
                fld_Reader_Gate,
                fld_InventoryId,
                fld_TagRead_DateTime,
                ActionStatus,
                fld_TagSerial,
                fld_WMUserId
            FROM tbl_UHF_ReaderLogMain
            WHERE fld_TagSerial <> N'000' 
              AND fld_Reader_Gate <> N'0'
              AND fld_TagSerial IN (SELECT TagEpc FROM TagEpcCTE)

            UNION

            SELECT 
                fld_Reader_Gate,
                fld_InventoryId,
                fld_TagRead_DateTime,
                ActionStatus,
                fld_TagSerial,
                fld_WMUserId
            FROM tbl_UHF_ReaderLog
            WHERE fld_TagSerial <> N'000' 
              AND fld_Reader_Gate <> N'0'
              AND fld_TagSerial IN (SELECT TagEpc FROM TagEpcCTE)
        ) AS ReaderLog
        LEFT OUTER JOIN LogStatusCTE ON ReaderLog.ActionStatus = LogStatusCTE.StatusCode
        ORDER BY LogId";

        return dataAccess.SqlDataAdapter(command);
    }

    public string SGetLastReadedTagForHistory()
    {
        var command = "SELECT tbl_UHF_ReaderLog.Id,tbl_tags.ProductSerial " +
            "FROM tbl_UHF_ReaderLog INNER JOIN tbl_Tags ON fld_TagSerial = TagEpc " +
            "WHERE fld_Reader_GateType = 5 AND fld_TagSelectedFlag = 0  " +
            "ORDER BY fld_TagRead_DateTime DESC";

        var dt = dataAccess.SqlDataAdapter(command).Select();

        var serials = dt.Select(p => p.ItemArray[1].ToString()).ToList();

        if (serials.Any())
        {
            ChangeTagReadStatusByList(new List<int>() { dt.Select(p => (int)p.ItemArray[0]).ToList().First() });

            return serials.First();
        }
        else
        {
            return string.Empty;
        }
    }

