        dt.Columns.Add("ProductENTitle", typeof(string));//  
        dt.Columns.Add("ProductPackValue", typeof(string));//  
        dt.Columns.Add("ProductPackWeight", typeof(string));//  
        dt.Columns.Add("ProductPackVolume", typeof(string));//  
        dt.Columns.Add("ProductCountInPack", typeof(string));//  
        dt.Columns.Add("ProductValue", typeof(string));//  
        dt.Columns.Add("ProductTechnicalCode", typeof(string));//  
        dt.Columns.Add("ProductProperties", typeof(string));//  
        dt.Columns.Add("ProductType", typeof(string));//  
        dt.Columns.Add("ProductStatus", typeof(string));//  
        dt.Columns.Add("ProductSize", typeof(string));//  
        dt.Columns.Add("ProductUnit", typeof(string));//  
        dt.Columns.Add("ProductGroup", typeof(string));//  
        dt.Columns.Add("ProductBrand", typeof(string));//  
        dt.Columns.Add("ProductTechnicalData", typeof(string));//  
        dt.Columns.Add("ProductGroupTitle", typeof(string));//  
        dt.Columns.Add("ProductBrandTitle", typeof(string));//  
        dt.Columns.Add("ProductStatusTitle", typeof(string));//  
        dt.Columns.Add("ProductTypeTitle", typeof(string));//  
        dt.Columns.Add("ProductSizeTitle", typeof(string));//  


        var command = @"SELECT        tbl_Products.ProductCode, tbl_Products.ProductTitle, tbl_Products.ProductENTitle, COALESCE (tbl_Products.ProductPackValue, 0) AS ProductPackValue, tbl_Products.ProductPackWeight, 
                         COALESCE (tbl_Products.ProductPackVolume, 0) AS ProductPackVolume, COALESCE (tbl_Products.ProductCountInPack, 0) AS ProductCountInPack, COALESCE (tbl_Products.ProductValue, 0) AS ProductValue, 
                         COALESCE (tbl_Products.ProductTechnicalCode, N'0') AS ProductTechnicalCode, COALESCE (tbl_Products.ProductProperties, N' ') AS ProductProperties, COALESCE (tbl_Products.ProductType, N'0') AS ProductType, 
                         COALESCE (tbl_Products.ProductStatus, N'0') AS ProductStatus, COALESCE (tbl_Products.ProductSize, N'0') AS ProductSize, COALESCE (tbl_Products.ProductUnit, N'0') AS ProductUnit, COALESCE (tbl_Products.fld_ProductGroup, 
                         N'0') AS ProductGroup, COALESCE (tbl_Products.fld_ProductBrand, N'0') AS ProductBrand, COALESCE (tbl_Products.ProductTechnicalData, N'') AS ProductTechnicalData, COALESCE (tbl_ProductGroup.fld_ProductGroupTitle, N'') 
                         AS ProductGroupTitle, COALESCE (tbl_ProductBrand.fld_ProductBrandTitle, N'') AS ProductBrandTitle, COALESCE (tbl_ProductStatus.ProductStatusTitle, N'') AS ProductStatusTitle, COALESCE (tbl_ProductType.ProductTypeTitle, 
                         N'') AS ProductTypeTitle, COALESCE (tbl_ProductPropertyC.fld_ProductPropertyCTitle, N'') AS ProductSizeTitle
FROM            tbl_Products LEFT OUTER JOIN 
tbl_ProductPropertyC ON tbl_Products.ProductSize = tbl_ProductPropertyC.fld_ProductPropertyCId LEFT OUTER JOIN
                         tbl_ProductType ON tbl_Products.ProductType = tbl_ProductType.ProductTypeCode LEFT OUTER JOIN
                         tbl_ProductStatus ON tbl_Products.ProductStatus = tbl_ProductStatus.ProductStatusCode LEFT OUTER JOIN
                         tbl_ProductBrand ON tbl_Products.fld_ProductBrand = tbl_ProductBrand.fld_ProductBrandCode LEFT OUTER JOIN
                         tbl_ProductGroup ON tbl_Products.fld_ProductGroup = tbl_ProductGroup.fld_ProductGroupCode";
        dt = dataAccess.SqlDataAdapter(command);

        return dt;
    }

