                         tbl_Print.ProductUnit, tbl_Print.ProductSize, tbl_Print.ProductRegCode, tbl_ProductStatus.ProductStatusTitle, tbl_Print.ProductWeight, tbl_Print.ProductVolume, tbl_Print.ProjectCode, 
                         tbl_ProductPropertyA.fld_ProductPropertyATitle, tbl_ProductPropertyB.fld_ProductPropertyBTitle, tbl_Print.PrintType, tbl_Print.PrintUser, tbl_Print.PrintFlag, tbl_Print.RegisterFlag, tbl_Print.InputFileName, 
                         tbl_Print.PrintActionDateTime, tbl_Print.ProductContractType, tbl_Products.ProductTechnicalData, tbl_Print.Manufacturer AS ProductOldSerial, tbl_Print.DocumentId, COALESCE (tbl_Tags.TagEpc, N'') AS TagEpc, 
                         COALESCE (tbl_Print.fld_ProductGroup, N'') AS ProductGroup, COALESCE (tbl_Print.fld_ProductBrand, N'') AS ProductBrand, COALESCE (tbl_ProductGroup.fld_ProductGroupTitle, N'') AS ProductGroupTitle, 
                         COALESCE (tbl_ProductBrand.fld_ProductBrandTitle, N'') AS ProductBrandTitle, tbl_ProductPropertyC.fld_ProductPropertyCTitle AS ProductSizeTitle, tbl_Print.ProductProperties,tbl_Print.ProductProductionShift, tbl_Print.ProductProductionLine, tbl_Print.ProductType,tbl_Print.ProductStatus,tbl_Print.Location,tbl_Print.fld_ProductSubGroup,tbl_Print.fld_ProductClass,tbl_Print.DestinationCode as WareHouseCode
FROM            tbl_Tags RIGHT OUTER JOIN
                         tbl_Print ON tbl_Tags.ProductSerial = tbl_Print.ProductSerial LEFT OUTER JOIN
                         tbl_ProductPropertyB ON tbl_Print.ProductProductionShift = tbl_ProductPropertyB.fld_ProductPropertyBId LEFT OUTER JOIN
                         tbl_ProductPropertyA ON tbl_Print.ProductProductionLine = tbl_ProductPropertyA.fld_ProductPropertyAId LEFT OUTER JOIN
                         tbl_ProductPropertyC RIGHT OUTER JOIN
                         tbl_Products ON tbl_ProductPropertyC.fld_ProductPropertyCId = tbl_Products.ProductSize LEFT OUTER JOIN
                         tbl_ProductBrand ON tbl_Products.fld_ProductBrand = tbl_ProductBrand.fld_ProductBrandCode LEFT OUTER JOIN
                         tbl_ProductGroup ON tbl_Products.fld_ProductGroup = tbl_ProductGroup.fld_ProductGroupCode LEFT OUTER JOIN
                         tbl_ProductType ON tbl_Products.ProductType = tbl_ProductType.ProductTypeCode LEFT OUTER JOIN
                         tbl_ProductStatus ON tbl_Products.ProductStatus = tbl_ProductStatus.ProductStatusCode ON tbl_Print.ProductCode = tbl_Products.ProductCode   
        WHERE(tbl_Print.ProductSerial = @ProductSerial) and SoftDelete=0  ORDER BY tbl_Print.ProductSerial ";

        dtProductInfo = dataAccess.SqlDataAdapter(command,
            new KeyValuePair<string, object>("ProductSerial", ProductSerial));

        return dtProductInfo;
    }

