 COALESCE (tbl_Print.fld_ProductBrand, N'') AS ProductBrand,
 COALESCE (tbl_ProductGroup.fld_ProductGroupTitle, N'') AS ProductGroupTitle, 
 COALESCE (tbl_ProductBrand.fld_ProductBrandTitle, N'') AS ProductBrandTitle,
 tbl_ProductPropertyC.fld_ProductPropertyCTitle AS ProductSizeTitle,
 tbl_Print.ProductProperties,
 tbl_Print.ProductProductionLine,
 tbl_Print.ProductProductionShift,
 COALESCE (tbl_Print.ProductType, N'') AS ProductTypeCode,
 COALESCE (tbl_Products.ProductPackValue, 0) AS ProductPackValue,
 COALESCE (tbl_Products.ProductPackWeight, 0) AS ProductPackWeight,
 COALESCE (tbl_Print.ProductStatus, N'') AS ProductStatusCode,
 COALESCE (tbl_Print.DestinationCode, N'') AS DestinationCode,
 COALESCE (tbl_Print.PrintActionId, 0) AS ActionId
FROM            tbl_Tags RIGHT OUTER JOIN
                          tbl_Print ON tbl_Tags.ProductSerial = tbl_Print.ProductSerial LEFT OUTER JOIN
                          tbl_ProductPropertyB ON tbl_Print.ProductProductionShift = tbl_ProductPropertyB.fld_ProductPropertyBId LEFT OUTER JOIN
                          tbl_ProductPropertyA ON tbl_Print.ProductProductionLine = tbl_ProductPropertyA.fld_ProductPropertyAId LEFT OUTER JOIN
