                          tbl_ProductType ON tbl_Products.ProductType = tbl_ProductType.ProductTypeCode LEFT OUTER JOIN
                          tbl_ProductStatus ON tbl_Products.ProductStatus = tbl_ProductStatus.ProductStatusCode ON tbl_Print.ProductCode = tbl_Products.ProductCode   
WHERE        (tbl_Print.PrintActionId = (SELECT TOP(1) InnerP.PrintActionId FROM tbl_Print InnerP WHERE InnerP.ProductSerial = @ProductSerial))
ORDER BY tbl_Print.ProductSerial
";
        dtProductInfo = dataAccess.SqlDataAdapter(command,
            new KeyValuePair<string, object>("ProductSerial", serial));

        return dtProductInfo;
    }

    public DataTable SReportPrint(List<ReportFilter> reportFilters)
    {
        var dt = new DataTable();
        dt.Columns.Add("ProductSerial", typeof(string));
        dt.Columns.Add("ProductCode", typeof(string));
        dt.Columns.Add("ProductName", typeof(string));
        dt.Columns.Add("ProductProperties", typeof(string));
        dt.Columns.Add("PrintActionDateTime", typeof(DateTime));
        dt.Columns.Add("RegisterUser", typeof(string));
        dt.Columns.Add("PrintFlag", typeof(int));
        dt.Columns.Add("RegisterFlag", typeof(int));

        reportFilters ??= new();

        var where = new StringBuilder(" WHERE (tbl_Print.SoftDelete = 0 OR tbl_Print.SoftDelete IS NULL) ");
        var parameters = new List<KeyValuePair<string, object>>();

        string? GetSingleValue(string fieldName)
        {
            var filter = reportFilters.FirstOrDefault(p => p.FieldName != null && p.FieldName.Equals(fieldName, StringComparison.OrdinalIgnoreCase));
            if (filter == null)
            {
                return null;
            }

            if (filter.Values != null && filter.Values.Any())
            {
                return filter.Values.FirstOrDefault();
            }

            return filter.Value;
        }

        void AddLikeCondition(string columnName, string fieldName)
        {
            var filter = reportFilters.FirstOrDefault(p => p.FieldName != null && p.FieldName.Equals(fieldName, StringComparison.OrdinalIgnoreCase));
            var value = GetSingleValue(fieldName);
            if (value.HasNoValue())
            {
                return;
            }

            var paramName = fieldName + "Like";
            if (filter is not null && filter.IsLike)
            {
                where.Append($" AND {columnName} LIKE @{paramName} ");
                parameters.Add(new(paramName, $"%{value}%"));
            }
            else
            {
                where.Append($" AND {columnName} = @{paramName} ");
                parameters.Add(new(paramName, value));
            }
        }

        void AddIntCondition(string columnName, string fieldName)
        {
            var value = GetSingleValue(fieldName);
            if (value.HasNoValue())
            {
                return;
            }

            if (!int.TryParse(value, out int parsed))
            {
                return;
            }

            var paramName = fieldName + "Value";
            where.Append($" AND {columnName} = @{paramName} ");
            parameters.Add(new(paramName, parsed));
        }

        void AddDateCondition(string columnName, string fieldName, bool isStart)
        {
            var value = GetSingleValue(fieldName);
            if (value.HasNoValue())
            {
                return;
            }

            DateTime parsedDate;
            try
            {
                parsedDate = PersianCalendarTools.PersianToGregorian(value);
            }
            catch
            {
                return;
            }

            var paramName = fieldName + (isStart ? "Start" : "End");
            if (isStart)
            {
                where.Append($" AND {columnName} >= @{paramName} ");
                parameters.Add(new(paramName, parsedDate.Date));
            }
            else
            {
                where.Append($" AND {columnName} < DATEADD(day, 1, @{paramName}) ");
                parameters.Add(new(paramName, parsedDate.Date));
            }
        }

        AddLikeCondition("tbl_Print.ProductSerial", "ProductSerial");
        AddLikeCondition("tbl_Print.ProductCode", "ProductCode");
        AddIntCondition("tbl_Print.PrintFlag", "PrintFlag");
        AddIntCondition("tbl_Print.RegisterFlag", "RegisterFlag");
        AddDateCondition("tbl_Print.PrintActionDateTime", "FromDate", true);
        AddDateCondition("tbl_Print.PrintActionDateTime", "ToDate", false);

        var command = $@"
            SELECT
                COALESCE(tbl_Print.ProductSerial, N'') AS ProductSerial,
                COALESCE(tbl_Print.ProductCode, N'') AS ProductCode,
                COALESCE(tbl_Print.ProductName, N'') AS ProductName,
                COALESCE(tbl_Print.ProductProperties, N'') AS ProductProperties,
                tbl_Print.PrintActionDateTime as [DateTime],
                COALESCE(tbl_User.Name, tbl_User.Username, tbl_Print.RegisterUser, N'') AS RegisterUser,
                COALESCE(tbl_Print.PrintFlag, 0) AS PrintFlag,
                COALESCE(tbl_Print.RegisterFlag, 0) AS RegisterFlag,
                COALESCE(tbl_Print.ProductRegCode, N'') AS ProductRegCode,
                COALESCE(tbl_Print.ProductCount, 0) AS ProductCount
            FROM tbl_Print
            LEFT OUTER JOIN tbl_User ON tbl_User.Id = tbl_Print.RegisterUser
            {where}
            ORDER BY ProductSerial DESC";

        return dataAccess.SqlDataAdapter(command, parameters.ToArray());
    }

