    public bool SDeleteProduct(string ProductCode)
    {
        var commandProductExist = "SELECT ProductCode FROM tbl_Tags WHERE ProductCode = N'" + ProductCode + "'";
        var hasValue = dataAccess.SqlDataReaders(commandProductExist);
        if (hasValue == null)
        {
            var command = @"Delete From tbl_Products  Where ProductCode=@ProductCode ";
            return dataAccess.CmdSqlExecuteNonQuery(command,
                new KeyValuePair<string, object>("ProductCode", ProductCode)) > 0;
        }
        else
            return false;

    }


    public bool SDeletePrintByPrintId(string PrintId)
    {
        var commandDeletePrintByPrintId = " DELETE FROM tbl_Print WHERE         Id =   N'" + PrintId + "'";
        return dataAccess.CmdSqlExecuteNonQuery(commandDeletePrintByPrintId) > 0;
    }


