                         GETDATE())) AND (CAST(dbo.JalaliDateToGeorgianDate(SUBSTRING(tbl_Tags.TagRegisterShamsiUnixDate, 0, 5) + '/' + SUBSTRING(tbl_Tags.TagRegisterShamsiUnixDate, 5, 2) 
                         + '/' + SUBSTRING(tbl_Tags.TagRegisterShamsiUnixDate, 7, 2), SUBSTRING(tbl_Tags.TagRegisterShamsiUnixDate, 9, 2) + ':' + SUBSTRING(tbl_Tags.TagRegisterShamsiUnixDate, 11, 2)) AS datetime) >= DATEADD(month, - 3, 
                         GETDATE()))) THEN N'13' WHEN ((CAST(dbo.JalaliDateToGeorgianDate(SUBSTRING(tbl_Tags.TagRegisterShamsiUnixDate, 0, 5) + '/' + SUBSTRING(tbl_Tags.TagRegisterShamsiUnixDate, 5, 2) 
                         + '/' + SUBSTRING(tbl_Tags.TagRegisterShamsiUnixDate, 7, 2), SUBSTRING(tbl_Tags.TagRegisterShamsiUnixDate, 9, 2) + ':' + SUBSTRING(tbl_Tags.TagRegisterShamsiUnixDate, 11, 2)) AS datetime) < DATEADD(month, - 3, 
                         GETDATE())) AND (CAST(dbo.JalaliDateToGeorgianDate(SUBSTRING(tbl_Tags.TagRegisterShamsiUnixDate, 0, 5) + '/' + SUBSTRING(tbl_Tags.TagRegisterShamsiUnixDate, 5, 2) 
                         + '/' + SUBSTRING(tbl_Tags.TagRegisterShamsiUnixDate, 7, 2), SUBSTRING(tbl_Tags.TagRegisterShamsiUnixDate, 9, 2) + ':' + SUBSTRING(tbl_Tags.TagRegisterShamsiUnixDate, 11, 2)) AS datetime) >= DATEADD(month, - 6, 
                         GETDATE()))) THEN N'36' WHEN ((CAST(dbo.JalaliDateToGeorgianDate(SUBSTRING(tbl_Tags.TagRegisterShamsiUnixDate, 0, 5) + '/' + SUBSTRING(tbl_Tags.TagRegisterShamsiUnixDate, 5, 2) 
                         + '/' + SUBSTRING(tbl_Tags.TagRegisterShamsiUnixDate, 7, 2), SUBSTRING(tbl_Tags.TagRegisterShamsiUnixDate, 9, 2) + ':' + SUBSTRING(tbl_Tags.TagRegisterShamsiUnixDate, 11, 2)) AS datetime) < DATEADD(month, - 6, 
                         GETDATE())) AND (CAST(dbo.JalaliDateToGeorgianDate(SUBSTRING(tbl_Tags.TagRegisterShamsiUnixDate, 0, 5) + '/' + SUBSTRING(tbl_Tags.TagRegisterShamsiUnixDate, 5, 2) 
                         + '/' + SUBSTRING(tbl_Tags.TagRegisterShamsiUnixDate, 7, 2), SUBSTRING(tbl_Tags.TagRegisterShamsiUnixDate, 9, 2) + ':' + SUBSTRING(tbl_Tags.TagRegisterShamsiUnixDate, 11, 2)) AS datetime) >= DATEADD(month, - 12, 
                         GETDATE()))) THEN N'612' WHEN ((CAST(dbo.JalaliDateToGeorgianDate(SUBSTRING(tbl_Tags.TagRegisterShamsiUnixDate, 0, 5) + '/' + SUBSTRING(tbl_Tags.TagRegisterShamsiUnixDate, 5, 2) 
                         + '/' + SUBSTRING(tbl_Tags.TagRegisterShamsiUnixDate, 7, 2), SUBSTRING(tbl_Tags.TagRegisterShamsiUnixDate, 9, 2) + ':' + SUBSTRING(tbl_Tags.TagRegisterShamsiUnixDate, 11, 2)) AS datetime) < DATEADD(month, - 12, 
                         GETDATE()))) THEN N'1200' END
HAVING        (COUNT(tbl_TagsMovement.ProductSerial) > 0)
ORDER BY AgeTitle2                         ";

            dtProductsAgeList = dataAccess.SqlDataAdapter(sqlCommand);
        }
        catch (Exception exception)
        {
            return null;
        }

        return dtProductsAgeList;
    }

