    public DataTable SPSearchProduct(string name, string reg, string code, string st)
    {
        var dtProductInfo = new DataTable();
        var command = @"
                             SELECT tbl_Products.Id as [ProductId],
COALESCE( tbl_Products.ProductCode,N'-1') as [ProductCode],
COALESCE(tbl_Products.ProductTitle,N'-1') as [ProductName],
COALESCE( tbl_Products.ProductENTitle,N'-1') as [ProductENTitle],
COALESCE(tbl_Products.ProductPackValue,N'-1') as ProductPackValue,
COALESCE( tbl_Products.ProductPackWeight,N'-1') as [ProductPackWeight],
COALESCE(tbl_Products.ProductPackVolume,N'-1') as [ProductPackVolume], 
COALESCE(tbl_Products.ProductCountInPack,N'-1') as [ProductCountInPack],
COALESCE(tbl_Products.ProductValue,N'-1') as [ProductValue],
COALESCE(tbl_Products.ProductTechnicalCode,N'-1')as [TechnicalCode],
COALESCE( tbl_Products.ProductProperties,N'-1')as [ProductProperties],
COALESCE(tbl_Products.ProductType,N'-1') as [ProductType] ,
COALESCE( tbl_Products.ProductSize,N'-1')as [ProductSize] ,
COALESCE (tbl_Products.ProductUnit,N'-1')as [ProductUnit], 
COALESCE(tbl_Products.ProductStatus,N'-1')as [ProductStatus],
COALESCE (tbl_ProductStatus.ProductStatusTitle,N'-1')as [ProductStatusTitle],
COALESCE (tbl_ProductType.ProductTypeTitle,N'-1')as [ProductTypeTitle],
COALESCE (tbl_ProductStatus.ProductStatusTitle,N'-1')as [Quality],
COALESCE([Size].fld_ProductPropertyCId , N'') AS [ProductSizeCode],
COALESCE([Size].fld_ProductPropertyCTitle , N'') AS [ProductSizeTitle],
COALESCE(tbl_ProductGroup.fld_ProductGroupCode, N'') AS [ProductGroupCode],
COALESCE(tbl_ProductGroup.fld_ProductGroupTitle, N'') AS [ProductGroupTitle],
COALESCE(tbl_ProductGroup.fld_ProductGroupTitle, N'') AS [ProductGroupTitle],
COALESCE(tbl_ProductBrand.fld_ProductBrandCode, N'') AS [ProductBrandCode],
COALESCE(tbl_ProductBrand.fld_ProductBrandTitle, N'') AS [ProductBrandTitle],
COALESCE(tbl_Products.fld_ProductSubGroup, N'') AS [ProductSubGroup], 
COALESCE(tbl_Products.fld_ProductClass, N'') AS [ProductClass],
COALESCE((SELECT        TOP (1) fld_CountInNextlevelUnit
FROM            tbl_ProductUOM
WHERE        (fld_ProductCode = tbl_Products.ProductCode) AND (fld_UOMLevel = 1)),'1') as [CountInNextlevelUnit],
COALESCE((SELECT        tbl_UOM.fld_UOMTitle
FROM            tbl_ProductUOM LEFT OUTER JOIN
                         tbl_UOM ON tbl_ProductUOM.fld_UOMId = tbl_UOM.fld_UOMId
WHERE        (tbl_ProductUOM.fld_ProductCode = tbl_Products.ProductCode) AND (tbl_ProductUOM.fld_UOMLevel = 2)),'1') as [NextlevelUnitTitle],
COALESCE(tbl_Products.fld_HasDoubleTag, 0) AS [HasDoubleTag]
FROM tbl_Products LEFT OUTER JOIN
tbl_ProductType ON tbl_Products.ProductType = tbl_ProductType.ProductTypeCode LEFT OUTER JOIN
tbl_ProductStatus ON tbl_Products.ProductStatus = tbl_ProductStatus.ProductStatusCode LEFT OUTER JOIN
tbl_ProductPropertyC [Size] ON [Size].fld_ProductPropertyCId = tbl_Products.ProductSize LEFT OUTER JOIN
tbl_ProductGroup ON tbl_ProductGroup.fld_ProductGroupCode = tbl_Products.fld_ProductGroup LEFT OUTER JOIN
tbl_ProductBrand ON tbl_ProductBrand.fld_ProductBrandCode = tbl_Products.fld_ProductBrand ";
        var whereStr = "";
        if (!name.Equals("-1"))
        {
            if (!string.IsNullOrEmpty(whereStr))
                whereStr += " AND ";
            whereStr += $" (tbl_Products.ProductTitle LIKE N'%{name}%') ";
        }
        if (!reg.Equals("-1"))
        {
            if (!string.IsNullOrEmpty(whereStr))
                whereStr += " AND ";
            whereStr += $" (tbl_Products.ProductTechnicalCode = N'{reg}') ";
        }
        if (!code.Equals("-1"))
        {
            if (!string.IsNullOrEmpty(whereStr))
                whereStr += " AND ";
            whereStr += $" (tbl_Products.ProductCode = N'{code}') ";
        }
        if (!st.Equals("-1"))
        {
            if (!string.IsNullOrEmpty(whereStr))
                whereStr += " AND ";
            whereStr += $" (tbl_Products.ProductStatus = N'{st}') ";
        }
        if (!string.IsNullOrEmpty(whereStr))
            command = command + " WHERE " + whereStr;
        dtProductInfo = dataAccess.SqlDataAdapter(command);
        return dtProductInfo;
    }

    public DataTable SPSearchProductBySerial(GetAllProductBySerialDto search)
    {
        var whereString = "";

        if (search.FromSerial.NotEquals("-1"))
        {
            if (!string.IsNullOrEmpty(whereString))
                whereString += " AND ";
            whereString += $" (tbl_Tags.ProductSerial >= N'{search.FromSerial}') ";
        }

        if (search.ToSerial.NotEquals("-1"))
        {
            if (!string.IsNullOrEmpty(whereString))
                whereString += " AND ";
            whereString += $" (tbl_Tags.ProductSerial <= N'{search.ToSerial}') ";
        }

        if (search.Line.NotEquals("-1"))
        {
            if (!string.IsNullOrEmpty(whereString))
                whereString += " AND ";
            whereString += $" (tbl_Tags.fld_ProductPropertyAId = N'{search.Line}') ";
        }

        if (search.Shift.NotEquals("-1"))
        {
            if (!string.IsNullOrEmpty(whereString))
                whereString += " AND ";
            whereString += $" (tbl_Tags.fld_ProductPropertyBId = N'{search.Shift}') ";
        }

        if (search.Size.NotEquals("-1"))
        {
            if (!string.IsNullOrEmpty(whereString))
                whereString += " AND ";
            whereString += $" (tbl_Tags.fld_ProductPropertyCId = N'{search.Size}') ";
        }

        if (search.Qc.NotEquals("-1"))
        {
            if (!string.IsNullOrEmpty(whereString))
                whereString += " AND ";
            whereString += $" (tbl_Tags.ProductStatus = N'{search.Qc}') ";
        }

        if (search.TechnicalCode.NotEquals("-1"))
        {
            if (!string.IsNullOrEmpty(whereString))
            {
                whereString += " AND ";
            }

            if (!search.TechnicalCodeLike)
            {
                whereString += " (tbl_Tags.RegCode = N'" + search.TechnicalCode + "')  ";
            }
            else
            {
                whereString += " (tbl_Tags.RegCode Like N'%" + search.TechnicalCode + "%')  ";
            }
        }

        if (search.ProductCode.NotEquals("-1"))
        {
            if (!string.IsNullOrEmpty(whereString))
                whereString += " AND ";
            whereString += $" (tbl_Tags.ProductCode = N'{search.ProductCode}') ";
        }

        if (!search.FromDate.Equals("-1"))
        {
            search.FromDate = search.FromDate.Substring(0, 4) + search.FromDate.Substring(5, 2) + search.FromDate.Substring(8, 2);
            whereString += string.IsNullOrEmpty(whereString) ? "" : " AND ";
            whereString += $" SUBSTRING(tbl_Tags.TagRegisterShamsiUnixDate,0,9) >= N'{search.FromDate}' ";
        }

        if (!search.ToDate.Equals("-1"))
        {
            search.ToDate = search.ToDate.Substring(0, 4) + search.ToDate.Substring(5, 2) + search.ToDate.Substring(8, 2);
            whereString += string.IsNullOrEmpty(whereString) ? "" : " AND ";
            whereString += $" SUBSTRING(tbl_Tags.TagRegisterShamsiUnixDate,0,9) <= N'{search.ToDate}' ";
        }

        if (!search.OldSerial.Equals("-1"))
        {
            whereString += string.IsNullOrEmpty(whereString) ? "" : " AND ";
            whereString += $" (tbl_Tags.DeviceIp = N'{search.OldSerial}') ";
        }

        if (!search.FreezeStatus.Equals(-1))
        {
            whereString += string.IsNullOrEmpty(whereString) ? "" : " AND ";
            whereString += $" (tbl_Tags.Freeze = N'{search.FreezeStatus}') ";
        }

        if (!search.Brand.Equals("-1"))
        {
            whereString += string.IsNullOrEmpty(whereString) ? "" : " AND ";
            whereString += $" (tbl_Tags.fld_ProductBrand = N'{search.Brand}') ";
        }

        if (!search.Group.Equals("-1"))
        {
            whereString += string.IsNullOrEmpty(whereString) ? "" : " AND ";
            whereString += $" (tbl_Tags.fld_ProductGroup = N'{search.Group}') ";
        }

        if (!search.Type.Equals("-1"))
        {
            whereString += string.IsNullOrEmpty(whereString) ? "" : " AND ";
            whereString += $" (tbl_Tags.ProductType = N'{search.Type}') ";
        }

        if (search.DynamicFilters is { Count: > 0 })
        {
            foreach (var filter in search.DynamicFilters)
            {
                if (string.IsNullOrWhiteSpace(filter.Key) || string.IsNullOrWhiteSpace(filter.Value))
                    continue;

                whereString += string.IsNullOrEmpty(whereString) ? "" : " AND ";
                whereString += $" (JSON_VALUE(tbl_Tags.ProductProperties, N'$.\"{filter.Key}\"') LIKE N'%{filter.Value}%') ";
            }
        }

        if (!string.IsNullOrEmpty(whereString))
            whereString = " WHERE " + whereString;

        var command = $@"
;WITH FilteredTags AS
(
    SELECT
        ProductSerial,
        ProductCode,
        RegCode,
        ProductName,
        TagRegisterShamsiUnixDate,
        fld_ProductPropertyAId,
        fld_ProductPropertyBId,
        fld_ProductPropertyCId,
        ProductStatus,
        TagZone,
        TagInDestinationId,
        ProductCount,
        Freeze,
        DeviceIp,
        ProductType AS ProductTypeCode,
        fld_ProductBrand AS [ProductBrand],
        fld_ProductGroup AS [ProductGroup]
    FROM tbl_Tags WITH (NOLOCK)
    {whereString}
)
SELECT
    ISNULL(F.ProductSerial, N'') AS [ProductSerial],
    ISNULL(F.ProductCode, N'') AS [ProductCode],
    ISNULL(F.RegCode, N'') AS [TechnicalCode],
    ISNULL(F.ProductName, N'') AS [ProductName],
    ISNULL(F.TagRegisterShamsiUnixDate, N'') AS [DateTime],
    ISNULL(A.fld_ProductPropertyATitle, N'') AS [Line],
    ISNULL(B.fld_ProductPropertyBTitle, N'') AS [Shift],
    ISNULL(C.fld_ProductPropertyCTitle, N'') AS [Size],
    ISNULL(S.ProductStatusTitle, N'') AS [Qc],
    ISNULL(D.DestinationTitle, N'') AS [Warehouse],
    ISNULL(Z.ZoneTitle, N'') AS [Location],
    ISNULL(F.ProductCount, 0) AS [Count],
    CASE 
        WHEN F.Freeze = 1 THEN N'فریز'
        WHEN F.Freeze = 0 THEN N'عدم فریز'
        ELSE N'مشخص نشده'
    END AS [FreezeStatus],
    ISNULL((SELECT tbl_ProductType.ProductTypeTitle FROM tbl_ProductType WHERE tbl_ProductType.ProductTypeCode = F.ProductTypeCode), 0) AS [Type],
    ISNULL((SELECT tbl_ProductBrand.fld_ProductBrandTitle FROM tbl_ProductBrand WHERE tbl_ProductBrand.fld_ProductBrandCode = F.ProductBrand), 0) AS [Brand],
    ISNULL((SELECT tbl_ProductGroup.fld_ProductGroupTitle FROM tbl_ProductGroup WHERE tbl_ProductGroup.fld_ProductGroupCode = F.ProductGroup), 0) AS [Group]
FROM FilteredTags F
    LEFT JOIN tbl_Zones Z ON F.TagZone = Z.ZoneCode
    LEFT JOIN tbl_Destination D ON F.TagInDestinationId = D.DestinationCode
    LEFT JOIN tbl_ProductPropertyA A ON F.fld_ProductPropertyAId = A.fld_ProductPropertyAId
    LEFT JOIN tbl_ProductPropertyB B ON F.fld_ProductPropertyBId = B.fld_ProductPropertyBId
    LEFT JOIN tbl_ProductPropertyC C ON F.fld_ProductPropertyCId = C.fld_ProductPropertyCId
    LEFT JOIN tbl_ProductStatus S ON F.ProductStatus = S.ProductStatusCode
ORDER BY F.ProductSerial;
";


        return dataAccess.SqlDataAdapter(command, 120);
    }

