            if (!string.IsNullOrEmpty(whereStr))
                whereStr += " AND ";
            whereStr += $" (tbl_Products.fld_ProductBrand = N'{search.Brand}') ";
        }

        if (!search.Group.Equals("-1"))
        {
            if (!string.IsNullOrEmpty(whereStr))
                whereStr += " AND ";
            whereStr += $" (tbl_Products.fld_ProductGroup = N'{search.Group}') ";
        }

        if (!search.SubGroup.Equals("-1"))
        {
            if (!string.IsNullOrEmpty(whereStr))
                whereStr += " AND ";
            whereStr += $" (tbl_Products.fld_ProductSubGroup = N'{search.SubGroup}') ";
        }

        if (!search.Class.Equals("-1"))
        {
            if (!string.IsNullOrEmpty(whereStr))
                whereStr += " AND ";
            whereStr += $" (tbl_Products.fld_ProductClass = N'{search.Class}') ";
        }

        if (!string.IsNullOrEmpty(whereStr))
        {
            whereStr += " AND ";
        }

        whereStr += $" (COALESCE(tbl_Products.fld_ProductIsActive,1) = {(search.IsActive ? "1" : "0")}) ";

        if (!string.IsNullOrEmpty(whereStr))
            command = command + " WHERE " + whereStr;
        dtProductInfo = dataAccess.SqlDataAdapter(command);
        return dtProductInfo;
    }

