    public string SCreateEpc(string serial, string productCode, string refCode, string epc, string type)
    {
        string newEpc = "";

        if (type.ToLower() == "1")//FTP pomp
        {
            serial = ReplaceAllEnglishAlphbet(serial, "").Trim();
            Random rdm = new Random();
            string Random = rdm.Next(1, 99).ToString().PadLeft(2, '0'); //2char



            //if ((productCode.Length + serial.Length) <= 22)
            //{
            productCode = (productCode.Length > 12) ? productCode.Substring(productCode.Length - 12, 12) : productCode.PadRight(12, '0');//12 char



            serial = (serial.Length > 10) ? serial.Substring(serial.Length - 10, 10).Trim() : serial.Trim().PadLeft(10, '0');//10 char

            newEpc = (productCode + Random + serial).Substring(0, 24);
            //}
            //else
            //{
            //    serial = serial.Substring(0, 12) + Random + serial.Substring(14, 10).Trim().PadLeft(10, '0');

            //    newEpc = serial.Substring(0,24);
            //}
        }
        else if (type.ToLower() == "2")
        {
            productCode = (productCode.Length > 12) ? productCode.Substring(productCode.Length - 12, 12) : productCode.PadLeft(12, '0');

            serial = (long.Parse(SGetNewProductSerial(configuration.GetSection("ProjectConfigs").GetSection("WmsConfigs")["GetMaxProductSerialBy"].ToString()))).ToString();

            serial = (serial.Length > 12) ? serial.Substring(serial.Length - 12, 12) : serial.PadLeft(12, '0');

            newEpc = (productCode + serial).Substring(0, 24);
        }
        else if (type.ToLower() == "kdt") //ftp TolidFan
        {
            Random rdm = new Random();

            serial = rdm.Next(1, 999).ToString().PadLeft(3, '0') + "000000000000" + serial;

            newEpc = serial.PadLeft(24, '0').Substring(0, 24);
        }


        return newEpc;
    }

    public string SCreateNewSerial(string serial, string productCode, string refCode, string epc, string type, string productProductionLine = "", string productProductionShift = "")
    {
        string newSerial = "";

        if (type.ToLower() == "ftp_pomp")
        {
            if (serial.Length < 18)
            {
                productCode = (productCode.Length > 12) ? productCode.Substring(productCode.Length - 12, 12) : productCode.PadRight(12, '0');

                serial = ReplaceAllEnglishAlphbet(serial, "").Trim();
                //if (serial.Length < 8)
                //{
                //    PersianCalendar pc = new PersianCalendar();
                //    serial = pc.GetMonth(DateTime.Now).ToString().Trim().PadLeft(2, '0') + pc.GetDayOfMonth(DateTime.Now).ToString().PadLeft(2, '0') + pc.GetHour(DateTime.Now).ToString().PadLeft(2, '0') + pc.GetMinute(DateTime.Now).ToString().PadLeft(2, '0') + pc.GetSecond(DateTime.Now).ToString().PadLeft(2, '0') + pc.GetMilliseconds(DateTime.Now).ToString().PadLeft(2, '0').Substring(0, 2) + serial;
                //}

                serial = (serial.Length > 12) ? serial.Trim().Substring(serial.Length - 12, 12) : serial.Trim().PadLeft(12, '0');

                newSerial = productCode + serial;
            }
            else
            {
                newSerial = serial;
            }
        }
        else if (type.ToLower() == "ftp_tolidfan")
        {
            if (serial.Length < 18)
            {
                productCode = (productCode.Length > 12) ? productCode.Substring(productCode.Length - 12, 12) : productCode.PadRight(12, '0');

                serial = ReplaceAllEnglishAlphbet(serial, "");
                //if (serial.Length < 8)
                //{
                //    PersianCalendar pc = new PersianCalendar();
                //    serial = pc.GetYear(DateTime.Now).ToString().Substring(3, 2) + pc.GetMonth(DateTime.Now).ToString().PadLeft(2, '0') + serial;
                //}

                serial = (serial.Length > 12) ? serial.Substring(serial.Length - 12, 12) : serial.PadLeft(12, '0');

                newSerial = productCode + serial;
            }
            else
            {
                newSerial = serial;
            }
        }
        else if (type.ToLower() == "kdt")
        {
            if (serial.Length != 9)
            {
                string Year = DateTimeTools.GetPersianDate().Substring(1, 3);
                string Month = DateTimeTools.GetPersianDate().Substring(5, 2);
                string Counter = "0001";

                var commandCheckExistSerialIntbl_Tags = @"SELECT        MAX(CAST(SUBSTRING(ProductSerial, 6, 4) AS int))+1 AS Expr1 FROM            tbl_Print WHERE        (ProductSerial LIKE '" + Year + Month + "%')";
                var CheckExistSerialIntbl_Tags = dataAccess.SqlDataReaders(commandCheckExistSerialIntbl_Tags);
                if (CheckExistSerialIntbl_Tags != null && CheckExistSerialIntbl_Tags[0].Value.ToString() != "")
                {
                    Counter = CheckExistSerialIntbl_Tags[0].Value.ToString().PadLeft(4, '0');
                }

                newSerial = Year + Month + Counter;
            }
            else
                newSerial = serial;
        }
        else if (type.ToLower() == "kosar")
        {
            if (serial.Length < 8)
            {
                var CommandtGetProductData = @"SELECT        TOP (1) ProductTechnicalCode, ProductTitle, ProductENTitle, ProductSize,ProductValue,ProductUnit,
                                        ProductCountInPack, ProductPackValue, ProductPackVolume,ProductPackWeight, ProductStatus,ProductProperties, ProductType,Coalesce(fld_ProductGroup,'') as ProductGroup,Coalesce(fld_ProductBrand,'') as ProductBrand,fld_ProductSubGroup
                                        FROM            tbl_Products
                                        WHERE (ProductCode = N'" + productCode + "')"
                  ;
                var ProductInfo = dataAccess.SqlDataReaders(CommandtGetProductData,
                        new KeyValuePair<string, object>("ProductCode", productCode));


                if (ProductInfo != null)
                {
                    var commandtGetMaxSerial = @"SELECT        COALESCE (MAX(CAST(REPLACE(ProductSerial, '" + ProductInfo[15].Value.ToString() + @"_', '') AS int) + 1), 1) AS Expr1
FROM            tbl_Print
WHERE        (fld_ProductSubGroup = @ProductSubGroup) ";
                    var MaxSerial = dataAccess.SqlDataReaders(commandtGetMaxSerial,
                            new KeyValuePair<string, object>("ProductSubGroup", ProductInfo[15].Value.ToString()));

                    newSerial = ProductInfo[15].Value.ToString() + "_" + MaxSerial[0].Value.ToString().PadLeft(5, '0');
                }
                else
                {
                    newSerial = serial;
                }
            }
            else
                newSerial = serial;
        }
        else if (type.ToLower() == "faradid")
        {
            if (serial.Length < 7)
            {
                var CommandtGetProductData = @" SELECT       CAST(MAX(tbl_Print.ProductSerial) + 1 AS nvarchar(20))  AS Expr1
FROM            tbl_Print RIGHT OUTER JOIN
                         tbl_Products ON tbl_Print.ProductType = tbl_Products.ProductType
WHERE        (tbl_Products.ProductCode = @ProductCode) "
                  ;
                var MaxSerial = dataAccess.SqlDataReaders(CommandtGetProductData,
                        new KeyValuePair<string, object>("ProductCode", productCode));


                newSerial = MaxSerial[0].Value.ToString();

            }
            else

            {
                newSerial = serial;
            }
        }
        return newSerial;
    }

    public string SetImageAndGpsLocationAfterRegisterAndReturnSerial(string ProductCode,
        string ProductSerial,
        string[] ImageFilesName,
        string GpsLocation)
    {
        string WhereKey = "";
        if (ProductCode != "")
        {
            WhereKey += " ProductCode = '" + ProductCode + "' ";
        }

        if(ProductSerial!="")
        {
            WhereKey += ((WhereKey != "") ? " AND " : "") + (" ProductSerial = '" + ProductSerial + "' ");

        }

        var command = "SELECT        TOP (1) ProductSerial FROM tbl_Tags " + ((WhereKey != "") ? " where " + WhereKey : "") + "  ORDER BY Id DESC ";

        var LastSerial = (dataAccess.SqlDataReaders(command)!=null)? dataAccess.SqlDataReaders(command)[0].Value.ToString():"";

        if (LastSerial != "")
        {
            foreach (string FileName in ImageFilesName)
            {
                var cmd = " UPDATE     tbl_Gallery SET            fld_GalleryUsageId ='" + LastSerial + "'   where fld_GalleryMediaName =N'" + FileName + @"' ";
                var resultUpdate = dataAccess.CmdSqlExecuteNonQuery(cmd);
            }

            if (GpsLocation.HasValue())
            {
                var lat = GpsLocation.Split(',')[0];

                var lng = GpsLocation.Split(',')[1];

                string userId = httpContext.User.GetUserId();

                apiContext.GpsLogs.Add(new()
                {
                    UserId = userId,
                    UsageType = (int)GPSLogUsageType.Gallery,
                    Lat = lat,
                    Long = lng,
                    LogDateTime = DateTime.Now,
                    UsageId = ProductSerial,
                    AdditionalData = JsonConvert.SerializeObject(new
                    {
                        ActionTypeTitle = "رجیستر",
                    })
                });

                apiContext.SaveChanges();
            }
        }
        return LastSerial;
         
    }

