    public int SInsertUpdateNotification(Notification notif)
    {
        var command = "";
        bool result;

        if (notif.Id == -1)
        {
            command = @"INSERT INTO [dbo].[tbl_NotificationOrders] (
                                                  [fld_NOStatus]
                                                 ,[fld_NODateTime]
                                                 ,[fld_NOUserId]
                                                 ,[fld_NOType]
                                                 ,[fld_NOTimePeriod]
                                                 ,[fld_NOSendDay]
                                                 ,[fld_NOSendClock]
                                                 ,[fld_NOSendType]
                                                 ,[fld_NOSendContacts]
                                                 ,[fld_NOContent]
                                                 ,[fld_NOTitle]
                                                 ,[fld_NOEventType]) 
                        VALUES (@St,GETDATE(),@Usr,@Tp,@Tm,@Day,@Clock,@STp,@Contacts,@Contents,@Title,@EventTp)";

            result = dataAccess.CmdSqlExecuteNonQuery(command
                , new KeyValuePair<string, object>("St", notif.Status ? 1 : 0)
                , new KeyValuePair<string, object>("Usr", notif.UserId)
                , new KeyValuePair<string, object>("Tp", notif.Type)
                , new KeyValuePair<string, object>("Tm", notif.TimePeriod)
                , new KeyValuePair<string, object>("Day", notif.SendDay)
                , new KeyValuePair<string, object>("Clock", notif.SendClock)
                , new KeyValuePair<string, object>("STp", notif.SendType)
                , new KeyValuePair<string, object>("Contacts", notif.SendContacts)
                , new KeyValuePair<string, object>("Contents", notif.Content)
                , new KeyValuePair<string, object>("Title", notif.Title)
                , new KeyValuePair<string, object>("EventTp", notif.EventType)
                ) > 0;
        }
        else
        {
            command = @"UPDATE [dbo].[tbl_NotificationOrders] SET
                                                  [fld_NOStatus] = @St
                                                 ,[fld_NODateTime] = GETDATE()
                                                 ,[fld_NOUserId] = @Usr
                                                 ,[fld_NOType] = @Tp
                                                 ,[fld_NOTimePeriod] = @Tm
                                                 ,[fld_NOSendDay] = @Day
                                                 ,[fld_NOSendClock] = @Clock
                                                 ,[fld_NOSendType] = @STp
                                                 ,[fld_NOSendContacts] = @Contacts
                                                 ,[fld_NOContent] = @Contents
                                                 ,[fld_NOTitle] = @Title
                                                 ,[fld_NOEventType] = @EventTp 
                        WHERE [Id] = " + notif.Id;

            result = dataAccess.CmdSqlExecuteNonQuery(command
                , new KeyValuePair<string, object>("St", notif.Status ? 1 : 0)
                , new KeyValuePair<string, object>("Usr", notif.UserId)
                , new KeyValuePair<string, object>("Tp", notif.Type)
                , new KeyValuePair<string, object>("Tm", notif.TimePeriod)
                , new KeyValuePair<string, object>("Day", notif.SendDay)
                , new KeyValuePair<string, object>("Clock", notif.SendClock)
                , new KeyValuePair<string, object>("STp", notif.SendType)
                , new KeyValuePair<string, object>("Contacts", notif.SendContacts)
                , new KeyValuePair<string, object>("Contents", notif.Content)
                , new KeyValuePair<string, object>("Title", notif.Title)
                , new KeyValuePair<string, object>("EventTp", notif.EventType)
                ) > 0;
        }

        if (result)
        {
            return int.Parse(GetLatestIdOfIdentityTable("tbl_NotificationOrders"));
        }
        else
        {
            return -1;
        }
    }

    public bool SInsertQueues(List<Queue> queues)
    {
        var childrenCommands = new List<KeyValuePair<string, KeyValuePair<string, object>[]>>();

        foreach (Queue queue in queues)
        {
            var cmd = @"INSERT INTO [dbo].[tbl_NotificationQueue]
           ([fld_Text],[fld_SendType],[fld_Contact],[fld_SendDateTime],[fld_SendDate],[fld_SendTime],[fld_SendStatus],[fld_NotificationOrderId],[fld_QueueActionCode],[fld_SaveDateTime])
            VALUES (@Text ,@SendType , @Contact, @SendDateTime, @SendDate ,@SendTime ,@SendStatus, @OrderId, @ActionCode, GETDATE())";

            var parameters = new List<KeyValuePair<string, object>>();
            parameters.Add(new("Text", queue.Text));
            parameters.Add(new("SendType", queue.SendType));
            parameters.Add(new("Contact", queue.Contact));
            parameters.Add(new("SendDateTime", queue.SendDateTime));
            parameters.Add(new("SendDate", queue.SendDate));
            parameters.Add(new("SendTime", queue.SendTime));
            parameters.Add(new("SendStatus", queue.SendStatus));
            parameters.Add(new("ActionCode", queue.ActionCode));
            parameters.Add(new("OrderId", queue.OrderId));

            childrenCommands.Add(new(cmd, parameters.ToArray()));
        }

        return dataAccess.CmdSqlExecuteNonQueryWithTransaction(childrenCommands) > 0;
    }

    public DataTable SGetQueuesForSend()
    {
        var cmd = @"SELECT [fld_Id] as [Id], [fld_Text] as [Text], [fld_SendType] as [SendType]
      ,[fld_Contact] as [Contact], [fld_SendDateTime] as [SendDateTime], [fld_SendDate] as [SendDate]
