    public bool SSetQueuesStatus(Dictionary<int, int> queueStatus)
    {
        var childrenCommands = new List<KeyValuePair<string, KeyValuePair<string, object>[]>>();

        foreach (KeyValuePair<int, int> item in queueStatus)
        {
            var cildCommand = @"UPDATE [tbl_NotificationQueue] SET [fld_SendStatus] = {item.Value} WHERE [fld_Id] = {item.Key}";
            childrenCommands.Add(new(cildCommand, new List<KeyValuePair<string, object>>().ToArray()));
        }

        return dataAccess.CmdSqlExecuteNonQueryWithTransaction(childrenCommands) > 0;
    }

