    public DataTable SCalAggByEpc(List<string> epcs)
    {
        string serials = epcs.Aggregate(string.Empty, (first, next) =>
        {
            return first + (string.IsNullOrEmpty(next) ? string.Empty : (",N'" + next + "'"));
        }).Remove(0, 1);

        var cmd = $" SELECT  Count(ProductSerial) as [Count], Sum(ProductCount) as [Sum] FROM tbl_Tags WHERE TagEpc IN ({serials})";

        return dataAccess.SqlDataAdapter(cmd);
    }

    public DataTable SGetInStoreProductsByProductCode(List<ReportFilter> reportFilters)
    {
        string[] StartShiftTime = new string[3];
        DataTable shiftList = SPGetShiftStartENDList();
        foreach (DataRow dr in shiftList.Rows)
        {
            string Temp = dr["fld_ProductPropertyBDesc"].ToString().Split('-')[0].Split(':')[0] + dr["fld_ProductPropertyBDesc"].ToString().Split('-')[0].Split(':')[1] + "01";
            StartShiftTime[Convert.ToInt32(dr["fld_ProductPropertyBId"].ToString()) - 1] = Temp;
        }

        if (!reportFilters.Exists(p => p.FieldName.Equals("ProductCode")))
        {
            return null;
        }

        List<string> whereList = new();
        whereList.Add("(p.ProductTitle IS NOT NULL)");

        foreach (ReportFilter filter in reportFilters)
        {
            if (filter.SqlWhereCommand.HasValue())
            {
                continue;
            }

            if (filter.Type.Equals(FilterType.Dynamic))
            {
                filter.SqlWhereCommand = $"JSON_VALUE(t.ProductProperties,N'$.\"{filter.FieldName}\"')";
                whereList.Add(DynamicFilteringTools.GetDynamicWhere(filter));
            }
            else if (filter.Type.Equals(FilterType.Static))
            {
                if (filter.Values != null && filter.Values[0].ToString() != "")
                {
                    switch (filter.FieldName)
                    {
                        case "ProductCode":
                            filter.SqlWhereCommand = "t.ProductCode";
                            break;

                        case "Qc":
                            filter.SqlWhereCommand = "t.ProductStatus";
                            break;

                        case "TechnicalCode":
                            filter.SqlWhereCommand = "t.RegCode";
                            break;

                        case "ProductSerial":
                            filter.SqlWhereCommand = "t.ProductSerial";
                            break;

                        case "FromDate":
                            filter.SqlWhereCommand = "t.TagRegisterShamsiUnixDate";
                            filter.Values = filter.Values.Select(date => $"{(date.Replace("/", "") + StartShiftTime[0])}").ToList();
                            break;

                        case "ToDate":
                            filter.SqlWhereCommand = "t.TagRegisterShamsiUnixDate";
                            filter.Values = filter.Values.Select(date => $"{(date.Replace("/", "") + StartShiftTime[0])}").ToList();
                            break;

                        case "TagZone":
                            filter.SqlWhereCommand = "t.TagZone";
                            break;

                        case "WarehouseCode":
                            filter.SqlWhereCommand = "t.TagInDestinationId";
                            break;

                        case "Line":
                            filter.SqlWhereCommand = "t.fld_ProductPropertyAId";
                            break;

                        case "Shift":
                            filter.SqlWhereCommand = "t.fld_ProductPropertyBId";
                            break;

                        case "AgeRange":
                            switch (filter.Values.First())
                            {
                                case "1":
                                    whereList.Add("(t.TagRegisterDateTime < GETDATE()) AND (t.TagRegisterDateTime >= DATEADD(month, -1, GETDATE()))");
                                    continue;

                                case "2":
                                    whereList.Add("(t.TagRegisterDateTime < DATEADD(month, -1, GETDATE())) AND (t.TagRegisterDateTime >= DATEADD(month, -3, GETDATE()))");
                                    continue;

                                case "3":
                                    whereList.Add("(t.TagRegisterDateTime < DATEADD(month, -3, GETDATE())) AND (t.TagRegisterDateTime >= DATEADD(month, -6, GETDATE()))");
                                    continue;

                                case "4":
                                    whereList.Add("(t.TagRegisterDateTime < DATEADD(month, -6, GETDATE())) AND (t.TagRegisterDateTime >= DATEADD(month, -12, GETDATE()))");
                                    continue;

                                case "5":
                                    whereList.Add("(t.TagRegisterDateTime < DATEADD(month, -12, GETDATE()))");
                                    continue;
                            }
                            break;

                        case "Size":
                            filter.SqlWhereCommand = "p.ProductSize";
                            break;
                    }

                    if (filter.SqlWhereCommand.HasValue())
                    {
                        whereList.Add(DynamicFilteringTools.GetStaticWhere(filter));
                    }
                }
            }
        }

        var sqlCommand = $@"
    WITH LatestMovements AS
    (
        SELECT tm.ProductSerial,
               tm.RTagsMovementDate + '  ' + tm.RTagsMovementTime AS EnterDate,
               ROW_NUMBER() OVER (PARTITION BY tm.ProductSerial ORDER BY tm.RMovementActionId DESC) AS RowNum
        FROM tbl_TagsMovement tm
        WHERE tm.RMovementActionId IS NOT NULL
    ),
    FilteredTags AS
    (
        SELECT t.ProductSerial,
               t.ProductCode,
               t.ProductName,
               t.RegCode,
               t.TagRegisterShamsiUnixDate,
               t.ProductStatus,
               t.ProductCount,
               t.Username,
               t.fld_ProductPropertyAId,
               t.fld_ProductPropertyBId,
               t.TagEpc,
               t.TagZone,
               t.TagInDestinationId,
               t.ProductProperties,
               t.ProductType,
               COALESCE((SELECT tbl_DestinationType.fld_DestinationTypeName FROM tbl_DestinationType WHERE tbl_DestinationType.fld_DestinationTypeCode = t.TagStatus),N'') AS [TagStatus]
        FROM tbl_Tags t
        INNER JOIN tbl_Products p ON t.ProductCode = p.ProductCode
        {(whereList.Any() ? " WHERE " + string.Join(" AND ", whereList) : "")}
    )
    SELECT TOP (10000)
           ft.ProductSerial,
           ft.ProductCode,
           ft.ProductName,
           ft.RegCode,
           ft.TagRegisterShamsiUnixDate AS [Date],
           COALESCE(ps.ProductStatusTitle, N'') AS Qc,
           ft.ProductCount,
           ft.TagRegisterShamsiUnixDate,
           ft.Username,
           COALESCE(pa.fld_ProductPropertyATitle, N'') AS Line,
           COALESCE(pb.fld_ProductPropertyBTitle, N'') AS Shift,
           ft.TagEpc,
           CONCAT(d.DestinationTitle, N' : ', ft.TagZone) AS [Zone],
           COALESCE(ft.ProductProperties, N'{{}}') AS [ProductProperties],
           COALESCE(pt.ProductTypeTitle, N'') AS ProductTypeTitle,
           COALESCE(p.ProductSize, N'') AS ProductSize,
           COALESCE(lm.EnterDate, N'-') AS EnterDate,
           COALESCE(ft.TagStatus, N'') AS TagStatus
    FROM FilteredTags ft
    LEFT JOIN LatestMovements lm 
        ON ft.ProductSerial = lm.ProductSerial 
        AND lm.RowNum = 1
    LEFT JOIN tbl_ProductPropertyA pa 
        ON ft.fld_ProductPropertyAId = pa.fld_ProductPropertyAId
    LEFT JOIN tbl_ProductPropertyB pb 
        ON ft.fld_ProductPropertyBId = pb.fld_ProductPropertyBId
    LEFT JOIN tbl_Products p 
        ON ft.ProductCode = p.ProductCode
    LEFT JOIN tbl_ProductStatus ps 
        ON ft.ProductStatus = ps.ProductStatusCode
    LEFT JOIN tbl_ProductType pt 
        ON ft.ProductType = pt.ProductTypeCode
    LEFT JOIN tbl_Destination d 
        ON ft.TagInDestinationId = d.DestinationCode
    ORDER BY ft.ProductSerial";

        return dataAccess.SqlDataAdapter(sqlCommand);
    }

    public DataTable SInStoreReport(List<ReportFilter> reportFilters)
    {
        string[] StartShiftTime = new string[3];
        DataTable shiftList = SPGetShiftStartENDList();
        foreach (DataRow dr in shiftList.Rows)
        {
            string Temp = dr["fld_ProductPropertyBDesc"].ToString().Split('-')[0].Split(':')[0] + dr["fld_ProductPropertyBDesc"].ToString().Split('-')[0].Split(':')[1] + "01";
            StartShiftTime[Convert.ToInt32(dr["fld_ProductPropertyBId"].ToString()) - 1] = Temp;
        }

        List<string> whereList = new();
        whereList.Add("(p.ProductTitle IS NOT NULL)");

        foreach (ReportFilter filter in reportFilters)
        {
            if (filter.SqlWhereCommand.HasValue())
            {
                continue;
            }

            if (filter.Type.Equals(FilterType.Dynamic))
            {
                filter.SqlWhereCommand = $"JSON_VALUE(t.ProductProperties,N'$.\"{filter.FieldName}\"')";
                whereList.Add(DynamicFilteringTools.GetDynamicWhere(filter));
            }
            else if (filter.Type.Equals(FilterType.Static))
            {
                switch (filter.FieldName)
                {
                    case "ProductCode":
                        filter.SqlWhereCommand = "t.ProductCode";
                        break;

                    case "Qc":
                        filter.SqlWhereCommand = "t.ProductStatus";
                        break;

                    case "TechnicalCode":
                        filter.SqlWhereCommand = "t.RegCode";
                        break;

                    case "ProductSerial":
                        filter.SqlWhereCommand = "t.ProductSerial";
                        break;

                    case "FromDate":
                        filter.SqlWhereCommand = "t.TagRegisterShamsiUnixDate";
                        filter.Values = filter.Values.Select(date => $"{(date.Replace("/", "") + StartShiftTime[0])}").ToList();
                        break;

                    case "ToDate":
                        filter.SqlWhereCommand = "t.TagRegisterShamsiUnixDate";
                        filter.Values = filter.Values.Select(date => $"{(date.Replace("/", "") + StartShiftTime[0])}").ToList();
                        break;

                    case "TagZone":
                        filter.SqlWhereCommand = "t.TagZone";
                        break;

                    case "WarehouseCode":
                        filter.SqlWhereCommand = "t.TagInDestinationId";
                        break;

                    case "Line":
                        filter.SqlWhereCommand = "t.fld_ProductPropertyAId";
                        break;

                    case "Shift":
                        filter.SqlWhereCommand = "t.fld_ProductPropertyBId";
                        break;

                    case "AgeRange":
                        switch (filter.Values.First())
                        {
                            case "1":
                                whereList.Add("(t.TagRegisterDateTime < GETDATE()) AND (t.TagRegisterDateTime >= DATEADD(month, -1, GETDATE()))");
                                continue;

                            case "2":
                                whereList.Add("(t.TagRegisterDateTime < DATEADD(month, -1, GETDATE())) AND (t.TagRegisterDateTime >= DATEADD(month, -3, GETDATE()))");
                                continue;

                            case "3":
                                whereList.Add("(t.TagRegisterDateTime < DATEADD(month, -3, GETDATE())) AND (t.TagRegisterDateTime >= DATEADD(month, -6, GETDATE()))");
                                continue;

                            case "4":
                                whereList.Add("(t.TagRegisterDateTime < DATEADD(month, -6, GETDATE())) AND (t.TagRegisterDateTime >= DATEADD(month, -12, GETDATE()))");
                                continue;

                            case "5":
                                whereList.Add("(t.TagRegisterDateTime < DATEADD(month, -12, GETDATE()))");
                                continue;
                        }
                        break;

                    case "Size":
                        filter.SqlWhereCommand = "t.fld_ProductPropertyCId";
                        break;
                }

                if (filter.SqlWhereCommand.HasValue())
                {
                    whereList.Add(DynamicFilteringTools.GetStaticWhere(filter));
                }
            }
        }

        var sqlCommand = $@"
    WITH FilteredTags AS
    (
        SELECT t.ProductCode,
               t.TagInDestinationId,
               t.RegCode,
               t.ProductStatus,
               t.fld_ProductPropertyCId,
               t.ProductSerial,
               t.ProductCount,
               t.TagZone
        FROM tbl_Tags AS t
        LEFT JOIN tbl_Products p ON t.ProductCode = p.ProductCode
        {(whereList.Any() ? " WHERE " + string.Join(" AND ", whereList) : "")}
    ),
    ZoneAggregation AS
    (
        SELECT ProductCode,
               TagInDestinationId,
               STRING_AGG(TagZone, ' | ') AS ZoneList
        FROM (
            SELECT DISTINCT ProductCode, TagInDestinationId, TagZone
            FROM FilteredTags
        ) AS DistinctZones
        GROUP BY ProductCode, TagInDestinationId
    )
    SELECT ft.ProductCode AS [ProductCode],
           COALESCE(p.ProductTitle, N'') AS [ProductName],
           COALESCE(ft.TagInDestinationId, N'') AS [WarehouseCode],
           COALESCE(ft.RegCode, N'') AS [TechnicalCode],
           COALESCE(ps.ProductStatusTitle, N'') AS [Qc],
           COALESCE(pc.fld_ProductPropertyCTitle, N'') AS [Size],
           COUNT(ft.ProductSerial) AS [Count],
           SUM(ft.ProductCount) AS [SumCount],
           COALESCE(N'انبار: ' + d.DestinationTitle + N'- لوکیشن ها: ' + za.ZoneList, N'') AS ZoneList
    FROM FilteredTags ft
    LEFT JOIN ZoneAggregation za 
        ON ft.ProductCode = za.ProductCode 
        AND ft.TagInDestinationId = za.TagInDestinationId
    LEFT JOIN tbl_Products p 
        ON ft.ProductCode = p.ProductCode
    LEFT JOIN tbl_ProductStatus ps 
        ON ft.ProductStatus = ps.ProductStatusCode
    LEFT JOIN tbl_ProductPropertyC pc 
        ON ft.fld_ProductPropertyCId = pc.fld_ProductPropertyCId
    LEFT JOIN tbl_Destination d 
        ON ft.TagInDestinationId = d.DestinationCode
    GROUP BY ft.ProductCode, 
             p.ProductTitle, 
             ft.RegCode, 
             ps.ProductStatusTitle, 
             p.ProductSize, 
             d.DestinationTitle, 
             ft.TagInDestinationId, 
             pc.fld_ProductPropertyCTitle,
             za.ZoneList
    ORDER BY ft.ProductCode";

        return dataAccess.SqlDataAdapter(sqlCommand, 120);
    }

    public DataTable SInStoreReproductReport(StoreRequest search)
    {
        string[] StartShiftTime = new string[3];
        DataTable shiftList = SPGetShiftStartENDList();
        foreach (DataRow dr in shiftList.Rows)
        {
            string Temp = dr["fld_ProductPropertyBDesc"].ToString().Split('-')[0].Split(':')[0] + dr["fld_ProductPropertyBDesc"].ToString().Split('-')[0].Split(':')[1] + "01";
            StartShiftTime[Convert.ToInt32(dr["fld_ProductPropertyBId"].ToString()) - 1] = Temp;
        }

        string whereKey = " Where Tags.ReProduct = 1 ";
        string whereKeySubQuery = " Where (ProductCode = Tags.ProductCode) AND ReProduct = 1";


        if (!search.ProductCode.Equals("-1"))
        {
            whereKey += " AND (Tags.ProductCode=N'" + search.ProductCode + "')  ";
            whereKeySubQuery += " AND (ProductCode=N'" + search.ProductCode + "')  ";
        }
        if (!search.ProductStatus.Equals("-1"))
        {
            whereKey += " AND (Tags.ProductStatus=N'" + search.ProductStatus + "') ";
            whereKeySubQuery += " AND (ProductStatus=N'" + search.ProductStatus + "')";
        }
        if (!search.ProductSerial.Equals("-1"))
        {
            whereKey += " AND (Tags.ProductSerial=N'" + search.ProductSerial + "')  ";
            whereKeySubQuery += " AND (ProductSerial=N'" + search.ProductSerial + "') ";
        }

        if (!search.FromDate.Equals("-1"))
        {
            whereKey += " AND (Tags.TagRegisterShamsiUnixDate >= '" + search.FromDate + StartShiftTime[0] + "') ";
            whereKeySubQuery += " AND (TagRegisterShamsiUnixDate >= '" + search.FromDate + StartShiftTime[0] + "') ";
        }
        if (!search.ToDate.Equals("-1"))
        {

            whereKey += " AND (Tags.TagRegisterShamsiUnixDate <= '" + search.ToDate + StartShiftTime[0] + "') ";
            whereKeySubQuery += " AND (TagRegisterShamsiUnixDate <= '" + search.ToDate + StartShiftTime[0] + "')  ";
        }
        if (!search.TagZone.Equals("-1"))
        {

            if (!search.TagZoneLike)
            {
                whereKey += " AND (Tags.TagZone=N'" + search.TagZone + "')  ";
                whereKeySubQuery += " AND (TagZone=N'" + search.TagZone + "') ";
            }
            else
            {
                whereKey += " AND (Tags.TagZone Like N'" + search.TagZone + "%') ";
                whereKeySubQuery += " AND (TagZone Like N'" + search.TagZone + "%')  ";

            }
        }

        if (!search.TechnicalCode.Equals("-1"))
        {
            if (!search.TechnicalCodeLike)
            {
                whereKey += " AND (Tags.RegCode = N'" + search.TechnicalCode + "')  ";
                whereKeySubQuery += " AND (RegCode = N'" + search.TechnicalCode + "') ";
            }
            else
            {
                whereKey += " AND (Tags.RegCode Like N'" + search.TechnicalCode + "%')  ";
                whereKeySubQuery += " AND (RegCode Like N'" + search.TechnicalCode + "%')  ";

            }
        }


        if (!search.AgeRange.Equals("-1"))
        {
            switch (search.AgeRange)
            {
                case "1":
                    whereKey += @" AND (TagRegisterDateTime < GETDATE()) AND (TagRegisterDateTime >= DATEADD(month, -1, GETDATE()))  ";
                    whereKeySubQuery += @" AND (TagRegisterDateTime < GETDATE()) AND (TagRegisterDateTime >= DATEADD(month, -1, GETDATE()))  ";
                    break;
                case "2":
                    whereKey += @" AND (TagRegisterDateTime < DATEADD(month, -1, GETDATE())) AND (TagRegisterDateTime >= DATEADD(month, -3, GETDATE()))  ";
                    whereKeySubQuery += @" AND (TagRegisterDateTime < DATEADD(month, -1, GETDATE())) AND (TagRegisterDateTime >= DATEADD(month, -3, GETDATE()))  ";
                    break;
                case "3":
                    whereKey += @" AND (TagRegisterDateTime < DATEADD(month, -3, GETDATE())) AND (TagRegisterDateTime >= DATEADD(month, -6, GETDATE())) ";
                    whereKeySubQuery += @" AND (TagRegisterDateTime < DATEADD(month, -3, GETDATE())) AND (TagRegisterDateTime >= DATEADD(month, -6, GETDATE())) ";
                    break;
                case "4":
                    whereKey += @" AND (TagRegisterDateTime  < DATEADD(month, -6, GETDATE())) AND (TagRegisterDateTime >= DATEADD(month, -12, GETDATE()))  ";
                    whereKeySubQuery += @" AND (TagRegisterDateTime < DATEADD(month, -6, GETDATE())) AND (TagRegisterDateTime >= DATEADD(month, -12, GETDATE()))  ";
                    break;

                case "5":
                    whereKey += @" AND (TagRegisterDateTime < DATEADD(month, -12, GETDATE())) ";
                    whereKeySubQuery += @" AND (TagRegisterDateTime < DATEADD(month, -12, GETDATE())) ";
                    break;
            }
        }

        //   if (search.EnterStatus != "-1")
        //  {
        //     whereKey += $" AND Tags.TagStatus = {search.EnterStatus}";
        //    whereKeySubQuery += $" AND TagStatus = {search.EnterStatus} ";
        // }

        var sqlCommand = @"
                         SELECT        
                         CASE WHEN Tags.TagStatus = 0 THEN N'انبارهای تولید' WHEN Tags.TagStatus = 1 THEN N'داخل انبار' WHEN Tags.TagStatus = 2 THEN N'انبارهای بارگیری' ELSE N'-' END AS EnterStatus,
                         Tags.ProductCode as [ProductCode],
                         tbl_Products.ProductTitle as [ProductName],
                         Tags.RegCode as [TechnicalCode],
                         tbl_ProductStatus.ProductStatusTitle as [Qc],
                         tbl_Products.ProductSize as [Size],
                         COUNT(Tags.ProductSerial) AS [Count],
                         SUM(Tags.ProductCount) AS [SumCount],
                         COALESCE(( SELECT 
                         STRING_AGG( TagZone, ' | ') WITHIN GROUP (ORDER BY  TagZone) AS NewField from (
                         select distinct  ProductCode,tbl_Tags_1.TagZone FROM [dbo].[tbl_Tags]   AS tbl_Tags_1 " + whereKeySubQuery + @") x GROUP BY  ProductCode),'0') AS ZoneList                           FROM tbl_Tags AS Tags LEFT OUTER JOIN
                         tbl_ProductPropertyA ON Tags.fld_ProductPropertyAId = tbl_ProductPropertyA.fld_ProductPropertyAId LEFT OUTER JOIN
                         tbl_ProductPropertyB ON Tags.fld_ProductPropertyBId = tbl_ProductPropertyB.fld_ProductPropertyBId LEFT OUTER JOIN
                         tbl_Products ON Tags.ProductCode = tbl_Products.ProductCode LEFT OUTER JOIN
                         tbl_ProductStatus ON Tags.ProductStatus = tbl_ProductStatus.ProductStatusCode LEFT OUTER JOIN
                         tbl_ProductType ON Tags.ProductType = tbl_ProductType.ProductTypeCode " +

                (whereKey != string.Empty ? whereKey : "") +
                " GROUP BY Tags.TagStatus,Tags.ProductCode, tbl_Products.ProductTitle, Tags.RegCode, tbl_ProductStatus.ProductStatusTitle , tbl_Products.ProductSize";

        return dataAccess.SqlDataAdapter(sqlCommand);
    }

    public DataTable SGetReproductsByProductCode(StoreRequest search)
    {
        string[] StartShiftTime = new string[3];
        DataTable shiftList = SPGetShiftStartENDList();
        foreach (DataRow dr in shiftList.Rows)
