                         tbl_ProductType ON Tags.ProductType = tbl_ProductType.ProductTypeCode
                        "
                        + (whereKey != string.Empty ? whereKey : "") +
                        " ORDER BY Tags.ProductSerial  "
        ;

        return dataAccess.SqlDataAdapter(sqlCommand);
    }

