    public bool AddUserClaims(string userId, List<Claim> claims, string userToken)
    {
        var commands = new List<string>();

        if (!claims.Any())
        {
            return false;
        }

        commands.Add($@"DELETE FROM tbl_UserClaim WHERE UserId = N'{userId}' AND ClaimType = N'{claims.First().Type}' ");

        foreach (Claim claim in claims)
        {
            commands.Add($@"INSERT tbl_UserClaim (UserId,ClaimType,ClaimValue) VALUES (N'{userId}',N'{claim.Type}',N'{claim.Value}')");
        }

        return dataAccess.CmdSqlExecuteNonQueryWithTransaction(commands) > 0;
    }

    public bool UpdateUserData(UpdateUserCommand command)
    {
        command.LastModifier = httpContext.User.GetUserId();

        string commandString = string.Empty;

        var parameters = new List<KeyValuePair<string, object>>();

        if (command.Password.HasValue())
        {
            commandString = @$"UPDATE [dbo].[tbl_User] SET [LastModifiedDate] = GETDATE(),[IsActive]= @IsActiv,[LastModifierIdentityID] = @LstUsrId,[UserName] = @Usrnam ,
                 [PasswordHash] = @PssHsh, [SecurityStamp] = @SecStmp  , [Name] = @PrsiaNam , Details = @Dtl , Image = @Img WHERE [Id] = @Id";

            parameters.Add(new("Id", command.Id));
            parameters.Add(new("IsActiv", command.IsActive));
            parameters.Add(new("LstUsrId", command.LastModifier));
            parameters.Add(new("PrsiaNam", command.PersianName));
            parameters.Add(new("PssHsh", CryptoTools.GetHashedStringSha256StringBuilder(command.Password)));
            parameters.Add(new("SecStmp", Guid.NewGuid().ToString()));
            parameters.Add(new("Usrnam", command.Username));
            parameters.Add(new("Dtl", command.Details));
            parameters.Add(new("Img", command.Image));
        }
        else
        {
            commandString = @$"UPDATE [dbo].[tbl_User] SET [LastModifiedDate] = GETDATE(),[IsActive]= @IsActiv,[LastModifierIdentityID] = @LstUsrId,[UserName] = @Usrnam , [SecurityStamp] = @SecStmp  , [Name] = @PrsiaNam , Details = @Dtl , Image = @Img WHERE [Id] = @Id";

            parameters.Add(new("Id", command.Id));
            parameters.Add(new("IsActiv", command.IsActive));
            parameters.Add(new("LstUsrId", command.LastModifier));
            parameters.Add(new("PrsiaNam", command.PersianName));
            parameters.Add(new("SecStmp", Guid.NewGuid().ToString()));
            parameters.Add(new("Usrnam", command.Username));
            parameters.Add(new("Dtl", command.Details));
            parameters.Add(new("Img", command.Image));
        }

        if (dataAccess.CmdSqlExecuteNonQuery(commandString, parameters.ToArray()) > 0)
        {
            string commandRole =
                """
                 DELETE FROM tbl_UserRole WHERE UserId = @UserId
                 
                 INSERT INTO tbl_UserRole (UserId,RoleId) VALUES (@UserId,@RoleId)
                """;

            if (sqlDataAccess.CmdSqlExecuteNonQuery(commandRole
                , new KeyValuePair<string, object>("UserId", command.Id)
                , new("RoleId", command.Role)) > 0)
            {
                return true;
            }
        }

        return false;
    }

    public DataTable SReportEnter(EnterRequest search)
    {
        string[] startShiftTime = new string[3];
        DataTable shiftList = SPGetShiftStartENDList();
        foreach (DataRow dr in shiftList.Rows)
        {
            string temp = dr["fld_ProductPropertyBDesc"].ToString().Split('-')[0];
            startShiftTime[Convert.ToInt32(dr["fld_ProductPropertyBId"].ToString()) - 1] = temp;
        }

        var whereConditions = new List<string>
    {
        "tbl_TagsMovement.ProductCode IS NOT NULL",
        "tbl_Products.ProductTitle IS NOT NULL"
    };

        var whereConditionsSubQuery = new List<string>
    {
        "tbl_TagsMovement_1.ProductCode = tbl_TagsMovement.ProductCode",
        "tbl_MovementActions_1.MovementActionTp = tbl_MovementActions.MovementActionTp",
        "tbl_MovementActions_1.MovementActionDestinationId = tbl_MovementActions.MovementActionDestinationId"
    };

        if (!search.ProductCode.Equals("-1"))
        {
            whereConditions.Add($"tbl_TagsMovement.ProductCode = N'{search.ProductCode}'");
            whereConditionsSubQuery.Add($"tbl_TagsMovement_1.ProductCode = N'{search.ProductCode}'");
        }

        if (!search.FromDate.Equals("-1"))
        {
            whereConditions.Add($"tbl_MovementActions.MovementActionDateTime >= dbo.JalaliDateToGeorgianDate(N'{search.FromDate}', N'{startShiftTime[0]}')");
            whereConditionsSubQuery.Add($"tbl_MovementActions_1.MovementActionDateTime >= dbo.JalaliDateToGeorgianDate(N'{search.FromDate}', N'{startShiftTime[0]}')");
        }

        if (!search.ToDate.Equals("-1"))
        {
            whereConditions.Add($"tbl_MovementActions.MovementActionDateTime <= dbo.JalaliDateToGeorgianDate(N'{search.ToDate}', N'{startShiftTime[0]}')");
            whereConditionsSubQuery.Add($"tbl_MovementActions_1.MovementActionDateTime <= dbo.JalaliDateToGeorgianDate(N'{search.ToDate}', N'{startShiftTime[0]}')");
        }

        if (!search.ProductSerial.Equals("-1"))
        {
            whereConditions.Add($"tbl_TagsMovement.ProductSerial = N'{search.ProductSerial}'");
            whereConditionsSubQuery.Add($"tbl_TagsMovement_1.ProductSerial = N'{search.ProductSerial}'");
        }

        if (!search.Qc.Equals("-1"))
        {
            whereConditions.Add($"tbl_Products.ProductStatus = N'{search.Qc}'");
            whereConditionsSubQuery.Add($"tbl_Products_1.ProductStatus = N'{search.Qc}'");
        }

        if (!search.Size.Equals("-1"))
        {
            whereConditions.Add($"tbl_Products.ProductSize = N'{search.Size}'");
            whereConditionsSubQuery.Add($"tbl_Products_1.ProductSize = N'{search.Size}'");
        }

        if (!search.TechnicalCode.Equals("-1"))
        {
            if (!search.TechnicalCodeLike)
            {
                whereConditions.Add($"tbl_Products.ProductTechnicalCode = N'{search.TechnicalCode}'");
                whereConditionsSubQuery.Add($"tbl_Products_1.ProductTechnicalCode = N'{search.TechnicalCode}'");
            }
            else
            {
                whereConditions.Add($"tbl_Products.ProductTechnicalCode LIKE N'%{search.TechnicalCode}%'");
                whereConditionsSubQuery.Add($"tbl_Products_1.ProductTechnicalCode LIKE N'%{search.TechnicalCode}%'");
            }
        }

        if (!search.DestinationCode.Equals("-1"))
        {
            whereConditions.Add($"tbl_MovementActions.MovementActionDestinationId = N'{search.DestinationCode}'");
            whereConditionsSubQuery.Add($"tbl_MovementActions_1.MovementActionDestinationId = N'{search.DestinationCode}'");
        }

        if (!search.ProductGroup.Equals("-1"))
        {
            whereConditions.Add($"tbl_Products.fld_ProductGroup = N'{search.ProductGroup}'");
            whereConditionsSubQuery.Add($"tbl_Products_1.fld_ProductGroup = N'{search.ProductGroup}'");
        }

        if (!search.ProductBrand.Equals("-1"))
        {
            whereConditions.Add($"tbl_Products.fld_ProductBrand = N'{search.ProductBrand}'");
            whereConditionsSubQuery.Add($"tbl_Products_1.fld_ProductBrand = N'{search.ProductBrand}'");
        }

        if (!search.ProductType.Equals("-1"))
        {
            whereConditions.Add($"tbl_Products.ProductType = N'{search.ProductType}'");
            whereConditionsSubQuery.Add($"tbl_Products_1.ProductType = N'{search.ProductType}'");
        }

        if (!search.GateCode.Equals("-1"))
        {
            whereConditions.Add($"tbl_UHF_ReaderLog.fld_Reader_Gate = N'{search.GateCode}'");
            whereConditionsSubQuery.Add($"tbl_UHF_ReaderLog_1.fld_Reader_Gate = N'{search.GateCode}'");
        }

        if (search.ActionType is not null)
        {
            whereConditions.Add($"tbl_MovementActions.MovementActionTp = {search.ActionType}");
            whereConditionsSubQuery.Add($"tbl_MovementActions_1.MovementActionTp = {search.ActionType}");
        }

        var whereString = "WHERE " + string.Join(" AND ", whereConditions);
        var whereStringSubQuery = "WHERE " + string.Join(" AND ", whereConditionsSubQuery);

        var cmd = $"""
        WITH FilteredMovements AS
        (
            SELECT DISTINCT tbl_TagsMovement.ProductSerial,
                   tbl_TagsMovement.ProductCode,
                   tbl_Products.ProductTitle,
                   tbl_Products.ProductTechnicalCode,
                   tbl_Products.ProductSize,
                   tbl_Products.ProductStatus,
                   tbl_ProductBrand.fld_ProductBrandTitle,
                   tbl_ProductGroup.fld_ProductGroupTitle,
                   tbl_ProductType.ProductTypeTitle,
                   tbl_MovementActions.MovementActionTp,
                   tbl_MovementActions.MovementActionDestinationId,
                   tbl_Destination.DestinationTitle,
                   tbl_Destination_1.DestinationTitle AS StoreTitle,
                   tbl_ActionTypes.fld_ActionTypeTitle
            FROM tbl_ActionTypes
            RIGHT OUTER JOIN tbl_MovementActions 
                ON tbl_ActionTypes.fld_ActionTypeId = tbl_MovementActions.MovementActionTp
            LEFT OUTER JOIN tbl_Destination AS tbl_Destination_1 
                ON tbl_MovementActions.MovementActionStore = tbl_Destination_1.DestinationCode
            LEFT OUTER JOIN tbl_Destination 
                ON tbl_MovementActions.MovementActionDestinationId = tbl_Destination.DestinationCode
            RIGHT OUTER JOIN tbl_TagsMovement 
            LEFT OUTER JOIN tbl_Products 
                ON tbl_TagsMovement.ProductCode = tbl_Products.ProductCode
            LEFT OUTER JOIN tbl_ProductType 
                ON tbl_Products.ProductType = tbl_ProductType.ProductTypeCode
                ON tbl_MovementActions.MovementActionId = tbl_TagsMovement.RMovementActionId
            LEFT OUTER JOIN tbl_UHF_ReaderLog 
                ON tbl_MovementActions.MovementActionUHFLogId LIKE N'%,' + CAST(tbl_UHF_ReaderLog.fld_InventoryId AS NVARCHAR(10)) + N',%'
            LEFT OUTER JOIN tbl_ProductBrand 
                ON tbl_Products.fld_ProductBrand = tbl_ProductBrand.fld_ProductBrandCode
            LEFT OUTER JOIN tbl_ProductGroup 
                ON tbl_Products.fld_ProductGroup = tbl_ProductGroup.fld_ProductGroupCode
            {whereString}
        ),
        ProductCounts AS
        (
            SELECT fm.ProductSerial,
                   COALESCE(t.ProductCount, 0) AS ProductCount
            FROM FilteredMovements fm
            LEFT JOIN tbl_Tags t ON fm.ProductSerial = t.ProductSerial
        )
        SELECT COALESCE(fm.ProductCode, N'') AS ProductCode,
               COALESCE(fm.ProductTechnicalCode, N'') AS RegCode,
               COALESCE(fm.ProductTitle, N'') AS ProductName,
               COALESCE(fm.ProductSize, N'') AS Size,
               COALESCE(fm.ProductStatus, N'') AS Qc,
               COUNT(DISTINCT fm.ProductSerial) AS Count,
               COALESCE(SUM(pc.ProductCount), 0) AS SumCount,
               COALESCE(fm.fld_ProductBrandTitle, N'') AS ProductBrand,
               COALESCE(fm.fld_ProductGroupTitle, N'') AS ProductGroup,
               COALESCE(fm.ProductTypeTitle, N'') AS ProductType,
               COALESCE(fm.MovementActionTp, 0) AS ActionType,
               COALESCE(CAST(fm.MovementActionDestinationId AS NVARCHAR(250)), N'') AS DestinationCode,
               COALESCE(fm.DestinationTitle, N'') AS DestinationTitle,
               COALESCE(fm.StoreTitle, N'') AS StoreTitle,
               COALESCE(fm.fld_ActionTypeTitle, N'') AS ActionTypeTitle
        FROM FilteredMovements fm
        LEFT JOIN ProductCounts pc ON fm.ProductSerial = pc.ProductSerial
        GROUP BY fm.ProductCode, fm.ProductTitle, fm.ProductTechnicalCode, fm.ProductSize,
                 fm.ProductStatus, fm.fld_ProductBrandTitle, fm.fld_ProductGroupTitle,
                 fm.ProductTypeTitle, fm.MovementActionTp, fm.MovementActionDestinationId,
                 fm.DestinationTitle, fm.StoreTitle, fm.fld_ActionTypeTitle
        ORDER BY fm.ProductCode DESC
        """;

        return dataAccess.SqlDataAdapter(cmd);
    }

    public DataTable SReportEnterProductList(EnterRequest search)
    {
        string[] StartShiftTime = new string[3];
        DataTable shiftList = SPGetShiftStartENDList();
        foreach (DataRow dr in shiftList.Rows)
        {
            string Temp = dr["fld_ProductPropertyBDesc"].ToString().Split('-')[0];
            StartShiftTime[Convert.ToInt32(dr["fld_ProductPropertyBId"].ToString()) - 1] = Temp;
        }

        var whereString = "";

        if (!search.ProductName.Equals("-1"))
        {
            whereString += string.IsNullOrEmpty(whereString) ? "" : " AND ";
            whereString += $" tbl_Products.ProductTitle LIKE N'%{search.ProductName}%' ";
        }
        if (!search.ProductCode.Equals("-1"))
        {
            whereString += string.IsNullOrEmpty(whereString) ? "" : " AND ";
            whereString += $" tbl_TagsMovement.ProductCode = N'{search.ProductCode}' ";
        }
        if (!search.FromDate.Equals("-1"))
        {
            whereString += string.IsNullOrEmpty(whereString) ? "" : " AND ";
            whereString += $" tbl_TagsMovement.RTagsMovementDateTime >=  dbo.JalaliDateToGeorgianDate(N'{search.FromDate}',N'{StartShiftTime[0]}') ";
        }
        if (!search.ToDate.Equals("-1"))
        {
            whereString += string.IsNullOrEmpty(whereString) ? "" : " AND ";
            whereString += $" (tbl_TagsMovement.RTagsMovementDateTime <= dbo.JalaliDateToGeorgianDate(N'{search.ToDate}',N'{StartShiftTime[0]}')) ";
        }

        if (!search.TechnicalCode.Equals("-1"))
        {
            whereString += string.IsNullOrEmpty(whereString) ? "" : " AND ";
            whereString += $" Tags.RegCode = N'{search.TechnicalCode}' ";
        }

        if (!search.Shift.Equals("-1"))
        {
            switch (search.Shift)
            {
                case "1":
                    whereString += string.IsNullOrEmpty(whereString) ? "" : " AND ";

                    whereString += " (tbl_TagsMovement.RTagsMovementTime >= '" + StartShiftTime[0] + "')  AND  (tbl_TagsMovement.RTagsMovementTime < '" + StartShiftTime[1] + "')   ";

                    break;
                case "2":
                    whereString += string.IsNullOrEmpty(whereString) ? "" : " AND ";

                    whereString += " (tbl_TagsMovement.RTagsMovementTime >= '" + StartShiftTime[1] + "')  AND  (tbl_TagsMovement.RTagsMovementTime < '" + StartShiftTime[2] + "')   ";

                    break;
                case "3":
                    whereString += string.IsNullOrEmpty(whereString) ? "" : " AND ";

                    whereString += " (( (tbl_TagsMovement.RTagsMovementTime >= '" + StartShiftTime[2] + "')  AND (tbl_TagsMovement.RTagsMovementTime < '24:00') ) OR ( (tbl_TagsMovement.RTagsMovementTime >= '00:00' ) and (tbl_TagsMovement.RTagsMovementTime < '" + StartShiftTime[0] + "' )))   ";

                    break;

            }
        }



        var dtProducts = new DataTable();
        dtProducts.Columns.Add("RMovementActionId", typeof(string));
        dtProducts.Columns.Add("RTagsMovementDate", typeof(string));
        dtProducts.Columns.Add("RTagsMovementTime", typeof(string));
        dtProducts.Columns.Add("MovementData", typeof(string));
        dtProducts.Columns.Add("ProductSerial", typeof(string));
        dtProducts.Columns.Add("ProductCode", typeof(string));
        dtProducts.Columns.Add("ProductName", typeof(string));
        dtProducts.Columns.Add("RegCode", typeof(string));
        dtProducts.Columns.Add("ProductStatusTitle", typeof(string));
        dtProducts.Columns.Add("ProductCount", typeof(string));
        dtProducts.Columns.Add("TagRegisterShamsiUnixDate", typeof(string));
        dtProducts.Columns.Add("Username", typeof(string));
        dtProducts.Columns.Add("fld_ProductPropertyATitle", typeof(string));
        dtProducts.Columns.Add("fld_ProductPropertyBTitle", typeof(string));
        dtProducts.Columns.Add("TagEpc", typeof(string));
        dtProducts.Columns.Add("TagZone", typeof(string));
        dtProducts.Columns.Add("ProductProperties", typeof(string));
        dtProducts.Columns.Add("ProductTypeTitle", typeof(string));
        dtProducts.Columns.Add("ProductSize", typeof(string));
        dtProducts.Columns.Add("HMovementActionId", typeof(string));
        dtProducts.Columns.Add("HTagsMovementDate", typeof(string));
        dtProducts.Columns.Add("HTagsMovementTime", typeof(string));
        dtProducts.Columns.Add("MovementActionData", typeof(string));


        if (whereString != "")
            whereString = " where " + whereString;

        var cmd = $@" 
                         SELECT        TOP (6000) tbl_TagsMovement.RMovementActionId, tbl_TagsMovement.RTagsMovementDate, tbl_TagsMovement.RTagsMovementTime, COALESCE (tbl_TagsMovement.MovementData, N' ') AS MovementData, 
                         Tags.ProductSerial, Tags.ProductCode, Tags.ProductName, Tags.RegCode, tbl_ProductStatus.ProductStatusTitle, Tags.ProductCount, Tags.TagRegisterShamsiUnixDate, Tags.Username, 
                         tbl_ProductPropertyA.fld_ProductPropertyATitle, tbl_ProductPropertyB.fld_ProductPropertyBTitle, Tags.TagEpc, COALESCE (Tags.TagZone, N'0') AS TagZone, Tags.ProductProperties, 
                         COALESCE (tbl_ProductType.ProductTypeTitle, N'0') AS ProductTypeTitle, tbl_Products.ProductSize, tbl_TagsMovement.HMovementActionId, tbl_TagsMovement.HTagsMovementDate, tbl_TagsMovement.HTagsMovementTime, 
                         COALESCE ((SELECT        MovementActionData FROM            tbl_MovementActions
                         WHERE        (MovementActionId = tbl_TagsMovement.HMovementActionId) AND (MovementActionTp = 6)), N'') AS MovementActionData
                         FROM   tbl_TagsMovement LEFT OUTER JOIN
                         tbl_Tags AS Tags ON tbl_TagsMovement.TagEpc = Tags.TagEpc AND tbl_TagsMovement.ProductSerial = Tags.ProductSerial LEFT OUTER JOIN
                         tbl_ProductPropertyA ON Tags.fld_ProductPropertyAId = tbl_ProductPropertyA.fld_ProductPropertyAId LEFT OUTER JOIN
                         tbl_ProductPropertyB ON Tags.fld_ProductPropertyBId = tbl_ProductPropertyB.fld_ProductPropertyBId LEFT OUTER JOIN
                         tbl_Products ON Tags.ProductCode = tbl_Products.ProductCode LEFT OUTER JOIN
                         tbl_ProductStatus ON Tags.ProductStatus = tbl_ProductStatus.ProductStatusCode LEFT OUTER JOIN
                         tbl_ProductType ON Tags.ProductType = tbl_ProductType.ProductTypeCode
                        {whereString}
                         ";


        dtProducts = dataAccess.SqlDataAdapter(cmd);
        return dtProducts;
    }

    public DataTable SReportEnterProductsByProductCode(EnterRequest search)
    {
        string[] startShiftTime = new string[3];
        DataTable shiftList = SPGetShiftStartENDList();
        foreach (DataRow dr in shiftList.Rows)
        {
            string temp = dr["fld_ProductPropertyBDesc"].ToString().Split('-')[0];
            startShiftTime[Convert.ToInt32(dr["fld_ProductPropertyBId"].ToString()) - 1] = temp;
        }

        var whereConditions = new List<string>
        {
            "tbl_TagsMovement.ProductCode IS NOT NULL",
            "tbl_Products.ProductTitle IS NOT NULL"
        };

        if (!search.ProductCode.Equals("-1"))
        {
            whereConditions.Add($"tbl_TagsMovement.ProductCode = N'{search.ProductCode}'");
        }

        if (!search.FromDate.Equals("-1"))
        {
            whereConditions.Add($"tbl_MovementActions.MovementActionDateTime >= dbo.JalaliDateToGeorgianDate(N'{search.FromDate}', N'{startShiftTime[0]}')");
        }

        if (!search.ToDate.Equals("-1"))
        {
            whereConditions.Add($"tbl_MovementActions.MovementActionDateTime <= dbo.JalaliDateToGeorgianDate(N'{search.ToDate}', N'{startShiftTime[0]}')");
        }

        if (!search.ProductSerial.Equals("-1"))
        {
            whereConditions.Add($"tbl_TagsMovement.ProductSerial = N'{search.ProductSerial}'");
        }

        if (!search.Qc.Equals("-1"))
        {
            whereConditions.Add($"tbl_Products.ProductStatus = N'{search.Qc}'");
        }

        if (!search.Size.Equals("-1"))
        {
            whereConditions.Add($"tbl_Products.ProductSize = N'{search.Size}'");
        }

        if (!search.TechnicalCode.Equals("-1"))
        {
            if (!search.TechnicalCodeLike)
            {
                whereConditions.Add($"tbl_Products.ProductTechnicalCode = N'{search.TechnicalCode}'");
            }
            else
            {
                whereConditions.Add($"tbl_Products.ProductTechnicalCode LIKE N'%{search.TechnicalCode}%'");
            }
        }

        if (!search.ProductBrand.Equals("-1"))
        {
            whereConditions.Add($"tbl_Products.fld_ProductBrand = N'{search.ProductBrand}'");
        }

        if (!search.ProductGroup.Equals("-1"))
        {
            whereConditions.Add($"tbl_Products.fld_ProductGroup = N'{search.ProductGroup}'");
        }

        if (!search.ProductType.Equals("-1"))
        {
            whereConditions.Add($"tbl_Products.ProductType = N'{search.ProductType}'");
        }

        if (!search.GateCode.Equals("-1"))
        {
            whereConditions.Add($"tbl_UHF_ReaderLog.fld_Reader_Gate = N'{search.GateCode}'");
        }

        if (search.ActionType is not null)
        {
            whereConditions.Add($"tbl_MovementActions.MovementActionTp = {search.ActionType}");
        }

        if (!search.DestinationCode.Equals("-1"))
        {
            whereConditions.Add($"tbl_MovementActions.MovementActionDestinationId = N'{search.DestinationCode}'");
        }

        var whereString = "WHERE " + string.Join(" AND ", whereConditions);

        var cmd = $@"
        SELECT DISTINCT TOP (6000)
               tbl_TagsMovement.RMovementActionId,
               tbl_TagsMovement.RTagsMovementDate + ' - ' + tbl_TagsMovement.RTagsMovementTime AS EnterDateTime,
               tbl_TagsMovement.ProductSerial,
               tbl_TagsMovement.ProductCode,
               tbl_Products.ProductTitle AS ProductName,
               COALESCE(tbl_Products.ProductTechnicalCode, N'') AS TechnicalCode,
               tbl_ProductStatus.ProductStatusTitle AS Qc,
               COALESCE(Tags.ProductCount, 0) AS ProductCount,
               COALESCE(tbl_ProductPropertyA.fld_ProductPropertyATitle, N'') AS Line,
               COALESCE(tbl_ProductPropertyB.fld_ProductPropertyBTitle, N'') AS Shift,
               COALESCE(tbl_ProductType.ProductTypeTitle, N'') AS ProductType,
               tbl_Products.ProductSize AS Size,
               COALESCE(Tags.TagRegisterShamsiUnixDate, N'') AS RegisterDateTime,
               COALESCE((SELECT tbl_DestinationType.fld_DestinationTypeName FROM tbl_DestinationType WHERE tbl_DestinationType.fld_DestinationTypeCode = Tags.TagStatus),N'') AS [TagStatus],
               COALESCE(tbl_UHF_ReaderLog.fld_Reader_Gate, N'') AS GateCode,
               COALESCE(tbl_ProductBrand.fld_ProductBrandTitle, N'') AS ProductBrand,
               COALESCE(tbl_ProductGroup.fld_ProductGroupTitle, N'') AS ProductGroup,
               COALESCE((SELECT tbl_Station.fld_StationName 
                         FROM tbl_Station 
                         WHERE tbl_Station.fld_StationCode = tbl_UHF_ReaderLog.fld_Reader_Gate), N'') AS StationName,
               COALESCE((SELECT tbl_User.[Name] 
                         FROM tbl_User 
                         WHERE (TRY_CONVERT(uniqueidentifier, tbl_MovementActions.MovementActionUserId) IS NOT NULL AND tbl_User.Id = tbl_MovementActions.MovementActionUserId) OR
                         (tbl_User.Username = tbl_MovementActions.MovementActionUserId)
                         ), N'') AS Username,
               COALESCE(tbl_MovementActions.MovementActionData,N'{{}}') AS [ActionData]
        FROM tbl_ActionTypes
        RIGHT OUTER JOIN tbl_MovementActions 
            ON tbl_ActionTypes.fld_ActionTypeId = tbl_MovementActions.MovementActionTp
        RIGHT OUTER JOIN tbl_TagsMovement
        LEFT OUTER JOIN tbl_Products 
            ON tbl_TagsMovement.ProductCode = tbl_Products.ProductCode
        LEFT OUTER JOIN tbl_ProductType 
            ON tbl_Products.ProductType = tbl_ProductType.ProductTypeCode
        LEFT OUTER JOIN tbl_ProductStatus 
            ON tbl_Products.ProductStatus = tbl_ProductStatus.ProductStatusCode
            ON tbl_MovementActions.MovementActionId = tbl_TagsMovement.RMovementActionId
        LEFT OUTER JOIN tbl_UHF_ReaderLog 
            ON tbl_MovementActions.MovementActionUHFLogId LIKE N'%,' + CAST(tbl_UHF_ReaderLog.fld_InventoryId AS NVARCHAR(10)) + N',%'
        LEFT OUTER JOIN tbl_ProductBrand 
            ON tbl_Products.fld_ProductBrand = tbl_ProductBrand.fld_ProductBrandCode
        LEFT OUTER JOIN tbl_ProductGroup 
            ON tbl_Products.fld_ProductGroup = tbl_ProductGroup.fld_ProductGroupCode
        LEFT OUTER JOIN tbl_Tags AS Tags 
            ON tbl_TagsMovement.ProductSerial = Tags.ProductSerial
        LEFT OUTER JOIN tbl_ProductPropertyA 
            ON Tags.fld_ProductPropertyAId = tbl_ProductPropertyA.fld_ProductPropertyAId
        LEFT OUTER JOIN tbl_ProductPropertyB 
            ON Tags.fld_ProductPropertyBId = tbl_ProductPropertyB.fld_ProductPropertyBId
        {whereString}
        ORDER BY tbl_TagsMovement.RMovementActionId DESC, tbl_TagsMovement.ProductSerial
        ";


        return dataAccess.SqlDataAdapter(cmd);
    }

    public DataTable SReportExitActionByOpCode(List<ReportFilter> reportFilters)
    {
        string userId = httpContext.User.GetUserId();
        List<string> whereList = new();

        foreach (ReportFilter filter in reportFilters)
        {
            if (filter.SqlWhereCommand.HasValue())
            {
                continue;
            }

            if (filter.Type.Equals(FilterType.Dynamic))
            {
                if (filter.AdditionalData["DynamicFilterActionType"] == "1")
                {
                    whereList.Add(
                        $"""
                        JSON_VALUE(Tags.ProductProperties,N'$."{filter.FieldName}"') IN(N'{string.Join("',N'", filter.Values)}')
                        """);
                }
                else
                {
                    filter.SqlWhereCommand = $"JSON_VALUE(tbl_MovementActions.MovementActionData,N'$.\"{filter.FieldName}\"')";

                    whereList.Add(DynamicFilteringTools.GetDynamicWhere(filter));
                }
            }
            else if (filter.Type.Equals(FilterType.TechnicalInfo))
            {
                filter.SqlWhereCommand = $"JSON_VALUE(tbl_Products.ProductTechnicalData,N'$.\"{filter.FieldName}\"')";

                whereList.Add(DynamicFilteringTools.GetTechnicalInfoWhere(filter));
            }
            else if (filter.Type.Equals(FilterType.Static))
            {
                switch (filter.FieldName)
                {
                    case "OperationCode":
                        filter.SqlWhereCommand = "tbl_TagsMovement.RMovementActionId";
                        break;

                    case "ProductCode":
                        filter.SqlWhereCommand = "tbl_TagsMovement.ProductCode";
                        break;

                    case "TechnicalCode":
                        filter.SqlWhereCommand = "tbl_Products.ProductTechnicalCode";
                        break;

                    case "FromDate":
                        filter.SqlWhereCommand = "tbl_MovementActions.MovementActionDateTime";
                        filter.Values = filter.Values.Select(date => $"dbo.JalaliDateToGeorgianDate(N'{date}', N'06:00')").ToList();
                        break;

                    case "ToDate":
                        filter.SqlWhereCommand = "tbl_MovementActions.MovementActionDateTime";
                        filter.Values = filter.Values.Select(date => $"dbo.JalaliDateToGeorgianDate(N'{date}', N'06:00')").ToList();
                        break;

                    case "GateOpCode":
                        filter.SqlWhereCommand = "tbl_MovementActions.MovementActionUHFLogId";
                        break;

                    case "StoreCode":
                        filter.SqlWhereCommand = "tbl_MovementActions.MovementActionStore";
                        break;

                    case "Size":
                        filter.SqlWhereCommand = "tbl_Products.ProductSize";
                        break;

                    case "ProductGroup":
                        filter.SqlWhereCommand = "tbl_Products.fld_ProductGroup";
                        break;

                    case "ProductBrand":
                        filter.SqlWhereCommand = "tbl_Products.fld_ProductBrand";
                        break;

                    case "ProductType":
                        filter.SqlWhereCommand = "tbl_Products.ProductType";
                        break;

                    case "Line":
                        filter.SqlWhereCommand = "Tags.fld_ProductPropertyAId";
                        break;

                    case "Shift":
                        filter.SqlWhereCommand = "Tags.fld_ProductPropertyBId";
                        break;

                    case "GateCode":
                        filter.SqlWhereCommand = "tbl_MovementActions.MovementActionUHFLogGate";
                        break;

                    case "ActionType":
                        filter.SqlWhereCommand = "tbl_MovementActions.MovementActionTp";
                        break;

                    case "DocumentKey":
                        filter.SqlWhereCommand = "tbl_MovementActions.MovementActionDocumentId";
                        break;

                    case "TruckType":
                        filter.SqlWhereCommand = "TruckCross_1.fld_TruckCrossType";
                        break;

                    case "CarPlaque":
                        filter.SqlWhereCommand = "TruckCross_1.fld_TruckCrossPlaque";
                        break;

                    case "NationalCode":
                        filter.SqlWhereCommand = "TruckCross_1.fld_TruckCrossNationalCode";
                        break;

                    case "DriverName":
                        filter.SqlWhereCommand = "TruckCross_1.fld_TruckCrossDriverName";
                        break;

                    case "TruckCrossCause":
                        filter.SqlWhereCommand = "TruckCross_1.fld_TruckCrossPresentCause";
                        break;

                    case "TruckCrossOperationType":
                        filter.SqlWhereCommand = "TruckCross_1.fld_TruckCrossPresentOperationType";
                        break;

                    case "TruckCrossShipment":
                        filter.SqlWhereCommand = "TruckCross_1.fld_TruckCrossPresentShipment";
                        break;

                    case "TruckCrossOperationDestination":
                        filter.SqlWhereCommand = "TruckCross_1.fld_TruckCrossPresentOperationDestination";
                        break;

                }

                if (filter.SqlWhereCommand.HasValue())
                {
                    whereList.Add(DynamicFilteringTools.GetStaticWhere(filter));
                }
            }
        }

        var dtProducts = new DataTable();
        var cmd = $@" 
                         SELECT        TOP (6000) tbl_TagsMovement.ProductSerial, 
                         tbl_TagsMovement.ProductCode, tbl_Products.ProductTitle AS ProductName,
                         COALESCE( Tags.RegCode ,N'') AS TechnicalCode,
                         tbl_ProductStatus.ProductStatusTitle AS Qc, 
                         COALESCE(Tags.ProductCount,0) AS ProductCount, tbl_Products.ProductSize AS Size, 
                         COALESCE (tbl_ProductBrand.fld_ProductBrandTitle, N'') AS ProductBrand,
                         COALESCE (tbl_ProductGroup.fld_ProductGroupTitle, N'') AS ProductGroup, 
                         COALESCE (tbl_ProductType.ProductTypeTitle, N'') AS ProductType,
					  	 COALESCE (tbl_MovementActions.MovementActionUHFLogGate, N'') AS GateCode,
				 		 COALESCE(tbl_Products.ProductTechnicalData ,N'') AS TechnicalInfoData,
                         COALESCE((SELECT tbl_Station.fld_StationName FROM tbl_Station 
                         WHERE tbl_Station.fld_StationCode = tbl_MovementActions.MovementActionUHFLogGate),N'') AS StationName,
                         CASE WHEN Guarantee.fld_ProductGuaranteeStatus = 0 THEN N'شروع نشده' 
                         	WHEN Guarantee.fld_ProductGuaranteeStatus = 1 THEN N'فعال' 
                         	WHEN Guarantee.fld_ProductGuaranteeStatus = 2 THEN N'اتمام یافته' 
                         	ELSE N'' END AS GuaranteeStatus,
                         COALESCE(Guarantee.fld_ProductGuaranteeStartDate,N'') AS GuaranteeStartDate,
	                     COALESCE(Guarantee.fld_ProductGuaranteeEndDate,N'') AS GuaranteeEndDate,
                         COALESCE(Tags.ProductProperties,'{{}}') AS ProductProperties,
                         COALESCE(tbl_MovementActions.MovementActionData,'{{}}') AS MovementActionData,
                         (SELECT COALESCE(tbl_ProductPropertyA.fld_ProductPropertyATitle,N'') FROM tbl_ProductPropertyA 
                         WHERE tbl_ProductPropertyA.fld_ProductPropertyAId = Tags.fld_ProductPropertyAId) AS Line,
                         (SELECT COALESCE(tbl_ProductPropertyB.fld_ProductPropertyBTitle,N'') FROM tbl_ProductPropertyB 
                         WHERE tbl_ProductPropertyB.fld_ProductPropertyBId = Tags.fld_ProductPropertyBId) AS Shift
                         FROM    tbl_Tags AS Tags RIGHT OUTER JOIN
                                 tbl_MovementActions LEFT OUTER JOIN
                                 tbl_ProductStatus LEFT OUTER JOIN
                                 tbl_TagsMovement LEFT OUTER JOIN
                                 tbl_Products ON tbl_TagsMovement.ProductCode = tbl_Products.ProductCode ON tbl_ProductStatus.ProductStatusCode = tbl_Products.ProductStatus RIGHT OUTER JOIN
                                 tbl_ProductType ON tbl_Products.ProductType = tbl_ProductType.ProductTypeCode LEFT OUTER JOIN
                                 tbl_ProductBrand ON tbl_Products.fld_ProductBrand = tbl_ProductBrand.fld_ProductBrandCode LEFT OUTER JOIN
                                 tbl_ProductGroup ON tbl_Products.fld_ProductGroup = tbl_ProductGroup.fld_ProductGroupCode ON tbl_MovementActions.MovementActionId = tbl_TagsMovement.RMovementActionId ON 
                                 Tags.ProductSerial = tbl_TagsMovement.ProductSerial  LEFT OUTER JOIN
				                 tbl_TruckCross AS TruckCross_1 ON tbl_MovementActions.MovementActionTruckCrossId = TruckCross_1.fld_TruckCrossId 
                                 LEFT JOIN tbl_ProductGuarantee AS Guarantee  ON Tags.ProductSerial = Guarantee.fld_ProductGuaranteeProductSerial 
                         {(whereList.Any() ? " WHERE " + string.Join(" AND ", whereList) : "")}
                         ";

        dtProducts = dataAccess.SqlDataAdapter(cmd);
        return dtProducts;
    }

    public DataTable SReportExitProductList(EnterRequest search)
    {
        var whereString = " WHERE        (Tags.TagStatus <> 0) AND (tbl_TagsMovement.HTagsMovementSt = 1) AND (tbl_TagsMovement.RTagsMovementSt = 1) and    (MovementActionTp = 6) AND (MovementActionData NOT LIKE N'%برگشت کالا%') ";

        if (!search.TechnicalCode.Equals("-1"))
        {
            whereString += string.IsNullOrEmpty(whereString) ? "" : " AND ";
            whereString += $" tbl_Products.ProductTechnicalCode = N'{search.TechnicalCode}' ";
        }
        if (!search.ProductCode.Equals("-1"))
        {
            whereString += string.IsNullOrEmpty(whereString) ? "" : " AND ";
            whereString += $" tbl_TagsMovement.ProductCode = N'{search.ProductCode}' ";
        }
        if (!search.FromDate.Equals("-1"))
        {
            whereString += string.IsNullOrEmpty(whereString) ? "" : " AND ";
            whereString += $" tbl_MovementActions.MovementActionDate >= N'{search.FromDate}' ";
        }
        if (!search.ToDate.Equals("-1"))
        {
            whereString += string.IsNullOrEmpty(whereString) ? "" : " AND ";
            whereString += $" tbl_MovementActions.MovementActionDate <= N'{search.ToDate}' ";
        }

        if (!search.FromTime.Equals("-1"))
        {
            whereString += string.IsNullOrEmpty(whereString) ? "" : " AND ";
            whereString += $" tbl_MovementActions.MovementActionCarPlaque Like N'%{search.FromTime}%' ";
        }
        if (!search.ToTime.Equals("-1"))
        {
            whereString += string.IsNullOrEmpty(whereString) ? "" : " AND ";
            whereString += $" tbl_MovementActions.MovementActionData Like N'%{search.ToTime}%' ";
        }
        if (!search.ProductName.Equals("-1"))
        {
            whereString += string.IsNullOrEmpty(whereString) ? "" : " AND ";
            whereString += $" tbl_MovementActions.MovementActionUHFLogId = {search.ProductName} ";
        }
        if (!search.ProductSerial.Equals("-1"))
        {
            whereString += string.IsNullOrEmpty(whereString) ? "" : " AND ";
            whereString += $" tbl_MovementActions.MovementActionDriverName Like N'%{search.ProductSerial}%' ";
        }
        var dtProducts = new DataTable();
        dtProducts.Columns.Add("HMovementActionId", typeof(string));
        dtProducts.Columns.Add("HTagsMovementDate", typeof(string));
        dtProducts.Columns.Add("HTagsMovementTime", typeof(string));
        dtProducts.Columns.Add("MovementData", typeof(string));
        dtProducts.Columns.Add("ProductSerial", typeof(string));
        dtProducts.Columns.Add("ProductCode", typeof(string));
        dtProducts.Columns.Add("ProductName", typeof(string));
        dtProducts.Columns.Add("RegCode", typeof(string));
        dtProducts.Columns.Add("ProductStatusTitle", typeof(string));
        dtProducts.Columns.Add("ProductCount", typeof(string));
        dtProducts.Columns.Add("TagRegisterShamsiUnixDate", typeof(string));
        dtProducts.Columns.Add("Username", typeof(string));
        dtProducts.Columns.Add("fld_ProductPropertyATitle", typeof(string));
        dtProducts.Columns.Add("fld_ProductPropertyBTitle", typeof(string));
        dtProducts.Columns.Add("TagEpc", typeof(string));
        dtProducts.Columns.Add("TagZone", typeof(string));
        dtProducts.Columns.Add("ProductProperties", typeof(string));
        dtProducts.Columns.Add("ProductTypeTitle", typeof(string));
        dtProducts.Columns.Add("ProductSize", typeof(string));
        dtProducts.Columns.Add("MovementActionCarPlaque", typeof(string));
        dtProducts.Columns.Add("MovementActionDriverName", typeof(string));

        var cmd = $@"SELECT        TOP (7000) tbl_MovementActions.MovementActionId AS HMovementActionId, tbl_MovementActions.MovementActionDate AS HTagsMovementDate, tbl_MovementActions.MovementActionTime AS HTagsMovementTime, 
                         COALESCE (tbl_MovementActions.MovementActionData, N' ') AS MovementData, Tags.ProductSerial, Tags.ProductCode, Tags.ProductName, Tags.RegCode, tbl_ProductStatus.ProductStatusTitle, Tags.ProductCount, 
                         Tags.TagRegisterShamsiUnixDate, Tags.Username, tbl_ProductPropertyA.fld_ProductPropertyATitle, tbl_ProductPropertyB.fld_ProductPropertyBTitle, Tags.TagEpc, Tags.TagZone, Tags.ProductProperties, 
                         tbl_ProductType.ProductTypeTitle, tbl_Products.ProductSize, tbl_MovementActions.MovementActionId, tbl_MovementActions.MovementActionCarPlaque, tbl_MovementActions.MovementActionDriverName
FROM            tbl_MovementActions LEFT OUTER JOIN
                         tbl_TagsMovement ON tbl_MovementActions.MovementActionId = tbl_TagsMovement.HMovementActionId LEFT OUTER JOIN
                         tbl_Tags AS Tags LEFT OUTER JOIN
                         tbl_ProductPropertyB ON Tags.fld_ProductPropertyBId = tbl_ProductPropertyB.fld_ProductPropertyBId LEFT OUTER JOIN
                         tbl_ProductPropertyA ON Tags.fld_ProductPropertyAId = tbl_ProductPropertyA.fld_ProductPropertyAId ON tbl_TagsMovement.ProductSerial = Tags.ProductSerial LEFT OUTER JOIN
                         tbl_Products ON Tags.ProductCode = tbl_Products.ProductCode LEFT OUTER JOIN
                         tbl_ProductStatus ON Tags.ProductStatus = tbl_ProductStatus.ProductStatusCode LEFT OUTER JOIN
                         tbl_ProductType ON Tags.ProductType = tbl_ProductType.ProductTypeCode
                        {whereString}
                         ";

        dtProducts = dataAccess.SqlDataAdapter(cmd);
        return dtProducts;
    }

    public DataTable SReportExit(EnterRequest search)
    {
        var whereString = " WHERE        (Tags.TagStatus <> 0) AND (tbl_TagsMovement.HTagsMovementSt = 1) AND (tbl_TagsMovement.RTagsMovementSt = 1) and    (MovementActionTp = 6) AND (MovementActionData NOT LIKE N'%برگشت کالا%') ";
        if (!search.ProductName.Equals("-1"))
        {
            whereString += string.IsNullOrEmpty(whereString) ? "" : " AND ";
            whereString += $" tbl_Products.ProductTitle LIKE N'%{search.ProductName}%' ";
        }
        if (!search.TechnicalCode.Equals("-1"))
        {
            whereString += string.IsNullOrEmpty(whereString) ? "" : " AND ";
            whereString += $" tbl_Products.ProductTechnicalCode = N'{search.TechnicalCode}' ";
        }
        if (!search.ProductCode.Equals("-1"))
        {
            whereString += string.IsNullOrEmpty(whereString) ? "" : " AND ";
            whereString += $" tbl_TagsMovement.ProductCode = N'{search.ProductCode}' ";
        }
        if (!search.FromDate.Equals("-1"))
        {
            whereString += string.IsNullOrEmpty(whereString) ? "" : " AND ";
            whereString += $" tbl_MovementActions.MovementActionDate >= N'{search.FromDate}' ";
        }
        if (!search.ToDate.Equals("-1"))
        {
            whereString += string.IsNullOrEmpty(whereString) ? "" : " AND ";
            whereString += $" tbl_MovementActions.MovementActionDate <= N'{search.ToDate}' ";
        }

        var dtProducts = new DataTable();

        var cmd = $@"SELECT        TOP (5000) 
                                        tbl_MovementActions.MovementActionId AS OpCode, 
                                        tbl_MovementActions.MovementActionDate +' - '+tbl_MovementActions.MovementActionTime AS DateTime, 
                                        COALESCE (tbl_MovementActions.MovementActionData, N' ') AS MovementData, 
                                        Tags.ProductSerial, 
                                        Tags.ProductCode, 
                                        Tags.ProductName, 
                                        Tags.RegCode, 
                                        tbl_ProductStatus.ProductStatusTitle, 
                                        Tags.ProductCount as [Count], 
                                        Tags.TagRegisterShamsiUnixDate, 
                                        Tags.Username as [User], 
                                        tbl_ProductPropertyA.fld_ProductPropertyATitle, 
                                        tbl_ProductPropertyB.fld_ProductPropertyBTitle, 
                                        Tags.TagEpc, Tags.TagZone, Tags.ProductProperties, 
                                        tbl_ProductType.ProductTypeTitle, 
                                        tbl_Products.ProductSize, 
                                        COALESCE(tbl_MovementActions.MovementActionCarPlaque,N'') as [Plaque], 
                                        COALESCE(tbl_MovementActions.MovementActionDriverName,N'') as [Driver],
                                        COALESCE(tbl_MovementActions.MovementActionDriverMobile,N'') as [Phone]
                                        FROM tbl_MovementActions LEFT OUTER JOIN
                                        tbl_TagsMovement ON tbl_MovementActions.MovementActionId = tbl_TagsMovement.HMovementActionId LEFT OUTER JOIN
                                        tbl_Tags AS Tags LEFT OUTER JOIN
                                        tbl_ProductPropertyB ON Tags.fld_ProductPropertyBId = tbl_ProductPropertyB.fld_ProductPropertyBId LEFT OUTER JOIN
                                        tbl_ProductPropertyA ON Tags.fld_ProductPropertyAId = tbl_ProductPropertyA.fld_ProductPropertyAId ON tbl_TagsMovement.ProductSerial = Tags.ProductSerial LEFT OUTER JOIN
                                        tbl_Products ON Tags.ProductCode = tbl_Products.ProductCode LEFT OUTER JOIN
                                        tbl_ProductStatus ON Tags.ProductStatus = tbl_ProductStatus.ProductStatusCode LEFT OUTER JOIN
                                        tbl_ProductType ON Tags.ProductType = tbl_ProductType.ProductTypeCode
                        {whereString}
                         ";


        dtProducts = dataAccess.SqlDataAdapter(cmd);
        return dtProducts;
    }

    public DataTable SReportExitActionFull(List<ReportFilter> reportFilters)
    {
        List<string> whereList = new();
        whereList.Add("tbl_TagsMovement.ProductCode IS NOT NULL");

        foreach (ReportFilter filter in reportFilters)
        {
            if (filter.SqlWhereCommand.HasValue())
            {
                continue;
            }

            if (filter.Type.Equals(FilterType.Dynamic))
            {
                if (filter.AdditionalData["DynamicFilterActionType"] == "1")
                {
                    whereList.Add(
                        $"""
                    (JSON_VALUE(Tags.ProductProperties,N'$."{filter.FieldName}"') IN(N'{string.Join("',N'", filter.Values)}'))
                    """);
                }
                else
                {
                    filter.SqlWhereCommand = $"JSON_VALUE(tbl_MovementActions.MovementActionData,N'$.\"{filter.FieldName}\"')";

                    whereList.Add(DynamicFilteringTools.GetDynamicWhere(filter));
                }
            }
            else if (filter.Type.Equals(FilterType.TechnicalInfo))
            {
                filter.SqlWhereCommand = $"JSON_VALUE(tbl_Products.ProductTechnicalData,N'$.\"{filter.FieldName}\"')";

                whereList.Add(DynamicFilteringTools.GetTechnicalInfoWhere(filter));
            }
            else if (filter.Type.Equals(FilterType.Static))
            {
                switch (filter.FieldName)
                {
                    case "OperationCode":
                        filter.SqlWhereCommand = "MovementActionId";
                        break;

                    case "ProductCode":
                        filter.SqlWhereCommand = "tbl_TagsMovement.ProductCode";
                        break;

                    case "TechnicalCode":
                        filter.SqlWhereCommand = "tbl_Products.ProductTechnicalCode";
                        break;

                    case "FromDate":
                        filter.SqlWhereCommand = "tbl_MovementActions.MovementActionDateTime";
                        filter.Values = filter.Values.Select(date => $"dbo.JalaliDateToGeorgianDate(N'{date}', N'06:00')").ToList();
                        break;

                    case "ToDate":
                        filter.SqlWhereCommand = "tbl_MovementActions.MovementActionDateTime";
                        filter.Values = filter.Values.Select(date => $"dbo.JalaliDateToGeorgianDate(N'{date}', N'06:00')").ToList();
                        break;

                    case "GateOpCode":
                        filter.SqlWhereCommand = "MovementActionUHFLogId";
                        break;

                    case "StoreCode":
                        filter.SqlWhereCommand = "tbl_MovementActions.MovementActionStore";
                        break;

                    case "Size":
                        filter.SqlWhereCommand = "tbl_Products.ProductSize";
                        break;

                    case "ProductGroup":
                        filter.SqlWhereCommand = "tbl_Products.fld_ProductGroup";
                        break;

                    case "ProductBrand":
                        filter.SqlWhereCommand = "tbl_Products.fld_ProductBrand";
                        break;

                    case "ProductType":
                        filter.SqlWhereCommand = "tbl_Products.ProductType";
                        break;

                    case "Line":
                        filter.SqlWhereCommand = "Tags.fld_ProductPropertyAId";
                        break;

                    case "Shift":
                        filter.SqlWhereCommand = "Tags.fld_ProductPropertyBId";
                        break;

                    case "GateCode":
                        filter.SqlWhereCommand = "tbl_MovementActions.MovementActionUHFLogGate";
                        break;

                    case "ActionType":
                        filter.SqlWhereCommand = "tbl_MovementActions.MovementActionTp";
                        break;

                    case "DocumentKey":
                        filter.SqlWhereCommand = "tbl_MovementActions.MovementActionDocumentId";
                        break;

                    case "TruckType":
                        filter.SqlWhereCommand = "TruckCross_1.fld_TruckCrossType";
                        break;

                    case "CarPlaque":
                        filter.SqlWhereCommand = "TruckCross_1.fld_TruckCrossPlaque";
                        break;

                    case "NationalCode":
                        filter.SqlWhereCommand = "TruckCross_1.fld_TruckCrossNationalCode";
                        break;

                    case "DriverName":
                        filter.SqlWhereCommand = "TruckCross_1.fld_TruckCrossDriverName";
                        break;

                    case "TruckCrossCause":
                        filter.SqlWhereCommand = "TruckCross_1.fld_TruckCrossPresentCause";
                        break;

                    case "TruckCrossOperationType":
                        filter.SqlWhereCommand = "TruckCross_1.fld_TruckCrossPresentOperationType";
                        break;

                    case "TruckCrossShipment":
                        filter.SqlWhereCommand = "TruckCross_1.fld_TruckCrossPresentShipment";
                        break;

                    case "TruckCrossOperationDestination":
                        filter.SqlWhereCommand = "TruckCross_1.fld_TruckCrossPresentOperationDestination";
                        break;
                }

                if (filter.SqlWhereCommand.HasValue())
                {
                    whereList.Add(DynamicFilteringTools.GetStaticWhere(filter));
                }
            }
        }

        var dtProducts = new DataTable();

        var cmd = """
            SELECT TOP (150000)
            CAST(tbl_MovementActions.MovementActionId AS nvarchar(250)) AS OpCode,
            tbl_MovementActions.MovementActionDate + ' - ' + tbl_MovementActions.MovementActionTime AS DateTime,
            ISNULL(CAST(tbl_TagsMovement.ProductSerial AS NVARCHAR(100)), N'') AS ProductSerial,
            ISNULL(CAST(tbl_TagsMovement.ProductCode AS nvarchar(100)), N'') AS ProductCode,
            ISNULL(tbl_Products.ProductTitle, N'') AS ProductName,
            ISNULL(tbl_ProductPropertyC.fld_ProductPropertyCTitle, N'') AS Size,
            ISNULL(tbl_Products.ProductTechnicalCode, N'') AS TechnicalCode,
            ISNULL(tbl_ProductStatus.ProductStatusTitle, N'') AS Qc,
            ISNULL(Tags.ProductCount, 0) AS Count,
            ISNULL(tbl_ProductPropertyA.fld_ProductPropertyATitle, N'') AS Line,
            ISNULL(tbl_ProductPropertyB.fld_ProductPropertyBTitle, N'') AS Shift,
            ISNULL(tbl_ProductGroup.fld_ProductGroupTitle, N'') AS ProductGroup,
            ISNULL(tbl_ProductBrand.fld_ProductBrandTitle, N'') AS ProductBrand,
            ISNULL(tbl_ProductType.ProductTypeTitle, N'') AS ProductType,
            ISNULL(tbl_MovementActions.MovementActionUHFLogGate, N'') AS GateCode,
            ISNULL(tbl_MovementActions.MovementActionDocumentId, N'') AS ActionDocumentId,
            ISNULL(CAST(tbl_MovementActions.MovementActionStore AS nvarchar(250)), N'') AS StoreCode,
            ISNULL(tbl_MovementActions.MovementActionTp, 0) AS ActionType,
            ISNULL(tbl_ActionTypes.fld_ActionTypeTitle, N'') AS ActionTypeTitle,
            ISNULL(tbl_Destination.DestinationTitle, N'') AS DestinationTitle,
            ISNULL(tbl_Destination_1.DestinationTitle, N'') AS StoreTitle,
            ISNULL(tbl_Products.ProductTechnicalData, N'') AS TechnicalInfoData,
            ISNULL(tbl_MovementActions.MovementActionDesc, N'') AS MovementActionDesc,
            ISNULL(Tags.DeviceIp, N'') AS DeviceIp,
            ISNULL(Tags.ContractStatus, N'') AS ContractStatus,
            ISNULL(tbl_Station.fld_StationName, N'') AS StationName,
            ISNULL(Tags.ProductProperties, '{}') AS ProductProperties,
            ISNULL(tbl_TagsMovement.MovementData, '{}') AS MovementProperties,
            COALESCE((SELECT tbl_User.[Name] 
                                     FROM tbl_User 
                                     WHERE (TRY_CONVERT(uniqueidentifier, tbl_MovementActions.MovementActionUserId) IS NOT NULL AND tbl_User.Id = tbl_MovementActions.MovementActionUserId) OR
                                     (tbl_User.Username = tbl_MovementActions.MovementActionUserId)
                                     ), (SELECT tbl_Station.fld_StationName FROM tbl_Station WHERE tbl_Station.fld_StationCode = tbl_MovementActions.MovementActionUHFLogGate),N'') AS Username,
            ISNULL(tbl_MovementActions.MovementActionData, '{}') AS MovementActionData
            FROM tbl_MovementActions
            INNER JOIN tbl_TagsMovement ON tbl_MovementActions.MovementActionId = tbl_TagsMovement.RMovementActionId
            LEFT OUTER JOIN tbl_Tags AS Tags ON tbl_TagsMovement.ProductSerial = Tags.ProductSerial
            LEFT OUTER JOIN tbl_Products ON tbl_TagsMovement.ProductCode = tbl_Products.ProductCode
            LEFT OUTER JOIN tbl_ActionTypes ON tbl_MovementActions.MovementActionTp = tbl_ActionTypes.fld_ActionTypeId
            LEFT OUTER JOIN tbl_Destination ON tbl_MovementActions.MovementActionStore = tbl_Destination.DestinationCode
            LEFT OUTER JOIN tbl_Destination AS tbl_Destination_1 ON tbl_MovementActions.MovementActionDestinationId = tbl_Destination_1.DestinationCode
            LEFT OUTER JOIN tbl_ProductPropertyA ON Tags.fld_ProductPropertyAId = tbl_ProductPropertyA.fld_ProductPropertyAId
            LEFT OUTER JOIN tbl_ProductPropertyB ON Tags.fld_ProductPropertyBId = tbl_ProductPropertyB.fld_ProductPropertyBId
            LEFT OUTER JOIN tbl_ProductPropertyC ON tbl_Products.ProductSize = tbl_ProductPropertyC.fld_ProductPropertyCId
            LEFT OUTER JOIN tbl_ProductStatus ON tbl_Products.ProductStatus = tbl_ProductStatus.ProductStatusCode
            LEFT OUTER JOIN tbl_ProductType ON tbl_Products.ProductType = tbl_ProductType.ProductTypeCode
            LEFT OUTER JOIN tbl_ProductGroup ON tbl_Products.fld_ProductGroup = tbl_ProductGroup.fld_ProductGroupCode
            LEFT OUTER JOIN tbl_ProductBrand ON tbl_Products.fld_ProductBrand = tbl_ProductBrand.fld_ProductBrandCode
            LEFT OUTER JOIN tbl_TruckCross AS TruckCross_1 ON tbl_MovementActions.MovementActionTruckCrossId = TruckCross_1.fld_TruckCrossId
            LEFT OUTER JOIN tbl_Station ON tbl_MovementActions.MovementActionUHFLogGate = tbl_Station.fld_StationCode
            """ +
        (whereList.Any() ? " WHERE " + string.Join(" AND ", whereList) : "") +
        " ORDER BY tbl_MovementActions.MovementActionDateTime DESC";

        dtProducts = dataAccess.SqlDataAdapter(cmd, 120);

        return dtProducts;
    }

    public DataTable SReportExitActions(List<ReportFilter> reportFilters)
    {
        string userId = httpContext.User.GetUserId();

        var recordCount = "TOP(5000)";

        List<string> whereList = new();

        List<string> subWhereList = new();

        foreach (ReportFilter filter in reportFilters)
        {
            string subQueryWhereCommand = string.Empty;

            if (filter.SqlWhereCommand.HasValue())
            {
                continue;
            }

            if (filter.Type.Equals(FilterType.Dynamic))
            {
                if (filter.AdditionalData["DynamicFilterActionType"] == "1")
                {
                    whereList.Add(
                        $"""
                    (tbl_TagsMovement_1.ProductSerial 
                    IN(SELECT ProductSerial
                    FROM tbl_Tags AS Tags
                    WHERE tbl_TagsMovement_1.ProductSerial = Tags.ProductSerial
                    AND JSON_VALUE(Tags.ProductProperties,N'$."{filter.FieldName}"') IN(N'{string.Join("',N'", filter.Values)}')))
                    """);

                    subWhereList.Add(
                        $"""
                    (tbl_TagsMovement_3.ProductSerial 
                    IN(SELECT ProductSerial
                    FROM tbl_Tags AS Tags_3
                    WHERE tbl_TagsMovement_3.ProductSerial = Tags_3.ProductSerial
                    AND JSON_VALUE(Tags_3.ProductProperties,N'$."{filter.FieldName}"') IN(N'{string.Join("',N'", filter.Values)}')))
                    """);
                }
                else
                {
                    filter.SqlWhereCommand = $"JSON_VALUE(tbl_MovementActions.MovementActionData,N'$.\"{filter.FieldName}\"')";

                    subQueryWhereCommand = $"JSON_VALUE(tbl_MovementActions_3.MovementActionData,N'$.\"{filter.FieldName}\"')";

                    whereList.Add(DynamicFilteringTools.GetDynamicWhere(filter));

                    subWhereList.Add(DynamicFilteringTools.GetDynamicWhere(filter).Replace(filter.SqlWhereCommand, subQueryWhereCommand));
                }
            }
            else if (filter.Type.Equals(FilterType.TechnicalInfo))
            {
                filter.SqlWhereCommand = $"JSON_VALUE(tbl_Products.ProductTechnicalData,N'$.\"{filter.FieldName}\"')";

                subQueryWhereCommand = $"JSON_VALUE(tbl_Products_3.ProductTechnicalData,N'$.\"{filter.FieldName}\"')";

                whereList.Add(DynamicFilteringTools.GetTechnicalInfoWhere(filter));

                subWhereList.Add(DynamicFilteringTools.GetTechnicalInfoWhere(filter).Replace(filter.SqlWhereCommand, subQueryWhereCommand));
            }
            else if (filter.Type.Equals(FilterType.Static))
            {
                switch (filter.FieldName)
                {
                    case "OperationCode":
