                        break;

                    case "DocumentKey":
                        filter.SqlWhereCommand = "tbl_MovementActions.MovementActionDocumentId";
                        subQueryWhereCommand = "tbl_MovementActions_3.MovementActionDocumentId";
                        break;

                    case "RecordsCount":
                        recordCount = $@"TOP({filter.Value})";
                        break;

                    case "TruckType":
                        filter.SqlWhereCommand = "TruckCross_1.fld_TruckCrossType";
                        subQueryWhereCommand = "TruckCross_3.fld_TruckCrossType";
                        break;

                    case "CarPlaque":
                        filter.SqlWhereCommand = "TruckCross_1.fld_TruckCrossPlaque";
                        subQueryWhereCommand = "TruckCross_3.fld_TruckCrossPlaque";
                        break;

                    case "NationalCode":
                        filter.SqlWhereCommand = "TruckCross_1.fld_TruckCrossNationalCode";
                        subQueryWhereCommand = "TruckCross_3.fld_TruckCrossNationalCode";
                        break;

                    case "DriverName":
                        filter.SqlWhereCommand = "TruckCross_1.fld_TruckCrossDriverName";
                        subQueryWhereCommand = "TruckCross_3.fld_TruckCrossDriverName";
                        break;

                    case "TruckCrossCause":
                        filter.SqlWhereCommand = "TruckCross_1.fld_TruckCrossPresentCause";
                        subQueryWhereCommand = "TruckCross_3.fld_TruckCrossPresentCause";
                        break;

                    case "TruckCrossOperationType":
                        filter.SqlWhereCommand = "TruckCross_1.fld_TruckCrossPresentOperationType";
                        subQueryWhereCommand = "TruckCross_3.fld_TruckCrossPresentOperationType";
                        break;

                    case "TruckCrossShipment":
                        filter.SqlWhereCommand = "TruckCross_1.fld_TruckCrossPresentShipment";
                        subQueryWhereCommand = "TruckCross_3.fld_TruckCrossPresentShipment";
                        break;

                    case "TruckCrossOperationDestination":
                        filter.SqlWhereCommand = "TruckCross_1.fld_TruckCrossPresentOperationDestination";
                        subQueryWhereCommand = "TruckCross_3.fld_TruckCrossPresentOperationDestination";
                        break;
                }

                if (filter.SqlWhereCommand.HasValue())
                {
                    whereList.Add(DynamicFilteringTools.GetStaticWhere(filter));

                    if (subQueryWhereCommand.HasValue())
                    {
                        subWhereList.Add(DynamicFilteringTools.GetStaticWhere(filter).Replace(filter.SqlWhereCommand, subQueryWhereCommand));
                    }
                }
            }
        }

        var dtProducts = new DataTable();

        var cmd = $"""
        WITH ActionSumCounts AS (
            SELECT
                tbl_MovementActions_3.MovementActionId,
                tbl_MovementActions_3.MovementActionTp,
                tbl_MovementActions_3.MovementActionStore,
                SUM(tbl_Tags.ProductCount) AS SumCount
            FROM tbl_MovementActions AS tbl_MovementActions_3
            LEFT OUTER JOIN tbl_ActionTypes AS tbl_ActionTypes_3 ON tbl_MovementActions_3.MovementActionTp = tbl_ActionTypes_3.fld_ActionTypeId
            LEFT OUTER JOIN tbl_TagsMovement AS tbl_TagsMovement_3 ON tbl_MovementActions_3.MovementActionId = tbl_TagsMovement_3.RMovementActionId
            LEFT OUTER JOIN tbl_Products AS tbl_Products_3 ON tbl_TagsMovement_3.ProductCode = tbl_Products_3.ProductCode
            LEFT OUTER JOIN tbl_TruckCross AS TruckCross_3 ON tbl_MovementActions_3.MovementActionTruckCrossId = TruckCross_3.fld_TruckCrossId
            LEFT OUTER JOIN tbl_Tags ON tbl_Tags.ProductSerial = tbl_TagsMovement_3.ProductSerial
            {(subWhereList.Any() ? " WHERE " + string.Join(" AND ", subWhereList) : "")}
            GROUP BY tbl_MovementActions_3.MovementActionId, tbl_MovementActions_3.MovementActionTp, tbl_MovementActions_3.MovementActionStore
        )
        SELECT {recordCount} 
            OpCode, 
            [User], 
            DateTime, 
            Count, 
            SumCount, 
            StoreCode, 
            GateOp, 
            MovementActionData, 
            GateCode,
            ActionType, 
            ActionTypeTitle, 
            DestinationTitle, 
            StoreTitle, 
            ActionDocumentId,
            MovementActionDesc,
            Serials,
            StationName
        FROM (
            SELECT
                CAST(tbl_MovementActions.MovementActionId AS nvarchar(250)) AS OpCode,
                ISNULL(COUNT(DISTINCT tbl_TagsMovement_1.ProductSerial), 0) AS Count,
                ISNULL(sumCounts.SumCount, 0) AS SumCount,
                ISNULL(tbl_MovementActions.MovementActionUHFLogGate, N'') AS GateCode,
                COALESCE((SELECT tbl_User.[Name] FROM tbl_User WHERE (TRY_CONVERT(uniqueidentifier, tbl_MovementActions.MovementActionUserId) IS NOT NULL AND tbl_User.Id = tbl_MovementActions.MovementActionUserId) OR
                (tbl_User.Username = tbl_MovementActions.MovementActionUserId)),(SELECT tbl_Station.fld_StationName FROM tbl_Station WHERE tbl_Station.fld_StationCode = tbl_MovementActions.MovementActionUHFLogGate), N'') AS [User],
                tbl_MovementActions.MovementActionDate + ' - ' + tbl_MovementActions.MovementActionTime AS DateTime,
                ISNULL(tbl_MovementActions.MovementActionData, N'') AS MovementActionData,
                ISNULL(CAST(tbl_MovementActions.MovementActionStore AS nvarchar(250)), N'') AS StoreCode,
                ISNULL(CAST(tbl_MovementActions.MovementActionUHFLogId AS nvarchar(50)), N'') AS GateOp,
                ISNULL(tbl_MovementActions.MovementActionTp, 0) AS ActionType,
                ISNULL(tbl_ActionTypes.fld_ActionTypeTitle, N'') AS ActionTypeTitle,
                ISNULL(tbl_Destination.DestinationTitle, N'') AS StoreTitle,
                ISNULL(tbl_Destination_1.DestinationTitle, N'') AS DestinationTitle,
                ISNULL(tbl_MovementActions.MovementActionDocumentId, N'') AS ActionDocumentId,
                ISNULL(tbl_MovementActions.MovementActionDesc, N'') AS MovementActionDesc,
                STRING_AGG(CAST(tbl_TagsMovement_1.ProductSerial AS NVARCHAR(MAX)), ' , ') AS [Serials],
                ISNULL(tbl_Station.fld_StationName, N'') AS StationName
            FROM tbl_MovementActions
            LEFT OUTER JOIN tbl_Destination AS tbl_Destination_1 ON tbl_Destination_1.DestinationCode = tbl_MovementActions.MovementActionDestinationId
            LEFT OUTER JOIN tbl_Destination ON tbl_MovementActions.MovementActionStore = tbl_Destination.DestinationCode
            LEFT OUTER JOIN tbl_ActionTypes ON tbl_MovementActions.MovementActionTp = tbl_ActionTypes.fld_ActionTypeId
            LEFT OUTER JOIN tbl_TagsMovement AS tbl_TagsMovement_1 ON tbl_MovementActions.MovementActionId = tbl_TagsMovement_1.RMovementActionId
            LEFT OUTER JOIN tbl_Products ON tbl_TagsMovement_1.ProductCode = tbl_Products.ProductCode
            LEFT OUTER JOIN tbl_TruckCross AS TruckCross_1 ON tbl_MovementActions.MovementActionTruckCrossId = TruckCross_1.fld_TruckCrossId
            LEFT OUTER JOIN tbl_Station ON tbl_Station.fld_StationCode = tbl_MovementActions.MovementActionUHFLogGate
            LEFT OUTER JOIN ActionSumCounts AS sumCounts ON
                tbl_MovementActions.MovementActionId = sumCounts.MovementActionId
                AND tbl_MovementActions.MovementActionTp = sumCounts.MovementActionTp
                AND tbl_MovementActions.MovementActionStore = sumCounts.MovementActionStore
            {(whereList.Any() ? " WHERE " + string.Join(" AND ", whereList) : "")}
            GROUP BY
                tbl_MovementActions.MovementActionId,
                tbl_MovementActions.MovementActionUserId,
                tbl_MovementActions.MovementActionDate,
                tbl_MovementActions.MovementActionTime,
                tbl_MovementActions.MovementActionUHFLogId,
                tbl_MovementActions.MovementActionStore,
                tbl_MovementActions.MovementActionData,
                tbl_MovementActions.MovementActionUHFLogGate,
                tbl_MovementActions.MovementActionTp,
                tbl_ActionTypes.fld_ActionTypeTitle,
                tbl_Destination.DestinationTitle,
                tbl_Destination_1.DestinationTitle,
                tbl_MovementActions.MovementActionDocumentId,
                tbl_MovementActions.MovementActionDesc,
                tbl_Station.fld_StationName,
                sumCounts.SumCount
            HAVING COUNT(DISTINCT tbl_TagsMovement_1.ProductSerial) > 0 
        ) AS Nested
        ORDER BY DateTime DESC
        """;

        dtProducts = dataAccess.SqlDataAdapter(cmd, 120);

        return dtProducts;
    }

    public DataTable SGetTruckCrossByMovementActionId(string movementActionId)
    {
        string userId = httpContext.User.GetUserId();

        string command =
            $"""
            SELECT   COALESCE(tbl_TruckCross.fld_TruckCrossDriverName ,N'') AS DriverName, 
            		 COALESCE(tbl_TruckCross.fld_TruckCrossNationalCode,N'') AS NationalCode,
                     COALESCE(tbl_TruckCross.fld_TruckCrossLicenseCode,N'') AS LicenseCode, 
            		 COALESCE(tbl_TruckCross.fld_TruckCrossDriverPhone,N'') AS DriverPhone,
            		 COALESCE(tbl_TruckCross.fld_TruckCrossPlaque,N'') AS Plaque,
                     COALESCE(tbl_TruckType.fld_TruckTypeTitle,N'') AS TypeTitle,
            		 COALESCE(tbl_TruckCross.fld_TruckCrossEnterWeightTonage,0) AS EnterWeightTonage,
                     COALESCE(tbl_TruckCross.fld_TruckCrossExitWeightTonage,0) AS ExitWeightTonage
            FROM     tbl_MovementActions INNER JOIN
                     tbl_TruckCross ON tbl_MovementActions.MovementActionTruckCrossId = tbl_TruckCross.fld_TruckCrossId LEFT OUTER JOIN
                     tbl_TruckType ON tbl_TruckCross.fld_TruckCrossType = tbl_TruckType.fld_TruckTypeId
            WHERE MovementActionId = N'{movementActionId}'
            """;

        var result = dataAccess.SqlDataAdapter(command, 120);

        return result;
    }

    public bool SUpdateMovementActionTruckCross(int actionId, int newTruckCrossId)
    {
        string command = $"""
            UPDATE tbl_MovementActions SET MovementActionTruckCrossId = {newTruckCrossId}  
            , MovementActionDateTime = CAST(N'{DateTime.Now.ToString()}' AS DATETIME)
            WHERE MovementActionId = {actionId}
            """;

        return dataAccess.CmdSqlExecuteNonQuery(command) > 0;
    }

    public DataTable SReportBackEnterProductList(EnterRequest search)
    {
        if (search.FromTime.HasNoValue())
        {
            search.FromTime = "-1";
        }

        if (search.ToTime.HasNoValue())
        {
            search.ToTime = "-1";
        }

        var whereString = " WHERE        (Tags.TagStatus <> 0) AND (tbl_TagsMovement.HTagsMovementSt = 1) AND (tbl_TagsMovement.RTagsMovementSt = 1) and    (MovementActionTp = 6) AND (MovementActionData   LIKE N'%برگشت کالا%') ";
        if (!search.ProductName.Equals("-1"))
        {
            whereString += string.IsNullOrEmpty(whereString) ? "" : " AND ";
            whereString += $" tbl_Products.ProductTitle LIKE N'%{search.ProductName}%' ";
        }

        if (!search.TechnicalCode.Equals("-1"))
        {
            whereString += string.IsNullOrEmpty(whereString) ? "" : " AND ";
            whereString += $" tbl_Products.ProductTechnicalCode = N'{search.TechnicalCode}' ";
        }

        if (!search.ProductCode.Equals("-1"))
        {
            whereString += string.IsNullOrEmpty(whereString) ? "" : " AND ";
            whereString += $" tbl_TagsMovement.ProductCode = N'{search.ProductCode}' ";
        }

        if (!search.FromDate.Equals("-1"))
        {
            whereString += string.IsNullOrEmpty(whereString) ? "" : " AND ";
            whereString += $" tbl_MovementActions.MovementActionDate >= N'{search.FromDate}' ";
        }

        if (!search.ToDate.Equals("-1"))
        {
            whereString += string.IsNullOrEmpty(whereString) ? "" : " AND ";
            whereString += $" tbl_MovementActions.MovementActionDate <= N'{search.ToDate}' ";
        }

        if (!search.FromTime.Equals("-1"))
        {
            whereString += string.IsNullOrEmpty(whereString) ? "" : " AND ";
            whereString += $" tbl_MovementActions.MovementActionTime >= N'{search.FromTime}' ";
        }

        if (!search.ToTime.Equals("-1"))
        {
            whereString += string.IsNullOrEmpty(whereString) ? "" : " AND ";
            whereString += $" tbl_MovementActions.MovementActionTime <= N'{search.ToTime}' ";
        }

        var dtProducts = new DataTable();
        dtProducts.Columns.Add("HMovementActionId", typeof(string));
        dtProducts.Columns.Add("HTagsMovementDate", typeof(string));
        dtProducts.Columns.Add("HTagsMovementTime", typeof(string));
        dtProducts.Columns.Add("MovementData", typeof(string));
        dtProducts.Columns.Add("ProductSerial", typeof(string));
        dtProducts.Columns.Add("ProductCode", typeof(string));
        dtProducts.Columns.Add("ProductName", typeof(string));
        dtProducts.Columns.Add("RegCode", typeof(string));
        dtProducts.Columns.Add("ProductStatusTitle", typeof(string));
        dtProducts.Columns.Add("ProductCount", typeof(string));
        dtProducts.Columns.Add("TagRegisterShamsiUnixDate", typeof(string));
        dtProducts.Columns.Add("Username", typeof(string));
        dtProducts.Columns.Add("fld_ProductPropertyATitle", typeof(string));
        dtProducts.Columns.Add("fld_ProductPropertyBTitle", typeof(string));
        dtProducts.Columns.Add("TagEpc", typeof(string));
        dtProducts.Columns.Add("TagZone", typeof(string));
        dtProducts.Columns.Add("ProductProperties", typeof(string));
        dtProducts.Columns.Add("ProductTypeTitle", typeof(string));
        dtProducts.Columns.Add("ProductSize", typeof(string));
        dtProducts.Columns.Add("MovementActionCarPlaque", typeof(string));
        dtProducts.Columns.Add("MovementActionDriverName", typeof(string));

        var cmd = $@"SELECT        TOP (5000) tbl_MovementActions.MovementActionId AS HMovementActionId, tbl_MovementActions.MovementActionDate AS HTagsMovementDate, tbl_MovementActions.MovementActionTime AS HTagsMovementTime, 
                         COALESCE (tbl_MovementActions.MovementActionData, N' ') AS MovementData, Tags.ProductSerial, Tags.ProductCode, Tags.ProductName, Tags.RegCode, tbl_ProductStatus.ProductStatusTitle, Tags.ProductCount, 
                         Tags.TagRegisterShamsiUnixDate, Tags.Username, COALESCE(tbl_ProductPropertyA.fld_ProductPropertyATitle,N''),COALESCE( tbl_ProductPropertyB.fld_ProductPropertyBTitle,N''), Tags.TagEpc, Tags.TagZone, Tags.ProductProperties, 
                         tbl_ProductType.ProductTypeTitle, tbl_Products.ProductSize, tbl_MovementActions.MovementActionId, tbl_MovementActions.MovementActionCarPlaque, tbl_MovementActions.MovementActionDriverName
FROM            tbl_MovementActions LEFT OUTER JOIN
                         tbl_TagsMovement ON tbl_MovementActions.MovementActionId = tbl_TagsMovement.HMovementActionId LEFT OUTER JOIN
                         tbl_Tags AS Tags LEFT OUTER JOIN
                         tbl_ProductPropertyB ON Tags.fld_ProductPropertyBId = tbl_ProductPropertyB.fld_ProductPropertyBId LEFT OUTER JOIN
                         tbl_ProductPropertyA ON Tags.fld_ProductPropertyAId = tbl_ProductPropertyA.fld_ProductPropertyAId ON tbl_TagsMovement.ProductSerial = Tags.ProductSerial LEFT OUTER JOIN
                         tbl_Products ON Tags.ProductCode = tbl_Products.ProductCode LEFT OUTER JOIN
                         tbl_ProductStatus ON Tags.ProductStatus = tbl_ProductStatus.ProductStatusCode LEFT OUTER JOIN
                         tbl_ProductType ON Tags.ProductType = tbl_ProductType.ProductTypeCode
                        {whereString}
                         ";


        dtProducts = dataAccess.SqlDataAdapter(cmd);
        return dtProducts;
    }

    public DataTable SReportHMovementActions(EnterRequest search)
    {
        var whereString = " WHERE        (MovementActionTp = 6) AND (MovementActionData NOT LIKE N'%برگشت کالا%') ";

        if (!search.ProductCode.Equals("-1"))
        {
            whereString += string.IsNullOrEmpty(whereString) ? "" : " AND ";
            whereString += $" tbl_TagsMovement.ProductCode = N'{search.ProductCode}' ";
        }
        if (!search.TechnicalCode.Equals("-1"))
        {
            whereString += string.IsNullOrEmpty(whereString) ? "" : " AND ";
            whereString += $" tbl_Tags_2.RegCode = N'{search.TechnicalCode}' ";
        }
        if (!search.FromDate.Equals("-1"))
        {
            whereString += string.IsNullOrEmpty(whereString) ? "" : " AND ";
            whereString += $" tbl_MovementActions.MovementActionDate >= N'{search.FromDate}' ";
        }
        if (!search.ToDate.Equals("-1"))
        {
            whereString += string.IsNullOrEmpty(whereString) ? "" : " AND ";
            whereString += $" tbl_MovementActions.MovementActionDate <= N'{search.ToDate}' ";
        }
        if (!search.FromTime.Equals("-1"))
        {
            whereString += string.IsNullOrEmpty(whereString) ? "" : " AND ";
            whereString += $" tbl_MovementActions.MovementActionCarPlaque Like N'%{search.FromTime}%' ";
        }
        if (!search.ToTime.Equals("-1"))
        {
            whereString += string.IsNullOrEmpty(whereString) ? "" : " AND ";
            whereString += $" tbl_MovementActions.MovementActionData Like N'%{search.ToTime}%' ";
        }
        if (!search.ProductName.Equals("-1"))
        {
            whereString += string.IsNullOrEmpty(whereString) ? "" : " AND ";
            whereString += $" tbl_MovementActions.MovementActionUHFLogId = {search.ProductName} ";
        }
        if (!search.ProductSerial.Equals("-1"))
        {
            whereString += string.IsNullOrEmpty(whereString) ? "" : " AND ";
            whereString += $" tbl_MovementActions.MovementActionDriverName Like N'%{search.ProductSerial}%' ";
        }


        var dtProducts = new DataTable();
        dtProducts.Columns.Add("MovementActionId", typeof(string));
        dtProducts.Columns.Add("MovementActionUserId", typeof(string));
        dtProducts.Columns.Add("MovementActionDate", typeof(string));
        dtProducts.Columns.Add("MovementActionTime", typeof(string));
        dtProducts.Columns.Add("MovementActionCountTags", typeof(string));
        dtProducts.Columns.Add("MovementActionCarPlaque", typeof(string));
        dtProducts.Columns.Add("MovementActionDriverName", typeof(string));
        dtProducts.Columns.Add("MovementActionDriverMobile", typeof(string));
        dtProducts.Columns.Add("MovementActionUHFLogIDData", typeof(string));
        dtProducts.Columns.Add("MovementActionData", typeof(string));

        var cmd = $@" SELECT  Distinct      TOP (5000) tbl_MovementActions.MovementActionId, tbl_MovementActions.MovementActionUserId, tbl_MovementActions.MovementActionDate, tbl_MovementActions.MovementActionTime, COALESCE
                             ((SELECT        CAST(COUNT(ProductSerial) AS nvarchar(50)) + ' - ' + CAST(SUM(ProductCount) AS nvarchar(50)) AS Expr1
                                 FROM            tbl_TagsMovement
                                 WHERE        (HMovementActionId = tbl_MovementActions.MovementActionId)), '0 - 0') AS MovementActionCountTags, tbl_MovementActions.MovementActionCarPlaque, tbl_MovementActions.MovementActionDriverName, 
                         tbl_MovementActions.MovementActionDriverMobile, CAST(tbl_MovementActions.MovementActionUHFLogId AS nvarchar(50)) + ' - ' + COALESCE (CAST
                             ((SELECT        COUNT(DISTINCT tbl_Tags.ProductSerial) AS Expr1
                                 FROM            tbl_UHF_ReaderLog LEFT OUTER JOIN
                                                          tbl_Tags ON tbl_UHF_ReaderLog.fld_TagSerial = tbl_Tags.TagEpc
                                 WHERE        (tbl_UHF_ReaderLog.fld_Reader_GateType = 3) AND (tbl_UHF_ReaderLog.fld_InventoryId = tbl_MovementActions.MovementActionUHFLogId) AND (tbl_Tags.ProductSerial IS NOT NULL)) AS nvarchar(50)), '0') 
                         + ' - ' + COALESCE (CAST
                             ((SELECT        TOP (1) CASE fld_Reader_Gate WHEN 1 THEN N'هندهلد' ELSE N'گیت' END AS Expr1
                                 FROM            tbl_UHF_ReaderLog AS tbl_UHF_ReaderLog_1 LEFT OUTER JOIN
                                                          tbl_Tags AS tbl_Tags_1 ON tbl_UHF_ReaderLog_1.fld_TagSerial = tbl_Tags_1.TagEpc
                                 WHERE        (tbl_UHF_ReaderLog_1.fld_Reader_GateType = 3) AND (tbl_UHF_ReaderLog_1.fld_InventoryId = tbl_MovementActions.MovementActionUHFLogId) AND (tbl_Tags_1.ProductSerial IS NOT NULL)) AS nvarchar(50)), 
                         '0') AS MovementActionUHFLogIDData, tbl_MovementActions.MovementActionData
FROM            tbl_Tags AS tbl_Tags_2 RIGHT OUTER JOIN
                         tbl_TagsMovement AS tbl_TagsMovement_1 ON tbl_Tags_2.ProductSerial = tbl_TagsMovement_1.ProductSerial RIGHT OUTER JOIN
                         tbl_MovementActions ON tbl_TagsMovement_1.HMovementActionId = tbl_MovementActions.MovementActionId
                        {whereString}
ORDER BY MovementActionDate, MovementActionTime
                         ";


        dtProducts = dataAccess.SqlDataAdapter(cmd);


        return dtProducts;
    }

    public DataTable SGetProductOfWarehouse(InventoryRequest search)
    {
        var whereString = "";

        if (!search.ProductCode.Equals("-1"))
        {
            whereString += string.IsNullOrEmpty(whereString) ? " " : " AND ";
            whereString += $" tbl_Tags.ProductCode = N'{search.ProductCode}' ";
        }

        if (!search.TechnicalCode.Equals("-1"))
        {
            whereString += string.IsNullOrEmpty(whereString) ? " " : " AND ";
            whereString += $" tbl_Tags.RegCode  = N'{search.TechnicalCode}' ";
        }

        if (search.Warehouse.NotEquals("-1"))
        {
            var warehouseValues = string.Join(",", search.Warehouse.Split(',').Select(w => $"N'{w.Trim()}'"));

            whereString += string.IsNullOrEmpty(whereString) ? " " : " AND ";
            whereString += $" tbl_Tags.TagInDestinationId IN ({warehouseValues}) ";
        }

        if (search.Type.NotEquals("-1"))
        {
            whereString += string.IsNullOrEmpty(whereString) ? " " : " AND ";
            whereString += $" tbl_Tags.ProductType  = N'{search.Type}' ";
        }

        if (!search.Qc.Equals("-1"))
        {
            whereString += string.IsNullOrEmpty(whereString) ? " " : " AND ";
            whereString += $" tbl_Tags.ProductStatus  = N'{search.Qc}' ";
        }

        if (!search.Size.Equals("-1"))
        {
            whereString += string.IsNullOrEmpty(whereString) ? " " : " AND ";
            whereString += $" tbl_Tags.fld_ProductPropertyCId  = N'{search.Size}' ";
        }

        var cmd = $@"
         SELECT COALESCE(tbl_Tags.ProductCode, N'')			        AS ProductCode
			   ,COALESCE (tbl_Products.ProductTitle, N'')			AS ProductTitle
			   ,COALESCE (tbl_Products.ProductTechnicalCode, N'')	AS RegCode
			   ,COALESCE (tbl_Products.ProductStatus, N'')			AS Qc
			   ,COALESCE (tbl_Products.ProductSize, N'')			AS ProductSize
			   ,COALESCE (tbl_Tags.ProductSerial, N'')				AS ProductSerial
			   ,COALESCE (tbl_Tags.ProductCount, 0)					AS ProductCount
			   ,COALESCE (tbl_Tags.TagEpc, N'')						AS Epc
			   ,COALESCE((SELECT STRING_AGG( TagZone, ' | ')
                WITHIN GROUP (ORDER BY  TagZone) AS NewField from 
                (SELECT DISTINCT ProductCode,tbl_Tags_1.TagZone 
                FROM [dbo].[tbl_Tags]   AS tbl_Tags_1   
                Where tbl_Tags_1.productcode = tbl_Tags.productcode
                and  tbl_Tags_1.TagStatus  = 1  ) x GROUP BY  
                ProductCode),'0')                                   AS [Zones]
               ,COALESCE (tbl_Tags.TagZone, N'')                    AS [ThisTagZone]
               ,COALESCE(tbl_Tags.TagRegisterShamsiUnixDate,N'')    AS [Date]
               ,COALESCE(tbl_Tags.ContractStatus,N'') AS [ContractStatus]
	           ,COALESCE((SELECT TOP(1) tbl_Destination.DestinationTitle
	           FROM tbl_Destination RIGHT OUTER JOIN tbl_Tags AS Tags ON tbl_Destination.DestinationCode = Tags.TagInDestinationId
	           WHERE tbl_Tags.ProductSerial = Tags.ProductSerial
	           ),N'') AS [DestinationTitle]
               ,COALESCE(tbl_Tags.TagInDestinationId,N'') AS Place
               FROM tbl_Products RIGHT OUTER JOIN tbl_Tags ON tbl_Products.ProductCode = tbl_Tags.ProductCode "
               + (whereString.HasNoValue() ? "" : $" WHERE {whereString}") +
               "ORDER BY tbl_Tags.ProductCode";

        return dataAccess.SqlDataAdapter(cmd);
    }

    public DataTable SSearchLastCAD(GetInventoryConflictsQuery search)
    {
        string whereString = string.Empty;

        if (!search.InventoryHeaderId.Equals("-1"))
        {
            whereString += string.IsNullOrEmpty(whereString) ? " " : " AND ";
            whereString += $" tbl_CustomerAccountingData.fld_CADInventoryHeaderId = {search.InventoryHeaderId}   ";
        }

        if (!search.ProductCode.Equals("-1"))
        {
            whereString += string.IsNullOrEmpty(whereString) ? " " : " AND ";
            whereString += $" tbl_Products.ProductCode = N'{search.ProductCode}' ";
        }

        if (!search.Type.Equals("-1"))
        {
            whereString += string.IsNullOrEmpty(whereString) ? " " : " AND ";
            whereString += $" tbl_Products.ProductType = N'{search.Type}' ";
        }

        if (!search.Size.Equals("-1"))
        {
            whereString += string.IsNullOrEmpty(whereString) ? " " : " AND ";
            whereString += $" tbl_Products.ProductSize = N'{search.Size}' ";
        }

        if (!search.Qc.Equals("-1"))
        {
            whereString += string.IsNullOrEmpty(whereString) ? " " : " AND ";
            whereString += $" tbl_Products.ProductStatus = N'{search.Qc}' ";
        }

        if (search.TechnicalCode.NotEquals("-1"))
        {
            if (search.TechnicalCodeLike)
            {
                whereString += string.IsNullOrEmpty(whereString) ? " " : " AND ";
                whereString += $"(tbl_Products.ProductTechnicalCode  Like N'%{search.TechnicalCode}%')";
            }
            else
            {
                whereString += string.IsNullOrEmpty(whereString) ? " " : " AND ";
                whereString += $" tbl_Products.ProductTechnicalCode = N'{search.TechnicalCode}' ";
            }
        }

        string cmd = $"""
            SELECT  COALESCE(tbl_Products.ProductCode, N'')						 AS [ProductCode],
            		COALESCE(tbl_Products.ProductTitle, N'')					 AS [ProductTitle],
            		COALESCE(tbl_Products.ProductStatus, N'')					 AS [Qc],
            		COALESCE(tbl_Products.ProductSize, N'')						 AS [ProductSize],
            		COALESCE(tbl_Products.ProductTechnicalCode, N'')			 AS [Regcode],
            		COALESCE(tbl_CustomerAccountingData.fld_CADProductCount, 0)	 AS [ProductCount],
                    COALESCE(tbl_CustomerAccountingData.fld_CADRealityCount, 0)	 AS [RealityCount]
            FROM    tbl_CustomerAccountingData INNER JOIN tbl_Products ON tbl_CustomerAccountingData.fld_CADProductCode = tbl_Products.ProductCode
            {(whereString.HasValue() ? "WHERE " + whereString : "")}
            """;

        return dataAccess.SqlDataAdapter(cmd);
    }

    public DataTable SSearchInventoryTags(InventoryRequest search)
    {
        string whereStringSubQuery = "";

        if (search.InventoryHeaderId.NotEquals("-1"))
        {
            whereStringSubQuery += string.IsNullOrEmpty(whereStringSubQuery) ? " " : " AND ";
            whereStringSubQuery += $" tbl_InventoryTags.fld_InventoryHeaderId = {search.InventoryHeaderId}   ";
        }

        string[] StartShiftTime = new string[3];
        DataTable shiftList = SPGetShiftStartENDList();

        foreach (DataRow dr in shiftList.Rows)
        {
            string Temp = dr["fld_ProductPropertyBDesc"].ToString().Split('-')[0].Split(':')[0] + dr["fld_ProductPropertyBDesc"].ToString().Split('-')[0].Split(':')[1] + "01";
            StartShiftTime[Convert.ToInt32(dr["fld_ProductPropertyBId"].ToString()) - 1] = Temp;
        }

        if (!search.FromDate.Equals("-1"))
        {
            string dateTimeFilter =
                PersianCalendarTools.PersianToGregorian(search.FromDate).ToShortDateString() + " " +
                StartShiftTime[0].Substring(0, 2) + ':' + StartShiftTime[0].Substring(2, 2) + ':' + StartShiftTime[0].Substring(4, 2);

            whereStringSubQuery += string.IsNullOrEmpty(whereStringSubQuery) ? " " : " AND ";
            whereStringSubQuery += $" tbl_InventoryTags.fld_InventoryDateTime >=  CONVERT(DATETIME,  N'{dateTimeFilter}', 102)   ";
        }

        if (!search.ToDate.Equals("-1"))
        {
            string dateTimeFilter =
                PersianCalendarTools.PersianToGregorian(search.ToDate).ToShortDateString() + " " +
                StartShiftTime[0].Substring(0, 2) + ':' + StartShiftTime[0].Substring(2, 2) + ':' + StartShiftTime[0].Substring(4, 2);

            whereStringSubQuery += string.IsNullOrEmpty(whereStringSubQuery) ? " " : " AND ";
            whereStringSubQuery += $" (tbl_InventoryTags.fld_InventoryDateTime <=  CONVERT(DATETIME,  N'{dateTimeFilter}', 102)  )  ";
        }

        if (!search.Desc.Equals("-1"))
        {
            whereStringSubQuery += string.IsNullOrEmpty(whereStringSubQuery) ? " " : " AND ";
            whereStringSubQuery += $" tbl_InventoryTags.fld_InventoryProductDesc  Like N'%{search.Desc}%' ";
        }

        if (!search.Place.Equals("-1"))
        {
            whereStringSubQuery += string.IsNullOrEmpty(whereStringSubQuery) ? " " : " AND ";
            whereStringSubQuery += $" tbl_InventoryTags.fld_InventoryPlace = N'{search.Place}' ";
        }

        if (!search.Warehouse.Equals("-1"))
        {
            var warehouseValues = string.Join(",", search.Warehouse.Split(',').Select(w => $"N'{w.Trim()}'"));

            whereStringSubQuery += string.IsNullOrEmpty(whereStringSubQuery) ? " " : " AND ";
            whereStringSubQuery += $" tbl_InventoryTags.fld_InventoryStoreCode IN ({warehouseValues}) ";
        }

        if (!search.User.Equals("-1"))
        {
            whereStringSubQuery += string.IsNullOrEmpty(whereStringSubQuery) ? " " : " AND ";
            whereStringSubQuery += $" tbl_InventoryTags.fld_InventoryUser = N'{search.User}' ";
        }

        if (!search.ProductCode.Equals("-1"))
        {
            whereStringSubQuery += string.IsNullOrEmpty(whereStringSubQuery) ? " " : " AND ";
            whereStringSubQuery += $" tbl_Tags.ProductCode = N'{search.ProductCode}' ";
        }

        if (!search.Type.Equals("-1"))
        {
            whereStringSubQuery += string.IsNullOrEmpty(whereStringSubQuery) ? " " : " AND ";
            whereStringSubQuery += $" tbl_Tags.ProductType = N'{search.Type}' ";
        }

        if (!search.Size.Equals("-1"))
        {
            whereStringSubQuery += string.IsNullOrEmpty(whereStringSubQuery) ? " " : " AND ";
            whereStringSubQuery += $" tbl_Tags.fld_ProductPropertyCId = N'{search.Size}' ";
        }

        if (!search.Qc.Equals("-1"))
        {
            whereStringSubQuery += string.IsNullOrEmpty(whereStringSubQuery) ? " " : " AND ";
            whereStringSubQuery += $" tbl_Tags.ProductStatus = N'{search.Qc}' ";
        }

        if (search.TechnicalCode.NotEquals("-1"))
        {
            if (search.TechnicalCodeLike)
            {
                whereStringSubQuery += string.IsNullOrEmpty(whereStringSubQuery) ? " " : " AND ";
                whereStringSubQuery += $"(tbl_Tags.RegCode  Like N'%{search.TechnicalCode}%')";
            }
            else
            {
                whereStringSubQuery += string.IsNullOrEmpty(whereStringSubQuery) ? " " : " AND ";
                whereStringSubQuery += $" tbl_Tags.RegCode = N'{search.TechnicalCode}' ";
            }
        }

        //COALESCE(tbl_Tags.TagRegisterShamsiUnixDate,N'')AS [Date]
        string command = """
            SELECT distinct	tbl_InventoryTags.fld_InventoryDate			    AS [InventoryDate],
            		tbl_InventoryTags.fld_InventoryHeaderId			AS [InventoryHeaderId],
            		tbl_InventoryTags.fld_InventoryStoreCode		AS [InventoryZone],
                    tbl_InventoryTags.fld_InventoryTagEPC           AS [Epc],
            		COALESCE(tbl_Tags.ProductSerial, N'')			AS [ProductSerial],
            		COALESCE(tbl_Tags.ProductName, N'')				AS [ProductName],
            		COALESCE(tbl_Tags.ProductCode, N'')				AS [ProductCode],
            		COALESCE(tbl_Tags.ProductCount, 0)				AS [ProductCount],
            		COALESCE(tbl_Tags.RegCode, N'')				    AS [RegCode],
                    COALESCE(tbl_Tags.TagRegisterShamsiUnixDate, N'') AS [RegisterDate],
            	 N'' AS [Date],
                    COALESCE(tbl_Tags.ContractStatus,N'') AS [ContractStatus],
                    COALESCE((SELECT TOP(1) tbl_Destination.DestinationTitle
                    FROM tbl_Destination RIGHT OUTER JOIN tbl_Tags AS Tags ON tbl_Destination.DestinationCode = Tags.TagInDestinationId
                    WHERE tbl_Tags.ProductSerial = Tags.ProductSerial
                    ),N'') AS [DestinationTitle],
                    COALESCE(tbl_Tags.TagInDestinationId,N'') AS Place
            FROM	tbl_InventoryTags LEFT JOIN tbl_Tags ON tbl_Tags.TagEpc = tbl_InventoryTags.fld_InventoryTagEPC
            """;

        if (whereStringSubQuery.HasValue())
        {
            command += $" where {whereStringSubQuery} ";
        }
        return dataAccess.SqlDataAdapter(command, 300);
    }

    public DataTable SCalculateAccontingConflicts(InventoryRequest search)
    {
        var nestedWhere = "";
        var whereString = "(tbl_Tags.TagStatus = 1)";
        var whereStringSubQuery = "  Where tbl_Tags_2.TagStatus  = 1  ";
        var whereStringSubQuery2 = " Where tbl_Tags_3.TagStatus  = 1   ";

        if (search.InventoryHeaderId.NotEquals("-1"))
        {
            whereStringSubQuery += string.IsNullOrEmpty(whereStringSubQuery) ? " " : " AND ";
            whereStringSubQuery += $" tbl_InventoryTags_1.fld_InventoryHeaderId = {search.InventoryHeaderId}   ";
            whereStringSubQuery2 += string.IsNullOrEmpty(whereStringSubQuery2) ? " " : " AND ";
            whereStringSubQuery2 += $" tbl_InventoryTags_2.fld_InventoryHeaderId = {search.InventoryHeaderId}   ";
        }

        if (search.Warehouse.NotEquals("-1"))
        {
            whereString += string.IsNullOrEmpty(whereString) ? " " : " AND ";
            whereString += $" tbl_Tags.TagInDestinationId  = N'{search.Warehouse}' ";
        }

        if (search.Type.NotEquals("-1"))
        {
            whereString += string.IsNullOrEmpty(whereString) ? " " : " AND ";
            whereString += $" tbl_Tags.ProductType  = N'{search.Type}' ";
        }

        if (!search.ProductCode.Equals("-1"))
        {
            whereString += string.IsNullOrEmpty(whereString) ? " " : " AND ";
            whereString += $" tbl_Tags.ProductCode = N'{search.ProductCode}' ";
        }

        if (!search.FromDate.Equals("-1"))
        {
            string[] TagRegisterShamsiUnixDateTemp = search.FromDate.Split('/');
            var TagRegisterShamsiUnixDate = TagRegisterShamsiUnixDateTemp[0] + TagRegisterShamsiUnixDateTemp[1] + TagRegisterShamsiUnixDateTemp[2] + "010101";
            whereString += string.IsNullOrEmpty(whereString) ? " " : " AND ";
            whereString += $" tbl_Tags.TagRegisterShamsiUnixDate  < N'{TagRegisterShamsiUnixDate}'   ";
            whereStringSubQuery += string.IsNullOrEmpty(whereStringSubQuery) ? " " : " AND ";
            whereStringSubQuery += $" tbl_InventoryTags_1.fld_InventoryDate >=   N'{search.FromDate}'   ";
            whereStringSubQuery2 += string.IsNullOrEmpty(whereStringSubQuery2) ? " " : " AND ";
            whereStringSubQuery2 += $" tbl_InventoryTags_2.fld_InventoryDate >=   N'{search.FromDate}'   ";
        }

        if (!search.ToDate.Equals("-1"))
        {
            whereStringSubQuery += string.IsNullOrEmpty(whereStringSubQuery) ? " " : " AND ";
            whereStringSubQuery += $" (tbl_InventoryTags_1.fld_InventoryDate <=  N'{search.ToDate}' )  ";
            whereStringSubQuery2 += string.IsNullOrEmpty(whereStringSubQuery2) ? " " : " AND ";
            whereStringSubQuery2 += $" (tbl_InventoryTags_2.fld_InventoryDate <=  N'{search.ToDate}' )  ";
        }

        if (!search.TechnicalCode.Equals("-1"))
        {
            whereString += string.IsNullOrEmpty(whereString) ? " " : " AND ";
            whereString += $" tbl_Tags.RegCode  = N'{search.TechnicalCode}' ";
        }

        if (!search.ProductSerial.Equals("-1"))
        {
            whereString += string.IsNullOrEmpty(whereString) ? " " : " AND ";
            whereString += $" tbl_Tags.ProductSerial  = N'{search.ProductSerial}' ";
        }

        if (!search.Desc.Equals("-1"))
        {
            whereStringSubQuery += string.IsNullOrEmpty(whereStringSubQuery) ? " " : " AND ";
            whereStringSubQuery += $" tbl_InventoryTags_1.fld_InventoryProductDesc  Like N'%{search.Desc}%' ";
            whereStringSubQuery2 += string.IsNullOrEmpty(whereStringSubQuery2) ? " " : " AND ";
            whereStringSubQuery2 += $" tbl_InventoryTags_2.fld_InventoryProductDesc  Like N'%{search.Desc}%' ";
        }

        if (!search.Place.Equals("-1"))
        {
            whereStringSubQuery += string.IsNullOrEmpty(whereStringSubQuery) ? " " : " AND ";
            whereStringSubQuery += $" tbl_InventoryTags_1.fld_InventoryPlace = N'{search.Desc}' ";
            whereStringSubQuery2 += string.IsNullOrEmpty(whereStringSubQuery2) ? " " : " AND ";
            whereStringSubQuery2 += $" tbl_InventoryTags_2.fld_InventoryPlace = N'{search.Desc}' ";
        }

        if (!search.Qc.Equals("-1"))
        {
            whereString += string.IsNullOrEmpty(whereString) ? " " : " AND ";
            whereString += $" tbl_Tags.ProductStatus  = N'{search.Qc}' ";
        }

        if (search.ConflictsShown)
        {
            nestedWhere += string.IsNullOrEmpty(nestedWhere) ? "" : " AND ";
            nestedWhere += $" (Nested.SumValue - Nested.InventorySumValue != 0 OR Nested.CountProduct - Nested.inventoryCountProduct != 0 OR Nested.InventorySumValue - Nested.SumCountAccounting != 0) ";
        }

        var cmd = $@"
SELECT Nested.*,
Nested.SumCountAccounting as SumCountAccounting,
Nested.InventorySumValue - Nested.SumCountAccounting as [ConflictSumCountAccounting],
Nested.CountProduct - Nested.inventoryCountProduct  as ConflictCount, 
Nested.SumValue - Nested.InventorySumValue as ConflictValue
FROM (
    SELECT COALESCE(tbl_Tags.ProductCode, N'')                                                   AS ProductCode
    ,COALESCE (tbl_Products.ProductTitle, N'')                                                   AS ProductTitle
    ,COALESCE (tbl_Products.ProductTechnicalCode, N'')                                           AS RegCode
    ,COALESCE (tbl_Products.ProductStatus, N'')                                                  AS ProductStatus
    ,COALESCE (tbl_Products.ProductSize, N'')                                                    AS ProductSize
    ,COUNT(DISTINCT tbl_Tags.ProductSerial)                                                      AS CountProduct
    ,SUM(tbl_Tags.ProductCount)                                                                  AS SumValue
    ,COALESCE ((SELECT COUNT(DISTINCT ProductSerial) AS Expr1 FROM tbl_Tags AS tbl_Tags_3
                WHERE(TagEpc IN (SELECT tbl_InventoryTags_2.fld_InventoryTagEPC
                                 FROM tbl_InventoryTags AS tbl_InventoryTags_2 LEFT OUTER JOIN
                                 tbl_Tags AS tbl_Tags_4 ON tbl_InventoryTags_2.fld_InventoryTagEPC = tbl_Tags_4.TagEpc
                          {whereStringSubQuery2})) AND(ProductCode = tbl_Tags.ProductCode)), 0) AS inventoryCountProduct
    ,COALESCE ((SELECT SUM(ProductCount) AS Expr1 FROM tbl_Tags AS tbl_Tags_1
                WHERE(TagEpc IN (SELECT tbl_InventoryTags_1.fld_InventoryTagEPC
                                 FROM tbl_InventoryTags AS tbl_InventoryTags_1 LEFT OUTER JOIN
                                 tbl_Tags AS tbl_Tags_2 ON tbl_InventoryTags_1.fld_InventoryTagEPC = tbl_Tags_2.TagEpc
                           {whereStringSubQuery})) AND(ProductCode = tbl_Tags.ProductCode)), 0) AS InventorySumValue
,COALESCE ((SELECT TOP(1) tbl_CustomerAccountingData.fld_CADProductCount FROM tbl_CustomerAccountingData 
				WHERE tbl_CustomerAccountingData.fld_CADProductCode = tbl_Tags.ProductCode AND tbl_CustomerAccountingData.fld_CADOpCode = (SELECT MAX([InnerCad].fld_CADOpCode) FROM tbl_CustomerAccountingData AS [InnerCad])), 0) AS SumCountAccounting
    FROM tbl_Products RIGHT OUTER JOIN
    tbl_Tags ON tbl_Products.ProductCode = tbl_Tags.ProductCode
    WHERE  {whereString}
    GROUP BY tbl_Tags.ProductCode, tbl_Products.ProductTitle, tbl_Products.ProductTechnicalCode, tbl_Products.ProductStatus, tbl_Products.ProductSize, tbl_Tags.TagStatus 
) AS Nested 
 " + (string.IsNullOrEmpty(nestedWhere) ? "" : " WHERE " + nestedWhere);

        return dataAccess.SqlDataAdapter(cmd);
    }

    public DataTable SRepInventoryDetails(InventoryRequest search)
    {
        var enterRequest = new EnterRequest
        {
            ProductSerial = search.ProductSerial,
            ProductCode = search.ProductCode,
            FromDate = search.FromDate,
            ToDate = search.ToDate,
            TechnicalCode = search.TechnicalCode,
            ProductName = search.Place,
            Shift = search.Qc,
            FromTime = search.ProductSerial,
            ToTime = search.Desc
        };

        var dt = SRepInventoryProductList(enterRequest);

        dt.Columns["TagRegisterShamsiUnixDate"].ColumnName = "Date";
        dt.Columns["InventoryData"].ColumnName = "Status";
        dt.Columns["TagZone"].ColumnName = "Zone";
        dt.Columns["ProductCount"].DataType = typeof(decimal);
        dt.Columns.Add("Desc");
        dt.Columns.Add("Place");

        foreach (DataRow row in dt.Rows)
        {
            row["Desc"] = "";

            row["Place"] = "";
        }

        return dt;
    }

    public DataTable SReportExitActionTajamoeeProductCode(List<ReportFilter> reportFilters)
    {
        List<string> whereList = new();
        whereList.Add("(tbl_TagsMovement.ProductCode IS NOT NULL)");

        List<string> subWhereList = new();

        string limit = string.Empty;

        foreach (ReportFilter filter in reportFilters)
        {
            string subQueryWhereCommand = string.Empty;

            if (filter.SqlWhereCommand.HasValue())
            {
                continue;
            }

            if (filter.Type.Equals(FilterType.Dynamic))
            {
                if (filter.AdditionalData["DynamicFilterActionType"] == "1")
                {
                    whereList.Add(
                        $"""
                    (tbl_TagsMovement.ProductSerial IN (
                    SELECT ProductSerial FROM tbl_Tags AS Tags 
                    WHERE JSON_VALUE(Tags.ProductProperties,N'$."{filter.FieldName}"') IN(N'{string.Join("',N'", filter.Values)}')))
                    """);

                    subWhereList.Add(
                        $"""
                    (tbl_TagsMovement_3.ProductSerial 
                    IN (SELECT ProductSerial FROM tbl_Tags AS Tags_3 
                    WHERE JSON_VALUE(Tags_3.ProductProperties,N'$."{filter.FieldName}"') IN(N'{string.Join("',N'", filter.Values)}')))
                    """);
                }
                else
                {
                    filter.SqlWhereCommand = $"JSON_VALUE(tbl_MovementActions.MovementActionData,N'$.\"{filter.FieldName}\"')";

                    subQueryWhereCommand = $"JSON_VALUE(tbl_MovementActions_3.MovementActionData,N'$.\"{filter.FieldName}\"')";

                    whereList.Add(DynamicFilteringTools.GetDynamicWhere(filter));

                    subWhereList.Add(DynamicFilteringTools.GetDynamicWhere(filter).Replace(filter.SqlWhereCommand, subQueryWhereCommand));
                }
            }
            else if (filter.Type.Equals(FilterType.TechnicalInfo))
            {
                filter.SqlWhereCommand = $"JSON_VALUE(tbl_Products.ProductTechnicalData,N'$.\"{filter.FieldName}\"')";

                subQueryWhereCommand = $"JSON_VALUE(tbl_Products_3.ProductTechnicalData,N'$.\"{filter.FieldName}\"')";

                whereList.Add(DynamicFilteringTools.GetTechnicalInfoWhere(filter));

                subWhereList.Add(DynamicFilteringTools.GetTechnicalInfoWhere(filter).Replace(filter.SqlWhereCommand, subQueryWhereCommand));
            }
            else if (filter.Type.Equals(FilterType.Static))
            {
                switch (filter.FieldName)
                {
                    case "OperationCode":
                        filter.SqlWhereCommand = "MovementActionId";
                        subQueryWhereCommand = "tbl_MovementActions_3.MovementActionId";
                        break;

                    case "ProductCode":
                        filter.SqlWhereCommand = "tbl_TagsMovement.ProductCode";
                        subQueryWhereCommand = "tbl_TagsMovement_3.ProductCode";
                        break;

                    case "TechnicalCode":
                        filter.SqlWhereCommand = "tbl_Products.ProductTechnicalCode";
                        subQueryWhereCommand = "tbl_Products_3.ProductTechnicalCode";
                        break;

                    case "FromDate":
                        filter.SqlWhereCommand = "tbl_MovementActions.MovementActionDateTime";
                        subQueryWhereCommand = "tbl_MovementActions_3.MovementActionDateTime";
                        filter.Values = filter.Values.Select(date => $"dbo.JalaliDateToGeorgianDate(N'{date}', N'06:00')").ToList();
                        break;

                    case "ToDate":
                        filter.SqlWhereCommand = "tbl_MovementActions.MovementActionDateTime";
                        subQueryWhereCommand = "tbl_MovementActions_3.MovementActionDateTime";
                        filter.Values = filter.Values.Select(date => $"dbo.JalaliDateToGeorgianDate(N'{date}', N'06:00')").ToList();
                        break;

                    case "GateOpCode":
                        filter.SqlWhereCommand = "tbl_MovementActions.MovementActionUHFLogId";
                        subQueryWhereCommand = "tbl_MovementActions_3.MovementActionUHFLogId";
                        break;

                    case "StoreCode":
                        filter.SqlWhereCommand = "tbl_MovementActions.MovementActionStore";
                        subQueryWhereCommand = "tbl_MovementActions_3.MovementActionStore";
                        break;

                    case "Size":
                        filter.SqlWhereCommand = "tbl_Products.ProductSize";
                        subQueryWhereCommand = "tbl_Products_3.ProductSize";
                        break;

                    case "ProductGroup":
                        filter.SqlWhereCommand = "tbl_Products.fld_ProductGroup";
                        subQueryWhereCommand = "tbl_Products_3.fld_ProductGroup";
                        break;

                    case "ProductBrand":
                        filter.SqlWhereCommand = "tbl_Products.fld_ProductBrand";
                        subQueryWhereCommand = "tbl_Products_3.fld_ProductBrand";
                        break;

                    case "ProductType":
                        filter.SqlWhereCommand = "tbl_Products.ProductType";
                        subQueryWhereCommand = "tbl_Products_3.ProductType";
                        break;

                    case "Line":
                        whereList.Add($@"(tbl_TagsMovement.ProductSerial IN 
                    (SELECT Tags.ProductSerial FROM tbl_Tags AS Tags 
                    WHERE Tags.fld_ProductPropertyAId IN('{string.Join("','", filter.Values)}') ))");

                        subWhereList.Add($@"(tbl_TagsMovement_3.ProductSerial 
                    IN (SELECT Tags_3.ProductSerial FROM tbl_Tags AS Tags_3 
                    WHERE Tags_3.fld_ProductPropertyAId IN('{string.Join("','", filter.Values)}') ))");
                        break;

                    case "Shift":
                        whereList.Add($@"(tbl_TagsMovement.ProductSerial 
                    IN (SELECT Tags.ProductSerial FROM tbl_Tags AS Tags 
                    WHERE Tags.fld_ProductPropertyBId IN('{string.Join("','", filter.Values)}') ))");

                        subWhereList.Add($@"(tbl_TagsMovement_3.ProductSerial 
                    IN (SELECT Tags_3.ProductSerial FROM tbl_Tags AS Tags_3 
                    WHERE Tags_3.fld_ProductPropertyBId IN('{string.Join("','", filter.Values)}') ))");
                        break;

                    case "GateCode":
                        filter.SqlWhereCommand = "tbl_MovementActions.MovementActionUHFLogGate";
                        subQueryWhereCommand = "tbl_MovementActions_3.MovementActionUHFLogGate";
                        break;

                    case "ActionType":
                        filter.SqlWhereCommand = "tbl_MovementActions.MovementActionTp";
                        subQueryWhereCommand = "tbl_MovementActions_3.MovementActionTp";
                        break;

                    case "DocumentKey":
                        filter.SqlWhereCommand = "tbl_MovementActions.MovementActionDocumentId";
                        subQueryWhereCommand = "tbl_MovementActions_3.MovementActionDocumentId";
                        break;

                    case "TruckType":
                        filter.SqlWhereCommand = "TruckCross_1.fld_TruckCrossType";
                        subQueryWhereCommand = "TruckCross_3.fld_TruckCrossType";
                        break;

                    case "CarPlaque":
                        filter.SqlWhereCommand = "TruckCross_1.fld_TruckCrossPlaque";
                        subQueryWhereCommand = "TruckCross_3.fld_TruckCrossPlaque";
                        break;

                    case "NationalCode":
                        filter.SqlWhereCommand = "TruckCross_1.fld_TruckCrossNationalCode";
                        subQueryWhereCommand = "TruckCross_3.fld_TruckCrossNationalCode";
                        break;

                    case "DriverName":
                        filter.SqlWhereCommand = "TruckCross_1.fld_TruckCrossDriverName";
                        subQueryWhereCommand = "TruckCross_3.fld_TruckCrossDriverName";
                        break;

                    case "TruckCrossCause":
                        filter.SqlWhereCommand = "TruckCross_1.fld_TruckCrossPresentCause";
                        subQueryWhereCommand = "TruckCross_3.fld_TruckCrossPresentCause";
                        break;

                    case "TruckCrossOperationType":
                        filter.SqlWhereCommand = "TruckCross_1.fld_TruckCrossPresentOperationType";
                        subQueryWhereCommand = "TruckCross_3.fld_TruckCrossPresentOperationType";
                        break;

                    case "TruckCrossShipment":
                        filter.SqlWhereCommand = "TruckCross_1.fld_TruckCrossPresentShipment";
                        subQueryWhereCommand = "TruckCross_3.fld_TruckCrossPresentShipment";
                        break;

                    case "TruckCrossOperationDestination":
                        filter.SqlWhereCommand = "TruckCross_1.fld_TruckCrossPresentOperationDestination";
                        subQueryWhereCommand = "TruckCross_3.fld_TruckCrossPresentOperationDestination";
                        break;
                }

                if (filter.SqlWhereCommand.HasValue())
                {
                    whereList.Add(DynamicFilteringTools.GetStaticWhere(filter));

                    if (subQueryWhereCommand.HasValue())
                    {
                        subWhereList.Add(DynamicFilteringTools.GetStaticWhere(filter).Replace(filter.SqlWhereCommand, subQueryWhereCommand));
                    }
                }
            }
            else if (filter.Type.Equals(FilterType.Limit))
            {
                limit = $" TOP({filter.Value}) ";

                filter.SqlWhereCommand = "tbl_MovementActions.MovementActionDateTime";
                subQueryWhereCommand = "tbl_MovementActions_3.MovementActionDateTime";
                filter.Values = new()
                {
                    $"dbo.JalaliDateToGeorgianDate(N'{PersianCalendarTools.GregorianToPersian(DateTime.Now.AddDays(-2))}', N'06:00')"
                };
            }
        }

        // Pre-calculate SumCount in a CTE for better performance - non-correlated
        var cmd = $"""
        WITH ProductSumCounts AS (
            SELECT 
                tbl_TagsMovement_3.ProductCode,
                tbl_MovementActions_3.MovementActionTp,
                tbl_MovementActions_3.MovementActionStore,
                SUM(tbl_Tags.ProductCount) AS SumCount
            FROM tbl_MovementActions AS tbl_MovementActions_3
            LEFT OUTER JOIN tbl_ActionTypes AS tbl_ActionTypes_3 ON tbl_MovementActions_3.MovementActionTp = tbl_ActionTypes_3.fld_ActionTypeId
            LEFT OUTER JOIN tbl_TagsMovement AS tbl_TagsMovement_3 ON tbl_MovementActions_3.MovementActionId = tbl_TagsMovement_3.RMovementActionId
            LEFT OUTER JOIN tbl_Products AS tbl_Products_3 ON tbl_TagsMovement_3.ProductCode = tbl_Products_3.ProductCode
            LEFT OUTER JOIN tbl_TruckCross AS TruckCross_3 ON tbl_MovementActions_3.MovementActionTruckCrossId = TruckCross_3.fld_TruckCrossId
            INNER JOIN tbl_Tags ON tbl_Tags.ProductSerial = tbl_TagsMovement_3.ProductSerial
            {(subWhereList.Any() ? " WHERE " + string.Join(" AND ", subWhereList) : "")}
            GROUP BY tbl_TagsMovement_3.ProductCode, tbl_MovementActions_3.MovementActionTp, tbl_MovementActions_3.MovementActionStore
            )
        SELECT
            NESTED.ProductCode,
            NESTED.ProductName,
            NESTED.TechnicalCode,
            NESTED.Qc,
            NESTED.Count,
            NESTED.SumCount,
            NESTED.StoreCode,
            NESTED.ActionType,
            NESTED.ActionTypeTitle,
            NESTED.DestinationTitle,
            NESTED.StoreTitle,
            NESTED.TechnicalInfoData,
            NESTED.OpCode,
            CAST(ISNULL(NESTED.SumCount / NULLIF(p.ProductValue, 0), 0) AS decimal(18,2)) AS ProductCountInPack
        FROM (
            SELECT
                ISNULL(tbl_TagsMovement.ProductCode, N'') AS ProductCode,
                ISNULL(tbl_Products.ProductTitle, N'') AS ProductName,
                ISNULL(tbl_Products.ProductTechnicalCode, N'') AS TechnicalCode,
                ISNULL(tbl_Products.ProductStatus, N'') AS Qc,
                COUNT(DISTINCT tbl_TagsMovement.ProductSerial) AS Count,
                ISNULL(psc.SumCount, 0) AS SumCount,
                ISNULL(CAST(tbl_MovementActions.MovementActionStore AS nvarchar(250)), N'') AS StoreCode,
                ISNULL(tbl_MovementActions.MovementActionTp, 0) AS ActionType,
                ISNULL(tbl_ActionTypes.fld_ActionTypeTitle, N'') AS ActionTypeTitle,
                ISNULL(tbl_Destination.DestinationTitle, N'') AS DestinationTitle,
                ISNULL(tbl_Destination_1.DestinationTitle, N'') AS StoreTitle,
                ISNULL(STRING_AGG(tbl_Products.ProductTechnicalData, '-,-'), N'') AS TechnicalInfoData,
                ISNULL(tbl_MovementActions.MovementActionId, 0) AS [OpCode]
            FROM tbl_Destination AS tbl_Destination_1
            RIGHT OUTER JOIN tbl_MovementActions ON tbl_Destination_1.DestinationCode = tbl_MovementActions.MovementActionDestinationId
            LEFT OUTER JOIN tbl_Destination ON tbl_MovementActions.MovementActionStore = tbl_Destination.DestinationCode
            LEFT OUTER JOIN tbl_ActionTypes ON tbl_MovementActions.MovementActionTp = tbl_ActionTypes.fld_ActionTypeId
            LEFT OUTER JOIN tbl_TagsMovement ON tbl_MovementActions.MovementActionId = tbl_TagsMovement.RMovementActionId
            LEFT OUTER JOIN tbl_Products ON tbl_TagsMovement.ProductCode = tbl_Products.ProductCode
            LEFT OUTER JOIN tbl_ProductBrand ON tbl_Products.fld_ProductBrand = tbl_ProductBrand.fld_ProductBrandCode
            LEFT OUTER JOIN tbl_ProductGroup ON tbl_Products.fld_ProductGroup = tbl_ProductGroup.fld_ProductGroupCode
            LEFT OUTER JOIN tbl_ProductType ON tbl_Products.ProductType = tbl_ProductType.ProductTypeCode
            LEFT OUTER JOIN tbl_TruckCross AS TruckCross_1 ON tbl_MovementActions.MovementActionTruckCrossId = TruckCross_1.fld_TruckCrossId
            LEFT OUTER JOIN ProductSumCounts AS psc ON 
                tbl_TagsMovement.ProductCode = psc.ProductCode
                AND tbl_MovementActions.MovementActionTp = psc.MovementActionTp
                AND tbl_MovementActions.MovementActionStore = psc.MovementActionStore
            {(whereList.Any() ? " WHERE " + string.Join(" AND ", whereList) : "")}
            GROUP BY
                tbl_TagsMovement.ProductCode,
                tbl_Products.ProductTitle,
                tbl_Products.ProductTechnicalCode,
                tbl_Products.ProductStatus,
                tbl_MovementActions.MovementActionStore,
                tbl_MovementActions.MovementActionTp,
                tbl_ActionTypes.fld_ActionTypeTitle,
                tbl_Destination.DestinationTitle,
                tbl_Destination_1.DestinationTitle,
                psc.SumCount,
                tbl_MovementActions.MovementActionId
        ) AS NESTED
        LEFT OUTER JOIN tbl_Products AS p ON NESTED.ProductCode = p.ProductCode
        """;

        return dataAccess.SqlDataAdapter(cmd, 120);
    }

    public DataTable SReportBackEnterTajamoeeProductCode(EnterRequest search)
    {
        if (string.IsNullOrEmpty(search.FromTime))
        {
            search.FromTime = "-1";
        }

        if (string.IsNullOrEmpty(search.ToTime))
        {
            search.ToTime = "-1";
        }

        if (string.IsNullOrEmpty(search.Shift))
        {
            search.Shift = "-1";
        }

        if (string.IsNullOrEmpty(search.ProductSerial))
        {
            search.ProductSerial = "-1";
        }

        var whereString = " WHERE (tbl_Tags.TagStatus<>0) and  (HTagsMovementSt=1) AND (RTagsMovementSt=1) and    (MovementActionTp = 6) AND (MovementActionData  LIKE N'%برگشت کالا%')";
        if (!search.ProductSerial.Equals("-1"))
        {
            whereString += string.IsNullOrEmpty(whereString) ? "" : " AND ";
            whereString += $" tbl_Tags.ProductSerial = N'{search.ProductSerial}' ";
        }
        if (!search.ProductName.Equals("-1"))
        {
            whereString += string.IsNullOrEmpty(whereString) ? "" : " AND ";
            whereString += $" tbl_Tags.ProductName LIKE N'%{search.ProductName}%' ";
        }
        if (!search.TechnicalCode.Equals("-1"))
        {
            whereString += string.IsNullOrEmpty(whereString) ? "" : " AND ";
            whereString += $" tbl_Tags.RegCode = N'{search.TechnicalCode}' ";
        }
        if (!search.ProductCode.Equals("-1"))
        {
            whereString += string.IsNullOrEmpty(whereString) ? "" : " AND ";
            whereString += $" tbl_TagsMovement.ProductCode = N'{search.ProductCode}' ";
        }
        if (!search.FromDate.Equals("-1"))
        {
            whereString += string.IsNullOrEmpty(whereString) ? "" : " AND ";
            whereString += $" tbl_MovementActions.MovementActionDate >= N'{search.FromDate}' ";
        }
        if (!search.ToDate.Equals("-1"))
        {
            whereString += string.IsNullOrEmpty(whereString) ? "" : " AND ";
            whereString += $" tbl_MovementActions.MovementActionDate <= N'{search.ToDate}' ";
        }
        if (!search.FromTime.Equals("-1"))
        {
            whereString += string.IsNullOrEmpty(whereString) ? "" : " AND ";
            whereString += $" tbl_MovementActions.MovementActionTime >= N'{search.FromTime}' ";
        }
        if (!search.ToTime.Equals("-1"))
        {
            whereString += string.IsNullOrEmpty(whereString) ? "" : " AND ";
            whereString += $" tbl_MovementActions.MovementActionTime <= N'{search.ToTime}' ";
        }
        if (!search.Shift.Equals("-1"))
        {
            whereString += string.IsNullOrEmpty(whereString) ? "" : " AND ";
            whereString += $" tbl_Tags.fld_ProductPropertyBId = N'{search.Shift}' ";
        }

        var cmd = $@" SELECT        tbl_TagsMovement.ProductCode, tbl_Tags.ProductName, COUNT(DISTINCT tbl_TagsMovement.ProductSerial) AS Count, SUM(tbl_TagsMovement.ProductCount) AS SumCount
FROM            tbl_TagsMovement RIGHT OUTER JOIN
                         tbl_MovementActions ON tbl_TagsMovement.HMovementActionId = tbl_MovementActions.MovementActionId LEFT OUTER JOIN
                         tbl_Tags ON tbl_TagsMovement.ProductSerial = tbl_Tags.ProductSerial
                        {whereString}
                        GROUP BY tbl_TagsMovement.ProductCode, tbl_Tags.ProductName ";

        return dataAccess.SqlDataAdapter(cmd);
    }

    public DataTable SReportEnterAction(List<ReportFilter> reportFilters)
    {
        string userId = httpContext.User.GetUserId();

        var recordCount = 5000;

        List<string> whereList = new()
    {
        "ma.MovementActionId IS NOT NULL"
    };

        foreach (ReportFilter filter in reportFilters)
        {
            if (filter.SqlWhereCommand.HasValue())
            {
                continue;
            }

            if (filter.Type.Equals(FilterType.Dynamic))
            {
                if (filter.AdditionalData["DynamicFilterActionType"] == "1")
                {
                    whereList.Add(
                        $"""
                EXISTS (
                    SELECT 1 
                    FROM tbl_Tags AS Tags
                    WHERE tm1.ProductSerial = Tags.ProductSerial
                    AND JSON_VALUE(Tags.ProductProperties, N'$."{filter.FieldName}"') IN(N'{string.Join("',N'", filter.Values)}')
                )
                """);
                }
                else
                {
                    filter.SqlWhereCommand = $"JSON_VALUE(ma.MovementActionData, N'$.\"{filter.FieldName}\"')";
                    whereList.Add(DynamicFilteringTools.GetDynamicWhere(filter));
                }
            }
            else if (filter.Type.Equals(FilterType.TechnicalInfo))
            {
                filter.SqlWhereCommand = $"JSON_VALUE(p.ProductTechnicalData, N'$.\"{filter.FieldName}\"')";
                whereList.Add(DynamicFilteringTools.GetTechnicalInfoWhere(filter));
            }
            else if (filter.Type.Equals(FilterType.Static))
            {
                switch (filter.FieldName)
                {
                    case "OperationCode":
                        filter.SqlWhereCommand = "ma.MovementActionId";
                        break;

                    case "ProductCode":
                        filter.SqlWhereCommand = "tm1.ProductCode";
                        break;

                    case "TechnicalCode":
                        filter.SqlWhereCommand = "p.ProductTechnicalCode";
                        break;

                    case "FromDate":
                        filter.SqlWhereCommand = "ma.MovementActionDateTime";
                        filter.Values = filter.Values.Select(date => $"dbo.JalaliDateToGeorgianDate(N'{date}', N'06:00')").ToList();
                        break;

                    case "ToDate":
                        filter.SqlWhereCommand = "ma.MovementActionDateTime";
                        filter.Values = filter.Values.Select(date => $"dbo.JalaliDateToGeorgianDate(N'{date}', N'06:00')").ToList();
                        break;

                    case "GateOpCode":
                        filter.SqlWhereCommand = "ma.MovementActionUHFLogId";
                        break;

                    case "Destination":
                        filter.SqlWhereCommand = "ma.MovementActionDestinationId";
                        break;

                    case "Size":
                        filter.SqlWhereCommand = "p.ProductSize";
                        break;

                    case "ProductGroup":
                        filter.SqlWhereCommand = "p.fld_ProductGroup";
                        break;

                    case "ProductBrand":
                        filter.SqlWhereCommand = "p.fld_ProductBrand";
                        break;

                    case "ProductType":
                        filter.SqlWhereCommand = "p.ProductType";
                        break;

                    case "GateCode":
                        filter.SqlWhereCommand = "ma.MovementActionUHFLogGate";
                        break;

                    case "ActionType":
                        filter.SqlWhereCommand = "ma.MovementActionTp";
                        break;

                    case "Qc":
                        filter.SqlWhereCommand = "p.ProductStatus";
                        break;

                    case "DocumentKey":
                        filter.SqlWhereCommand = "ma.MovementActionDocumentId";
                        break;

                    case "RecordsCount":
                        if (int.TryParse(filter.Value, out int count))
                        {
                            recordCount = count;
                        }
                        break;
                }

                if (filter.SqlWhereCommand.HasValue())
                {
                    whereList.Add(DynamicFilteringTools.GetStaticWhere(filter));
                }
            }
        }

        var cmd = $"""
    WITH FilteredMovements AS
    (
        SELECT ma.MovementActionId,
               ma.MovementActionStore,
               tm1.ProductSerial,
               ma.MovementActionUserId,
               ma.MovementActionDate,
               ma.MovementActionTime,
               ma.MovementActionDateTime,
               ma.MovementActionUHFLogId,
               ma.MovementActionDestinationId,
               ma.MovementActionData,
               ma.MovementActionUHFLogGate,
               ma.MovementActionTp,
               ma.MovementActionDocumentId,
               ma.MovementActionDesc
        FROM tbl_MovementActions ma
        INNER JOIN tbl_Destination d1 
            ON ma.MovementActionStore = d1.DestinationCode
        LEFT JOIN tbl_TagsMovement tm1 
            ON ma.MovementActionId = tm1.RMovementActionId
        LEFT JOIN tbl_Products p 
            ON tm1.ProductCode = p.ProductCode
        WHERE {string.Join(" AND ", whereList)}
    ),
    ProductCounts AS
    (
        SELECT fm.MovementActionId,
               COUNT(DISTINCT fm.ProductSerial) AS Count,
               SUM(COALESCE(t.ProductCount, 0)) AS SumCount
        FROM FilteredMovements fm
        LEFT JOIN tbl_Tags t 
            ON fm.ProductSerial = t.ProductSerial
        GROUP BY fm.MovementActionId
    )
    SELECT TOP ({recordCount})
           CAST(fm.MovementActionId AS NVARCHAR(250)) AS OpCode,
           COALESCE(u.Name, '') AS [User],
           fm.MovementActionDate + ' - ' + fm.MovementActionTime AS DateTime,
           COALESCE(pc.Count, 0) AS Count,
           COALESCE(pc.SumCount, 0) AS SumCount,
           COALESCE(CAST(fm.MovementActionDestinationId AS NVARCHAR(250)), N'') AS Destination,
           COALESCE(CAST(fm.MovementActionUHFLogId AS NVARCHAR(50)), N'') AS GateOp,
           COALESCE(fm.MovementActionData, N'') AS MovementActionData,
           COALESCE(fm.MovementActionUHFLogGate, N'') AS GateCode,
           COALESCE(fm.MovementActionTp, 0) AS ActionType,
           COALESCE(at.fld_ActionTypeTitle, N'') AS ActionTypeTitle,
           COALESCE(d.DestinationTitle, N'') AS DestinationTitle,
           COALESCE(d1.DestinationTitle, N'') AS StoreTitle,
           COALESCE(fm.MovementActionDocumentId, N'') AS ActionDocumentId,
           COALESCE(fm.MovementActionDesc, N'') AS MovementActionDesc,
           COALESCE(s.fld_StationName, N'') AS StationName
    FROM (
        SELECT DISTINCT MovementActionId,
               MovementActionStore,
               MovementActionUserId,
               MovementActionDate,
               MovementActionTime,
               MovementActionUHFLogId,
               MovementActionDestinationId,
               MovementActionData,
               MovementActionUHFLogGate,
               MovementActionTp,
               MovementActionDocumentId,
               MovementActionDesc
        FROM FilteredMovements
    ) fm
    INNER JOIN ProductCounts pc 
        ON fm.MovementActionId = pc.MovementActionId
    LEFT JOIN tbl_User u 
        ON fm.MovementActionUserId = u.Id
    LEFT JOIN tbl_ActionTypes at 
        ON fm.MovementActionTp = at.fld_ActionTypeId
    LEFT JOIN tbl_Destination d 
        ON fm.MovementActionDestinationId = d.DestinationCode
    LEFT JOIN tbl_Destination d1 
        ON fm.MovementActionStore = d1.DestinationCode
    LEFT JOIN tbl_Station s 
        ON fm.MovementActionUHFLogGate = s.fld_StationCode
    WHERE pc.Count > 0 
      AND pc.SumCount > 0
    ORDER BY fm.MovementActionDate DESC, fm.MovementActionTime DESC
    """;

        return dataAccess.SqlDataAdapter(cmd, 120);
    }

    public DataTable SReportEnterActionByOpCode(List<ReportFilter> reportFilters)
