            }
            else if (filter.Type.Equals(FilterType.Static))
            {
                switch (filter.FieldName)
                {
                    case "OperationCode":
                        filter.SqlWhereCommand = "tm.RMovementActionId";
                        break;

                    case "ProductCode":
                        filter.SqlWhereCommand = "tm.ProductCode";
                        break;

                    case "TechnicalCode":
                        filter.SqlWhereCommand = "p.ProductTechnicalCode";
                        break;

                    case "FromDate":
                        filter.SqlWhereCommand = "ma.MovementActionDateTime";
                        filter.Values = filter.Values.Select(date => $"dbo.JalaliDateToGeorgianDate(N'{date}', N'06:00')").ToList();
                        break;

                    case "ToDate":
                        filter.SqlWhereCommand = "ma.MovementActionDateTime";
                        filter.Values = filter.Values.Select(date => $"dbo.JalaliDateToGeorgianDate(N'{date}', N'06:00')").ToList();
                        break;

                    case "GateOpCode":
                        filter.SqlWhereCommand = "ma.MovementActionUHFLogId";
                        break;

                    case "Destination":
                        filter.SqlWhereCommand = "ma.MovementActionDestinationId";
                        break;

                    case "Size":
                        filter.SqlWhereCommand = "p.ProductSize";
                        break;

                    case "ProductGroup":
                        filter.SqlWhereCommand = "p.fld_ProductGroup";
                        break;

                    case "ProductBrand":
                        filter.SqlWhereCommand = "p.fld_ProductBrand";
                        break;

                    case "ProductType":
                        filter.SqlWhereCommand = "p.ProductType";
                        break;

                    case "GateCode":
                        filter.SqlWhereCommand = "ma.MovementActionUHFLogGate";
                        break;

                    case "ActionType":
                        filter.SqlWhereCommand = "ma.MovementActionTp";
                        break;

                    case "Qc":
                        filter.SqlWhereCommand = "p.ProductStatus";
                        break;

                    case "DocumentKey":
                        filter.SqlWhereCommand = "ma.MovementActionDocumentId";
                        break;
                }

                if (filter.SqlWhereCommand.HasValue())
                {
                    whereList.Add(DynamicFilteringTools.GetStaticWhere(filter));
                }
            }
        }

        var cmd = @"
    SELECT TOP (6000)
           tm.ProductSerial,
           tm.ProductCode,
           p.ProductTitle AS ProductName,
           COALESCE(p.ProductTechnicalCode, N'') AS TechnicalCode,
           ps.ProductStatusTitle AS Qc,
           COALESCE(t.ProductCount, 0) AS ProductCount,
           p.ProductSize AS Size,
           COALESCE(pb.fld_ProductBrandTitle, N'') AS ProductBrand,
           COALESCE(pg.fld_ProductGroupTitle, N'') AS ProductGroup,
           COALESCE(pt.ProductTypeTitle, N'') AS ProductType,
           COALESCE(ma.MovementActionUHFLogGate, N'') AS GateCode,
           COALESCE(p.ProductTechnicalData, N'') AS TechnicalInfoData,
           COALESCE(s.fld_StationName, N'') AS StationName,
           COALESCE(t.ProductProperties, '{}') AS ProductProperties
    FROM tbl_MovementActions ma
    INNER JOIN tbl_TagsMovement tm 
        ON ma.MovementActionId = tm.RMovementActionId
    LEFT JOIN tbl_Products p 
        ON tm.ProductCode = p.ProductCode
    LEFT JOIN tbl_ProductStatus ps 
        ON p.ProductStatus = ps.ProductStatusCode
    LEFT JOIN tbl_ProductType pt 
        ON p.ProductType = pt.ProductTypeCode
    LEFT JOIN tbl_ProductBrand pb 
        ON p.fld_ProductBrand = pb.fld_ProductBrandCode
    LEFT JOIN tbl_ProductGroup pg 
        ON p.fld_ProductGroup = pg.fld_ProductGroupCode
    LEFT JOIN tbl_Tags t 
        ON tm.ProductSerial = t.ProductSerial
    LEFT JOIN tbl_Station s 
        ON ma.MovementActionUHFLogGate = s.fld_StationCode
    WHERE " + string.Join(" AND ", whereList) +
        " ORDER BY ma.MovementActionId DESC, tm.ProductSerial";

        return dataAccess.SqlDataAdapter(cmd);
    }

    public DataTable SReportEnterActionTajamoeeProductCode(List<ReportFilter> reportFilters)
    {
        List<string> whereList = new();
        whereList.Add("(tbl_TagsMovement.ProductCode IS NOT NULL)");

        List<string> subWhereList = new();
        subWhereList.Add("(tbl_TagsMovement_3.ProductCode = tbl_TagsMovement.ProductCode)");
        subWhereList.Add("(tbl_MovementActions_3.MovementActionTp = tbl_MovementActions.MovementActionTp)");
        subWhereList.Add("(tbl_MovementActions_3.MovementActionDestinationId = tbl_MovementActions.MovementActionDestinationId)");

        foreach (ReportFilter filter in reportFilters)
        {
            string subQueryWhereCommand = string.Empty;

            if (filter.SqlWhereCommand.HasValue())
            {
                continue;
            }

            if (filter.Type.Equals(FilterType.Dynamic))
            {
                if (filter.AdditionalData["DynamicFilterActionType"] == "1")
                {
                    whereList.Add(
                        $"""
                    (tbl_TagsMovement.ProductSerial IN (
                    SELECT ProductSerial FROM tbl_Tags AS Tags 
                    WHERE JSON_VALUE(Tags.ProductProperties,N'$."{filter.FieldName}"') IN(N'{string.Join("',N'", filter.Values)}')))
                    """);

                    subWhereList.Add(
                        $"""
                    (tbl_TagsMovement_3.ProductSerial 
                    IN (SELECT ProductSerial FROM tbl_Tags AS Tags_3 
                    WHERE JSON_VALUE(Tags_3.ProductProperties,N'$."{filter.FieldName}"') IN(N'{string.Join("',N'", filter.Values)}')))
                    """);
                }
                else
                {
                    filter.SqlWhereCommand = $"JSON_VALUE(tbl_MovementActions.MovementActionData,N'$.\"{filter.FieldName}\"')";
                    subQueryWhereCommand = $"JSON_VALUE(tbl_MovementActions_3.MovementActionData,N'$.\"{filter.FieldName}\"')";

                    whereList.Add(DynamicFilteringTools.GetDynamicWhere(filter));
                    subWhereList.Add(DynamicFilteringTools.GetDynamicWhere(filter).Replace(filter.SqlWhereCommand, subQueryWhereCommand));
                }
            }
            else if (filter.Type.Equals(FilterType.TechnicalInfo))
            {
                filter.SqlWhereCommand = $"JSON_VALUE(tbl_Products.ProductTechnicalData,N'$.\"{filter.FieldName}\"')";
                subQueryWhereCommand = $"JSON_VALUE(tbl_Products_3.ProductTechnicalData,N'$.\"{filter.FieldName}\"')";

                whereList.Add(DynamicFilteringTools.GetTechnicalInfoWhere(filter));
                subWhereList.Add(DynamicFilteringTools.GetTechnicalInfoWhere(filter).Replace(filter.SqlWhereCommand, subQueryWhereCommand));
            }
            else if (filter.Type.Equals(FilterType.Static))
            {
                switch (filter.FieldName)
                {
                    case "OperationCode":
                        filter.SqlWhereCommand = "MovementActionId";
                        subQueryWhereCommand = "tbl_MovementActions_3.MovementActionId";
                        break;

                    case "ProductCode":
                        filter.SqlWhereCommand = "tbl_TagsMovement.ProductCode";
                        subQueryWhereCommand = "tbl_TagsMovement_3.ProductCode";
                        break;

                    case "TechnicalCode":
                        filter.SqlWhereCommand = "tbl_Products.ProductTechnicalCode";
                        subQueryWhereCommand = "tbl_Products_3.ProductTechnicalCode";
                        break;

                    case "FromDate":
                        filter.SqlWhereCommand = "tbl_MovementActions.MovementActionDateTime";
                        subQueryWhereCommand = "tbl_MovementActions_3.MovementActionDateTime";
                        filter.Values = filter.Values.Select(date => $"dbo.JalaliDateToGeorgianDate(N'{date}', N'06:00')").ToList();
                        break;

                    case "ToDate":
                        filter.SqlWhereCommand = "tbl_MovementActions.MovementActionDateTime";
                        subQueryWhereCommand = "tbl_MovementActions_3.MovementActionDateTime";
                        filter.Values = filter.Values.Select(date => $"dbo.JalaliDateToGeorgianDate(N'{date}', N'06:00')").ToList();
                        break;

                    case "GateOpCode":
                        filter.SqlWhereCommand = "tbl_MovementActions.MovementActionUHFLogId";
                        subQueryWhereCommand = "tbl_MovementActions_3.MovementActionUHFLogId";
                        break;

                    case "Destination":
                        filter.SqlWhereCommand = "tbl_MovementActions.MovementActionDestinationId";
                        subQueryWhereCommand = "tbl_MovementActions_3.MovementActionDestinationId";
                        break;

                    case "Size":
                        filter.SqlWhereCommand = "tbl_Products.ProductSize";
                        subQueryWhereCommand = "tbl_Products_3.ProductSize";
                        break;

                    case "ProductGroup":
                        filter.SqlWhereCommand = "tbl_Products.fld_ProductGroup";
                        subQueryWhereCommand = "tbl_Products_3.fld_ProductGroup";
                        break;

                    case "ProductBrand":
                        filter.SqlWhereCommand = "tbl_Products.fld_ProductBrand";
                        subQueryWhereCommand = "tbl_Products_3.fld_ProductBrand";
                        break;

                    case "ProductType":
                        filter.SqlWhereCommand = "tbl_Products.ProductType";
                        subQueryWhereCommand = "tbl_Products_3.ProductType";
                        break;

                    case "GateCode":
                        filter.SqlWhereCommand = "tbl_MovementActions.MovementActionUHFLogGate";
                        subQueryWhereCommand = "tbl_MovementActions_3.MovementActionUHFLogGate";
                        break;

                    case "ActionType":
                        filter.SqlWhereCommand = "tbl_MovementActions.MovementActionTp";
                        subQueryWhereCommand = "tbl_MovementActions_3.MovementActionTp";
                        break;

                    case "Qc":
                        filter.SqlWhereCommand = "tbl_Products.ProductStatus";
                        subQueryWhereCommand = "tbl_Products_3.ProductStatus";
                        break;

                    case "DocumentKey":
                        filter.SqlWhereCommand = "tbl_MovementActions.MovementActionDocumentId";
                        subQueryWhereCommand = "tbl_MovementActions_3.MovementActionDocumentId";
                        break;
                }

                if (filter.SqlWhereCommand.HasValue())
                {
                    whereList.Add(DynamicFilteringTools.GetStaticWhere(filter));

                    if (subQueryWhereCommand.HasValue())
                    {
                        subWhereList.Add(DynamicFilteringTools.GetStaticWhere(filter).Replace(filter.SqlWhereCommand, subQueryWhereCommand));
                    }
                }
            }
        }

        var cmd = $"""
        WITH FilteredMovements AS
        (
            SELECT tbl_TagsMovement.ProductCode,
                   tbl_TagsMovement.ProductSerial,
                   tbl_Products.ProductTitle,
                   tbl_Products.ProductTechnicalCode,
                   tbl_Products.ProductStatus,
                   tbl_Products.ProductValue,
                   tbl_MovementActions.MovementActionDestinationId,
                   tbl_MovementActions.MovementActionTp,
                   tbl_ActionTypes.fld_ActionTypeTitle,
                   tbl_Destination.DestinationTitle,
                   tbl_Destination_1.DestinationTitle AS StoreTitle,
                   tbl_MovementActions.MovementActionId AS [OpCode]
            FROM tbl_Destination AS tbl_Destination_1
            RIGHT OUTER JOIN tbl_MovementActions 
                ON tbl_Destination_1.DestinationCode = tbl_MovementActions.MovementActionStore
            LEFT OUTER JOIN tbl_Destination 
                ON tbl_MovementActions.MovementActionDestinationId = tbl_Destination.DestinationCode
            LEFT OUTER JOIN tbl_ActionTypes 
                ON tbl_MovementActions.MovementActionTp = tbl_ActionTypes.fld_ActionTypeId
            LEFT OUTER JOIN tbl_TagsMovement 
            LEFT OUTER JOIN tbl_Products 
                ON tbl_TagsMovement.ProductCode = tbl_Products.ProductCode
                ON tbl_MovementActions.MovementActionId = tbl_TagsMovement.RMovementActionId
            {(whereList.Any() ? "WHERE " + string.Join(" AND ", whereList) : "")}
        ),
        ProductCounts AS
        (
            SELECT fm.ProductSerial,
                   COALESCE(t.ProductCount, 0) AS ProductCount
            FROM FilteredMovements fm
            LEFT JOIN tbl_Tags t ON fm.ProductSerial = t.ProductSerial
        )
        SELECT COALESCE(fm.ProductCode, N'') AS ProductCode,
               COALESCE(fm.ProductTitle, N'') AS ProductName,
               COALESCE(fm.ProductTechnicalCode, N'') AS TechnicalCode,
               COALESCE(fm.ProductStatus, N'') AS Qc,
               COUNT(DISTINCT fm.ProductSerial) AS Count,
               COALESCE(SUM(pc.ProductCount), 0) AS SumCount,
               COALESCE(CAST(fm.MovementActionDestinationId AS NVARCHAR(250)), N'') AS Destination,
               COALESCE(fm.MovementActionTp, 0) AS ActionType,
               COALESCE(fm.fld_ActionTypeTitle, N'') AS ActionTypeTitle,
               COALESCE(fm.DestinationTitle, N'') AS DestinationTitle,
               COALESCE(fm.StoreTitle, N'') AS StoreTitle,
               CAST(COALESCE(
                   CASE WHEN fm.ProductValue > 0 
                        THEN SUM(pc.ProductCount) / fm.ProductValue 
                        ELSE 0 
                   END, 0) AS DECIMAL(18,2)) AS ProductCountInPack,
               COALESCE(fm.OpCode, 0) AS OpCode
        FROM FilteredMovements fm
        LEFT JOIN ProductCounts pc ON fm.ProductSerial = pc.ProductSerial
        GROUP BY fm.ProductCode, fm.ProductTitle, fm.ProductTechnicalCode, 
                 fm.ProductStatus, fm.MovementActionDestinationId, fm.MovementActionTp,
                 fm.fld_ActionTypeTitle, fm.DestinationTitle, fm.StoreTitle, fm.ProductValue, fm.OpCode
        """;

        return dataAccess.SqlDataAdapter(cmd, 120);
    }

    public DataTable SReportEnterActionFull(List<ReportFilter> reportFilters)
    {
        List<string> whereList = new()
    {
        "ma.MovementActionId IS NOT NULL"
    };

        foreach (ReportFilter filter in reportFilters)
        {
            if (filter.SqlWhereCommand.HasValue())
            {
                continue;
            }

            if (filter.Type.Equals(FilterType.Dynamic))
            {
                if (filter.AdditionalData["DynamicFilterActionType"] == "1")
                {
                    whereList.Add(
                        $"""
                (JSON_VALUE(t.ProductProperties, N'$."{filter.FieldName}"') IN(N'{string.Join("',N'", filter.Values)}'))
                """);
                }
                else
                {
                    filter.SqlWhereCommand = $"JSON_VALUE(ma.MovementActionData, N'$.\"{filter.FieldName}\"')";
                    whereList.Add(DynamicFilteringTools.GetDynamicWhere(filter));
                }
            }
            else if (filter.Type.Equals(FilterType.TechnicalInfo))
            {
                filter.SqlWhereCommand = $"JSON_VALUE(p.ProductTechnicalData, N'$.\"{filter.FieldName}\"')";
                whereList.Add(DynamicFilteringTools.GetTechnicalInfoWhere(filter));
            }
            else if (filter.Type.Equals(FilterType.Static))
            {
                switch (filter.FieldName)
                {
                    case "OperationCode":
                        filter.SqlWhereCommand = "ma.MovementActionId";
                        break;

                    case "ProductCode":
                        filter.SqlWhereCommand = "tm.ProductCode";
                        break;

                    case "TechnicalCode":
                        filter.SqlWhereCommand = "p.ProductTechnicalCode";
                        break;

                    case "FromDate":
                        filter.SqlWhereCommand = "ma.MovementActionDateTime";
                        filter.Values = filter.Values.Select(date => $"dbo.JalaliDateToGeorgianDate(N'{date}', N'06:00')").ToList();
                        break;

                    case "ToDate":
                        filter.SqlWhereCommand = "ma.MovementActionDateTime";
                        filter.Values = filter.Values.Select(date => $"dbo.JalaliDateToGeorgianDate(N'{date}', N'06:00')").ToList();
                        break;

                    case "GateOpCode":
                        filter.SqlWhereCommand = "ma.MovementActionUHFLogId";
                        break;

                    case "Destination":
                        filter.SqlWhereCommand = "ma.MovementActionDestinationId";
                        break;

                    case "Size":
                        filter.SqlWhereCommand = "p.ProductSize";
                        break;

                    case "ProductGroup":
                        filter.SqlWhereCommand = "p.fld_ProductGroup";
                        break;

                    case "ProductBrand":
                        filter.SqlWhereCommand = "p.fld_ProductBrand";
                        break;

                    case "ProductType":
                        filter.SqlWhereCommand = "p.ProductType";
                        break;

                    case "GateCode":
                        filter.SqlWhereCommand = "ma.MovementActionUHFLogGate";
                        break;

                    case "ActionType":
                        filter.SqlWhereCommand = "ma.MovementActionTp";
                        break;

                    case "Qc":
                        filter.SqlWhereCommand = "p.ProductStatus";
                        break;

                    case "DocumentKey":
                        filter.SqlWhereCommand = "ma.MovementActionDocumentId";
                        break;

                    case "Line":
                        filter.SqlWhereCommand = "t.fld_ProductPropertyAId";
                        break;

                    case "Shift":
                        filter.SqlWhereCommand = "t.fld_ProductPropertyBId";
                        break;
                }

                if (filter.SqlWhereCommand.HasValue())
                {
                    whereList.Add(DynamicFilteringTools.GetStaticWhere(filter));
                }
            }
        }

        var cmd = @"
    SELECT TOP (300000)
           CAST(ma.MovementActionId AS NVARCHAR(250)) AS OpCode,
           ma.MovementActionDate + ' - ' + ma.MovementActionTime AS DateTime,
           ISNULL(CAST(tm.ProductSerial AS NVARCHAR(100)), N'') AS ProductSerial,
           ISNULL(tm.ProductCode, N'') AS ProductCode,
           ISNULL(p.ProductTitle, N'') AS ProductName,
           ISNULL(p.ProductSize, N'') AS Size,
           ISNULL(p.ProductTechnicalCode, N'') AS TechnicalCode,
           ISNULL(ps.ProductStatusTitle, N'') AS Qc,
           ISNULL(t.ProductCount, 0) AS Count,
           ISNULL(pa.fld_ProductPropertyATitle, N'') AS Line,
           ISNULL(pb.fld_ProductPropertyBTitle, N'') AS Shift,
           ISNULL(pg.fld_ProductGroupTitle, N'') AS ProductGroup,
           ISNULL(pbr.fld_ProductBrandTitle, N'') AS ProductBrand,
           ISNULL(pt.ProductTypeTitle, N'') AS ProductType,
           ISNULL(ma.MovementActionUHFLogGate, N'') AS GateCode,
           ISNULL(ma.MovementActionDocumentId, N'') AS ActionDocumentId,
           ISNULL(CAST(ma.MovementActionDestinationId AS NVARCHAR(250)), N'') AS Destination,
           ISNULL(ma.MovementActionTp, 0) AS ActionType,
           ISNULL(at.fld_ActionTypeTitle, N'') AS ActionTypeTitle,
           ISNULL(d.DestinationTitle, N'') AS DestinationTitle,
           ISNULL(d1.DestinationTitle, N'') AS StoreTitle,
           ISNULL(p.ProductTechnicalData, N'') AS TechnicalInfoData,
           ISNULL(ma.MovementActionDesc, N'') AS MovementActionDesc,
           ISNULL(z.ZoneTitle, N'') AS ZoneTitle,
           ISNULL(s.fld_StationName, N'') AS StationName,
           ISNULL(t.ProductProperties, '{}') AS ProductProperties,
           ma.MovementActionId AS SortMovementActionId,
           tm.ProductSerial AS SortProductSerial,
           COALESCE((SELECT tbl_User.[Name] 
                         FROM tbl_User 
                         WHERE (TRY_CONVERT(uniqueidentifier, ma.MovementActionUserId) IS NOT NULL AND tbl_User.Id = ma.MovementActionUserId) OR
                         (tbl_User.Username = ma.MovementActionUserId)
                         ), N'') AS Username,
           COALESCE(ma.MovementActionData,N'{}') AS [MovementActionData]
    FROM tbl_MovementActions ma
    INNER JOIN tbl_TagsMovement tm 
        ON ma.MovementActionId = tm.RMovementActionId
    LEFT JOIN tbl_Products p 
        ON tm.ProductCode = p.ProductCode
    LEFT JOIN tbl_ProductType pt 
        ON p.ProductType = pt.ProductTypeCode
    LEFT JOIN tbl_ProductBrand pbr 
        ON p.fld_ProductBrand = pbr.fld_ProductBrandCode
    LEFT JOIN tbl_ProductGroup pg 
        ON p.fld_ProductGroup = pg.fld_ProductGroupCode
    LEFT JOIN tbl_ActionTypes at 
        ON ma.MovementActionTp = at.fld_ActionTypeId
    LEFT JOIN tbl_Destination d 
        ON ma.MovementActionDestinationId = d.DestinationCode
    LEFT JOIN tbl_Destination d1 
        ON ma.MovementActionStore = d1.DestinationCode
    LEFT JOIN tbl_Tags t 
        ON tm.ProductSerial = t.ProductSerial
    LEFT JOIN tbl_ProductPropertyA pa 
        ON t.fld_ProductPropertyAId = pa.fld_ProductPropertyAId
    LEFT JOIN tbl_ProductPropertyB pb 
        ON t.fld_ProductPropertyBId = pb.fld_ProductPropertyBId
    LEFT JOIN tbl_ProductStatus ps 
        ON p.ProductStatus = ps.ProductStatusCode
    LEFT JOIN tbl_Zones z 
        ON t.TagZone = z.ZoneCode
    LEFT JOIN tbl_Station s 
        ON ma.MovementActionUHFLogGate = s.fld_StationCode
    WHERE " + string.Join(" AND ", whereList) +
            " ORDER BY SortMovementActionId DESC, SortProductSerial";

        return dataAccess.SqlDataAdapter(cmd, 120);
    }

    public DataTable SSearchProductForLocate(List<ReportFilter> reportFilters)
    {
        List<string> whereList = new();

        foreach (ReportFilter filter in reportFilters)
        {
            if (filter.SqlWhereCommand.HasValue())
            {
                continue;
            }

            if (filter.Type.Equals(FilterType.Dynamic))
            {
                filter.SqlWhereCommand = $"JSON_VALUE(tbl_MovementActions.MovementActionData,N'$.\"{filter.FieldName}\"')";

                whereList.Add(DynamicFilteringTools.GetDynamicWhere(filter));
            }
            else if (filter.Type.Equals(FilterType.TechnicalInfo))
            {
                filter.SqlWhereCommand = $" JSON_VALUE(tbl_Products.ProductTechnicalData,N'$.\"{filter.FieldName}\"')";

                whereList.Add(DynamicFilteringTools.GetTechnicalInfoWhere(filter));
            }
            else if (filter.Type.Equals(FilterType.Static))
            {
                switch (filter.FieldName)
                {
                    case "ProductCode":
                        filter.SqlWhereCommand = "Tags.ProductCode";
                        break;

                    case "TechnicalCode":
                        filter.SqlWhereCommand = "tbl_Products.ProductTechnicalCode";
                        break;

                    case "FromDate":
                        filter.SqlWhereCommand = "tbl_MovementActions.MovementActionDateTime";
                        filter.Values = filter.Values.Select(date => $"dbo.JalaliDateToGeorgianDate(N'{date}', N'06:00')").ToList();
                        break;

                    case "ToDate":
                        filter.SqlWhereCommand = $"tbl_MovementActions.MovementActionDateTime";
                        filter.Values = filter.Values.Select(date => $"dbo.JalaliDateToGeorgianDate(N'{date}', N'06:00')").ToList();
                        break;

                    case "Destination":
                        filter.SqlWhereCommand = $"Tags.TagInDestinationId";
                        break;

                    case "Size":
                        filter.SqlWhereCommand = $"tbl_Products.ProductSize";
                        break;

                    case "ProductGroup":
                        filter.SqlWhereCommand = $"tbl_Products.fld_ProductGroup";
                        break;

                    case "ProductBrand":
                        filter.SqlWhereCommand = $"tbl_Products.fld_ProductBrand";
                        break;

                    case "ProductType":
                        filter.SqlWhereCommand = $"tbl_Products.ProductType";
                        break;

                    case "Zone":
                        filter.SqlWhereCommand = $"Tags.TagZone";
                        break;

                    case "Qc":
                        filter.SqlWhereCommand = $"tbl_Products.ProductStatus";
                        break;
                }

                if (filter.SqlWhereCommand.HasValue())
                {
                    whereList.Add(DynamicFilteringTools.GetStaticWhere(filter));
                }
            }
        }

        var dtProducts = new DataTable();

        var cmd = """
            SELECT DISTINCT 
                    CAST(Tags.ProductSerial AS NVARCHAR(100)) AS ProductSerial,
                    Tags.ProductCode,
            		COALESCE (tbl_Products.ProductTitle, N'') AS ProductName,
                    COALESCE (tbl_ProductPropertyC.fld_ProductPropertyCTitle, N'') AS Size, 
                    COALESCE(tbl_Products.ProductTechnicalCode,N'') AS TechnicalCode,
                    COALESCE (tbl_ProductStatus.ProductStatusTitle, N'') AS Qc,
                    COALESCE (Tags.ProductCount, 0) AS [Count],
                    COALESCE (tbl_ProductPropertyA.fld_ProductPropertyATitle, N'') AS Line, 
                    COALESCE (tbl_ProductPropertyB.fld_ProductPropertyBTitle, N'') AS Shift, 
                    COALESCE (tbl_ProductGroup.fld_ProductGroupTitle, N'') AS ProductGroup, 
                    COALESCE (tbl_ProductBrand.fld_ProductBrandTitle, N'') AS ProductBrand, 
                    COALESCE (tbl_ProductType.ProductTypeTitle, N'') AS ProductType,
                    COALESCE (tbl_Destination.DestinationTitle, N'') AS StoreTitle,
                    COALESCE(tbl_Zones.ZoneTitle, N'') AS ZoneTitle,
                    COALESCE(tbl_Products.ProductTechnicalData, N'{}') AS TechnicalInfoData
            FROM    tbl_Tags AS Tags LEFT OUTER JOIN
                    tbl_MovementActions ON Tags.TagInActionId = tbl_MovementActions.MovementActionId LEFT OUTER JOIN
                    tbl_Products ON Tags.ProductCode = tbl_Products.ProductCode LEFT OUTER JOIN
                    tbl_ProductType ON tbl_Products.ProductType = tbl_ProductType.ProductTypeCode LEFT OUTER JOIN
                    tbl_ProductBrand ON tbl_Products.fld_ProductBrand = tbl_ProductBrand.fld_ProductBrandCode LEFT OUTER JOIN
                    tbl_ProductGroup ON tbl_Products.fld_ProductGroup = tbl_ProductGroup.fld_ProductGroupCode RIGHT OUTER JOIN
                    tbl_Destination ON tbl_Destination.DestinationCode = Tags.TagInDestinationId  LEFT OUTER JOIN
                    tbl_ProductPropertyB ON Tags.fld_ProductPropertyBId = tbl_ProductPropertyB.fld_ProductPropertyBId LEFT OUTER JOIN
                    tbl_ProductPropertyC ON Tags.fld_ProductPropertyCId = tbl_ProductPropertyC.fld_ProductPropertyCId LEFT OUTER JOIN
                    tbl_ProductPropertyA ON Tags.fld_ProductPropertyAId = tbl_ProductPropertyA.fld_ProductPropertyAId  LEFT OUTER JOIN
                    tbl_ProductStatus ON tbl_Products.ProductStatus = tbl_ProductStatus.ProductStatusCode LEFT OUTER JOIN
                    tbl_Zones ON tbl_Zones.ZoneCode = Tags.TagZone
            """ + (whereList.Any() ? " WHERE " + string.Join(" AND ", whereList) : "");

        dtProducts = dataAccess.SqlDataAdapter(cmd, 120);
        return dtProducts;
    }


    public DataTable SReportUhfLog(List<ReportFilter> reportFilters)
    {
        List<string> whereList = new();

        // whereList.Add("(UHF.fld_Reader_GateType = N'_DETECT_PRODUCT_AND_SEND_TO_WEB_')");
        whereList.Add("(UHF.fld_TagSerial <> N'000')");

        List<string> nestedWhereList = new();

        foreach (ReportFilter filter in reportFilters)
        {
            bool isNested = false;

            if (filter.SqlWhereCommand.HasValue())
            {
                continue;
            }

            if (filter.Type.Equals(FilterType.Static))
            {
                switch (filter.FieldName)
                {
                    case "FromDate":
                        filter.SqlWhereCommand = "SUBSTRING(DateTime,1,8)";
                        filter.Values = filter.Values
                            .Select(date => $"{date.Replace("/", "")}")
                            .ToList();
                        isNested = true;
                        break;

                    case "ToDate":
                        filter.SqlWhereCommand = "SUBSTRING(DateTime,1,8)";
                        filter.Values = filter.Values
                            .Select(date => $"{date.Replace("/", "")}")
                            .ToList();
                        isNested = true;
                        break;

                    case "FromTime":
                        filter.SqlWhereCommand = "SUBSTRING(DateTime,9,6)";
                        filter.Values = filter.Values
                            .Select(date => $"{date.Replace(":", "")}00")
                            .ToList();
                        isNested = true;
                        break;

                    case "ToTime":
                        filter.SqlWhereCommand = "SUBSTRING(DateTime,9,6)";
                        filter.Values = filter.Values
                            .Select(date => $"{date.Replace(":", "")}00")
                            .ToList();
                        isNested = true;
                        break;

                    case "RegUesr":
                        filter.SqlWhereCommand = "UHF.fld_SaveUserId";
                        break;

                    case "ProductCode":
                        filter.SqlWhereCommand = "Tags.ProductCode";
                        break;

                    case "ProductSerial":
                        filter.SqlWhereCommand = "Tags.ProductSerial";
                        break;

                    case "InventoryId":
                        filter.SqlWhereCommand = "UHF.fld_InventoryId";
                        break;

                    case "ActionStatus":
                        filter.SqlWhereCommand = "UHF.ActionStatus";
                        break;

                    case "Station":
                        filter.SqlWhereCommand = "UHF.fld_Reader_Gate";
                        break;
                }

                if (filter.SqlWhereCommand.HasValue())
                {
                    if (isNested)
                    {
                        nestedWhereList.Add(
                            DynamicFilteringTools.GetStaticWhere(filter));
                    }
                    else
                    {
                        var staticWhere = DynamicFilteringTools.GetStaticWhere(filter);

                        if (filter.FieldName == "ProductCode" || filter.FieldName == "ProductSerial")
                        {
                            whereList.Add(staticWhere);
                        }
                        else
                        {
                            whereList.Add(staticWhere);
                        }
                    }

                    isNested = false;
                }
            }
        }

        var sqlCommand = $"""
            ;WITH ALL_LOGS AS
(
    SELECT
        UHF.fld_InventoryId,
        UHF.fld_Reader_Gate AS ReaderGateCode,
        ISNULL(ST.fld_StationName,N'') AS ReaderGateName,
        UHF.fld_SaveUserId,
        UHF.ActionStatus,
        UHF.ActionDesc,
        UHF.fld_TagRead_DateTime,
        UHF.fld_TagSerial,
        Tags.ProductCount
      FROM tbl_UHF_ReaderLog UHF
      LEFT JOIN tbl_Tags Tags ON UHF.fld_TagSerial = Tags.TagEpc
      LEFT JOIN tbl_Station ST  ON ST.fld_StationCode = UHF.fld_Reader_Gate

    {(whereList.Any()
        ? " WHERE " + string.Join(" AND ", whereList)
        : "")}

    UNION ALL

    SELECT
        UHF.fld_InventoryId,
        UHF.fld_Reader_Gate AS ReaderGateCode,
        ISNULL(ST.fld_StationName,N'') AS ReaderGateName,
        UHF.fld_SaveUserId,
        UHF.ActionStatus,
        UHF.ActionDesc,
        UHF.fld_TagRead_DateTime,
        UHF.fld_TagSerial,
        Tags.ProductCount
    FROM tbl_UHF_ReaderLogMain UHF
    LEFT JOIN tbl_Tags Tags ON UHF.fld_TagSerial = Tags.TagEpc
    LEFT JOIN tbl_Station ST ON ST.fld_StationCode = UHF.fld_Reader_Gate

    {(whereList.Any()
        ? " WHERE " + string.Join(" AND ", whereList)
        : "")}
),

FINAL_DATA AS
(
    SELECT
        fld_InventoryId,
        ReaderGateCode,
        ReaderGateName,
        COALESCE(
            CASE
                WHEN TRY_CONVERT(
                    UNIQUEIDENTIFIER,
                    fld_SaveUserId
                ) IS NOT NULL
                THEN
                (
                    SELECT Username
                    FROM tbl_User
                    WHERE Id = ALL_LOGS.fld_SaveUserId
                )

                ELSE fld_SaveUserId
            END,
            N''
        ) AS Username,
        ActionStatus,
        MAX(ActionDesc) AS ActionDesc,
        MIN(fld_TagRead_DateTime) AS DateTime,
        COUNT(fld_TagSerial) AS CountTag,
        COUNT(CASE WHEN ActionStatus = 0 THEN fld_TagSerial END) AS CountTagOk,
        SUM(ISNULL(ProductCount,0)) AS SumValue

    FROM ALL_LOGS

    GROUP BY
        fld_InventoryId,
        ReaderGateCode,
        ReaderGateName,
        fld_SaveUserId,
        ActionStatus
)

SELECT
      CAST(fld_InventoryId AS NVARCHAR(100)) AS InventoryId,
      ISNULL(ReaderGateCode,N'') AS ReaderGateCode,
      ISNULL(ReaderGateName,N'') AS ReaderGateName,
      Username,
      ISNULL(DateTime,N'') AS DateTime,
      ISNULL(ActionDesc,N'') AS ActionDesc,
      ISNULL( CAST(ActionStatus AS NVARCHAR(10)), N'' ) AS ActionStatus,
      CountTag,
      CountTagOk,
      SumValue

    FROM FINAL_DATA

{(
nestedWhereList.Any()
    ? " WHERE " + string.Join(" AND ", nestedWhereList)
    : ""
)}

ORDER BY fld_InventoryId
""";

        return dataAccess.SqlDataAdapter(sqlCommand, 120);
    }

    public DataTable SReportUhfLogBySerials(List<ReportFilter> reportFilters)
    {
        List<string> uhfWhereList = new();
        List<string> tagWhereList = new();

        // uhfWhereList.Add("UHF.fld_Reader_GateType = N'_DETECT_PRODUCT_AND_SEND_TO_WEB_'");
        uhfWhereList.Add("UHF.fld_TagSerial <> N'000'");

        bool hasProductFilter = false;

        foreach (ReportFilter filter in reportFilters)
        {
            if (filter.Type != FilterType.Static)
                continue;

            if (!filter.SqlWhereCommand.HasValue())
            {
                switch (filter.FieldName)
                {
                    case "FromDate":
                        uhfWhereList.Add(
                            $"UHF.fld_TagRead_DateTime >= N'{filter.Values.First().Replace("/", "")}000000'");
                        break;

                    case "ToDate":
                        uhfWhereList.Add(
                            $"UHF.fld_TagRead_DateTime <= N'{filter.Values.First().Replace("/", "")}235959'");
                        break;

                    case "FromTime":
                        uhfWhereList.Add(
                            $"SUBSTRING(UHF.fld_TagRead_DateTime,9,6) >= N'{filter.Values.First().Replace(":", "")}00'");
                        break;

                    case "ToTime":
                        uhfWhereList.Add(
                            $"SUBSTRING(UHF.fld_TagRead_DateTime,9,6) <= N'{filter.Values.First().Replace(":", "")}00'");
                        break;

                    case "Station":
                        filter.SqlWhereCommand = "UHF.fld_Reader_Gate";
                        uhfWhereList.Add(
                            DynamicFilteringTools.GetStaticWhere(filter));
                        break;

                    case "RegUesr":
                        filter.SqlWhereCommand = "UHF.fld_SaveUserId";
                        uhfWhereList.Add(
                            DynamicFilteringTools.GetStaticWhere(filter));
                        break;

                    case "InventoryId":
                        filter.SqlWhereCommand = "UHF.fld_InventoryId";
                        uhfWhereList.Add(
                            DynamicFilteringTools.GetStaticWhere(filter));
                        break;

                    case "ActionStatus":
                        {
                            if (
                                filter.Values == null ||
                                filter.Values.All(string.IsNullOrWhiteSpace)
                            )
                            {
                                break;
                            }

                            filter.SqlWhereCommand = "UHF.ActionStatus";
                            uhfWhereList.Add(
                                DynamicFilteringTools.GetStaticWhere(filter));
                            break;
                        }

                    case "ProductCode":
                        filter.SqlWhereCommand = "Tags.ProductCode";

                        tagWhereList.Add(
                            DynamicFilteringTools.GetStaticWhere(filter));

                        hasProductFilter = true;
                        break;

                    case "ProductSerial":
                        filter.SqlWhereCommand = "Tags.ProductSerial";

                        tagWhereList.Add(
                            DynamicFilteringTools.GetStaticWhere(filter));

                        hasProductFilter = true;
                        break;
                }
            }
        }

        string uhfWhere = uhfWhereList.Any()
            ? "WHERE " + string.Join(" AND ", uhfWhereList)
            : "";

        string tagWhere = tagWhereList.Any()
            ? "AND " + string.Join(" AND ", tagWhereList)
            : "";

        string finalTagFilter = hasProductFilter
            ? "WHERE Tags.TagEpc IS NOT NULL"
            : "";

        var sqlCommand = $@"

;WITH UHF_DATA AS
(
    SELECT 
        fld_InventoryId,
        fld_TagSerial,
        fld_TagRead_DateTime,
        ActionStatus
    FROM tbl_UHF_ReaderLog UHF

    {uhfWhere}

    UNION ALL

    SELECT 
        fld_InventoryId,
        fld_TagSerial,
        fld_TagRead_DateTime,
        ActionStatus
    FROM tbl_UHF_ReaderLogMain UHF

    {uhfWhere}
)

SELECT
      ISNULL( Tags.ProductSerial, N'رجیستر نشده' ) AS ProductSerial,
      ISNULL( UHF_DATA.fld_TagSerial, N'' ) AS EPC,
      ISNULL(Tags.ProductCode,  N'' ) AS ProductCode,
      ISNULL( Tags.RegCode, N'') AS RegCode,
      ISNULL( Tags.ProductName, N'' ) AS ProductTitle,
      ISNULL( SUBSTRING(UHF_DATA.fld_TagRead_DateTime,1,8), N'' ) AS [Date],
      ISNULL( SUBSTRING(UHF_DATA.fld_TagRead_DateTime,9,6), N'' ) AS [Time],
      UHF_DATA.fld_TagRead_DateTime AS [DateTime],
      ISNULL(Tags.ProductCount, 0) AS ProductCount,
      ISNULL(UHF_DATA.ActionStatus, -1)  AS ActionStatus
     FROM UHF_DATA
     LEFT JOIN tbl_Tags Tags ON UHF_DATA.fld_TagSerial = Tags.TagEpc
    {tagWhere}

{finalTagFilter}

ORDER BY
    Tags.ProductSerial DESC
";

        return dataAccess.SqlDataAdapter(sqlCommand, 120);
    }

    public DataTable SReportUhfLogByProducts(List<ReportFilter> reportFilters)
    {
        List<string> whereList = new();
        List<string> nestedWhereList = new();
        List<string> groupBy = new();

        whereList.Add("UHF.fld_TagSerial <> N'000'");
        whereList.Add("UHF.ActionStatus = 0 ");
        // whereList.Add("UHF.fld_Reader_GateType = N'_DETECT_PRODUCT_AND_SEND_TO_WEB_'");

        foreach (var filter in reportFilters)
        {
            bool isNested = false;

            if (filter.Type != FilterType.Static)
                continue;

            switch (filter.FieldName)
            {
                case "FromDate":

                    filter.SqlWhereCommand =
                        "SUBSTRING([NESTED].[DateTime],1,8)";

                    filter.Values = filter.Values
                        .Select(date => date.Replace("/", ""))
                        .ToList();

                    isNested = true;

                    break;

                case "ToDate":

                    filter.SqlWhereCommand =
                        "SUBSTRING([NESTED].[DateTime],1,8)";

                    filter.Values = filter.Values
                        .Select(date => date.Replace("/", ""))
                        .ToList();

                    isNested = true;

                    break;

                case "FromTime":

                    filter.SqlWhereCommand =
                        "SUBSTRING([NESTED].[DateTime],9,6)";

                    filter.Values = filter.Values
                        .Select(date => $"{date.Replace(":", "")}00")
                        .ToList();

                    isNested = true;

                    break;

                case "ToTime":

                    filter.SqlWhereCommand =
                        "SUBSTRING([NESTED].[DateTime],9,6)";

                    filter.Values = filter.Values
                        .Select(date => $"{date.Replace(":", "")}00")
                        .ToList();

                    isNested = true;

                    break;

                case "ProductCode":

                    filter.SqlWhereCommand =
                        "Tags.ProductCode";

                    break;

                case "ProductSerial":

                    filter.SqlWhereCommand =
                        "Tags.ProductSerial";

                    break;

                case "Station":

                    filter.SqlWhereCommand =
                        "UHF.fld_Reader_Gate";

                    break;

                case "RegUesr":

                    filter.SqlWhereCommand =
                        "UHF.fld_SaveUserId";

                    break;

                case "ActionStatus":

                    filter.SqlWhereCommand =
                        "UHF.ActionStatus";

                    break;

                case "InventoryId":

                    filter.SqlWhereCommand =
                        "UHF.fld_InventoryId";

                    break;
            }

            if (filter.SqlWhereCommand.HasValue())
            {
                if (isNested)
                {
                    nestedWhereList.Add(
                        DynamicFilteringTools.GetStaticWhere(filter));
                }
                else
                {

                    if (
                        filter.FieldName == "ActionStatus" &&
                        filter.Values.Any(v => string.IsNullOrWhiteSpace(v))
                    )
                    {
                        whereList.Add(
                            "(ISNULL(UHF.ActionStatus,N'') = N'')");
                    }
                    else
                    {
                        whereList.Add(
                            DynamicFilteringTools.GetStaticWhere(filter));
                    }
                }
            }
        }


        groupBy.Add("[NESTED].ProductCode");
        groupBy.Add("[NESTED].fld_Reader_Gate");
        groupBy.Add("[NESTED].ActionStatus");

        string sql = $@"
;WITH ALL_DATA AS
(
    SELECT
        Tags.ProductSerial,
        Tags.ProductCode,
        Tags.RegCode,
        Tags.ProductName,
        Tags.ProductCount,
        UHF.fld_TagSerial,
        UHF.fld_TagRead_DateTime AS [DateTime],
        UHF.fld_Reader_Gate,
        UHF.ActionStatus
      FROM tbl_UHF_ReaderLog UHF
      LEFT JOIN tbl_Tags Tags ON UHF.fld_TagSerial = Tags.TagEpc

    {(whereList.Any()
            ? "WHERE " + string.Join(" AND ", whereList)
            : "")}

    UNION ALL

    SELECT
        Tags.ProductSerial,
        Tags.ProductCode,
        Tags.RegCode,
        Tags.ProductName,
        Tags.ProductCount,
        UHF.fld_TagSerial,
        UHF.fld_TagRead_DateTime AS [DateTime],
        UHF.fld_Reader_Gate,
        UHF.ActionStatus
      FROM tbl_UHF_ReaderLogMain UHF
      LEFT JOIN tbl_Tags Tags ON UHF.fld_TagSerial = Tags.TagEpc

    {(whereList.Any()
            ? "WHERE " + string.Join(" AND ", whereList)
            : "")})

     SELECT
       ISNULL( MAX([NESTED].ProductCode), N'رجیستر نشده') AS ProductCode,
       ISNULL(MAX([NESTED].RegCode), N'') AS RegCode,
       ISNULL(MAX([NESTED].ProductName), N'' ) AS ProductTitle,
       ISNULL([NESTED].fld_Reader_Gate, N'' ) AS ReaderGate,
       ISNULL( CAST([NESTED].ActionStatus AS NVARCHAR(10)), N'' ) AS ActionStatus,
       SUM(ISNULL([NESTED].ProductCount,0)) AS SumValue,
       COUNT([NESTED].fld_TagSerial) AS [Count]

     FROM ALL_DATA AS [NESTED]

{(
        nestedWhereList.Any()
            ? "WHERE " + string.Join(" AND ", nestedWhereList)
            : ""
    )}

GROUP BY
    {string.Join(",", groupBy)}

ORDER BY
    MAX([NESTED].ProductCode) DESC
";

        return dataAccess.SqlDataAdapter(sql, 120);
    }

    public bool SCheckExistNewSerial(string productSerial, string productCode, string productProductionLine = "", string productProductionShift = "")
    {
        if (configuration.GetSection("ProjectConfigs").GetSection("WmsConfigs")["CreateNewSerial"].ToString() != "")
        {
            productSerial = SCreateNewSerial(productSerial, productCode, "-1", "", configuration.GetSection("ProjectConfigs").GetSection("WmsConfigs")["CreateNewSerial"].ToString(), productProductionLine, productProductionShift);
        }

        var commandCheckExistSerialIntbl_Tags = @"SELECT        Top(1) Id
                                        FROM            tbl_Tags
                                        WHERE (ProductSerial = N'" + productSerial + "')";
        var CheckExistSerialIntbl_Tags = dataAccess.SqlDataReaders(commandCheckExistSerialIntbl_Tags);
        if (CheckExistSerialIntbl_Tags == null)
        {
            return false;
        }
        else
        {
            return true;
        }
    }

