            ;

            parameters1.Add(new("MovementActionId", actionId));
            parameters1.Add(new("UserId", ActionUser));
            parameters1.Add(new("Date", DateTimeTools.GetPersianDate()));
            parameters1.Add(new("Time", DateTime.Now.Hour.ToString().PadLeft(2, '0') + ":" + DateTime.Now.Minute.ToString().PadLeft(2, '0')));
