                    var parameters3 = new List<KeyValuePair<string, object>>();
                    var commandTagMovementActionInsert = string.Format(@"INSERT INTO tbl_TagsMovement (
														TagEpc,
														ProductCode,
														ProductSerial,
														ProductCount,
														RMovementActionId,
														RTagsMovementDate,
