                var commandUpdateTagStatus = string.Format(@" UPDATE tbl_Tags SET TagStatus= @StCd, TagInActionId = @ActId, TagInDestinationId = @DestId,TagZone=@TagZone WHERE (ProductSerial = @ProductSerial ) OR (TagEpc=@ProductSerial)");
