        void ChangeDocumentStatus()
        {
            string newStatus = apiContext.ActionTypes.FirstOrDefault(p => p.Code == int.Parse(actionTypeStr))?.DocStatusChange;

            if (MovementActionDocumentId.HasValue() && newStatus != "0")
            {
                SaveDocumentStatusCommand changeStatus = new()
                {
                    DocumentKeyTypes = new(),
                    NewStatus = int.Parse(newStatus),
                    Description = $"تغییر وضعیت سند در عملیات {apiContext.ActionTypes.FirstOrDefault(p => p.Code == int.Parse(actionTypeStr))?.Title}",
                    User = ActionUser
                };

                DocumentKeyTypeDto keyType = new()
                {
                    Key = MovementActionDocumentId,
                    Type = actionTypeStr
                };

                changeStatus.DocumentKeyTypes.Add(keyType);

                SChangeDocumentStatus(changeStatus);
            }
        }

        void ChangePlacementOrderStatus()
        {
            if ((actionTypeStr == "4" || actionTypeStr == "6") && MovementActionDocumentId != "" && MovementActionDocumentId != "0")
            {
                var command = @"UPDATE        tbl_PlacementOrders SET             fld_POStatus = 2 WHERE        (fld_POType = 3) AND (fld_POStatus = 1) and  (fld_PODocumentKey=@DocumentId) AND (fld_PODocumentType IN (4,6)) ";
                dataAccess.CmdSqlExecuteNonQuery(command, new KeyValuePair<string, object>("DocumentId", MovementActionDocumentId));
            }
        }

        void SetProductGuarantees()
        {
            if (configuration["ProjectConfigs:WmsConfigs:SetProductGuarantees"].Equals("true"))
            {
                List<string> _ListProductCodes = new();

                foreach (GateResult _tag in _listGateResult)
                {
                    if (_ListProductCodes.FirstOrDefault(p => p.ToString() == _tag.ProductCode) == null)
                    {
                        _ListProductCodes.Add(_tag.ProductCode);
                    }
                }

                var CmdGetProductGuaranteesTypeAndValue = $"""
                    SELECT     ProductCode,  fld_ProductGuaranteeType, COALESCE(fld_ProductGuaranteeMonths,0)  
                    FROM tbl_Products WHERE  (ProductCode IN ('{string.Join("','", _ListProductCodes)}')) 
                    """;

                var _dtProductGuaranteesTypeAndValue = dataAccess.SqlDataAdapter(CmdGetProductGuaranteesTypeAndValue);

                foreach (DataRow _drProductGuarantees in _dtProductGuaranteesTypeAndValue.Rows)
                {
                    Enum.TryParse<GuaranteeTypes>(_drProductGuarantees[1].ToString(), out GuaranteeTypes gType);

                    bool FlagSetGuarantees = false;

                    switch (gType)
                    {
                        case GuaranteeTypes.EnterToWarehouse:
                            if (actionTypeStr == "2")
                            {
                                FlagSetGuarantees = true;
                            }
                            break;
                        case GuaranteeTypes.ExitFromWarehouse:
                            if (actionTypeStr == "4")
                            {
                                FlagSetGuarantees = true;
                            }
                            break;
                        case GuaranteeTypes.ExitFromFactory:
                            if (actionTypeStr == "6")
                            {
                                FlagSetGuarantees = true;
                            }
                            break;
                    }

                    if (FlagSetGuarantees)
                    {
                        PersianCalendar pc = new();

                        SaveProductGuaranteesCommand _saveProductGuaranteesCommand = new SaveProductGuaranteesCommand()
                        {
                            GuaranteeActivationType = gType,
                            GuaranteeStartDate = DateTimeTools.GetPersianDate(),
                            GuaranteedEndDate = DateTimeTools.ConvertMiladi2ShamsiDate(pc.AddMonths(DateTime.Now, (int)_drProductGuarantees[2])),
                            GuaranteeStatus = "1",
                            ProductSerials = _listGateResult.Where(p => p.ProductCode == _drProductGuarantees[0].ToString()).Select(p => p.ProductSerial).ToList()
                        };

                        var result = productBusiness.SSaveProductGuarantees(_saveProductGuaranteesCommand);
                    }
                }
            }
        }
    }


    /// <summary>
    /// این متد یا از طریق کد عملیات شناسایی، یا از طریق لیست تگ های قرائت شده 
    /// و یا از طریق لیست سریال ها به همراه عملیات های مربوط به این سریال ها استفاده میشوند.
    /// LogGateActionId: میتواند بدون مقدار باشد که با -1 پر میشود، میتواند با یک مقدار و میتواند با چند مقدار به کمک , از هم جدا شده اند پر شده باشد
    /// </summary>
    /// <param name="LogGateActionId"></param>
    /// <param name="ActionSourceLocation"></param>
    /// <param name="ActionDestinationLocation"></param>
    /// <param name="GateCode"></param>
    /// <param name="ActionUser"></param>
    /// <param name="PMCode"></param>
    /// <param name="ActionData"></param>
    /// <param name="ActionDestinationZoneCode"></param>
    /// <param name="MovementActionDesc"></param>
    /// <param name="MovementActionDocumentId"></param>
    /// <param name="MovementActionTruckCrossId"></param>
    /// <param name="Serials"></param>
    /// <returns></returns>
    public bool SSaveMovementAction2(
        string LogGateActionId
      , string ActionSourceLocation
      , string ActionDestinationLocation
      , string GateCode
      , string ActionUser
      , string PMCode
      , JToken ActionData
      , string ActionDestinationZoneCode = "0"
      , string MovementActionDesc = ""
      , string MovementActionDocumentId = ""
      , string MovementActionTruckCrossId = "0"
      , List<string> Serials = null
      , List<int> LogGateActionIds = null
      , DateTime? saveDateTime = null)
    {
        var _listAllWarehouseDto = SGetAllWarehouses();
        List<GateResult> _listGateResult = new();

        List<KeyValuePair<string, KeyValuePair<string, object>[]>> commands = new();

        string actionTypeStr = "-1";
        ActionType  ActionTypeData;

        string ActionTypeChangeTagLocation = "0";

        string _listProductSerials = "";

        if (LogGateActionId == "-1" || IsUhfLogIdUnique())
        {

            var command = @"UPDATE       tbl_UHF_ReaderLog
SET                fld_ProductSerial = tbl_Tags.ProductSerial
FROM            tbl_UHF_ReaderLog LEFT OUTER JOIN
                         tbl_Tags ON tbl_UHF_ReaderLog.fld_TagSerial = tbl_Tags.TagEpc
WHERE        (tbl_UHF_ReaderLog.fld_InventoryId = @LogGateActionId)   AND (tbl_UHF_ReaderLog.fld_ProductSerial IS NULL)";
            dataAccess.CmdSqlExecuteNonQuery(command, new KeyValuePair<string, object>("LogGateActionId", LogGateActionId));


            int RowIndex = 1;
            _listGateResult = GetGateTags();

            if (ActionSourceLocation.HasNoValue())
            {
                if (_listGateResult.Any())
                {
                    ActionSourceLocation = _listGateResult.First().TagInDestinationId;
                }
            }

            if (_listGateResult.Any())
            {
                actionTypeStr = GetActionType(ActionSourceLocation, ActionDestinationLocation).ToString();
            }

              ActionTypeData = apiContext.ActionTypes.FirstOrDefault(p => p.Code == int.Parse(actionTypeStr));
            ActionTypeChangeTagLocation = ActionTypeData?.ChangeTagLocation.ToString();

            if (_listProductSerials.Length > 5)
            {
                string actionId = SGetMaxActionId(-1).ToString();

                ActionData = GetActionData();

                CreateCommands(_listProductSerials, actionId, saveDateTime);

                if (dataAccess.CmdSqlExecuteNonQueryWithTransaction(commands) > 0)
                {
                    ChangeDocumentStatus();

                    ChangePlacementOrderStatus();

                    SetProductGuarantees();

                    Task.Run(() => UpdateUhfReaderLog(actionId));

                    SInsertStationSyncDataLog(GateCode, DateTime.Now);

                    return true;
                }
                else
                {
                    return false;
                }
            }
            else
            {
                return false;
            }
        }
        else
        {
            return false;
        }

        bool IsUhfLogIdUnique()
        {
            var cmdcheckinvId = @$"SELECT MovementActionId FROM tbl_MovementActions 
                                WHERE ( MovementActionUHFLogId = '{LogGateActionId}') ";
            var checkinvId = dataAccess.SqlDataAdapter(cmdcheckinvId).Select();

            return checkinvId.Count() == 0;
        }

        List<GateResult> GetGateTags()
        {
            if (LogGateActionId.Equals("-1"))
            {
                _listProductSerials = "'" + string.Join("','", Serials) + "'";
            }
            else
            {
                string command = @"SELECT DISTINCT fld_ProductSerial FROM            tbl_UHF_ReaderLog   WHERE         (ActionStatus=0) AND (fld_Reader_Gate = N'" + GateCode + "') AND (fld_InventoryId = " + LogGateActionId + @")  and fld_ProductSerial <>'' and fld_ProductSerial is not null ";

                var _dtSqlDataReadersResultTags = dataAccess.SqlDataAdapter(command);
                if (_dtSqlDataReadersResultTags.Rows.Count > 0)
                {
                    foreach (DataRow dr in _dtSqlDataReadersResultTags.Rows)
                    {
                        _listProductSerials += "'" + dr[0].ToString() + "'";

                    }
                    _listProductSerials = _listProductSerials.Replace("''", "','");
                }
            }
            List<GateResult> data = new List<GateResult>();

            if (_listProductSerials != "")
            {
                var CommandSelectProductData = $@"SELECT DISTINCT 
                    tbl_Tags_1.ProductCode, 
                    tbl_Tags_1.ProductName, 
                    tbl_Tags_1.RegCode AS ProductTechnicalCode,
                    '1' AS Count, 
                    tbl_Tags_1.ProductCount AS SumValue,
                    tbl_Tags_1.ProductType, 
                    tbl_Tags_1.ProductStatus, 
                    tbl_Tags_1.TagStatus, 
                    COALESCE (tbl_Tags_1.TagInDestinationId, N'0') AS TagInDestinationId,
                    COALESCE (tbl_Tags_1.Lock, N'0') AS Lock,
                    tbl_Tags_1.fld_ProductPropertyAId AS ProductLine, 
                    tbl_Tags_1.fld_ProductPropertyBId AS ProductShift,
                    tbl_Tags_1.TagEpc AS TagSerial,
                    tbl_Tags_1.ProductSerial,
                    tbl_Tags_1.ContractStatus as DocumentId
                    FROM tbl_Tags AS tbl_Tags_1
                    WHERE tbl_Tags_1.ProductSerial IN ({_listProductSerials})";


                var dtGateResult = dataAccess.SqlDataAdapter(CommandSelectProductData);

                int row = 0;
                foreach (DataRow dr in dtGateResult.Rows)
                {
                    GateResult gateResult = new GateResult();
                    gateResult.ProductName = dr["ProductName"].ToString();
                    gateResult.ProductCode = dr["ProductCode"].ToString();
                    gateResult.Row = (row++).ToString();
                    gateResult.Count = dr["Count"].ToString();
                    gateResult.SumValue = dr["SumValue"].ToString();
                    gateResult.ProductTechnicalCode = dr["ProductTechnicalCode"].ToString();
                    gateResult.TagSerial = dr["TagSerial"].ToString();
                    gateResult.ProductSerial = dr["ProductSerial"].ToString();
                    gateResult.ProductType = dr["ProductType"].ToString();
                    gateResult.ProductStatus = dr["ProductStatus"].ToString();
                    gateResult.TagStatus = dr["TagStatus"].ToString();
                    gateResult.TagInDestinationId = dr["TagInDestinationId"].ToString();
                    gateResult.Lock = dr["Lock"].ToString();
                    gateResult.ProductLine = dr["ProductLine"].ToString();
                    gateResult.ProductShift = dr["ProductShift"].ToString();
                    gateResult.DocumentId = dr["DocumentId"].ToString();

                    data.Add(gateResult);
                }
            }
            return data;
        }

        JToken GetActionData()
        {
            var dynamicFieldList = apiContext.DynamicFields
                        .Where(p => p.ActionType == int.Parse(actionTypeStr))
                        .OrderByDescending(p => p.Id);

            var dynamicFields = mapper.Map<List<DynamicFieldDto>>(dynamicFieldList).ToList();

            dynamicFields = dynamicFields.Where(p => p.FieldType == DynamicFieldType.HeaderData || p.FieldType == DynamicFieldType.OperationInfo).DistinctBy(p => p.Title).ToList();

            dynamic exo = new System.Dynamic.ExpandoObject();

            if (ActionData is not null)
            {
                foreach (var field in dynamicFields)
                {
                    var value = string.Empty;

                    try
                    {
                        if (ActionData[$"{field.Title?.Trim()}"] is not null)
                        {
                            value = ActionData[$"{field.Title?.Trim()}"].ToString();
                        }
                        else
                        {
                            value = "";
                        }
                    }
                    catch
                    {
                        value = "";
                    }

                    ((IDictionary<String, Object>)exo).Add(field.Title, value);
                }
            }

            return Newtonsoft.Json.JsonConvert.SerializeObject(exo);
        }

