                 '{tag.ProductCode}',
                 '{tag.ProductSerial}',
                 '{tag.SumValue}',
                 '{actionId}',
                 '{PersianCalendarTools.GregorianToPersian(saveDateTime)}',
                 '{saveDateTime.Value:HH:mm}',
                 1,
                 '{saveDateTime.Value}',
                 0,
                 '{actionTypeStr}',
                 '{MovementActionDocumentId}',
                 '{(LogGateActionId.Equals("-1") ? "," + string.Join(',', LogGateActionIds) + "," : LogGateActionId)}',
                 '{ActionDestinationLocation}')");
                }
                commands.Add(new(commandTagMovementActionInsert + string.Join(',', commandTagMovementActionInsertValues)
              , parameters3.ToArray()));

            }



            var parameters4 = new List<KeyValuePair<string, object>>();
            var commandUpdateTagStatus = string.Empty;
            bool AllowChangeLocationTag = false;
            string NewLocationTag = "";
            if (ActionDestinationLocation.NotEquals("-1"))
            {
                parameters4.Add(new("StCd", (int)_listAllWarehouseDto.FirstOrDefault(p => p.DestinationCode == ActionDestinationLocation).OperationalType));
               
                parameters4.Add(new("DestId", ActionDestinationLocation));

              
                if(ActionTypeChangeTagLocation=="1")
                {
                    AllowChangeLocationTag = true;
                    if ((ActionDestinationZoneCode != null && ActionDestinationZoneCode != "" && ActionDestinationZoneCode != "-1" && ActionDestinationZoneCode != "0"))
                    {
                        NewLocationTag = ActionDestinationZoneCode;
                    }
                    else
                    {
                        NewLocationTag = "";

                    }
                }
                else
                {
                    if ((ActionDestinationZoneCode != null && ActionDestinationZoneCode != "" && ActionDestinationZoneCode != "-1" && ActionDestinationZoneCode != "0"))
                    {
                        AllowChangeLocationTag = true;
                        NewLocationTag = ActionDestinationZoneCode;
                    }
                }


                    commandUpdateTagStatus = string.Format(@" UPDATE tbl_Tags SET TagStatus= @StCd, TagInActionId = @ActId, TagInDestinationId = @DestId " + ((AllowChangeLocationTag) ? @",TagZone=@TagZone" : " ") + " WHERE (ProductSerial IN (" + ListProductSerials + "))");
            }
            else
            {
                commandUpdateTagStatus = string.Format(@" UPDATE tbl_Tags SET TagInActionId = @ActId "+ ((AllowChangeLocationTag)?@",TagZone=@TagZone":" " )+"  WHERE (ProductSerial IN (" + ListProductSerials + "))");
            }

            parameters4.Add(new("ActId", actionId));
            if (AllowChangeLocationTag)
                parameters4.Add(new("TagZone", NewLocationTag));

            commands.Add(new(commandUpdateTagStatus, parameters4.ToArray()));


            //    var commandUpdateTagTreeParentSerial = string.Format(@" UPDATE tbl_Tags SET TagTreeParentSerial = '', TagTreeParentsEpc = '' where TagStatus<>@StCd and (ProductSerial IN (" + ListProductSerials + "))");
            //    var parameters5 = new List<KeyValuePair<string, object>>();
            //    parameters5.Add(new("StCd", (int)_listAllWarehouseDto.FirstOrDefault(p => p.DestinationCode == ActionDestinationLocation).OperationalType));

            //    commands.Add(new(commandUpdateTagTreeParentSerial, parameters5.ToArray()));
        }

