        void ChangePlacementOrderStatus()
        {
            if ((actionTypeStr == "4" || actionTypeStr == "6") && MovementActionDocumentId != "" && MovementActionDocumentId != "0")
            {
                var command = @"UPDATE        tbl_PlacementOrders SET             fld_POStatus = 2 WHERE        (fld_POType = 3) AND (fld_POStatus = 1) and  (fld_PODocumentKey=@DocumentId) AND (fld_PODocumentType IN (4,6)) ";
                dataAccess.CmdSqlExecuteNonQuery(command, new KeyValuePair<string, object>("DocumentId", MovementActionDocumentId));
            }
        }

        void SetProductGuarantees()
        {
            if (configuration["ProjectConfigs:WmsConfigs:SetProductGuarantees"].Equals("true"))
            {
                List<string> _ListProductCodes = new();

                foreach (GateResult _tag in _listGateResult)
                {
                    if (_ListProductCodes.FirstOrDefault(p => p.ToString() == _tag.ProductCode) == null)
                    {
                        _ListProductCodes.Add(_tag.ProductCode);
                    }
                }

                var CmdGetProductGuaranteesTypeAndValue = $"""
                    SELECT     ProductCode,  fld_ProductGuaranteeType, COALESCE(fld_ProductGuaranteeMonths,0)  
                    FROM tbl_Products WHERE  (ProductCode IN ('{string.Join("','", _ListProductCodes)}')) 
                    """;

                var _dtProductGuaranteesTypeAndValue = dataAccess.SqlDataAdapter(CmdGetProductGuaranteesTypeAndValue);

                foreach (DataRow _drProductGuarantees in _dtProductGuaranteesTypeAndValue.Rows)
                {
                    Enum.TryParse<GuaranteeTypes>(_drProductGuarantees[1].ToString(), out GuaranteeTypes gType);

                    bool FlagSetGuarantees = false;

                    switch (gType)
                    {
                        case GuaranteeTypes.EnterToWarehouse:
                            if (actionTypeStr == "2")
                            {
                                FlagSetGuarantees = true;
                            }
                            break;
                        case GuaranteeTypes.ExitFromWarehouse:
                            if (actionTypeStr == "4")
                            {
                                FlagSetGuarantees = true;
                            }
                            break;
                        case GuaranteeTypes.ExitFromFactory:
                            if (actionTypeStr == "6")
                            {
                                FlagSetGuarantees = true;
                            }
                            break;
                    }

                    if (FlagSetGuarantees)
                    {
                        PersianCalendar pc = new();

                        SaveProductGuaranteesCommand _saveProductGuaranteesCommand = new SaveProductGuaranteesCommand()
                        {
                            GuaranteeActivationType = gType,
                            GuaranteeStartDate = DateTimeTools.GetPersianDate(),
                            GuaranteedEndDate = DateTimeTools.ConvertMiladi2ShamsiDate(pc.AddMonths(DateTime.Now, ((int)_drProductGuarantees[2]))),
                            GuaranteeStatus = "1",
                            ProductSerials = _listGateResult.Where(p => p.ProductCode == _drProductGuarantees[0].ToString()).Select(p => p.ProductSerial).ToList()
                        };

                        var result = productBusiness.SSaveProductGuarantees(_saveProductGuaranteesCommand);
                    }
                }
            }
        }

        void UpdateUhfReaderLog(string movementActionId)
        {
            string updateUhfItemStatus = string.Empty;

            List<string> updateUhfHeaderStatus = new();

            if (LogGateActionId.Equals("-1") && LogGateActionIds is not null)
            {
                string inventoryInCondition = $"{string.Join(",", LogGateActionIds)}";

                updateUhfItemStatus =
                $"""
                UPDATE tbl_UHF_ReaderLog
                SET tbl_UHF_ReaderLog.MovementActionId = {movementActionId}
                WHERE tbl_UHF_ReaderLog.fld_InventoryId IN({inventoryInCondition}) 
                AND tbl_UHF_ReaderLog.fld_ProductSerial IN('{string.Join("','", Serials)}')
                """;

                updateUhfHeaderStatus.Add($@"
                UPDATE tbl_UHFReaderLogHeader
                SET fld_HeaderUsedStatus = 1
                WHERE fld_UHFReaderLogHeaderId IN({inventoryInCondition}) 
                  AND NOT EXISTS (
                      SELECT 1 
                      FROM tbl_UHF_ReaderLog 
                      WHERE fld_InventoryId IN({inventoryInCondition}) 
                      AND (MovementActionId IS NULL OR MovementActionId = '')
                      AND fld_TagSerial != N'000'
                  );");

                updateUhfHeaderStatus.Add($@"
                UPDATE tbl_UHFReaderLogHeader
                SET fld_HeaderUsedStatus = 0
                WHERE fld_UHFReaderLogHeaderId IN({inventoryInCondition}) 
                  AND NOT EXISTS (
                      SELECT 1 
                      FROM tbl_UHF_ReaderLog 
                      WHERE fld_InventoryId IN({inventoryInCondition})   
                        AND (MovementActionId IS NOT NULL OR MovementActionId <> '')
                	    AND fld_TagSerial != N'000'
                  );");

                updateUhfHeaderStatus.Add($@"
                UPDATE tbl_UHFReaderLogHeader
                SET fld_HeaderUsedStatus = 2
                WHERE fld_UHFReaderLogHeaderId IN({inventoryInCondition}) 
                  AND EXISTS (
                      SELECT 1 
                      FROM tbl_UHF_ReaderLog 
                      WHERE fld_InventoryId IN({inventoryInCondition})  
                        AND (MovementActionId IS NOT NULL OR MovementActionId <> '')
                		AND fld_TagSerial != N'000'
                  )
                  AND EXISTS (
                      SELECT 1 
                      FROM tbl_UHF_ReaderLog 
                      WHERE fld_InventoryId IN({inventoryInCondition}) 
                        AND (MovementActionId IS NULL OR MovementActionId = '')
                		AND fld_TagSerial != N'000'
                  );");
            }
            else
            {
                updateUhfItemStatus =
                $"""
                UPDATE tbl_UHF_ReaderLog
                SET tbl_UHF_ReaderLog.MovementActionId = {movementActionId}
                WHERE tbl_UHF_ReaderLog.fld_InventoryId = N'{LogGateActionId}'
                """;

                updateUhfHeaderStatus.Add($@"
                UPDATE tbl_UHFReaderLogHeader
                SET fld_HeaderUsedStatus = 1
                WHERE fld_UHFReaderLogHeaderId = N'{LogGateActionId}'
                ");
            }

            var childrenCommands = new List<KeyValuePair<string, KeyValuePair<string, object>[]>>();

            var parameters = new List<KeyValuePair<string, object>>();

            childrenCommands.Add(new(updateUhfItemStatus, parameters.ToArray()));

            foreach (var command in updateUhfHeaderStatus)
            {
                childrenCommands.Add(new(command, parameters.ToArray()));
            }

            sqlDataAccess.CmdSqlExecuteNonQueryWithTransaction(childrenCommands);
        }
    }


    public TruckCargo SGetPlacementMission(string[] ProductSerials, string[] Epcs, string WMDriverUserId, string WMId, string ActionId, string GateNumber, string GateTitle, string TypeGetPlacementMission, string ActionDescription, string ActionStatus, bool RecursiveFunction, bool CastResult)
    {
        TruckCargo _trca = new TruckCargo();
        string AllEpcs = "";
        List<string> NotExistPmSerialsList = new List<string>();
        List<string> AllProductSerial = new List<string>();
        if (ProductSerials != null && Epcs != null && (ProductSerials.Length > 0 || Epcs.Length > 0))
        {
            foreach (string tempSerial in ProductSerials)
            {
                if (tempSerial != "" && AllProductSerial.FirstOrDefault(p => p.ToString() == tempSerial) == null)
                    AllProductSerial.Add(tempSerial);
            }

            foreach (string tempEpc in Epcs)
            {
                if (tempEpc != "")
                    AllEpcs += "'" + tempEpc + "',";
            }
            if (AllEpcs.Length > 1)
            {
                AllEpcs = AllEpcs.Substring(0, AllEpcs.Length - 1);

            }
        }

        if (ActionId != "" && ActionId != "-1" && ActionId != "0")
        {
            var cmdGetEpcListByActionId = @" SELECT DISTINCT tbl_Tags.ProductSerial
FROM            tbl_UHF_ReaderLog INNER JOIN
                         tbl_Tags ON tbl_UHF_ReaderLog.fld_TagSerial = tbl_Tags.TagEpc
WHERE        (tbl_UHF_ReaderLog.fld_InventoryId = " + ActionId + @")" + ((AllEpcs != "") ? @" UNION
SELECT DISTINCT ProductSerial
FROM            tbl_Tags AS tbl_Tags_1
WHERE        (TagEpc IN (" + AllEpcs + @")) " : "");

            var _dtEpcList = dataAccess.SqlDataAdapter(cmdGetEpcListByActionId);

            foreach (DataRow drtempEpc in _dtEpcList.Rows)
            {
                if (AllProductSerial.FirstOrDefault(p => p.ToString() == drtempEpc[0].ToString()) == null)
                    AllProductSerial.Add(drtempEpc[0].ToString());
            }
        }

        if (AllProductSerial.Count > 0)
        {
            string FromStoreCode = "";
            string FromStoreTitle = "";
            string FromZoneCode = "";
            string ToZoneCode = "";
            string ToStoreCode = "";
            string ToStoreTitle = "";
            string ToZoneAddress = "";

            List<CargoProduct> _Products = new List<CargoProduct>();
            List<String> ToZoneList = new List<string>();

            foreach (string _productSerial in AllProductSerial)
            {
                var cmdGetPlacementMissionsBySerials = @" SELECT        tbl_Tags.ProductSerial, tbl_Tags.ProductCode, tbl_Tags.ProductName, tbl_Tags.RegCode, tbl_ProductPlacementMissions.fld_PPMId, tbl_ProductPlacementMissions.fld_PPMUserId, tbl_ProductPlacementMissions.fld_POCode, 
                         tbl_ProductPlacementMissions.fld_PPMType, tbl_ProductPlacementMissions.fld_PPMWMCode, tbl_ProductPlacementMissions.fld_PPMWMDriverUserId, tbl_ProductPlacementMissions.fld_PPMFromStoreCode, 
                         tbl_ProductPlacementMissions.fld_PPMFromZoneId, tbl_ProductPlacementMissions.fld_PPMToZoneId, tbl_ProductPlacementMissions.fld_PPMStoreCode, tbl_ProductPlacementMissions.fld_PPMStatus, 
                         tbl_ProductPlacementMissions.fld_PPMToZoneId_Edited, tbl_ProductPlacementMissions.fld_PPMDateTime, tbl_ProductPlacementMissions.fld_PPMActionId, tbl_ProductPlacementMissions.fld_PPMRegCode, 
                         tbl_Destination.DestinationTitle AS FromStoreTitle, tbl_Destination_1.DestinationTitle AS ToStoreTitle, tbl_Zones.ZoneAddress AS ToZoneAddress
FROM            tbl_ProductPlacementMissions LEFT OUTER JOIN
                         tbl_Zones ON tbl_ProductPlacementMissions.fld_PPMToZoneId = tbl_Zones.ZoneCode AND tbl_ProductPlacementMissions.fld_PPMStoreCode = tbl_Zones.ZoneStoreCode LEFT OUTER JOIN
                         tbl_Destination AS tbl_Destination_1 ON tbl_ProductPlacementMissions.fld_PPMStoreCode = tbl_Destination_1.DestinationCode LEFT OUTER JOIN
                         tbl_Destination ON tbl_ProductPlacementMissions.fld_PPMFromStoreCode = tbl_Destination.DestinationCode RIGHT OUTER JOIN
                         tbl_Tags ON tbl_ProductPlacementMissions.fld_PPMProductSerial = tbl_Tags.ProductSerial
WHERE        (tbl_Tags.ProductSerial='" + _productSerial + @"') order by fld_PPMStatus   ";

                var _dtPalcementMissions = dataAccess.SqlDataAdapter(cmdGetPlacementMissionsBySerials);

                DataRow dr = _dtPalcementMissions.Rows[0];

                if (_dtPalcementMissions.Rows.Count > 0 && (dr["fld_PPMStatus"] != null) && (dr["fld_PPMStatus"].ToString() == "0" || dr["fld_PPMStatus"].ToString() == "1"))
                {
                    CargoProduct _carcoProduct = new CargoProduct
                    {
                        PmCode = dr["fld_PPMId"].ToString(),
                        ProductCode = dr["ProductCode"].ToString(),
                        ProductName = dr["ProductName"].ToString(),
                        ProductSerial = dr["ProductSerial"].ToString(),
                        Regcode = dr["RegCode"].ToString(),
                        PmToStoreCode = dr["fld_PPMStoreCode"].ToString(),
                        PmToZoneCode = dr["fld_PPMToZoneId"].ToString(),
                        PmToStoreTitle = dr["ToStoreTitle"].ToString(),
                        PmToZoneAddress = dr["ToZoneAddress"].ToString()
                    };

                    _Products.Add(_carcoProduct);

                    if (ToZoneList.FirstOrDefault(p => p.ToString() == dr["fld_PPMStoreCode"].ToString() + "-" + dr["fld_PPMToZoneId"].ToString()) == null)
                    {
                        ToZoneList.Add(dr["fld_PPMStoreCode"].ToString() + "-" + dr["fld_PPMToZoneId"].ToString());
                    }

                    if (ToZoneList.Count == 1)
                    {
                        FromStoreCode = dr["fld_PPMFromStoreCode"].ToString();
                        FromStoreTitle = dr["FromStoreTitle"].ToString();
                        FromZoneCode = dr["fld_PPMFromZoneId"].ToString();
                        ToZoneCode = dr["fld_PPMToZoneId"].ToString();
                        ToStoreCode = dr["fld_PPMStoreCode"].ToString();
                        ToStoreTitle = dr["ToStoreTitle"].ToString();
                        ToZoneAddress = dr["ToZoneAddress"].ToString();
                    }
                    else
                    {
                        ToZoneCode = "";
                        ToStoreCode = "";
                        ToStoreTitle = "";
                        ToZoneAddress = "";
                    }
                }
                else
                {
                    if (NotExistPmSerialsList.FirstOrDefault(p => p.ToString() == dr["ProductSerial"].ToString()) == null)
                    {
                        NotExistPmSerialsList.Add(dr["ProductSerial"].ToString());
                    }
                }
            }

            if (NotExistPmSerialsList.Count > 0)
            {
                foreach (string _productSerial in NotExistPmSerialsList)
                {
                    SSetPlacementMission(_productSerial, WMDriverUserId, WMId, "", "0");

                    var cmdGetPlacementMissionsBySerials = @" SELECT        tbl_Tags.ProductSerial, tbl_Tags.ProductCode, tbl_Tags.ProductName, tbl_Tags.RegCode, tbl_ProductPlacementMissions.fld_PPMId, tbl_ProductPlacementMissions.fld_PPMUserId, tbl_ProductPlacementMissions.fld_POCode, 
                         tbl_ProductPlacementMissions.fld_PPMType, tbl_ProductPlacementMissions.fld_PPMWMCode, tbl_ProductPlacementMissions.fld_PPMWMDriverUserId, tbl_ProductPlacementMissions.fld_PPMFromStoreCode, 
                         tbl_ProductPlacementMissions.fld_PPMFromZoneId, tbl_ProductPlacementMissions.fld_PPMToZoneId, tbl_ProductPlacementMissions.fld_PPMStoreCode, tbl_ProductPlacementMissions.fld_PPMStatus, 
                         tbl_ProductPlacementMissions.fld_PPMToZoneId_Edited, tbl_ProductPlacementMissions.fld_PPMDateTime, tbl_ProductPlacementMissions.fld_PPMActionId, tbl_ProductPlacementMissions.fld_PPMRegCode, 
                         tbl_Destination.DestinationTitle AS FromStoreTitle, tbl_Destination_1.DestinationTitle AS ToStoreTitle, tbl_Zones.ZoneAddress AS ToZoneAddress
FROM            tbl_ProductPlacementMissions LEFT OUTER JOIN
                         tbl_Zones ON tbl_ProductPlacementMissions.fld_PPMToZoneId = tbl_Zones.ZoneCode AND tbl_ProductPlacementMissions.fld_PPMStoreCode = tbl_Zones.ZoneStoreCode LEFT OUTER JOIN
                         tbl_Destination AS tbl_Destination_1 ON tbl_ProductPlacementMissions.fld_PPMStoreCode = tbl_Destination_1.DestinationCode LEFT OUTER JOIN
                         tbl_Destination ON tbl_ProductPlacementMissions.fld_PPMFromStoreCode = tbl_Destination.DestinationCode RIGHT OUTER JOIN
                         tbl_Tags ON tbl_ProductPlacementMissions.fld_PPMProductSerial = tbl_Tags.ProductSerial
WHERE        (tbl_Tags.ProductSerial='" + _productSerial + @"') order by fld_PPMStatus   ";

                    var _dtPalcementMissions = dataAccess.SqlDataAdapter(cmdGetPlacementMissionsBySerials);

                    DataRow dr = _dtPalcementMissions.Rows[0];

                    if (_dtPalcementMissions.Rows.Count > 0 && (dr["fld_PPMStatus"] != null) && (dr["fld_PPMStatus"].ToString() == "0" || dr["fld_PPMStatus"].ToString() == "1"))
                    {
                        CargoProduct _carcoProduct = new CargoProduct
                        {
                            PmCode = dr["fld_PPMId"].ToString(),
                            ProductCode = dr["ProductCode"].ToString(),
                            ProductName = dr["ProductName"].ToString(),
                            ProductSerial = dr["ProductSerial"].ToString(),
                            Regcode = dr["RegCode"].ToString(),
                            PmToStoreCode = dr["fld_PPMStoreCode"].ToString(),
                            PmToZoneCode = dr["fld_PPMToZoneId"].ToString(),
                            PmToStoreTitle = dr["ToStoreTitle"].ToString(),
                            PmToZoneAddress = dr["ToZoneAddress"].ToString()
                        };
                        _Products.Add(_carcoProduct);



                        if (ToZoneList.FirstOrDefault(p => p.ToString() == dr["fld_PPMStoreCode"].ToString() + "-" + dr["fld_PPMToZoneId"].ToString()) == null)
                            ToZoneList.Add(dr["fld_PPMStoreCode"].ToString() + "-" + dr["fld_PPMToZoneId"].ToString());



                        if (ToZoneList.Count == 1)
                        {
                            FromStoreCode = dr["fld_PPMFromStoreCode"].ToString();
                            FromStoreTitle = dr["FromStoreTitle"].ToString();
                            FromZoneCode = dr["fld_PPMFromZoneId"].ToString();
                            ToZoneCode = dr["fld_PPMToZoneId"].ToString();
                            ToStoreCode = dr["fld_PPMStoreCode"].ToString();
                            ToStoreTitle = dr["ToStoreTitle"].ToString();
                            ToZoneAddress = dr["ToZoneAddress"].ToString();
                        }
                        else
                        {
                            ToZoneCode = "";
                            ToStoreCode = "";
                            ToStoreTitle = "";
                            ToZoneAddress = "";

                        }
                    }
                    else
                    {
                        CargoProduct _carcoProduct = new CargoProduct
                        {
                            PmCode = "",
                            ProductCode = dr["ProductCode"].ToString(),
                            ProductName = dr["ProductName"].ToString(),
                            ProductSerial = dr["ProductSerial"].ToString(),
                            Regcode = dr["RegCode"].ToString(),
                            PmToStoreCode = "",
                            PmToZoneCode = "",
                            PmToStoreTitle = "",
                            PmToZoneAddress = ""
                        };
                        _Products.Add(_carcoProduct);

                    }
                }
            }

            _trca.GateActionId = ActionId;
            _trca.Products = _Products;
            _trca.FromZoneCode = FromZoneCode;
            _trca.FromZoneTitle = FromZoneCode;
            _trca.FromWarehouseCode = FromStoreCode;
            _trca.FromWarehouseTitle = FromStoreTitle;
            _trca.DestinationZoneCode = ToZoneCode;
            _trca.DestinationZoneTitle = ToZoneCode;
            _trca.DestinationWarehouseCode = ToStoreCode;
            _trca.DestinationWarehouseTitle = ToStoreTitle;
            _trca.DestinationAddress = ToZoneAddress;
            _trca.GateTitle = GateTitle;
            _trca.ActionDescription = ActionDescription;
            _trca.CargoStatus = CargoStatus.PlaceInProgress;
            _trca.ActionStatus = (ActionStatus)Convert.ToInt32(ActionStatus);
            _trca.DriverUserId = WMDriverUserId;
            _trca.DriverUsername = WMDriverUserId;
            _trca.TruckNumber = WMId;

            if (WMDriverUserId != "" && WMDriverUserId != "-1")
            {
                if (CastResult)
                {
                    SSendSignalR(_trca);
                }

                string _tempAllProductSerials = "";

                foreach (string _productSerial in AllProductSerial)
                {

                    _tempAllProductSerials += "'" + _productSerial + "',";
                }

                if (_tempAllProductSerials.Length > 1)
                {
                    _tempAllProductSerials = _tempAllProductSerials.Substring(0, _tempAllProductSerials.Length - 1);
                }

                if (_tempAllProductSerials.Length > 0)
                {
                    SUpdatePlacementMissions(_tempAllProductSerials, "", WMId, WMDriverUserId, "1");
                }
            }

            return _trca;
        }
        else
        {
            return null;
        }
    }

    public string SSetPlacementMission(string ProductSerial, string WMDriverUserId, string WMId, string Type, string UserId)
    {
        string PMIdResult = "";

        var cmdGetPlacementOrders = @" DECLARE @ProductSerial nvarchar(50) ;
                                    set @ProductSerial=N'" + ProductSerial + @"';
                                    DECLARE @ProductCode nvarchar(50) ;
                                    DECLARE @TagEpc nvarchar(50) ;
                                    DECLARE @TagInDestination nvarchar(50) ;
                                    DECLARE @TagRegisterShamsiUnixDate nvarchar(50) ;
                                    SELECT    @ProductCode=[ProductCode] , @TagInDestination=[TagInDestinationId] , @TagRegisterShamsiUnixDate=[TagRegisterShamsiUnixDate] ,@TagEpc=[TagEpc] FROM            tbl_Tags WHERE        (ProductSerial = @ProductSerial)
 

 
                                    SELECT   @TagEpc as Epc, @TagRegisterShamsiUnixDate as TagRegisterShamsiUnixDate,@TagInDestination as TagInDestination ,  @ProductCode as ProductCode,  fld_POCode,fld_POFromStoreCode ,fld_POFromZoneCode, fld_POType, fld_POUser, fld_POToStoreCode, fld_POZoneCode, fld_POPackCountRemain, fld_POWMDriverId, fld_POProductSerial, fld_POProductCode, fld_POPackCount
                                                                        FROM            tbl_PlacementOrders
                                    WHERE       ((fld_POPackCount=0) OR ((fld_POPackCount>0) and (fld_POPackCountRemain>0) )) and   (fld_POExpireDate >= GETDATE()) AND (fld_POStatus = 0) AND (fld_POFromStoreCode=@TagInDestination) and  ((fld_POProductSerial like '%,'+Cast(@ProductSerial as nvarchar(50))+'%') OR (fld_POProductCode like '%,'+@ProductCode +'%' ) )
                                    order by fld_POProductSerial    ";

        var _dtPalcementOrders = dataAccess.SqlDataAdapter(cmdGetPlacementOrders);

        string ProductCode = "";
        string EPC = "";
        string TagRegisterShamsiUnixDate = "";
        string TagInDestination = "";
        string POFromStoreCode = "";
        string POFromZoneCode = "";
        string POToStoreCode = "";
        string POZoneCode = "";
        string POCode = "";
        string POWMDriverId = "";
        bool FlagSetMission = false;
        if (_dtPalcementOrders.Rows.Count == 0)
        {
            PMIdResult = "-1";
            FlagSetMission = false;
        }
        else
        {
            foreach (DataRow dr in _dtPalcementOrders.Rows)
            {
                if (dr["fld_POProductSerial"].ToString().Contains("," + ProductSerial))
                {
                    FlagSetMission = true;

                    ProductCode = dr["ProductCode"].ToString();
                    EPC = dr["Epc"].ToString();
                    TagRegisterShamsiUnixDate = dr["TagRegisterShamsiUnixDate"].ToString();
                    TagInDestination = dr["TagInDestination"].ToString();
                    POFromStoreCode = dr["fld_POFromStoreCode"].ToString();
                    POFromZoneCode = dr["fld_POFromZoneCode"].ToString();
                    POToStoreCode = dr["fld_POToStoreCode"].ToString();
                    POZoneCode = dr["fld_POZoneCode"].ToString();
                    POCode = dr["fld_POCode"].ToString();
                    POWMDriverId = dr["fld_POWMDriverId"].ToString();

                    break;
                }
            }

            if (!FlagSetMission)
            {
                foreach (DataRow dr in _dtPalcementOrders.Rows)
                {
                    ProductCode = dr["ProductCode"].ToString();

                    if (dr["fld_POProductCode"].ToString().Contains("," + ProductCode))
                    {
                        FlagSetMission = true;

                        TagRegisterShamsiUnixDate = dr["TagRegisterShamsiUnixDate"].ToString();
                        EPC = dr["Epc"].ToString();
                        TagInDestination = dr["TagInDestination"].ToString();
                        POFromStoreCode = dr["fld_POFromStoreCode"].ToString();
                        POFromZoneCode = dr["fld_POFromZoneCode"].ToString();
                        POToStoreCode = dr["fld_POToStoreCode"].ToString();
                        POZoneCode = dr["fld_POZoneCode"].ToString();
                        POCode = dr["fld_POCode"].ToString();
                        POWMDriverId = dr["fld_POWMDriverId"].ToString();

                        break;
                    }
                }

            }

            if (FlagSetMission && (POToStoreCode == "0" || POToStoreCode == "" || POZoneCode == "" || POZoneCode == "0"))
            {
                string TempToStore = "";
                if (POToStoreCode != "" && POToStoreCode != "-1" && POToStoreCode != "0")
                {
                    TempToStore = POToStoreCode.Split(',')[1];
                }
                string TempDestinationLocation = ChooseLocationByProductCodeANDRegisterDate(ProductCode, TempToStore, PersianCalendarTools.PersianToGregorian(TagRegisterShamsiUnixDate.Substring(0, 4) + "/" + TagRegisterShamsiUnixDate.Substring(4, 2) + "/" + TagRegisterShamsiUnixDate.Substring(6, 2)), "");
                if (TempDestinationLocation != "-1")
                {
                    POToStoreCode = TempDestinationLocation.Split('*')[0];
                    POZoneCode = TempDestinationLocation.Split('*')[1];
                }
                else
                {
                    FlagSetMission = false;
                }
            }
        }

        if (POToStoreCode.Contains(','))
        {
            var ToStoreCodeTemp = POToStoreCode.Split(',');
            if (ToStoreCodeTemp.Length > 1)
            {
                POToStoreCode = ToStoreCodeTemp[1].Replace(",", "");
            }
            else
            {
                POToStoreCode = POToStoreCode.Replace(",", "");
            }
        }

        if (POZoneCode.Contains(','))
        {
            var ToZoneCodeTemp = POZoneCode.Split(',');

            string ZoneListForQuery = "";

            for (int i = 1; i < ToZoneCodeTemp.Length; i++)
            {
                ZoneListForQuery += "'" + ToZoneCodeTemp[i] + "',";
            }

            ZoneListForQuery = ZoneListForQuery.Substring(0, ZoneListForQuery.Length - 1);

            string TempDestinationLocation = ChooseLocationByProductCodeANDRegisterDate(ProductCode, POToStoreCode, PersianCalendarTools.PersianToGregorian(TagRegisterShamsiUnixDate.Substring(0, 4) + "/" + TagRegisterShamsiUnixDate.Substring(4, 2) + "/" + TagRegisterShamsiUnixDate.Substring(6, 2)), ZoneListForQuery);

            if (TempDestinationLocation != "-1")
            {
                POZoneCode = TempDestinationLocation.Split('*')[1];
            }
            else
            {
                FlagSetMission = false;
            }
        }

        if (FlagSetMission)
        {
            if (WMDriverUserId == "")
            {
                WMDriverUserId = POWMDriverId;
            }

            if (SSavePlaceMissionsBySerial(ProductSerial, EPC, ProductCode, Type, WMDriverUserId, WMId, POFromStoreCode, POFromZoneCode, POToStoreCode, POZoneCode, UserId, POCode, "0"))
            {
                SUpdateZoneOccupiedCapacity(POToStoreCode, POZoneCode, "");
                var cmdGetMaxPMId = @" SELECT        MAX(fld_PPMId) AS Expr1 FROM            tbl_ProductPlacementMissions";
                PMIdResult = dataAccess.SqlDataReaders(cmdGetMaxPMId)[0].Value.ToString();
            }
        }

        return PMIdResult;
    }

    private string ChooseLocationByProductCodeANDRegisterDate(string ProductCode, string DestinationStoreCode, DateTime RegisterDate, string ZoneList)
    {
        var cmdChooseLocation = @"      SELECT TOP(1) tbl_Zones.ZoneStoreCode, tbl_Zones.ZoneCode, ABS(DATEDIFF(hour,Cast('" + RegisterDate.ToString() + @"' as datetime), tbl_Tags.TagRegisterDateTime)) AS ASBDateDiff

        FROM tbl_Tags LEFT OUTER JOIN
                      tbl_Zones ON tbl_Tags.TagInDestinationId = tbl_Zones.ZoneStoreCode AND tbl_Tags.TagZone = tbl_Zones.ZoneCode
        WHERE " + ((DestinationStoreCode != "") ? "(tbl_Tags.TagInDestinationId = '" + DestinationStoreCode + "') AND " : "") + " (tbl_Tags.ProductCode = '" + ProductCode + @"') AND(tbl_Zones.ZoneCapacity - tbl_Zones.ZoneOccupiedCapacity > 0) " + ((ZoneList != "") ? " AND (tbl_Tags.TagZone IN(" + ZoneList + "))  " : "") +
       " ORDER BY ASBDateDiff   ";

        var _dtChooseLocationList = dataAccess.SqlDataAdapter(cmdChooseLocation);

        if (_dtChooseLocationList.Rows.Count > 0)
        {
            return _dtChooseLocationList.Rows[0][0].ToString() + "*" + _dtChooseLocationList.Rows[0][1].ToString();
        }
        else
        {
            if (ZoneList != "")
            {

                var cmdChooseLocationByZoneList = @"    SELECT        TOP (1) ZoneStoreCode, ZoneCode
                                                        FROM            tbl_Zones
                                                        WHERE     " + ((DestinationStoreCode != "") ? " (ZoneStoreCode  = '" + DestinationStoreCode + "') AND " : "") + "      (ZoneCapacity - ZoneOccupiedCapacity > 0) AND (ZoneCode IN (" + ZoneList + "))     ";


                var _dtChooseLocationListByZoneList = dataAccess.SqlDataAdapter(cmdChooseLocationByZoneList);

                if (_dtChooseLocationListByZoneList.Rows.Count > 0)
                {
                    return _dtChooseLocationListByZoneList.Rows[0][0].ToString() + "*" + _dtChooseLocationListByZoneList.Rows[0][1].ToString();
                }
                else
                {
                    return "-1";
                }

            }
            else
            {
                return "-1";
            }
        }
    }

