    public List<CeramicAggregateResult> SPSecurityGateReportDetails(int gateOperationCode, string ProductCode)
    {
        var whereString = string.Empty;
        var innerWhereString = string.Empty;
        if (!ProductCode.Equals("-1"))
        {
            whereString += " AND (tbl_Tags.ProductCode = N'" + ProductCode + "') ";

        }

        if (!gateOperationCode.Equals(-1))
        {
            whereString += " AND (tbl_UHF_ReaderLog.fld_InventoryId = " + gateOperationCode + ")";
        }
        var cmd =
            $@"SELECT * 
FROM(
SELECT DISTINCT tbl_UHF_ReaderLog.fld_TagSerial AS Epc, COALESCE (tbl_Tags.ProductSerial, N'-1') AS ProductSerial, tbl_Tags.ProductCode, tbl_Tags.ProductName, COALESCE (tbl_Tags.ProductCount, 0) AS ProductCount,COALESCE (tbl_Tags.RegCode, '0') AS TechnicalCode, COALESCE(tbl_Tags.Freeze,0) AS Freeze
FROM            tbl_UHF_ReaderLog LEFT OUTER JOIN
                         tbl_Tags ON tbl_UHF_ReaderLog.fld_TagSerial = tbl_Tags.TagEpc
WHERE        (tbl_UHF_ReaderLog.fld_TagSerial IS NOT NULL) AND (tbl_Tags.TagStatus = N'1')  {whereString} 
) AS [NESTED]
WHERE [NESTED].Freeze = 0"
                                              ///   + " GROUP BY tbl_Tags.TagEpc, tbl_Tags.ProductSerial, tbl_Tags.ProductCode,tbl_Tags.ProductName ")
                                              ;

        var listTag = dataAccess.SqlDataAdapter(cmd);

        var finalList = new List<CeramicAggregateResult>();

        foreach (DataRow tag in listTag.Rows)
        {
            finalList.Add(new CeramicAggregateResult()
            {
                ProductCode = tag[2].ToString(),
                ProductCount = Convert.ToDecimal(tag[4].ToString()),
                ProductName = tag[3].ToString(),
                ProductSerial = tag[1].ToString(),
                SumCount = 0,// TechnicalCode
                TagEpc = tag[0].ToString(),
                MaxDate = tag[5].ToString()
            });

        }
        return finalList;
    }

    public DataTable SRepSCancelRegisterTag
    (string ProductSerial,
    string FromDate,
    string ToDate,
    string User
    )
    {
        string whereKey = " (SoftDelete = 1) AND";

        if (ProductSerial != "" && ProductSerial != "-1")
        {
            whereKey += " ( ProductSerial= " + ProductSerial + " )  AND";
        }

        if (FromDate != "" && FromDate != "-1")
        {
            whereKey += " (SoftDeleteDate >= '" + FromDate + "')  AND";
        }

        if (ToDate != "" && ToDate != "-1")
        {
            whereKey += " (SoftDeleteDate <= '" + ToDate + "')  AND";
        }

        if (User != "" && User != "-1")
        {
            whereKey += " (SoftDeleteUser=N'" + User + "')  AND";
        }

        if (!string.IsNullOrEmpty(whereKey))
        {
            if (whereKey != "" && whereKey.Substring(whereKey.Length - 3, 3) == "AND")
            {
                whereKey = whereKey.Substring(0, whereKey.Length - 3);
            }
        }

        var dtProducts = new DataTable();
        dtProducts.Columns.Add("ProductSerial", typeof(string));
        dtProducts.Columns.Add("ProductCode", typeof(string));
        dtProducts.Columns.Add("ProductName", typeof(string));
        dtProducts.Columns.Add("ProductRegCode", typeof(string));
        dtProducts.Columns.Add("ProductCount", typeof(string));
        dtProducts.Columns.Add("SoftDeleteUser", typeof(string));
        dtProducts.Columns.Add("SoftDeleteDate", typeof(string));
        dtProducts.Columns.Add("RegisterUser", typeof(string));
        dtProducts.Columns.Add("RegisterDate", typeof(string));

        try
        {
            var sqlCommand = @"SELECT COALESCE(ProductSerial,N'') AS ProductSerial, 
COALESCE(ProductCode,N'') AS ProductCode,
COALESCE(ProductName,N'') AS ProductName, 
COALESCE(ProductRegCode,N'') AS ProductRegCode,
COALESCE(ProductCount,0) AS ProductCount,
COALESCE((SELECT [Name] FROM tbl_User WHERE ID = SoftDeleteUser),N'') AS SoftDeleteUser, 
COALESCE(SoftDeleteDate,N'') AS SoftDeleteDate, 
COALESCE((SELECT [Name] FROM tbl_User WHERE ID = RegisterUser),N'')  AS RegisterUser ,
COALESCE(RegisterDate,N'') AS RegisterDate
FROM tbl_Print " + (whereKey != string.Empty ? " Where " + whereKey : "") +
                    " ORDER BY  ProductSerial  ";

            logger.LogInformation("SRepSCancelRegisterTag" +
     "ProductSerial: " + ProductSerial + Environment.NewLine +
     "FromDate: " + FromDate + Environment.NewLine +
     "ToDate: " + ToDate + Environment.NewLine +
      "User: " + User + Environment.NewLine +
      "sqlCommand: " + sqlCommand + Environment.NewLine
     );
            return dataAccess.SqlDataAdapter(sqlCommand);
        }
        catch (Exception exception)
        {
            logger.LogWarning(exception, exception.Message);
            return dtProducts;
        }
    }

