    public DataTable SGetTagSalesHistory(string serial)
    {
        var command = $@"SELECT TOP (1) 
        tbl_MovementActions.MovementActionId, 
        tbl_MovementActions.MovementActionDate + N' - ' + tbl_MovementActions.MovementActionTime AS DateTime, 
        tbl_MovementActions.MovementActionDate AS [Date],
        tbl_MovementActions.MovementActionTime AS [Time],
        COALESCE(tbl_MovementActions.MovementActionDocumentId, N'') AS MovementActionDocumentId,
        COALESCE(tbl_MovementActions.MovementActionDesc, N'') AS MovementActionDesc, 
        COALESCE(tbl_MovementActions.MovementActionUHFLogId, 0) as GateOpCode, 
        COALESCE(tbl_MovementActions.MovementActionData, N'{{}}') as MovementActionData, 
        COALESCE(tbl_MovementActions.MovementActionTruckCrossId, 0) as MovementActionTruckCrossId,
        COALESCE((SELECT tbl_User.[Name] 
        FROM tbl_User 
        WHERE (TRY_CONVERT(uniqueidentifier, tbl_MovementActions.MovementActionUserId) IS NOT NULL AND tbl_User.Id = tbl_MovementActions.MovementActionUserId) OR
        (tbl_User.Username = tbl_MovementActions.MovementActionUserId) ), N'') AS Username,
        N'' as [AgeAnalsys],
        (SELECT TagRegisterShamsiUnixDate FROM tbl_Tags WHERE ProductSerial = N'{serial}') as [ProductDate],
        COALESCE((SELECT fld_TruckCrossDriverName FROM tbl_TruckCross WHERE fld_TruckCrossId = tbl_MovementActions.MovementActionTruckCrossId), N'') AS DriverName,
        COALESCE((SELECT fld_TruckCrossNationalCode FROM tbl_TruckCross WHERE fld_TruckCrossId = tbl_MovementActions.MovementActionTruckCrossId), N'') AS NationalCode,
        COALESCE((SELECT fld_TruckCrossLicenseCode FROM tbl_TruckCross WHERE fld_TruckCrossId = tbl_MovementActions.MovementActionTruckCrossId), N'') AS LicenseCode,
        COALESCE((SELECT fld_TruckCrossDriverPhone FROM tbl_TruckCross WHERE fld_TruckCrossId = tbl_MovementActions.MovementActionTruckCrossId), N'') AS DriverPhone,
        COALESCE((SELECT fld_TruckCrossPlaque FROM tbl_TruckCross WHERE fld_TruckCrossId = tbl_MovementActions.MovementActionTruckCrossId), N'') AS Plaque,
        COALESCE((SELECT fld_TruckTypeTitle FROM tbl_TruckType 
                  WHERE fld_TruckTypeId = (SELECT fld_TruckCrossType FROM tbl_TruckCross 
                                          WHERE fld_TruckCrossId = tbl_MovementActions.MovementActionTruckCrossId)), N'') AS TruckCrossTypeTitle,
        COALESCE((SELECT fld_TruckCrossEnterWeightTonage FROM tbl_TruckCross WHERE fld_TruckCrossId = tbl_MovementActions.MovementActionTruckCrossId), 0) AS EnterWeightTonage,
        COALESCE((SELECT fld_TruckCrossExitWeightTonage FROM tbl_TruckCross WHERE fld_TruckCrossId = tbl_MovementActions.MovementActionTruckCrossId), 0) AS ExitWeightTonage,
        COALESCE((SELECT fld_TruckCrossExitPureWeightCargo FROM tbl_TruckCross WHERE fld_TruckCrossId = tbl_MovementActions.MovementActionTruckCrossId), 0) AS ExitPureWeightCargo
        FROM tbl_MovementActions
        WHERE MovementActionTp = 6 
          AND EXISTS (SELECT 1 FROM tbl_TagsMovement WHERE RMovementActionId = tbl_MovementActions.MovementActionId AND ProductSerial = N'{serial}')";

        var _sales = dataAccess.SqlDataAdapter(command);

        for (int i = 0; i < _sales.Rows.Count; i++)
        {
            DataRow row = _sales.Rows[i];

            string exitAgeAnalysis = GetExitAgeAnalysis(row["ProductDate"].ToString(), row["Date"].ToString());

            _sales.Rows[i]["AgeAnalsys"] = exitAgeAnalysis;
        }

        return _sales;
    }

    public bool SGroupRegister(List<string> serials
        , List<string> tags
        , List<string> locations
        , string RegisterUser
        , string RegisterDateTime
        , string DestinationCode)
    {
        bool Result = false;

        using var transaction = apiContext.Database.BeginTransaction();

        try
        {
            for (int i = 0; i < serials.Count; i++)
            {
                string[] Epctemp =
                {
                       tags[i]
                    };

                var propsToken = new JObject
                {
                    ["DocumentId"] = "",
                    ["LocationCode"] =( locations.Count>0 )? locations[i]:"",
                    ["ProductProductionLine"] = "",
                    ["ProductProductionShift"] = "",
                    ["ProductProperties"] = "",
                    ["DestinationCode"] = DestinationCode
                };

                Result = SRegisterTag(serials[i]
                    , ""
                    , "0"
                    , Epctemp
                    , RegisterUser
                    , "1"
                    , "1"
                    , propsToken.ToString());

                if (!Result)
                {
                    transaction.Rollback();

                    return false;
                }
            }


        }
        catch (Exception ex)
        {
            logger.LogWarning(ex, ex.Message);

            transaction.Rollback();

            return false;
        }

        transaction.Commit();

        return true;
    }

    public bool SProductRegisterOffline(List<RegisterOfflineTagsCommand> commands)
    {

        SInsertStationSyncDataLog("2", DateTime.Now);

        bool Result = false;

        using var transaction = apiContext.Database.BeginTransaction();

        try
        {
            foreach (RegisterOfflineTagsCommand command in commands)
            {
                for (int i = 0; i < command.ProductSerial.Count; i++)
                {
                    string[] Epctemp =
                    {
                        command.TagEpc[i]
                    };

                    string location;

                    if (command.Location is not null 
                        && command.Location.Any())
                    {
                        location = command.Location[i];
                    }
                    else
                    {
                        location = command.ProductZone;
                    }

                    var propsToken = new JObject
                    {
                        ["DocumentId"] = command.ProductDocCode,
                        ["LocationCode"] = location,
                        ["ProductProductionLine"] = command.ProductProduceLine,
                        ["ProductProductionShift"] = command.ProductProduceShift,
                        ["ProductProperties"] = command.ProductProperties,
                        ["DestinationCode"] = command.DestinationCode
                    };

                    Result = SRegisterTag(command.ProductSerial[i]
                        , command.ProductCode
                        , "0"
                        , Epctemp
                        , command.RegisterUser
                        , "1"
                        , "1"
                        , propsToken.ToString());

                    if (!Result)
                    {
                        transaction.Rollback();

                        return false;
                    }
                }

            }
        }
        catch (Exception ex)
        {
            logger.LogWarning(ex, ex.Message);

            transaction.Rollback();

            return false;
        }

        transaction.Commit();

        return true;
    }

    public DataTable SRepRegister
    (
    string ProductCode,
    string FromDate,
    string ToDate,
    string ProductLine,
    string ProductShift,
    string User,
    string TechnicalCode = ""
    )
    {
        string[] StartShiftTime = new string[3];
        DataTable shiftList = SPGetShiftStartENDList();

        foreach (DataRow dr in shiftList.Rows)
        {
            string Temp = dr["fld_ProductPropertyBDesc"].ToString().Split('-')[0].Split(':')[0] + dr["fld_ProductPropertyBDesc"].ToString().Split('-')[0].Split(':')[1] + "01";
            StartShiftTime[Convert.ToInt32(dr["fld_ProductPropertyBId"].ToString()) - 1] = Temp;
        }

        string whereKey = "";

        if (ProductCode != "")
        {
            whereKey += " (Tags.ProductCode=N'" + ProductCode + "')  AND";
        }

        if (FromDate != "")
        {
            whereKey += " (Tags.TagRegisterShamsiUnixDate >= '" + FromDate + StartShiftTime[0] + "')  AND";
        }

        if (ToDate != "")
        {
            whereKey += " (Tags.TagRegisterShamsiUnixDate <= '" + ToDate + StartShiftTime[0] + "')  AND";
        }

        if (ProductLine != "")
        {
            whereKey += " (Tags.fld_ProductPropertyAId=N'" + ProductLine + "')  AND";
        }

        if (TechnicalCode != "")
        {
            whereKey += " (Tags.RegCode=N'" + TechnicalCode + "')  AND";

        }

        if (ProductShift != "")
        {
            switch (ProductShift)
            {
                case "1":
                    whereKey += " (SUBSTRING(Tags.TagRegisterShamsiUnixDate, 9, 6) >= '" + StartShiftTime[0] + "')  AND  (SUBSTRING(Tags.TagRegisterShamsiUnixDate, 9, 6) < '" + StartShiftTime[1] + "')  AND";

                    break;
                case "2":
                    whereKey += " (SUBSTRING(Tags.TagRegisterShamsiUnixDate, 9, 6) >= '" + StartShiftTime[1] + "')  AND  (SUBSTRING(Tags.TagRegisterShamsiUnixDate, 9, 6) < '" + StartShiftTime[2] + "')  AND";

                    break;
                case "3":
                    whereKey += " (( (SUBSTRING(Tags.TagRegisterShamsiUnixDate, 9, 6) >= '" + StartShiftTime[2] + "')  AND (SUBSTRING(Tags.TagRegisterShamsiUnixDate, 9, 6) < '240000') ) OR ( (SUBSTRING(Tags.TagRegisterShamsiUnixDate, 9, 6) >= '000001' ) and (SUBSTRING(Tags.TagRegisterShamsiUnixDate, 9, 6) < '" + StartShiftTime[0] + "' )))  AND";
                    break;
            }
        }

        if (User != "")
        {
            whereKey += " (Tags.Username=N'" + User + "')  AND";
        }

        if (whereKey.Substring(whereKey.Length - 3, 3) == "AND")
        {
            whereKey = whereKey.Substring(0, whereKey.Length - 3);
        }

        var dtProducts = new DataTable();
        dtProducts.Columns.Add("ProductSerial", typeof(string));
        dtProducts.Columns.Add("ProductCode", typeof(string));
        dtProducts.Columns.Add("ProductName", typeof(string));
        dtProducts.Columns.Add("RegCode", typeof(string));
        dtProducts.Columns.Add("ProductStatusTitle", typeof(string));
        dtProducts.Columns.Add("ProductCount", typeof(string));
        dtProducts.Columns.Add("TagRegisterShamsiUnixDate", typeof(string));
        dtProducts.Columns.Add("Username", typeof(string));
        dtProducts.Columns.Add("fld_ProductPropertyATitle", typeof(string));
        dtProducts.Columns.Add("fld_ProductPropertyBTitle", typeof(string));
        dtProducts.Columns.Add("TagEpc", typeof(string));
        dtProducts.Columns.Add("TagZone", typeof(string));
        dtProducts.Columns.Add("ProductProperties", typeof(string));
        dtProducts.Columns.Add("ProductTypeTitle", typeof(string));
        dtProducts.Columns.Add("ProductSize", typeof(string));
        dtProducts.Columns.Add("RDate", typeof(string));

        try
        {
            var sqlCommand = @"
                     SELECT        TOP (5000) Tags.ProductSerial, Tags.ProductCode, Tags.ProductName, Tags.RegCode, tbl_ProductStatus.ProductStatusTitle, Tags.ProductCount, Tags.TagRegisterShamsiUnixDate, Tags.Username, 
                         tbl_ProductPropertyA.fld_ProductPropertyATitle, tbl_ProductPropertyB.fld_ProductPropertyBTitle, Tags.TagEpc, Tags.TagZone, Tags.ProductProperties, tbl_ProductType.ProductTypeTitle, tbl_Products.ProductSize, 
                         COALESCE
                             ((SELECT        TOP (1) RTagsMovementDate + '  ' + RTagsMovementTime AS Expr1
                                 FROM            tbl_TagsMovement AS tbl_TagsMovement_1
                                 WHERE        (ProductSerial = Tags.ProductSerial)
                                 ORDER BY RMovementActionId DESC), N'-') AS RDate
FROM            tbl_Tags AS Tags LEFT OUTER JOIN
                         tbl_ProductPropertyA ON Tags.fld_ProductPropertyAId = tbl_ProductPropertyA.fld_ProductPropertyAId LEFT OUTER JOIN
                         tbl_ProductPropertyB ON Tags.fld_ProductPropertyBId = tbl_ProductPropertyB.fld_ProductPropertyBId LEFT OUTER JOIN
                         tbl_Products ON Tags.ProductCode = tbl_Products.ProductCode LEFT OUTER JOIN
                         tbl_ProductStatus ON Tags.ProductStatus = tbl_ProductStatus.ProductStatusCode LEFT OUTER JOIN
                         tbl_ProductType ON Tags.ProductType = tbl_ProductType.ProductTypeCode
                        "
                    + (whereKey != string.Empty ? " Where " + whereKey : "") +
                    " ORDER BY Tags.ProductSerial  "
            ;


            return dataAccess.SqlDataAdapter(sqlCommand);
        }
        catch (Exception exception)
        {
            return dtProducts;
        }
    }

    public DataTable SRepRegisterTag
      (
      string ProductCode,
      string FromDate,
      string ToDate,
      string ProductLine,
      string ProductShift,
      string User,
      string TechnicalCode,
      string ProductStatus,
      string ProductSerial
      )
    {
        string[] StartShiftTime = new string[3];
        DataTable shiftList = SPGetShiftStartENDList();
        foreach (DataRow dr in shiftList.Rows)
        {
            string Temp = dr["fld_ProductPropertyBDesc"].ToString().Split('-')[0].Split(':')[0] + dr["fld_ProductPropertyBDesc"].ToString().Split('-')[0].Split(':')[1] + "01";
            StartShiftTime[Convert.ToInt32(dr["fld_ProductPropertyBId"].ToString()) - 1] = Temp;
        }
        string whereKey = "";

        if (ProductCode != "")
        {
            whereKey += " (Tags.ProductCode=N'" + ProductCode + "')  AND";
        }
        if (ProductStatus != "")
        {
            whereKey += " (Tags.ProductStatus=N'" + ProductStatus + "')  AND";
        }
        if (ProductSerial != "")
        {
            whereKey += " (Tags.ProductSerial=N'" + ProductSerial + "')  AND";
        }
        if (FromDate != "")
        {
            whereKey += " (Tags.TagRegisterShamsiUnixDate >= '" + FromDate + StartShiftTime[0] + "')  AND";
        }
        if (ToDate != "")
        {
            whereKey += " (Tags.TagRegisterShamsiUnixDate <= '" + ToDate + StartShiftTime[0] + "')  AND";
        }
        if (ProductLine != "")
        {
            whereKey += " (Tags.fld_ProductPropertyAId=N'" + ProductLine + "')  AND";
        }
        if (TechnicalCode != "")
        {
            whereKey += " (Tags.RegCode=N'" + TechnicalCode + "')  AND";
        }
        if (ProductShift != "")
        {
            switch (ProductShift)
            {
                case "1":
                    whereKey += " (SUBSTRING(Tags.TagRegisterShamsiUnixDate, 9, 6) >= '" + StartShiftTime[0] + "')  AND  (SUBSTRING(Tags.TagRegisterShamsiUnixDate, 9, 6) < '" + StartShiftTime[1] + "')  AND";

                    break;
                case "2":
                    whereKey += " (SUBSTRING(Tags.TagRegisterShamsiUnixDate, 9, 6) >= '" + StartShiftTime[1] + "')  AND  (SUBSTRING(Tags.TagRegisterShamsiUnixDate, 9, 6) < '" + StartShiftTime[2] + "')  AND";

                    break;
                case "3":
                    whereKey += " (( (SUBSTRING(Tags.TagRegisterShamsiUnixDate, 9, 6) >= '" + StartShiftTime[2] + "')  AND (SUBSTRING(Tags.TagRegisterShamsiUnixDate, 9, 6) < '240000') ) OR ( (SUBSTRING(Tags.TagRegisterShamsiUnixDate, 9, 6) >= '000001' ) and (SUBSTRING(Tags.TagRegisterShamsiUnixDate, 9, 6) < '" + StartShiftTime[0] + "' )))  AND";
                    break;
            }
        }
        if (User != "")
        {
            whereKey += " (Tags.Username=N'" + User + "')  AND";
        }

        if (!string.IsNullOrEmpty(whereKey))
        {
            if (whereKey.Substring(whereKey.Length - 3, 3) == "AND")
            {
                whereKey = whereKey.Substring(0, whereKey.Length - 3);
            }
        }

        var dtProducts = new DataTable();

        var sqlCommand = @"SELECT        TOP (5000) Tags.ProductSerial, Tags.ProductCode, Tags.ProductName, Tags.RegCode, tbl_ProductStatus.ProductStatusTitle, Tags.ProductCount, Tags.TagRegisterShamsiUnixDate, COALESCE(Tags.Username,N'') AS Username, 
                         tbl_ProductPropertyA.fld_ProductPropertyATitle, tbl_ProductPropertyB.fld_ProductPropertyBTitle, Tags.TagEpc, Tags.TagZone, Tags.ProductProperties, tbl_ProductType.ProductTypeTitle, tbl_Products.ProductSize, 
                         COALESCE
                             ((SELECT        TOP (1) RTagsMovementDate + '  ' + RTagsMovementTime AS Expr1
                                 FROM            tbl_TagsMovement AS tbl_TagsMovement_1
                                 WHERE        (ProductSerial = Tags.ProductSerial)
                                 ORDER BY RMovementActionId DESC), N'-') AS RDate, 
                         CASE WHEN Tags.TagStatus = 0 THEN N'انبارهای تولید' WHEN Tags.TagStatus = 1 THEN N'انبارهای محصول' WHEN Tags.TagStatus = 2 THEN N'انبارهای بارگیری' ELSE N'-' END AS TagStatus
FROM            tbl_Tags AS Tags LEFT OUTER JOIN
                         tbl_ProductPropertyA ON Tags.fld_ProductPropertyAId = tbl_ProductPropertyA.fld_ProductPropertyAId LEFT OUTER JOIN
                         tbl_ProductPropertyB ON Tags.fld_ProductPropertyBId = tbl_ProductPropertyB.fld_ProductPropertyBId LEFT OUTER JOIN
                         tbl_Products ON Tags.ProductCode = tbl_Products.ProductCode LEFT OUTER JOIN
                         tbl_ProductStatus ON Tags.ProductStatus = tbl_ProductStatus.ProductStatusCode LEFT OUTER JOIN
                         tbl_ProductType ON Tags.ProductType = tbl_ProductType.ProductTypeCode
                        "
                + (whereKey != string.Empty ? " Where " + whereKey : "") +
                " ORDER BY Tags.ProductSerial  ";


        return dataAccess.SqlDataAdapter(sqlCommand);
    }



    public DataTable SRepRegisterTagSummaryGroupBySizeANDRegCode(GetRegisterRequestFilter filter)
    {
        string userId = httpContext.User.GetUserId();

        string[] StartShiftTime = new string[3];
        DataTable shiftList = SPGetShiftStartENDList();

        foreach (DataRow dr in shiftList.Rows)
        {
            string Temp = dr["fld_ProductPropertyBDesc"].ToString().Split('-')[0].Split(':')[0] + dr["fld_ProductPropertyBDesc"].ToString().Split('-')[0].Split(':')[1] + "01";

            StartShiftTime[Convert.ToInt32(dr["fld_ProductPropertyBId"].ToString()) - 1] = Temp;
        }

        string whereKey = "";




        if (filter.ProductCode != "-1")
        {
            if (!string.IsNullOrEmpty(whereKey))
            {
                whereKey += " AND ";
            }


            whereKey += " (Tags.ProductCode=" + filter.ProductCode + ") ";
        }

        if (filter.Qc != "-1")
        {
            if (!string.IsNullOrEmpty(whereKey))
            {
                whereKey += " AND ";
            }

            whereKey += " (Tags.ProductStatus=" + filter.Qc + ")  ";
        }

        if (filter.ProductSerial != "-1")
        {
            if (!string.IsNullOrEmpty(whereKey))
            {
                whereKey += " AND ";
            }


            whereKey += " (Tags.ProductSerial=" + filter.ProductSerial + ")  ";




        }

        if (filter.ProductOldSerial != "-1")
        {
            if (!string.IsNullOrEmpty(whereKey))
            {
                whereKey += " AND ";
            }


            whereKey += " (Tags.DeviceIp=" + filter.ProductOldSerial + ")  ";




        }

        if (filter.FromDate != "-1")
        {
            if (!string.IsNullOrEmpty(whereKey))
            {
                whereKey += " AND ";
            }

            whereKey += " (Tags.TagRegisterShamsiUnixDate >= " + filter.FromDate + StartShiftTime[0] + ")  ";
        }

        if (filter.ToDate != "-1")
        {
            if (!string.IsNullOrEmpty(whereKey))
            {
                whereKey += " AND ";
            }


            whereKey += " (Tags.TagRegisterShamsiUnixDate <= " + filter.ToDate + StartShiftTime[0] + ")  ";
        }



        if (filter.FromTime != "-1")
        {
            if (!string.IsNullOrEmpty(whereKey))
            {
                whereKey += " AND ";
            }



            whereKey += " (SUBSTRING(Tags.TagRegisterShamsiUnixDate, 9, 6) >= " + filter.FromTime + ")   ";

        }
        if (filter.ToTime != "-1")
        {
            if (!string.IsNullOrEmpty(whereKey))
            {
                whereKey += " AND ";
            }



            whereKey += " (SUBSTRING(Tags.TagRegisterShamsiUnixDate, 9, 6) < " + filter.ToTime + ")   ";

        }

        if (filter.Line != "-1")
        {
            if (!string.IsNullOrEmpty(whereKey))
            {
                whereKey += " AND ";
            }


            whereKey += " (Tags.fld_ProductPropertyAId =''" + filter.Line + "'')  ";
        }

        if (filter.TechnicalCode != "-1")
        {
            if (!string.IsNullOrEmpty(whereKey))
            {
                whereKey += " AND ";
            }


            if (!filter.TechnicalCodeLike)
            {

                whereKey += " (Tags.RegCode=" + filter.TechnicalCode + ")  ";
            }
            else
            {

                whereKey += " (Tags.RegCode LIKE N'%" + filter.TechnicalCode + "%')  ";
            }
        }

        if (filter.Shift != "-1")
        {
            if (!string.IsNullOrEmpty(whereKey))
            {
                whereKey += " AND ";
            }

            whereKey += " (Tags.fld_ProductPropertyBId =" + filter.Shift + ")";


        }


        if (filter.Size != "-1")
        {
            if (!string.IsNullOrEmpty(whereKey))
            {
                whereKey += " AND ";
            }

            whereKey += $" Tags.fld_ProductPropertyCId  = {filter.Size}";

        }

        if (filter.ContractStatus != "-1")
        {
            if (!string.IsNullOrEmpty(whereKey))
            {
                whereKey += " AND ";
            }


            whereKey += " (Tags.ContractStatus=" + filter.ContractStatus + ") ";

        }

        if (filter.ProductGroup != "-1")
        {
            if (!string.IsNullOrEmpty(whereKey))
            {
                whereKey += " AND ";
            }


            whereKey += $" Tags.fld_ProductGroup  = {filter.ProductGroup} ";

        }

        if (filter.ProductBrand != "-1")
        {
            if (!string.IsNullOrEmpty(whereKey))
            {
                whereKey += " AND ";
            }


            whereKey += $" Tags.fld_ProductBrand  = N'{filter.ProductBrand}' ";

        }

        if (filter.RegisterDevice != "-1")
        {
            if (!string.IsNullOrEmpty(whereKey))
            {
                whereKey += " AND ";
            }


            whereKey += $" Tags.DeviceId  = {filter.RegisterDevice} ";


        }

        if (filter.InspectStatus != "-1")
        {
            if (!string.IsNullOrEmpty(whereKey))
            {
                whereKey += " AND ";
            }


            switch (filter.InspectStatus)
            {
                case "0":
                    whereKey += $"Tags.Lock = 1 AND Tags.fld_LastInspectResult <> [] ";


                    break;

                case "1":
                    whereKey += $"Tags.Lock = 0 AND Tags.fld_LastInspectResult <> [] ";


                    break;

                case "2":
                    whereKey += $"Tags.Lock = 0 AND Tags.fld_LastInspectResult = [] ";


                    break;

                default:
                    break;
            }
        }

        if (whereKey != "")
        { whereKey = " where " + whereKey; }
        DataTable dtProducts = new();

        string cmd =
           $@"  declare @columns nvarchar(max) = '', @sqlcmd    NVARCHAR(MAX) = '';
Select @columns +=  '['+ [SourceTable].ProductStatusTitle + '],' FROM (SELECT  Distinct tbl_ProductStatus.ProductStatusTitle FROM tbl_ProductStatus) as [SourceTable] ;
SET @columns = LEFT(@columns, LEN(@columns) - 1); 

SET @sqlcmd = 
'SELECT * 
FROM (SELECT        tbl_ProductPropertyA.fld_ProductPropertyATitle, Tags.RegCode, tbl_ProductPropertyC.fld_ProductPropertyCTitle, tbl_ProductStatus.ProductStatusTitle AS Qc, SUM(Tags.ProductCount) AS Count, 
                              COALESCE (JSON_VALUE(tbl_Products.ProductTechnicalData, ''$.description''), N'''') AS ProductType
FROM            tbl_Tags AS Tags LEFT OUTER JOIN
                         tbl_ProductPropertyA ON Tags.fld_ProductPropertyAId = tbl_ProductPropertyA.fld_ProductPropertyAId LEFT OUTER JOIN
                         tbl_Products ON Tags.ProductCode = tbl_Products.ProductCode LEFT OUTER JOIN
                         tbl_ProductPropertyC ON tbl_Products.ProductSize = tbl_ProductPropertyC.fld_ProductPropertyCId LEFT OUTER JOIN
                         tbl_ProductStatus ON tbl_Products.ProductStatus = tbl_ProductStatus.ProductStatusCode
 {whereKey}
GROUP BY Tags.RegCode, COALESCE (JSON_VALUE(tbl_Products.ProductTechnicalData, ''$.description''), N'''') , Tags.fld_ProductPropertyCId, tbl_ProductPropertyC.fld_ProductPropertyCTitle, tbl_ProductStatus.ProductStatusTitle, tbl_ProductPropertyA.fld_ProductPropertyATitle 
                          ) as [SourceTable]

pivot (SUM([SourceTable].[COUNT]) 
FOR [SourceTable].Qc IN ('+@columns+')) 
as [PivotTable] ORDER BY [PivotTable].RegCode
';
EXECUTE sp_executesql @sqlcmd;";


        logger.LogInformation("SRepRegisterTagSummaryGroupBySizeANDRegCode" + Environment.NewLine +
            JsonConvert.SerializeObject(filter) + Environment.NewLine +
            " Command : " + cmd, new KeyValuePair<string, object>("UserId", userId));


        return dataAccess.SqlDataAdapter(cmd);
    }


