                    whereKey += " (SUBSTRING(Tags.TagRegisterShamsiUnixDate, 9, 6) >= '" + StartShiftTime[0] + "')  AND  (SUBSTRING(Tags.TagRegisterShamsiUnixDate, 9, 6) < '" + StartShiftTime[1] + "')  ";
                    SubQuerywhereKey += " (SUBSTRING(TagRegisterShamsiUnixDate, 9, 6) >= '" + StartShiftTime[0] + "')  AND  (SUBSTRING(TagRegisterShamsiUnixDate, 9, 6) < '" + StartShiftTime[1] + "')  ";

