            }


            whereKey += " (SUBSTRING(Tags.TagRegisterShamsiUnixDate, 9, 6) < '" + filter.ToTime + "')   ";
            SubQuerywhereKey += " (SUBSTRING(TagRegisterShamsiUnixDate, 9, 6) < '" + filter.ToTime + "')   ";

        }
        if (filter.Size != "-1")
        {
            if (!string.IsNullOrEmpty(whereKey))
            {
                whereKey += " AND ";
            }

            if (!string.IsNullOrEmpty(SubQuerywhereKey))
            {
                SubQuerywhereKey += " AND ";
            }

            whereKey += $" Tags.fld_ProductPropertyCId  = N'{filter.Size}' ";

            SubQuerywhereKey += $" (Tags.fld_ProductPropertyCId = N'{filter.Size}')  ";

            groupBy += ", Tags.fld_ProductPropertyCId";
        }




        if (filter.ContractStatus != "-1")
        {
            if (!string.IsNullOrEmpty(whereKey))
            {
                whereKey += " AND ";
            }

            if (!string.IsNullOrEmpty(SubQuerywhereKey))
            {
                SubQuerywhereKey += " AND ";
            }

            SubQuerywhereKey += " (ContractStatus=N'" + filter.ContractStatus + "') ";
            whereKey += " (Tags.ContractStatus=N'" + filter.ContractStatus + "') ";
            groupBy += " ,Tags.ContractStatus";
        }

        if (filter.ProductGroup != "-1")
        {
            if (!string.IsNullOrEmpty(whereKey))
            {
                whereKey += " AND ";
            }

            if (!string.IsNullOrEmpty(SubQuerywhereKey))
            {
                SubQuerywhereKey += " AND ";
            }

            whereKey += $" Tags.fld_ProductGroup  = N'{filter.ProductGroup}' ";

            SubQuerywhereKey += $" (Tags.fld_ProductGroup = N'{filter.ProductGroup}')  ";

            groupBy += ", Tags.fld_ProductGroup";
        }

        if (filter.ProductBrand != "-1")
        {
            if (!string.IsNullOrEmpty(whereKey))
            {
                whereKey += " AND ";
            }

            if (!string.IsNullOrEmpty(SubQuerywhereKey))
            {
                SubQuerywhereKey += " AND ";
            }

            whereKey += $" Tags.fld_ProductBrand  = N'{filter.ProductBrand}' ";

            SubQuerywhereKey += $" (Tags.fld_ProductBrand = N'{filter.ProductBrand}')  ";

            groupBy += ", Tags.fld_ProductBrand";
        }

        if (filter.RegisterDevice != "-1")
        {
            if (!string.IsNullOrEmpty(whereKey))
            {
                whereKey += " AND ";
            }

            if (!string.IsNullOrEmpty(SubQuerywhereKey))
            {
                SubQuerywhereKey += " AND ";
            }

            whereKey += $" Tags.DeviceId  = N'{filter.RegisterDevice}' ";

            SubQuerywhereKey += $" (Tags.DeviceId = N'{filter.RegisterDevice}')  ";
        }

        DataTable dtProducts = new();

        string sqlCommand =
                @"SELECT DISTINCT TOP (5000) Tags.ProductCode, Tags.ProductName, Tags.RegCode , tbl_ProductStatus.ProductStatusTitle,
                  COUNT( Tags.ProductSerial) as [Count], SUM(Tags.ProductCount)as [SumCount] ,COALESCE(tbl_Products.ProductSize,N'') as [Size], 
                  (select COUNT(DISTINCT InnerTags.ProductSerial) FROM tbl_Tags AS [InnerTags] WHERE InnerTags.ProductCode = Tags.ProductCode AND InnerTags.TagStatus = 0 " + (SubQuerywhereKey == string.Empty ? "" : " AND " + SubQuerywhereKey) + @")  as [NotEnterCount] , 
                  COALESCE(ContractStatus,N'0') AS ContractStatus,
                  COALESCE(tbl_ProductGroup.fld_ProductGroupTitle,N'') AS ProductGroup,
				  COALESCE(tbl_ProductBrand.fld_ProductBrandTitle,N'') AS ProductBrand,
                  CASE Tags.DeviceId WHEN N'0' THEN N'کیوسک رجیستر' WHEN N'' THEN N'هند هلد' ELSE N'مشخص نشده' END AS [RegisterDevice]
                  FROM            tbl_Tags AS Tags LEFT OUTER JOIN
                  tbl_ProductPropertyA ON Tags.fld_ProductPropertyAId = tbl_ProductPropertyA.fld_ProductPropertyAId LEFT OUTER JOIN
                  tbl_ProductPropertyB ON Tags.fld_ProductPropertyBId = tbl_ProductPropertyB.fld_ProductPropertyBId LEFT OUTER JOIN
                  tbl_Products ON Tags.ProductCode = tbl_Products.ProductCode LEFT OUTER JOIN
                  tbl_ProductStatus ON Tags.ProductStatus = tbl_ProductStatus.ProductStatusCode LEFT OUTER JOIN
                  tbl_ProductType ON Tags.ProductType = tbl_ProductType.ProductTypeCode LEFT OUTER JOIN
				  tbl_ProductGroup ON Tags.fld_ProductGroup = tbl_ProductGroup.fld_ProductGroupCode LEFT OUTER JOIN
				  tbl_ProductBrand ON Tags.fld_ProductBrand = tbl_ProductBrand.fld_ProductBrandCode"
                + (whereKey != string.Empty ? " Where " + whereKey : "")
                + groupBy
                + " ORDER BY Tags.ProductCode ASC  ";

        return dataAccess.SqlDataAdapter(sqlCommand);
    }


    public DataTable SRepRegisterTagSummary(List<ReportFilter> reportFilters)
    {
        string userId = httpContext.User.GetUserId();

        List<string> whereList = new();

        List<string> subWhereList = new();
        List<string> subNoEnterWhereList = new();
        subNoEnterWhereList.Add("InnerTags.TagStatus = 0");

        subNoEnterWhereList.Add("InnerTags.ProductCode = Tags.ProductCode");
        subWhereList.Add("InnerTags.ProductCode = Tags.ProductCode");

        List<string> inspectStatusCountSubWhereList = new()
        {
            "InnerTags.ProductCode = Tags.ProductCode",
            "InnerTags.RegCode = Tags.RegCode",
            "InnerTags.ProductStatus = Tags.ProductStatus",
            "InnerTags.fld_ProductPropertyAId = Tags.fld_ProductPropertyAId",
            "InnerTags.ContractStatus = Tags.ContractStatus",
            "InnerTags.fld_ProductGroup = Tags.fld_ProductGroup",
            "InnerTags.fld_ProductBrand = Tags.fld_ProductBrand",
            "InnerTags.DeviceId = Tags.DeviceId"
        };

        //string groupBy = @" GROUP BY Tags.ProductCode,Tags.ProductName,Tags.RegCode,tbl_ProductStatus.ProductStatusTitle,
        //                 tbl_Products.ProductSize, Tags.ContractStatus ,tbl_ProductGroup.fld_ProductGroupTitle ,tbl_ProductBrand.fld_ProductBrandTitle, Tags.DeviceId
        //               , tbl_ProductPropertyA.fld_ProductPropertyATitle, Tags.fld_ProductPropertyAId,Tags.ProductStatus,Tags.fld_ProductGroup,Tags.fld_ProductBrand
        //               , COALESCE(Tags.ProductCount / tbl_Products.ProductValue,0)";


        string groupBy = @" GROUP BY Tags.ProductCode,Tags.ProductName,Tags.RegCode,tbl_ProductStatus.ProductStatusTitle,
                         tbl_Products.ProductSize, Tags.ContractStatus ,tbl_ProductGroup.fld_ProductGroupTitle ,tbl_ProductBrand.fld_ProductBrandTitle, Tags.DeviceId
                       , tbl_ProductPropertyA.fld_ProductPropertyATitle, Tags.fld_ProductPropertyAId,Tags.ProductStatus,Tags.fld_ProductGroup,Tags.fld_ProductBrand
                        ";


        string[] shiftStartTime = new string[3];
        DataTable shifts = SPGetShiftStartENDList();

        foreach (DataRow dr in shifts.Rows)
        {
            string temp = dr["fld_ProductPropertyBDesc"].ToString().Split('-')[0];

            shiftStartTime[Convert.ToInt32(dr["fld_ProductPropertyBId"].ToString()) - 1] = temp;
        }

        foreach (ReportFilter filter in reportFilters)
        {
            string subQueryWhereCommand = string.Empty;

            if (filter.SqlWhereCommand.HasValue())
            {
                continue;
            }

            if (filter.Type.Equals(FilterType.Dynamic))
            {
                filter.SqlWhereCommand = $"JSON_VALUE(Tags.ProductProperties,N'$.\"{filter.FieldName}\"')";

                subQueryWhereCommand = $"JSON_VALUE(InnerTags.ProductProperties,N'$.\"{filter.FieldName}\"')";

                whereList.Add(DynamicFilteringTools.GetDynamicWhere(filter));

                subWhereList.Add(DynamicFilteringTools.GetDynamicWhere(filter).Replace(filter.SqlWhereCommand, subQueryWhereCommand));
                subNoEnterWhereList.Add(DynamicFilteringTools.GetDynamicWhere(filter).Replace(filter.SqlWhereCommand, subQueryWhereCommand));
            }
            else if (filter.Type.Equals(FilterType.Static))
            {
                switch (filter.FieldName)
                {
                    case "ProductCode":
                        filter.SqlWhereCommand = "Tags.ProductCode";
                        subQueryWhereCommand = "InnerTags.ProductCode";
                        break;

                    case "Qc":
                        filter.SqlWhereCommand = "Tags.ProductStatus";
                        subQueryWhereCommand = "InnerTags.ProductStatus";
                        break;

                    case "ProductSerial":
                        filter.SqlWhereCommand = "Tags.ProductSerial";
                        subQueryWhereCommand = "ProductSerial";
                        break;

                    case "FromDate":
                        filter.SqlWhereCommand = "Tags.TagRegisterShamsiUnixDate";
                        subQueryWhereCommand = "InnerTags.TagRegisterShamsiUnixDate";
                        filter.Values = filter.Values.Select(date => $"{(date.Replace("/", "") + shiftStartTime[0])}").ToList();
                        break;

                    case "ToDate":
                        filter.SqlWhereCommand = "Tags.TagRegisterShamsiUnixDate";
                        subQueryWhereCommand = "InnerTags.TagRegisterShamsiUnixDate";
                        filter.Values = filter.Values.Select(date => $"{(date.Replace("/", "") + shiftStartTime[0])}").ToList();
                        break;

                    case "Line":
                        filter.SqlWhereCommand = "Tags.fld_ProductPropertyAId";
                        subQueryWhereCommand = "InnerTags.fld_ProductPropertyAId";
                        break;

                    case "TechnicalCode":
                        filter.SqlWhereCommand = "Tags.RegCode";
                        subQueryWhereCommand = "InnerTags.RegCode";
                        break;

                    case "Shift":
                        filter.SqlWhereCommand = "Tags.fld_ProductPropertyBId";
                        subQueryWhereCommand = "InnerTags.fld_ProductPropertyBId";
                        break;

                    case "User":
                        whereList.Add("( (TRY_CONVERT(UNIQUEIDENTIFIER, Tags.Username) IS NULL AND Tags.Username=N'" + filter.Value +
                                    "') OR (TRY_CONVERT(UNIQUEIDENTIFIER, Tags.Username) IS NOT NULL AND " +
                                    " (SELECT tbl_User.Username FROM tbl_User WHERE tbl_User.Id = Tags.Username) = N'" + filter.Value + "')) ");
                        groupBy += " , Tags.Username";
                        break;

                    case "Size":
                        filter.SqlWhereCommand = $"Tags.fld_ProductPropertyCId";
                        subQueryWhereCommand = $"InnerTags.fld_ProductPropertyCId";
                        break;

                    case "ContractStatus":
                        filter.SqlWhereCommand = $"Tags.ContractStatus";
                        subQueryWhereCommand = $"InnerTags.ContractStatus";
                        break;

                    case "ProductGroup":
                        filter.SqlWhereCommand = $"Tags.fld_ProductGroup";
                        subQueryWhereCommand = $"InnerTags.fld_ProductGroup";
                        break;

                    case "ProductBrand":
                        filter.SqlWhereCommand = $"Tags.fld_ProductBrand";
                        subQueryWhereCommand = $"InnerTags.fld_ProductBrand";
                        break;

                    case "RegisterDevice":
                        filter.SqlWhereCommand = $"Tags.DeviceId";
                        subQueryWhereCommand = $"InnerTags.DeviceId";
                        break;

                    case "InspectStatus":
                        switch (filter.Values.First())
                        {
                            case "0":
                                whereList.Add("(Tags.Lock = 1 AND Tags.fld_LastInspectResult <> N'[]' )");
                                subWhereList.Add("(InnerTags.Lock = 1 AND InnerTags.fld_LastInspectResult <> N'[]')");
                                subNoEnterWhereList.Add("(InnerTags.Lock = 1 AND InnerTags.fld_LastInspectResult <> N'[]')");
                                continue;

                            case "1":
                                whereList.Add("(Tags.Lock = 0 AND Tags.fld_LastInspectResult <> N'[]' )");
                                subWhereList.Add("(InnerTags.Lock = 0 AND InnerTags.fld_LastInspectResult <> N'[]')");
                                subNoEnterWhereList.Add("(InnerTags.Lock = 0 AND InnerTags.fld_LastInspectResult <> N'[]')");
                                continue;

                            case "2":
                                whereList.Add("(Tags.Lock = 0 AND Tags.fld_LastInspectResult = N'[]')");
                                subWhereList.Add("(InnerTags.Lock = 0 AND InnerTags.fld_LastInspectResult = N'[]')");
                                subNoEnterWhereList.Add("(InnerTags.Lock = 0 AND InnerTags.fld_LastInspectResult = N'[]')");
                                continue;
                        }
                        break;
                }

                if (filter.SqlWhereCommand.HasValue())
                {
                    whereList.Add(DynamicFilteringTools.GetStaticWhere(filter));

                    if (subQueryWhereCommand.HasValue())
                    {
                        subWhereList.Add(DynamicFilteringTools.GetStaticWhere(filter).Replace(filter.SqlWhereCommand, subQueryWhereCommand));
                        subNoEnterWhereList.Add(DynamicFilteringTools.GetStaticWhere(filter).Replace(filter.SqlWhereCommand, subQueryWhereCommand));
                    }
                }
            }
        }

        DataTable dtProducts = new();

        if (subWhereList.Any())
        {
            inspectStatusCountSubWhereList.AddRange(subWhereList);
        }

        string cmd =
            $@"
            SELECT * , 
            CAST(COALESCE((SELECT TOP(1) [NESTED].SumCount/ProductValue 
                           FROM tbl_Products 
                           WHERE tbl_Products.ProductCode = [NESTED].ProductCode)
                         , 0) AS decimal(18,2))  AS ProductCountInPack
            FROM(
            SELECT DISTINCT TOP (5000) 
                            COALESCE(Tags.ProductCode,N'') AS [ProductCode],
            				Tags.ProductName,
            				Tags.RegCode ,
            				tbl_ProductStatus.ProductStatusTitle,
            				COUNT( Tags.ProductSerial) as [Count],
            				SUM(Tags.ProductCount)as [SumCount] ,
            				COALESCE(tbl_Products.ProductSize,N'') as [Size], 
            				(SELECT COUNT(DISTINCT InnerTags.ProductSerial) 
                            FROM tbl_Tags AS [InnerTags] 
                            {(subNoEnterWhereList.Any() ? " WHERE " + string.Join(" AND ", subNoEnterWhereList) : "")})  as [NotEnterCount] , 
            				COALESCE(ContractStatus,N'0') AS ContractStatus,
            				COALESCE(tbl_ProductGroup.fld_ProductGroupTitle,N'') AS ProductGroup,
            				COALESCE(tbl_ProductBrand.fld_ProductBrandTitle,N'') AS ProductBrand,
            				CASE Tags.DeviceId WHEN N'0' THEN N'کیوسک رجیستر' WHEN N'' THEN N'هند هلد' ELSE N'مشخص نشده' END AS [RegisterDevice],
            				COALESCE(Tags.fld_ProductPropertyAId,N'') AS [LineCode],
            				COALESCE(tbl_ProductPropertyA.fld_ProductPropertyATitle,N'') AS [LineTitle],
            				(SELECT COUNT(DISTINCT InnerTags.ProductSerial)
            					FROM tbl_Tags AS InnerTags
                                {(inspectStatusCountSubWhereList.Any() ? " WHERE " + string.Join(" AND ", inspectStatusCountSubWhereList) : "")}
            					AND InnerTags.Lock = 0 AND InnerTags.fld_LastInspectResult = N'[]'
            					)
            						AS NotInspectCount,
            				(SELECT COUNT(DISTINCT InnerTags.ProductSerial)
            					FROM tbl_Tags AS InnerTags
                                {(inspectStatusCountSubWhereList.Any() ? " WHERE " + string.Join(" AND ", inspectStatusCountSubWhereList) : "")}
            					AND InnerTags.Lock = 1 AND InnerTags.fld_LastInspectResult <> N'[]'
            					)
            						AS FailedInspectCount,
            				(SELECT COUNT(DISTINCT InnerTags.ProductSerial)
            					FROM tbl_Tags AS InnerTags
                                {(inspectStatusCountSubWhereList.Any() ? " WHERE " + string.Join(" AND ", inspectStatusCountSubWhereList) : "")}
            					AND InnerTags.Lock = 0 AND InnerTags.fld_LastInspectResult <> N'[]'
            					)
            						AS AcceptInspectCount
            FROM            tbl_Tags AS Tags LEFT OUTER JOIN
            tbl_ProductPropertyA ON Tags.fld_ProductPropertyAId = tbl_ProductPropertyA.fld_ProductPropertyAId LEFT OUTER JOIN
            tbl_ProductPropertyB ON Tags.fld_ProductPropertyBId = tbl_ProductPropertyB.fld_ProductPropertyBId LEFT OUTER JOIN
            tbl_Products ON Tags.ProductCode = tbl_Products.ProductCode LEFT OUTER JOIN
            tbl_ProductStatus ON Tags.ProductStatus = tbl_ProductStatus.ProductStatusCode LEFT OUTER JOIN
            tbl_ProductType ON Tags.ProductType = tbl_ProductType.ProductTypeCode LEFT OUTER JOIN
            tbl_ProductGroup ON Tags.fld_ProductGroup = tbl_ProductGroup.fld_ProductGroupCode LEFT OUTER JOIN
            tbl_ProductBrand ON Tags.fld_ProductBrand = tbl_ProductBrand.fld_ProductBrandCode 
            {(whereList.Any() ? " WHERE " + string.Join(" AND ", whereList) : "")}
            {groupBy}
           	) AS [NESTED]
            ORDER BY [NESTED].ProductCode DESC
            ";

        return dataAccess.SqlDataAdapter(cmd);
    }

    public DataTable SRepRegisterTagDetailsForWinApp(GetRegisterRequestFilter filter)
    {
        string[] StartShiftTime = new string[3];
        DataTable shiftList = SPGetShiftStartENDList();

        foreach (DataRow dr in shiftList.Rows)
        {
            string Temp = dr["fld_ProductPropertyBDesc"].ToString().Split('-')[0].Split(':')[0] + dr["fld_ProductPropertyBDesc"].ToString().Split('-')[0].Split(':')[1] + "01";
            StartShiftTime[Convert.ToInt32(dr["fld_ProductPropertyBId"].ToString()) - 1] = Temp;
        }

        string whereKey = "";

        if (filter.ProductCode != "-1")
        {
            whereKey += " (Tags.ProductCode=N'" + filter.ProductCode + "')  AND";
        }

        if (filter.Qc != "-1")
        {
            whereKey += " (Tags.ProductStatus=N'" + filter.Qc + "')  AND";
        }

        if (filter.ProductSerial != "-1")
        {
            whereKey += " (Tags.ProductSerial=N'" + filter.ProductSerial + "')  AND";
        }

        if (filter.ProductOldSerial != "-1")
        {
            whereKey += " (Tags.DeviceIp=N'" + filter.ProductOldSerial + "')  AND";
        }

        if (filter.FromDate != "-1")
        {
            whereKey += " (Tags.TagRegisterShamsiUnixDate >= '" + filter.FromDate + StartShiftTime[0] + "')  AND";
        }

        if (filter.ToDate != "-1")
        {
            whereKey += " (Tags.TagRegisterShamsiUnixDate <= '" + filter.ToDate + StartShiftTime[0] + "')  AND";
        }

        if (filter.Line != "-1")
        {
            whereKey += " (Tags.fld_ProductPropertyAId=N'" + filter.Line + "')  AND";
        }

        if (filter.TechnicalCode != "-1")
        {
            whereKey += " (Tags.RegCode=N'" + filter.TechnicalCode + "')  AND";
        }



        if (filter.FromTime != "-1")
        {




            whereKey += " (SUBSTRING(Tags.TagRegisterShamsiUnixDate, 9, 6) >= '" + filter.FromTime + "')   AND";

        }
        if (filter.ToTime != "-1")
        {



            whereKey += " (SUBSTRING(Tags.TagRegisterShamsiUnixDate, 9, 6) < '" + filter.ToTime + "')   AND";

        }

        if (filter.Shift != "-1")
        {
            switch (filter.Shift)
            {
                case "1":
                    whereKey += " (SUBSTRING(Tags.TagRegisterShamsiUnixDate, 9, 6) >= '" + StartShiftTime[0] + "')  AND  (SUBSTRING(Tags.TagRegisterShamsiUnixDate, 9, 6) < '" + StartShiftTime[1] + "')  AND";

                    break;
                case "2":
                    whereKey += " (SUBSTRING(Tags.TagRegisterShamsiUnixDate, 9, 6) >= '" + StartShiftTime[1] + "')  AND  (SUBSTRING(Tags.TagRegisterShamsiUnixDate, 9, 6) < '" + StartShiftTime[2] + "')  AND";

                    break;
                case "3":
                    whereKey += " (( (SUBSTRING(Tags.TagRegisterShamsiUnixDate, 9, 6) >= '" + StartShiftTime[2] + "')  AND (SUBSTRING(Tags.TagRegisterShamsiUnixDate, 9, 6) < '240000') ) OR ( (SUBSTRING(Tags.TagRegisterShamsiUnixDate, 9, 6) >= '000001' ) and (SUBSTRING(Tags.TagRegisterShamsiUnixDate, 9, 6) < '" + StartShiftTime[0] + "' )))  AND";
                    break;
            }
        }

        if (filter.User != "-1")
        {
            whereKey += "( (TRY_CONVERT(UNIQUEIDENTIFIER, Tags.Username) IS NULL AND Tags.Username=N'" + filter.User +
                  "') OR (TRY_CONVERT(UNIQUEIDENTIFIER, Tags.Username) IS NOT NULL AND " +
                  " (SELECT tbl_User.Username FROM tbl_User WHERE tbl_User.Id = Tags.Username) = N'" + filter.User + "')) AND";
        }

        if (filter.ContractStatus != "-1")
        {
            whereKey += " (Tags.ContractStatus=N'" + filter.ContractStatus + "') AND";
        }

        if (filter.ProductGroup != "-1")
        {
            whereKey += $" Tags.fld_ProductGroup  = N'{filter.ProductGroup}' AND";
        }

        if (filter.ProductBrand != "-1")
        {
            whereKey += $" Tags.fld_ProductBrand  = N'{filter.ProductBrand}' AND";
        }

        if (filter.RegisterDevice != "-1")
        {
            whereKey += $" Tags.DeviceId  = N'{filter.RegisterDevice}' AND";
        }


        if (!string.IsNullOrEmpty(whereKey))
        {
            if (whereKey.Substring(whereKey.Length - 3, 3) == "AND")
            {
                whereKey = whereKey.Substring(0, whereKey.Length - 3);
            }
        }

        var dtProducts = new DataTable();

        var sqlCommand = @"SELECT DISTINCT TOP (5000) Tags.ProductCode, Tags.ProductName, Tags.RegCode , tbl_ProductStatus.ProductStatusTitle ,
                         Tags.ProductSerial, Tags.ProductCount as [Count] ,tbl_Products.ProductSize as [Size],
                         SUBSTRING(Tags.TagRegisterShamsiUnixDate,0,5)+'/'+SUBSTRING(Tags.TagRegisterShamsiUnixDate,5,2)+'/'+SUBSTRING(Tags.TagRegisterShamsiUnixDate,7,2)+' - '+SUBSTRING(Tags.TagRegisterShamsiUnixDate,9,2)+':'+SUBSTRING(Tags.TagRegisterShamsiUnixDate,11,2) as [DateTime],
						 COALESCE((SELECT        TOP (1) RTagsMovementDate + ' - ' + RTagsMovementTime AS Expr1
                                 FROM            tbl_TagsMovement AS tbl_TagsMovement_1
                                 WHERE        (ProductSerial = Tags.ProductSerial)
                                 ORDER BY RMovementActionId DESC), N'-') AS [DateTimeEnter],
						 CASE WHEN TRY_CONVERT(UNIQUEIDENTIFIER, Tags.Username) IS NOT NULL THEN  (SELECT tbl_User.Username FROM tbl_User WHERE tbl_User.Id = Tags.Username)
						 ELSE COALESCE(Tags.Username,N'') END AS [Username], COALESCE(tbl_ProductPropertyA.fld_ProductPropertyATitle ,N'') as [Line]
						 , COALESCE(tbl_ProductPropertyB.fld_ProductPropertyBTitle ,N'') as [Line],
						 CASE WHEN Tags.TagStatus = 0 THEN N'انبارهای تولید' WHEN Tags.TagStatus = 1 THEN N'انبارهای محصول' WHEN Tags.TagStatus = 2 THEN N'انبارهای بارگیری' ELSE N'-' END AS [Status],
                         COALESCE(tbl_ProductPropertyB.fld_ProductPropertyBTitle,N'') AS Shift
                         FROM tbl_Tags AS Tags LEFT OUTER JOIN
                         tbl_ProductPropertyA ON Tags.fld_ProductPropertyAId = tbl_ProductPropertyA.fld_ProductPropertyAId LEFT OUTER JOIN
                         tbl_ProductPropertyB ON Tags.fld_ProductPropertyBId = tbl_ProductPropertyB.fld_ProductPropertyBId LEFT OUTER JOIN
                         tbl_Products ON Tags.ProductCode = tbl_Products.ProductCode LEFT OUTER JOIN
                         tbl_ProductStatus ON Tags.ProductStatus = tbl_ProductStatus.ProductStatusCode LEFT OUTER JOIN
                         tbl_ProductType ON Tags.ProductType = tbl_ProductType.ProductTypeCode "
                + (whereKey != string.Empty ? " Where " + whereKey : "")
                + " ORDER BY Tags.ProductSerial ASC  "
        ;

        return dataAccess.SqlDataAdapter(sqlCommand);
    }

    public DataTable SRepRegisterTagDetails(List<ReportFilter> reportFilters)
    {
        string[] shiftStartTime = new string[3];

        DataTable shiftList = SPGetShiftStartENDList();

        foreach (DataRow dr in shiftList.Rows)
        {
            string temp = dr["fld_ProductPropertyBDesc"].ToString().Split('-')[0].Split(':')[0] +
                          dr["fld_ProductPropertyBDesc"].ToString().Split('-')[0].Split(':')[1] + "01";

            shiftStartTime[Convert.ToInt32(dr["fld_ProductPropertyBId"]) - 1] = temp;
        }

        List<string> whereList = new();

        foreach (ReportFilter filter in reportFilters)
        {
            if (filter.SqlWhereCommand.HasValue())
                continue;

            if (filter.Type.Equals(FilterType.Dynamic))
            {
                filter.SqlWhereCommand = $"JSON_VALUE(Tags.ProductProperties,N'$.\"{filter.FieldName}\"')";
                whereList.Add(DynamicFilteringTools.GetDynamicWhere(filter));
            }
            else if (filter.Type.Equals(FilterType.Static))
            {
                switch (filter.FieldName)
                {
                    case "ProductCode":
                        filter.SqlWhereCommand = "Tags.ProductCode";
                        break;

                    case "Qc":
                        filter.SqlWhereCommand = "Tags.ProductStatus";
                        break;

                    case "ProductSerial":
                        filter.SqlWhereCommand = "Tags.ProductSerial";
                        break;

                    case "FromDate":
                        filter.SqlWhereCommand = "Tags.TagRegisterShamsiUnixDate";
                        filter.Values = filter.Values
                            .Select(date => $"{date.Replace("/", "") + shiftStartTime[0]}")
                            .ToList();
                        break;

                    case "ToDate":
                        filter.SqlWhereCommand = "Tags.TagRegisterShamsiUnixDate";
                        filter.Values = filter.Values
                            .Select(date => $"{date.Replace("/", "") + shiftStartTime[0]}")
                            .ToList();
                        break;

                    case "Line":
                        filter.SqlWhereCommand = "Tags.fld_ProductPropertyAId";
                        break;

                    case "TechnicalCode":
                        filter.SqlWhereCommand = "Tags.RegCode";
                        break;

                    case "Shift":
                        filter.SqlWhereCommand = "Tags.fld_ProductPropertyBId";
                        break;

                    case "User":
                        whereList.Add(@"
                    (
                        (TRY_CONVERT(UNIQUEIDENTIFIER, Tags.Username) IS NULL AND Tags.Username = N'" + filter.Value + @"')
                        OR
                        (TRY_CONVERT(UNIQUEIDENTIFIER, Tags.Username) IS NOT NULL 
                            AND U.Username = N'" + filter.Value + @"')
                    )");
                        break;

                    case "Size":
                        filter.SqlWhereCommand = "Tags.fld_ProductPropertyCId";
                        break;

                    case "ContractStatus":
                        filter.SqlWhereCommand = "Tags.ContractStatus";
                        break;

                    case "ProductGroup":
                        filter.SqlWhereCommand = "Tags.fld_ProductGroup";
                        break;

                    case "ProductBrand":
                        filter.SqlWhereCommand = "Tags.fld_ProductBrand";
                        break;

                    case "RegisterDevice":
                        filter.SqlWhereCommand = "Tags.DeviceId";
                        break;

                    case "InspectStatus":
                        switch (filter.Values.First())
                        {
                            case "0":
                                whereList.Add("(Tags.Lock = 1 AND Tags.fld_LastInspectResult <> N'[]')");
                                continue;

                            case "1":
                                whereList.Add("(Tags.Lock = 0 AND Tags.fld_LastInspectResult <> N'[]')");
                                continue;

                            case "2":
                                whereList.Add("(Tags.Lock = 0 AND Tags.fld_LastInspectResult = N'[]')");
                                continue;
                        }
                        break;
                }

                if (filter.SqlWhereCommand.HasValue())
                    whereList.Add(DynamicFilteringTools.GetStaticWhere(filter));
            }
        }

        string sqlCommand = $@"

    SELECT DISTINCT TOP (5000)
        Tags.ProductCode,
        Tags.ProductName,
        Tags.RegCode,
        PS.ProductStatusTitle,
        Tags.ProductSerial,
        Tags.ProductCount AS [Count],
        P.ProductSize AS [Size],
        COALESCE(Tags.ProductProperties,N'{{}}') AS ProductProperties,

        SUBSTRING(Tags.TagRegisterShamsiUnixDate,1,4)+'/'+
        SUBSTRING(Tags.TagRegisterShamsiUnixDate,5,2)+'/'+
        SUBSTRING(Tags.TagRegisterShamsiUnixDate,7,2)+' - '+
        SUBSTRING(Tags.TagRegisterShamsiUnixDate,9,2)+':'+
        SUBSTRING(Tags.TagRegisterShamsiUnixDate,11,2) AS DateTime,

        COALESCE(Mov.Expr1, N'-') AS DateTimeEnter,

        CASE 
            WHEN TRY_CONVERT(UNIQUEIDENTIFIER, Tags.Username) IS NOT NULL 
                THEN U.Username
            ELSE COALESCE(Tags.Username,N'')
        END AS Username,

        COALESCE(A.fld_ProductPropertyATitle ,N'') AS Line,

        CASE 
            WHEN Tags.TagStatus = 0 THEN N'انبارهای تولید'
            WHEN Tags.TagStatus = 1 THEN N'انبارهای محصول'
            WHEN Tags.TagStatus = 2 THEN N'انبارهای بارگیری'
            ELSE N'-'
        END AS Status,

        COALESCE(B.fld_ProductPropertyBTitle,N'') AS Shift,

        COALESCE(Ins.fld_InspectShamsiDate,N'') AS InspectDate,

        CASE 
            WHEN (Tags.Lock = 0 AND Tags.fld_LastInspectResult = N'[]') THEN N'بازرسی نشده'
            WHEN (Tags.Lock = 0 AND Tags.fld_LastInspectResult <> N'[]') THEN N'بازرسی تأیید'
            WHEN (Tags.Lock = 1 AND Tags.fld_LastInspectResult <> N'[]') THEN N'بازرسی مردود'
            ELSE N'-'
        END AS InspectStatus

    FROM tbl_Tags Tags

    LEFT JOIN tbl_ProductPropertyA A
        ON Tags.fld_ProductPropertyAId = A.fld_ProductPropertyAId

    LEFT JOIN tbl_ProductPropertyB B
        ON Tags.fld_ProductPropertyBId = B.fld_ProductPropertyBId

    LEFT JOIN tbl_Products P
        ON Tags.ProductCode = P.ProductCode

    LEFT JOIN tbl_ProductStatus PS
        ON Tags.ProductStatus = PS.ProductStatusCode

    LEFT JOIN tbl_ProductType PT
        ON Tags.ProductType = PT.ProductTypeCode

    LEFT JOIN tbl_User U
        ON TRY_CONVERT(UNIQUEIDENTIFIER, Tags.Username) = U.Id

    OUTER APPLY
    (
        SELECT TOP (1)
            TM.RTagsMovementDate + ' - ' + TM.RTagsMovementTime AS Expr1
        FROM tbl_TagsMovement TM
        WHERE TM.ProductSerial = Tags.ProductSerial
        ORDER BY TM.RMovementActionId DESC
    ) Mov

    OUTER APPLY
    (
        SELECT TOP (1)
            I.fld_InspectShamsiDate
        FROM tbl_Inspect I
        WHERE I.fld_InspectId = Tags.fld_InspectActionId
          AND I.fld_InspectSerial = Tags.ProductSerial
        ORDER BY I.fld_InspectDateTime DESC
    ) Ins

    {(whereList.Any() ? " WHERE " + string.Join(" AND ", whereList) : "")}

    ORDER BY Tags.ProductSerial ASC
    ";

        return dataAccess.SqlDataAdapter(sqlCommand, 120);
    }


    public DataTable SRepExistTag
    (
    string ProductCode,
    string FromDate,
    string ToDate,
    string TechnicalCode,
    string ProductStatus,
    string ProductSerial,
    string TagZone
    )
    {
        string[] StartShiftTime = new string[3];
        DataTable shiftList = SPGetShiftStartENDList();
        foreach (DataRow dr in shiftList.Rows)
        {
            string Temp = dr["fld_ProductPropertyBDesc"].ToString().Split('-')[0].Split(':')[0] + dr["fld_ProductPropertyBDesc"].ToString().Split('-')[0].Split(':')[1] + "01";
            StartShiftTime[Convert.ToInt32(dr["fld_ProductPropertyBId"].ToString()) - 1] = Temp;
        }
        string whereKey = " Where TagStatus=1 AND";

        if (ProductCode != "")
        {
            whereKey += " (Tags.ProductCode=N'" + ProductCode + "')  AND";
        }
        if (ProductStatus != "")
        {
            whereKey += " (Tags.ProductStatus=N'" + ProductStatus + "')  AND";
        }
        if (ProductSerial != "")
        {
            whereKey += " (Tags.ProductSerial=N'" + ProductSerial + "')  AND";
        }
        if (FromDate != "")
        {
            whereKey += " (Tags.TagRegisterShamsiUnixDate >= '" + FromDate + StartShiftTime[0] + "')  AND";
        }
        if (ToDate != "")
        {
            whereKey += " (Tags.TagRegisterShamsiUnixDate <= '" + ToDate + StartShiftTime[0] + "')  AND";
        }
        if (TagZone != "")
        {
            whereKey += " (Tags.TagZone=N'" + TagZone + "')  AND";
        }
        if (TechnicalCode != "")
        {
            whereKey += " (Tags.RegCode Like N'" + TechnicalCode + "%')  AND";
        }



        if (whereKey.Substring(whereKey.Length - 3, 3) == "AND")
        {
            whereKey = whereKey.Substring(0, whereKey.Length - 3);
        }

        var dtProducts = new DataTable();
        dtProducts.Columns.Add("ProductSerial", typeof(string));
        dtProducts.Columns.Add("ProductCode", typeof(string));
        dtProducts.Columns.Add("ProductName", typeof(string));
        dtProducts.Columns.Add("RegCode", typeof(string));
        dtProducts.Columns.Add("ProductStatusTitle", typeof(string));
        dtProducts.Columns.Add("ProductCount", typeof(string));
        dtProducts.Columns.Add("TagRegisterShamsiUnixDate", typeof(string));
        dtProducts.Columns.Add("Username", typeof(string));
        dtProducts.Columns.Add("fld_ProductPropertyATitle", typeof(string));
        dtProducts.Columns.Add("fld_ProductPropertyBTitle", typeof(string));
        dtProducts.Columns.Add("TagEpc", typeof(string));
        dtProducts.Columns.Add("TagZone", typeof(string));
        dtProducts.Columns.Add("ProductProperties", typeof(string));
        dtProducts.Columns.Add("ProductTypeTitle", typeof(string));
        dtProducts.Columns.Add("ProductSize", typeof(string));
        dtProducts.Columns.Add("RDate", typeof(string));


        try
        {
            var sqlCommand = @"SELECT        TOP (10000) Tags.ProductSerial, Tags.ProductCode, Tags.ProductName, Tags.RegCode, tbl_ProductStatus.ProductStatusTitle, Tags.ProductCount, Tags.TagRegisterShamsiUnixDate, Tags.Username, 
                         tbl_ProductPropertyA.fld_ProductPropertyATitle, tbl_ProductPropertyB.fld_ProductPropertyBTitle, Tags.TagEpc, Tags.TagZone, Tags.ProductProperties, tbl_ProductType.ProductTypeTitle, tbl_Products.ProductSize, 
                         COALESCE
                             ((SELECT        TOP (1) RTagsMovementDate + '  ' + RTagsMovementTime AS Expr1
                                 FROM            tbl_TagsMovement AS tbl_TagsMovement_1
                                 WHERE        (ProductSerial = Tags.ProductSerial)
                                 ORDER BY RMovementActionId DESC), N'-') AS RDate
                         FROM            tbl_Tags AS Tags LEFT OUTER JOIN
                         tbl_ProductPropertyA ON Tags.fld_ProductPropertyAId = tbl_ProductPropertyA.fld_ProductPropertyAId LEFT OUTER JOIN
                         tbl_ProductPropertyB ON Tags.fld_ProductPropertyBId = tbl_ProductPropertyB.fld_ProductPropertyBId LEFT OUTER JOIN
                         tbl_Products ON Tags.ProductCode = tbl_Products.ProductCode LEFT OUTER JOIN
                         tbl_ProductStatus ON Tags.ProductStatus = tbl_ProductStatus.ProductStatusCode LEFT OUTER JOIN
                         tbl_ProductType ON Tags.ProductType = tbl_ProductType.ProductTypeCode
                        "
                    + (whereKey != string.Empty ? whereKey : "") +
                    " ORDER BY Tags.ProductSerial  "
            ;


            return dataAccess.SqlDataAdapter(sqlCommand);
        }
        catch (Exception exception)
        {
            return dtProducts;
        }

    }

