            parameters.Add(new("PPMUserId", userToken));
            parameters.Add(new("PPMRegDateTime", DateTime.Now));
            parameters.Add(new("PPMProductCode", code));
            parameters.Add(new("PPMProductSerial", serial));
            parameters.Add(new("PPMProductEPC", epc));
            parameters.Add(new("PPMType", type));
            parameters.Add(new("PPMWMCode", truck));
            parameters.Add(new("PPMWMDriverUserId", "0"));
