            parameters.Add(new("fld_PPMActionId", actionCode));

            childrenCommands.Add(new(cmd, parameters.ToArray()));
        }

        var result = dataAccess.CmdSqlExecuteNonQueryWithTransaction(childrenCommands) > 0;

        /*if (result)
