        string type, string wCode, string fromZoneId, string toZoneId, string storeCode, int count, string actionCode = "0"
          )
    {
        logger.LogInformation("SSavePlacementMissionsByCount"
            , new KeyValuePair<string, object>("userId", userId)
            , new KeyValuePair<string, object>("productCode", productCode)
            , new KeyValuePair<string, object>("productSerial", productSerial)
            , new KeyValuePair<string, object>("productEPC", productEPC)
