    public DataTable SGetProductListInZoneByDate(string code, string zone, string Date, string desticationCode)
    {
        logger.LogInformation("SGetProductListInZoneByDate"
    , new KeyValuePair<string, object>("code", code)
    , new KeyValuePair<string, object>("zone", zone)
    , new KeyValuePair<string, object>("Date", Date)
    , new KeyValuePair<string, object>("desticationCode", desticationCode)
    );

        var cmd =
            $@"SELECT        ProductSerial
FROM            tbl_Tags
WHERE        (ProductCode = '" + code + "') AND (TagRegisterShamsiUnixDate LIKE '%" + Date + "%') AND (TagZone = '" + zone + "') AND (TagInDestinationId = '" + desticationCode + "')";
        return dataAccess.SqlDataAdapter(cmd);
    }

    public DataTable SSearchZone(
           string productCode
         , int minCap
         , int maxCap
         , string zoneCode
         , string location
         , DestinationOperationalType warehouseType
         , bool zoneCodeLike = false) 
    {
        logger.LogInformation("SSearchZone" + Environment.NewLine
                            + "productCode" + productCode + Environment.NewLine
                            + "minCap" + minCap + Environment.NewLine
                            + "maxCap" + maxCap + Environment.NewLine
                            + "zoneCode" + zoneCode + Environment.NewLine
                            + "zoneCodeLike" + zoneCodeLike + Environment.NewLine
                            + "location" + location);

        var cmd = @"SELECT distinct COALESCE(tbl_Zones.id,0) as [id], 
COALESCE(ZoneCode,N'') as [ZoneCode], 
COALESCE(ZoneTitle,N'') as [Title],
COALESCE(ZoneCapacity,0) as [Capacity],
COALESCE(ZoneDimention,N'') as [Dimention],
COALESCE(ZoneParentCode,N'') as [ParentCode], 
CAST(COALESCE(ZoneParentLayer,N'') AS NVARCHAR(512)) as [ParentLayer],
COALESCE(ZoneStoreCode,N'') as [StoreCode],
COALESCE(tbl_Destination.DestinationTitle,N'') as [StoreTitle],
COALESCE(tbl_Destination.DestinationDesc,N'-1') as [StoreType],
COALESCE(ZoneCountPixle,N'') as [CountPixle], 
COALESCE(ZoneOccupiedCapacity,0) as [OccupiedCapacity],
COALESCE(ZoneCapacity,0)-COALESCE(ZoneOccupiedCapacity,0) as [FreeCapacity]
FROM  tbl_Zones 
LEFT JOIN tbl_Tags on tbl_Tags.TagZone = tbl_Zones.ZoneCode
LEFT JOIN tbl_Destination ON tbl_Destination.DestinationCode = tbl_Zones.ZoneStoreCode
                                       ";

        var whereString = string.Empty;

        var parameters = new List<KeyValuePair<string, object>>();

        if (!productCode.Equals("-1"))
        {
            if (!string.IsNullOrEmpty(whereString))
                whereString += " AND ";
            whereString += " tbl_Tags.ProductCode = @PCode ";
            parameters.Add(new("PCode", productCode));
        }

        if (!minCap.Equals(-1))
        {
            if (!string.IsNullOrEmpty(whereString))
                whereString += " AND ";
            whereString += @" @Min <= case tbl_Zones.ZoneCapacity
                                   when 0 then 0
                                   else( tbl_Zones.ZoneOccupiedCapacity/tbl_Zones.ZoneCapacity*100) end ";
            parameters.Add(new("Min", minCap));
        }

        if (!maxCap.Equals(-1))
        {
            if (!string.IsNullOrEmpty(whereString))
                whereString += " AND ";
            whereString += @" @Max > case tbl_Zones.ZoneCapacity
                                  when 0 then 0
                                  else (tbl_Zones.ZoneOccupiedCapacity/tbl_Zones.ZoneCapacity*100) end ";
            parameters.Add(new("Max", maxCap));
        }

        if (!zoneCode.Equals("-1"))
        {
            if (!string.IsNullOrEmpty(whereString))
                whereString += " AND ";

            if (zoneCodeLike)
            {
                whereString += $" tbl_Zones.ZoneCode LIKE N'%{zoneCode}%' ";
            }
            else
            {
                whereString += $" tbl_Zones.ZoneCode = N'{zoneCode}' ";
            }
        }

        if (!location.Equals("-1"))
        {
            if (!string.IsNullOrEmpty(whereString))
                whereString += " AND ";
            whereString += $" tbl_Zones.ZoneStoreCode = N'{location}' ";
        }

        if (warehouseType != DestinationOperationalType.NotSpecified)
        {
            if (!string.IsNullOrEmpty(whereString))
                whereString += " AND ";
            whereString += $" tbl_Zones.DestinationDesc = N'{(int)warehouseType}' ";
        }

        if (!string.IsNullOrEmpty(whereString))
        {
            cmd += " WHERE " + whereString;
        }

        return dataAccess.SqlDataAdapter(cmd, parameters.ToArray());
    }

    public DataTable SSearchZoneByCodes(string[] codes)
    {
        logger.LogInformation("SSearchZoneByCodes"
    , new KeyValuePair<string, object>("codes", codes)
    );
        var codesStr = string.Empty;

        for (int i = 0; i < codes.Length; i++)
        {
            codesStr += $"N'{codes[i]}'";
            if (i != codes.Length - 1)
            {
                codesStr += ",";
            }
        }

        var cmd = @$"SELECT distinct tbl_Zones.id, ZoneCode as [ZoneCode], ZoneTitle as [Title], ZoneCapacity as [Capacity],
ZoneDimention as [Dimention], ZoneParentCode as [ParentCode], CAST(ZoneParentLayer AS nvarchar(20))as [ParentLayer],
ZoneStoreCode as [StoreCode], ZoneCountPixle as [CountPixle], ZoneOccupiedCapacity as [OccupiedCapacity],
ZoneCapacity-ZoneOccupiedCapacity as [FreeCapacity]
FROM  tbl_Zones 
LEFT JOIN tbl_Tags on tbl_Tags.TagZone = tbl_Zones.ZoneCode
WHERE tbl_Tags.ProductCode IN ({codesStr})
                                       ";

        return dataAccess.SqlDataAdapter(cmd);
    }

    public DataTable SSearchZones(string productCode, int minCap, int maxCap, string zoneCode, string RegCode, string ProductSerial, string ZoneLayer)
    {
        logger.LogInformation("SSearchZones"
    , new KeyValuePair<string, object>("productCode", productCode)
    , new KeyValuePair<string, object>("minCap", minCap)
    , new KeyValuePair<string, object>("maxCap", maxCap)
    , new KeyValuePair<string, object>("zoneCode", zoneCode)
    , new KeyValuePair<string, object>("RegCode", RegCode)
    , new KeyValuePair<string, object>("ProductSerial", ProductSerial)
    , new KeyValuePair<string, object>("ZoneLayer", ZoneLayer)
    );

        var cmd = @" SELECT tbl_Zones.ZoneCode, tbl_Zones.ZoneTitle AS Title, tbl_Zones.ZoneCapacity AS Capacity, tbl_Zones.ZoneCapacity - COUNT(DISTINCT tbl_Tags.ProductSerial) AS FreeCapacity, COUNT(DISTINCT tbl_Tags.ProductCode) 
                         AS CountProductCode, tbl_Zones.ZoneParentLayer
FROM            tbl_Zones LEFT OUTER JOIN
                         tbl_Tags ON tbl_Tags.TagZone " + ((ZoneLayer == "1") ? " LIKE { fn CONCAT(tbl_Zones.ZoneCode, '%') }" : "= tbl_Zones.ZoneCode ")
                         ;
        var whereString = string.Empty;
        var havingString = " having (tbl_Zones.ZoneParentLayer = " + ZoneLayer + ") ";
        var parameters = new List<KeyValuePair<string, object>>();

        if (!productCode.Equals("-1"))
        {
            if (!string.IsNullOrEmpty(whereString))
                whereString += " AND ";
            whereString += " tbl_Tags.ProductCode = @PCode ";
            parameters.Add(new("PCode", productCode));
        }
        if (!RegCode.Equals("-1"))
        {
            if (!string.IsNullOrEmpty(whereString))
                whereString += " AND ";
            whereString += " tbl_Tags.RegCode = @RegCode ";
            parameters.Add(new("RegCode", RegCode));
        }

        if (!ProductSerial.Equals("-1"))
        {
            if (!string.IsNullOrEmpty(whereString))
                whereString += " AND ";
            whereString += " tbl_Tags.ProductSerial = @ProductSerial ";
            parameters.Add(new("ProductSerial", ProductSerial));
        }
        if (minCap == 0 && maxCap == 0)
        {
            if (!string.IsNullOrEmpty(havingString))
                havingString += " AND ";
            havingString += "   COUNT(DISTINCT tbl_Tags.ProductSerial) = 0 ";

        }
        else if (minCap == 0 && maxCap == 100)
        {

        }
        else
        {
            if (!minCap.Equals(-1))
            {
                if (!string.IsNullOrEmpty(havingString))
                    havingString += " AND ";
                havingString += @"" + minCap.ToString() + @" < case tbl_Zones.ZoneCapacity
                                   when 0 then 0
                                   else( COUNT(DISTINCT tbl_Tags.ProductSerial)/tbl_Zones.ZoneCapacity*100) end ";
            }
            if (!maxCap.Equals(-1) && maxCap.ToString() != "100")
            {
                if (!string.IsNullOrEmpty(havingString))
                    havingString += " AND ";
                havingString += @"" + maxCap.ToString() + @" >= case tbl_Zones.ZoneCapacity
                                  when 0 then 0
                                  else (COUNT(DISTINCT tbl_Tags.ProductSerial)/tbl_Zones.ZoneCapacity*100) end ";

            }
        }
        if (!zoneCode.Equals("-1"))
        {
            if (!string.IsNullOrEmpty(whereString))
                whereString += " AND ";
            whereString += $" tbl_Zones.ZoneCode = N'{zoneCode}' ";
        }


        if (whereString.Trim() == "AND")
        {
            whereString = "";
        }
        if (!string.IsNullOrEmpty(whereString))
            cmd += " WHERE " + whereString;

        cmd += " GROUP BY tbl_Zones.ZoneCode, tbl_Zones.ZoneTitle, tbl_Zones.ZoneCapacity, tbl_Zones.ZoneOccupiedCapacity, tbl_Zones.id,tbl_Zones.ZoneParentLayer,tbl_Zones.ZoneParentCode, tbl_Zones.ZoneRowIndex  ";
        if (!string.IsNullOrEmpty(havingString))
            cmd += havingString;

        cmd += " ORDER BY tbl_Zones.ZoneParentCode, tbl_Zones.ZoneRowIndex  ";

        return dataAccess.SqlDataAdapter(cmd);
    }

