    public int SPDefineZone(string ZoneCode, string ZoneTitle, string ZoneDimention, string ZoneParentCode,
        string ZoneParentLayer, string ZoneStoreCode, string ZoneCountPixle, string MinZoneCapacity,
        string MaxZoneCapacity, string ZoneRowIndex, string UserCode)
    {



        var checkInvHeader = " SELECT Count(*) FROM tbl_Zones WHERE ZoneCode = N'" + ZoneCode + "'";

        var check = (int)dataAccess
            .SqlDataAdapter(checkInvHeader).Select()[0].ItemArray[0] > 0;

        if (!check)
        {
            var command = @"INSERT         
                                INTO              tbl_Zones(ZoneCode, ZoneTitle, ZoneDimention, ZoneParentCode, ZoneParentLayer, ZoneStoreCode, ZoneCountPixle, MinZoneCapacity,MaxZoneCapacity,ZoneRowIndex,ZoneCapacity)
                                VALUES(@ZoneCode, @ZoneTitle, @ZoneDimention, @ZoneParentCode, @ZoneParentLayer, @ZoneStoreCode, @ZoneCountPixle, @MinZoneCapacity,@MaxZoneCapacity,@ZoneRowIndex,@MaxZoneCapacity) ";

            return dataAccess.CmdSqlExecuteNonQuery(command,
                new KeyValuePair<string, object>("ZoneCode", ZoneCode),
                new KeyValuePair<string, object>("ZoneTitle", ZoneTitle),
                new KeyValuePair<string, object>("ZoneDimention", ZoneDimention),
                new KeyValuePair<string, object>("ZoneParentCode", ZoneParentCode),
                new KeyValuePair<string, object>("ZoneParentLayer", ZoneParentLayer),
                new KeyValuePair<string, object>("ZoneStoreCode", ZoneStoreCode),
                new KeyValuePair<string, object>("ZoneCountPixle", ZoneCountPixle),
                new KeyValuePair<string, object>("MinZoneCapacity", MinZoneCapacity),
                new KeyValuePair<string, object>("MaxZoneCapacity", MaxZoneCapacity),
                new KeyValuePair<string, object>("ZoneRowIndex", ZoneRowIndex)
            );
        }
        else
        {
            var command = @"UPDATE       tbl_Zones
SET            ZoneCapacity=@ZoneCapacity, MinZoneCapacity =@MinZoneCapacity, MaxZoneCapacity =@MaxZoneCapacity, ZoneRowIndex = @ZoneRowIndex, ZoneStoreCode = @ZoneStoreCode
WHERE        (ZoneCode = @ZoneCode)";


            return dataAccess.CmdSqlExecuteNonQuery(command,
                new KeyValuePair<string, object>("ZoneCode", ZoneCode),
                new KeyValuePair<string, object>("MinZoneCapacity", MinZoneCapacity),
                new KeyValuePair<string, object>("ZoneCapacity", MaxZoneCapacity),
                new KeyValuePair<string, object>("MaxZoneCapacity", MaxZoneCapacity),
                new KeyValuePair<string, object>("ZoneRowIndex", ZoneRowIndex),
                new KeyValuePair<string, object>("ZoneStoreCode", ZoneStoreCode));
        }

    }

    public int SInsertZoneExcel(SaveZoneCommand saveZoneCommand)
    {


        List<Zone> newZones = mapper.Map<List<Zone>>(saveZoneCommand.Zones);

        List<string> oldZones = apiContext.Zones.Select(p => p.Code).ToList();

        List<Zone> insert = new();

        List<Zone> update = new();

        foreach (var zone in newZones)
        {
            if (oldZones.Any(p => p.Equals(zone.Code)))
            {
                update.Add(zone);
            }
            else
            {
                insert.Add(zone);
            }
        }

        List<KeyValuePair<string, KeyValuePair<string, object>[]>> commands = new();

        foreach (var zone in insert)
        {
            var command = @"INSERT         
                                INTO              tbl_Zones(ZoneCode, ZoneTitle, ZoneDimention, ZoneParentCode, ZoneParentLayer, ZoneStoreCode, ZoneCountPixle, MinZoneCapacity,MaxZoneCapacity,ZoneRowIndex,ZoneCapacity)
                                VALUES(@ZoneCode, @ZoneTitle, @ZoneDimention, @ZoneParentCode, @ZoneParentLayer, @ZoneStoreCode, @ZoneCountPixle, @MinZoneCapacity,@MaxZoneCapacity,@ZoneRowIndex,@MaxZoneCapacity) ";

            List<KeyValuePair<string, object>> parameters = new();

            parameters.Add(new KeyValuePair<string, object>("ZoneCode", zone.Code));
            parameters.Add(new KeyValuePair<string, object>("ZoneTitle", zone.Title));
            parameters.Add(new KeyValuePair<string, object>("ZoneDimention", zone.Dimention));
            parameters.Add(new KeyValuePair<string, object>("ZoneParentCode", zone.ParentCode));
            parameters.Add(new KeyValuePair<string, object>("ZoneParentLayer", zone.ParentLayer));
            parameters.Add(new KeyValuePair<string, object>("ZoneStoreCode", zone.WarehouseCode));
            parameters.Add(new KeyValuePair<string, object>("ZoneCountPixle", zone.CountPixle));
            parameters.Add(new KeyValuePair<string, object>("MinZoneCapacity", zone.MinCapacity));
            parameters.Add(new KeyValuePair<string, object>("MaxZoneCapacity", zone.MaxCapacity));
            parameters.Add(new KeyValuePair<string, object>("ZoneRowIndex", zone.RowIndex));

            commands.Add(new(command, parameters.ToArray()));
        }

        foreach (var zone in update)
        {
            var command = @"UPDATE       tbl_Zones
                            SET            ZoneCapacity=@ZoneCapacity, MinZoneCapacity =@MinZoneCapacity, MaxZoneCapacity =@MaxZoneCapacity, ZoneRowIndex = @ZoneRowIndex, ZoneStoreCode = @ZoneStoreCode, ZoneTitle = @ZoneTitle
                            WHERE        (ZoneCode = @ZoneCode)";

            List<KeyValuePair<string, object>> parameters = new();

            parameters.Add(new KeyValuePair<string, object>("ZoneCode", zone.Code));
            parameters.Add(new KeyValuePair<string, object>("MinZoneCapacity", zone.MinCapacity));
            parameters.Add(new KeyValuePair<string, object>("ZoneCapacity", zone.MaxCapacity));
            parameters.Add(new KeyValuePair<string, object>("MaxZoneCapacity", zone.MaxCapacity));
            parameters.Add(new KeyValuePair<string, object>("ZoneRowIndex", zone.RowIndex));
            parameters.Add(new KeyValuePair<string, object>("ZoneStoreCode", zone.WarehouseCode));
            parameters.Add(new KeyValuePair<string, object>("ZoneTitle", zone.Title));

            commands.Add(new(command, parameters.ToArray()));
        }

        return dataAccess.CmdSqlExecuteNonQueryWithTransaction(commands);
    }

    public int SInsertUpdateZone(ZoneDto zone)
    {
        logger.LogInformation("SInsertUpdateZone" + Environment.NewLine +
                             $"UserId: {httpContext.User.GetUserId()}" + Environment.NewLine +
                              "zone: " + JsonConvert.SerializeObject(zone));

        Zone data = mapper.Map<Zone>(zone);

        if (!apiContext.Zones.Any(p => p.Code == zone.ZoneCode))
        {
            apiContext.Zones.Add(data);
        }
        else
        {
            apiContext.Zones.Update(data);
        }

        return apiContext.SaveChanges();
    }

    public int SPDeleteZone(string ZoneCode, string UserCode)
    {

        logger.LogInformation("SPDeleteZone"
    , new KeyValuePair<string, object>("ZoneCode", ZoneCode)
    , new KeyValuePair<string, object>("UserCode", UserCode)
    );

        int deleteResult = SCheckDeleteZone(ZoneCode);

        if (deleteResult != 1)
            return deleteResult;

        var command = @"Delete  From  tbl_Zones where ZoneCode=@ZoneCode ";

        return dataAccess.CmdSqlExecuteNonQuery(command
            , new KeyValuePair<string, object>("ZoneCode", ZoneCode));

    }

    public int SCheckDeleteZone(string zoneCode)
    {
        logger.LogInformation("SCheckDeleteZone"
    , new KeyValuePair<string, object>("ZoneCode", zoneCode)
    );

        var checkInvHeader = " SELECT COALESCE(ZoneCapacity,0) FROM tbl_Zones WHERE ZoneCode = N'" + zoneCode + "'";
        var check = (decimal)dataAccess.SqlDataAdapter(checkInvHeader).Select()[0].ItemArray[0] > 0;
        if (check)
            return -2;

        var checkParents = " SELECT Count(*) FROM tbl_Zones WHERE ZoneParentCode = '" + zoneCode + "'";
        var checkParent = (int)dataAccess
            .SqlDataAdapter(checkParents).Select()[0].ItemArray[0] > 0;
        if (checkParent)
            return -3;

        return 1;
    }

