        var cmd = @$"SELECT        TagZone AS ZoneCode, ProductCode, COALESCE (RegCode, N'') AS TechnicalCode, ProductStatus AS Quality, COUNT(ProductSerial) AS Count, SUM(ProductCount) AS SumCount, MIN(TagRegisterShamsiUnixDate) AS FirstDate, 
