    public DataTable SSearchZoneProducts(string zoneCode, string desticationCode)
    {
        var cmd = @"WITH ZoneHierarchy AS (
        SELECT ZoneCode AS TargetZone, ZoneCode AS DescendantZone
        FROM tbl_Zones
        UNION ALL
        SELECT zh.TargetZone, z.ZoneCode
        FROM tbl_Zones z
        INNER JOIN ZoneHierarchy zh ON z.ZoneParentCode = zh.DescendantZone
    )
    SELECT t.TagInDestinationId AS [WarehouseCode], t.TagZone AS ZoneCode, t.ProductCode, COALESCE(t.RegCode, N'') AS RegCode, t.ProductStatus AS Qc, COUNT(DISTINCT t.ProductSerial) AS Count,
    SUM(t.ProductCount) AS SumCount,
    SUBSTRING(MIN(t.TagRegisterShamsiUnixDate),0,5)+'/'+SUBSTRING(MIN(t.TagRegisterShamsiUnixDate),5,2)+'/'+SUBSTRING(MIN(t.TagRegisterShamsiUnixDate),7,2) AS FirstDate,
    SUBSTRING(MAX(t.TagRegisterShamsiUnixDate),0,5)+'/'+SUBSTRING(MAX(t.TagRegisterShamsiUnixDate),5,2)+'/'+SUBSTRING(MAX(t.TagRegisterShamsiUnixDate),7,2) AS LastDate
    FROM tbl_Tags t
    INNER JOIN ZoneHierarchy zh ON t.TagZone = zh.DescendantZone AND zh.TargetZone = @ZoneCode
    GROUP BY t.TagInDestinationId, t.TagZone, t.ProductCode, t.RegCode, t.ProductStatus";
        return dataAccess.SqlDataAdapter(cmd,
            new KeyValuePair<string, object>("ZoneCode", zoneCode));
    }

    public DataTable SSearchZonesProducts(StoreProductRequest search)
    {
        var parameters = new List<KeyValuePair<string, object>>();

        var ageRangeFilter = "";
        //    search.AgeRange switch
        //{
        //    "1" => " AND t.TagRegisterDateTime < GETDATE() AND t.TagRegisterDateTime >= DATEADD(MONTH, -1, GETDATE()) ",
        //    "2" => " AND t.TagRegisterDateTime < DATEADD(MONTH, -1, GETDATE()) AND t.TagRegisterDateTime >= DATEADD(MONTH, -3, GETDATE()) ",
        //    "3" => " AND t.TagRegisterDateTime < DATEADD(MONTH, -3, GETDATE()) AND t.TagRegisterDateTime >= DATEADD(MONTH, -6, GETDATE()) ",
        //    "4" => " AND t.TagRegisterDateTime < DATEADD(MONTH, -6, GETDATE()) AND t.TagRegisterDateTime >= DATEADD(MONTH, -12, GETDATE()) ",
        //    "5" => " AND t.TagRegisterDateTime < DATEADD(MONTH, -12, GETDATE()) ",
        //    _ => ""
        //};

        var capacityCheckType = configuration["ProjectConfigs:WmsConfigs:Zone:CapacityCheckType"];

        var OccupiedCapacity = "";

        switch (capacityCheckType)
        {
            case "CountSerials":
                OccupiedCapacity = " COUNT(DISTINCT t.ProductSerial)  ";
                break;

            case "SumProductCount":
                OccupiedCapacity = " SUM(t.ProductCount)  ";
                break;

            case "SumProductWeight":
                OccupiedCapacity = " SUM(t.ProductWeight)  ";
                break;

            case "SumProductVolume":
                OccupiedCapacity = " SUM(t.ProductVolume) ";
                break;
        }


        string rootZoneFilter;
        string zoneCondition = search.TagZoneLike ? "ZoneCode LIKE '%' + @ZoneCode + '%'" : "ZoneCode = @ZoneCode";

        if (search.TagZone.NotEquals("-1") && search.ZoneLayer.NotEquals("-1"))
        {
            rootZoneFilter = $"{zoneCondition} AND ZoneParentLayer = @Layer";
            parameters.Add(new("ZoneCode", search.TagZone));
            parameters.Add(new("Layer", search.ZoneLayer));
        }
        else if (search.TagZone.NotEquals("-1"))
        {
            rootZoneFilter = zoneCondition;
            parameters.Add(new("ZoneCode", search.TagZone));
        }
        else
        {
            rootZoneFilter = "ZoneParentLayer = @Layer";
            var layer = search.ZoneLayer.NotEquals("-1") ? (object)search.ZoneLayer : DBNull.Value;
            parameters.Add(new("Layer", layer));
        }


        var tagFilters = new System.Text.StringBuilder();

        if (search.ProductCode.NotEquals("-1"))
        {
            tagFilters.Append(" AND t.ProductCode = @PCode ");
            parameters.Add(new("PCode", search.ProductCode));
        }

        if (search.ProductSerial.NotEquals("-1"))
        {
            tagFilters.Append(" AND t.ProductSerial = @ProductSerial ");
            parameters.Add(new("ProductSerial", search.ProductSerial));
        }

        if (search.WarehouseCode.NotEquals("-1"))
        {
            tagFilters.Append(" AND t.TagInDestinationId = @StoreCode ");
            parameters.Add(new("StoreCode", search.WarehouseCode));
        }

        var cmd = $@"
WITH RootZones AS (
    SELECT Id, ZoneCode, MaxZoneCapacity AS RootCapacity
    FROM tbl_Zones
    WHERE {rootZoneFilter}
),
ZoneTree AS (
    SELECT z.Id, z.ZoneCode, z.MaxZoneCapacity, r.ZoneCode AS RootZone, r.RootCapacity
    FROM tbl_Zones z
    INNER JOIN RootZones r ON z.Id = r.Id

    UNION ALL

    SELECT z.Id, z.ZoneCode, z.MaxZoneCapacity, p.RootZone, p.RootCapacity
    FROM tbl_Zones z
    INNER JOIN ZoneTree p ON z.ZoneParentCode = p.ZoneCode
)
SELECT
    z.RootZone AS ZoneCode,
    CAST(COALESCE(MAX(z.RootCapacity), 0) AS DECIMAL(18,2)) AS TotalCapacity,
    CAST(COALESCE(MAX(z.RootCapacity), 0) - CAST(COALESCE({OccupiedCapacity}, 0) AS DECIMAL(18,2)) AS DECIMAL(18,2)) AS FreeCapacity,
    CASE
        WHEN COALESCE(MAX(z.RootCapacity), 0) = 0 THEN CAST(0 AS DECIMAL(5,2))
        ELSE CAST((COALESCE(MAX(z.RootCapacity), 0) - CAST(COALESCE({OccupiedCapacity}, 0) AS DECIMAL(18,2))) * 100.0 / COALESCE(MAX(z.RootCapacity), 0) AS DECIMAL(5,2))
    END AS FreePercent,
    COUNT(DISTINCT t.ProductSerial) AS [CountSerials],
    CAST(COALESCE({OccupiedCapacity}, 0) AS DECIMAL(18,2)) AS [OccupiedCapacity],
    CASE
        WHEN COALESCE(MAX(z.RootCapacity), 0) = 0 THEN CAST(0 AS DECIMAL(5,2))
        ELSE CAST(CAST(COALESCE({OccupiedCapacity}, 0) AS DECIMAL(18,2)) * 100.0 / COALESCE(MAX(z.RootCapacity), 0) AS DECIMAL(5,2))
    END AS OccupiedPercent,
    COUNT(DISTINCT t.ProductCode) AS CountProductCode
FROM ZoneTree z
LEFT JOIN tbl_Tags t ON t.TagZone = z.ZoneCode
    {ageRangeFilter}
    {tagFilters}
GROUP BY z.RootZone
ORDER BY z.RootZone";

        return dataAccess.SqlDataAdapter(cmd, parameters.ToArray());
    }



    public List<SerialRowDto> SGetZoneProductSerials(GetZoneProductSerialsQuery zoneProductSerialsQuery)
    {
        var cmd = @"
 WITH ZoneTree AS (
     SELECT Id, ZoneCode
     FROM tbl_Zones
     WHERE ZoneCode = @ZoneCode

     UNION ALL

     SELECT z.Id, z.ZoneCode
     FROM tbl_Zones z
         INNER JOIN ZoneTree p ON z.ZoneParentCode = p.ZoneCode
 )
 SELECT
     t.TagZone,
     t.ProductSerial,
     t.ProductName,
     t.ProductCode,
     t.RegCode,
     t.ProductCount,
     t.ProductProperties
 FROM ZoneTree z
 INNER JOIN tbl_Tags t
     ON t.TagZone = z.ZoneCode
 WHERE
      (@PCode IS NULL OR t.ProductCode = @PCode)
     AND (@ProductSerial IS NULL OR t.ProductSerial = @ProductSerial)
     AND (@StoreCode IS NULL OR t.TagInDestinationId = @StoreCode)
     AND (@RegCode IS NULL 
      OR (@RegCodeLike = 1 AND t.RegCode LIKE '%' + @RegCode + '%')
      OR (@RegCodeLike = 0 AND t.RegCode = @RegCode)
         )
 ORDER BY
     t.TagZone,
     t.ProductSerial";

        var parameters = new[] {
        new KeyValuePair<string, object>("ZoneCode", zoneProductSerialsQuery.ZoneCode),
        new KeyValuePair<string, object>("PCode", zoneProductSerialsQuery.ProductCode.HasNoValue() ?  DBNull.Value : zoneProductSerialsQuery.ProductCode),
        new KeyValuePair<string, object>("ProductSerial", zoneProductSerialsQuery.ProductSerial.HasNoValue() ?  DBNull.Value : zoneProductSerialsQuery.ProductSerial),
        new KeyValuePair<string, object>("StoreCode", zoneProductSerialsQuery.StoreCode.HasNoValue() ?  DBNull.Value : zoneProductSerialsQuery.StoreCode),
        new KeyValuePair<string, object>("RegCode", zoneProductSerialsQuery.RegCode.HasNoValue() ? DBNull.Value : zoneProductSerialsQuery.RegCode),
        new KeyValuePair<string, object>("RegCodeLike", zoneProductSerialsQuery.RegCodeLike)
    };

        var dt = dataAccess.SqlDataAdapter(cmd, parameters);

        return dt.AsEnumerable().Select(row => new SerialRowDto
        {
            TagZone = row["TagZone"]?.ToString() ?? "",
            ProductSerial = row["ProductSerial"]?.ToString() ?? "",
            ProductName = row["ProductName"]?.ToString() ?? "",
            ProductCode = row["ProductCode"]?.ToString() ?? "",
            RegCode = row["RegCode"]?.ToString() ?? "",
            ProductCount = row["ProductCount"] != DBNull.Value ? Convert.ToDecimal(row["ProductCount"]) : 0,
            DynamicData = !string.IsNullOrEmpty(row["ProductProperties"]?.ToString())
                ? JsonConvert.DeserializeObject<Dictionary<string, string>>(row["ProductProperties"].ToString())
                : new Dictionary<string, string>()
        }).ToList();
    }

    public DataTable SGetCollectProductList(string documentKey, string documentType, string WarehouseCode = "1")
    {
        logger.LogInformation("SGetCollectProductList",
            new KeyValuePair<string, object>("documentKey", documentKey),
            new KeyValuePair<string, object>("documentType", documentType));


        string First_UnitName = " پالت ";
        string Second_UnitName = " کارتن ";
        string Third_UnitName = " متر مربع ";
        string ResultSerialList = "";
        DataTable _dtCollectResult = new DataTable();
        _dtCollectResult.Columns.Add("Row", typeof(String));
        _dtCollectResult.Columns.Add("ProductCode", typeof(String));
        _dtCollectResult.Columns.Add("ProductTechnicalCode", typeof(String));
        _dtCollectResult.Columns.Add("ProductName", typeof(String));
        _dtCollectResult.Columns.Add("Location", typeof(String));
        _dtCollectResult.Columns.Add("SumValue", typeof(String));
        _dtCollectResult.Columns.Add("CountProduct", typeof(String));
        _dtCollectResult.Columns.Add("CountProductDesc", typeof(String));
        _dtCollectResult.Columns.Add("SerialList", typeof(String));
        var _dtDocProductList = SGetCollectProuductsOrderFromStore(documentKey, documentType);

        foreach (DataRow _drProduct in _dtDocProductList.Rows)
        {
            ResultSerialList = "";

            string ProductCode = _drProduct["ProductCode"].ToString();
            string ProductTechnicalCode = _drProduct["ProductTechnicalCode"].ToString();
            string ProductName = _drProduct["ProductName"].ToString();
            bool FlagIncompletePalette = (_drProduct["CountProduct"].ToString().Contains(':')) ? true : false;
            decimal ProductPackValue = Convert.ToDecimal(_drProduct["ProductPackValue"].ToString());
            decimal ProductValue = Convert.ToDecimal(_drProduct["ProductValue"].ToString());
            string IncompletePaletteSerial = "";
            decimal SumValue = (_drProduct["SumValue"].ToString() != "") ? Convert.ToDecimal(_drProduct["SumValue"].ToString()) : 0;
            int CountcompletePaletteProduct = 0;
            decimal ValueIncompletePaletteProduct = 0;
            if (!FlagIncompletePalette)
                CountcompletePaletteProduct = Convert.ToInt32(_drProduct["CountProduct"].ToString());
            else
            {
                CountcompletePaletteProduct = Convert.ToInt32(_drProduct["CountProduct"].ToString().Split(':')[0].Trim());
                ValueIncompletePaletteProduct = (SumValue % ProductPackValue);
            }
            var cmdCompleteProductLocationAgeList = @"  SELECT        TOP (100) PERCENT COUNT(DISTINCT ProductSerial) AS count, Coalesce(TagZone ,N'-') AS Location, '0' AS Reserved ,'0' As Remained
                          FROM            tbl_Tags
                           WHERE   ( TagInDestinationId='" + WarehouseCode + @"') and     (ProductCode = '" + ProductCode + @"') AND (TagStatus = 1) and ProductCount='" + ProductPackValue + @"' 
                          GROUP BY TagZone, dbo.GetProductAnalyseAgeDateTime(TagRegisterDateTime)
                          ORDER BY dbo.GetProductAnalyseAgeDateTime(TagRegisterDateTime) DESC ";
            var _dtCompleteProductLocationAgeList = dataAccess.SqlDataAdapter(cmdCompleteProductLocationAgeList);


            var cmdReservationCollectByProduct = @" SELECT        SUM(fld_POPackCount) AS Count, fld_POFromZoneCode As Location
FROM            tbl_PlacementOrders
WHERE        (fld_POType = 3) AND (fld_POStatus = 1) AND (fld_POProductCode = '" + ProductCode + @"') AND
    (DATEDIFF(day, fld_PODateTime, GETDATE()) <= 2 AND DATEDIFF(day, fld_PODateTime, GETDATE()) >= 0)
GROUP BY fld_POFromZoneCode
order by fld_POFromZoneCode desc";
            var _dtReservationCollectByProduct = dataAccess.SqlDataAdapter(cmdReservationCollectByProduct);


            foreach (DataRow drCompleteProductLocationAgeList in _dtCompleteProductLocationAgeList.Rows)
            {
                foreach (DataRow drReservationCollectByProduct in _dtReservationCollectByProduct.Rows)
                {
                    if (drCompleteProductLocationAgeList["Location"].ToString() == drReservationCollectByProduct["Location"].ToString())
                    {
                        drCompleteProductLocationAgeList["Reserved"] = drReservationCollectByProduct["Count"].ToString();
                    }
                }

                drCompleteProductLocationAgeList["Remained"] = (drCompleteProductLocationAgeList["Reserved"].ToString() == "0") ? drCompleteProductLocationAgeList["count"].ToString() : ((Convert.ToInt32(drCompleteProductLocationAgeList["count"].ToString()) - Convert.ToInt32(drCompleteProductLocationAgeList["Reserved"].ToString()))).ToString();


            }

            var _dtInCompleteProductLocationAgeList = new DataTable();
            if (FlagIncompletePalette)
            {
                var cmdInCompleteProductLocationAgeList = @"  SELECT           ProductSerial  ,ProductCount as count, TagZone As Location
                                                                  FROM            tbl_Tags
                                                                  WHERE        (ProductCode = '" + ProductCode + @"') AND (TagStatus = 1) and ProductCount<>'" + ProductPackValue + @"'  and   TagZone <>'0'
																  order by  ProductCount   ";
                _dtInCompleteProductLocationAgeList = dataAccess.SqlDataAdapter(cmdInCompleteProductLocationAgeList);
            }

            decimal RemainCountcompletePaletteProduct = CountcompletePaletteProduct;
            int index = 0;

            foreach (DataRow _drCompleteProduct in _dtCompleteProductLocationAgeList.Rows)
            {
                if ((Convert.ToInt32(_drCompleteProduct["Remained"].ToString())) > 0)
                {
                    if ((Convert.ToInt32(_drCompleteProduct["Remained"].ToString())) >= RemainCountcompletePaletteProduct)
                    {
                        string[] RowInfo = { (_dtCollectResult.Rows.Count + 1).ToString(), ProductCode, ProductTechnicalCode, ProductName, _drCompleteProduct["Location"].ToString(), (RemainCountcompletePaletteProduct * ProductPackValue).ToString(), RemainCountcompletePaletteProduct.ToString(), RemainCountcompletePaletteProduct.ToString() + First_UnitName, "" };
                        _dtCollectResult.Rows.Add(RowInfo);
                        break;
                    }
                    else
                    {
                        string[] RowInfo = { (_dtCollectResult.Rows.Count + 1).ToString(), ProductCode, ProductTechnicalCode, ProductName, _drCompleteProduct["Location"].ToString(), ((Convert.ToDecimal(_drCompleteProduct["Remained"].ToString())) * ProductPackValue).ToString(), (Convert.ToDecimal(_drCompleteProduct["Remained"].ToString())).ToString(), (Convert.ToInt32(_drCompleteProduct["Remained"].ToString())) + First_UnitName, "" };
                        _dtCollectResult.Rows.Add(RowInfo);
                        RemainCountcompletePaletteProduct = RemainCountcompletePaletteProduct - (Convert.ToInt32(_drCompleteProduct["Remained"].ToString()));
                    }
                }
            }
            if (FlagIncompletePalette)
            {
                var RemainCountIncompletePaletteProduct = ValueIncompletePaletteProduct;
                foreach (DataRow _drInCompleteProduct in _dtInCompleteProductLocationAgeList.Rows)
                {
                    if (Convert.ToDecimal(_drInCompleteProduct["count"].ToString()) >= RemainCountIncompletePaletteProduct)
                    {
                        string[] RowInfo = { (_dtCollectResult.Rows.Count + 1).ToString(), ProductCode, ProductTechnicalCode, ProductName, _drInCompleteProduct["Location"].ToString(), RemainCountIncompletePaletteProduct.ToString(), Math.Round((ProductPackValue / RemainCountIncompletePaletteProduct), 2).ToString(), Math.Round((RemainCountIncompletePaletteProduct / ProductValue), MidpointRounding.ToEven).ToString() + Second_UnitName + (((RemainCountIncompletePaletteProduct % ProductValue) > 0) ? " و " + (RemainCountIncompletePaletteProduct % ProductValue).ToString() + Third_UnitName : ""), _drInCompleteProduct["ProductSerial"].ToString() };
                        _dtCollectResult.Rows.Add(RowInfo);
                        break;

                    }
                    else
                    {
                        string[] RowInfo = { (_dtCollectResult.Rows.Count + 1).ToString(), ProductCode, ProductTechnicalCode, ProductName, _drInCompleteProduct["Location"].ToString(), Convert.ToDecimal(_drInCompleteProduct["count"].ToString()).ToString(), Math.Round((ProductPackValue / Convert.ToDecimal(_drInCompleteProduct["count"].ToString())), 2).ToString(), Math.Round((Convert.ToDecimal(_drInCompleteProduct["count"].ToString()) / ProductValue), MidpointRounding.ToEven).ToString() + Second_UnitName + (((Convert.ToDecimal(_drInCompleteProduct["count"].ToString()) % ProductValue) > 0) ? " و " + (Convert.ToDecimal(_drInCompleteProduct["count"].ToString()) % ProductValue).ToString() + Third_UnitName : ""), _drInCompleteProduct["ProductSerial"].ToString() };
                        _dtCollectResult.Rows.Add(RowInfo);
                        RemainCountIncompletePaletteProduct = RemainCountIncompletePaletteProduct - Convert.ToDecimal(_drInCompleteProduct["count"].ToString());
                    }
                }
            }
        }

        return _dtCollectResult;
    }

    public string STransferProductCountToAnotherTag(string FromSerial, string ToEPC, string Count, string DestinationCode, string userToken)
    {
        var NewProductSerial = "";
        var childrenCommands = new List<KeyValuePair<string, KeyValuePair<string, object>[]>>();

        var command1 = @"UPDATE       tbl_Tags
SET                ProductCount =(ProductCount- " + Count + @")
WHERE        (ProductSerial = '" + FromSerial + "') ";

        childrenCommands.Add(new(command1, null));

        if (SCheckTagEPC(ToEPC))
        {
            var command2 = @"UPDATE       tbl_Tags
SET                ProductCount =(ProductCount+" + Count + @")
WHERE        (TagEpc = '" + ToEPC + "') ";

            childrenCommands.Add(new(command2, null));
            SSavePrintByNewSerialANDOldSerialInTransferData(ToEPC, FromSerial, Count, "", "Update");

        }
        else
        {

            NewProductSerial = (Convert.ToInt32(SGetNewProductSerial(configuration.GetSection("ProjectConfigs").GetSection("WmsConfigs")["GetMaxProductSerialBy"].ToString()))).ToString();
            if (NewProductSerial != "" && configuration.GetSection("ProjectConfigs").GetSection("WmsConfigs")["CreateNewSerial"].ToString() != "")
            {

                NewProductSerial = SCreateNewSerial(NewProductSerial, "", "-1", "", configuration.GetSection("ProjectConfigs").GetSection("WmsConfigs")["CreateNewSerial"].ToString(), "", "");
            }

            if (ToEPC.ToLower().Contains("esv"))
            {
                ToEPC = NewProductSerial;
            }

            SSavePrintByNewSerialANDOldSerialInTransferData(NewProductSerial, FromSerial, Count, "", "Insert");
            //     var command3 = @"INSERT INTO tbl_Print                          (ProductSerial ) VALUES        ('" + NewProductSerial + "')";


            //   childrenCommands.Add(new(command3, null));

            var command4 = @"INSERT INTO tbl_Tags
                         (ProductSerial, ProductCode, TagEpc, ProjectCode, ProductCount, ProductName, ProductType, ProductStatus, TagStatus, TagRegisterShamsiUnixDate, TagRegisterUser, TagTreeParentsId, NewProductSerial, ProductProperties, 
                         Lock, Username, DeviceId, DeviceIp, Freeze, Deactivate, TagInActionId, TagInDestinationId, TagInActionId2, TagInDestinationId2, fld_ProductPropertyAId, fld_ProductPropertyBId, fld_ProductPropertyCId, RegCode, 
                         ContractStatus, TagZone, TagRegisterDateTime, ReProduct, fld_InspectActionId, fld_LastInspectResult, fld_ProductGroup, fld_ProductBrand)
SELECT        '" + NewProductSerial + @"' AS Expr1, ProductCode, '" + ToEPC + @"' AS Expr2, ProjectCode, '" + Count + @"' AS Expr3, ProductName, ProductType, ProductStatus, TagStatus, TagRegisterShamsiUnixDate, TagRegisterUser, '" + FromSerial + @"' AS Expr4, NewProductSerial, ProductProperties, Lock, 
                         Username, DeviceId, DeviceIp, Freeze, Deactivate, TagInActionId, TagInDestinationId, TagInActionId2, TagInDestinationId2, fld_ProductPropertyAId, fld_ProductPropertyBId, fld_ProductPropertyCId, RegCode, ContractStatus, 
                         TagZone, TagRegisterDateTime, ReProduct, fld_InspectActionId, fld_LastInspectResult, fld_ProductGroup, fld_ProductBrand FROM            tbl_Tags AS tbl_Tags_1 WHERE        (ProductSerial = '" + FromSerial + @"')";

            childrenCommands.Add(new(command4, null));


            var command5 = @"UPDATE        tbl_TagsMovement SET                 ProductCount = ProductCount -   " + Count + @"
WHERE           (ProductSerial = '" + FromSerial + @"')  and HTagsMovementSt=0   ";


            childrenCommands.Add(new(command5, null));


            var command6 = @"INSERT INTO tbl_TagsMovement
                         (TagEpc, ProductCode, ProductSerial, ProductCount, HMovementActionId, HTagsMovementDate, HTagsMovementTime, HTagsMovementDateTime, HTagsMovementSt, RMovementActionId, RTagsMovementDate, 
                         RTagsMovementTime, RTagsMovementDateTime, RTagsMovementSt, MovementData, ApiSendStatus, ApiSendUser, ApiSendDateTime, ApiSendData, RMovementActionType, RMovementActionDocumentId)
SELECT         '" + ToEPC + @"', ProductCode, '" + NewProductSerial + @"', '" + Count + @"', HMovementActionId, HTagsMovementDate, HTagsMovementTime, HTagsMovementDateTime, HTagsMovementSt, RMovementActionId, RTagsMovementDate, 
                         RTagsMovementTime, RTagsMovementDateTime, RTagsMovementSt, MovementData, ApiSendStatus, ApiSendUser, ApiSendDateTime, ApiSendData, RMovementActionType, RMovementActionDocumentId
FROM            tbl_TagsMovement AS tbl_TagsMovement_1
WHERE        (ProductSerial = '" + FromSerial + @"') and   HTagsMovementSt=0 ";


            childrenCommands.Add(new(command6, null));


        }

        bool resultTag = dataAccess.CmdSqlExecuteNonQueryWithTransaction(childrenCommands) == 1;
        if (NewProductSerial != "" && resultTag)
        {


            //var sqlCommandForGetTagInDestinationIdFromSerial = @" SELECT        TOP (1) TagStatus, TagInDestinationId FROM            tbl_Tags WHERE        (ProductSerial = '" + FromSerial + "') ";

            //var TagInDestinationIdFromSerial = dataAccess.SqlDataReaders(
            //    sqlCommandForGetTagInDestinationIdFromSerial);

            //SSaveMovementAction2("-1", TagInDestinationIdFromSerial[1].Value.ToString(), DestinationCode, "0", userToken, "0", null, "0", "", "", "0", new List<string>() { NewProductSerial }, new List<int>() { -1 }, DateTime.Now);
        }

        string logCommand = $"""
                   INSERT INTO [dbo].[tbl_TransferProductCountLog]
                  ([fld_OldSerial]
                  ,[fld_NewSerial]
                  ,[fld_Count]
                  ,[fld_ProductCode]
                  ,[fld_Date]
                  ,[fld_UserId])
            VALUES
                  (N'{FromSerial}'
                  ,N'{NewProductSerial}'
                  ,{Count}
                  ,(SELECT ProductCode FROM tbl_Tags WHERE ProductSerial = N'{FromSerial}')
                  ,GETDATE()
                  ,N'{userToken}')
            """;

        dataAccess.CmdSqlExecuteNonQuery(logCommand);

        if (resultTag)
        {
            return NewProductSerial;
        }

        return "";
    }

    public DataTable SGetTransferProductCountLogs()
    {
        string command = """
                      SELECT TOP(100) [fld_Id] AS [Id]
                ,[fld_OldSerial] AS [OldSerial]
                ,[fld_NewSerial] AS [NewSerial]
                ,[fld_Count] AS [Count]
                ,[fld_ProductCode] AS [ProductCode]
                ,[fld_Date] AS [Date]
                ,[fld_UserId] AS [UserId]
            FROM [dbo].[tbl_TransferProductCountLog]
            ORDER BY [fld_Id] DESC
            """;

        return dataAccess.SqlDataAdapter(command);
    }

    public bool SSavePlacementMissions(string userId, string productCode, string productSerial, string productEPC,
    string type, string wCode, string fromZoneId, string toZoneId, string storeCode, string actionCode, string actionRemainCount)
    {

        logger.LogInformation("SSavePlacementMissions" + Environment.NewLine
                             + "userId" + userId + Environment.NewLine
                             + "productCode" + productCode + Environment.NewLine
                             + "productSerial" + productSerial + Environment.NewLine
                             + "productEPC" + productEPC + Environment.NewLine
                             + "type" + type + Environment.NewLine
                             + "wCode" + wCode + Environment.NewLine
                             + "fromZoneId" + fromZoneId + Environment.NewLine
                             + "toZoneId" + toZoneId + Environment.NewLine
                             + "storeCode" + storeCode + Environment.NewLine
                             + "actionCode" + actionCode + Environment.NewLine
                             + "actionRemainCount" + actionRemainCount);


        var cmdUpdate = @"  update tbl_ProductPlacementMissions set fld_PPMStatus=3 where fld_PPMType=1  and fld_PPMStatus=0 and fld_PPMProductSerial=@PPMProductSerial";
        dataAccess.CmdSqlExecuteNonQuery(cmdUpdate,
            new KeyValuePair<string, object>("PPMProductSerial", productSerial));

        var cmd = @" INSERT INTO tbl_ProductPlacementMissions
                                    (fld_PPMUserId, fld_PPMRegDateTime, fld_PPMProductCode, fld_PPMProductSerial, fld_PPMProductEPC, fld_PPMType, fld_PPMWMCode, fld_PPMWMDriverUserId, fld_PPMFromZoneId, fld_PPMToZoneId, fld_PPMStoreCode,
                                    fld_PPMStatus, fld_PPMToZoneId_Edited,fld_PPMActionId )
                                    VALUES
                                    (@PPMUserId, @PPMRegDateTime, @PPMProductCode, @PPMProductSerial,
                                    @PPMProductEPC, @PPMType, @PPMWMCode, @PPMWMDriverUserId, @PPMFromZoneId,
                                    @PPMToZoneId, @PPMStoreCode, @PPMStatus, @PPMToZoneId_Edited,@fld_PPMActionId ) ";

        var result = dataAccess.CmdSqlExecuteNonQuery(cmd,
            new KeyValuePair<string, object>("PPMUserId", userId),
            new KeyValuePair<string, object>("PPMRegDateTime", DateTime.Now),
            new KeyValuePair<string, object>("PPMProductCode", productCode),
