            new KeyValuePair<string, object>("PPMStatus", (type == "4") ? CargoStatus.Placed : CargoStatus.FreeCargo),
            new KeyValuePair<string, object>("PPMToZoneId_Edited", "0"),
            new KeyValuePair<string, object>("fld_PPMActionId", actionCode)) == 1;

        if (result)
        {
            if (actionCode != "-1")
            {
                try
                {
                    bool actionRemainCountConvertResult = int.TryParse(actionRemainCount, out int actionRemainCountInt);

                    if (!actionRemainCountConvertResult)
                    {
                        actionRemainCountInt = 0;
                    }

                    var commandUpdateAction = @"UPDATE       tbl_PlacementOrders
                    SET                fld_POPackCountRemain = fld_POPackCountRemain - 1 " + ((actionRemainCountInt <= 1) ? ", fld_POStatus = 2" : "") + " WHERE         (fld_POCode = " + actionCode + ") and (fld_POZoneCode=N'" + toZoneId + "') ";
                    dataAccess.CmdSqlExecuteNonQuery(commandUpdateAction);
                }
                catch (Exception ex)
                {
                    return false;
                }
                var missDt = SSelectPlacementMissions(GetLatestIdOfIdentityTable("tbl_ProductPlacementMissions"))
                    .Select()
                    .First();
                // Enum.TryParse(missDt.ItemArray[11].ToString(), out CargoStatus castedSt);
                //SCastOnline("0", JsonConvert.SerializeObject(new TruckCargo()
                //{
                //    Id = missDt.ItemArray[0].ToString(),
                //    SaverUserId = missDt.ItemArray[1].ToString(),
                //    SaverName = missDt.ItemArray[2].ToString(),
                //    ProductCode = missDt.ItemArray[3].ToString(),
                //    DriverUserId = missDt.ItemArray[4].ToString(),
                //    DriverUsername = missDt.ItemArray[5].ToString(),
                //    RegCode = missDt.ItemArray[6].ToString(),
                //    ProductSerial = missDt.ItemArray[7].ToString(),
                //    TruckNumber = missDt.ItemArray[8].ToString(),
                //    From = missDt.ItemArray[9].ToString(),
                //    Destination = missDt.ItemArray[10].ToString(),
                //    StatusEnum = castedSt,
                //    Status = missDt.ItemArray[11].ToString(),
                //    ProductName = string.IsNullOrEmpty(userId) ? "" : missDt.ItemArray[12].ToString()
                //}), userId);
            }
        }

        logger.LogInformation("SSavePlacementMissions => result:" + result);

        return result;
