    public bool SUpdateZoneOccupiedCapacity(string StoreCode, string ZoneCode, string ProductSerial)
    {
        logger.LogInformation("SUpdateZoneOccupiedCapacity"
      + Environment.NewLine + "StoreCode" + StoreCode
      + Environment.NewLine + "ZoneCode" + ZoneCode
      + Environment.NewLine + "ProductSerial" + ProductSerial);

        var cmd = "";

        if (ProductSerial == "")
        {
            cmd = @"UPDATE       tbl_Zones
SET                ZoneOccupiedCapacity =
                             (SELECT        COUNT(DISTINCT ProductSerial) AS Expr1
                               FROM            tbl_Tags
                               WHERE        (TagInDestinationId = tbl_Zones.ZoneStoreCode) AND (TagZone = tbl_Zones.ZoneCode)) +
                             (SELECT        COUNT(DISTINCT fld_PPMProductSerial) AS Expr1
                               FROM            tbl_ProductPlacementMissions
                               WHERE        (fld_PPMToZoneId = tbl_Zones.ZoneCode) AND (fld_PPMStoreCode = tbl_Zones.ZoneStoreCode) AND (fld_PPMStatus IN (0, 1)))
							   where tbl_Zones.ZoneStoreCode='" + StoreCode + @"' and  tbl_Zones.ZoneCode='" + ZoneCode + "'";
        }
        else
        {
            cmd = @"UPDATE       tbl_Zones
SET                ZoneOccupiedCapacity = tbl_Zones.ZoneOccupiedCapacity - 1
FROM            tbl_Tags LEFT OUTER JOIN
                         tbl_Zones ON tbl_Tags.TagInDestinationId = tbl_Zones.ZoneStoreCode AND tbl_Tags.TagZone = tbl_Zones.ZoneCode
WHERE        (tbl_Tags.ProductSerial = '" + ProductSerial + "') OR  (tbl_Tags.TagEpc = '" + ProductSerial + "')";
        }

        bool result = dataAccess.CmdSqlExecuteNonQuery(cmd) == 1;

        return result;
    }


