    public bool SSetMissionStatus(
        string pId,
        string pStatus,
        string pDateTime,
        string pDriver,
        string pTruck,
        string PSerial)
    {

        logger.LogInformation("SSetMissionStatus"
    , new KeyValuePair<string, object>("pStatus", pStatus)
    , new KeyValuePair<string, object>("pDateTime", pDateTime)
    , new KeyValuePair<string, object>("pDriver", pDriver)
    , new KeyValuePair<string, object>("pTruck", pTruck)
    , new KeyValuePair<string, object>("PSerial", PSerial)
    );

        string TagZone = "0";
        var cmd = "";
        var result = false;
        if (!pStatus.Equals("0"))
        {
            cmd = @" Update    tbl_ProductPlacementMissions Set  fld_PPMDateTime=@PPMDateTime ,
                                        fld_PPMStatus=@PPMStatus , fld_PPMWMDriverUserId = @Driver,
                                        fld_PPMWMCode = @Truck , fld_PPMProductSerial=@PSerial
                                        where  fld_PPMId=@PPMId   ";

            TagZone = SGetProductPlacementMissionsToZoneId(pId);
            result = dataAccess.CmdSqlExecuteNonQuery(cmd
                , new KeyValuePair<string, object>("PPMId", pId)
                , new KeyValuePair<string, object>("PPMDateTime", pDateTime)
                , new KeyValuePair<string, object>("PPMStatus", pStatus)
