                                        where  fld_PPMId=@PPMId   ";
            result = dataAccess.CmdSqlExecuteNonQuery(cmd,
                new KeyValuePair<string, object>("PPMId", pId)) == 1;
        }

        if (result)
        {
            SPSetTagZone(PSerial, TagZone, "");

