    public DataTable SSelectPlacementMissionsByProductSerial(string ProductSerial)
    {
        logger.LogInformation("SSelectPlacementMissionsByProductSerial"
    , new KeyValuePair<string, object>("ProductSerial", ProductSerial)
    );
        var sqlCommand =
                @" SELECT Top(1) fld_PPMId as Id, fld_PPMUserId as SaverUserId,
                       (select [Name] FROM tbl_User where tbl_User.Username = fld_PPMUserId OR tbl_User.Id = fld_PPMUserId) as [SaverName],
                       fld_PPMProductCode as ProductCode, fld_PPMWMDriverUserId as DriverUserId,
                       (select [Name] FROM tbl_User where tbl_User.Username = fld_PPMWMDriverUserId OR tbl_User.Id = fld_PPMWMDriverUserId) as [DriverUsername],
                       COALESCE(fld_PPMRegCode,(select tbl_Tags.Regcode from tbl_Tags WHERE tbl_Tags.ProductSerial= tbl_ProductPlacementMissions.fld_PPMProductSerial)) as [RegCode],
                       fld_PPMProductSerial as ProductSerial,
                       fld_PPMWMCode as [TruckNumber], fld_PPMFromZoneId as [From], fld_PPMToZoneId as [Destination], 
                       COALESCE(fld_PPMStatus,0) as [Status],
                       (select tbl_Tags.ProductName from tbl_Tags WHERE tbl_Tags.ProductSerial= tbl_ProductPlacementMissions.fld_PPMProductSerial) as [Name]
            FROM tbl_ProductPlacementMissions
            WHERE  fld_PPMStatus IN(0, 1)    And fld_PPMProductSerial =" + ProductSerial + " ORDER BY  fld_PPMId  ";
        //     SCastOnline("", "", "");
        return dataAccess.SqlDataAdapter(sqlCommand);
    }

    public DataTable SSelectPlacementMissions(string pPMId = "")
    {
        logger.LogInformation("SSelectPlacementMissions"
    , new KeyValuePair<string, object>("pPMId", pPMId)
    );
        var sqlCommand =
                @" SELECT        tbl_ProductPlacementMissions.fld_PPMId AS Id, COALESCE(tbl_ProductPlacementMissions.fld_PPMUserId,N'') AS SaverUserId,
                             COALESCE((SELECT   top(1)     Name
                               FROM            tbl_User
                               WHERE        (Username = tbl_ProductPlacementMissions.fld_PPMUserId) OR
                                                         (Id = tbl_ProductPlacementMissions.fld_PPMUserId)),N'') AS SaverName, tbl_ProductPlacementMissions.fld_PPMProductCode AS ProductCode, 
                         COALESCE(tbl_ProductPlacementMissions.fld_PPMWMDriverUserId,N'') AS DriverUserId,
                             COALESCE((SELECT  top(1)      Name
                               FROM            tbl_User AS tbl_User_1
                               WHERE        (Username = tbl_ProductPlacementMissions.fld_PPMWMDriverUserId) OR
                                                         (Id = tbl_ProductPlacementMissions.fld_PPMWMDriverUserId)),N'') AS DriverUsername, COALESCE (tbl_ProductPlacementMissions.fld_PPMRegCode,
                             (SELECT top(1)     tbl_Products.ProductTechnicalCode
                               FROM            tbl_Products
                               WHERE        (tbl_Products.ProductCode = tbl_ProductPlacementMissions.fld_PPMProductCode))) AS RegCode, tbl_ProductPlacementMissions.fld_PPMProductSerial AS ProductSerial, 
                         tbl_ProductPlacementMissions.fld_PPMWMCode AS TruckNumber, 
case 
when tbl_Zones.ZoneTitle IS NULL then N'-'
when tbl_Zones.ZoneTitle = N'0' then N'-'
else tbl_Zones.ZoneTitle end AS [From],
case 
when tbl_Zones.ZoneTitle IS NULL then N'-'
when tbl_Zones.ZoneTitle = N'0' then N'-'
else tbl_Zones.ZoneTitle end AS Destination,
COALESCE (tbl_ProductPlacementMissions.fld_PPMStatus, 0) AS Status,
                             COALESCE((SELECT    top(1)    ProductName
                               FROM            tbl_Tags AS tbl_Tags_1
                               WHERE        (ProductSerial = tbl_ProductPlacementMissions.fld_PPMProductSerial)),N'') AS Name
FROM            tbl_ProductPlacementMissions LEFT OUTER JOIN
                         tbl_Zones AS tbl_Zones_1 ON tbl_ProductPlacementMissions.fld_PPMToZoneId = tbl_Zones_1.ZoneCode LEFT OUTER JOIN
                         tbl_Zones ON tbl_ProductPlacementMissions.fld_PPMFromZoneId = tbl_Zones.ZoneCode
WHERE        (tbl_ProductPlacementMissions.fld_PPMStatus IN (0, 1)) " + ((pPMId != "") ? " And fld_PPMId=" + pPMId : "") + " ORDER BY  fld_PPMId  ";
        //     SCastOnline("", "", "");
        return dataAccess.SqlDataAdapter(sqlCommand);
    }
    #endregion

    public DataTable SFindTagsProduct(string productSerial, string productCode,
        string productTechCode, string statusCode, string fromDate, string toDate, string ProductSize, string ProductType, string InspectStatus, string DestinationCode,string DynamicField,string userToken)
    {
        if (fromDate != "-1")
            fromDate = fromDate.Replace("/", "").PadRight(14, '0');
        if (toDate != "-1")
            toDate = toDate.Replace("/", "").PadRight(14, '0');

        var whereString = "";

        var cmd = " SELECT ProductSerial,TagEpc FROM tbl_Tags ";
        var parameters = new List<KeyValuePair<string, object>>();

        if (!productSerial.Equals("-1") && !productSerial.Equals(""))
        {
            if (!whereString.Equals(""))
                whereString += "";
            whereString += " ProductSerial = '" + productSerial + "'";
        }
        if (!productCode.Equals("-1") && !productCode.Equals(""))
        {
            if (!whereString.Equals(""))
                whereString += " AND";
            whereString += " ProductCode = '" + productCode + "'";
        }
        if (!productTechCode.Equals("-1") && !productTechCode.Equals(""))
        {
            if (!whereString.Equals(""))
                whereString += " AND";
            whereString += " RegCode = '" + productTechCode + "'";
        }
        if (!statusCode.Equals("-1") && !statusCode.Equals(""))
        {
            if (!whereString.Equals(""))
                whereString += " AND";
            whereString += " ProductStatus = '" + statusCode + "'";
        }
        if (!fromDate.Equals("-1") && !fromDate.Equals(""))
        {
            if (!whereString.Equals(""))
                whereString += " AND";
            whereString += " TagRegisterShamsiUnixDate >= '" + fromDate + "'";
        }
        if (!toDate.Equals("-1") && !toDate.Equals(""))
        {
            if (!whereString.Equals(""))
                whereString += " AND";
            whereString += " TagRegisterShamsiUnixDate <= '" + toDate + "'";
        }


        if (!ProductSize.Equals("-1") && !ProductSize.Equals(""))
        {
            if (!whereString.Equals(""))
                whereString += " AND";
            whereString += " fld_ProductPropertyCId = '" + ProductSize + "'";
        }


        if (!ProductType.Equals("-1") && !ProductType.Equals(""))
        {
            if (!whereString.Equals(""))
                whereString += " AND";
            whereString += " ProductType = '" + ProductType + "'";
        }

        if (!InspectStatus.Equals("-1") && !InspectStatus.Equals(""))
        {
            if (!whereString.Equals(""))
                whereString += " AND";
            if (InspectStatus == "بازرسی نشده")
            {
                whereString += " fld_InspectActionId == 0 ";
            }
            else if (InspectStatus == "بازرسی تائید")
            {
                whereString += " fld_InspectActionId <> 0 and Lock=0";
            }
            else if (InspectStatus == "بازرسی مردود")
            {
                whereString += " fld_InspectActionId <> 0 and Lock=1";
            }
        }

        // <item>بازرسی نشده</item>
        //< item > بازرسی تائید </ item >
        //< item > بازرسی مردود </ item >


        if (!DestinationCode.Equals("-1") && !DestinationCode.Equals(""))
        {
            if (!whereString.Equals(""))
                whereString += " AND";
            whereString += " TagInDestinationId = '" + DestinationCode + "'";
        }


        if (!DynamicField.Equals("-1") && !DynamicField.Equals("")&& DynamicField.Contains("&"))
        {
            
            var DynamicField_Key = DynamicField.Split("&")[0];
            var DynamicField_value = DynamicField.Split("&")[1];
            if (!whereString.Equals(""))
                whereString += " AND";
            whereString +=  $"JSON_VALUE(tbl_Tags.ProductProperties,N'$.\"{DynamicField_Key}\"') like N'%{DynamicField_value}%'";
        }

        cmd += (whereString != string.Empty ? " Where " + whereString : "");

        return dataAccess.SqlDataAdapter(cmd);
    }

    public DataTable SRepExistTagTajamoeeProductCode
    (
    string ProductCode,
    string FromDate,
    string ToDate,
    string TechnicalCode,
    string ProductStatus,
    string ProductSerial,
    string TagZone
    )
    {
        string[] StartShiftTime = new string[3];
        DataTable shiftList = SPGetShiftStartENDList();
        foreach (DataRow dr in shiftList.Rows)
        {
            string Temp = dr["fld_ProductPropertyBDesc"].ToString().Split('-')[0].Split(':')[0] + dr["fld_ProductPropertyBDesc"].ToString().Split('-')[0].Split(':')[1] + "01";
            StartShiftTime[Convert.ToInt32(dr["fld_ProductPropertyBId"].ToString()) - 1] = Temp;
        }

        string whereKey = " Where Tags.TagStatus=1 AND";
        string whereKeySubQuery = " Where TagStatus=1 AND (ProductCode = Tags.ProductCode) AND";


        if (ProductCode != "")
        {
            whereKey += " (Tags.ProductCode=N'" + ProductCode + "')  AND";
            whereKeySubQuery += " (ProductCode=N'" + ProductCode + "')  AND";
        }
        if (ProductStatus != "")
        {
            whereKey += " (Tags.ProductStatus=N'" + ProductStatus + "')  AND";
            whereKeySubQuery += " (ProductStatus=N'" + ProductStatus + "')  AND";
        }
        if (ProductSerial != "")
        {
            whereKey += " (Tags.ProductSerial=N'" + ProductSerial + "')  AND ";
            whereKeySubQuery += " (ProductSerial=N'" + ProductSerial + "')  AND ";
        }

        if (FromDate != "")
        {
            whereKey += " (Tags.TagRegisterShamsiUnixDate >= '" + FromDate + StartShiftTime[0] + "')  AND";
            whereKeySubQuery += " (TagRegisterShamsiUnixDate >= '" + FromDate + StartShiftTime[0] + "')  AND";
        }
        if (ToDate != "")
        {

            whereKey += " (Tags.TagRegisterShamsiUnixDate <= '" + ToDate + StartShiftTime[0] + "')  AND";
            whereKeySubQuery += " (TagRegisterShamsiUnixDate <= '" + ToDate + StartShiftTime[0] + "')  AND";
        }
        if (TagZone != "")
        {
            whereKey += " (Tags.TagZone=N'" + TagZone + "')  AND";
            whereKeySubQuery += " (TagZone=N'" + TagZone + "')  AND";
        }

        if (TechnicalCode != "")
        {
            whereKey += " (Tags.RegCode Like N'" + TechnicalCode + "%')  AND";
            whereKeySubQuery += " (RegCode Like N'" + TechnicalCode + "%')  AND";

        }



        if (whereKey.Substring(whereKey.Length - 3, 3) == "AND")
        {
            whereKey = whereKey.Substring(0, whereKey.Length - 3);
        }



        if (whereKeySubQuery.Substring(whereKeySubQuery.Length - 3, 3) == "AND")
        {
            whereKeySubQuery = whereKeySubQuery.Substring(0, whereKeySubQuery.Length - 3);
        }


        var dtProducts = new DataTable();
        dtProducts.Columns.Add("ProductCode", typeof(string));
        dtProducts.Columns.Add("ProductName", typeof(string));
        dtProducts.Columns.Add("RegCode", typeof(string));
        dtProducts.Columns.Add("ProductStatusTitle", typeof(string));
        dtProducts.Columns.Add("ProductSize", typeof(string));
        dtProducts.Columns.Add("CountPack", typeof(string));
        dtProducts.Columns.Add("SumValue", typeof(string));
        dtProducts.Columns.Add("CountNotEnter", typeof(string));

        try
        {
            var sqlCommand = @"
                        SELECT        Tags.ProductCode, tbl_Products.ProductTitle as ProductName, Tags.RegCode, tbl_ProductStatus.ProductStatusTitle, tbl_Products.ProductSize, COUNT(Tags.ProductSerial) AS CountPack, SUM(Tags.ProductCount) AS SumValue,
                             coalesce(( SELECT 
STRING_AGG( TagZone, ' | ') WITHIN GROUP (ORDER BY  TagZone) AS 
NewField
from (
    select distinct  ProductCode,  tbl_Tags_1.TagZone
    FROM [dbo].[tbl_Tags]   AS tbl_Tags_1 " + whereKeySubQuery + @"
                               ) x GROUP BY  ProductCode),'0') AS ZoneList FROM            tbl_Tags AS Tags LEFT OUTER JOIN
                         tbl_ProductPropertyA ON Tags.fld_ProductPropertyAId = tbl_ProductPropertyA.fld_ProductPropertyAId LEFT OUTER JOIN
                         tbl_ProductPropertyB ON Tags.fld_ProductPropertyBId = tbl_ProductPropertyB.fld_ProductPropertyBId LEFT OUTER JOIN
                         tbl_Products ON Tags.ProductCode = tbl_Products.ProductCode LEFT OUTER JOIN
                         tbl_ProductStatus ON Tags.ProductStatus = tbl_ProductStatus.ProductStatusCode LEFT OUTER JOIN
                         tbl_ProductType ON Tags.ProductType = tbl_ProductType.ProductTypeCode " +

                    (whereKey != string.Empty ? whereKey : "") +
                    " GROUP BY Tags.ProductCode, tbl_Products.ProductTitle, Tags.RegCode, tbl_ProductStatus.ProductStatusTitle , tbl_Products.ProductSize";

            return dataAccess.SqlDataAdapter(sqlCommand);

        }
        catch (Exception exception)
        {
            //logger.LogWarning(exception, exception.Message);
            return dtProducts;
        }
    }

    public DataTable SRepRegisterTajamoeeProductCode
    (
    string ProductCode,
    string FromDate,
    string ToDate,
    string ProductLine,
    string ProductShift,
    string User,
    string TechnicalCode,
    string ProductStatus,
    string ProductSerial
    )
    {
        string[] StartShiftTime = new string[3];
        DataTable shiftList = SPGetShiftStartENDList();
        foreach (DataRow dr in shiftList.Rows)
        {
            string Temp = dr["fld_ProductPropertyBDesc"].ToString().Split('-')[0].Split(':')[0] + dr["fld_ProductPropertyBDesc"].ToString().Split('-')[0].Split(':')[1] + "01";
            StartShiftTime[Convert.ToInt32(dr["fld_ProductPropertyBId"].ToString()) - 1] = Temp;
        }

        string whereKey = "";
        string whereKeySubQuery = "";

        if (ProductCode != "")
        {
            whereKey += " (Tags.ProductCode=N'" + ProductCode + "')  AND";
            whereKeySubQuery += " (Tags_1.ProductCode=N'" + ProductCode + "')  AND";
        }
        if (ProductStatus != "")
        {
            whereKey += " (Tags.ProductStatus=N'" + ProductStatus + "')  AND";
            whereKeySubQuery += " (Tags_1.ProductStatus=N'" + ProductStatus + "')  AND";
        }
        if (ProductSerial != "")
        {
            whereKey += " (Tags.ProductSerial=N'" + ProductSerial + "')  AND ";
            whereKeySubQuery += " (Tags_1.ProductSerial=N'" + ProductSerial + "')  AND ";
        }

        if (FromDate != "")
        {


            whereKey += " (Tags.TagRegisterShamsiUnixDate >= '" + FromDate + StartShiftTime[0] + "')  AND";
            whereKeySubQuery += " (Tags_1.TagRegisterShamsiUnixDate >= '" + FromDate + StartShiftTime[0] + "')  AND";
        }
        if (ToDate != "")
        {

            whereKey += " (Tags.TagRegisterShamsiUnixDate <= '" + ToDate + StartShiftTime[0] + "')  AND";
            whereKeySubQuery += " (Tags_1.TagRegisterShamsiUnixDate <= '" + ToDate + StartShiftTime[0] + "')  AND";
        }
        if (ProductLine != "")
        {
            whereKey += " (Tags.fld_ProductPropertyAId=N'" + ProductLine + "')  AND";
            whereKeySubQuery += " (Tags_1.fld_ProductPropertyAId=N'" + ProductLine + "')  AND";
        }

        if (TechnicalCode != "")
        {
            whereKey += " (Tags.RegCode=N'" + TechnicalCode + "')  AND";
            whereKeySubQuery += " (Tags_1.RegCode=N'" + TechnicalCode + "')  AND";

        }
        if (ProductShift != "")
        {
            switch (ProductShift)
            {
                case "1":
                    whereKey += " (SUBSTRING(Tags.TagRegisterShamsiUnixDate, 9, 6) >= '" + StartShiftTime[0] + "')  AND  (SUBSTRING(Tags.TagRegisterShamsiUnixDate, 9, 6) < '" + StartShiftTime[1] + "')  AND";
                    whereKeySubQuery += " (SUBSTRING(Tags_1.TagRegisterShamsiUnixDate, 9, 6) >= '" + StartShiftTime[0] + "')  AND  (SUBSTRING(Tags_1.TagRegisterShamsiUnixDate, 9, 6) < '" + StartShiftTime[1] + "')  AND";

                    break;
                case "2":
                    whereKey += " (SUBSTRING(Tags.TagRegisterShamsiUnixDate, 9, 6) >= '" + StartShiftTime[1] + "')  AND  (SUBSTRING(Tags.TagRegisterShamsiUnixDate, 9, 6) < '" + StartShiftTime[2] + "')  AND";
                    whereKeySubQuery += " (SUBSTRING(Tags_1.TagRegisterShamsiUnixDate, 9, 6) >= '" + StartShiftTime[1] + "')  AND  (SUBSTRING(Tags_1.TagRegisterShamsiUnixDate, 9, 6) < '" + StartShiftTime[2] + "')  AND";

                    break;
                case "3":
                    whereKey += " (( (SUBSTRING(Tags.TagRegisterShamsiUnixDate, 9, 6) >= '" + StartShiftTime[2] + "')  AND (SUBSTRING(Tags.TagRegisterShamsiUnixDate, 9, 6) < '240000') ) OR ( (SUBSTRING(Tags.TagRegisterShamsiUnixDate, 9, 6) >= '000001' ) and (SUBSTRING(Tags.TagRegisterShamsiUnixDate, 9, 6) < '" + StartShiftTime[0] + "' )))  AND";
                    whereKeySubQuery += "  (( (SUBSTRING(Tags_1.TagRegisterShamsiUnixDate, 9, 6) >= '" + StartShiftTime[2] + "')  AND (SUBSTRING(Tags_1.TagRegisterShamsiUnixDate, 9, 6) < '240000') ) OR ( (SUBSTRING(Tags_1.TagRegisterShamsiUnixDate, 9, 6) >= '000001' ) and (SUBSTRING(Tags_1.TagRegisterShamsiUnixDate, 9, 6) < '" + StartShiftTime[0] + "' )))  AND";

                    break;

            }
        }
        if (User != "")
        {
            whereKey += " (Tags.Username=N'" + User + "')  AND";
            whereKeySubQuery += " (Tags_1.Username=N'" + User + "')  AND";
        }


        if (whereKey.Substring(whereKey.Length - 3, 3) == "AND")
        {
            whereKey = whereKey.Substring(0, whereKey.Length - 3);
        }



        if (whereKeySubQuery.Substring(whereKeySubQuery.Length - 3, 3) == "AND")
        {
            whereKeySubQuery = whereKeySubQuery.Substring(0, whereKeySubQuery.Length - 3);
        }


        var dtProducts = new DataTable();
        dtProducts.Columns.Add("ProductCode", typeof(string));
        dtProducts.Columns.Add("ProductName", typeof(string));
        dtProducts.Columns.Add("RegCode", typeof(string));
        dtProducts.Columns.Add("ProductStatusTitle", typeof(string));
        dtProducts.Columns.Add("ProductSize", typeof(string));
        dtProducts.Columns.Add("CountPack", typeof(string));
        dtProducts.Columns.Add("SumValue", typeof(string));
        dtProducts.Columns.Add("CountNotEnter", typeof(string));

        try
        {
            var sqlCommand = @"
                        SELECT        Tags.ProductCode, Tags.ProductName, Tags.RegCode, tbl_ProductStatus.ProductStatusTitle, tbl_Products.ProductSize, COUNT(Tags.ProductSerial) AS CountPack, SUM(Tags.ProductCount) AS SumValue,
                             (SELECT        COUNT(DISTINCT ProductSerial) AS Expr1
                               FROM            tbl_Tags AS Tags_1
                               WHERE        (TagStatus = 0  OR TagStatus IS NULL ) AND (ProductCode = Tags.ProductCode)" + (whereKey != string.Empty ? " And " + whereKeySubQuery : "") +
                           @") AS CountNotEnter FROM            tbl_Tags AS Tags LEFT OUTER JOIN
                         tbl_ProductPropertyA ON Tags.fld_ProductPropertyAId = tbl_ProductPropertyA.fld_ProductPropertyAId LEFT OUTER JOIN
                         tbl_ProductPropertyB ON Tags.fld_ProductPropertyBId = tbl_ProductPropertyB.fld_ProductPropertyBId LEFT OUTER JOIN
                         tbl_Products ON Tags.ProductCode = tbl_Products.ProductCode LEFT OUTER JOIN
                         tbl_ProductStatus ON Tags.ProductStatus = tbl_ProductStatus.ProductStatusCode LEFT OUTER JOIN
                         tbl_ProductType ON Tags.ProductType = tbl_ProductType.ProductTypeCode" +

                    (whereKey != string.Empty ? " Where " + whereKey : "") +
                    " GROUP BY Tags.ProductCode, Tags.ProductName, Tags.RegCode, tbl_ProductStatus.ProductStatusTitle , tbl_Products.ProductSize";

            return dataAccess.SqlDataAdapter(sqlCommand);

        }
        catch (Exception exception)
        {
            return dtProducts;
        }
    }

    public DataTable SRepPlacementMissions
    (
    string ProductCode,
    string TechnicalCode,
    string ProductSerial,
    string FromDate,
    string ToDate,
    string FromZoneId,
    string ToZoneId,
    string DriverUserId,
    string PlacementMissionType,
    string PPMActionId,
    string TagStatus,
    string PlacementMissionStatus
    )
    {

        string whereKey = "";
        if (ProductCode != "")
        {
            whereKey += " (tbl_ProductPlacementMissions.fld_PPMProductCode=N'" + ProductCode + "')  AND";
        }
        if (TagStatus != "" && TagStatus != "-1")
        {
            whereKey += " (tbl_Tags.TagStatus=N'" + TagStatus + "')  AND";
        }
        if (TechnicalCode != "")
        {
            whereKey += " (tbl_Products.ProductTechnicalCode=N'" + TechnicalCode + "')  AND";
        }

        if (FromDate != "")
        {
            whereKey += " (tbl_ProductPlacementMissions.fld_PPMRegDateTime >= dbo.JalaliDateToGeorgianDate('" + FromDate + "','00:00'))  AND";
        }
        if (ToDate != "")
        {
            whereKey += " (tbl_ProductPlacementMissions.fld_PPMRegDateTime <  dbo.JalaliDateToGeorgianDate('" + ToDate + "','00:00'))  AND";
        }
        if (ProductSerial != "")
        {
            whereKey += " (tbl_ProductPlacementMissions.fld_PPMProductSerial=N'" + ProductSerial + "')  AND";
        }

