        {
            whereKey += " (tbl_ProductPlacementMissions.fld_PPMFromZoneId=N'" + FromZoneId + "')  AND";
        }
        if (ToZoneId != "")
        {
            whereKey += " (tbl_ProductPlacementMissions.fld_PPMToZoneId=N'" + ToZoneId + "')  AND";
        }
        if (DriverUserId != "")
        {
            whereKey += " (tbl_ProductPlacementMissions.fld_PPMWMDriverUserId=N'" + DriverUserId + "')  AND";
        }
        if (PlacementMissionType != "" && PlacementMissionType != "-1")
        {
            whereKey += " (tbl_ProductPlacementMissions.fld_PPMType=N'" + PlacementMissionType + "')  AND";
        }
        if (PlacementMissionStatus != "" && PlacementMissionStatus != "-1")
        {
            whereKey += " (tbl_ProductPlacementMissions.fld_PPMStatus=N'" + PlacementMissionStatus + "')  AND";
        }

        if (!string.IsNullOrEmpty(whereKey))
        {
            if (whereKey.Substring(whereKey.Length - 3, 3) == "AND")
            {
                whereKey = whereKey.Substring(0, whereKey.Length - 3);
            }
        }

        var dtProducts = new DataTable();
        dtProducts.Columns.Add("fld_PPMId", typeof(string));
        dtProducts.Columns.Add("fld_PPMProductSerial", typeof(string));
        dtProducts.Columns.Add("fld_PPMProductCode", typeof(string));
