        dtProducts.Columns.Add("ProductTitle", typeof(string));
        dtProducts.Columns.Add("PPMType", typeof(string));
        dtProducts.Columns.Add("FromZoneTitle", typeof(string));
        dtProducts.Columns.Add("ToZoneTitle", typeof(string));
        dtProducts.Columns.Add("RegUsername", typeof(string));
        dtProducts.Columns.Add("fld_PPMRegDateTime", typeof(string));
        dtProducts.Columns.Add("DriverUserName", typeof(string));
        dtProducts.Columns.Add("fld_PPMWMCode", typeof(string));
        dtProducts.Columns.Add("fld_PPMDateTime", typeof(string));
        dtProducts.Columns.Add("PPMStatus", typeof(string));
        dtProducts.Columns.Add("PPMActionId", typeof(string));
        dtProducts.Columns.Add("TagStatus", typeof(string));

        try
        {
            var sqlCommand = @"SELECT        tbl_ProductPlacementMissions.fld_PPMId, tbl_ProductPlacementMissions.fld_PPMProductSerial, tbl_ProductPlacementMissions.fld_PPMProductCode,COALESCE( tbl_Products.ProductTechnicalCode,N''),COALESCE( tbl_Products.ProductTitle,N''), 
                         CASE WHEN tbl_ProductPlacementMissions.fld_PPMType = 1 THEN N'جانمایی کالا' WHEN tbl_ProductPlacementMissions.fld_PPMType = 2 THEN N'جابجایی کالا' ELSE N'جمع آوری کالا' END AS PPMType, 
                         tbl_Zones.ZoneTitle AS FromZoneTitle, COALESCE(tbl_Zones_1.ZoneTitle,N'' )AS ToZoneTitle, COALESCE (tbl_User.Username, N'0') AS RegUsername, dbo.GeorgianDateToJalaliDate(tbl_ProductPlacementMissions.fld_PPMRegDateTime) 
                         + ' ' + SUBSTRING(CAST(tbl_ProductPlacementMissions.fld_PPMRegDateTime AS nvarchar(50)), 12, 8) AS fld_PPMRegDateTime, COALESCE (tbl_User_1.Username, N'0') AS DriverUserName, 
                         tbl_ProductPlacementMissions.fld_PPMWMCode, COALESCE (dbo.GeorgianDateToJalaliDate(tbl_ProductPlacementMissions.fld_PPMDateTime) 
                         + ' ' + SUBSTRING(CAST(tbl_ProductPlacementMissions.fld_PPMDateTime AS nvarchar(50)), 12, 8), N'0') AS fld_PPMDateTime, 
                         CASE WHEN tbl_ProductPlacementMissions.fld_PPMStatus = 0 THEN N'ثبت شده' WHEN tbl_ProductPlacementMissions.fld_PPMStatus = 1 THEN N'در حال اجرا' WHEN tbl_ProductPlacementMissions.fld_PPMStatus = 2 THEN N'اتمام'
                          ELSE N'لغو شده' END AS PPMStatus, COALESCE (tbl_ProductPlacementMissions.fld_PPMActionId,0) as PPMActionId,  CASE WHEN tbl_Tags.TagStatus = 0 THEN N'انبارهای تولید' WHEN tbl_Tags.TagStatus = 1  THEN N'انبارهای محصول'  WHEN tbl_Tags.TagStatus = 2  THEN N'انبارهای بارگیری' ELSE N'نامشخص' END  as TagStatus
FROM            tbl_User AS tbl_User_1 RIGHT OUTER JOIN
                         tbl_Products RIGHT OUTER JOIN
                         tbl_Tags RIGHT OUTER JOIN
                         tbl_ProductPlacementMissions ON tbl_Tags.ProductSerial = tbl_ProductPlacementMissions.fld_PPMProductSerial ON tbl_Products.ProductCode = tbl_ProductPlacementMissions.fld_PPMProductCode LEFT OUTER JOIN
                         tbl_User ON tbl_ProductPlacementMissions.fld_PPMUserId = tbl_User.Id ON tbl_User_1.Id = tbl_ProductPlacementMissions.fld_PPMWMDriverUserId LEFT OUTER JOIN
                         tbl_Zones AS tbl_Zones_1 ON tbl_ProductPlacementMissions.fld_PPMToZoneId = tbl_Zones_1.ZoneCode LEFT OUTER JOIN
                         tbl_Zones ON tbl_ProductPlacementMissions.fld_PPMFromZoneId = tbl_Zones.ZoneCode
                        "
                    + (whereKey != string.Empty ? " Where " + whereKey : "") +
                    " ORDER BY tbl_ProductPlacementMissions.fld_PPMId  ";


            return dataAccess.SqlDataAdapter(sqlCommand, 120);
        }
        catch (Exception exception)
        {
            return dtProducts;
        }
    }

    public DataTable SRepInventoryProductList(EnterRequest search)
    {
        var whereString = "";

        if (!search.ProductName.Equals("-1"))
        {
            whereString += string.IsNullOrEmpty(whereString) ? "" : " AND ";
            whereString += $" Tags.ProductName LIKE N'%{search.ProductName}%' ";
        }

        if (!search.ProductCode.Equals("-1"))
        {
            whereString += string.IsNullOrEmpty(whereString) ? "" : " AND ";
            whereString += $" Tags.ProductCode = N'{search.ProductCode}' ";
        }

        if (!search.FromDate.Equals("-1"))
        {
            string[] TagRegisterShamsiUnixDateTemp = search.FromDate.Split('/');
            var TagRegisterShamsiUnixDate = TagRegisterShamsiUnixDateTemp[0] + TagRegisterShamsiUnixDateTemp[1] + TagRegisterShamsiUnixDateTemp[2] + "010101";
            whereString += string.IsNullOrEmpty(whereString) ? "" : " AND ";
            whereString += $" Tags.TagRegisterShamsiUnixDate  < N'{TagRegisterShamsiUnixDate}' ";
        }
        if (!search.ToDate.Equals("-1"))
        {
            string[] TagRegisterShamsiUnixDateTemp = search.FromDate.Split('/');
            var TagRegisterShamsiUnixDate = TagRegisterShamsiUnixDateTemp[0] + TagRegisterShamsiUnixDateTemp[1] + TagRegisterShamsiUnixDateTemp[2] + "010101";
            whereString += string.IsNullOrEmpty(whereString) ? "" : " AND ";
            whereString += $" Tags.TagRegisterShamsiUnixDate  > N'{TagRegisterShamsiUnixDate}' ";
        }

        if (!search.TechnicalCode.Equals("-1"))
        {
            whereString += string.IsNullOrEmpty(whereString) ? "" : " AND ";
            whereString += $" Tags.RegCode = N'{search.TechnicalCode}' ";
        }

        if (!search.FromTime.Equals("-1"))
        {
            whereString += string.IsNullOrEmpty(whereString) ? "" : " AND ";
            whereString += $" Tags.ProductSerial  = N'{search.FromTime}' ";
        }

        if (!search.ToTime.Equals("-1"))
        {
            whereString += string.IsNullOrEmpty(whereString) ? "" : " AND ";
            whereString += $" tbl_InventoryTags.fld_InventoryProductDesc  Like N'%{search.ToTime}%' ";

        }
        if (!search.Shift.Equals("-1"))
        {
            whereString += string.IsNullOrEmpty(whereString) ? "" : " AND ";
            whereString += $" Tags.ProductStatus  = N'{search.Shift}' ";
        }

        if (!search.ProductSerial.Equals("-1"))
        {
            whereString += string.IsNullOrEmpty(whereString) ? "" : " AND ";
            whereString += $" tbl_InventoryTags.fld_InventoryPlace  = N'{search.ProductSerial}' ";
        }

        var dtProducts = new DataTable();
        dtProducts.Columns.Add("ProductSerial", typeof(string));
        dtProducts.Columns.Add("ProductCode", typeof(string));
        dtProducts.Columns.Add("ProductName", typeof(string));
        dtProducts.Columns.Add("RegCode", typeof(string));
        dtProducts.Columns.Add("ProductStatusTitle", typeof(string));
        dtProducts.Columns.Add("ProductCount", typeof(string));
        dtProducts.Columns.Add("TagZone", typeof(string));
        dtProducts.Columns.Add("ProductSize", typeof(string));
        dtProducts.Columns.Add("InventoryData", typeof(string));
        dtProducts.Columns.Add("TagRegisterShamsiUnixDate", typeof(string));
        dtProducts.Columns.Add("Epc", typeof(string));

        var cmd = $@"SELECT DISTINCT COALESCE (Tags.ProductSerial, N'') AS ProductSerial, COALESCE (Tags.ProductCode, N'') AS ProductCode, COALESCE (Tags.ProductName, N'') AS ProductName, COALESCE (Tags.RegCode, N'') AS RegCode,
                             (SELECT        COALESCE (ProductStatusTitle, N'') AS Expr1
                               FROM            tbl_ProductStatus
                               WHERE        (ProductStatusCode = Tags.ProductStatus)) AS ProductStatusTitle, COALESCE (Tags.ProductCount, N'0') AS ProductCount, COALESCE (Tags.TagZone, N'0') AS TagZone, COALESCE (Tags.fld_ProductPropertyCId, 
                         N'') AS ProductSize, CASE WHEN (tbl_InventoryTags.fld_InventoryTagEPC IS NULL) THEN N'مغایرت کسری' WHEN (tbl_InventoryTags.fld_InventoryTagEPC IS NOT NULL) THEN N'بدون مشکل' ELSE N'' END AS InventoryData, 
                         Tags.TagRegisterShamsiUnixDate,
						 Tags.TagEpc as [Epc]
FROM            tbl_Tags AS Tags LEFT OUTER JOIN
                         tbl_InventoryTags ON Tags.TagEpc = tbl_InventoryTags.fld_InventoryTagEPC
{(whereString.HasValue() ? $" WHERE {whereString}" : "")}
UNION 
SELECT DISTINCT COALESCE (Tags.ProductSerial, N'') AS ProductSerial, COALESCE (Tags.ProductCode, N'') AS ProductCode, COALESCE (Tags.ProductName, N'') AS ProductName, COALESCE (Tags.RegCode, N'') AS RegCode,
                             (SELECT        COALESCE (ProductStatusTitle, N'') AS Expr1
                               FROM            tbl_ProductStatus
                               WHERE        (ProductStatusCode = Tags.ProductStatus)) AS ProductStatusTitle, COALESCE (Tags.ProductCount, N'0') AS ProductCount, COALESCE (Tags.TagZone, N'0') AS TagZone, COALESCE (Tags.fld_ProductPropertyCId, 
                         N'') AS ProductSize, N'مغایرت اضافی' AS InventoryData, Tags.TagRegisterShamsiUnixDate, Tags.TagEpc
FROM            tbl_InventoryTags LEFT OUTER JOIN
                         tbl_Tags AS Tags ON tbl_InventoryTags.fld_InventoryTagEPC = Tags.TagEpc 
{(whereString.HasValue() ? $" WHERE {whereString}" : "")}";

        dtProducts = dataAccess.SqlDataAdapter(cmd);
        return dtProducts;
    }



