    public DataTable SLatestUHFLogActionByActionTypeANDDeviceId(string ActionType, string DeviceId, string userToken)
    {

        var cmd = $@" SELECT         Distinct fld_InventoryId as UHFLogActionId,(SELECT        SUBSTRING(CAST(MAX(tbl_UHF_ReaderLog_2.fld_TagRead_DateTime) AS nvarchar(50)), 9, 2) + ':' + SUBSTRING(CAST(MAX(tbl_UHF_ReaderLog_2.fld_TagRead_DateTime) AS nvarchar(50)), 11, 2) AS Expr1
FROM            tbl_UHF_ReaderLog as tbl_UHF_ReaderLog_2
WHERE        (tbl_UHF_ReaderLog_2.fld_InventoryId = tbl_UHF_ReaderLog.fld_InventoryId)) as UHFLogCtionTime,(SELECT        COUNT(DISTINCT tbl_UHF_ReaderLog_3.fld_TagSerial) AS Expr1
FROM            tbl_UHF_ReaderLog AS tbl_UHF_ReaderLog_3
WHERE        (tbl_UHF_ReaderLog_3.fld_InventoryId = tbl_UHF_ReaderLog.fld_InventoryId) AND (tbl_UHF_ReaderLog_3.fld_TagSerial <> '000')) as UHFLogActionCount
FROM            tbl_UHF_ReaderLog
WHERE        (fld_Reader_Gate = N'{DeviceId}') AND (fld_Reader_GateType = '{ActionType}')
ORDER BY fld_InventoryId desc";


        return dataAccess.SqlDataAdapter(cmd);
    }


