    public bool SSaveSecurityLog(List<string> tags, string code, string gate, string gateType)
    {
        var logResult = SSaveEnumerationPallets("StoreProduct client", code, gate, tags, gateType, true);
        if (!logResult)
        {
            var dt = new DataTable();
            dt.Columns.Add("اطلاعات تگ ثبت نشد");
            return false;
        }

        return true;
    }

    public List<CeramicAggregateResult> SPSaveSecurityGateUHFLog(List<string> tags, string code, string gate, string gateType)
    {
        try
        {
            var logResult = SSaveEnumerationPallets("StoreProduct client", code, gate, tags, gateType, true);
            if (!logResult)
            {
                var dt = new DataTable();
                dt.Columns.Add("اطلاعات تگ ثبت نشد");
                return null;
            }


            var listTag = new DataTable();
            var cmdGetlistTag = @"SELECT DISTINCT  '0' AS Message,tbl_UHF_ReaderLog.fld_TagSerial, COALESCE(tbl_Tags.ProductSerial,N'-1') as [ProductSerial], tbl_Tags.ProductCode,tbl_Tags.ProductName, tbl_Tags.ProductCount AS Value
FROM            tbl_UHF_ReaderLog LEFT OUTER JOIN
                         tbl_Tags ON tbl_UHF_ReaderLog.fld_TagSerial = tbl_Tags.TagEpc
 WHERE(fld_Reader_Gate = N'" + gate + "') AND(fld_InventoryId = N'" + code + "')";
            listTag = dataAccess.SqlDataAdapter(cmdGetlistTag, 5000);

            if (listTag is null)
            {
                listTag = new DataTable();
            }

            var strTags = string.Empty;

            var dtResult = new DataTable();
            dtResult.Columns.Add("Error");
            dtResult.Columns.Add("TagEpc");
            dtResult.Columns.Add("ProductSerial");
            dtResult.Columns.Add("ProductCode");
            dtResult.Columns.Add("ProductName");
            dtResult.Columns.Add("ProductCount");
            dtResult.Columns.Add("SumCount");

            decimal sumValueCorrectProduct = 0;
            decimal countCorrectProduct = 0;
            decimal sumValueIncorrectProduct = 0;
            decimal countIncorrectProduct = 0;

            foreach (DataRow tag in listTag.Rows)
            {
                if (tag[2].ToString() != "-1")
                {
                    if (!string.IsNullOrEmpty(strTags))
                        strTags += ",";
                    strTags += ($"N'{tag[1].ToString()}'");
                    var val = tag[5].ToString();
                    sumValueCorrectProduct += decimal.Parse(string.IsNullOrEmpty(val) ? "0" : val);
                    countCorrectProduct++;
                }
                else
                {
                    var val = tag[5].ToString();
                    sumValueIncorrectProduct += decimal.Parse(string.IsNullOrEmpty(val) ? "0" : val);
                    countIncorrectProduct++;
                }
            }

            var finalList = new List<CeramicAggregateResult>();
            finalList.Add(new CeramicAggregateResult()
            {
                Error = "1",
                TagEpc = "0",
                ProductSerial = "0",
                ProductCode = "0",
                ProductName = "0",
                ProductCount = sumValueCorrectProduct,
                SumCount = countCorrectProduct
            });

            finalList.Add(new CeramicAggregateResult()
            {
                Error = "2",
                TagEpc = "0",
                ProductSerial = "0",
                ProductCode = "0",
                ProductName = "0",
                ProductCount = sumValueIncorrectProduct,
                SumCount = countIncorrectProduct
            });

            if (listTag.Rows.Count > 0)
            {
                var listTajamoee = new DataTable();
                var cmdGetTajamoee =
                    @" SELECT        ProductCode, ProductName, SUM(ProductCount) AS SumValue, COUNT(ProductSerial) AS Count
                    FROM            tbl_Tags  WHERE TagEpc IN(" + strTags + ") GROUP BY ProductCode, ProductName";
                listTajamoee = dataAccess.SqlDataAdapter(cmdGetTajamoee);
                foreach (DataRow Rowdata in listTajamoee.Rows)
                {
                    decimal.TryParse(Rowdata[2].ToString(), out decimal countDec);
                    decimal.TryParse(Rowdata[3].ToString(), out decimal countSum);
                    finalList.Add(new CeramicAggregateResult()
                    {
                        Error = "3",
                        TagEpc = "0",
                        ProductSerial = "0",
                        ProductCode = Rowdata[0].ToString(),
                        ProductName = Rowdata[1].ToString(),
                        ProductCount = countDec,
                        SumCount = countSum
                    });
                }
            }
            return finalList.Distinct().ToList();
        }
        catch (Exception e)
        {
            return null;
        }
    }

    public bool SSaveInventoryWithDesc(int header, string store, string deviceId, string[] data, string desc, DateTime? saveDateTime = null)
    {
        if (saveDateTime is null)
        {
            saveDateTime = DateTime.Now;
        }

        var childrenCommands = new List<KeyValuePair<string, KeyValuePair<string, object>[]>>();
        desc = desc.Replace("{", "").Replace("}", "");
        var splited = desc.Contains(',') ? desc.Split(',') : new string[0];
        var descDic = new Dictionary<string, string>();
        for (int i = 0; i < splited.Length; i++)
        {
            var item = splited[i].Split('=');
            descDic.Add(item[0].Trim(), item[1].Trim());
        }
        var checkInvHeader = " SELECT Count(*) FROM tbl_InventoryHeader WHERE fld_InventoryHeaderId = " + header;
        var check = (int)dataAccess
            .SqlDataAdapter(checkInvHeader).Select()[0].ItemArray[0] > 0;
        if (!check)
        {
            var invHeader = @"
                                 SET IDENTITY_INSERT tbl_InventoryHeader ON;  
                                 INSERT INTO tbl_InventoryHeader
                                                          (fld_InventoryHeaderId, fld_InventoryDate, fld_InventoryTime, fld_InventoryUserId)
                                 VALUES        (@HeaderId,@Date,@Time,@UserId)
                                 SET IDENTITY_INSERT tbl_InventoryHeader OFF; ";
            var parameters = new List<KeyValuePair<string, object>>();

            parameters.Add(new("HeaderId", header));
            parameters.Add(new("Date", PersianCalendarTools.GregorianToPersian(saveDateTime)));
            parameters.Add(new("UserId", deviceId));
            parameters.Add(new("Time", saveDateTime.Value.ToString("HH:mm")));
            childrenCommands.Add(new(invHeader, parameters.ToArray()));

        }
        var headerEpcsCmd = " SELECT fld_InventoryTagEPC FROM tbl_InventoryTags WHERE fld_InventoryHeaderId = " + header;
        var headerEpcs = dataAccess
            .SqlDataAdapter(headerEpcsCmd).Select().Select(p => p.ItemArray[0].ToString()).ToArray();
        foreach (string item in data)
        {
            string InventoryEpc = "";
            string InventoryLocation = "";
            string InventoryDescription = "";

            if (item.Contains("___"))
            {
                InventoryEpc = item.Split("___")[0];
                InventoryLocation = item.Split("___")[1];
                InventoryDescription = item.Split("___")[2];

            }
            else
            {
                InventoryEpc = item;
            }
            if (headerEpcs.Contains(item))
                continue;
            var insertCmd = @" INSERT INTO tbl_InventoryTags (fld_InventoryHeaderId,fld_InventoryTagEPC, fld_InventoryStoreCode, fld_InventoryDate, fld_InventoryDateTime, fld_InventoryUser, fld_InventoryDeviceIp, fld_InventoryDeviceId,fld_InventoryProductDesc,fld_InventoryPlace)
                                                  VALUES        (@HeaderId,@EPC,@StoreCode,@Date,GetDate(),@User,N'',@DeviceId,@Desc,@Location)";
            var parameters = new List<KeyValuePair<string, object>>();

            parameters.Add(new("HeaderId", header));
            parameters.Add(new("EPC", InventoryEpc));
            parameters.Add(new("StoreCode", store));
            parameters.Add(new("Date", PersianCalendarTools.GregorianToPersian(saveDateTime)));
            parameters.Add(new("User", deviceId));
            parameters.Add(new("DeviceId", deviceId));
            parameters.Add(new("Location", InventoryLocation));
            if (descDic.ContainsKey(item))
                parameters.Add(new("Desc", InventoryDescription));
            else
                parameters.Add(new("Desc", InventoryDescription));
            childrenCommands.Add(new(insertCmd, parameters.ToArray()));
        }
        return dataAccess.CmdSqlExecuteNonQueryWithTransaction(childrenCommands) == 1;
    }
