    /// <summary>
    /// 0TagEpc  ,1ProductSerial,  2ProductCode,   3ProductCount,   4ProductName,  5ProductTypeTitle,  6ProductStatusTitle,7TagStatus,   8TagRegisterShamsiUnixDate,   9RegCode,10fld_ProductPropertyATitle,   11fld_ProductPropertyBTitle,  12ProductProperties,13ProductENTitle,   14ProductPackWeight,   15ProductPackVolume,16ProductCountInPack,  17ProductValue,   18ProductSize,19ProductUnit
    /// /// </summary>
    /// <param name="epc"></param>
    /// <returns></returns>
    public DataTable SGetProduct(string epc)
    {
        if(epc.Length>24)
        {
            epc = epc.Substring(0, 24);
        }
        DataTable _dtResult;
        var cmd = @"SELECT        TOP (1) COALESCE (tbl_Tags.TagEpc, N'') AS TagEpc, COALESCE (tbl_Tags.ProductSerial, N'') AS ProductSerial, COALESCE (tbl_Tags.ProductCode, N'') AS ProductCode, COALESCE (tbl_Tags.ProductCount, 0) AS ProductCount, 
                         COALESCE (tbl_Tags.ProductName, N'') AS ProductName, COALESCE (tbl_ProductType.ProductTypeTitle, N'') AS ProductTypeTitle, COALESCE (tbl_ProductStatus.ProductStatusTitle, N'') AS ProductStatusTitle, 
                         COALESCE (tbl_Tags.TagStatus, 0) AS TagStatus, COALESCE (tbl_Tags.TagRegisterShamsiUnixDate, N'') AS TagRegisterShamsiUnixDate, COALESCE (tbl_Tags.RegCode, N'') AS RegCode, 
                         COALESCE (tbl_ProductPropertyA.fld_ProductPropertyATitle, N'') AS fld_ProductPropertyATitle, COALESCE (tbl_ProductPropertyB.fld_ProductPropertyBTitle, N'') AS fld_ProductPropertyBTitle, 
                         COALESCE (tbl_Tags.ProductProperties, N'') AS ProductProperties, COALESCE (tbl_Products.ProductENTitle, N'') AS ProductENTitle, COALESCE (tbl_Products.ProductPackWeight, 0) AS ProductPackWeight, 
                         COALESCE (tbl_Products.ProductPackVolume, 0) AS ProductPackVolume, CASE WHEN (COALESCE (tbl_Tags.ProductCount, 0) > 0) THEN CAST((tbl_Tags.ProductCount / COALESCE (tbl_Products.ProductValue, 0)) AS float) 
                         ELSE 0 END AS ProductCountInPack, COALESCE (tbl_Products.ProductValue, 0) AS ProductValue, COALESCE (tbl_Products.ProductSize, N'') AS ProductSize, COALESCE (tbl_Products.ProductUnit, N'') AS ProductUnit, 
                         COALESCE (tbl_Tags.DeviceIp, N'') AS OldProductSerial, COALESCE (CAST(tbl_Tags.ContractStatus AS nvarchar(100)), N'') AS DocumentCode, COALESCE (tbl_Tags.TagZone, N'') AS TagZone, 
                         COALESCE (tbl_Tags.fld_LastInspectResult, N'') AS LastInspectResult, COALESCE (tbl_Tags.Lock, 0) AS Lock, COALESCE
                             ((SELECT        fld_ProductBrandTitle
                                 FROM            tbl_ProductBrand
                                 WHERE        (fld_ProductBrandCode = tbl_Tags.fld_ProductBrand)), N'') AS ProductBrand, COALESCE
                             ((SELECT        fld_ProductGroupTitle
                                 FROM            tbl_ProductGroup
                                 WHERE        (fld_ProductGroupCode = tbl_Tags.fld_ProductGroup)), N'') AS ProductGroup, COALESCE (tbl_Tags.TagInDestinationId, N'0') AS WarehouseCode, COALESCE
                             ((SELECT        DestinationTitle
                                 FROM            tbl_Destination
                                 WHERE        (DestinationCode = tbl_Tags.TagInDestinationId)), N'') AS WarehouseTitle, 
                         CASE WHEN tbl_Tags.TagStatus = 0 THEN N'انبارهای تولید' WHEN tbl_Tags.TagStatus = 1 THEN N'انبارهای محصول' WHEN tbl_Tags.TagStatus = 2 THEN N'انبارهای بارگیری' ELSE N'-' END AS TagStatusTitle, 
                         CASE WHEN tbl_Tags.Freeze = 0 THEN N'عدم فریز' WHEN tbl_Tags.TagStatus = 1 THEN N'فریز شده' ELSE N'-' END AS FreezeStatusTitle, CASE WHEN (tbl_Tags.Lock = 0 AND fld_LastInspectResult = N'[]') 
                         THEN N'بازرسی نشده' WHEN (tbl_Tags.Lock = 0 AND fld_LastInspectResult <> N'[]') THEN N'بازرسی تأیید' WHEN (tbl_Tags.Lock = 1 AND fld_LastInspectResult <> N'[]') THEN N'بازرسی مردود' ELSE N'-' END AS InspectStatusTitle, 
                         SUBSTRING(tbl_Tags.TagRegisterShamsiUnixDate, 0, 5) + '/' + SUBSTRING(tbl_Tags.TagRegisterShamsiUnixDate, 5, 2) + '/' + SUBSTRING(tbl_Tags.TagRegisterShamsiUnixDate, 7, 2) 
                         + '  ' + SUBSTRING(tbl_Tags.TagRegisterShamsiUnixDate, 9, 2) + ':' + SUBSTRING(tbl_Tags.TagRegisterShamsiUnixDate, 11, 2) AS TagRegisterShamsiTime,'1' as UnitCount,Coalesce(TagTreeParentSerial,'') as ParentSerial,Coalesce(TagTreeParentsId,'') as TransferParentSerial
FROM            tbl_Tags LEFT OUTER JOIN
                         tbl_Products ON tbl_Tags.ProductCode = tbl_Products.ProductCode LEFT OUTER JOIN
                         tbl_ProductType ON tbl_Tags.ProductType = tbl_ProductType.ProductTypeCode LEFT OUTER JOIN
                         tbl_ProductStatus ON tbl_Tags.ProductStatus = tbl_ProductStatus.ProductStatusCode LEFT OUTER JOIN
                         tbl_ProductPropertyA ON tbl_Tags.fld_ProductPropertyAId = tbl_ProductPropertyA.fld_ProductPropertyAId LEFT OUTER JOIN
                         tbl_ProductPropertyB ON tbl_Tags.fld_ProductPropertyBId = tbl_ProductPropertyB.fld_ProductPropertyBId
WHERE        (tbl_Tags.TagEpc = @Epc) OR
                         (tbl_Tags.ProductSerial = @Epc) OR
                         (tbl_Tags.DeviceIp = @Epc) OR
                         (tbl_Tags.TagEpc2 = @Epc) ";

        _dtResult = dataAccess.SqlDataAdapter(cmd, new KeyValuePair<string, object>("Epc", epc));
        if (_dtResult.Rows.Count == 0)
        {
            var cmdGetDataByUnitEpc = @"SELECT TOP(1) COALESCE(tbl_TagsUnitTree.fld_TUTEPC, N'') AS TagEpc, COALESCE (tbl_TagsUnitTree.fld_TUTSerial, N'') AS ProductSerial, COALESCE (tbl_TagsUnitTree.fld_TUTProductCode, N'') AS ProductCode, COALESCE (tbl_TagsUnitTree.fld_TUTSumValue, 0) AS ProductCount,
             COALESCE (tbl_UOM.fld_UOMTitle + ' - ' + tbl_Products.ProductTitle + ' - ' + CAST(tbl_TagsUnitTree.fld_TUTCount AS nvarchar(50)) + N' عددی', N'') AS ProductName, COALESCE (tbl_ProductType.ProductTypeTitle, N'') AS ProductTypeTitle, COALESCE (tbl_ProductStatus.ProductStatusTitle, N'') AS ProductStatusTitle, '0' AS TagStatus,
             COALESCE (tbl_TagsUnitTree.fld_TUTRegDate, N'') AS TagRegisterShamsiUnixDate, COALESCE (tbl_Products.ProductTechnicalCode, N'') AS RegCode, '' AS fld_ProductPropertyATitle, '' AS fld_ProductPropertyBTitle, '' AS ProductProperties, COALESCE (tbl_Products.ProductENTitle, N'') AS ProductENTitle, '0' AS ProductPackWeight,
             '0' AS ProductPackVolume, 0 AS ProductCountInPack, 0 AS ProductValue, COALESCE (tbl_Products.ProductSize, N'') AS ProductSize, COALESCE (tbl_Products.ProductUnit, N'') AS ProductUnit, '' AS OldProductSerial, '' AS DocumentCode, '' AS TagZone, '' AS LastInspectResult, '' AS Lock, COALESCE
                 ((SELECT   fld_ProductBrandTitle
                 FROM      tbl_ProductBrand
                 WHERE(fld_ProductBrandCode = tbl_Products.fld_ProductBrand)), N'') AS ProductBrand, COALESCE
                 ((SELECT   fld_ProductGroupTitle
                 FROM      tbl_ProductGroup
                 WHERE(fld_ProductGroupCode = tbl_Products.fld_ProductGroup)), N'') AS ProductGroup, '' AS WarehouseCode, '' AS WarehouseTitle, '' AS TagStatusTitle, '' AS FreezeStatusTitle, '' AS InspectStatusTitle, '' AS TagRegisterShamsiTime, tbl_TagsUnitTree.fld_TUTCount AS UnitCount,'' as ParentSerial, ''  as TransferParentSerial
FROM     tbl_ProductStatus RIGHT OUTER JOIN
             tbl_Products ON tbl_ProductStatus.ProductStatusCode = tbl_Products.ProductStatus LEFT OUTER JOIN
             tbl_ProductType ON tbl_Products.ProductType = tbl_ProductType.ProductTypeCode RIGHT OUTER JOIN
             tbl_TagsUnitTree ON tbl_Products.ProductCode = tbl_TagsUnitTree.fld_TUTProductCode LEFT OUTER JOIN
             tbl_ProductUOM LEFT OUTER JOIN
             tbl_UOM ON tbl_ProductUOM.fld_UOMId = tbl_UOM.fld_UOMId ON tbl_TagsUnitTree.fld_TUTProductCode = tbl_ProductUOM.fld_ProductCode AND tbl_TagsUnitTree.fld_TUTUnitId = tbl_ProductUOM.fld_ProductUOMId
WHERE (tbl_TagsUnitTree.fld_TUTEPC = @Epc) OR
             (tbl_TagsUnitTree.fld_TUTSerial = @Epc)";

            _dtResult = dataAccess.SqlDataAdapter(cmdGetDataByUnitEpc, new KeyValuePair<string, object>("Epc", epc));

        }

        return _dtResult;
    }


