    public bool SPSaveExitProducts(
    string username,
    string actionId,
    string deviceId,
    string CarPlaque,
    string DriverName,
    string DriverMobile,
     string actionDesc,
    string[] listTags,
    string TagStatus = "2")
    {
        if (TagStatus == "1")
            TagStatus = "2";
        var childrenCommands = new List<KeyValuePair<string, KeyValuePair<string, object>[]>>();

        var commandCheckExist = @" SELECT  MovementActionId From   tbl_MovementActions Where MovementActionId=" + actionId + " AND MovementActionTp=2";

        var resultCheckExist = dataAccess.SqlDataAdapter(commandCheckExist);


        var commandMovementAction = (resultCheckExist.Select().ToList().Count == 0) ? string.Format(@"INSERT    
INTO              tbl_MovementActions(MovementActionId,  MovementActionTp, MovementActionStore, MovementActionUserId, MovementActionDate, MovementActionTime, MovementActionDateTime, MovementActionCountTags, 
                         MovementActionDestinationId, MovementActionCarPlaque, MovementActionDriverName,  MovementActionData)
VALUES        (@MovementActionId,@MovementActionTp, @MovementActionStore, @MovementActionUserId, @MovementActionDate, @MovementActionTime, @MovementActionDateTime, @MovementActionCountTags, 
                         @MovementActionDestinationId, @MovementActionCarPlaque, @MovementActionDriverName,  @MovementActionData)") : @"UPDATE       tbl_MovementActions
SET                MovementActionCountTags = @MovementActionCountTags,
                MovementActionDestinationId = @MovementActionDestinationId,
                MovementActionCarPlaque = @MovementActionCarPlaque,
                MovementActionDriverName = @MovementActionDriverName,
                MovementActionData = @MovementActionData
WHERE(MovementActionId = @MovementActionId)and MovementActionTp=@MovementActionTp";

        actionId = actionId == "-1" ? SGetMaxIdByMovementActionTp(2).ToString() : actionId;
        var parameters = new List<KeyValuePair<string, object>>();

        parameters.Add(new("MovementActionId", actionId));
        parameters.Add(new("MovementActionTp", "2"));//Exit
        parameters.Add(new("MovementActionStore", ""));
        parameters.Add(new("MovementActionDateTime", DateTime.Now.ToString()));
        parameters.Add(new("MovementActionDestinationId", "0"));
        parameters.Add(new("MovementActionCarPlaque", CarPlaque));
        parameters.Add(new("MovementActionDriverName", DriverName));

        object dataObjectAction = new
        {
            MovementActionDesc = actionDesc
        };
        parameters.Add(new("MovementActionData", JToken.FromObject(dataObjectAction).ToString()));
        parameters.Add(new("MovementActionUserId", username));
        parameters.Add(new("MovementActionDate", DateTimeTools.GetPersianDate()));
        parameters.Add(new("MovementActionTime", DateTimeTools.GetTime()));
        parameters.Add(new("MovementActionCountTags", listTags.Count()));
        childrenCommands.Add(new(commandMovementAction, parameters.ToArray()));


        foreach (string tag in listTags)
        {

            var commandTagMovementAction = @"UPDATE tbl_TagsMovement SET
                                                      HMovementActionId = @ActionId, HTagsMovementDate = @Date, HTagsMovementTime = @Time,
                                                      HTagsMovementDateTime = @DateTime, HTagsMovementSt = 1,
                                                      MovementData = @Data     
                                                      WHERE (TagEpc=@tag) and RTagsMovementSt=1 and HTagsMovementSt=0 ";
            var param = new List<KeyValuePair<string, object>>();
            param.Add(new("tag", tag));
            param.Add(new("ActionId", actionId));
            param.Add(new("Date", DateTimeTools.GetPersianDate()));
            param.Add(new("Time", DateTimeTools.GetTime()));
            param.Add(new("DateTime", DateTime.Now));
            param.Add(new("Data", ""));
            childrenCommands.Add(new(commandTagMovementAction, param.ToArray()));

            var commandSt = " UPDATE tbl_Tags SET TagStatus = @StCd, TagInActionId = @ActId, TagInDestinationId = @DestId  WHERE TagEpc = @TEpc ";
            var parametersSt = new List<KeyValuePair<string, object>>();

            parametersSt.Add(new("StCd", 1));
            parametersSt.Add(new("TEpc", tag));
            parametersSt.Add(new("ActId", actionId));
            parametersSt.Add(new("DestId", ""));

            childrenCommands.Add(new(commandSt, parametersSt.ToArray()));
        }

        bool result = dataAccess.CmdSqlExecuteNonQueryWithTransaction(childrenCommands) > 0;

        logger.LogInformation("SPSaveExitProducts => Result: " + result.ToString());

        return result;
    }

