    public int SCreateNewUHFReaderLogHeader(SaveUHFReaderLogHeaderCommand command)
    {
        string userId = httpContext.User.GetUserId();

        UHFReaderLogHeader header = new UHFReaderLogHeader
        {
            StationCode = command?.StationCode,
            ActionTypeCode = command?.ActionTypeCode,
            DocumentCode = command?.DocumentCode,
            TruckCrossId = command?.TruckCrossId,
            UserId = userId,
            ControlType = command?.ControlType,
