        var cmdInsert = @" INSERT      
INTO              tbl_UHF_ReaderLog(fld_TagSerial, fld_InventoryId,fld_Reader_Gate,fld_TagRead_DateTime)
VALUES('000', " + header.Id.ToString() + @",'" + command?.StationCode + @"','0')";

        var resultInsert = dataAccess.CmdSqlExecuteNonQuery(cmdInsert);

        return header.Id;
    }

    public int SCreateUHFReaderLogHeadersFromUHFReaderLog()
    {
        var command = """
            SET IDENTITY_INSERT [dbo].[tbl_UHFReaderLogHeader]  ON
            
            IF OBJECT_ID('tempdb..#TempUniqueInventoryIds') IS NOT NULL
                DROP TABLE #TempUniqueInventoryIds;

            SELECT 
                DISTINCT fld_InventoryId
            INTO #TempUniqueInventoryIds
            FROM (
                SELECT fld_InventoryId FROM [dbo].[tbl_UHF_ReaderLog]
                UNION
                SELECT fld_InventoryId FROM [dbo].[tbl_UHF_ReaderLogMain]
            ) AS CombinedInventoryIds;

            WITH CombinedRanks AS (
                SELECT 
                    s.fld_InventoryId,
                    s.fld_Reader_Gate,
                    s.fld_DocumentId,
                    s.fld_SaveUserId,
                    s.MovementActionId,
                    ROW_NUMBER() OVER (PARTITION BY s.fld_InventoryId ORDER BY s.fld_InventoryId) AS rn
                FROM (
                    SELECT fld_InventoryId, fld_Reader_Gate, fld_DocumentId, fld_SaveUserId, MovementActionId
                    FROM [dbo].[tbl_UHF_ReaderLog]
                    UNION ALL
                    SELECT fld_InventoryId, fld_Reader_Gate, fld_DocumentId, fld_SaveUserId, MovementActionId
                    FROM [dbo].[tbl_UHF_ReaderLogMain]
                ) AS s
                INNER JOIN #TempUniqueInventoryIds t ON s.fld_InventoryId = t.fld_InventoryId
            )
            INSERT INTO [dbo].[tbl_UHFReaderLogHeader] (
                fld_UHFReaderLogHeaderId,
                fld_StationCode,
                fld_ActionType,
                fld_DocumentCode,
                fld_TruckCrossId,
                fld_UHFReaderLogHeaderUserId,
                fld_UHFReaderLogHeaderControlType,
                fld_CarProperties,
                fld_MovementActionId
            )
            SELECT
                fld_InventoryId AS fld_UHFReaderLogHeaderId,
                fld_Reader_Gate AS fld_StationCode,
                NULL AS fld_ActionType,
                fld_DocumentId AS fld_DocumentCode,
                NULL AS fld_TruckCrossId,
                fld_SaveUserId AS fld_UHFReaderLogHeaderUserId,
                NULL AS fld_UHFReaderLogHeaderControlType,
                NULL AS fld_CarProperties,
                MovementActionId AS fld_MovementActionId
            FROM CombinedRanks
            WHERE rn = 1
            ORDER BY fld_InventoryId;

            DROP TABLE #TempUniqueInventoryIds;

            SET IDENTITY_INSERT [dbo].[tbl_UHFReaderLogHeader]  OFF
            """;

        return dataAccess.CmdSqlExecuteNonQuery(command);
    }

    public int SGetMaxInvIdByGate(string gate)
    {
        int Id = 0;

        var cmd = @$"SELECT        COALESCE (MAX(tbl_UHF_ReaderLog.fld_InventoryId), N'0') AS MaxId
FROM            tbl_UHF_ReaderLog LEFT OUTER JOIN
                         tbl_Tags ON tbl_UHF_ReaderLog.fld_TagSerial = tbl_Tags.TagEpc
WHERE        (tbl_Tags.Id IS NOT NULL) and fld_Reader_Gate = N'{gate}'";

        var dt = dataAccess.SqlDataAdapter(cmd);

