        {
            Id = result;
        }

        return Id;
    }

    public int SGetNextPreviousInvIdByCurrentId(bool isNext, string invId, string gate)
    {
        int Id = 0;

        var whereString = isNext ? $"WHERE        (tbl_Tags.Id IS NOT NULL) and  fld_Reader_Gate = N'{gate}' AND fld_InventoryId > N'{invId}'"
                                 : $"WHERE        (tbl_Tags.Id IS NOT NULL) and  fld_Reader_Gate = N'{gate}' AND fld_InventoryId < N'{invId}'";

        var orderBy = isNext ? $" ORDER BY  fld_InventoryId "
                             : $" ORDER BY  fld_InventoryId DESC";

        var cmd = @$"SELECT        TOP (1) COALESCE (tbl_UHF_ReaderLog.fld_InventoryId, N'0') AS NextPreviousId
FROM            tbl_UHF_ReaderLog LEFT OUTER JOIN
                         tbl_Tags ON tbl_UHF_ReaderLog.fld_TagSerial = tbl_Tags.TagEpc
                    {whereString}
                    {orderBy}";

        var dt = dataAccess.SqlDataAdapter(cmd).Select().ToList();

        if (dt.Any())
        {
            if (int.TryParse(dt.First().ItemArray[0].ToString(), out int result))
            {
                Id = result;
            }
        }
        else
        {
            Id = 0;
        }

        return Id;
    }

    public DataTable GetAllProductPropertyAData(string userToken)
