    public DataTable SGetDataFromCus(string code)
    {
        var cmd = @" SELECT _Mats.mat_Code AS ProductCode, _Mats.mat_Name AS ProductName, SUM(_InvTranses.itr_Amount) AS SumValue, COALESCE (_Arts.art_Desc, N'') AS[Desc]         FROM _InvTranses INNER JOIN                               _Mats ON _Mats.mat_Key = _InvTranses.itr_MatKey INNER JOIN                                _Arts ON _Arts.art_Key = _InvTranses.itr_ArtKey      WHERE(_Arts.art_Key = @DocumentID) AND(_Mats.mat_Name NOT LIKE N'%PATTERN%') AND(_InvTranses.itr_StockKey in (6, 24, 27))         GROUP BY _Mats.mat_Code, _Mats.mat_Name, _Arts.art_Desc";
        return dataAccess.SqlDataAdapter(cmd,
            configuration.GetConnectionString("NosaConnectionString"),
            new KeyValuePair<string, object>("DocumentID", code));
    }

    public bool SSaveProductType(
           string ProductTypeTitle, string ProductTypeParentId, string ProductTypeParentsId, string ProductTypeCode, string userToken)
    {
        string commandProductTypeCodeExist = "SELECT ProductTypeCode FROM tbl_ProductType WHERE ProductTypeCode = N'" + ProductTypeCode + "'";
        var hasValue = dataAccess.SqlDataReaders(commandProductTypeCodeExist);
        if (hasValue == null)
        {
            var command = @" INSERT INTO tbl_ProductType (ProductTypeTitle,ProductTypeParentId,ProductTypeParentsId,ProductTypeCode) 
                                 VALUES (@Title,@PId,@PIds,@Code) ";

            return dataAccess.CmdSqlExecuteNonQuery(command
                , new KeyValuePair<string, object>("Title", ProductTypeTitle)
                , new KeyValuePair<string, object>("PId", ProductTypeParentId)
                , new KeyValuePair<string, object>("PIds", ProductTypeParentsId)
                , new KeyValuePair<string, object>("Code", ProductTypeCode)) > 0;
        }
        else
        {
            var commandUpdate = @"UPDATE tbl_ProductType SET 
										ProductTypeTitle = @ProductTypeTitle,
														ProductTypeParentId = @ProductTypeParentId
														 
									WHERE
										(ProductTypeCode = @ProductTypeCode)";

            return dataAccess.CmdSqlExecuteNonQuery(commandUpdate
                , new KeyValuePair<string, object>("ProductTypeTitle", ProductTypeTitle)
                , new KeyValuePair<string, object>("ProductTypeParentId", ProductTypeParentId)
                , new KeyValuePair<string, object>("ProductTypeCode", ProductTypeCode)) > 0;
        }

    }

    public string SGetDataFromCusDocumentDesc(string code)
    {
        var cmd = @" SELECT       COALESCE (_Arts.art_Desc, N'') AS [Desc] FROM       _Arts  
                                        WHERE        (_Arts.art_Key = @DocumentID)   ";
        DataTable _dt = dataAccess.SqlDataAdapter(cmd,
           configuration.GetConnectionString("NosaConnectionString"),
            new KeyValuePair<string, object>("DocumentID", code));
        if (_dt.Rows.Count > 0)
        {
            DataRow dr = _dt.Rows[0];
            string Desc = dr["Desc"].ToString();
            int startIndex = Desc.LastIndexOf("مقصد") + 4;
            string Destiantion = Desc.Substring(startIndex, Desc.Length - startIndex).Replace(':', ' ').Trim();
            string DestinationType = "1";

            if (Destiantion.Contains("عراق")
                   || Destiantion.Contains("امارت")
                   || Destiantion.Contains("قطر")
                   || Destiantion.Contains("سوریه")
                   || Destiantion.Contains("گرجستان")
                   || Destiantion.Contains("ترکمنستان")
                   || Destiantion.Contains("ارمنستان")
                   || Destiantion.Contains("بلغارستان")
                   || Destiantion.Contains("بحرین")
                   || Destiantion.Contains("کویت")
                   || Destiantion.Contains("افغانستان")
                   || Destiantion.Contains("باکو")
                   || Destiantion.Contains("باكو")
                   || Destiantion.Contains("بـاکــو")
                   || Destiantion.Contains("تركمنستان")
                   || Destiantion.Contains("پاكستان")
                   || Destiantion.Contains("قرقيزستان")
                   || Destiantion.Contains("بحرين")
                   || Destiantion.Contains("عمان")
                   || Destiantion.Contains("دبي")
                   || Destiantion.Contains("دبي")
                   || Destiantion.Contains("دبی")
                   || Destiantion.Contains("قرقيزستان")
                   || Destiantion.Contains("ازبكستان".Trim())
                   || Destiantion.Contains("روسیه".Trim())
                   || Destiantion.Contains("روسیــه".Trim())
                   || Destiantion.Contains("روسيه".Trim())
                   || Destiantion.Contains("روسيه".Trim())
                   || Destiantion.Contains("تركيه".Trim())
                   || Destiantion.Contains("تركيه".Trim()))
            {
                DestinationType = "2";
            }

            return Destiantion + "*" + DestinationType;
        }
        else
            return "مشخص نشده" + "*0";
    }

