    public DataTable SPGetPlacementOrdersList(int type = -1)
    {
        var cmd = "";
        var whereString = string.Empty;
        if (!type.Equals(-1))
            whereString = $" WHERE fld_POType = {type} ";

        cmd += $@"  SELECT        tbl_PlacementOrders.fld_POCode AS OrderCode, 
                    dbo.GeorgianDateToJalaliDate(tbl_PlacementOrders.fld_PODateTime) AS [DateTime],
                    tbl_PlacementOrders.fld_POUser AS [Username], 
                    tbl_PlacementOrders.fld_POProductCode AS ProductCode,
                    COALESCE(tbl_Products.ProductTechnicalCode,N'' ) AS RegCode,
                    COALESCE(tbl_Products.ProductTitle ,N'' ) AS ProductName,
                    SUM(tbl_PlacementOrders.fld_POPackCount) AS [Count], 
                    SUM(tbl_PlacementOrders.fld_POPackCountRemain) AS PackRemain,
                    string_agg(tbl_PlacementOrders.fld_POZoneCode, ' | ') AS Zones,
                    tbl_PlacementOrders.fld_POStatus as [Status]
                    FROM            tbl_PlacementOrders INNER JOIN
                                             tbl_Products ON tbl_PlacementOrders.fld_POProductCode = tbl_Products.ProductCode
                    {whereString}
                    GROUP BY tbl_PlacementOrders.fld_POCode, tbl_PlacementOrders.fld_POUser, tbl_PlacementOrders.fld_PODateTime, 
                    tbl_PlacementOrders.fld_POProductCode, tbl_Products.ProductTitle, tbl_PlacementOrders.fld_POStatus,
                    tbl_Products.ProductTechnicalCode
                    ORDER BY OrderCode DESC";
        return dataAccess.SqlDataAdapter(cmd);
    }

    public DataTable SGetPlacementOrders()
    {
        var command =
            """
            SELECT  fld_POParent AS OperationCode, 
            		COALESCE(fld_PODocumentKey,N'') AS DocumentKey,
            		COALESCE(fld_PODocumentType,N'') AS DocumentType,
            		(SELECT TOP(1) SubPlacementOrder.fld_PODateTime 
            		FROM tbl_PlacementOrders AS SubPlacementOrder 
            		WHERE MainPlacementOrder.fld_POParent = SubPlacementOrder.fld_POParent ) AS [DateTime],
            		COALESCE(tbl_User.Name,N'') AS [User],
            		fld_POStatus AS [Status],
            		Count(fld_POCode) AS  OrderCount
            FROM    tbl_PlacementOrders AS MainPlacementOrder LEFT OUTER JOIN 
            		tbl_User ON MainPlacementOrder.fld_POUser =  tbl_User.Id
            WHERE fld_POParent is not null 
            GROUP BY fld_POParent,fld_PODocumentKey,fld_PODocumentType,tbl_User.Name,fld_POStatus,fld_POType
            ORDER BY fld_POParent DESC
            """;

        return dataAccess.SqlDataAdapter(command);
    }

    public DataTable SGetPlacementOrdersByOperationCode(string operationCode)
    {
        var command =
            $"""
            SELECT  tbl_PlacementOrders.fld_POCode AS OrderCode, 
            tbl_PlacementOrders.fld_PODateTime AS [DateTime],
            tbl_PlacementOrders.fld_POProductCode AS ProductCode,
            COALESCE(tbl_Products.ProductTechnicalCode, N'') AS RegCode,
            COALESCE(tbl_Products.ProductTitle, N'')AS ProductName,
            SUM(COALESCE(tbl_PlacementOrders.fld_POPackCount,0)) AS [Count], 
            SUM(COALESCE(tbl_PlacementOrders.fld_POPackCountRemain,0)) AS PackRemain,
            string_agg(tbl_PlacementOrders.fld_POZoneCode, ' | ') AS Zones,
            tbl_PlacementOrders.fld_POStatus as [Status],
            COALESCE(fld_POSumValue,0) AS SumValue
            FROM            tbl_PlacementOrders INNER JOIN
                                     tbl_Products ON tbl_PlacementOrders.fld_POProductCode = tbl_Products.ProductCode
            WHERE tbl_PlacementOrders.fld_POParent = N'{operationCode}'
            GROUP BY tbl_PlacementOrders.fld_POCode, tbl_PlacementOrders.fld_POUser, tbl_PlacementOrders.fld_PODateTime, 
            tbl_PlacementOrders.fld_POProductCode, tbl_Products.ProductTitle, tbl_PlacementOrders.fld_POStatus,
            tbl_Products.ProductTechnicalCode,tbl_PlacementOrders.fld_POSumValue
            ORDER BY OrderCode DESC
            """;

        return dataAccess.SqlDataAdapter(command);
    }

