    public int SGetRemainZoneCapacity(string storeCode, string zoneCode)
    {
        var command = $@" SELECT        ZoneCapacity -
                             Coalesce((SELECT        COUNT(DISTINCT ProductSerial) AS Expr1
                               FROM            tbl_Tags
                               WHERE        (TagZone = N'{zoneCode}')),0) AS Expr1
FROM            tbl_Zones
WHERE        (ZoneCode = N'{zoneCode}') AND (ZoneStoreCode = N'{storeCode}')";
        var dtStr = dataAccess.SqlDataAdapter(command)
            .Select().ToList();
        if (!dtStr.Any())
            return 0;
        if (int.TryParse(dtStr[0].ItemArray[0]
            .ToString(), out int result))
            return result;
        return 0;
    }

    public int SGetRemainZoneCapacityMulti(string storeCode, string zones)
    {
        var inString = string.Empty;
        foreach (string item in zones.Split('|'))
        {
            inString += !string.IsNullOrEmpty(inString) ? " , " : "";
            inString += $"N'{item.Trim()}'";
        }
        var command = @$" SELECT        ZoneCapacity -
                             Coalesce((SELECT        COUNT(DISTINCT ProductSerial) AS Expr1
                               FROM            tbl_Tags
                               WHERE        (tbl_Tags.TagZone = tbl_Zones.ZoneCode)),0) AS Expr1
FROM            tbl_Zones
WHERE        (ZoneCode IN ({inString}) ) AND (ZoneStoreCode = N'{storeCode}')";
        var dtStr = dataAccess.SqlDataAdapter(command)
            .Select().ToList();
        var final = 0;
        foreach (DataRow row in dtStr)
        {
            final += int.Parse(row.ItemArray[0].ToString());
        }
        return final;
    }

