    public string SpGetSummaryEnterGateInDate(string Date, string GateNumber)
    {
        string DateFrom = "";
        string DataTo = "";
        DateTime _dtcheckFROM = new DateTime(DateTime.Now.Year, DateTime.Now.Month, DateTime.Now.Day, 0, 0, 0);
        DateTime _dtcheckto = new DateTime(DateTime.Now.Year, DateTime.Now.Month, DateTime.Now.Day, 6, 0, 0);
        if (DateTime.Now > _dtcheckFROM && DateTime.Now < _dtcheckto)
        {
            DateFrom = PersianCalendarTools.GregorianToPersian(PersianCalendarTools.PersianToGregorian(Date).AddDays(-1)).ToString();
            DataTo = Date;
        }
        else
        {
            DateFrom = Date;
            DataTo = PersianCalendarTools.GregorianToPersian(PersianCalendarTools.PersianToGregorian(Date).AddDays(1)).ToString();
        }


        string[] StartShiftTime = new string[3];
        DataTable shiftList = SPGetShiftStartENDList();
        foreach (DataRow dr in shiftList.Rows)
        {
            string Temp = dr["fld_ProductPropertyBDesc"].ToString().Split('-')[0];
            StartShiftTime[Convert.ToInt32(dr["fld_ProductPropertyBId"].ToString()) - 1] = Temp;
        }

        var whereString = " WHERE  (HTagsMovementSt=0) and (RTagsMovementSt=1) AND  ";



        whereString += $" tbl_TagsMovement.RTagsMovementDateTime >=  dbo.JalaliDateToGeorgianDate(N'{DateFrom}',N'{StartShiftTime[0]}') AND ";

        whereString += $" (tbl_TagsMovement.RTagsMovementDateTime <= dbo.JalaliDateToGeorgianDate(N'{DataTo}',N'{StartShiftTime[0]}')) ";







        var dt = new DataTable();
        var command = @" SELECT COUNT(DISTINCT ProductSerial) AS count, SUM(ProductCount) AS Sum
FROM tbl_TagsMovement  " + whereString;
        string result = "";

        result = dataAccess.SqlDataReaders(command)[0].Value.ToString() + " / " + dataAccess.SqlDataReaders(command)[1].Value.ToString();
        return result;
    }

    public string SpGetSummaryEnterGateInShift(string Date, string GateNumber, string Shift)
    {
        try
        {
            string DateFrom = "";
            string DataTo = "";
            DateTime _dtcheckFROM = new DateTime(DateTime.Now.Year, DateTime.Now.Month, DateTime.Now.Day, 0, 0, 0);
            DateTime _dtcheckto = new DateTime(DateTime.Now.Year, DateTime.Now.Month, DateTime.Now.Day, 6, 0, 0);
            if (DateTime.Now > _dtcheckFROM && DateTime.Now < _dtcheckto)
            {
                DateFrom = PersianCalendarTools.GregorianToPersian(PersianCalendarTools.PersianToGregorian(Date).AddDays(-1)).ToString();
                DataTo = Date;
            }
            else
            {
                DateFrom = Date;
                DataTo = PersianCalendarTools.GregorianToPersian(PersianCalendarTools.PersianToGregorian(Date).AddDays(1)).ToString();
            }
            string[] StartShiftTime = new string[3];
            DataTable shiftList = SPGetShiftStartENDList();
            foreach (DataRow dr in shiftList.Rows)
            {
                string Temp = dr["fld_ProductPropertyBDesc"].ToString().Split('-')[0];
                StartShiftTime[Convert.ToInt32(dr["fld_ProductPropertyBId"].ToString()) - 1] = Temp;
            }

            var whereString = " WHERE  (HTagsMovementSt=0) and (RTagsMovementSt=1) AND  ";



            whereString += $" tbl_TagsMovement.RTagsMovementDateTime >=  dbo.JalaliDateToGeorgianDate(N'{DateFrom}',N'{StartShiftTime[0]}') AND ";

            whereString += $" (tbl_TagsMovement.RTagsMovementDateTime <= dbo.JalaliDateToGeorgianDate(N'{DataTo}',N'{StartShiftTime[0]}')) AND ";


            switch (Shift)
            {
                case "1":


                    whereString += " (tbl_TagsMovement.RTagsMovementTime >= '" + StartShiftTime[0] + "')  AND  (tbl_TagsMovement.RTagsMovementTime < '" + StartShiftTime[1] + "')   ";

                    break;
                case "2":


                    whereString += " (tbl_TagsMovement.RTagsMovementTime >= '" + StartShiftTime[1] + "')  AND  (tbl_TagsMovement.RTagsMovementTime < '" + StartShiftTime[2] + "')   ";

                    break;
                case "3":


                    whereString += " (( (tbl_TagsMovement.RTagsMovementTime >= '" + StartShiftTime[2] + "')  AND (tbl_TagsMovement.RTagsMovementTime < '24:00') ) OR ( (tbl_TagsMovement.RTagsMovementTime >= '00:00' ) and (tbl_TagsMovement.RTagsMovementTime < '" + StartShiftTime[0] + "' )))   ";

                    break;

            }


            //string[] StartEnd = SPGetShiftStartEND(Shift).Split('-');
            //string Start = StartEnd[0];
            //string End = StartEnd[1];
            //string result = "";
            //DateTime dtNow = DateTime.Now;
            //DateTime dtStart = new DateTime(dtNow.Year, dtNow.Month, dtNow.Day, Convert.ToInt32(Start.Split(':')[0]), Convert.ToInt32(Start.Split(':')[1]), 0);
            //dtNow = (Shift != "3") ? DateTime.Now : DateTime.Now.AddDays(1);
            //DateTime dtEnd = new DateTime(dtNow.Year, dtNow.Month, dtNow.Day, Convert.ToInt32(End.Split(':')[0]), Convert.ToInt32(End.Split(':')[1]), 0);

            var dt = new DataTable();
            var command = @" SELECT        COUNT(DISTINCT ProductSerial) AS count, SUM(ProductCount) AS Sum
FROM            tbl_TagsMovement   " + whereString;

            var result = dataAccess.SqlDataReaders(command)[0].Value.ToString() + " / " + dataAccess.SqlDataReaders(command)[1].Value.ToString();
            return result;
        }
        catch
        {
            return "0/0";
        }
    }


