    public string SPGetShift(string Time)
    {
        Time = DateTimeTools.ConvertFormatTimeTo24H(Time);
        string ShiftCode = "";
        DateTime dtTime = new DateTime(DateTime.Now.Year, DateTime.Now.Month, DateTime.Now.Day, Convert.ToInt32(Time.Split(':')[0]), Convert.ToInt32(Time.Split(':')[1]), 0);

        DataTable dtShiftStartENDList = SPGetShiftStartENDList();
        foreach (DataRow dr in dtShiftStartENDList.Rows)
        {
            string[] StartEnd = dr[0].ToString().Split('-');
            string Start = StartEnd[0];
            string End = StartEnd[1];

            DateTime dtNow = DateTime.Now;
            DateTime dtStart = new DateTime(dtNow.Year, dtNow.Month, dtNow.Day, Convert.ToInt32(Start.Split(':')[0]), Convert.ToInt32(Start.Split(':')[1]), 0);

            //      dtNow = (dr[1].ToString() != "3") ? DateTime.Now : DateTime.Now.AddDays(1);
            DateTime dtEnd = new DateTime(dtNow.Year, dtNow.Month, dtNow.Day, Convert.ToInt32(End.Split(':')[0]), Convert.ToInt32(End.Split(':')[1]), 0);

            if (dtTime >= dtStart && dtTime < dtEnd)
            {
                ShiftCode = dr[1].ToString();
                break;
            }
        }
        return ShiftCode;
    }

