    public bool SPSaveEnterProducts(
     string actionId,
     string deviceId,
     string actionDesc,
     string actionStore,
     string LocationCode,
     List<string> listTags
     )
    {
        string username = deviceId;

        List<KeyValuePair<string, KeyValuePair<string, object>[]>> childrenCommands = new();

        string commandMovementAction = @"INSERT    
INTO              tbl_MovementActions(MovementActionId,  MovementActionTp, MovementActionStore, MovementActionUserId, MovementActionDate, MovementActionTime, MovementActionDateTime, MovementActionCountTags, 
                         MovementActionDestinationId, MovementActionCarPlaque, MovementActionDriverName,  MovementActionData)
VALUES        (@MovementActionId,@MovementActionTp, @MovementActionStore, @MovementActionUserId, @MovementActionDate, @MovementActionTime, GETDATE(), @MovementActionCountTags, 
                         @MovementActionDestinationId, @MovementActionCarPlaque, @MovementActionDriverName,  @MovementActionData)";

        actionId = actionId == "-1" ? SGetMaxIdByMovementActionTp(1).ToString() : actionId;

        var parameters = new List<KeyValuePair<string, object>>();
        parameters.Add(new("MovementActionId", actionId));
        parameters.Add(new("MovementActionTp", "1"));//Enter
        parameters.Add(new("MovementActionStore", actionStore));
        // parameters.Add(new("MovementActionDateTime", DateTime.Now.ToString()));//Enter
        parameters.Add(new("MovementActionDestinationId", "0"));
        parameters.Add(new("MovementActionCarPlaque", ""));
        parameters.Add(new("MovementActionDriverName", ""));
        parameters.Add(new("MovementActionData", ""));
        parameters.Add(new("MovementActionUserId", username));
        parameters.Add(new("MovementActionDate", DateTimeTools.GetPersianDate()));
        parameters.Add(new("MovementActionTime", DateTimeTools.GetTime()));
        parameters.Add(new("MovementActionCountTags", listTags.Count()));
        childrenCommands.Add(new(commandMovementAction, parameters.ToArray()));

        foreach (string tag in listTags)
        {
            string commandCheck = @" SELECT ProductSerial  From tbl_TagsMovement Where TagEpc=@TagEpc AND HTagsMovementSt=0 ";

            bool FlagExist = false;

            if (dataAccess.SqlDataAdapter(commandCheck, new KeyValuePair<string, object>("TagEpc", tag)).Rows.Count > 0)
            {
                FlagExist = true;
            }

            if (!FlagExist)
            {
                var commandTagMovementAction = @"INSERT INTO tbl_TagsMovement (
														TagEpc,
														ProductCode,
														ProductSerial,
														ProductCount,
														RMovementActionId,
														RTagsMovementDate,
														RTagsMovementTime,
														RTagsMovementSt,                                                       
                                                        RTagsMovementDateTime,
                                                        HTagsMovementSt
													)
													VALUES (
														@tag,
														(SELECT Top(1) ProductCode FROM tbl_tags AS T WHERE T.tagepc = @tag),
														(SELECT Top(1) ProductSerial FROM tbl_tags AS T WHERE T.tagepc = @tag),
														(SELECT Top(1) ProductCount FROM tbl_tags AS T WHERE T.tagepc = @tag),
														@ActionId,
														@Date,
														@Time,
														1,
                                                        @RDateTime,
                                                        0)";
                var param = new List<KeyValuePair<string, object>>();

                param.Add(new("tag", tag));
                param.Add(new("RDateTime", DateTime.Now));
                param.Add(new("ActionId", actionId));
                param.Add(new("Date", DateTimeTools.GetPersianDate()));
                param.Add(new("Time", DateTimeTools.GetTime()));
                childrenCommands.Add(new(commandTagMovementAction, param.ToArray()));
            }

            var commandSt = " UPDATE tbl_Tags SET TagStatus = @StCd, TagInActionId = @ActId, TagInDestinationId = @DestId  WHERE TagEpc = @TEpc ";
            var parametersSt = new List<KeyValuePair<string, object>>();

            parametersSt.Add(new("StCd", 1));
            parametersSt.Add(new("TEpc", tag));
            parametersSt.Add(new("ActId", actionId));
            parametersSt.Add(new("DestId", LocationCode));

            childrenCommands.Add(new(commandSt, parametersSt.ToArray()));
        }

        bool result = dataAccess.CmdSqlExecuteNonQueryWithTransaction(childrenCommands) > 0;

        logger.LogInformation("SPSaveEnterProducts => Result: " + result.ToString());

        return result;
    }

