            );

    }
    public string SConfirmLocation(string operationCode, string locationCode, string fields)
    {
        var fieldsToken = JToken.Parse(fields);

        string sumWeights = (fieldsToken["sumWeights"] != null) ? fieldsToken["sumWeights"].ToString() : "";

        if (sumWeights != "")
        {

            string commandGetSerial= @" SELECT top(1) fld_ProductSerial  From tbl_UHF_ReaderLog Where fld_InventoryId=@operationCode   ";
 

            var dt = dataAccess.SqlDataAdapter(commandGetSerial, new KeyValuePair<string, object>("operationCode", operationCode));
            if (dt.Rows.Count > 0)
            {
                string ProductSerial = dt.Rows[0][0].ToString();

                if (ProductSerial != "")
                {
                    var command = " UPDATE tbl_Tags SET ProductWeight = @ProductWeight  WHERE ProductSerial = @ProductSerial ";

                    //command.Parameters.AddWithValue("TagZone", TagZone);
                    dataAccess.CmdSqlExecuteNonQuery(command,
                        new KeyValuePair<string, object>("ProductSerial", ProductSerial),
                        new KeyValuePair<string, object>("ProductWeight", sumWeights)        
                        );
                }
            }
        }

        string commandGetLocationCapacity = @" SELECT top(1) Coalesce( MaxZoneCapacity,'0')  From    tbl_Zones Where ZoneCode=@ZoneCode   ";


        var dtLocationCapacity = dataAccess.SqlDataAdapter(commandGetLocationCapacity, new KeyValuePair<string, object>("ZoneCode", locationCode));
        if (dtLocationCapacity.Rows.Count > 0)
        {
            string LocationCapacity = dtLocationCapacity.Rows[0][0].ToString();

            var OccupiedCapacityQueryText = "";

            var capacityCheckType = configuration["ProjectConfigs:WmsConfigs:Zone:CapacityCheckType"];
            switch (capacityCheckType)
            {
                case "CountSerials":
                    OccupiedCapacityQueryText = " COUNT(DISTINCT ProductSerial)  ";
                    break;

                case "SumProductCount":
                    OccupiedCapacityQueryText = " SUM(ProductCount)  ";
                    break;

                case "SumProductWeight":
                    OccupiedCapacityQueryText = " SUM(ProductWeight)  ";
                    break;

                case "SumProductVolume":
                    OccupiedCapacityQueryText = " SUM(ProductVolume) ";
                    break;
            }


            string commandGetLocationOccupiedCapacity = @" 
                SELECT Coalesce(" + OccupiedCapacityQueryText + ",0)    FROM tbl_Tags WHERE (TagZone = @ZoneCode   )";

            int RemainLocationCapacity = -1;
            var dtLocationOccupiedCapacity = dataAccess.SqlDataAdapter(commandGetLocationOccupiedCapacity, new KeyValuePair<string, object>("ZoneCode", locationCode));
            if (dtLocationOccupiedCapacity.Rows.Count > 0)
            {
                  RemainLocationCapacity = Convert.ToInt32(LocationCapacity) - Convert.ToInt32(dtLocationOccupiedCapacity.Rows[0][0].ToString());
            }

            if (RemainLocationCapacity >= 0)
                return "مجاز";

            else
                return "غیرمجاز به علت  " + RemainLocationCapacity.ToString() + "کیلو وزن بیشتر از ظرفیت";
        }
        else
            return "غیرمجاز ";

    }

