    public bool SSaveInventory(int header, string store, string deviceId, string[] data)
    {
        var childrenCommands = new List<KeyValuePair<string, KeyValuePair<string, object>[]>>();
        var checkInvHeader = " SELECT Count(*) FROM tbl_InventoryHeader WHERE fld_InventoryHeaderId = " + header;
        var check = (int)dataAccess
            .SqlDataAdapter(checkInvHeader).Select()[0].ItemArray[0] > 0;
        if (!check)
        {
            var invHeader = @"
SET IDENTITY_INSERT tbl_InventoryHeader ON;  
INSERT INTO tbl_InventoryHeader
                         (fld_InventoryHeaderId, fld_InventoryDate, fld_InventoryTime, fld_InventoryUserId)
VALUES        (@HeaderId,@Date,@Time,@UserId)
SET IDENTITY_INSERT tbl_InventoryHeader OFF; ";
            var parameters = new List<KeyValuePair<string, object>>();
            parameters.Add(new("HeaderId", header));
            parameters.Add(new("Date", PersianCalendarTools.GregorianToPersian(DateTime.Now)));
            parameters.Add(new("UserId", deviceId));
            parameters.Add(new("Time", DateTime.Now.Hour + ":" + DateTime.Now.Minute));
            childrenCommands.Add(new(invHeader, parameters.ToArray()));
        }
        var headerEpcsCmd = " SELECT fld_InventoryTagEPC FROM tbl_InventoryTags WHERE fld_InventoryHeaderId = " + header;
        var headerEpcs = dataAccess
            .SqlDataAdapter(headerEpcsCmd).Select().Select(p => p.ItemArray[0].ToString()).ToArray();
        foreach (string item in data)
        {
            if (headerEpcs.Contains(item))
                continue;
            var insertCmd = @" INSERT INTO tbl_InventoryTags (fld_InventoryHeaderId,fld_InventoryTagEPC, fld_InventoryStoreCode, fld_InventoryDate, fld_InventoryDateTime, fld_InventoryUser, fld_InventoryDeviceIp, fld_InventoryDeviceId)
VALUES        (@HeaderId,@EPC,@StoreCode,@Date,GetDate(),@User,N'',@DeviceId)";
            var parameters = new List<KeyValuePair<string, object>>();
            parameters.Add(new("HeaderId", header));
            parameters.Add(new("EPC", item));
            parameters.Add(new("StoreCode", store));
            parameters.Add(new("Date", PersianCalendarTools.GregorianToPersian(DateTime.Now)));
            parameters.Add(new("User", deviceId));
            parameters.Add(new("DeviceId", deviceId));
            childrenCommands.Add(new(insertCmd, parameters.ToArray()));
        }
        return dataAccess.CmdSqlExecuteNonQueryWithTransaction(childrenCommands) == 1;
    }

    public int SPSavePlacementOrders(
     string userToken,
     string productCode,
     string productLine,
     string productShift,
     string packCount,
     string storeCode,
     List<string> zoneList,
     string pOCode,
     int truck,
     string fromZoneCode = "0",
     string type = "1")
    {
        if (pOCode.Equals("-1"))
        {
            pOCode = SGetMaxPOCode();
        }

        int AllPackCount = Convert.ToInt32(packCount);

        int POPackCount = 0;

        var childrenCommands = new List<KeyValuePair<string, KeyValuePair<string, object>[]>>();

        DateTime PODateTime = DateTime.Now;

        foreach (string ZoneCode in zoneList)
        {
            if (AllPackCount > 0)
            {
                int ZoneCapacity = SGetRemainZoneCapacity(storeCode, ZoneCode.Trim());

                if ((AllPackCount - ZoneCapacity) > 0)
                {
                    POPackCount = ZoneCapacity;
                }
                else
                {
                    POPackCount = AllPackCount;
                }

                string commandPlacementOrders = @"INSERT INTO              tbl_PlacementOrders
                                                        (fld_POCode, fld_POUser, fld_PODateTime,
                                                        fld_POProductCode, fld_POType, fld_POPackCount,
                                                        fld_POStatus, fld_POZoneCode, fld_POPackCountRemain,
                                                        fld_POProductLine, fld_POProductShift, fld_POStoreCode,fld_POFromZoneCode)
                                                        VALUES       
                                                        (@POCode,@POUser,@PODateTime,@POProductCode,
                                                        @POType,@POPackCount, '1',@POZoneCode,@POPackCount,
                                                        @POProductLine,@POProductShift,@POStoreCode,@POFromZoneCode)";

                List<KeyValuePair<string, object>> parameters = new();

                parameters.Add(new("POCode", pOCode));
                parameters.Add(new("POUser", userToken));
                parameters.Add(new("POProductCode", productCode));
                parameters.Add(new("PODateTime", PODateTime));
                parameters.Add(new("POType", type));
                parameters.Add(new("POPackCount", POPackCount));
                parameters.Add(new("POZoneCode", ZoneCode.Trim()));
                parameters.Add(new("POProductLine", productLine));
                parameters.Add(new("POProductShift", productShift));
                parameters.Add(new("POStoreCode", storeCode));
                parameters.Add(new("POFromZoneCode", fromZoneCode));

                childrenCommands.Add(new(commandPlacementOrders, parameters.ToArray()));

                AllPackCount = AllPackCount - POPackCount;
            }
            else
                break;
        }

        if (dataAccess.CmdSqlExecuteNonQueryWithTransaction(childrenCommands) > 0)
        {
            if (type.Equals("2"))
            {
                bool saveMissionResult = SSavePlacementMissionsByCount(userToken, productCode, "", "", "2", truck.ToString(), fromZoneCode,
                      zoneList.First(), storeCode, int.Parse(packCount), pOCode);

                if (!saveMissionResult)
                {
                    return -1;
                }
            }

            return int.Parse(pOCode);
        }
        else
        {
            return -1;
        }
    }

    public bool SSavePlaceOrdersBySerialsCount(
    List<string> serials,
    string destWarehouse,
    string destZone,
    string pOCode,
    int truck,
    string type,
    string userToken)
    {
        if (string.IsNullOrEmpty(type))
        {
            type = "1";
        }

        if (pOCode.Equals("-1"))
        {
            pOCode = SGetMaxPOCode();
        }

        string serialStr = serials.Aggregate(string.Empty
         , (first, next) => first + (string.IsNullOrEmpty(next) ? string.Empty : (",N'" + next + "'"))).Remove(0, 1);

        var tagsRows = dataAccess.SqlDataAdapter($"SELECT ProductSerial, ProductCode, ProductCount, TagZone, TagInDestinationId, fld_ProductPropertyAId, fld_ProductPropertyBId,TagEpc FROM tbl_Tags WHERE ProductSerial IN ({serialStr})")
                              .Select();

        var childrenCommands = new List<KeyValuePair<string, KeyValuePair<string, object>[]>>();

        DateTime nowDateTime = DateTime.Now;


        foreach (DataRow row in tagsRows)
        {
            string serial = row.ItemArray[0].ToString();

            string code = row.ItemArray[1].ToString();

            decimal count = (decimal)row.ItemArray[2];

            string zone = row.ItemArray[3].ToString();

            string fromWarehouse = row.ItemArray[4].ToString();

            string line = row.ItemArray[5].ToString();

            string shift = row.ItemArray[6].ToString();

            string epc = row.ItemArray[7].ToString();

            string commandPlacementOrders = @"INSERT        
                                                        INTO              tbl_PlacementOrders
                                                        (fld_POCode, fld_POUser, fld_PODateTime,
                                                        fld_POProductCode, fld_POType, fld_POPackCount,
                                                        fld_POStatus, fld_POZoneCode, fld_POPackCountRemain,
                                                        fld_POProductLine, fld_POProductShift, fld_POStoreCode,fld_POFromZoneCode)
                                                        VALUES       
                                                        (@POCode,@POUser,@PODateTime,@POProductCode,
                                                        @POType,@POPackCount, '1',@POZoneCode,@POPackCount,
                                                        @POProductLine,@POProductShift,@POStoreCode,@POFromZoneCode)";

            List<KeyValuePair<string, object>> parameters = new();

            parameters.Add(new("POCode", pOCode));
            parameters.Add(new("POUser", userToken));
            parameters.Add(new("POProductCode", code));
            parameters.Add(new("PODateTime", nowDateTime));
            parameters.Add(new("POType", type));
            parameters.Add(new("POPackCount", count));
            parameters.Add(new("POZoneCode", destZone));
            parameters.Add(new("POProductLine", line));
            parameters.Add(new("POProductShift", shift));
            parameters.Add(new("POStoreCode", destWarehouse));
            parameters.Add(new("POFromZoneCode", zone));

            childrenCommands.Add(new(commandPlacementOrders, parameters.ToArray()));

            string cmd = @" INSERT INTO tbl_ProductPlacementMissions
                                    (fld_PPMUserId, fld_PPMRegDateTime, fld_PPMProductCode, fld_PPMProductSerial, fld_PPMProductEPC, fld_PPMType, fld_PPMWMCode, fld_PPMWMDriverUserId, fld_PPMFromZoneId, fld_PPMToZoneId, fld_PPMStoreCode,
                                    fld_PPMStatus, fld_PPMToZoneId_Edited,fld_PPMActionId )
                                    VALUES
                                    (@PPMUserId, @PPMRegDateTime, @PPMProductCode, @PPMProductSerial,
                                    @PPMProductEPC, @PPMType, @PPMWMCode, @PPMWMDriverUserId, @PPMFromZoneId,
                                    @PPMToZoneId, @PPMStoreCode, @PPMStatus, @PPMToZoneId_Edited,@fld_PPMActionId ) ";

            List<KeyValuePair<string, object>> placeParameters = new();

            placeParameters.Add(new("PPMUserId", userToken));
            placeParameters.Add(new("PPMRegDateTime", DateTime.Now));
            placeParameters.Add(new("PPMProductCode", code));
            placeParameters.Add(new("PPMProductSerial", serial));
            placeParameters.Add(new("PPMProductEPC", epc));
            placeParameters.Add(new("PPMType", type));
            placeParameters.Add(new("PPMWMCode", truck));
            placeParameters.Add(new("PPMWMDriverUserId", "0"));
            placeParameters.Add(new("PPMFromZoneId", zone));
            placeParameters.Add(new("PPMToZoneId", destZone));
            placeParameters.Add(new("PPMStoreCode", destWarehouse));
            placeParameters.Add(new("PPMStatus", 0));
            placeParameters.Add(new("PPMToZoneId_Edited", "0"));
            placeParameters.Add(new("fld_PPMActionId", pOCode));

            childrenCommands.Add(new(cmd, placeParameters.ToArray()));
        }

        return dataAccess.CmdSqlExecuteNonQueryWithTransaction(childrenCommands) == 1;
    }

    public int SPSavePlacementOrdersBySerials(
    string userToken,
    string productCode,
    string productLine,
    string productShift,
    string packCount,
    string storeCode,
    List<string> zoneList,
    string pOCode,
    int truck,
    string fromZoneCode,
    string type,
    string[] serials = null)
    {
        if (string.IsNullOrEmpty(fromZoneCode))
        {
            fromZoneCode = "0";
        }

        if (string.IsNullOrEmpty(type))
        {
            type = "1";
        }

        if (pOCode.Equals("-1"))
        {
            pOCode = SGetMaxPOCode();
        }

        int AllPackCount = Convert.ToInt32(packCount);
        int POPackCount = 0;
        var childrenCommands = new List<KeyValuePair<string, KeyValuePair<string, object>[]>>();
        DateTime PODateTime = DateTime.Now;
        foreach (string ZoneCode in zoneList)
        {
            if (AllPackCount > 0)
            {
                int ZoneCapacity = SGetRemainZoneCapacity(storeCode, ZoneCode);
                if ((AllPackCount - ZoneCapacity) > 0)
                {
                    POPackCount = ZoneCapacity;
                }
                else
                {
                    POPackCount = AllPackCount;
                }

                var commandPlacementOrders = @"INSERT        
                                                        INTO              tbl_PlacementOrders
                                                        (fld_POCode, fld_POUser, fld_PODateTime,
                                                        fld_POProductCode, fld_POType, fld_POPackCount,
                                                        fld_POStatus, fld_POZoneCode, fld_POPackCountRemain,
                                                        fld_POProductLine, fld_POProductShift, fld_POStoreCode,fld_POFromZoneCode)
                                                        VALUES       
                                                        (@POCode,@POUser,@PODateTime,@POProductCode,
                                                        @POType,@POPackCount, '1',@POZoneCode,@POPackCount,
                                                        @POProductLine,@POProductShift,@POStoreCode,@POFromZoneCode)";
                var parameters = new List<KeyValuePair<string, object>>();

                parameters.Add(new("POCode", pOCode));
                parameters.Add(new("POUser", userToken));
                parameters.Add(new("POProductCode", productCode));
                parameters.Add(new("PODateTime", PODateTime));
                parameters.Add(new("POType", type));
                parameters.Add(new("POPackCount", POPackCount));
                parameters.Add(new("POZoneCode", ZoneCode));
                parameters.Add(new("POProductLine", productLine));
                parameters.Add(new("POProductShift", productShift));
                parameters.Add(new("POStoreCode", storeCode));
                parameters.Add(new("POFromZoneCode", fromZoneCode));
                childrenCommands.Add(new(commandPlacementOrders, parameters.ToArray()));

                AllPackCount = AllPackCount - POPackCount;
            }
            else
                break;
        }
        if (dataAccess.CmdSqlExecuteNonQueryWithTransaction(childrenCommands) > 0)
        {
            if (serials is null)
            {

                if (type.Equals("2") || type.Equals("3"))
                {
                    var saveMissionResult = SSavePlacementMissionsByCount(userToken, productCode, "", "", type, truck.ToString(), fromZoneCode,
                          zoneList.First(), storeCode, int.Parse(packCount), pOCode);

                    if (!saveMissionResult)
                        return -1;
                }
            }
            else
            {
                if (type.Equals("3"))
                {
                    foreach (string serial in serials)
                    {
                        var saveMissionResult = SSavePlacementMissionsByCount(userToken, productCode, serial, "", type, truck.ToString(), fromZoneCode,
                          zoneList.First(), storeCode, int.Parse(packCount), pOCode);

                        if (!saveMissionResult)
                            return -1;
                    }
                }
            }

            return int.Parse(pOCode);
        }
        else
            return -1;
    }

    public int SPSavePlacementOrdersBySerialsFromCollect(SavePlacementOrderCollectCommand order)
    {
        if (string.IsNullOrEmpty(order.FromZoneCode))
        {
            order.FromZoneCode = "0";
        }

        var userToken = httpContext.User.GetUserId();

        int failedResults = 0;

        string pOParent = SGetMaxPOOperationCode();

        string currentpOCode = string.Empty;

        foreach (var plan in order.CollectPlans)
        {
            order.POCode = SGetMaxPOCode();

            decimal AllPackCount = Convert.ToDecimal(plan.PackCount);
            decimal POPackCount = 0;
            var childrenCommands = new List<KeyValuePair<string, KeyValuePair<string, object>[]>>();
            DateTime PODateTime = DateTime.Now;

            if (order.Type.Equals("3"))
            {
                var commandPlacementOrders = @"INSERT        
                                                        INTO              tbl_PlacementOrders
                                                        (fld_POCode, fld_POUser, fld_PODateTime,
                                                        fld_POProductCode, fld_POType, fld_POPackCount,
                                                        fld_POStatus, fld_POZoneCode, fld_POPackCountRemain,
                                                        fld_POProductLine, fld_POProductShift, fld_POStoreCode,fld_POFromZoneCode,
                                                        fld_PODocumentKey,fld_PODocumentType,fld_POParent,fld_POSumValue,fld_POPackCountDescription)
                                                        VALUES       
                                                        (@POCode,@POUser,@PODateTime,@POProductCode,
                                                        @POType,@POPackCount, '1',@POZoneCode,@POPackCount,
                                                        @POProductLine,@POProductShift,@POStoreCode,@POFromZoneCode,
                                                        @PODocumentKey,@PODocumentType,@POParent,@POSumValue,@PackCountDescription)";
                var parameters = new List<KeyValuePair<string, object>>();

                parameters.Add(new("POCode", order.POCode));
                parameters.Add(new("POUser", userToken));
                parameters.Add(new("POProductCode", plan.ProductCode));
                parameters.Add(new("PODateTime", PODateTime));
                parameters.Add(new("POType", order.Type));
                parameters.Add(new("POPackCount", AllPackCount));
                parameters.Add(new("POZoneCode", "0"));
                parameters.Add(new("POProductLine", order.ProductLine));
                parameters.Add(new("POProductShift", order.ProductShift));
                parameters.Add(new("POStoreCode", order.StoreCode));
                parameters.Add(new("POFromZoneCode", plan.FromZoneCode));
                parameters.Add(new("PODocumentKey", order.DocumentKey));
                parameters.Add(new("PODocumentType", order.DocumentType));
                parameters.Add(new("POParent", pOParent));
                parameters.Add(new("POSumValue", plan.SumValue));
                parameters.Add(new("PackCountDescription", plan.PackCountDescription));
                childrenCommands.Add(new(commandPlacementOrders, parameters.ToArray()));
            }
            else
            {
                foreach (string ZoneCode in plan.ZoneList)
                {
                    if (AllPackCount > 0)
                    {
                        if (order.Type.Equals("3"))
                        {
                            POPackCount = AllPackCount;
                        }
                        else
                        {
                            int remain = SGetRemainZoneCapacity(order.StoreCode, ZoneCode);
                            decimal ZoneCapacity = Convert.ToDecimal(remain);

                            if ((AllPackCount - ZoneCapacity) > 0)
                            {
                                POPackCount = ZoneCapacity;
                            }
                            else
                            {
                                POPackCount = AllPackCount;
                            }
                        }


                        var commandPlacementOrders = @"INSERT        
                                                        INTO              tbl_PlacementOrders
                                                        (fld_POCode, fld_POUser, fld_PODateTime,
                                                        fld_POProductCode, fld_POType, fld_POPackCount,
                                                        fld_POStatus, fld_POZoneCode, fld_POPackCountRemain,
                                                        fld_POProductLine, fld_POProductShift, fld_POStoreCode,fld_POFromZoneCode,
                                                        fld_PODocumentKey,fld_PODocumentType,fld_POParent,fld_POSumValue)
                                                        VALUES       
                                                        (@POCode,@POUser,@PODateTime,@POProductCode,
                                                        @POType,@POPackCount, '1',@POZoneCode,@POPackCount,
                                                        @POProductLine,@POProductShift,@POStoreCode,@POFromZoneCode,
                                                        @PODocumentKey,@PODocumentType,@POParent,@POSumValue)";
                        var parameters = new List<KeyValuePair<string, object>>();

                        parameters.Add(new("POCode", order.POCode));
                        parameters.Add(new("POUser", userToken));
                        parameters.Add(new("POProductCode", plan.ProductCode));
                        parameters.Add(new("PODateTime", PODateTime));
                        parameters.Add(new("POType", order.Type));
                        parameters.Add(new("POPackCount", POPackCount));
                        parameters.Add(new("POZoneCode", ZoneCode));
                        parameters.Add(new("POProductLine", order.ProductLine));
                        parameters.Add(new("POProductShift", order.ProductShift));
                        parameters.Add(new("POStoreCode", order.StoreCode));
                        parameters.Add(new("POFromZoneCode", order.FromZoneCode));
                        parameters.Add(new("PODocumentKey", order.DocumentKey));
                        parameters.Add(new("PODocumentType", order.DocumentType));
                        parameters.Add(new("POParent", pOParent));
                        parameters.Add(new("POSumValue", plan.SumValue));
                        childrenCommands.Add(new(commandPlacementOrders, parameters.ToArray()));

                        AllPackCount = AllPackCount - POPackCount;
                    }
                    else
                        break;
                }
            }


            if (dataAccess.CmdSqlExecuteNonQueryWithTransaction(childrenCommands) > 0)
            {
                if (plan.Serials is null)
                {

                    if (order.Type.Equals("2") || order.Type.Equals("3"))
                    {
                        var saveMissionResult = SSavePlacementMissionsByCount(userToken, plan.ProductCode, "", "", order.Type, plan.Truck.ToString(),
                            order.FromZoneCode, plan.ZoneList.First(), order.StoreCode, int.Parse(plan.PackCount), order.POCode);
                    }
                }
                else
                {
                    if (order.Type.Equals("3"))
                    {
                        foreach (string serial in plan.Serials)
                        {
                            var saveMissionResult = SSavePlacementMissionsByCount(userToken, plan.ProductCode, serial, "", order.Type, plan.Truck.ToString(),
                                order.FromZoneCode, plan.ZoneList.First(), order.StoreCode, int.Parse(plan.PackCount), order.POCode);
                        }
                    }
                }
            }
            else
            {
                failedResults++;
            }
        }

        if (failedResults > 0)
        {
            return -1;
        }
        else
        {
            return 1;
        }
    }

    public DataTable SPositionSearch(PositionSearchRequest search)
    {
        var whereString = string.Empty;
        if (!search.ProductCode.Equals("-1"))
        {
            whereString += " AND ";
            whereString += $" ProductCode = N'{search.ProductCode}'";
        }
        if (!search.ZoneCode.Equals("-1"))
        {
            whereString += " AND ";
            whereString += $" TagZone = N'{search.ZoneCode}'";
        }
        var cmd = @$"SELECT   DISTINCT     TagZone as ZoneCode,
ProductCode, Coalesce(RegCode,N'') as TechnicalCode, 
ProductStatus as Quality, COUNT(ProductSerial) AS [Count], 
SUM(ProductCount) AS [SumCount], MIN(TagRegisterShamsiUnixDate) AS [FirstDate],
MAX(TagRegisterShamsiUnixDate) as [LastDate]
                FROM            tbl_Tags
                WHERE        (TagZone IS NOT NULL AND TagZone != '0') {whereString}
                GROUP BY TagZone, ProductCode, RegCode, ProductStatus ";
        return dataAccess.SqlDataAdapter(cmd, 120);
    }
    public DataTable SGetProductDetails(string code, string zone, string desticationCode)
    {
        var whereString = string.Empty;

        if (!code.Equals("-1"))
            whereString += $" AND ProductCode = N'{code}'";

        if (!zone.Equals("-1"))
            whereString += $" AND TagZone = N'{zone}'";

        if (!desticationCode.Equals("-1"))
            whereString += $" AND TagInDestinationId = N'{desticationCode}'";

        var cmd = @$"SELECT   TagInDestinationId AS [WarehouseCode],    SUBSTRING(TagRegisterShamsiUnixDate,0,5)+'/'+SUBSTRING(TagRegisterShamsiUnixDate,5,2)+'/'+SUBSTRING(TagRegisterShamsiUnixDate,7,2)
                  AS [EnterDate], COUNT(ProductSerial) AS [Count], SUM(ProductCount) AS [SumCount]
                  FROM            tbl_Tags
                  WHERE        (TagZone IS NOT NULL) {whereString}
                  GROUP BY TagInDestinationId, TagZone, ProductCode,  
                  SUBSTRING(TagRegisterShamsiUnixDate,0,5)+'/'+SUBSTRING(TagRegisterShamsiUnixDate,5,2)+'/'+
                  SUBSTRING(TagRegisterShamsiUnixDate,7,2) ORDER BY [EnterDate] ";
        return dataAccess.SqlDataAdapter(cmd);
    }

    public DataTable SGetCapacityByProductCode(string productCode, string from, string destination)
    {
        var cmd = @" SELECT        (SELECT        COUNT(DISTINCT ProductSerial) AS Expr1
                          FROM            tbl_Tags AS tbl_Tags_1
                          WHERE        (ProductCode = tbl_Tags.ProductCode) AND (TagZone = @FromZone) AND (TagStatus = 1)) AS CountInFromZone,
                             (SELECT        COUNT(DISTINCT ProductSerial) AS Expr1
                               FROM            tbl_Tags AS tbl_Tags_2
                               WHERE        (ProductCode = tbl_Tags.ProductCode) AND (TagZone = @ToZone) AND (TagStatus = 1)) AS CountInToZone
FROM            tbl_Tags
WHERE        (ProductCode = @PCode) AND (TagStatus = 1) ";

        return dataAccess.SqlDataAdapter(cmd
            , new KeyValuePair<string, object>("PCode", productCode)
            , new KeyValuePair<string, object>("FromZone", from)
            , new KeyValuePair<string, object>("ToZone", destination)
            );
    }

    public DataTable SRepSummaryRegister(string ShamsiUnixFromDate, string ShamsiUnixDateToFrom, string TypeTimeFilter)
    {
        if (ShamsiUnixFromDate.Contains("/"))
        {
            ShamsiUnixFromDate = ShamsiUnixFromDate.Replace("/", "");

            ShamsiUnixFromDate = ShamsiUnixFromDate.PadRight(14, '0');
        }

        if (ShamsiUnixDateToFrom.Contains("/"))
        {
            ShamsiUnixDateToFrom = ShamsiUnixDateToFrom.Replace("/", "");

            ShamsiUnixDateToFrom = ShamsiUnixDateToFrom.PadRight(14, '0');
        }

        var whereString = string.Empty;

        DataTable dtResult = new();

        dtResult.Columns.Add("CountProductSerial", typeof(string));
        dtResult.Columns.Add("SumProductCount", typeof(string));
        dtResult.Columns.Add("CountPropertyAId", typeof(string));
        dtResult.Columns.Add("CountProductType", typeof(string));
        dtResult.Columns.Add("CountProudctSize", typeof(string));
        dtResult.Columns.Add("SumProductCountProductStatusDCG", typeof(string));
        dtResult.Columns.Add("MaxRegister", typeof(string));
        dtResult.Columns.Add("AVGRegister", typeof(string));

        var cmd = @$"SELECT COALESCE(COUNT(tbl_Tags.ProductSerial),0) AS CountProductSerial, 
                            COALESCE(SUM(tbl_Tags.ProductCount),0) AS SumProductCount, 
                            COALESCE(COUNT(DISTINCT tbl_Tags.fld_ProductPropertyAId),0) AS CountPropertyAId, 
                            COALESCE(COUNT(DISTINCT tbl_Tags.ProductType),0) AS CountProductType, 
                            COALESCE(COUNT(DISTINCT tbl_Products.ProductSize),0) AS CountProudctSize,
                             (SELECT        COALESCE(SUM(ProductCount),0) AS Expr1
                               FROM            tbl_Tags AS tbl_Tags_1
                               WHERE        (TagRegisterShamsiUnixDate >= '{ShamsiUnixFromDate}') AND (TagRegisterShamsiUnixDate < '{ShamsiUnixDateToFrom}') AND (ProductStatus IN ('D', 'CG'))) AS SumProductCountProductStatusDCG
                    FROM            tbl_Tags LEFT OUTER JOIN
                                             tbl_Products ON tbl_Tags.ProductCode = tbl_Products.ProductCode
                    WHERE        (tbl_Tags.TagRegisterShamsiUnixDate >= '{ShamsiUnixFromDate}') AND  (tbl_Tags.TagRegisterShamsiUnixDate < '{ShamsiUnixDateToFrom}')";

        DataTable _dtMain = dataAccess.SqlDataAdapter(cmd);

        if (_dtMain.Rows.Count > 0)
        {
            string GroupByCommandMaxRegister = "";

            switch (TypeTimeFilter)
            {
                case "1"://daily
                    GroupByCommandMaxRegister = " GROUP BY SUBSTRING(TagRegisterShamsiUnixDate, 0, 9)";
                    break;
                case "2"://monthly
                    GroupByCommandMaxRegister = "GROUP BY SUBSTRING(TagRegisterShamsiUnixDate, 0, 7)";
                    break;
                case "3"://Yearly
                    GroupByCommandMaxRegister = "GROUP BY SUBSTRING(TagRegisterShamsiUnixDate, 0, 5)";
                    break;
                case "4"://Weekly
                    GroupByCommandMaxRegister = " GROUP BY SUBSTRING(TagRegisterShamsiUnixDate, 0, 9)";
                    break;
                case "5"://Seasonly
                    GroupByCommandMaxRegister = " GROUP BY SUBSTRING(TagRegisterShamsiUnixDate, 0, 9)";
                    break;

            }

            var commandMaxRegister = @$" SELECT TOP(1) COALESCE(SUM(ProductCount),0) AS MaxRegister
                                    FROM tbl_Tags
                                    WHERE(fld_ProductPropertyAId > 0)
                                   {GroupByCommandMaxRegister}
                                    ORDER BY MaxRegister DESC ";

            var MaxRegister = dataAccess.SqlDataReaders(commandMaxRegister)[0].Value.ToString();

            var commandAVGRegister = @"SELECT        COALESCE(CAST(SUM(ProductCount) / COUNT(DISTINCT SUBSTRING(TagRegisterShamsiUnixDate, 0, 9)) AS decimal(18, 2)),0) AS AVGRegister
                                    FROM            tbl_Tags
                                    WHERE(fld_ProductPropertyAId > 0) AND(fld_ProductPropertyBId > 0) ";

            var AVGRegister = dataAccess.SqlDataReaders(commandAVGRegister)[0].Value.ToString();

            string[] RowData ={ _dtMain.Rows[0]["CountProductSerial"].ToString(),
                _dtMain.Rows[0]["SumProductCount"].ToString(),
                _dtMain.Rows[0]["CountPropertyAId"].ToString(),
                _dtMain.Rows[0]["CountProductType"].ToString(),
                _dtMain.Rows[0]["CountProudctSize"].ToString(),
                _dtMain.Rows[0]["SumProductCountProductStatusDCG"].ToString(),MaxRegister.ToString(),AVGRegister.ToString() };

            dtResult.Rows.Add(RowData);
        }

        return dtResult;
    }


    public List<RegisterStats> SGetDailyRegisterStats()
    {
        var today = PersianCalendarTools.GregorianToPersian(DateTime.Now);
        var data = new List<RegisterStats>();
        var cmd = @"SELECT fld_Id,dbo.GeorgianDateToJalaliDate(fld_SaveDate) ,fld_SaveUser, fld_Data
                                       FROM tbl_Item where dbo.GeorgianDateToJalaliDate(fld_SaveDate) = @Date";
        var dt = dataAccess.SqlDataAdapter(cmd,
            new KeyValuePair<string, object>("Date", today)).Select().ToList();
        foreach (DataRow row in dt)
            data.Add(JsonConvert.DeserializeObject<RegisterStats>(row.ItemArray[3].ToString()));
        return data;
    }

    public List<ExitStats> SGetDailyExitStats()
    {
        var today = PersianCalendarTools.GregorianToPersian(DateTime.Now);

        List<ExitStats> data = new();

        var cmd = @"SELECT  fld_Data
                    FROM    tbl_Item where CAST(CAST(fld_SaveDate as date) as datetime) = @Date";

        var dt = dataAccess.SqlDataAdapter(cmd
            , new KeyValuePair<string, object>("Date", DateTime.Now)).Select().ToList();

        foreach (DataRow row in dt)
        {
            data.Add(JsonConvert.DeserializeObject<ExitStats>(row.ItemArray[0].ToString()));
        }

        return data;
    }
