    public DataTable SReportHMovementOnProductType(IndexSearch search)
    {
        logger.LogInformation("SReportHMovementOnProductType" + Environment.NewLine
                            + "FromDate" + search.FromDate + Environment.NewLine
                            + "ToDate" + search.ToDate + Environment.NewLine
                            + "Pl" + search.Pl + Environment.NewLine
                            + "Shift" + search.Shift + Environment.NewLine
                            + "Regcode" + search.Regcode);

        var whereString = SGetWhereStringSearchIndex(search);

        if (!string.IsNullOrEmpty(whereString))
        {
            whereString = (" WHERE " + whereString);
        }

        var cmdData = $@"SELECT        tbl_Products.ProductType, SUM(tbl_TagsMovement.ProductCount) AS SumValue
FROM            tbl_TagsMovement LEFT OUTER JOIN
                         tbl_Products ON tbl_TagsMovement.ProductCode = tbl_Products.ProductCode RIGHT OUTER JOIN
                         tbl_MovementActions ON tbl_TagsMovement.HMovementActionId = tbl_MovementActions.MovementActionId
WHERE        (tbl_MovementActions.MovementActionTp = 6) AND (tbl_MovementActions.MovementActionDateTime >= '{search.FromDate}') AND (tbl_MovementActions.MovementActionDateTime < '{search.ToDate}') AND 
                         (tbl_MovementActions.MovementActionData NOT LIKE N'%برگشت کالا%') AND (tbl_Products.ProductType IS NOT NULL)
GROUP BY tbl_Products.ProductType";
        var mainData = dataAccess.SqlDataAdapter(cmdData);

        if (mainData.Select().Any())
        {
            return mainData;
        }

        return dataAccess.SqlDataAdapter(@" SELECT N'نامشخص' as ProductType,  0 AS SumValue ");
    }
