    public DataTable SReportHMovementOnAgeAnalyse(IndexSearch search)
    {
        logger.LogInformation("SReportHMovementOnAgeAnalyse" + Environment.NewLine
                            + "FromDate" + search.FromDate + Environment.NewLine
                            + "ToDate" + search.ToDate + Environment.NewLine
                            + "Pl" + search.Pl + Environment.NewLine
                            + "Shift" + search.Shift + Environment.NewLine
                            + "Regcode" + search.Regcode);

        var whereString = SGetWhereStringSearchIndex(search);

        if (!string.IsNullOrEmpty(whereString))
        {
            whereString = (" WHERE " + whereString);
        }

        var cmdData = $@"SELECT        N'کمتر از یک ماه' AS AgeTitle, COUNT(tbl_Tags.ProductSerial) AS CountSerial, SUM(tbl_Tags.ProductCount) AS SumValue 
FROM            tbl_Tags RIGHT OUTER JOIN                          tbl_TagsMovement ON tbl_Tags.ProductSerial = tbl_TagsMovement.ProductSerial RIGHT OUTER JOIN                          tbl_MovementActions ON tbl_TagsMovement.HMovementActionId = tbl_MovementActions.MovementActionId
WHERE         (CAST(dbo.JalaliDateToGeorgianDate(SUBSTRING(tbl_Tags.TagRegisterShamsiUnixDate, 0, 5) + '/' + SUBSTRING(tbl_Tags.TagRegisterShamsiUnixDate, 5, 2) 
                         + '/' + SUBSTRING(tbl_Tags.TagRegisterShamsiUnixDate, 7, 2), SUBSTRING(tbl_Tags.TagRegisterShamsiUnixDate, 9, 2) + ':' + SUBSTRING(tbl_Tags.TagRegisterShamsiUnixDate, 11, 2)) AS datetime) 
						 < GETDATE())  and (CAST(dbo.JalaliDateToGeorgianDate(SUBSTRING(tbl_Tags.TagRegisterShamsiUnixDate, 0, 5) + '/' + SUBSTRING(tbl_Tags.TagRegisterShamsiUnixDate, 5, 2) 
                         + '/' + SUBSTRING(tbl_Tags.TagRegisterShamsiUnixDate, 7, 2), SUBSTRING(tbl_Tags.TagRegisterShamsiUnixDate, 9, 2) + ':' + SUBSTRING(tbl_Tags.TagRegisterShamsiUnixDate, 11, 2)) AS datetime) 
						 >= DATEADD(month,-1,GETDATE())) AND (tbl_MovementActions.MovementActionTp = 6) 
                         AND (tbl_MovementActions.MovementActionData NOT LIKE N'%برگشت کالا%') AND (tbl_MovementActions.MovementActionDateTime >= '{search.FromDate}') AND (tbl_MovementActions.MovementActionDateTime < '{search.ToDate}')

						 union
						 SELECT        N'یک تا سه ماه' AS AgeTitle, COUNT(tbl_Tags.ProductSerial) AS CountSerial, SUM(tbl_Tags.ProductCount) AS SumValue 
FROM            tbl_Tags RIGHT OUTER JOIN                          tbl_TagsMovement ON tbl_Tags.ProductSerial = tbl_TagsMovement.ProductSerial RIGHT OUTER JOIN                          tbl_MovementActions ON tbl_TagsMovement.HMovementActionId = tbl_MovementActions.MovementActionId
WHERE         (CAST(dbo.JalaliDateToGeorgianDate(SUBSTRING(tbl_Tags.TagRegisterShamsiUnixDate, 0, 5) + '/' + SUBSTRING(tbl_Tags.TagRegisterShamsiUnixDate, 5, 2) 
                         + '/' + SUBSTRING(tbl_Tags.TagRegisterShamsiUnixDate, 7, 2), SUBSTRING(tbl_Tags.TagRegisterShamsiUnixDate, 9, 2) + ':' + SUBSTRING(tbl_Tags.TagRegisterShamsiUnixDate, 11, 2)) AS datetime) 
						 < DATEADD(month,-1,GETDATE()))  and (CAST(dbo.JalaliDateToGeorgianDate(SUBSTRING(tbl_Tags.TagRegisterShamsiUnixDate, 0, 5) + '/' + SUBSTRING(tbl_Tags.TagRegisterShamsiUnixDate, 5, 2) 
                         + '/' + SUBSTRING(tbl_Tags.TagRegisterShamsiUnixDate, 7, 2), SUBSTRING(tbl_Tags.TagRegisterShamsiUnixDate, 9, 2) + ':' + SUBSTRING(tbl_Tags.TagRegisterShamsiUnixDate, 11, 2)) AS datetime) 
						 >= DATEADD(month,-3,GETDATE())) AND (tbl_MovementActions.MovementActionTp = 6) 
                         AND (tbl_MovementActions.MovementActionData NOT LIKE N'%برگشت کالا%') AND (tbl_MovementActions.MovementActionDateTime >= '{search.FromDate}') AND (tbl_MovementActions.MovementActionDateTime < '{search.ToDate}')
						 	 union
						 SELECT        N'سه تا شش ماه' AS AgeTitle, COUNT(tbl_Tags.ProductSerial) AS CountSerial, SUM(tbl_Tags.ProductCount) AS SumValue 
FROM            tbl_Tags RIGHT OUTER JOIN                          tbl_TagsMovement ON tbl_Tags.ProductSerial = tbl_TagsMovement.ProductSerial RIGHT OUTER JOIN                          tbl_MovementActions ON tbl_TagsMovement.HMovementActionId = tbl_MovementActions.MovementActionId
WHERE         (CAST(dbo.JalaliDateToGeorgianDate(SUBSTRING(tbl_Tags.TagRegisterShamsiUnixDate, 0, 5) + '/' + SUBSTRING(tbl_Tags.TagRegisterShamsiUnixDate, 5, 2) 
                         + '/' + SUBSTRING(tbl_Tags.TagRegisterShamsiUnixDate, 7, 2), SUBSTRING(tbl_Tags.TagRegisterShamsiUnixDate, 9, 2) + ':' + SUBSTRING(tbl_Tags.TagRegisterShamsiUnixDate, 11, 2)) AS datetime) 
						 < DATEADD(month,-3,GETDATE()))  and (CAST(dbo.JalaliDateToGeorgianDate(SUBSTRING(tbl_Tags.TagRegisterShamsiUnixDate, 0, 5) + '/' + SUBSTRING(tbl_Tags.TagRegisterShamsiUnixDate, 5, 2) 
                         + '/' + SUBSTRING(tbl_Tags.TagRegisterShamsiUnixDate, 7, 2), SUBSTRING(tbl_Tags.TagRegisterShamsiUnixDate, 9, 2) + ':' + SUBSTRING(tbl_Tags.TagRegisterShamsiUnixDate, 11, 2)) AS datetime) 
						 >= DATEADD(month,-6,GETDATE())) AND (tbl_MovementActions.MovementActionTp = 6) 
                         AND (tbl_MovementActions.MovementActionData NOT LIKE N'%برگشت کالا%') AND (tbl_MovementActions.MovementActionDateTime >= '{search.FromDate}') AND (tbl_MovementActions.MovementActionDateTime < '{search.ToDate}')
						  union
