WHERE            (CAST(dbo.JalaliDateToGeorgianDate(SUBSTRING(tbl_Tags.TagRegisterShamsiUnixDate, 0, 5) + '/' + SUBSTRING(tbl_Tags.TagRegisterShamsiUnixDate, 5, 2) 
                         + '/' + SUBSTRING(tbl_Tags.TagRegisterShamsiUnixDate, 7, 2), SUBSTRING(tbl_Tags.TagRegisterShamsiUnixDate, 9, 2) + ':' + SUBSTRING(tbl_Tags.TagRegisterShamsiUnixDate, 11, 2)) AS datetime) 
						 < DATEADD(month,-12,GETDATE())) AND (tbl_MovementActions.MovementActionTp = 6) 
