    }
    public DataTable SReportStoreOn10MaxProduct()
    {
        logger.LogInformation("SReportStoreOnProductType");

        var cmd = $@" SELECT        TOP (10) tbl_Tags.ProductCode, COUNT(tbl_Tags.ProductSerial) AS CountSerial, SUM(tbl_Tags.ProductCount) AS SumValue, SUM(tbl_Tags.ProductCount) * 100 /
                             (SELECT        SUM(ProductCount) AS Expr1
                               FROM            tbl_Tags AS tbl_Tags_1
                               WHERE        (TagStatus = 1)) AS [Percent], tbl_Products.ProductTitle, tbl_Products.ProductStatus, tbl_Products.ProductSize, tbl_Products.ProductTechnicalCode
FROM            tbl_Tags LEFT OUTER JOIN
                         tbl_Products ON tbl_Tags.ProductCode = tbl_Products.ProductCode
