        return dataAccess.SqlDataAdapter(@" SELECT N'نامشخص' as ProductCode, 0 AS CountSerial,0 AS SumValue,0 AS[Percent],'' as ProductTitle, '' as ProductStatus, '' as ProductSize, '' as ProductTechnicalCode");
    }
