    public DataTable SRepSummaryStoreInfo()
    {
        logger.LogInformation("SRepSummaryStoreInfo");

        var whereString = string.Empty;

        DataTable dtResult = new DataTable();
        dtResult.Columns.Add("CountProductSerial", typeof(string));
        dtResult.Columns.Add("SumProductCount", typeof(string));
        dtResult.Columns.Add("AvgDate", typeof(string));
        dtResult.Columns.Add("COUNTEmptyZone", typeof(string));
        dtResult.Columns.Add("StoreCapacity", typeof(string));

        var cmd1 = $@" SELECT COUNT(ProductSerial) AS CountProductSerial, CAST( SUM(ProductCount) as bigint) AS SumProductCount, dbo.GeorgianDateToJalaliDate(cast(avg(CAST(CAST((dbo.JalaliDateToGeorgianDate(SUBSTRING(TagRegisterShamsiUnixDate, 0, 5) + '/' + SUBSTRING(TagRegisterShamsiUnixDate, 5, 2)
                           + '/' + SUBSTRING(TagRegisterShamsiUnixDate, 7, 2), SUBSTRING(TagRegisterShamsiUnixDate, 9, 2) + ':' + SUBSTRING(TagRegisterShamsiUnixDate, 11, 2))) as datetime) as float)) as datetime)) as AvgDate
                FROM tbl_Tags
                WHERE(TagStatus = N'1')";
        var dtResultcmd1 = dataAccess.SqlDataAdapter(cmd1);


        var cmd2 = $@" SELECT COUNT(DISTINCT tbl_Zones.ZoneCode) AS COUNTEmptyZone
                FROM tbl_Zones LEFT OUTER JOIN
                              tbl_Tags ON tbl_Zones.ZoneCode = tbl_Tags.TagZone
                WHERE (tbl_Zones.ZoneParentCode <> N'-1') AND (ZoneCapacity>0) and  (tbl_Zones.ZoneCode NOT LIKE '%R%') AND(tbl_Zones.ZoneCode NOT LIKE '%MR%') AND(tbl_Tags.TagZone IS NULL)  ";
        var dtResultcmd2 = dataAccess.SqlDataAdapter(cmd2);

        var cmd3 = $@" SELECT SUM(ZoneCapacity) AS StoreCapacity
                FROM tbl_Zones
                WHERE(ZoneParentCode <> N'-1') AND(ZoneCode NOT LIKE '%R%') AND(ZoneCode NOT LIKE '%MR%')";

        var dtResultcmd3 = dataAccess.SqlDataAdapter(cmd3);

        if (dtResultcmd1.Rows.Count > 0)
        {
            string[] dr = { dtResultcmd1.Rows[0]["CountProductSerial"].ToString()
                        , dtResultcmd1.Rows[0]["SumProductCount"].ToString()
                        , dtResultcmd1.Rows[0]["AvgDate"].ToString()
                        , dtResultcmd2.Rows[0]["COUNTEmptyZone"].ToString()
                        , dtResultcmd3.Rows[0]["StoreCapacity"].ToString() };

            dtResult.Rows.Add(dr);
        }

        return dtResult;
    }
