						 >= DATEADD(month,-12,GETDATE()))) then N'612' when ( (CAST(dbo.JalaliDateToGeorgianDate(SUBSTRING(tbl_Tags.TagRegisterShamsiUnixDate, 0, 5) + '/' + SUBSTRING(tbl_Tags.TagRegisterShamsiUnixDate, 5, 2) 
                         + '/' + SUBSTRING(tbl_Tags.TagRegisterShamsiUnixDate, 7, 2), SUBSTRING(tbl_Tags.TagRegisterShamsiUnixDate, 9, 2) + ':' + SUBSTRING(tbl_Tags.TagRegisterShamsiUnixDate, 11, 2)) AS datetime) 
						 < DATEADD(month,-12,GETDATE()))) then N'1200' end
						 order by ProductCode,age desc
                         ";


            var dtProductsAgeList = dataAccess.SqlDataAdapter(sqlCommand);

            var sqlCommandGetProducts = @"
                        
						SELECT DISTINCT tbl_TagsMovement.ProductCode, tbl_Products.ProductStatus, tbl_Products.ProductTechnicalCode, tbl_Products.ProductType, tbl_Products.ProductSize
FROM            tbl_TagsMovement LEFT OUTER JOIN
                         tbl_Products ON tbl_TagsMovement.ProductCode = tbl_Products.ProductCode LEFT OUTER JOIN
                         tbl_Tags ON tbl_TagsMovement.ProductSerial = tbl_Tags.ProductSerial RIGHT OUTER JOIN
                         tbl_MovementActions ON tbl_TagsMovement.HMovementActionId = tbl_MovementActions.MovementActionId
                         WHERE        (tbl_MovementActions.MovementActionTp = 6) AND (tbl_MovementActions.MovementActionData NOT LIKE N'%برگشت کالا%') AND (tbl_MovementActions.MovementActionDateTime < '{DateTimeTo}') AND 
                         (tbl_MovementActions.MovementActionDateTime >= '{DateTimeForm}')
						 
						 order by tbl_TagsMovement.ProductCode desc
                         ";



            var dtProducts = dataAccess.SqlDataAdapter(sqlCommandGetProducts);


            foreach (DataRow drProduct in dtProducts.Rows)
            {
                var sqlCommandGetProductsExistInStore = @"						 SELECT        N'1200' AS AgeStoreTitle, COUNT(ProductSerial) AS CountSerial, Coalesce(SUM(ProductCount),0) AS SumValue 
FROM            tbl_Tags
WHERE        (TagStatus = 1)  and ProductCode=N'{drProduct[0].ToString()}'  and    (CAST(dbo.JalaliDateToGeorgianDate(SUBSTRING(tbl_Tags.TagRegisterShamsiUnixDate, 0, 5) + '/' + SUBSTRING(tbl_Tags.TagRegisterShamsiUnixDate, 5, 2) 
                         + '/' + SUBSTRING(tbl_Tags.TagRegisterShamsiUnixDate, 7, 2), SUBSTRING(tbl_Tags.TagRegisterShamsiUnixDate, 9, 2) + ':' + SUBSTRING(tbl_Tags.TagRegisterShamsiUnixDate, 11, 2)) AS datetime) 
						 < DATEADD(month,-12,GETDATE()))
						  union
						 SELECT        N'612' AS AgeStoreTitle, COUNT(ProductSerial) AS CountSerial, Coalesce(SUM(ProductCount),0) AS SumValue 
FROM            tbl_Tags
WHERE        (TagStatus = 1) and ProductCode=N'{drProduct[0].ToString()}'   and (CAST(dbo.JalaliDateToGeorgianDate(SUBSTRING(tbl_Tags.TagRegisterShamsiUnixDate, 0, 5) + '/' + SUBSTRING(tbl_Tags.TagRegisterShamsiUnixDate, 5, 2) 
                         + '/' + SUBSTRING(tbl_Tags.TagRegisterShamsiUnixDate, 7, 2), SUBSTRING(tbl_Tags.TagRegisterShamsiUnixDate, 9, 2) + ':' + SUBSTRING(tbl_Tags.TagRegisterShamsiUnixDate, 11, 2)) AS datetime) 
						 < DATEADD(month,-6,GETDATE()))  and (CAST(dbo.JalaliDateToGeorgianDate(SUBSTRING(tbl_Tags.TagRegisterShamsiUnixDate, 0, 5) + '/' + SUBSTRING(tbl_Tags.TagRegisterShamsiUnixDate, 5, 2) 
                         + '/' + SUBSTRING(tbl_Tags.TagRegisterShamsiUnixDate, 7, 2), SUBSTRING(tbl_Tags.TagRegisterShamsiUnixDate, 9, 2) + ':' + SUBSTRING(tbl_Tags.TagRegisterShamsiUnixDate, 11, 2)) AS datetime) 
						 >= DATEADD(month,-12,GETDATE()))
                         
						 union
						 SELECT        N'36' AS AgeStoreTitle, COUNT(ProductSerial) AS CountSerial, Coalesce(SUM(ProductCount),0) AS SumValue 
FROM            tbl_Tags
WHERE        (TagStatus = 1) and ProductCode=N'{drProduct[0].ToString()}'  and (CAST(dbo.JalaliDateToGeorgianDate(SUBSTRING(tbl_Tags.TagRegisterShamsiUnixDate, 0, 5) + '/' + SUBSTRING(tbl_Tags.TagRegisterShamsiUnixDate, 5, 2) 
                         + '/' + SUBSTRING(tbl_Tags.TagRegisterShamsiUnixDate, 7, 2), SUBSTRING(tbl_Tags.TagRegisterShamsiUnixDate, 9, 2) + ':' + SUBSTRING(tbl_Tags.TagRegisterShamsiUnixDate, 11, 2)) AS datetime) 
						 < DATEADD(month,-3,GETDATE()))  and (CAST(dbo.JalaliDateToGeorgianDate(SUBSTRING(tbl_Tags.TagRegisterShamsiUnixDate, 0, 5) + '/' + SUBSTRING(tbl_Tags.TagRegisterShamsiUnixDate, 5, 2) 
                         + '/' + SUBSTRING(tbl_Tags.TagRegisterShamsiUnixDate, 7, 2), SUBSTRING(tbl_Tags.TagRegisterShamsiUnixDate, 9, 2) + ':' + SUBSTRING(tbl_Tags.TagRegisterShamsiUnixDate, 11, 2)) AS datetime) 
						 >= DATEADD(month,-6,GETDATE()))
 

						 						  union
						 SELECT        N'13' AS AgeStoreTitle, COUNT(ProductSerial) AS CountSerial, Coalesce(SUM(ProductCount),0) AS SumValue 
FROM            tbl_Tags
WHERE        (TagStatus = 1) and ProductCode=N'{drProduct[0].ToString()}'   and (CAST(dbo.JalaliDateToGeorgianDate(SUBSTRING(tbl_Tags.TagRegisterShamsiUnixDate, 0, 5) + '/' + SUBSTRING(tbl_Tags.TagRegisterShamsiUnixDate, 5, 2) 
                         + '/' + SUBSTRING(tbl_Tags.TagRegisterShamsiUnixDate, 7, 2), SUBSTRING(tbl_Tags.TagRegisterShamsiUnixDate, 9, 2) + ':' + SUBSTRING(tbl_Tags.TagRegisterShamsiUnixDate, 11, 2)) AS datetime) 
						 < DATEADD(month,-1,GETDATE()))  and (CAST(dbo.JalaliDateToGeorgianDate(SUBSTRING(tbl_Tags.TagRegisterShamsiUnixDate, 0, 5) + '/' + SUBSTRING(tbl_Tags.TagRegisterShamsiUnixDate, 5, 2) 
                         + '/' + SUBSTRING(tbl_Tags.TagRegisterShamsiUnixDate, 7, 2), SUBSTRING(tbl_Tags.TagRegisterShamsiUnixDate, 9, 2) + ':' + SUBSTRING(tbl_Tags.TagRegisterShamsiUnixDate, 11, 2)) AS datetime) 
						 >= DATEADD(month,-3,GETDATE()))
 
						 	 union

						SELECT        N'01' AS AgeStoreTitle, COUNT(ProductSerial) AS CountSerial, Coalesce(SUM(ProductCount),0) AS SumValue 
FROM            tbl_Tags
WHERE        (TagStatus = 1) and ProductCode=N'{drProduct[0].ToString()}'  and (CAST(dbo.JalaliDateToGeorgianDate(SUBSTRING(tbl_Tags.TagRegisterShamsiUnixDate, 0, 5) + '/' + SUBSTRING(tbl_Tags.TagRegisterShamsiUnixDate, 5, 2) 
                         + '/' + SUBSTRING(tbl_Tags.TagRegisterShamsiUnixDate, 7, 2), SUBSTRING(tbl_Tags.TagRegisterShamsiUnixDate, 9, 2) + ':' + SUBSTRING(tbl_Tags.TagRegisterShamsiUnixDate, 11, 2)) AS datetime) 
						 < GETDATE())  and (CAST(dbo.JalaliDateToGeorgianDate(SUBSTRING(tbl_Tags.TagRegisterShamsiUnixDate, 0, 5) + '/' + SUBSTRING(tbl_Tags.TagRegisterShamsiUnixDate, 5, 2) 
                         + '/' + SUBSTRING(tbl_Tags.TagRegisterShamsiUnixDate, 7, 2), SUBSTRING(tbl_Tags.TagRegisterShamsiUnixDate, 9, 2) + ':' + SUBSTRING(tbl_Tags.TagRegisterShamsiUnixDate, 11, 2)) AS datetime) 
						 >= DATEADD(month,-1,GETDATE()))
 
 
                         ";

                var dtProductsExistInStore = dataAccess.SqlDataAdapter(sqlCommandGetProductsExistInStore);

                foreach (DataRow drProductsAgeList in dtProductsAgeList.Rows)
                {
                    if (drProductsAgeList["ProductCode"].ToString() == drProduct[0].ToString())
                    {
                        foreach (DataRow drProductsExistInStore in dtProductsExistInStore.Rows)
                        {
                            if (drProductsExistInStore["AgeStoreTitle"].ToString() == drProductsAgeList["age"].ToString())
                            {
                                drProductsExistInStore["CountSerial"] = Convert.ToInt32(drProductsExistInStore["CountSerial"].ToString()) + Convert.ToInt32(drProductsAgeList["CountProductSerial"].ToString());
                            }
                        }
                    }
                }
                foreach (DataRow drProductsAgeList in dtProductsAgeList.Rows)
                {


                    if (drProductsAgeList["ProductCode"].ToString() == drProduct[0].ToString())
                    {
                        if (drProductsAgeList["age"].ToString() == "1200")
                        {
                            break;
                        }
                        var Count = Convert.ToInt32(drProductsAgeList["CountProductSerial"].ToString());
                        foreach (DataRow drProductsExistInStore in dtProductsExistInStore.Rows)
                        {

                            if (drProductsExistInStore["AgeStoreTitle"].ToString() == drProductsAgeList["age"].ToString())
                            {
                                if (Convert.ToInt32(drProductsExistInStore["CountSerial"].ToString()) >= Count)
                                {
                                    drProductsExistInStore["CountSerial"] = Convert.ToInt32(drProductsExistInStore["CountSerial"].ToString()) - Count;
                                    Count = 0;
                                    break;
                                }
                                else
                                {
                                    drProductsExistInStore["CountSerial"] = 0;
                                    Count = Count - Convert.ToInt32(drProductsExistInStore["CountSerial"].ToString());
                                    continue;
                                }
                            }
                            else
                            {
                                if (Convert.ToInt32(drProductsExistInStore["CountSerial"].ToString()) > 0)
                                {
                                    if (Convert.ToInt32(drProductsExistInStore["CountSerial"].ToString()) >= Count)
                                    {
                                        drProductsExistInStore["CountSerial"] = Convert.ToInt32(drProductsExistInStore["CountSerial"].ToString()) - Count; ;
                                        result.Rows.Add(drProduct[2].ToString() + "-" + drProduct[1].ToString() + "-" + drProduct[4].ToString(), Count);
                                        break;
                                    }
                                    else
                                    {
                                        drProductsExistInStore["CountSerial"] = 0;
                                        Count = Count - Convert.ToInt32(drProductsExistInStore["CountSerial"].ToString());
                                        result.Rows.Add(drProduct[2].ToString() + "-" + drProduct[1].ToString() + "-" + drProduct[4].ToString(), Count);

                                        continue;
                                    }
                                }
                                else
                                {
                                    continue;

                                }
                            }
                        }
                    }
                }
            }
        }
        catch (Exception exception)
        {
            logger.LogWarning(exception, exception.Message);

            return null;
        }

        return result;
    }


    public string SGetNotif_WinFormService(string DateTimeLastCheck, string User)
    {
        logger.LogInformation("SGetNotif_WinFormService" + " DateTimeLastCheck: " + DateTimeLastCheck.ToString() + " User: " + User);
        var whereString = string.Empty;
        var cmd = $@"SELECT       Coalesce( string_Agg(fld_Text, '\n'),'')  AS Expr1
                     FROM            tbl_NotificationQueue
                     WHERE        (fld_SendType = 2) AND (fld_Contact = N'{User}') AND (fld_SaveDateTime >= '{DateTimeLastCheck}')";


        var dtResult = dataAccess.SqlDataAdapter(cmd);

        string FinalResult = "";
        if (dtResult.Rows.Count > 0)
        {
            var TempResult = dtResult.Rows[0][0].ToString().Split("\n");
            if (TempResult.Length > 1)
            {
                foreach (string _text in TempResult)
                {
                    FinalResult += _text + Environment.NewLine;
                }
            }
            else
            {
                FinalResult = TempResult[0];
            }
        }
        return FinalResult;
    }

