    public Dictionary<int, DateTime> SCheckMovementInRange(string from, string to)
    {
        logger.LogInformation("SCheckMovementInRange"
    , new KeyValuePair<string, object>("from", from)
    , new KeyValuePair<string, object>("to", to)
    );

        var cmd = @"SELECT TOP(1) tbl_MovementActions.MovementActionId , MovementActionDateTime as [DateTime] FROM tbl_MovementActions
                    WHERE (tbl_MovementActions.MovementActionTp = 6) AND (tbl_MovementActions.MovementActionData NOT LIKE N'%برگشت کالا%') 
                    AND  " + (from.Equals(to) ? $"tbl_MovementActions.MovementActionDate = N'{from}'" : $"(tbl_MovementActions.MovementActionDate >= N'{from}' AND tbl_MovementActions.MovementActionDate <= N'{to}')")
                + @" ORDER BY tbl_MovementActions.MovementActionId DESC ";

        var dt = dataAccess.SqlDataAdapter(cmd).Select();

        var dict = new Dictionary<int, DateTime>();

        if (dt.Any())
        {
            dict.Add((int)dt[0].ItemArray[0], (DateTime)dt[0].ItemArray[1]);
        }

        return dict;
    }
