    public DataTable SSMS_ForoshMax()
    {
        logger.LogInformation("SSMS_ForoshMax"
    , new KeyValuePair<string, object>("", "")
    );
        DataTable dtResult = new DataTable();
        var allStats = SGetDailyExitStats();
        allStats = allStats.Where(p => p.Exit != null).ToList();
        var stats = new ExitStats();
        stats = allStats.FirstOrDefault(p => p.Exit.Any(f => f.Type == RegisterStatsEnum.Daily));

        var max = stats.Exit.First().Max.ToString();

        dtResult.Columns.Add("MaxForosh", typeof(string));
        dtResult.Rows.Add(max);
        return dtResult;
    }

