    public DataTable SRepSummaryRegisterForSMS(string fromDate, string toDate)
    {
        logger.LogInformation("SRepSummaryRegisterForSMS"
    , new KeyValuePair<string, object>("fromDate", fromDate)
    , new KeyValuePair<string, object>("toDate", toDate)
    );
        if (fromDate == toDate)
        {
            toDate = PersianCalendarTools.GregorianToPersian(PersianCalendarTools.PersianToGregorian(toDate).AddDays(1));
        }
        fromDate = fromDate.Split('/')[0] + fromDate.Split('/')[1] + fromDate.Split('/')[2];
        fromDate += "060101";

        toDate = toDate.Split('/')[0] + toDate.Split('/')[1] + toDate.Split('/')[2];
        toDate += "060101";

        var whereString = string.Empty;
        DataTable dtResult = new DataTable();

        dtResult.Columns.Add("CountProductSerial", typeof(string));
        dtResult.Columns.Add("SumProductCount", typeof(string));
        dtResult.Columns.Add("CountPropertyAId", typeof(string));
        dtResult.Columns.Add("CountProductType", typeof(string));
        dtResult.Columns.Add("CountProductSize", typeof(string));
        dtResult.Columns.Add("SumProductCountProductStatusD", typeof(string)); //%
        dtResult.Columns.Add("SumProductCountProductStatusCG", typeof(string)); //%
        dtResult.Columns.Add("MaxRegister", typeof(string));
        dtResult.Columns.Add("AVGRegister", typeof(string));
        dtResult.Columns.Add("MaxRegisterPercent", typeof(string));
        dtResult.Columns.Add("AVGRegisterPercent", typeof(string));




        var cmd = @"SELECT        COUNT(tbl_Tags.ProductSerial) AS CountProductSerial, COALESCE (SUM(tbl_Tags.ProductCount), 0) AS SumProductCount, COUNT(DISTINCT tbl_Tags.fld_ProductPropertyAId) AS CountPropertyAId, 
                         COUNT(DISTINCT tbl_Tags.ProductType) AS CountProductType, COUNT(DISTINCT tbl_Products.ProductSize) AS CountProductSize, CAST(CAST(COALESCE
                             ((SELECT        COALESCE (SUM(tbl_Tags_1.ProductCount), 0) AS Expr1
                                 FROM            tbl_Tags AS tbl_Tags_1
                                 WHERE      (tbl_Tags_1.fld_ProductPropertyAId > 0) AND ( tbl_Tags_1.TagRegisterShamsiUnixDate    >= '{fromDate}') AND 
							   ( tbl_Tags_1.TagRegisterShamsiUnixDate  <  '{toDate}') AND    (tbl_Tags_1.ProductStatus IN ('D'))), 0) * 100 / SUM(tbl_Tags.ProductCount) AS decimal(18, 1)) AS nvarchar(50)) + ' %' AS SumProductCountProductStatusD, CAST(CAST(COALESCE
                             ((SELECT        COALESCE (SUM(tbl_Tags_2.ProductCount), 0) AS Expr1
                                 FROM            tbl_Tags AS tbl_Tags_2
                                 WHERE      (tbl_Tags_2.fld_ProductPropertyAId > 0) AND ( tbl_Tags_2.TagRegisterShamsiUnixDate    >= '{fromDate}') AND 
							   ( tbl_Tags_2.TagRegisterShamsiUnixDate  <  '{toDate}') AND    (tbl_Tags_2.ProductStatus IN ( 'CG'))), 0) * 100 / SUM(tbl_Tags.ProductCount) AS decimal(18, 1)) AS nvarchar(50)) + ' %' AS SumProductCountProductStatusCG
FROM            tbl_Tags LEFT OUTER JOIN
                         tbl_Products ON tbl_Tags.ProductCode = tbl_Products.ProductCode
WHERE     (fld_ProductPropertyAId > 0) AND   (  tbl_Tags.TagRegisterShamsiUnixDate  >= '{fromDate}')
					AND  ( tbl_Tags.TagRegisterShamsiUnixDate <  " +
                (fromDate.Equals(toDate) ? "=" : "")
                + $" N'{toDate}')";
        DataTable _dtMain = dataAccess.SqlDataAdapter(cmd);
        var allStats = SGetDailyRegisterStats();
        allStats = allStats.Where(p => p.Reg != null).ToList();
        RegisterStats stats = new RegisterStats();
        if (_dtMain.Rows.Count > 0)
        {
            string GroupByCommandMaxRegister = "";
            GroupByCommandMaxRegister = " GROUP BY SUBSTRING(TagRegisterShamsiUnixDate, 0, 9)";
            stats = allStats.FirstOrDefault(p => p.Reg.Any(f => f.Type == RegisterStatsEnum.Daily));
            var commandMaxRegister = @" SELECT COALESCE(SUM(ProductCount),0) AS MaxRegister
                                    FROM tbl_Tags
                                    WHERE (fld_ProductPropertyAId > 0)
                                   {GroupByCommandMaxRegister}
                                    ORDER BY MaxRegister DESC ";

            var max = stats != null ? stats.Reg.First().Max.ToString() : "0";
            var maxPercent = "0";

            if (max != "0" && Convert.ToDecimal(_dtMain.Rows[0]["SumProductCount"].ToString()) > 0)
            {
                var _maxTempValue = Convert.ToDecimal(_dtMain.Rows[0]["SumProductCount"].ToString()) - Convert.ToDecimal(max);
                var _maxTempPercent = _maxTempValue * 100 / Convert.ToDecimal(_dtMain.Rows[0]["SumProductCount"].ToString());

                _maxTempPercent = Math.Round(_maxTempPercent, 1);

                if ((_maxTempValue) >= 0)
                    max = _maxTempPercent + " % بیشتر معادل " + Math.Round(_maxTempValue, 1) + " متر مربع";
                else
                    max = (-1 * _maxTempPercent) + " % کمتر معادل " + (-1 * Math.Round(_maxTempValue, 1)) + " متر مربع";

                maxPercent = _maxTempPercent.ToString();
            }
            var commandAVGRegister = @"SELECT        COALESCE(CAST(SUM(ProductCount) / COUNT(DISTINCT SUBSTRING(TagRegisterShamsiUnixDate, 0, 9)) AS decimal(18, 2)),0) AS AVGRegister
                                    FROM            tbl_Tags
                                    WHERE(fld_ProductPropertyAId > 0) AND(fld_ProductPropertyBId > 0) ";
            var average = stats != null ? stats.Reg.First().Avg.ToString() : "0";
            var averagePercent = "0";
            if (average != "0" && Convert.ToDecimal(_dtMain.Rows[0]["SumProductCount"].ToString()) > 0)
            {
                var _avgTempValue = Convert.ToDecimal(_dtMain.Rows[0]["SumProductCount"].ToString()) - Convert.ToDecimal(average);
                var _avgTempPercent = _avgTempValue * 100 / Convert.ToDecimal(_dtMain.Rows[0]["SumProductCount"].ToString());
                _avgTempPercent = Math.Round(_avgTempPercent, 1);
                if ((_avgTempValue) >= 0)
                    average = _avgTempPercent + " % بیشتر معادل " + Math.Round(_avgTempValue, 1) + " متر مربع";
                else
                    average = (-1 * _avgTempPercent) + " % کمتر معادل " + (-1 * Math.Round(_avgTempValue, 1)) + " متر مربع";
                averagePercent = _avgTempPercent.ToString();
            }

            string[] RowData ={ _dtMain.Rows[0]["CountProductSerial"].ToString(),
                _dtMain.Rows[0]["SumProductCount"].ToString(),
                _dtMain.Rows[0]["CountPropertyAId"].ToString(),
                _dtMain.Rows[0]["CountProductType"].ToString(),
                _dtMain.Rows[0]["CountProductSize"].ToString(),
                _dtMain.Rows[0]["SumProductCountProductStatusD"].ToString(),
                 _dtMain.Rows[0]["SumProductCountProductStatusCG"].ToString()
                ,max.ToString(),average.ToString(),maxPercent.ToString(),averagePercent.ToString()};

            dtResult.Rows.Add(RowData);
        }


        return dtResult;
    }
    public DataTable SRepSummaryExitProductsForSMS(string fromDate, string toDate)
    {
        logger.LogInformation("SRepSummaryExitProductsForSMS"
    , new KeyValuePair<string, object>("fromDate", fromDate)
    , new KeyValuePair<string, object>("toDate", toDate)
    );
        var fromDateGregorian = PersianCalendarTools.PersianToGregorian(fromDate);
        DateTime fromMain;
        var whereString = string.Empty;
        DataTable dtResult = new DataTable();



        toDate = PersianCalendarTools.GregorianToPersian(PersianCalendarTools.PersianToGregorian(toDate).AddDays(1));


        var cmd = $@"SELECT        COUNT(DISTINCT tbl_TagsMovement.HMovementActionId) AS CountAction, COUNT(DISTINCT tbl_TagsMovement.ProductSerial) AS CountProductSerial, COALESCE (SUM(tbl_TagsMovement.ProductCount), 0) 
                         AS SumProductCount, COALESCE (dbo.GeorgianDateToJalaliDate(CAST(AVG(CAST(CAST(dbo.JalaliDateToGeorgianDate(SUBSTRING(tbl_Tags.TagRegisterShamsiUnixDate, 0, 5) 
                         + '/' + SUBSTRING(tbl_Tags.TagRegisterShamsiUnixDate, 5, 2) + '/' + SUBSTRING(tbl_Tags.TagRegisterShamsiUnixDate, 7, 2), SUBSTRING(tbl_Tags.TagRegisterShamsiUnixDate, 9, 2) 
                         + ':' + SUBSTRING(tbl_Tags.TagRegisterShamsiUnixDate, 11, 2)) AS datetime) AS float)) AS datetime)), '0') AS AVGRegisterDate
FROM            tbl_TagsMovement LEFT OUTER JOIN
                         tbl_Tags ON tbl_TagsMovement.ProductSerial = tbl_Tags.ProductSerial RIGHT OUTER JOIN
                         tbl_MovementActions ON tbl_TagsMovement.HMovementActionId = tbl_MovementActions.MovementActionId
WHERE        (tbl_MovementActions.MovementActionTp = 6) AND (tbl_MovementActions.MovementActionData NOT LIKE N'%برگشت کالا%') AND (tbl_MovementActions.MovementActionDate >= '{fromDate}') AND (tbl_MovementActions.MovementActionDate <" +
    (fromDate.Equals(toDate) ? "=" : "")
    + $@" '{toDate}') ";
        var allStats = SGetDailyExitStats();
        allStats = allStats.Where(p => p.Exit != null).ToList();
        var stats = new ExitStats();
        DataTable _dtMain = dataAccess.SqlDataAdapter(cmd);
        if (_dtMain.Rows.Count > 0)
        {
            string GroupByCommandMaxExit = "0";


            GroupByCommandMaxExit = " tbl_TagsMovement.HTagsMovementDate ";
            stats = allStats.FirstOrDefault(p => p.Exit.Any(f => f.Type == RegisterStatsEnum.Daily));

            var max = stats.Exit.First().Max.ToString();
            var maxPercent = "0";
            if (max != "" && decimal.Parse(max) > 0 && Convert.ToDecimal(_dtMain.Rows[0]["SumProductCount"].ToString()) > 0)
            {
                var _maxTempValue = Convert.ToDecimal(_dtMain.Rows[0]["SumProductCount"].ToString()) - Convert.ToDecimal(max);
                var _maxTempPercent = _maxTempValue * 100 / Convert.ToDecimal(_dtMain.Rows[0]["SumProductCount"].ToString());
                _maxTempPercent = Math.Round(_maxTempPercent, 1);
                if ((_maxTempValue) >= 0)
                    max = _maxTempPercent + " % بیشتر - : " + Math.Round(_maxTempValue, 1) + " متر مربع";
                else
                    max = (-1 * _maxTempPercent) + " % کمتر - : " + (-1 * Math.Round(_maxTempValue, 1)) + " متر مربع";
                maxPercent = _maxTempPercent.ToString();
            }
            else
            {
                max = "0";
            }
            var average = stats.Exit.First().Avg.ToString();
            var averagePercent = "0";
            if (average != "" && decimal.Parse(average) > 0 && Convert.ToDecimal(_dtMain.Rows[0]["SumProductCount"].ToString()) > 0)
            {
                var _avgTempValue = Convert.ToDecimal(_dtMain.Rows[0]["SumProductCount"].ToString()) - Convert.ToDecimal(average);
                var _avgTempPercent = _avgTempValue * 100 / Convert.ToDecimal(_dtMain.Rows[0]["SumProductCount"].ToString());
                _avgTempPercent = Math.Round(_avgTempPercent, 1);
                if ((_avgTempValue) >= 0)
                    average = _avgTempPercent + " % بیشتر - : " + Math.Round(_avgTempValue, 1) + " متر مربع";
                else
                    average = (-1 * _avgTempPercent) + " % کمتر - : " + (-1 * Math.Round(_avgTempValue, 1)) + " متر مربع";
                averagePercent = _avgTempPercent.ToString();
            }
            else
            {
                average = "0";
            }
            var cmdDestinationType_2 = @"SELECT        SUM(tbl_TagsMovement.ProductCount) AS SumDestinationType_2
FROM            tbl_MovementActions LEFT OUTER JOIN
                         tbl_TagsMovement ON tbl_MovementActions.MovementActionId = tbl_TagsMovement.HMovementActionId
WHERE        (tbl_MovementActions.MovementActionTp = 6) AND
(tbl_MovementActions.MovementActionData NOT LIKE N'%برگشت کالا%') AND 
(JSON_VALUE(tbl_MovementActions.MovementActionData, '$.DetinationType') = '2') AND 
(tbl_MovementActions.MovementActionDate >= '{fromDate}') AND (tbl_MovementActions.MovementActionDate <"
    + (fromDate.Equals(toDate) ? "=" : "") +
    $"'{toDate}')    ";
            var SumDestinationType_2 = dataAccess.SqlDataReaders(cmdDestinationType_2)[0].Value.ToString();

            if (SumDestinationType_2 != "" && Convert.ToDecimal(SumDestinationType_2) > 0)
            {
                SumDestinationType_2 = Math.Round((Convert.ToDecimal(SumDestinationType_2) * 100 / Convert.ToDecimal(_dtMain.Rows[0]["SumProductCount"].ToString())), 1).ToString() + " %";
            }
            else
            {
                SumDestinationType_2 = "0 %";
            }
            //_dtMain.Rows[0]["AVGRegisterDate"].ToString()
            string[] RowData ={ _dtMain.Rows[0]["CountAction"].ToString(),
                _dtMain.Rows[0]["CountProductSerial"].ToString(),
                _dtMain.Rows[0]["SumProductCount"].ToString(),
             _dtMain.Rows[0]["AVGRegisterDate"].ToString()   ,max,
                average,SumDestinationType_2, stats.Exit.First().Avg.ToString()};
            dtResult.Rows.Add(RowData);
        }
        return dtResult;
    }



