    public DataTable SReportCargoByType(int tp)
    {
        var cmd = @"SELECT        fld_PPMActionId as [ActionId], fld_PPMUserId as [SaverUserId],
(select top(1) [Name] FROM tbl_User where tbl_User.Username = fld_PPMUserId OR tbl_User.Id = fld_PPMUserId) as [SaverName],
fld_PPMProductCode as ProductCode,
fld_PPMRegDateTime as [Date], COUNT(fld_PPMId) AS [Count], fld_PPMWMCode as [Truck], fld_PPMFromZoneId as [From], fld_PPMToZoneId as [Destination],COALESCE(tbl_PlacementOrders.fld_POStatus,0) as[Status]
                  FROM            tbl_ProductPlacementMissions
left join 
tbl_PlacementOrders on tbl_PlacementOrders.fld_POCode = tbl_ProductPlacementMissions.fld_PPMActionId
                  WHERE        (fld_PPMType = @Tp)
                  GROUP BY fld_PPMActionId, fld_PPMUserId, fld_PPMRegDateTime, fld_PPMWMCode, fld_PPMFromZoneId, fld_PPMToZoneId,fld_PPMProductCode,tbl_PlacementOrders.fld_POStatus ";
        return dataAccess.SqlDataAdapter(cmd,
            new KeyValuePair<string, object>("Tp", tp));
    }

    public bool SDeleteReportCargoByActionId(int actionId)
    {
        var cmd = @"
                  UPDATE       tbl_PlacementOrders
                  SET                fld_POStatus = 3
                  WHERE        (fld_POCode = @POCode) ";
        if (dataAccess.CmdSqlExecuteNonQuery(cmd,
            new KeyValuePair<string, object>("POCode", actionId)) > 0)
        {
            var cmdPm = @"
                  UPDATE       tbl_ProductPlacementMissions
                  SET                fld_PPMStatus = 3
                  WHERE        (fld_PPMActionId = @POCode)";

            dataAccess.CmdSqlExecuteNonQuery(cmdPm,
                new KeyValuePair<string, object>("POCode", actionId));

            return true;
        }
        return false;
    }

    public bool SSetTruckNumber(int truck, string user)
    {
        var cmd = @"UPDATE       tbl_WarehouseMachines
                                       SET                fld_WMDriverName = @DriverUserName
                                       WHERE(fld_WMCode = @Truck) ";
        return dataAccess.CmdSqlExecuteNonQuery(cmd,
           new KeyValuePair<string, object>("DriverUserName", user)
           , new KeyValuePair<string, object>("Truck", truck)
           ) > 0;
    }
