    public DataTable SGetProductsByEpcsInAndroidAction(List<string> epcList, string userToken, string ActionId, string ActionType, string DeviceId)
    {
        DeviceId = "HandHeld" + DeviceId;


        var listActionType = SGetActionTypes();

        if (epcList.Count == 0)
            return new DataTable();

        SSaveGateLog(userToken, ActionId, DeviceId, epcList, null, ActionType);

        var _listSourceActionTypeSelected = listActionType.FirstOrDefault(p => p.Id == Convert.ToInt32(ActionType)).From.Split(',');

        var command = @$" SELECT        tbl_Tags.Id, tbl_Tags.ProductSerial, tbl_Tags.ProductCode, tbl_Tags.TagEpc, tbl_Tags.ProjectCode, tbl_Tags.ProductCount, tbl_Tags.ProductName, tbl_Tags.ProductType, tbl_Tags.ProductStatus, tbl_Tags.TagStatus, 
                         tbl_Tags.TagRegisterShamsiUnixDate, tbl_Tags.TagRegisterUser, tbl_Tags.TagTreeParentId, tbl_Tags.TagTreeSecondParentId, tbl_Tags.TagTreeParentsId, tbl_Tags.NewProductSerial, tbl_Tags.ProductProperties, 
                         tbl_Tags.Lock, tbl_Tags.Username, tbl_Tags.DeviceId, tbl_Tags.DeviceIp, tbl_Tags.Freeze, tbl_Tags.Deactivate, tbl_Tags.TagInActionId, tbl_Tags.TagInDestinationId, tbl_Tags.TagInActionId2, tbl_Tags.TagInDestinationId2, 
                         tbl_Tags.fld_ProductPropertyAId, tbl_Tags.fld_ProductPropertyBId, tbl_Tags.fld_ProductPropertyCId, tbl_Tags.RegCode, tbl_Tags.fld_LastModifierUser, tbl_Tags.ContractStatus, COALESCE (tbl_Tags.TagZone, N'0') AS TagZone, 
                         tbl_Tags.TagRegisterDateTime, tbl_Tags.ReProduct, tbl_Tags.fld_LastInspectResult, tbl_Tags.fld_ProductGroup, tbl_Tags.fld_ProductBrand, tbl_Tags.fld_InspectActionId, COALESCE (tbl_Tags.TagInDestinationId, N'0') 
                         AS WarehouseCode, COALESCE (tbl_ProductStatus.ProductStatusTitle, N'-1') AS ProductStatusTitle, COALESCE (tbl_ProductType.ProductTypeTitle, N'-1') AS ProductTypeTitle, COALESCE
                             ((SELECT        TOP (1) RTagsMovementDate
                                 FROM            tbl_TagsMovement
                                 WHERE        (TagEpc = tbl_Tags.TagEpc)
                                 ORDER BY RTagsMovementDate), N'-1') AS EnterDate, COALESCE
                             ((SELECT        TOP (1) fld_POStatus
                                 FROM            tbl_PlacementOrders
                                 WHERE        (fld_POType = 1) AND (fld_POProductCode = tbl_Tags.ProductCode)
                                 ORDER BY fld_PODateTime DESC), N'-1') AS PlaceSt, CAST(COALESCE (tbl_Tags.Freeze, 0) AS NVARCHAR) AS FreezeStatus, CASE WHEN (fld_InspectActionId = 0) THEN N'0' WHEN (tbl_Tags.Lock = 0 AND 
                         fld_InspectActionId <> 0) THEN N'1' WHEN (tbl_Tags.Lock = 1 AND fld_InspectActionId <> 0) THEN N'2' ELSE N'0' END AS InspectStatus,'0' as InSourceStatus
FROM            tbl_Tags LEFT OUTER JOIN
                         tbl_ProductStatus ON tbl_ProductStatus.ProductStatusCode = tbl_Tags.ProductStatus LEFT OUTER JOIN
                         tbl_ProductType ON tbl_ProductType.ProductTypeCode = tbl_Tags.ProductType
WHERE        (tbl_Tags.TagEpc IN (SELECT DISTINCT fld_TagSerial
FROM            tbl_UHF_ReaderLog
WHERE        (fld_InventoryId = '" + ActionId + "') AND (ActionStatus=0) )) ";

        DataTable _dtResult = dataAccess.SqlDataAdapter(command);

        foreach (DataRow _dr in _dtResult.Rows)
        {
            if (_listSourceActionTypeSelected.Length == 1)
            {
                if ((_listSourceActionTypeSelected[0] != "") && _dr["TagStatus"].ToString() == _listSourceActionTypeSelected[0])
                    _dr["InSourceStatus"] = 1;
            }
            else if (_listSourceActionTypeSelected.Length == 2)
            {
                if (((_listSourceActionTypeSelected[0] != "") && _dr["TagStatus"].ToString() == _listSourceActionTypeSelected[0]) || _dr["TagStatus"].ToString() == _listSourceActionTypeSelected[1])
                    _dr["InSourceStatus"] = 1;
            }
            else if (_listSourceActionTypeSelected.Length == 3)
            {
                if (((_listSourceActionTypeSelected[0] != "") && _dr["TagStatus"].ToString() == _listSourceActionTypeSelected[0]) || _dr["TagStatus"].ToString() == _listSourceActionTypeSelected[1] || _dr["TagStatus"].ToString() == _listSourceActionTypeSelected[2])
                    _dr["InSourceStatus"] = 1;
            }

        }

        return _dtResult;
    }

    public DataTable SGetProductsByEpcs(List<string> epcList, string userToken)
    {
        if (epcList.Count == 0)
            return new DataTable();

        for (int i = 0; i < epcList.Count; i++)
        {
            epcList[i] = ("N'" + epcList[i] + "'");
        }

        var command = @$" SELECT        tbl_Tags.Id, tbl_Tags.ProductSerial, tbl_Tags.ProductCode, tbl_Tags.TagEpc, tbl_Tags.ProjectCode, tbl_Tags.ProductCount, tbl_Tags.ProductName, tbl_Tags.ProductType, tbl_Tags.ProductStatus, tbl_Tags.TagStatus, 
                         tbl_Tags.TagRegisterShamsiUnixDate, tbl_Tags.TagRegisterUser, tbl_Tags.TagTreeParentId, tbl_Tags.TagTreeSecondParentId, tbl_Tags.TagTreeParentsId, tbl_Tags.NewProductSerial, tbl_Tags.ProductProperties, 
                         tbl_Tags.Lock, tbl_Tags.Username, tbl_Tags.DeviceId, tbl_Tags.DeviceIp, tbl_Tags.Freeze, tbl_Tags.Deactivate, tbl_Tags.TagInActionId, tbl_Tags.TagInDestinationId, tbl_Tags.TagInActionId2, tbl_Tags.TagInDestinationId2, 
                         tbl_Tags.fld_ProductPropertyAId, tbl_Tags.fld_ProductPropertyBId, tbl_Tags.fld_ProductPropertyCId, tbl_Tags.RegCode, tbl_Tags.fld_LastModifierUser, tbl_Tags.ContractStatus, COALESCE(tbl_Tags.TagZone,'0') as TagZone , 
                         tbl_Tags.TagRegisterDateTime, tbl_Tags.ReProduct, tbl_Tags.fld_LastInspectResult, tbl_Tags.fld_ProductGroup, tbl_Tags.fld_ProductBrand, tbl_Tags.fld_InspectActionId, COALESCE (tbl_Tags.TagInDestinationId, N'0') 
                         AS WarehouseCode, COALESCE (tbl_ProductStatus.ProductStatusTitle, N'-1') AS ProductStatusTitle, COALESCE (tbl_ProductType.ProductTypeTitle, N'-1') AS ProductTypeTitle, COALESCE
                             ((SELECT        TOP (1) RTagsMovementDate
                                 FROM            tbl_TagsMovement
                                 WHERE        (TagEpc = tbl_Tags.TagEpc)
                                 ORDER BY RTagsMovementDate), N'-1') AS EnterDate, COALESCE
                             ((SELECT        TOP (1) fld_POStatus
                                 FROM            tbl_PlacementOrders
                                 WHERE        (fld_POType = 1) AND (fld_POProductCode = tbl_Tags.ProductCode)
                                 ORDER BY fld_PODateTime DESC), N'-1') AS PlaceSt, CAST(COALESCE (tbl_Tags.Freeze, 0) AS NVARCHAR) AS FreezeStatus, CASE WHEN (fld_InspectActionId = 0) THEN N'0' WHEN (tbl_Tags.Lock = 0 AND 
                         fld_InspectActionId <> 0) THEN N'1' WHEN (tbl_Tags.Lock = 1 AND fld_InspectActionId <> 0) THEN N'2' ELSE N'0' END AS InspectStatus
FROM            tbl_Tags LEFT OUTER JOIN
                         tbl_ProductStatus ON tbl_ProductStatus.ProductStatusCode = tbl_Tags.ProductStatus LEFT OUTER JOIN
                         tbl_ProductType ON tbl_ProductType.ProductTypeCode = tbl_Tags.ProductType
                                   WHERE tbl_Tags.TagEpc in ({string.Join(", ", epcList.ToArray())}) ";

        return dataAccess.SqlDataAdapter(command);
    }

    public int CheckFieldUniqueness
        (
            string tableName,
            string fieldName,
            string value,
            string userToken
        )
    {
        var command = @" select count(*) from " + tableName + " where " + fieldName + " = N'" + value + "'";

        var dataList = dataAccess.SqlDataAdapter(command).Select().ToList();
        if (dataList.Count == 0)
            return 0;
        else
            return (int)dataList[0].ItemArray[0];
    }
