    public List<string> IGetAndroidClaims(string username)
    {
        var commands = "";

        if (Guid.TryParse(username, out var ParsedValue))
        {
            commands = $"SELECT ClaimValue as [Value] FROM tbl_UserClaim WHERE UserId = N'{username}' AND ClaimType = N'{System.Security.Claims.ClaimTypes.AuthenticationInstant}' ";
        }
        else
        {
            commands = $"SELECT ClaimValue as [Value] FROM tbl_UserClaim WHERE UserId = (SELECT [Id] FROM [dbo].[tbl_User] WHERE [Username] = N'{username}') AND ClaimType = N'{System.Security.Claims.ClaimTypes.AuthenticationInstant}' ";
        }

        return sqlDataAccess.SqlDataAdapter(commands)
                               .Select()
                               .Select(p => p.ItemArray[0].ToString().Replace("\r\n", ""))
                               .ToList();
    }

