    public List<GetUserQuickAccessVm> SGetUserQuickAccess()
    {
        string userId = httpContext.User.GetUserId();

        var items = apiContext.UserQuickAccesses
            .Where(p => p.UserId == userId)
            .Include(p => p.MenuLink)
            .Select(p => new GetUserQuickAccessVm
            {
                Id = p.Id,
                MenuLinkId = p.MenuLinkId,
                Title = p.MenuLink.Title,
                Url = p.MenuLink.Url,
                IconName = p.MenuLink.IconName
            })
            .ToList();

        return items;
    }

    public bool SSaveUserQuickAccess(int menuLinkId)
    {
        string userId = httpContext.User.GetUserId();

        bool exists = apiContext.UserQuickAccesses
            .Any(p => p.UserId == userId && p.MenuLinkId == menuLinkId);

        if (exists)
            return false;

        int count = apiContext.UserQuickAccesses
            .Count(p => p.UserId == userId);

        if (count >= 4)
            return false;

        apiContext.UserQuickAccesses.Add(new UserQuickAccess
        {
            UserId = userId,
            MenuLinkId = menuLinkId
        });

        try
        {
            apiContext.SaveChanges();
        }
        catch (DbUpdateException)
        {
            return false;
        }

        return true;
    }

    public bool SRemoveUserQuickAccess(int id)
    {
        string userId = httpContext.User.GetUserId();

        var item = apiContext.UserQuickAccesses
            .FirstOrDefault(p => p.Id == id && p.UserId == userId);

        if (item is null)
            return false;

        apiContext.UserQuickAccesses.Remove(item);
        apiContext.SaveChanges();

        return true;
    }


