    public bool SSaveTechnicalInformation(JArray data)
    {
        List<string> commands = new();

        foreach (JToken item in data)
        {
            string productCode = item.First().Values().First().ToString();

            item.First().Remove();

            string command = $"UPDATE tbl_Products SET ProductTechnicalData = N'{item}' WHERE ProductCode = N'{productCode}' ";

            commands.Add(command);
        }

        return dataAccess.CmdSqlExecuteNonQueryWithTransaction(commands) == 1;
    }

    public bool SSaveTechnicalInformationUsingJsonArray(List<SaveProductTerchnicalDataCommand> commands)
    {
        List<string> commandsString = new();

        foreach (SaveProductTerchnicalDataCommand item in commands)
        {
            string command = $"UPDATE tbl_Products SET ProductTechnicalData = N'{JsonTools.ConvertJsonObjectToEncodedString(item.Data)}' WHERE ProductCode = N'{item.ProductCode}'";

            commandsString.Add(command);
        }

        return dataAccess.CmdSqlExecuteNonQueryWithTransaction(commandsString) == 1;
    }

    public DataTable SGetSerialDataForPlace(List<string> serials)
    {
        string command = $"""
            SELECT [ProductCode]
                  ,[ProductSerial]
                  ,[ProductCount]
                  ,[ProductName]
                  ,[RegCode] as [TechnicalCode]
            FROM   [tbl_Tags]
            WHERE ProductSerial IN ({serials.Aggregate(string.Empty, (first, next) =>
