    public List<InspectElementDto> SGetAllElements()
    {
        string command = @"SELECT [fld_InspectElementId]
                                 ,[fld_InspectElementName]
                                 ,[fld_InspectElementType]
                                 ,[fld_InspectElementValue]
                                 ,[fld_InspectElementMinValue]
                                 ,[fld_InspectElementMaxValue]
                                 ,[fld_InspectElementIsGatePrevent]
                                 ,[fld_InspectElementIsActive]
                                 ,[fld_InspectElementIsRequired]
                                 ,[fld_InspectElementProductTypes]
                                 ,[fld_InspectElementOptions]
                                 ,[fld_InspectElementRow]
                                  FROM [dbo].[tbl_InspectElement] ORDER BY fld_InspectElementId ASC";

        var result = dataAccess.SqlDataAdapter(command).Select();

        return result.Select(p => new InspectElementDto()
        {
            Id = (int)p.ItemArray[0],
            Name = p.ItemArray[1].ToString(),
            InspectElementType = (InspectElementType)p.ItemArray[2],
            Value = p.ItemArray[3].ToString(),
            MinValue = p.ItemArray[4] is not null ? (int)p.ItemArray[4] : 0,
            MaxValue = p.ItemArray[5] is not null ? (int)p.ItemArray[5] : 0,
            Prevent = (bool)p.ItemArray[6],
            IsActive = (bool)p.ItemArray[7],
            IsRequired = (bool)p.ItemArray[8],
            ProductTypes = p.ItemArray[9].ToString().Equals("ALL") ? new string[] { "ALL" } : p.ItemArray[9].ToString().Split('|'),
            Options = p.ItemArray[10].ToString().HasNoValue() ? new string[0] : p.ItemArray[10].ToString().Split('|'),
            Row = p.ItemArray[11] is not null ? (int)p.ItemArray[11] : 0
        }).ToList();
    }

    public DataTable SGetAllElementsDataTable()
    {

        string command = @"SELECT [fld_InspectElementId]
                                 ,[fld_InspectElementName]
                                 ,[fld_InspectElementType]
                                 ,[fld_InspectElementValue]
                                 ,[fld_InspectElementMinValue]
                                 ,[fld_InspectElementMaxValue]
                                 ,[fld_InspectElementIsGatePrevent]
                                 ,[fld_InspectElementIsActive]
                                 ,[fld_InspectElementIsRequired]
                                 ,[fld_InspectElementProductTypes]
                                 ,[fld_InspectElementOptions]
                                 ,COALESCE([fld_InspectElementRow],0) AS [fld_InspectElementRow]
                                  FROM [dbo].[tbl_InspectElement] ORDER BY fld_InspectElementId ASC";

        return dataAccess.SqlDataAdapter(command);
    }

    public int SSaveElement(InspectElementDto inspect)
    {
        string command = string.Empty;

        List<KeyValuePair<string, object>> parameters = new();

        string options = string.Empty;

        if (inspect.Options.Any())
        {
            options = inspect.Options.Aggregate(string.Empty, (first, next) =>
            {
                return first + (string.IsNullOrEmpty(next) ? string.Empty : ($"|{next}"));
            }).Remove(0, 1);
        }

        if (inspect.Id == 0)
        {
            command = @" INSERT INTO [dbo].[tbl_InspectElement] (fld_InspectElementName,fld_InspectElementType,fld_InspectElementValue,fld_InspectElementMinValue
                         ,fld_InspectElementMaxValue,fld_InspectElementIsGatePrevent,fld_InspectElementIsActive,fld_InspectElementIsRequired
                         ,fld_InspectElementProductTypes,fld_InspectElementOptions,fld_InspectElementRow) VALUES 
            (@Name,@Type,@Value,@Min,@Max,@Prevent,@Active,@Required,@ProductTypes
            " + (string.IsNullOrEmpty(options) ? ",NULL" : $",N'{options}'") + " ,@Row)";

            parameters.Add(new("Name", inspect.Name));
            parameters.Add(new("Type", inspect.InspectElementType));
            parameters.Add(new("Value", inspect.Value));
            parameters.Add(new("Min", inspect.MinValue));
            parameters.Add(new("Max", inspect.MaxValue));
            parameters.Add(new("Prevent", inspect.Prevent));
            parameters.Add(new("Active", inspect.IsActive));
            parameters.Add(new("Required", inspect.IsRequired));
            parameters.Add(new("Row", inspect.Row));

            if (inspect.ProductTypes.First().Equals("ALL"))
            {
                parameters.Add(new("ProductTypes", "ALL"));
            }
            else
            {
                parameters.Add(new("ProductTypes", inspect.ProductTypes.Aggregate(string.Empty, (first, next) =>
                {
                    return first + (string.IsNullOrEmpty(next) ? string.Empty : ($"|{next}"));
                }).Remove(0, 1)));
            }
        }
        else
        {
            command = @" UPDATE [dbo].[tbl_InspectElement]
       SET [fld_InspectElementName] = @Name
      ,[fld_InspectElementType] = @Type
      ,[fld_InspectElementValue] = @Value
      ,[fld_InspectElementMinValue] = @Min
      ,[fld_InspectElementMaxValue] = @Max
      ,[fld_InspectElementIsGatePrevent] = @Prevent
      ,[fld_InspectElementIsActive] = @Active
      ,[fld_InspectElementIsRequired] = @Required
      ,[fld_InspectElementProductTypes] = @ProductTypes
      ,[fld_InspectElementOptions] = " + (string.IsNullOrEmpty(options) ? "NULL" : $"N'{options}'") +
      ",[fld_InspectElementRow] = @Row" + " WHERE [fld_InspectElementId] = @Id";

            parameters.Add(new("Id", inspect.Id));
            parameters.Add(new("Name", inspect.Name));
            parameters.Add(new("Type", inspect.InspectElementType));
            parameters.Add(new("Value", inspect.Value));
            parameters.Add(new("Min", inspect.MinValue));
            parameters.Add(new("Max", inspect.MaxValue));
            parameters.Add(new("Prevent", inspect.Prevent));
            parameters.Add(new("Active", inspect.IsActive));
            parameters.Add(new("Required", inspect.IsRequired));
            parameters.Add(new("Row", inspect.Row));

            if (inspect.ProductTypes.First().Equals("ALL"))
            {
                parameters.Add(new("ProductTypes", "ALL"));
            }
            else
            {
                parameters.Add(new("ProductTypes", inspect.ProductTypes.Aggregate(string.Empty, (first, next) =>
                {
                    return first + (string.IsNullOrEmpty(next) ? string.Empty : ($"|{next}"));
                }).Remove(0, 1)));
            }

        }

        if (dataAccess.CmdSqlExecuteNonQuery(command, parameters.ToArray()) > 0)
        {
            return int.Parse(GetLatestIdOfIdentityTable("tbl_InspectElement"));
        }
        else
        {
            return -1;
        }
    }

    public bool SDeleteElement(int elementId)
    {
        string command = @" DELETE FROM tbl_InspectElement WHERE fld_InspectElementId = " + elementId;

        return dataAccess.CmdSqlExecuteNonQuery(command) == 1;
    }

    public bool SSaveInspect(InspectSaveDto inspect)
    {
        var elements = SGetAllElements();

        foreach (var result in inspect.InspectElementResults)
        {
            result.InspectRow = elements.FirstOrDefault(p => p.Id == result.InspectElementId).Row;
        }

        inspect.InspectElementResults = inspect.InspectElementResults.OrderBy(p => p.InspectRow).ToList();

        string results = JsonConvert.SerializeObject(inspect.InspectElementResults);

        logger.LogInformation("SSaveInspect" + Environment.NewLine +
                              "Epc:" + inspect.Serial + Environment.NewLine +
                              "InspectResult:" + inspect.InspectResult + Environment.NewLine +
                              "InspectElementResults:" + results + Environment.NewLine +
                              "UserId:" + inspect.UserId + Environment.NewLine);
        #region Check Result

        string productType = dataAccess.SqlDataAdapter($"SELECT ProductType FROM tbl_Tags WHERE ProductSerial = N'{inspect.Serial}' ")
                  .Select()
                  .First().ItemArray.First()
                  .ToString();

        var preventElements = dataAccess.SqlDataAdapter($@"SELECT DISTINCT tbl_InspectElement.fld_InspectElementType,
                                    tbl_InspectElement.fld_InspectElementId
                                    FROM tbl_InspectElement CROSS APPLY STRING_SPLIT(tbl_InspectElement.fld_InspectElementProductTypes, '|')
                                    WHERE tbl_InspectElement.fld_InspectElementIsGatePrevent = 1 
                                AND (VALUE IN (N'{productType}') OR tbl_InspectElement.fld_InspectElementProductTypes = N'ALL')");

        bool finalInspectResult = true;

        foreach (DataRow row in preventElements.Select())
        {
            if ((InspectElementType)row.ItemArray[0] == InspectElementType.OneOption)
            {
                foreach (InspectElementValues elementValue in inspect.InspectElementResults)
                {
                    if (elementValue.InspectElementId == (int)row.ItemArray[1])
                    {
                        finalInspectResult = elementValue.InspectElementValue.ToLower().Equals("true");

                        break;
                    }
                }

                if (!finalInspectResult)
                {
                    break;
                }
            }
        }

        inspect.InspectResult = finalInspectResult ? InspectResult.Verfied : InspectResult.NotVerfied;

        #endregion
        #region Inspect
        List<KeyValuePair<string, KeyValuePair<string, object>[]>> commands = new();

        string commandInspect = @" INSERT INTO [dbo].[tbl_Inspect]
           ([fld_InspectDateTime]
           ,[fld_InspectShamsiDate]
           ,[fld_InspectSerial]
           ,[fld_InspectUser]
           ,[fld_InspectResult]
           ,[fld_InspectElementsResults])
     VALUES
           (GetDate()
           ,@Shamsi
           ,@Epc
           ,@User
           ,@Result
           ,@Elements) ";

        List<KeyValuePair<string, object>> parametersInspect = new()
        {
            new("Shamsi", PersianCalendarTools.GregorianToPersian(DateTime.Now)),
            new("Epc", inspect.Serial),
            new("User", inspect.UserId),
            new("Result", inspect.InspectResult),
            new("Elements", results)
        };

        commands.Add(new(commandInspect, parametersInspect.ToArray()));
        #endregion
        bool resultSaveAction = dataAccess.CmdSqlExecuteNonQueryWithTransaction(commands) >= 1;

        if (!resultSaveAction)
        {
            logger.LogInformation("SSaveInspect: " + Environment.NewLine +
                                 $"action save result: {resultSaveAction}");

            return false;
        }

        int inspectId = int.Parse(GetLatestIdOfIdentityTable("tbl_Inspect"));
        commands.Clear();

        #region Inspect Result
        foreach (var result in inspect.InspectElementResults)
        {
            string commandResult = """
                   INSERT INTO [dbo].[tbl_InspectResult]
                  ([fld_InspectResultInspectId]
                  ,[fld_InspectResultInspectElementId]
                  ,[fld_InspectResultValues])
                    VALUES
                  (@InspectId,@ElementId,@Values)
            """;

            List<KeyValuePair<string, object>> parametersResult = new()
            {
                new("InspectId", inspectId),
                new("ElementId", result.InspectElementId),
                new("Values", result.InspectElementValue)
            };

            commands.Add(new(commandResult, parametersResult.ToArray()));
        }

        resultSaveAction = dataAccess.CmdSqlExecuteNonQueryWithTransaction(commands) >= 1;

        if (!resultSaveAction)
        {
            logger.LogInformation("SSaveInspect result: false");
        }
        #endregion

        #region Tags

        string commandTags = """ 
                                    UPDATE tbl_Tags SET Lock = @Lock, 
                                    fld_LastInspectResult = @Result,
                                    fld_InspectActionId = @InspectId WHERE ProductSerial = @Serial 
                                """;

        List<KeyValuePair<string, object>> parametersTags = new()
        {
            new("Result", results),
            new("Lock", inspect.InspectResult != InspectResult.Verfied),
            new("Serial", inspect.Serial),
            new("InspectId", inspectId)
        };

        var resultTags = dataAccess.CmdSqlExecuteNonQuery(commandTags, parametersTags.ToArray());

        logger.LogInformation("SSaveInspect: " + Environment.NewLine +
                             $"action result Tags: {resultTags}");

        #endregion
        return true;
    }

    public List<InspectReportResponse> SReportInspects(InspectReportRequest request)
    {
        List<string> whereList = new();

        whereList.Add(" tbl_Tags.TagRegisterDateTime IS NOT NULL ");

        if (!request.FromDate.Equals("-1"))
        {
            whereList.Add($" N'{request.FromDate}' <= tbl_Inspect.fld_InspectShamsiDate ");
        }

        if (!request.ToDate.Equals("-1"))
        {
            whereList.Add($" N'{request.ToDate}' >= tbl_Inspect.fld_InspectShamsiDate ");
        }

        if (!request.ProductCode.Equals("-1"))
        {
            whereList.Add($" tbl_Products.ProductCode = N'{request.ProductCode}' ");
        }

        if (!request.ProductSerial.Equals("-1"))
        {
            whereList.Add($" tbl_Inspect.fld_InspectSerial = N'{request.ProductSerial}' ");
        }

        if (!request.UserId.Equals("-1"))
        {
            whereList.Add($" tbl_Inspect.fld_InspectUser = N'{request.UserId}' ");
        }

        if (!request.Line.Equals("-1"))
        {
            whereList.Add($" tbl_Tags.fld_ProductPropertyAId = N'{request.Line}' ");
        }

        if (!request.RegCode.Equals("-1"))
        {
            whereList.Add($" tbl_Products.ProductTechnicalCode = N'{request.RegCode}' ");
        }

        if (!request.InspectResult.Equals(-1))
        {
            whereList.Add($" tbl_Inspect.fld_InspectResult = {request.InspectResult} ");
        }

        if (request.ElementFilters.Any())
        {
            List<string> elementWhereList = new();

            foreach (var filter in request.ElementFilters)
            {
                elementWhereList.Add($"(JSON_VALUE(value,'$.InspectElementId') = N'{@filter.InspectElementId}' AND" +
                    $" LOWER(JSON_VALUE(value,'$.InspectElementValue')) = N'{@filter.InspectElementValue}')");
            }

            whereList.Add('(' + string.Join(" OR ", elementWhereList) + ')');
        }

        if (request.DynamicFilters.Any())
        {
            foreach (var filter in request.DynamicFilters)
            {
                whereList.Add($"JSON_VALUE(tbl_Tags.ProductProperties,N'$.\"{filter.Key}\"') = N'{filter.Value}'");
            }
        }

        string command = @"
        SELECT DISTINCT 
            COALESCE((SELECT [Name] 
                      FROM tbl_User 
                      WHERE Id = tbl_Inspect.fld_InspectUser), N'') AS [InspectUsername],
            tbl_Products.ProductTitle AS [ProductName],
            tbl_Products.ProductCode AS [ProductCode],
            tbl_Inspect.fld_InspectDateTime AS [DateTime],
            tbl_Products.ProductTechnicalCode AS [RegCode],
            tbl_Inspect.fld_InspectResult AS [Result],
            tbl_Inspect.fld_InspectId AS [InspectId],
            tbl_Inspect.fld_InspectElementsResults AS [Values],
            tbl_Tags.ProductSerial AS [ProductSerial],
            COALESCE((SELECT fld_ProductPropertyATitle 
                      FROM tbl_ProductPropertyA 
                      WHERE fld_ProductPropertyAId = tbl_Tags.fld_ProductPropertyAId), N'') AS [Line],
            tbl_Tags.TagRegisterDateTime AS [ProductionDateTime],
            tbl_Tags.ProductProperties
        FROM tbl_Inspect
        INNER JOIN tbl_Tags ON tbl_Tags.ProductSerial = tbl_Inspect.fld_InspectSerial
        INNER JOIN tbl_Products ON tbl_Tags.ProductCode = tbl_Products.ProductCode" +
            (request.ElementFilters.Any() ? " CROSS APPLY OPENJSON(tbl_Inspect.fld_InspectElementsResults, '$') " : "")
            + (whereList.Any() ? " WHERE " + string.Join(" AND ", whereList) : "")
            + " ORDER BY tbl_Inspect.fld_InspectDateTime ASC";

        return dataAccess.SqlDataAdapter(command)
                                  .Select()
                                  .Select(row => new InspectReportResponse()
                                  {
                                      InspectUsername = row.ItemArray[0].ToString(),
                                      ProductName = row.ItemArray[1].ToString(),
                                      ProductCode = row.ItemArray[2].ToString(),
                                      DateTime = (DateTime)row.ItemArray[3],
                                      RegCode = row.ItemArray[4].ToString(),
                                      Result = (InspectResult)row.ItemArray[5],
                                      InspectId = (int)row.ItemArray[6],
                                      Values = JsonConvert.DeserializeObject<List<InspectElementValues>>(row.ItemArray[7].ToString()),
                                      ProductSerial = row.ItemArray[8].ToString(),
                                      Line = row.ItemArray[9].ToString(),
                                      ProductionDateTime = (DateTime)row.ItemArray[10],
                                      ProductProperties = row.ItemArray[11].ToString()
                                  }).ToList();
    }

    public List<InspectProductHeader> SReportInspectProducts(InspectProductReportQuery request)
    {
        string whereString = "";

        if (request.FromDate.NotEquals("-1"))
        {
            if (whereString.HasValue())
            {
                whereString += " AND ";
            }

            whereString += $" tbl_Inspect.fld_InspectShamsiDate >=  N'{request.FromDate}' ";
        }

        if (request.ToDate.NotEquals("-1"))
        {
            if (whereString.HasValue())
            {
                whereString += " AND ";
            }

            whereString += $" tbl_Inspect.fld_InspectShamsiDate  < N'{request.ToDate}' ";
        }

        if (request.FromTime.NotEquals("-1"))
        {
            if (whereString.HasValue())
            {
                whereString += " AND ";
            }

            whereString += $" N'{request.FromTime}' <= CAST(fld_InspectDateTime AS Time) ";
        }

        if (request.ToTime.NotEquals("-1"))
        {
            if (whereString.HasValue())
            {
                whereString += " AND ";
            }

            whereString += $" N'{request.ToTime}' > CAST(fld_InspectDateTime AS Time) ";
        }

        if (request.ProductCode.NotEquals("-1"))
        {
            if (whereString.HasValue())
            {
                whereString += " AND ";
            }

            whereString += $" tbl_Tags.ProductCode = N'{request.ProductCode}' ";
        }

        if (request.TechnicalCode.NotEquals("-1"))
        {
            if (whereString.HasValue())
            {
                whereString += " AND ";
            }

            if (request.TechnicalCodeLike)
            {
                whereString += $" tbl_Tags.RegCode Like N'%{request.TechnicalCode}%' ";
            }
            else
            {
                whereString += $" tbl_Tags.RegCode = N'{request.TechnicalCode}' ";
            }
        }

        if (request.Line.NotEquals("-1"))
        {
            if (whereString.HasValue())
            {
                whereString += " AND ";
            }

            whereString += $" tbl_Tags.fld_ProductPropertyAId = N'{request.Line}' ";
        }

        if (request.Size.NotEquals("-1"))
        {
            if (whereString.HasValue())
            {
                whereString += " AND ";
            }

            whereString += $" tbl_Tags.fld_ProductPropertyCId = N'{request.Size}' ";
        }

        if (request.Shift.NotEquals("-1"))
        {
            if (whereString.HasValue())
            {
                whereString += " AND ";
            }

            whereString += $" tbl_Tags.fld_ProductPropertyBId = N'{request.Shift}' ";
        }

        if (request.Qc.NotEquals("-1"))
        {
            if (whereString.HasValue())
            {
                whereString += " AND ";
            }

            whereString += $" tbl_Tags.ProductStatus = N'{request.Qc}' ";
        }

        List<InspectProduct> products = new();

        DataTable dt = new();

        dt.Columns.Add("RegCode");
        dt.Columns.Add("Size");
        dt.Columns.Add("Line");
        dt.Columns.Add("AcceptedSum");
        dt.Columns.Add("AcceptedCount");
        dt.Columns.Add("RejectedCount");
        dt.Columns.Add("RejectedSum");

        string command = $@"
            SELECT
            tbl_Tags.ProductSerial,
            tbl_Tags.RegCode,
            COALESCE(tbl_ProductPropertyC.fld_ProductPropertyCTitle ,N'' )AS [Size],
            COALESCE(tbl_ProductPropertyA.fld_ProductPropertyATitle ,N'')AS [Line],
            tbl_Inspect.fld_InspectResult AS Lock,
            tbl_ProductStatus.ProductStatusTitle as Qc,
            tbl_Tags.ProductCount as [Count],       
            ROW_NUMBER() OVER (PARTITION BY tbl_Tags.ProductSerial ORDER BY tbl_Inspect.fld_InspectDateTime DESC) as [RowNumber]
            FROM   tbl_Inspect INNER JOIN tbl_Tags ON tbl_Inspect.fld_InspectSerial = tbl_Tags.ProductSerial
            INNER JOIN tbl_ProductStatus ON tbl_ProductStatus.ProductStatusCode = tbl_Tags.ProductStatus
            INNER JOIN tbl_ProductPropertyC ON tbl_Tags.fld_ProductPropertyCId = tbl_ProductPropertyC.fld_ProductPropertyCId
            INNER JOIN tbl_ProductPropertyA ON tbl_Tags.fld_ProductPropertyAId = tbl_ProductPropertyA.fld_ProductPropertyAId
              
        ";

        if (whereString.HasValue())
        {
            command += $" WHERE {whereString} ";
        }

        var data = dataAccess.SqlDataAdapter(command).Select();

        List<InspectProductHeader> result = new();

        foreach (DataRow row in data)
        {
            products.Add(new()
            {
                ProductSerial = row.ItemArray[0].ToString(),
                RegCode = row.ItemArray[1].ToString(),
                Size = row.ItemArray[2].ToString(),
                Line = row.ItemArray[3].ToString(),
                Lock = (int)row.ItemArray[4] == 1,
                Qc = row.ItemArray[5].ToString(),
                Count = (decimal)row.ItemArray[6],
                Row = (long)row.ItemArray[7]
            });
        }

        products = products.Where(p => p.Row == 1).ToList();

        List<InspectProduct> accepted = products
            .Where(p => p.Lock)
            .DistinctBy(p => p.ProductSerial).ToList();

        List<InspectProduct> rejected = products
            .Where(p => !p.Lock)
            .DistinctBy(p => p.ProductSerial)
            .ToList();

        foreach (InspectProduct acceptedItem in accepted)
        {
            var header = result.FirstOrDefault(p => p.RegCode == acceptedItem.RegCode
            && p.Size == acceptedItem.Size && p.Line == acceptedItem.Line);

            if (header is null)
            {
                header = new()
                {
                    RegCode = acceptedItem.RegCode,
                    Size = acceptedItem.Size,
                    Line = acceptedItem.Line
                };

                result.Add(header);
            }

            header.AcceptedCount++;

            header.AcceptedSum += acceptedItem.Count;

            var qc = header.Items.FirstOrDefault(p => p.Qc == acceptedItem.Qc);

            if (qc is null)
            {
                qc = new()
                {
                    Qc = acceptedItem.Qc
                };

                header.Items.Add(qc);
            }

            qc.SumCount += acceptedItem.Count;
        }

        foreach (InspectProduct rejectedItem in rejected)
        {
            var header = result.FirstOrDefault(p => p.RegCode == rejectedItem.RegCode
            && p.Size == rejectedItem.Size && p.Line == rejectedItem.Line);

            if (header is null)
            {
                header = new()
                {
                    RegCode = rejectedItem.RegCode,
                    Size = rejectedItem.Size,
                    Line = rejectedItem.Line
                };

                result.Add(header);
            }

            header.RejectedCount++;

            header.RejectedSum += rejectedItem.Count;
        }

        return result;
    }
