    public List<WarehouseDto> SGetWarehousesDestinationListByActionType(int ActionType)
    {
        var tpsList = SGetActionTypes();
        var DestinationWarehouseCodes = tpsList.FirstOrDefault(p => p.Code == ActionType).To.Split(',');

        return mapper.Map<List<WarehouseDto>>(apiContext.Warehouses.Where(p => ((DestinationWarehouseCodes.Length <= 2) ? (p.OperationalType == Convert.ToInt32(DestinationWarehouseCodes[1])) : (p.OperationalType == Convert.ToInt32(DestinationWarehouseCodes[1]) || p.OperationalType == Convert.ToInt32(DestinationWarehouseCodes[2])))));
    }




    public int SSaveWarehouse(WarehouseDto warehouse)
    {
        Warehouse data = new()
        {
            Code = warehouse.DestinationCode,
            Title = warehouse.DestinationTitle,
            OperationalType = (int)warehouse.OperationalType,
            InventoryType = ((int)warehouse.InventoryType).ToString(),
            IsActive = warehouse.IsActive ? 1 : 0,
            IsDefault = warehouse.IsDefault ? 1 : 0,
            Id = warehouse.Id
        };

        var shouldInsert = CheckFieldUniqueness("tbl_Destination", "DestinationCode", warehouse.DestinationCode, "");

        if (shouldInsert == 0)
        {
            apiContext.Warehouses.Add(data);
        }
        else
        {
            apiContext.Warehouses.Update(data);
        }

        if (apiContext.SaveChanges() > 0)
        {
            return data.Id;
        }
        else
        {
            return -1;
        }
    }

