    #region Place
    public List<CeramicAggregateResult> SGetPlaceProductDataBySerials(PlaceProductRequest request)
    {
        var userToken = httpContext.User.GetUserId();

        string getSerialsCommand =
            $"""
            SELECT        tbl_Tags.ProductSerial
            FROM            tbl_Tags RIGHT OUTER JOIN
                                     tbl_UHF_ReaderLog ON tbl_Tags.TagEpc = tbl_UHF_ReaderLog.fld_TagSerial
            WHERE        (tbl_UHF_ReaderLog.fld_InventoryId = '{request.LogGateActionId}') AND (tbl_UHF_ReaderLog.fld_TagSerial <> '000')
            """;

        List<string> oldSerials = dataAccess.SqlDataAdapter(getSerialsCommand).Select().ToList().Select(p => p.ItemArray[0].ToString()).ToList();

        List<string> deleteSerials = oldSerials.Except(request.Serials.Select(p => p.Serial)).ToList();

        List<PlaceSerialDto> insertSerials = request.Serials.ExceptBy(oldSerials, p => p.Serial).ToList();

        if (deleteSerials.Any())
        {
            string deleteUhfLogsCommand =
                @$"
                DELETE tbl_UHF_ReaderLog
                FROM tbl_UHF_ReaderLog 
                LEFT JOIN tbl_Tags 
                  ON tbl_UHF_ReaderLog.fld_TagSerial = tbl_Tags.TagEpc
                WHERE (tbl_UHF_ReaderLog.fld_InventoryId = {request.LogGateActionId} ) 
                    AND (tbl_UHF_ReaderLog.fld_TagSerial <> '000')
                    AND (tbl_Tags.ProductSerial IN('{string.Join("','", deleteSerials)}') )
                ";

            dataAccess.CmdSqlExecuteNonQuery(deleteUhfLogsCommand);
        }

        if (SSaveGateLog(userToken, request.LogGateActionId, request.StationCode, null, null, "1", insertSerials))
        {
            return SCheckDirectPlaceBySecurityGate(request.StationCode, int.Parse(request.LogGateActionId), request.SourceWarehouse);
        }
        else
        {
            return new();
        }
    }

    public List<CeramicAggregateResult> SCheckDirectPlaceBySecurityGate(string gate, int gateOperationCode, string sourceWarehouse)
    {
        var whereString = string.Empty;
        var innerWhereString = string.Empty;
        if (!gate.Equals("-1"))
        {
            whereString += " AND (fld_Reader_Gate = N'" + gate + "') ";
            innerWhereString += " AND (U.fld_Reader_Gate = N'" + gate + "') ";
        }

        if (!gateOperationCode.Equals(-1))
        {
            whereString += " AND (fld_InventoryId = " + gateOperationCode + ")";
            innerWhereString += " AND (U.fld_InventoryId = " + gateOperationCode + ")";
        }

        var cmd =
            @$"SELECT DISTINCT 
                         '0' AS [Desc], tbl_UHF_ReaderLog.fld_TagSerial AS Epc, COALESCE (tbl_Tags.ProductSerial, N'-1') AS ProductSerial, tbl_Tags.ProductCode, tbl_Tags.ProductName, tbl_Tags.RegCode, 1 AS Count, 
                         COALESCE (tbl_Tags.ProductCount, 0) AS SumValue,
                             (SELECT        MAX(fld_TagRead_DateTime) AS Expr1
                               FROM            tbl_UHF_ReaderLog AS U 
             WHERE U.fld_TagSerial is not null {innerWhereString} ) AS MaxDate, tbl_Destination.DestinationType, COALESCE (tbl_Tags.Freeze, 0) AS Freeze, COALESCE (tbl_Tags.Lock, 0) AS Lock, COALESCE (tbl_Tags.fld_InspectActionId, N'0') 
                         AS fld_InspectActionId, COALESCE (tbl_Products.ProductUnit, N'') AS ProductUnit, COALESCE (tbl_Tags.TagInDestinationId, N'') AS SourceWarehouseCode,
                         COALESCE((SELECT tbl_Station.fld_StationName FROM tbl_Station 
                            WHERE tbl_Station.fld_StationCode = tbl_UHF_ReaderLog.fld_Reader_Gate),N'') AS StationName
FROM            tbl_Destination RIGHT OUTER JOIN
                         tbl_Tags ON tbl_Destination.DestinationCode = tbl_Tags.TagInDestinationId RIGHT OUTER JOIN
                         tbl_UHF_ReaderLog ON tbl_Tags.TagEpc = tbl_UHF_ReaderLog.fld_TagSerial LEFT OUTER JOIN
                         tbl_Products ON tbl_Tags.ProductCode = tbl_Products.ProductCode
WHERE        (tbl_UHF_ReaderLog.fld_TagSerial IS NOT NULL) AND  (tbl_UHF_ReaderLog.fld_TagSerial <>'000')  {whereString} ";

        //9 DestinationType  10 freez  11 lock  12 InspectActionId 14 TagInDestinationId(sourceWarehouseCode)
        var finalList = new List<CeramicAggregateResult>();
        var strTags = string.Empty;
        var listTag = dataAccess.SqlDataAdapter(cmd, 120);
        decimal sumValueProduct = 0;
        string MaxDate = "";
        decimal countProduct = 0;

        foreach (DataRow tag in listTag.Rows)
        {
            if (tag[2].ToString() != "-1") //  registered
            {
                if (!string.IsNullOrEmpty(strTags))
                    strTags += ",";
                strTags += ($"N'{tag[1].ToString()}'");
                sumValueProduct += decimal.Parse(tag[7].ToString());
                countProduct++;
                MaxDate = tag[8].ToString();

                var product = new CeramicAggregateResult()
                {
                    Error = "4",
                    ProductCode = tag[3].ToString(),
                    ProductCount = Convert.ToDecimal(tag[6].ToString()),
                    ProductName = tag[4].ToString(),
                    ProductSerial = tag[2].ToString(),
                    SumCount = Convert.ToDecimal(tag[7].ToString()),
                    MaxDate = "",
                    Regcode = tag[5].ToString(),
                    ProductUnit = tag[13].ToString(),
                    SourceWarehouseCode = tag[14].ToString(),
                    StationName = tag[15].ToString()
                };

                if (tag[10].ToString() != "1") // Freeze
                {
                    if (!bool.Parse(configuration.GetSection("ProjectConfigs").GetSection("WmsConfigs")["QcCheck"]) || tag[12].ToString() != "0") // Not Inspect
                    {
                        if (tag[11].ToString() != "1") // Lock
                        {
                            if (tag[14].ToString() == sourceWarehouse)
                            {
                                product.TagEpc = "";
                            }
                            else // moghayerat mabda
                            {
                                product.TagEpc = "کالا در مبدا انتخاب شده نیست";
                            }
                        }
                        else
                        {
                            product.TagEpc = "بازرسی کالا مردود است";
                        }
                    }
                    else
                    {
                        product.TagEpc = "کالا بازرسی نشده است";
                    }
                }
                else
                {
                    product.TagEpc = "کالا فریز شده است";
                }

                finalList.Add(product);
            }
            else
            {
                if (tag[1].ToString().Contains("E2000"))
                {
                    finalList.Add(new CeramicAggregateResult()
                    {
                        Error = "4",
                        ProductCode = "",
                        ProductCount = 0,
                        ProductName = "",
                        ProductSerial = "",
                        SumCount = 0,
                        TagEpc = tag[1].ToString() + " تگ ثبت نشده ",
                        MaxDate = "",
                        StationName = ""
                    });
                }
            }

        }


        finalList.Add(new CeramicAggregateResult()
        {
            Error = "1",
            TagEpc = "",
            ProductCode = "",
            ProductSerial = "",
            ProductName = "",
            ProductCount = countProduct,
            SumCount = sumValueProduct,
            MaxDate = MaxDate
        });
        if (string.IsNullOrEmpty(strTags))
        {
            return finalList;
        }
        var cmdGetTajamoee =
            @" SELECT DISTINCT tbl_Tags.ProductCode, tbl_Products.ProductTitle, SUM(tbl_Tags.ProductCount) AS SumValue, COUNT(tbl_Tags.ProductSerial) AS Count, tbl_Products.ProductUnit,
                               COALESCE(String_Agg(tbl_Tags.TagInDestinationId,','),N'') as SourceWarehouseCode
FROM   tbl_Tags LEFT OUTER JOIN
             tbl_Products ON tbl_Tags.ProductCode = tbl_Products.ProductCode
 WHERE TagEpc IN(" + strTags + ") GROUP BY tbl_Tags.ProductCode, tbl_Products.ProductTitle,tbl_Products.ProductUnit  ";
        logger.LogInformation("SPSecurityGateReport",
    new KeyValuePair<string, string>("gate", gate),
    new KeyValuePair<string, string>("gateOperationCode", gateOperationCode.ToString()),
    new KeyValuePair<string, string>("cmd", cmd),
    new KeyValuePair<string, string>("cmdGetTajamoee", cmdGetTajamoee)
    );


        var listTajamoee = dataAccess.SqlDataAdapter(cmdGetTajamoee);
        foreach (DataRow Rowdata in listTajamoee.Rows)
        {
            var data = new CeramicAggregateResult()
            {
                Error = "3",
                ProductCode = Rowdata[0].ToString(),
                ProductSerial = "",
                ProductName = Rowdata[1].ToString(),
                ProductCount = decimal.Parse(Rowdata[2].ToString()),
                SumCount = decimal.Parse(Rowdata[3].ToString()),
                MaxDate = MaxDate,
                ProductUnit = Rowdata[4].ToString(),
                SourceWarehouseCode = Rowdata[5].ToString().Split(',').First()
            };

            finalList.Add(data);
        }

        return finalList;
    }

