    public DataTable SGetAllPlaces()
    {
        string command = @$"
            SELECT MovementActionId AS PlaceId ,
            COALESCE(CONCAT(MovementActionDate,N'  ' ,MovementActionTime) ,N'') as [DateTime], 
            COALESCE (UserName,N'') AS UserName  ,
            MovementActionDestinationId AS [Destination],
            COALESCE (DestinationTitle,N'') AS DestinationWarehouseTitle , 
            COALESCE (MovementActionStore,N'') AS DestinationWarehouseCode,
            COALESCE(ZoneCapacity ,0)AS DestinationCapacity, 
            COALESCE(ZoneCapacity,0)-COALESCE(ZoneOccupiedCapacity,0) AS DestinationFreeCapacity,
            COALESCE(MovementActionDocumentId,N'') AS DocumentId
            FROM tbl_MovementActions LEFT JOIN tbl_Destination ON MovementActionStore = tbl_Destination.DestinationCode
            LEFT JOIN tbl_User ON MovementActionUserId = Id
            LEFT JOIN tbl_Zones ON MovementActionDestinationId = ZoneCode AND DestinationCode = ZoneStoreCode
            Order by  MovementActionId DESC";

        return dataAccess.SqlDataAdapter(command);
    }

    public DataTable SGetPlaceItems(string placeId)
    {
        string command = @$"
             SELECT	DISTINCT tbl_Tags.ProductCode
            	   , tbl_Tags.ProductSerial
            	   , tbl_Tags.ProductName
            	   , tbl_Tags.RegCode 
                   , tbl_Tags.ProductCount as [Count]
            	   , COALESCE((SELECT Sum(InnerJoin.ProductCount) FROM tbl_Tags AS [InnerJoin] WHERE [InnerJoin].TagZone = tbl_Tags.TagZone AND [InnerJoin].TagInDestinationId = tbl_Tags.TagInDestinationId GROUP BY [InnerJoin].TagZone, [InnerJoin].TagInDestinationId ),0) as [SumCountInFrom]
            	   , COALESCE((SELECT Sum([InnerJoin].ProductCount) FROM tbl_Tags AS [InnerJoin] WHERE [InnerJoin].ProductCode = tbl_Tags.ProductCode ) ,0) as [SumCountInDestination]
            FROM  tbl_TagsMovement  Right JOIN tbl_Tags  ON tbl_Tags.ProductSerial = tbl_TagsMovement.ProductSerial
            WHERE RMovementActionId = N'{placeId}' OR HMovementActionId = N'{placeId}'";

        return dataAccess.SqlDataAdapter(command);
    }

    public DataTable GetPlaceByActionId(string actionId)
    {
        string command =
            $"""
            SELECT        tbl_MovementActions.MovementActionId, tbl_MovementActions.MovementActionDate, tbl_MovementActions.MovementActionTime, tbl_ActionTypes.fld_ActionTypeTitle as ActionTypeTitle, tbl_Destination.DestinationTitle, 
                          COALESCE(tbl_MovementActions.MovementActionDocumentId,N'0') as MovementActionDocumentId, COALESCE(tbl_MovementActions.MovementActionDesc,N'') as MovementActionDesc,tbl_TagsMovement.ProductSerial,
                          tbl_Tags.ProductCode, tbl_Tags.ProductName, tbl_Tags.ProductCount, tbl_Tags.RegCode
            FROM          tbl_Tags RIGHT OUTER JOIN
                                     tbl_TagsMovement ON tbl_Tags.ProductSerial = tbl_TagsMovement.ProductSerial RIGHT OUTER JOIN
                                     tbl_MovementActions LEFT OUTER JOIN
                                     tbl_Destination ON tbl_MovementActions.MovementActionDestinationId = tbl_Destination.DestinationCode LEFT OUTER JOIN
                                     tbl_ActionTypes ON tbl_MovementActions.MovementActionTp = tbl_ActionTypes.fld_ActionTypeId ON tbl_TagsMovement.RMovementActionId = tbl_MovementActions.MovementActionId
            WHERE        (tbl_MovementActions.MovementActionId = N'{actionId}')
            """;

        return dataAccess.SqlDataAdapter(command);
    }

