    public DataTable SPSearchProductPlace(ProductPlaceFilterRequest request)
    {
        string whereString = GetWhereStringPlace(request);

        if (whereString.HasValue())
        {
            whereString = (" WHERE " + whereString);
        }

        string command = $@"SELECT        COALESCE(tbl_Destination.DestinationTitle,N'') AS Warehouse, tbl_Tags.ProductCode, tbl_Tags.RegCode, tbl_Tags.ProductName, tbl_Tags.ProductSerial, 
                         COALESCE (tbl_ProductType.ProductTypeTitle, N'') AS ProductType, COALESCE (tbl_Zones.ZoneTitle, N'') AS ZoneTitle,tbl_Tags.ProductCount
FROM            tbl_Tags LEFT OUTER JOIN
                         tbl_ProductType ON tbl_ProductType.ProductTypeCode = tbl_Tags.ProductType LEFT OUTER JOIN
                         tbl_Destination ON tbl_Tags.TagInDestinationId = tbl_Destination.DestinationCode LEFT OUTER JOIN
                         tbl_Zones ON tbl_Tags.TagZone = tbl_Zones.ZoneCode" + (string.IsNullOrEmpty(whereString) ? "" : whereString);

        return dataAccess.SqlDataAdapter(command);

        string GetWhereStringPlace(ProductPlaceFilterRequest search)
        {
            var whereString = string.Empty;

            if (!search.ProductCode.Equals("-1"))
            {
                if (!string.IsNullOrEmpty(whereString))
                {
                    whereString += " AND ";
                }

                whereString += $"tbl_tags.ProductCode = N'{search.ProductCode}' ";
            }

            if (!search.RegCode.Equals("-1"))
            {
                if (!string.IsNullOrEmpty(whereString))
                {
                    whereString += " AND ";
                }

                whereString += $"tbl_Tags.RegCode = N'{search.RegCode}' ";
            }

            if (!search.SourceWarehouseCode.Equals("-1"))
            {
                if (!string.IsNullOrEmpty(whereString))
                {
                    whereString += " AND ";
                }

                whereString += $"tbl_Destination.DestinationCode = N'{search.SourceWarehouseCode}' ";
            }

            if (!search.ProductName.Equals("-1"))
            {
                if (!string.IsNullOrEmpty(whereString))
                {
                    whereString += " AND ";
                }

                whereString += $"tbl_tags.ProductName LIKE N'%{search.ProductName}%' ";
            }

            return whereString;
        }
    }

    public DataTable SGetLastUhfGateActionsById(GetAllUhfReaderLogByActionIdQuery action)
    {
        string UHFGateActionDestinationCode = "";
        string UHFGateActionSourceCode = "";
        string GateActionType = "";
        List<string> wheres = new();

        wheres.Add("UHFHeader.fld_UHFReaderLogHeaderId IS NOT NULL");

        if (action.UhfGateActionId.HasValue())
        {
            wheres.Add($"UHFHeader.fld_UHFReaderLogHeaderId = N'{action.UhfGateActionId}'");
        }

        if (action.UhfGateCode.HasValue())
        {
            wheres.Add($"UHFHeader.fld_StationCode = N'{action.UhfGateCode}'");
        }

        if (action.UhfGateMovementActionDestination.HasValue())
        {
            UHFGateActionDestinationCode = action.UhfGateMovementActionDestination;
        }

        if (action.UhfGateMovementActionFrom.HasValue())
        {
            UHFGateActionSourceCode = action.UhfGateMovementActionFrom;
        }

        if (UHFGateActionDestinationCode != "" && UHFGateActionSourceCode != "")
        {
            GateActionType = GetActionType(UHFGateActionSourceCode, UHFGateActionDestinationCode).ToString();

            if (GateActionType != "" && GateActionType != "0")
            {
                wheres.Add($"( ( UHFHeader.fld_ActionType = N'{GateActionType}') OR (UHFHeader.fld_ActionType = N'_DETECT_PRODUCT_AND_SEND_TO_WEB_') )");
            }
        }

        string command = $"""
            SELECT *
            FROM
            (
                SELECT TOP (100) UHFHeader.fld_UHFReaderLogHeaderId AS Code
            	,(SELECT COUNT(ReaderLog.fld_TagSerial) 
            		FROM tbl_UHF_ReaderLog AS ReaderLog
            		WHERE (ReaderLog.fld_InventoryId = UHFHeader.fld_UHFReaderLogHeaderId
            		AND ReaderLog.fld_TagSerial <> '000')
            	) AS [Count]
            	,COALESCE((SELECT TOP (1) ReaderLog.fld_TagRead_DateTime
                FROM tbl_UHF_ReaderLog AS ReaderLog
                WHERE (ReaderLog.fld_InventoryId = UHFHeader.fld_UHFReaderLogHeaderId)
                ORDER BY ReaderLog.fld_TagRead_DateTime DESC), N'') AS DateTime
            	,CASE UHFHeader.fld_HeaderUsedStatus  WHEN 2 THEN N'ناقص' WHEN 1 THEN N'ثبت شده' ELSE N'ثبت نشده' END AS Status
                ,COALESCE(UHFHeader.fld_StationCode ,N'') as GateCode
            	,COALESCE((SELECT tbl_Station.fld_StationName FROM tbl_Station 
            	WHERE tbl_Station.fld_StationCode = UHFHeader.fld_StationCode),N'') AS StationName
            FROM tbl_UHFReaderLogHeader AS UHFHeader

            {(wheres.Any() ? "WHERE " + string.Join(" AND ", wheres) : string.Empty)}
    
            ORDER BY UHFHeader.fld_UHFReaderLogHeaderId DESC   ) AS [NESTED]

            WHERE [NESTED].[Count] > 0
            """;

        logger.LogInformation("SGetLastUhfGateActionsById" + Environment.NewLine + JsonConvert.SerializeObject(action) + " Command:" + command);

        return dataAccess.SqlDataAdapter(command);
    }

