    public int SUpdateUhfStatuses()
    {
        List<string> commands = new();

        //if(UhfLogAction used in any movementAction) => SET UHF.MovementActionId = Movement.MovementActionId;
        commands.Add("""
            UPDATE UHF
            SET UHF.MovementActionId = Movement.MovementActionId
            FROM tbl_UHF_ReaderLog UHF INNER JOIN 
            	tbl_MovementActions Movement ON CAST(UHF.fld_InventoryId AS nvarchar(256)) =  Movement.MovementActionUHFLogId
            WHERE (UHF.MovementActionId IS NULL OR UHF.MovementActionId = '')
            AND Movement.MovementActionUHFLogId IS NOT NULL AND Movement.MovementActionUHFLogId <> '' 
            """);

        //1. Update fld_HeaderUsedStatus to 1
        commands.Add("""
            UPDATE tbl_UHFReaderLogHeader
            SET fld_HeaderUsedStatus = 1
            WHERE fld_UHFReaderLogHeaderId IN (
                SELECT DISTINCT fld_InventoryId
                FROM tbl_UHF_ReaderLog
            )
            AND NOT EXISTS (
                SELECT 1
                FROM tbl_UHF_ReaderLog
                WHERE tbl_UHFReaderLogHeader.fld_UHFReaderLogHeaderId = tbl_UHF_ReaderLog.fld_InventoryId
            	AND (MovementActionId IS NULL OR MovementActionId = '')
            	AND fld_TagSerial != N'000'
            );
            """);

        //2. Update fld_UsedStatus to 0
        commands.Add("""
            UPDATE tbl_UHFReaderLogHeader
            SET fld_HeaderUsedStatus = 0
            WHERE fld_UHFReaderLogHeaderId IN (
                SELECT DISTINCT fld_InventoryId
                FROM tbl_UHF_ReaderLog
            )
            AND NOT EXISTS (
                SELECT 1
                FROM tbl_UHF_ReaderLog
                WHERE tbl_UHFReaderLogHeader.fld_UHFReaderLogHeaderId = tbl_UHF_ReaderLog.fld_InventoryId
            	AND (MovementActionId IS NOT NULL OR MovementActionId <> '')
            	AND fld_TagSerial != N'000'
            );
            """);

        //3. Update fld_UsedStatus to 2
        commands.Add("""
            UPDATE tbl_UHFReaderLogHeader
            SET fld_HeaderUsedStatus = 2
            WHERE fld_UHFReaderLogHeaderId IN (
                SELECT DISTINCT fld_InventoryId
                FROM tbl_UHF_ReaderLog
            )
            AND EXISTS (
                SELECT 1
                FROM tbl_UHF_ReaderLog
                WHERE tbl_UHFReaderLogHeader.fld_UHFReaderLogHeaderId = tbl_UHF_ReaderLog.fld_InventoryId
            	AND (MovementActionId IS NOT NULL OR MovementActionId <> '')
            	AND fld_TagSerial != N'000'
            )
            AND EXISTS (
                SELECT 1
                FROM tbl_UHF_ReaderLog
                WHERE tbl_UHFReaderLogHeader.fld_UHFReaderLogHeaderId = tbl_UHF_ReaderLog.fld_InventoryId
                AND (MovementActionId IS NULL OR MovementActionId = '')
            	AND fld_TagSerial != N'000'
            );
            """);

        var childrenCommands = new List<KeyValuePair<string, KeyValuePair<string, object>[]>>();

        var parameters = new List<KeyValuePair<string, object>>();

        foreach (var command in commands)
        {
            childrenCommands.Add(new(command, parameters.ToArray()));
        }

        return sqlDataAccess.CmdSqlExecuteNonQueryWithTransaction(childrenCommands);
    }

