    #region Document Methods For Devices
    public DocumentHeader SGetDocumentData(string documentKey, string documentType)
    {
        string userId = httpContext.User.GetUserId();

        DocumentHeader document = apiContext.DocumentHeaders
            .Include(header => header.DocumentItems
                                                .Where(p => p.Key == documentKey &&
                                                           (p.DocumentType == documentType ||
                                                            p.DocumentType1 == documentType ||
                                                            p.DocumentType2 == documentType)
                                                       ))
            .Where(header => header.Key == documentKey &&
                            (header.DocumentType == documentType ||
                             header.DocumentType1 == documentType ||
                             header.DocumentType2 == documentType)
                   ).FirstOrDefault();

        var permitedDocStatus = apiContext.ActionTypes.FirstOrDefault(p => p.Code == int.Parse(documentType))
                                                      ?.DocStatusPermitted;
        if (document is not null)
        {
            if (permitedDocStatus.Equals("0"))
            {
                return document;
            }
            else
            {
                foreach (var status in permitedDocStatus.Split(','))
                {
                    if (document.DocumentStatusId == int.Parse(status))
                    {
                        return document;
                    }
                }
            }
        }

        return null;
    }

    public List<DocumentHeader> SGetDocumentsByDocType(string documentType, int? limit = null)
    {
        string userId = httpContext.User.GetUserId();

        var query = apiContext.DocumentHeaders.AsQueryable();

        query = query.Include(header => header.DocumentItems
        .Where(p => p.DocumentType == documentType || p.DocumentType1 == documentType
                                                             || p.DocumentType2 == documentType))
            .Where(p => (p.DocumentType == documentType
            || p.DocumentType1 == documentType
            || p.DocumentType2 == documentType)
           );

        if (limit is not null)
        {
            query = query.OrderByDescending(p => p.Id).Take((int)limit).AsQueryable();
        }

        var documents = query.ToList();

        if (documents.Any())
        {
            var permitedDocStatus = string.Empty;

            var actionTypes = apiContext.ActionTypes.Where(p => p.Code == int.Parse(documentType));

            if (actionTypes.Any())
            {
                permitedDocStatus = actionTypes.First().DocStatusPermitted;
            }

            if (permitedDocStatus.Equals("0"))
            {
                return documents;
            }
            else
            {
                List<DocumentHeader> result = new();

                foreach (var doc in documents)
                {
                    foreach (var status in permitedDocStatus.Split(','))
                    {
                        if (doc.DocumentStatusId == int.Parse(status))
                        {
                            result.Add(doc);
                        }
                    }
                }

                return result;
            }
        }

        return null;
    }
