    #region Dynamic Document
    public bool SCheckCustomerDocumentAdd(string doc)
    {
        DataTable _dtResult = new();

        DateTime? lastLog = null;

        var jobLogRows = dataAccess.SqlDataAdapter($" SELECT TOP(1) fld_JobLogValue FROM tbl_JobLog WHERE fld_JobLogType = 1 AND fld_JobLogValue IS NOT NULL AND fld_JobLogEventId = N'{doc}' ORDER BY fld_JobLogId DESC ")
                                            .Select();

        if (jobLogRows.Any())
        {
            // if below line of code throws exception, check type of fld_JobLogValue in database for being datetime
            lastLog = (DateTime)jobLogRows.First().ItemArray[0];
        }

        var section = configuration.GetSection("ProjectConfigs")
                                                     .GetSection("WmsConfigs")
                                                     .GetSection("CustomerData")
                                                     .GetSection(doc);

        string command = section["Command"];

        // if below line of code throws exception because of lastLog.Value nullation, add a fake record with this eventid and type
        command += $" WHERE {section["Field_Check"]} > CAST(N'{lastLog.Value.AddSeconds(1)}' AS DATETIME) ORDER BY {section["Field_Order"]} DESC ";

        _dtResult = dataAccess.SqlDataAdapter(command,
                    configuration.GetConnectionString(doc));

        List<string> usedDocs = new();

        var rows = _dtResult.Select();

        string maxCheckValue = "0";

        foreach (DataRow row in _dtResult.Rows)
        {
            string documentId = "";

            string rowCheckValue = "0";

            foreach (DataColumn column in _dtResult.Columns)
            {
                if (column.ColumnName == section["Field_Key"])
                {
                    documentId = row[column].ToString();
                }

                if (column.ColumnName == section["Field_Check"])
                {
                    rowCheckValue = row[column].ToString();
                }
            }

            if (maxCheckValue == "0")
            {
                maxCheckValue = rowCheckValue;
            }

            if (usedDocs.Any(p => p.Equals(documentId)))
            {
                continue;
            }

            usedDocs.Add(documentId);

            if (!SSaveDynamicApi(documentId, doc, ""))
            {
                continue;
            }
        }

        string commandJobLog = string.Empty;

        if (maxCheckValue == "0")
        {
            commandJobLog = @$" INSERT INTO tbl_JobLog (fld_JobLogType,fld_JobLogDateTime,fld_JobLogDate,fld_JobLogTime,fld_JobLogValue,fld_JobLogEventId) 
                                   VALUES (1,GETDATE(),dbo.GeorgianDateToJalaliDate(GETDATE()),FORMAT(GETDATE(), 'HH:mm'),NULL,N'{doc}')";
        }
        else
        {
            commandJobLog = @$" INSERT INTO tbl_JobLog (fld_JobLogType,fld_JobLogDateTime,fld_JobLogDate,fld_JobLogTime,fld_JobLogValue,fld_JobLogEventId) 
                                   VALUES (1,GETDATE(),dbo.GeorgianDateToJalaliDate(GETDATE()),FORMAT(GETDATE(), 'HH:mm'),CAST(N'{maxCheckValue}' AS DATETIME),N'{doc}')";
        }

        bool resultSaveJobLog = dataAccess.CmdSqlExecuteNonQuery(commandJobLog) > 0;

        logger.LogInformation("SCheckCustomerDocumentAdd" + Environment.NewLine
                            + "resultSaveJobLog:" + resultSaveJobLog);

        return true;
    }

    public bool SSaveDynamicApi(string documentKey, string doc, string userToken)
    {
        var type = configuration[$"ProjectConfigs:WmsConfigs:CustomerData:{doc}:Type"];

        var type1 = configuration[$"ProjectConfigs:WmsConfigs:CustomerData:{doc}:Type1"] ?? "0";

        var type2 = configuration[$"ProjectConfigs:WmsConfigs:CustomerData:{doc}:Type2"] ?? "0";

        int docCheckType = 0;

        if (doc.HasValue())
        {
            if (int.TryParse(configuration[$"ProjectConfigs:WmsConfigs:CustomerData:{doc}:RemainCheckType"], out int remainCheck))
            {
                docCheckType = remainCheck;
            }
        }

        List<string> types = new()
        {   type,
            type1,
            type2
        };

        DataTable data = SGetDocumentDataFromCustomerDB(documentKey, doc);

        var originalFileName = "Api_" + documentKey + Guid.NewGuid().ToString().Substring(0, 6);

        string jsonString = JsonConvert.SerializeObject(data);

        logger.LogInformation("SSaveDynamicApi:" + Environment.NewLine
                      + $"documentKey:{documentKey}" + Environment.NewLine
                      + $"data:{jsonString}" + Environment.NewLine
                      + $"userId:{userToken}");

        JArray jsonArray = JArray.Parse(jsonString);

        List<InputFileData> inputs = new();

        foreach (var item in jsonArray)
        {
            inputs.Add(new()
            {
                DateTime = DateTime.Now,
                FileName = originalFileName,
                Type = type.ToString(),
                Type1 = type1.ToString(),
                Type2 = type2.ToString(),
                Data = JsonConvert.SerializeObject(item),
                User = userToken
            });
        }

        apiContext.AddRange(inputs);

        if (apiContext.SaveChanges() > 0)
        {
            return SDocumentDataFromInputFile(originalFileName, string.Join(',', types), docCheckType);
        }

        return false;
    }

    public DataTable SGetDocumentDataFromCustomerDB(string documentId, string doc)
    {
        DataTable _dtResult = new();

        var section = configuration.GetSection("ProjectConfigs")
                                   .GetSection("WmsConfigs")
                                   .GetSection("CustomerData")
                                   .GetSection(doc);

        string command = string.Format(section["Command"]);

        string Key = string.Format(section["Field_Key"]);

        if (!int.TryParse(documentId, out int intValue))
        {
            documentId = $"'{documentId}'";
        }

        command += $" where {Key}  in ( {documentId} ) ORDER BY {section["Field_Order"]} DESC ";

        _dtResult = dataAccess.SqlDataAdapter(command, 300,
                    configuration.GetConnectionString(doc));

        return _dtResult;
    }

    public int SConvertDataFromJArrayToJToken(string documentType)
    {
        var documents = apiContext.DocumentHeaders.Where(p => p.DocumentType == documentType).ToList();

        var documentItems = apiContext.DocumentItems.Where(p => p.DocumentType == documentType).ToList();

        List<DocumentHeader> finalHeaders = new();

        List<DocumentItem> finalItems = new();

        foreach (var header in documents)
        {
            dynamic headerDataExo = new System.Dynamic.ExpandoObject();

            var value = string.Empty;

            if (header.HeaderData.StartsWith('['))
            {
                foreach (JObject item in JToken.Parse(header.HeaderData).Children<JObject>())
                {
                    foreach (JProperty prop in item.Properties())
                    {
                        try
                        {
                            ((IDictionary<String, Object>)headerDataExo).Add(prop.Name, prop.Value);
                        }
                        catch
                        {
                            break;
                        }
                    }
                }

                header.HeaderData = Newtonsoft.Json.JsonConvert.SerializeObject(headerDataExo);

                finalHeaders.Add(header);

            }
        }

        foreach (var docItem in documentItems)
        {
            dynamic itemDataExo = new System.Dynamic.ExpandoObject();

            var value = string.Empty;
            if (docItem.ItemData.StartsWith('['))
            {
                foreach (JObject item in JToken.Parse(docItem.ItemData).Children<JObject>())
                {
                    foreach (JProperty prop in item.Properties())
                    {
                        try
                        {
                            ((IDictionary<String, Object>)itemDataExo).Add(prop.Name, prop.Value);
                        }
                        catch
                        {
                            break;
                        }
                    }
                }

                docItem.ItemData = Newtonsoft.Json.JsonConvert.SerializeObject(itemDataExo);

                finalItems.Add(docItem);
            }
        }

        apiContext.UpdateRange(finalHeaders);

        apiContext.UpdateRange(finalItems);

        return apiContext.SaveChanges();
    }

    public bool SSaveDynamicExcel(string path, string fileName, string originalFileName, string type, string documentType, int docCheckType)
    {
        string userId = httpContext.User.GetUserId();

        DataTable data = DataTableTools.ReadExcelDataOutDataTable($"{path}\\{fileName}");

        string jsonString = JsonConvert.SerializeObject(data);

        JArray jsonArray = JArray.Parse(jsonString);

        List<InputFileData> inputs = new();

        foreach (var item in jsonArray)
        {
            inputs.Add(new()
            {
                DateTime = DateTime.Now,
                FileName = originalFileName,
                Type = type,
                Data = JsonConvert.SerializeObject(item),
                User = userId
            });
        }

        apiContext.BulkInsert(inputs);

        return SDocumentDataFromInputFile(originalFileName, documentType, docCheckType);
    }

    public bool SCheckUniqueFileName(string originalFileName, string type)
    {
        return apiContext.InputFileDatas
                         .Any(file => file.FileName == originalFileName && file.Type == type);
    }

    public bool SSaveDynamicManual(SaveDocumentCommand command)
    {
        string userToken = httpContext.User.GetUserId();

        var originalFileName = "Manual_" + command.DocumentKey + Guid.NewGuid().ToString().Substring(0, 6);

        command.DocumentType = command.DocumentType ?? "0";

        command.DocumentType1 = command.DocumentType1 ?? "0";

        command.DocumentType2 = command.DocumentType2 ?? "0";

        List<InputFileData> inputs = new();

        foreach (var data in command.DocumentJsonData)
        {
            var dataJtoken = JToken.Parse(data);

            inputs.Add(new()
            {
                DateTime = DateTime.Now,
                FileName = originalFileName,
                Type = command.DocumentType,
                Type1 = command.DocumentType1,
                Type2 = command.DocumentType2,
                Data = dataJtoken.ToString(),
                User = userToken
            });
        }

        apiContext.AddRange(inputs);

        if (apiContext.SaveChanges() > 0)
        {
            return SDocumentDataFromInputFile(originalFileName,
                command.DocumentType + ',' + command.DocumentType1 + ',' + command.DocumentType2, command.DocumentCheckType ?? 0);
        }

        return false;
    }

    //Translate Method
    public bool SDocumentDataFromInputFile(string fileName, string documentType, int docCheckType = 0)
    {
        int activeStatus = SGetFirstDocumentStatus();

        string documentMainType = documentType.Split(',').FirstOrDefault() ?? "0";

        string documentType1 = documentType.Split(',').Skip(1).FirstOrDefault() ?? "0";

        string documentType2 = documentType.Split(',').Skip(2).FirstOrDefault() ?? "0";

        List<InputFileData>? inputExcelRows = apiContext.InputFileDatas.Where(p => p.FileName == fileName).ToList();

        List<DynamicField> dynamicFields = apiContext.DynamicFields.Where(p => p.ActionType == int.Parse(documentMainType)).ToList();

        if (docCheckType == 0)
        {
            if (int.TryParse(configuration["ProjectConfigs:WmsConfigs:DocumentRemain"], out int remainCheck))
            {
                docCheckType = remainCheck;
            }
            else
            {
                docCheckType = 1;
            }
        }

        if (inputExcelRows.Any())
        {
            DocumentHeader documentHeader = new()
            {
                FileName = fileName,
                UserId = inputExcelRows[0].User,
                ImportDateTime = inputExcelRows[0].DateTime,
                DocumentStatusId = activeStatus,
                DocumentType = documentMainType,
                DocumentType1 = documentType1,
                DocumentType2 = documentType2,
                Description = "",
                ImportType = 0,
                Parent = "0",
                AggStatus = 1,
                DocumentCheckType = docCheckType,
                DocumentItems = new List<DocumentItem>()
            };


            GetDocumentDataFromInput(documentHeader);

            if (!SIsDocumentUpdateAllowed(documentHeader.Key, documentMainType))
            {
                logger.LogInformation("SDocumentDataFromInputFile" + Environment.NewLine +
                      $"fileName:{fileName}, documentType:{documentType} , UpdateNotPermited!");

                return false;
            }
            else
            {
                return PrepareInsertDocument(documentHeader);
            }
        }

        return false;

        bool PrepareInsertDocument(DocumentHeader documentHeader)
        {
            apiContext.DocumentHeaders.Where(p => p.Key == documentHeader.Key
                                          && p.DocumentType == documentMainType)
                                      .ExecuteDelete();

            apiContext.DocumentItems.Where(p => p.Key == documentHeader.Key
                                        && p.DocumentType == documentMainType)
                                    .ExecuteDelete();

            apiContext.Add(documentHeader);

            if (apiContext.SaveChanges() > 0)
            {
                List<DocumentKeyTypeDto> keyTypes = new()
                        {
                            new()
                            {
                                Key = documentHeader.Key,
                                Type = documentHeader.DocumentType
                            }
                        };

                documentLog.SLogDocumentEvents(new()
                {
                    DocKeyTypes = keyTypes,
                    EventType = DocumentEventType.InsertDocument,
                    Status = activeStatus,
                    UserId = httpContext.User.GetUserId() ?? "Job"
                });

                return true;
            }

            return false;
        }

        void GetDocumentDataFromInput(DocumentHeader documentHeader)
        {
            List<DocumentItem> proccessedItems = new();

            foreach (InputFileData inputExcelRow in inputExcelRows)
            {
                var inputExcelDatas = JToken.Parse(inputExcelRow.Data);

                DocumentItem documentItem = new();

                dynamic headerDataExo = new System.Dynamic.ExpandoObject();

                dynamic itemDataExo = new System.Dynamic.ExpandoObject();

                foreach (var field in dynamicFields)
                {
                    var value = string.Empty;

                    if (inputExcelDatas[$"{field.RelatedTitle1?.Trim()}"] is not null)
                    {
                        try
                        {
                            value = inputExcelDatas[$"{field.RelatedTitle1?.Trim()}"].ToString();
                        }
                        catch
                        {
                            value = "";
                        }
                    }
                    else if (inputExcelDatas[$"{field.RelatedTitle2?.Trim()}"] is not null)
                    {
                        try
                        {
                            value = inputExcelDatas[$"{field.RelatedTitle2?.Trim()}"].ToString();
                        }
                        catch
                        {
                            value = "";
                        }
                    }
                    else if (inputExcelDatas[$"{field.RelatedTitle3?.Trim()}"] is not null)
                    {
                        try
                        {
                            value = inputExcelDatas[$"{field.RelatedTitle3?.Trim()}"].ToString();
                        }
                        catch
                        {
                            value = "";
                        }
                    }

                    if (field.FieldType == (int)DynamicFieldType.HeaderData)
                    {
                        if (field.IsHeaderKey)
                        {
                            documentHeader.Key = value;
                        }

                        ((IDictionary<String, Object>)headerDataExo).Add(field.Title, value);
                    }
                    else
                    {
                        if (field.IsSystematicField)
                        {
                            if ((bool)field.RelatedTitle1?.Trim().Equals("ProductCode")
                                || (bool)field.RelatedTitle2?.Trim().ToString().Equals("ProductCode")
                                || (bool)field.RelatedTitle3?.Trim().ToString().Equals("ProductCode"))
                            {
                                documentItem.ProductCode = value;
                            }
                            else if ((bool)field.RelatedTitle1?.Trim().Equals("ProductUnit")
                                || (bool)field.RelatedTitle2?.Trim().ToString().Equals("ProductUnit")
                                || (bool)field.RelatedTitle3?.Trim().ToString().Equals("ProductUnit"))
                            {
                                documentItem.ProductUnit = value;
                            }
                            else if ((bool)field.RelatedTitle1?.Trim().Equals("Count")
                                || (bool)field.RelatedTitle2?.Trim().ToString().Equals("Count")
                                || (bool)field.RelatedTitle3?.Trim().ToString().Equals("Count"))
                            {
                                try
                                {
                                    documentItem.Count = decimal.Parse((value.HasValue() ? value : "0"));
                                }
                                catch
                                {
                                    documentItem.Count = 0;
                                }
                            }
                            else if ((bool)field.RelatedTitle1?.Trim().Equals("ProductTitle")
                                || (bool)field.RelatedTitle2?.Trim().ToString().Equals("ProductTitle")
                                || (bool)field.RelatedTitle3?.Trim().ToString().Equals("ProductTitle"))
                            {
                                documentItem.ProductTitle = value;
                            }
                        }

                        ((IDictionary<String, Object>)itemDataExo).Add(field.Title, value);
                    }
                }

                if (documentHeader.HeaderData is null)
                {
                    documentHeader.HeaderData = JsonConvert.SerializeObject(headerDataExo);
                }

                documentItem.ItemData = JsonConvert.SerializeObject(itemDataExo);

                documentItem.Key = documentHeader.Key;

                documentItem.DocumentType = documentMainType;

                documentItem.DocumentType1 = documentType1;

                documentItem.DocumentType2 = documentType2;

                if (proccessedItems.Neither(p => p.Key == documentHeader.Key
                && p.DocumentType == documentMainType
                && p.ProductCode == documentItem.ProductCode))
                {
                    documentHeader.DocumentItems.Add(documentItem);

                    proccessedItems.Add(documentItem);
                }
            }
        }
    }

    public bool SIsDocumentUpdateAllowed(string documentKey, string documentType)
    => !apiContext.DocumentHeaders.Include(p => p.DocumentStatus)
                                      .Any(p => !p.DocumentStatus.IsUpdatePermitted
                                                         && p.DocumentType == documentType
                                                         && p.Key == documentKey);

