    public DataTable SGetAllDocumentByCurrentAndNextStatus(GetAllDocumentByStatusQuery request)
    {
        string userId = httpContext.User.GetUserId();

        string whereString = @"WHERE dh.fld_DocumentParent IS NOT NULL 
                         AND dh.fld_DocumentParent = N'0' ";

        if (request.ProductCode.HasValue())
        {
            whereString += $" AND EXISTS (SELECT 1 FROM tbl_DocumentItem WHERE tbl_DocumentItem.fld_DocumentKey = dh.fld_DocumentKey AND tbl_DocumentItem.fld_DocumentItemProductCode = N'{request.ProductCode}') ";
        }

        if (request.Status.NotEquals(0))
        {
            if (request.GetCurrentStatusOnly)
            {
                whereString += $" AND dh.fld_DocumentStatus IN({request.Status})";
            }
            else
            {
                whereString += $" AND dh.fld_DocumentStatus IN({request.Status},{SGetNextDocumentStatus(request.Status)})";
            }
        }

        if (request.DocumentType.HasValue())
        {
            whereString += $" AND dh.fld_DocumentType = N'{request.DocumentType}' ";
        }

        if (request.FromDate.HasValue())
        {
            whereString += $" AND dh.fld_DocumentImportDatetime >= N'{PersianCalendarTools.PersianToGregorian(request.FromDate)}' ";
        }

        if (request.ToDate.HasValue())
        {
            whereString += $" AND dh.fld_DocumentImportDatetime < N'{PersianCalendarTools.PersianToGregorian(request.ToDate)}' ";
        }

        if (request.DocumentKey.HasValue())
        {
            whereString += $" AND dh.fld_DocumentKey Like N'%{request.DocumentKey}%' ";
        }

        if (request.DocumentHeaderText.HasValue())
        {
            whereString += $" AND dh.fld_DocumentHeaderData Like N'%{request.DocumentHeaderText}%' ";
        }

        string topClause = request.Limit is not null ? $" TOP ({request.Limit.Value}) " : string.Empty;

        string cmd =
            $"""
    WITH DocumentAggregates AS (
        SELECT 
            di.fld_DocumentKey,
            COUNT(di.fld_DocumentItemProductCode) AS ItemCount,
            COALESCE(SUM(di.fld_DocumentItemCount), 0) AS ItemSum,
            COALESCE(SUM(di.fld_DocumentItemCount * (p.ProductPackWeight / NULLIF(p.ProductValue, 0))), 0) AS Weight,
            COALESCE(SUM(di.fld_DocumentItemCount * p.ProductPackVolume), 0) AS Volume
        FROM tbl_DocumentItem di
        LEFT JOIN tbl_Products p ON di.fld_DocumentItemProductCode = p.ProductCode
        WHERE EXISTS (
            SELECT 1 FROM tbl_DocumentHeader dh 
            WHERE dh.fld_DocumentKey = di.fld_DocumentKey 
            AND dh.fld_DocumentParent IS NOT NULL 
            AND dh.fld_DocumentParent = N'0'
            {(request.ProductCode.HasValue() ? $" AND di.fld_DocumentItemProductCode = N'{request.ProductCode}'" : "")}
        )
        GROUP BY di.fld_DocumentKey
    ),
    LastDocumentEvents AS (
        SELECT 
            dl.fld_LogDocumentKey,
            dl.fld_LogDocumentType,
            ROW_NUMBER() OVER (PARTITION BY dl.fld_LogDocumentKey, dl.fld_LogDocumentType ORDER BY dl.fld_LogDateTime DESC) as rn,
            dl.fld_LogDateTime
        FROM tbl_DocumentLog dl
    )
    SELECT {topClause}
        dh.fld_Id as Id,
        CAST(dh.fld_DocumentKey as nvarchar(512)) as [DocumentKey],
        dh.fld_DocumentType as [DocumentType],
        COALESCE(CAST(JSON_VALUE(dh.fld_DocumentHeaderData,[dbo].[Find_JsonObject_Index_From_JsonArray](dh.fld_DocumentHeaderData,N'کد مشتری مجوز فروش')) as nvarchar(50)),N'') as [CustomerCode],
        COALESCE(CAST(JSON_VALUE(dh.fld_DocumentHeaderData,[dbo].[Find_JsonObject_Index_From_JsonArray](dh.fld_DocumentHeaderData,N'عنوان مشتری مجوز فروش')) as nvarchar(50)),N'') as [CustomerTitle],
        CAST(dh.fld_DocumentImportDatetime as Date) as [DateTime],
        COALESCE(da.ItemCount, 0) AS [ItemCount],
        COALESCE(da.ItemSum, 0) AS [ItemSum],
        dh.fld_DocumentStatus as [Status],
        dh.fld_DocumentHeaderData as [HeaderData],
        COALESCE(lde.fld_LogDateTime, GETDATE()) AS LastDocumentEventDateTime,
        COALESCE(CAST(da.Weight as Decimal(18,0)), 0) AS Weight,
        COALESCE(da.Volume, 0) AS Volume
    FROM tbl_DocumentHeader dh
    LEFT JOIN DocumentAggregates da ON dh.fld_DocumentKey = da.fld_DocumentKey
    LEFT JOIN LastDocumentEvents lde ON dh.fld_DocumentKey = lde.fld_LogDocumentKey 
        AND dh.fld_DocumentType = lde.fld_LogDocumentType 
        AND lde.rn = 1
    {whereString}
    ORDER BY LastDocumentEventDateTime DESC
    """;

        logger.LogInformation("SGetAllDocumentByCurrentAndNextStatus" + Environment.NewLine
            + "request" + request + Environment.NewLine
            + "userId" + userId + Environment.NewLine
            + "command" + cmd + Environment.NewLine);

        var result = dataAccess.SqlDataAdapter(cmd);
        return result;
    }

    public DataTable SGetAllDocumentItemByStatusVm(GetAllDocumentByStatusQuery request)
    {
        string whereString = $" WHERE tbl_DocumentItem.fld_DocumentKey = N'{request.DocumentKey}' ";

        if (request.ProductCode.HasValue())
        {
            if (whereString.HasValue())
            {
                whereString += " AND ";
            }
            whereString += $" tbl_DocumentItem.fld_DocumentItemProductCode = N'{request.ProductCode}' ";
        }
        if (request.Status.NotEquals(-1))
        {
            if (whereString.HasValue())
            {
                whereString += " AND ";
            }
            whereString += $" tbl_DocumentHeader.fld_DocumentStatus = N'{request.Status}' ";
        }
        if (request.DocumentType.HasValue())
        {
            if (whereString.HasValue())
            {
                whereString += " AND ";
            }
            whereString += $" tbl_DocumentHeader.fld_DocumentType = N'{request.DocumentType}' ";
        }
        if (request.FromDate.HasValue())
        {
            if (whereString.HasValue())
            {
                whereString += " AND ";
            }
            whereString += $" tbl_DocumentHeader.fld_DocumentImportDatetime >= N'{PersianCalendarTools.PersianToGregorian(request.FromDate)}' ";
        }
        if (request.ToDate.HasValue())
        {
            if (whereString.HasValue())
            {
                whereString += " AND ";
            }
            whereString += $" tbl_DocumentHeader.fld_DocumentImportDatetime < N'{PersianCalendarTools.PersianToGregorian(request.ToDate)}' ";
        }
        if (request.DocumentHeaderText.HasValue())
        {
            if (whereString.HasValue())
            {
                whereString += " AND ";
            }
            whereString += $" tbl_DocumentHeader.fld_DocumentHeaderData Like N'%{request.DocumentHeaderText}%' ";
        }
        string cmd =
            $"""
            SELECT tbl_DocumentItem.fld_Id as Id, tbl_DocumentItem.fld_DocumentKey as DocumentKey, tbl_DocumentItem.fld_DocumentItemProductCode as ProductCode,
            		COALESCE(tbl_DocumentItem.fld_DocumentItemProductTitle,N'') as ProductTitle, tbl_DocumentItem.fld_DocumentItemCount as [Count], tbl_DocumentItem.fld_DocumentItemsData as ItemData
            FROM tbl_DocumentItem INNER JOIN tbl_DocumentHeader ON   tbl_DocumentItem.fld_DocumentKey = tbl_DocumentHeader.fld_DocumentKey
            {whereString}
            """;
        var result = dataAccess.SqlDataAdapter(cmd);
        return result;
    }

    public int SChangeDocumentStatus(SaveDocumentStatusCommand command)
    {
        string userId = httpContext.User.GetUserId();

        var result = 0;

        List<string> cmds = new();

        foreach (var currentKeyType in command.DocumentKeyTypes)
        {
            int newStatus = 0;



            DocumentHeader currentDocument = apiContext.DocumentHeaders
                                                       .FirstOrDefault(p => p.Key == currentKeyType.Key
                                                                              && (p.DocumentType == currentKeyType.Type
                                                                              || p.DocumentType1 == currentKeyType.Type
                                                                              || p.DocumentType2 == currentKeyType.Type));
            if (currentDocument is null)
            {
                return 0;
            }

            if (command.NewStatus > 0)
            {
                newStatus = command.NewStatus;
            }
            else
            {
                newStatus = SGetNextDocumentStatus(currentDocument.DocumentStatusId);
            }

            if (newStatus > 0)
            {
                result = newStatus;

                if (currentDocument.AggStatus == 1 || currentDocument.AggStatus == 2)
                {
                    List<string> docWheres = new();

                    docWheres.Add($"(fld_DocumentKey = N'{currentDocument.Key}' AND (fld_DocumentType = N'{currentDocument.DocumentType}' OR  fld_DocumentType1 = N'{currentDocument.DocumentType}' OR fld_DocumentType2 = N'{currentDocument.DocumentType}') )");

                    docWheres.Add($"(fld_DocumentParent = N'{currentDocument.Key}' AND (fld_DocumentType = N'{currentDocument.DocumentType}' OR  fld_DocumentType1 = N'{currentDocument.DocumentType}' OR fld_DocumentType2 = N'{currentDocument.DocumentType}') )");

                    cmds.Add(
                            $"""
                                 UPDATE tbl_DocumentHeader
                                 SET fld_DocumentStatus = {newStatus} ,fld_DocumentChangeStatusLastUserId = '{userId}'
                                 {(docWheres.Any() ? "WHERE " + string.Join(" OR ", docWheres) : "")}
                                 """);
                }
                else if (currentDocument.AggStatus == 3 || currentDocument.AggStatus == 4)
                {
                    List<int> statuses = apiContext.DocumentHeaders.Where(p => p.DivideParent == currentDocument.DivideParent &&
                                                                                     p.Key != currentDocument.Key)
                                                                   .Select(p => p.DocumentStatusId)
                                                                   .ToList();

                    statuses.Add(newStatus);

                    cmds.Add(
                        $"""
                            UPDATE tbl_DocumentHeader
                            SET fld_DocumentStatus = {newStatus} ,fld_DocumentChangeStatusLastUserId = '{userId}'
                            WHERE fld_DocumentKey = N'{currentDocument.Key}' AND     
                                      (fld_DocumentType = N'{currentDocument.DocumentType}' 
                                    OR fld_DocumentType1 = N'{currentDocument.DocumentType}' 
                                    OR fld_DocumentType2 = N'{currentDocument.DocumentType}')
                            """);

                    cmds.Add(
                        $"""
                            UPDATE tbl_DocumentHeader
                            SET fld_DocumentStatus = {statuses.Min()} ,
                                fld_DocumentChangeStatusLastUserId = '{userId}'
                            WHERE fld_DocumentKey = N'{currentDocument.DivideParent}' AND     
                                        (fld_DocumentType = N'{currentDocument.DocumentType}' 
                                    OR fld_DocumentType1 = N'{currentDocument.DocumentType}' 
                                    OR fld_DocumentType2 = N'{currentDocument.DocumentType}')
                            """);
                }
            }
            else
            {
                return 0;
            }
        }

        if (dataAccess.CmdSqlExecuteNonQueryWithTransaction(cmds) > 0)
        {
            documentLog.SLogDocumentEvents(new()
            {
                DocKeyTypes = command.DocumentKeyTypes,
                EventType = DocumentEventType.ChangeStatusForward,
                Status = result,
                Description = command.Description,
                UserId = command.User
            });

            return result;
        }

        return 0;
    }

    public int SRevokeDocumentStatus(SaveDocumentStatusCommand revoke)
    {
        string userId = httpContext.User.GetUserId();

        int result = -1;

        if (revoke.DocumentKeyTypes.Any())
        {
            List<string> cmds = new();

            foreach (var currentKeyType in revoke.DocumentKeyTypes)
            {
                int newStatus = -1;

                DocumentHeader currentDocument = new();

                var doc = apiContext.DocumentHeaders.Where(p => p.Key == currentKeyType.Key &&
                                                                                      (p.DocumentType == currentKeyType.Type
                                                                                    || p.DocumentType1 == currentKeyType.Type
                                                                                    || p.DocumentType2 == currentKeyType.Type)
                                                                                 ).ToList();
                if (doc.Any())
                {
                    currentDocument = doc.First();
                }
                else
                {
                    return -1;
                }

                newStatus = SGetPreviousDocumentStatus(currentDocument.DocumentStatusId);

                if (newStatus > -1)
                {
                    result = newStatus;

                    if (currentDocument.AggStatus == 1 || currentDocument.AggStatus == 2)
                    {
                        List<string> docWheres = new();

                        docWheres.Add($"(fld_DocumentKey = N'{currentDocument.Key}' AND (fld_DocumentType = N'{currentDocument.DocumentType}' OR  fld_DocumentType1 = N'{currentDocument.DocumentType}' OR fld_DocumentType2 = N'{currentDocument.DocumentType}') )");

                        docWheres.Add($"(fld_DocumentParent = N'{currentDocument.Key}' AND (fld_DocumentType = N'{currentDocument.DocumentType}' OR  fld_DocumentType1 = N'{currentDocument.DocumentType}' OR fld_DocumentType2 = N'{currentDocument.DocumentType}') )");

                        cmds.Add(
                                $"""
                                 UPDATE tbl_DocumentHeader
                                 SET fld_DocumentStatus = {newStatus} ,fld_DocumentChangeStatusLastUserId = '{userId}'
                                 {(docWheres.Any() ? "WHERE " + string.Join(" OR ", docWheres) : "")}
                                 """);
                    }
                    else if (currentDocument.AggStatus == 3 || currentDocument.AggStatus == 4)
                    {
                        List<int> statuses = apiContext.DocumentHeaders.Where(p => p.DivideParent == currentDocument.DivideParent &&
                                                                                   p.Key != currentDocument.Key)
                                                                       .Select(p => p.DocumentStatusId)
                                                                       .ToList();

                        statuses.Add(newStatus);

                        cmds.Add(
                            $"""
                            UPDATE tbl_DocumentHeader
                            SET fld_DocumentStatus = {newStatus} ,fld_DocumentChangeStatusLastUserId = '{userId}'
                            WHERE fld_DocumentKey = N'{currentDocument.Key}' AND     
                                      (fld_DocumentType = N'{currentDocument.DocumentType}' 
                                    OR fld_DocumentType1 = N'{currentDocument.DocumentType}' 
                                    OR fld_DocumentType2 = N'{currentDocument.DocumentType}')
                            """);

                        cmds.Add(
                            $"""
                            UPDATE tbl_DocumentHeader
                            SET fld_DocumentStatus = {statuses.Min()} ,
                                fld_DocumentChangeStatusLastUserId = '{userId}'
                            WHERE fld_DocumentKey = N'{currentDocument.DivideParent}' AND     
                                      (fld_DocumentType = N'{currentDocument.DocumentType}' 
                                    OR fld_DocumentType1 = N'{currentDocument.DocumentType}' 
                                    OR fld_DocumentType2 = N'{currentDocument.DocumentType}')
                            """);
                    }
                }
                else
                {
                    return 0;
                }
            }

            if (dataAccess.CmdSqlExecuteNonQueryWithTransaction(cmds) > 0)
            {
                documentLog.SLogDocumentEvents(new()
                {
                    DocKeyTypes = revoke.DocumentKeyTypes,
                    EventType = DocumentEventType.ChangeStatusBackward,
                    Status = result,
                    Description = revoke.Description
                });

                return result;
            }
        }

        return -1;
    }
    #endregion

    #region Document Remove
    public DataTable SGetAllMainDocuments(GetAllDocumentByStatusQuery request)
    {
        string userId = httpContext.User.GetUserId();

        string whereString = @"WHERE tbl_DocumentHeader.fld_DocumentAggStatus = N'1' ";
        string whereSubString = @"WHERE Items.fld_DocumentKey = tbl_DocumentHeader.fld_DocumentKey AND
                                        Items.fld_DocumentType = tbl_DocumentHeader.fld_DocumentType";
        string groupBy =
            """
            GROUP BY tbl_DocumentHeader.fld_Id, tbl_DocumentHeader.fld_DocumentKey, tbl_DocumentHeader.fld_DocumentHeaderData,
            tbl_DocumentHeader.fld_DocumentImportDatetime, tbl_DocumentHeader.fld_DocumentStatus,tbl_DocumentHeader.fld_DocumentType
            """;
        if (request.ProductCode.HasValue())
        {
            if (whereString.HasValue())
            {
                whereString += " AND ";
            }
            if (whereSubString.HasValue())
            {
                whereSubString += " AND ";
            }
            whereString += $" tbl_DocumentItem.fld_DocumentItemProductCode = N'{request.ProductCode}' ";
            whereSubString += $" Items.fld_DocumentItemProductCode = N'{request.ProductCode}' ";
        }
        if (request.Status.NotEquals(0))
        {
            if (whereString.HasValue())
            {
                whereString += " AND ";
            }
            if (request.GetCurrentStatusOnly)
            {
                whereString += $" tbl_DocumentHeader.fld_DocumentStatus IN({request.Status})";
            }
            else
            {
                whereString += $" tbl_DocumentHeader.fld_DocumentStatus IN({request.Status},{SGetNextDocumentStatus(request.Status)})";
            }
        }
        if (request.DocumentType.HasValue())
        {
            if (whereString.HasValue())
            {
                whereString += " AND ";
            }
            whereString += $" tbl_DocumentHeader.fld_DocumentType = N'{request.DocumentType}' ";
        }
        if (request.FromDate.HasValue())
        {
            if (whereString.HasValue())
            {
                whereString += " AND ";
            }
            whereString += $" tbl_DocumentHeader.fld_DocumentImportDatetime >= N'{PersianCalendarTools.PersianToGregorian(request.FromDate)}' ";
        }
        if (request.ToDate.HasValue())
        {
            if (whereString.HasValue())
            {
                whereString += " AND ";
            }
            whereString += $" tbl_DocumentHeader.fld_DocumentImportDatetime < N'{PersianCalendarTools.PersianToGregorian(request.ToDate)}' ";
        }
        if (request.DocumentKey.HasValue())
        {
            if (whereString.HasValue())
            {
                whereString += " AND ";
            }
            whereString += $" tbl_DocumentHeader.fld_DocumentKey Like N'%{request.DocumentKey}%' ";
        }
        string cmd =
            $"""
            SELECT      tbl_DocumentHeader.fld_Id as Id, 
            			CAST(tbl_DocumentHeader.fld_DocumentKey as nvarchar(512)) as [DocumentKey],
                        tbl_DocumentHeader.fld_DocumentType as [DocumentType],
            			CAST(tbl_DocumentHeader.fld_DocumentImportDatetime as Date) as [DateTime], 
            			(SELECT COUNT(Items.fld_DocumentItemProductCode)
            				FROM tbl_DocumentItem as Items
            				{whereSubString})
            					AS [ItemCount],
            			COALESCE((SELECT SUM(Items.fld_DocumentItemCount)
            				FROM tbl_DocumentItem as Items
            				{whereSubString})
            				,0) AS [ItemSum],
            			tbl_DocumentHeader.fld_DocumentStatus as [Status],
                        tbl_DocumentHeader.fld_DocumentHeaderData as [HeaderData]
            FROM    tbl_DocumentHeader INNER JOIN tbl_DocumentItem ON tbl_DocumentHeader.fld_DocumentKey = tbl_DocumentItem.fld_DocumentKey
            {whereString}
            {groupBy}
            """;
        var result = dataAccess.SqlDataAdapter(cmd);
        return result;
    }

    public int SRemoveDocuments(RemoveDocumentCommand command)
    {
        string userId = httpContext.User.GetUserId();

        List<string> headerWhereList = new();

        List<string> itemWhereList = new();

        foreach (var keyType in command.DocumentKeyTypes)
        {
            headerWhereList.Add(
                $"""
                (tbl_DocumentHeader.fld_DocumentKey = N'{keyType.Key}' 
                AND tbl_DocumentHeader.fld_DocumentType = N'{keyType.Type}' )
                """);

            headerWhereList.Add(
                $"""
                (fld_DocumentDivideParent = N'{keyType.Key}' 
                AND fld_DocumentType = N'{keyType.Type}' )
                """);

            itemWhereList.Add(
                $"""
                (tbl_DocumentItem.fld_DocumentKey = N'{keyType.Key}' 
                AND tbl_DocumentItem.fld_DocumentType = N'{keyType.Type}' )
                """);

            itemWhereList.Add(
                $"""
                    (tbl_DocumentItem.fld_DocumentKey IN 
                        (SELECT tbl_DocumentHeader.fld_DocumentKey 
                        FROM tbl_DocumentHeader 
                        WHERE tbl_DocumentHeader.fld_DocumentDivideParent = N'{keyType.Key}' 
                        AND tbl_DocumentHeader.fld_DocumentType = N'{keyType.Type}'  ) 
                    AND tbl_DocumentItem.fld_DocumentType = N'{keyType.Type}'  )
                    """);
        }

        List<string> commands = new();

        if (headerWhereList.Any())
        {
            commands.Add(
            $"""
                DELETE FROM tbl_DocumentItem 
                WHERE {string.Join(" OR ", itemWhereList)}
                """);

            commands.Add(
            $"""
                DELETE FROM tbl_DocumentHeader 
                WHERE {string.Join(" OR ", headerWhereList)}
                """);
        }

        var result = sqlDataAccess.CmdSqlExecuteNonQueryWithTransaction(commands);

        if (result > 0)
        {
            documentLog.SLogDocumentEvents(new()
            {
                DocKeyTypes = command.DocumentKeyTypes,
                EventType = DocumentEventType.RemoveDocument,
                Status = -1,
                Description = command.Description,
                UserId = userId
            });
        }

        return result;
    }
    #endregion

    #region Document Division
    public DataTable SGetRemainDividableDocumentItem(GetDividableDocumentQuery request)
    {
        string userId = httpContext.User.GetUserId();
        string command =
            $"""
            SELECT * 
            FROM(
            		SELECT  COALESCE(fld_DocumentItemProductCode,'') as ProductCode, COALESCE(fld_DocumentItemProductTitle,'') as ProductTitle,
            			    COALESCE(fld_DocumentItemProducUnit,'') as ProductUnit,
            			    COALESCE(fld_DocumentItemCount - 
            				        COALESCE(
                                        (SELECT SUM(COALESCE(fld_DocumentItemCount,0))
            						        FROM tbl_DocumentItem as Item INNER JOIN tbl_DocumentHeader as Header 
            															        ON Header.fld_DocumentKey = Item.fld_DocumentKey 
            															        AND Header.fld_DocumentType = Item.fld_DocumentType

            						        WHERE Header.fld_DocumentDivideParent = '{request.DocumentKey}' 
                                            AND Header.fld_DocumentType = '{request.DocumentType}' 
            						        AND Header.fld_DocumentAggStatus = 3
                                            AND Item.fld_DocumentItemProductCode = tbl_DocumentItem.fld_DocumentItemProductCode
                                            GROUP BY Item.fld_DocumentItemProductCode)
                                    ,0)
                            ,0)  as Count

            		FROM tbl_DocumentItem INNER JOIN tbl_DocumentHeader ON tbl_DocumentHeader.fld_DocumentKey = tbl_DocumentItem.fld_DocumentKey 
            														   AND tbl_DocumentHeader.fld_DocumentType = tbl_DocumentItem.fld_DocumentType
            		WHERE tbl_DocumentHeader.fld_DocumentKey = '{request.DocumentKey}' AND tbl_DocumentHeader.fld_DocumentType = '{request.DocumentType}' 
                    AND tbl_DocumentHeader.fld_DocumentAggStatus = N'1' AND (tbl_DocumentHeader.fld_DocumentParent = N'0' OR tbl_DocumentHeader.fld_DocumentParent = N'Divided')
            ) as [NESTED]
            WHERE [NESTED].Count >0 
            """;

        var result = dataAccess.SqlDataAdapter(command);

        return result;
    }

    public DataTable SGetDivisionSuggestItems(GetDividableDocumentQuery request)
    {
        string userId = httpContext.User.GetUserId();

        var condition = configuration[$"ProjectConfigs:WmsConfigs:DocumentDivisionCondition"];

        string suggestCondition = string.Empty;

        if (condition.HasValue())
        {
            suggestCondition = SCheckSqlInjection(condition);
        }

        string command =
            $"""
            SELECT [NESTED].ProductCode, [NESTED].ProductTitle, [NESTED].ProductUnit, [NESTED].Count  
            FROM(
            		SELECT  COALESCE(fld_DocumentItemProductCode,'') as ProductCode, COALESCE(fld_DocumentItemProductTitle,'') as ProductTitle,
            			    COALESCE(fld_DocumentItemProducUnit,'') as ProductUnit,
            			    COALESCE(fld_DocumentItemCount - 
            				        COALESCE(
                                        (SELECT SUM(COALESCE(fld_DocumentItemCount,0))
            						        FROM tbl_DocumentItem as Item INNER JOIN tbl_DocumentHeader as Header 
            															        ON Header.fld_DocumentKey = Item.fld_DocumentKey 
            															        AND Header.fld_DocumentType = Item.fld_DocumentType

            						        WHERE Header.fld_DocumentDivideParent = '{request.DocumentKey}' 
                                            AND Header.fld_DocumentType = '{request.DocumentType}' 
            						        AND Header.fld_DocumentAggStatus = 3
                                            AND Item.fld_DocumentItemProductCode = tbl_DocumentItem.fld_DocumentItemProductCode
                                            GROUP BY Item.fld_DocumentItemProductCode)
                                    ,0)
                            ,0)  as Count

            		FROM tbl_DocumentItem INNER JOIN tbl_DocumentHeader ON tbl_DocumentHeader.fld_DocumentKey = tbl_DocumentItem.fld_DocumentKey 
            														   AND tbl_DocumentHeader.fld_DocumentType = tbl_DocumentItem.fld_DocumentType
            		WHERE tbl_DocumentHeader.fld_DocumentKey = '{request.DocumentKey}' AND tbl_DocumentHeader.fld_DocumentType = '{request.DocumentType}'
                    AND tbl_DocumentHeader.fld_DocumentAggStatus = N'1' AND tbl_DocumentHeader.fld_DocumentParent = N'0'
            ) as [NESTED]
            INNER JOIN tbl_Products ON [NESTED].ProductCode = tbl_Products.ProductCode
            WHERE [NESTED].Count >0 {(suggestCondition.HasValue() ? " AND " + suggestCondition : "")}
            """;

        var result = dataAccess.SqlDataAdapter(command);

        return result;
    }

    public List<GetAllDividedDocumentHeaderVM> SGetDividedDocuments(GetDividableDocumentQuery request)
    {
