        List<GetAllDividedDocumentHeaderVM> documents = apiContext.DocumentHeaders
            .Include(p => p.DocumentItems.Where(q => q.DocumentType == request.DocumentType))
            .Where(header => header.DivideParent == request.DocumentKey
                          && header.AggStatus == 3
                          && header.DocumentType == request.DocumentType)
            .OrderByDescending(p => p.ImportDateTime)
