    public int SDivideDocument(SaveDocumentDivideCommand division)
    {
        string userId = httpContext.User.GetUserId();

        DocumentHeader currentDocument = apiContext.DocumentHeaders.Include(p => p.DocumentItems.Where(q => q.Key == division.CurrentDocKey
                                                                                                         && q.DocumentType == division.CurrentDocType))
                                                                   .Where(p => p.Key == division.CurrentDocKey
                                                                          && p.DocumentType == division.CurrentDocType)
                                                                   .ToList()
                                                                   .FirstOrDefault();

        List<DocumentKeyTypeDto> changedDocuments = new();

        if (currentDocument.Parent == "0")
        {
            #region Reamin
            DocumentHeader remainDocument = new()
            {
                Key = currentDocument.Key + "_0",
                DocumentType = currentDocument.DocumentType,
                DocumentType1 = currentDocument.DocumentType1,
                DocumentType2 = currentDocument.DocumentType2,
                UserId = userId,
                ImportType = ImportType.Divide,
                FileName = "Div_" + currentDocument.Key + "_0" + Guid.NewGuid().ToString().Substring(0, 6),
                ImportDateTime = DateTime.Now,
                Description = currentDocument.Description,
                DocumentStatusId = currentDocument.DocumentStatusId,
                AggStatus = 4,
                Parent = "0",
                DivideParent = currentDocument.Key,
                HeaderData = currentDocument.HeaderData,
                DocumentItems = new List<DocumentItem>()
            };

            foreach (var newItem in division.RemainDocItems)
            {
                remainDocument.DocumentItems.Add(new()
                {
                    Key = currentDocument.Key + "_0",
                    DocumentType = currentDocument.DocumentType,
                    DocumentType1 = currentDocument.DocumentType1,
                    DocumentType2 = currentDocument.DocumentType2,
                    ItemData = currentDocument.DocumentItems.FirstOrDefault(p => p.ProductCode == newItem.ProductCode)?.ItemData ?? "{}",
                    ProductCode = newItem.ProductCode,
                    ProductTitle = newItem.ProductTitle,
                    ProductUnit = newItem.ProductUnit,
                    Count = newItem.Count
                });
            }
            #endregion

            #region Division
            DocumentHeader dividedDocument = new()
            {
                Key = currentDocument.Key + "_1",
                DocumentType = currentDocument.DocumentType,
                DocumentType1 = currentDocument.DocumentType1,
                DocumentType2 = currentDocument.DocumentType2,
                UserId = userId,
                ImportType = ImportType.Divide,
                FileName = "Div_" + currentDocument.Key + "_1" + Guid.NewGuid().ToString().Substring(0, 6),
                ImportDateTime = DateTime.Now,
                Description = currentDocument.Description,
                DocumentStatusId = currentDocument.DocumentStatusId,
                AggStatus = 3,
                Parent = "0",
                DivideParent = currentDocument.Key,
                HeaderData = currentDocument.HeaderData,
                DocumentItems = new List<DocumentItem>()
            };

            foreach (var item in division.NewDivisionDocItems)
            {
                dividedDocument.DocumentItems.Add(new()
                {
                    Key = currentDocument.Key,
                    DocumentType = currentDocument.DocumentType,
                    DocumentType1 = currentDocument.DocumentType1,
                    DocumentType2 = currentDocument.DocumentType2,
                    ItemData = currentDocument.DocumentItems.FirstOrDefault(p => p.ProductCode == item.ProductCode)?.ItemData ?? "{}",
                    ProductCode = item.ProductCode,
                    ProductTitle = item.ProductTitle,
                    ProductUnit = item.ProductUnit,
                    Count = item.Count
                });
            }
            #endregion

            #region CRUD
            currentDocument.Parent = "Divided";

            apiContext.Add(remainDocument);

            apiContext.Add(dividedDocument);

            changedDocuments.Add(new()
            {
                Key = dividedDocument.Key,
                Type = dividedDocument.DocumentType
            });
            #endregion
        }
        else
        {
            #region Remain
            List<DocumentItem> newRemainItems = new();

            foreach (var newItem in division.RemainDocItems)
            {
                newRemainItems.Add(new()
                {
                    Key = currentDocument.Key + "_0",
                    DocumentType = currentDocument.DocumentType,
                    DocumentType1 = currentDocument.DocumentType1,
                    DocumentType2 = currentDocument.DocumentType2,
                    ItemData = currentDocument.DocumentItems.FirstOrDefault(p => p.ProductCode == newItem.ProductCode)?.ItemData ?? "{}",
                    ProductCode = newItem.ProductCode,
                    ProductTitle = newItem.ProductTitle,
                    ProductUnit = newItem.ProductUnit,
                    Count = newItem.Count
                });
            }

            var oldRemainItems = apiContext.DocumentItems.Where(p => p.Key == (division.CurrentDocKey + "_0")
                                                          && p.DocumentType == division.CurrentDocType)
                                                         .ToList();
            #endregion

            #region nextBranchCode
            var dividedKeys = apiContext.DocumentHeaders.Where(p => p.DivideParent == currentDocument.Key
                                                                 && p.DocumentType == currentDocument.DocumentType
                                                                 && p.AggStatus == 3)
                                                        .Select(p => p.Key)
                                                        .ToList();

            List<int> dividedBranches = new();

            foreach (var key in dividedKeys)
            {
                try
                {
                    dividedBranches.Add(int.Parse(key.Split('_').Last()));
                }
                catch
                {
                }
            }

            string newDividedKey = "";

            try
            {
                newDividedKey = currentDocument.Key + "_" + (dividedBranches.Max() + 1).ToString();
            }
            catch
            {

            }
            #endregion

            #region Division
            DocumentHeader dividedDocument = new()
            {
                Key = newDividedKey,
                DocumentType = currentDocument.DocumentType,
                DocumentType1 = currentDocument.DocumentType1,
                DocumentType2 = currentDocument.DocumentType2,
                UserId = userId,
                ImportType = ImportType.Divide,
                FileName = "Div_" + newDividedKey + Guid.NewGuid().ToString().Substring(0, 6),
                ImportDateTime = DateTime.Now,
                Description = currentDocument.Description,
                DocumentStatusId = currentDocument.DocumentStatusId,
                AggStatus = 3,
                Parent = "0",
                DivideParent = currentDocument.Key,
                HeaderData = currentDocument.HeaderData,
                DocumentItems = new List<DocumentItem>()
            };

            foreach (var item in division.NewDivisionDocItems)
            {
                dividedDocument.DocumentItems.Add(new()
                {
                    Key = newDividedKey,
                    DocumentType = currentDocument.DocumentType,
                    DocumentType1 = currentDocument.DocumentType1,
                    DocumentType2 = currentDocument.DocumentType2,
                    ItemData = currentDocument.DocumentItems.FirstOrDefault(p => p.ProductCode == item.ProductCode)?.ItemData ?? "{}",
                    ProductCode = item.ProductCode,
                    ProductTitle = item.ProductTitle,
                    ProductUnit = item.ProductUnit,
                    Count = item.Count
                });
            }
            #endregion

            #region CRUD
            apiContext.RemoveRange(oldRemainItems);

            apiContext.AddRange(newRemainItems);

            apiContext.Add(dividedDocument);

            changedDocuments.Add(new()
            {
                Key = dividedDocument.Key,
                Type = dividedDocument.DocumentType
            });
            #endregion
        }

        var result = apiContext.SaveChanges();

        if (result > 0)
        {
            documentLog.SLogDocumentEvents(new()
            {
                DocKeyTypes = changedDocuments,
                EventType = DocumentEventType.Divide,
                Status = currentDocument.DocumentStatusId,
                Description = division.Description,
                UserId = userId
            });
        }

        return result;
    }

    public int SRevokeDocumentDivision(GetDividableDocumentQuery request)
    {
        string userId = httpContext.User.GetUserId();

        logger.LogInformation("SRevokeDocumentDivision" + Environment.NewLine
                    + JsonConvert.SerializeObject(request) + Environment.NewLine
                    + "userId" + userId + Environment.NewLine);

        DocumentHeader currentDividedDocument = apiContext.DocumentHeaders.Include(p => p.DocumentItems.Where(q => q.Key == request.DocumentKey
                                                                                                     && q.DocumentType == request.DocumentType))
                                                                   .Where(p => p.Key == request.DocumentKey
                                                                            && p.DocumentType == request.DocumentType)
                                                                   .FirstOrDefault();

        DocumentHeader remainDocument = apiContext.DocumentHeaders.Include(p => p.DocumentItems.Where(q => q.Key == currentDividedDocument.DivideParent + "_0"
                                                                                                     && q.DocumentType == request.DocumentType))
                                                                   .Where(p => p.DivideParent == currentDividedDocument.DivideParent
                                                                            && p.DocumentType == request.DocumentType
                                                                            && p.AggStatus == 4)
                                                                   .FirstOrDefault();

        if (currentDividedDocument is not null && remainDocument is not null)
        {
            int dividedKeyCount = apiContext.DocumentHeaders.Where(p => p.DocumentType == currentDividedDocument.DocumentType &&
                                                                        p.DivideParent == currentDividedDocument.DivideParent &&
                                                                        p.AggStatus == 3)
                                                            .Select(p => p.Id)
                                                            .Count();

            List<string> commands = new();

            commands.Add($"""
                DELETE FROM tbl_DocumentHeader
                WHERE fld_DocumentKey = '{currentDividedDocument.Key}' 
                  AND fld_DocumentType = '{currentDividedDocument.DocumentType}' 
                """);

            commands.Add($"""
                DELETE FROM tbl_DocumentItem 
                WHERE fld_DocumentKey = '{currentDividedDocument.Key}' 
                  AND fld_DocumentType = '{currentDividedDocument.DocumentType}' 
                """);


            foreach (var item in currentDividedDocument.DocumentItems)
            {
                if (remainDocument.DocumentItems.Any(p => p.ProductCode == item.ProductCode))
                {
                    commands.Add($"""
                    UPDATE tbl_DocumentItem
                    SET fld_DocumentItemCount = {item.Count}
                    WHERE fld_DocumentKey = '{currentDividedDocument.DivideParent}_0' 
                      AND fld_DocumentType = '{currentDividedDocument.DocumentType}' 
                      AND fld_DocumentItemProductCode = '{item.ProductCode}'
                    """);
                }
                else
                {
                    commands.Add($"""
                    INSERT INTO tbl_DocumentItem (fld_DocumentKey, fld_DocumentItemProductCode,
                    fld_DocumentItemCount,fld_DocumentItemProductTitle,fld_DocumentItemProducUnit,
                    fld_DocumentType,fld_DocumentType1,fld_DocumentType2,fld_DocumentItemsData)
                    VALUES ('{currentDividedDocument.DivideParent}_0','{item.ProductCode}',{item.Count},'{item.ProductTitle}',
                            '{item.ProductUnit}','{currentDividedDocument.DocumentType}','{currentDividedDocument.DocumentType1}','{currentDividedDocument.DocumentType2}',
                            '{item.ItemData}')
                    """);
                }
            }

            if (dividedKeyCount - 1 == 0)
            {
                commands.Add($"""
                UPDATE tbl_DocumentHeader
                SET fld_DocumentParent = '0'
                WHERE fld_DocumentKey = '{currentDividedDocument.DivideParent}' AND fld_DocumentType = '{currentDividedDocument.DocumentType}' 
                """);

                commands.Add($"""
                DELETE FROM tbl_DocumentHeader
                WHERE fld_DocumentKey = '{currentDividedDocument.DivideParent}_0' 
                  AND fld_DocumentType = '{currentDividedDocument.DocumentType}' 
                """);

                commands.Add($"""
                DELETE FROM tbl_DocumentItem
                WHERE fld_DocumentKey = '{currentDividedDocument.DivideParent}_0' 
                  AND fld_DocumentType = '{currentDividedDocument.DocumentType}' 
                """);
            }

            var result = dataAccess.CmdSqlExecuteNonQueryWithTransaction(commands);

            if (result > 0)
            {

                List<DocumentKeyTypeDto> changedDocuments = new()
                {
                    new()
                    {
                        Key = currentDividedDocument.Key,
                        Type = currentDividedDocument.DocumentType
                    }
                };

                documentLog.SLogDocumentEvents(new()
                {
                    DocKeyTypes = changedDocuments,
                    EventType = DocumentEventType.RevokeDivide,
                    Status = request.DocumentStatus,
                    Description = request.Description,
                    UserId = userId
                });
            }

            return result;
        }
        return 0;
    }
