    #region Document Aggregate And Revoke
    public int SRevokeDocumentAgg(RevokeDocumentAggregateCommand revoke)
    {
        List<string> docWheres = new();

        List<DocumentKeyTypeDto> changedDocuments = new();

        foreach (var keyType in revoke.DocumentKeyTypes)
        {
            changedDocuments.Add(keyType);

            foreach (var key in keyType.Key.Split('-'))
            {
                docWheres.Add($"(fld_DocumentKey = N'{key}' AND fld_DocumentType = N'{keyType.Type}' )");
            }
        }

        List<string> commands = new();

        commands.Add(
               $"""
                DELETE FROM tbl_DocumentHeader 
                WHERE tbl_DocumentHeader.fld_DocumentKey = '{revoke.DocumentKeyTypes.First().Key}' AND 
                      tbl_DocumentHeader.fld_DocumentType = '{revoke.DocumentKeyTypes.First().Type}'
                """);

        commands.Add(
        $"""
                DELETE FROM tbl_DocumentItem 
                WHERE tbl_DocumentItem.fld_DocumentKey = '{revoke.DocumentKeyTypes.First().Key}' AND 
                      tbl_DocumentItem.fld_DocumentType = '{revoke.DocumentKeyTypes.First().Type}'
                """);

        commands.Add(
                $"""
                UPDATE tbl_DocumentHeader
                SET fld_DocumentParent = '0' , fld_DocumentAggStatus = '1'
                {(docWheres.Any() ? "WHERE " + string.Join(" OR ", docWheres) : "")}
                """);

        var result = sqlDataAccess.CmdSqlExecuteNonQueryWithTransaction(commands);

        if (result > 0)
        {
            documentLog.SLogDocumentEvents(new()
            {
                DocKeyTypes = changedDocuments,
                EventType = DocumentEventType.RevokeAggregate,
                Status = revoke.DocumentStatus,
                Description = revoke.Description
            });
        }

        return result;
    }
    #endregion

