    #region Reports
    public DataTable SReportInventory(InventoryReportRequest request)
    {
        string whereTag = " ";

        string whereInventory = " WHERE tbl_InventoryTags.fld_InventoryTagEPC IS NOT NULL ";

        if (request.WarehouseCode.NotEquals("-1"))
        {
            whereInventory += $" AND tbl_InventoryTags.fld_InventoryStoreCode = N'{request.WarehouseCode}' ";
        }

        if (request.Place.NotEquals("-1"))
        {
            whereInventory += $" AND tbl_InventoryTags.fld_InventoryPlace = N'{request.Place}' ";
        }

        if (request.Desc.NotEquals("-1"))
        {
            whereInventory += $" AND tbl_InventoryTags.fld_InventoryProductDesc Like N'%{request.Desc}%' ";
        }

        if (request.User.NotEquals("-1"))
        {
            whereInventory += $" AND tbl_InventoryTags.fld_InventoryUser = N'{request.User}' ";
        }

        if (request.Code.NotEquals("-1"))
        {
            whereInventory += $" AND tbl_InventoryTags.fld_InventoryHeaderId = N'{request.Code}' ";
        }

        if (request.FromDate.NotEquals("-1"))
        {
            whereInventory += $" AND tbl_InventoryTags.fld_InventoryDate >= N'{request.FromDate}' ";
        }

        if (request.ToDate.NotEquals("-1"))
        {
            whereInventory += $" AND tbl_InventoryTags.fld_InventoryDate <= N'{request.ToDate}' ";
        }

        if (request.FromTime.NotEquals("-1"))
        {
            whereInventory += $" AND CAST(CAST(tbl_InventoryTags.fld_InventoryDateTime AS time) AS nvarchar(5)) >= N'{request.FromTime}' ";
        }

        if (request.ToTime.NotEquals("-1"))
        {
            whereInventory += $" AND CAST(CAST(tbl_InventoryTags.fld_InventoryDateTime AS time) AS nvarchar(5)) <= N'{request.ToTime}' ";
        }

        if (request.ProductCode.NotEquals("-1"))
        {
            whereTag += $" AND tbl_Tags.ProductCode = N'{request.ProductCode}' ";
        }

        if (request.TechnicalCode.NotEquals("-1"))
        {
            whereTag += $" AND tbl_Tags.RegCode = N'{request.TechnicalCode}' ";
        }

        string command = $@"SELECT COALESCE(tbl_Tags.ProductCode,N'') as ProductCode,
	                               COALESCE(tbl_Tags.RegCode,N'') as RegCode,
	                               COALESCE(tbl_Tags.ProductName,N'رجیستر نشده') AS ProductName,
	                               SUM(1) AS [Count],
	                               COALESCE(SUM(tbl_Tags.ProductCount),0) AS [SumCount]
                            FROM tbl_Tags 
                            WHERE tbl_Tags.TagEpc IN (SELECT DISTINCT tbl_InventoryTags.fld_InventoryTagEPC From tbl_InventoryTags {whereInventory}) {whereTag}
                            GROUP BY tbl_Tags.ProductCode,tbl_Tags.RegCode,tbl_Tags.ProductName";

        return dataAccess.SqlDataAdapter(command);
    }

    public DataTable SReportInventoryBySerial(InventoryReportRequest request)
    {

        string where = " WHERE tbl_Tags.ProductSerial IS NOT NULL ";

        if (request.WarehouseCode.NotEquals("-1"))
        {
            where += $" AND tbl_InventoryTags.fld_InventoryStoreCode = N'{request.WarehouseCode}' ";
        }

        if (request.Place.NotEquals("-1"))
        {
            where += $" AND tbl_InventoryTags.fld_InventoryPlace = N'{request.Place}' ";
        }

        if (request.Desc.NotEquals("-1"))
        {
            where += $" AND tbl_InventoryTags.fld_InventoryProductDesc Like N'%{request.Desc}%' ";
        }

        if (request.User.NotEquals("-1"))
        {
            where += $" AND tbl_InventoryTags.fld_InventoryUser = N'{request.User}' ";
        }

        if (request.Code.NotEquals("-1"))
        {
            where += $" AND tbl_InventoryTags.fld_InventoryHeaderId = N'{request.Code}' ";
        }

        if (request.FromDate.NotEquals("-1"))
        {
            where += $" AND tbl_InventoryTags.fld_InventoryDate >= N'{request.FromDate}' ";
        }

        if (request.ToDate.NotEquals("-1"))
        {
            where += $" AND tbl_InventoryTags.fld_InventoryDate <= N'{request.ToDate}' ";
        }

        if (request.FromTime.NotEquals("-1"))
        {
            where += $" AND CAST(CAST(tbl_InventoryTags.fld_InventoryDateTime AS time) AS nvarchar(5)) >= N'{request.FromTime}' ";
        }

        if (request.ToTime.NotEquals("-1"))
        {
            where += $" AND CAST(CAST(tbl_InventoryTags.fld_InventoryDateTime AS time) AS nvarchar(5)) <= N'{request.ToTime}' ";
        }

        if (request.ProductCode.NotEquals("-1"))
        {
            where += $" AND tbl_Tags.ProductCode = N'{request.ProductCode}' ";
        }

        if (request.TechnicalCode.NotEquals("-1"))
        {
            where += $" AND tbl_Tags.RegCode = N'{request.TechnicalCode}' ";
        }

        string command = $@"WITH RankedTags AS (
            SELECT
                COALESCE(tbl_Tags.ProductSerial, N'') AS ProductSerial,
                COALESCE(tbl_Tags.ProductCode, N'') AS ProductCode,
                COALESCE(tbl_Tags.ProductCount, N'') AS ProductCount,
                COALESCE(tbl_Tags.RegCode, N'') AS RegCode,
                COALESCE(tbl_Tags.ProductName, N'') AS ProductName,
                COALESCE(tbl_Tags.TagRegisterShamsiUnixDate, N'') AS ProductDate,
                COALESCE(tbl_Tags.ContractStatus, N'') AS ContractStatus,
                COALESCE(tbl_Tags.DeviceIp, N'') AS OldSerial,
                COALESCE(tbl_InventoryTags.fld_InventoryProductDesc, N'') AS [Desc],
                CONCAT(COALESCE(tbl_InventoryTags.fld_InventoryDate, N''), ' - ', COALESCE(CAST(CAST(tbl_InventoryTags.fld_InventoryDateTime AS TIME) AS NVARCHAR(5)), N'')) AS [DateTime],
                ROW_NUMBER() OVER (PARTITION BY tbl_InventoryTags.fld_InventoryTagEPC ORDER BY tbl_InventoryTags.fld_InventoryDate DESC) AS rn
            FROM
                tbl_InventoryTags
            LEFT JOIN
                tbl_Tags ON tbl_Tags.TagEpc = tbl_InventoryTags.fld_InventoryTagEPC
            {where}
        )
        SELECT
            ProductSerial,
            ProductCode,
            ProductCount,
            RegCode,
            ProductName,
            ProductDate,
            ContractStatus,
            OldSerial,
            [Desc],
            [DateTime]
        FROM
            RankedTags
        WHERE
            rn = 1
        ORDER BY
            [DateTime] DESC;";

        return dataAccess.SqlDataAdapter(command);
    }

