        return "موجودی : " + Environment.NewLine + "تعداد" + Environment.NewLine + _dt.Rows[0]["Count"].ToString() + Environment.NewLine + "متراژ" + Environment.NewLine + _dt.Rows[0]["SumValue"].ToString();
