    public DataTable SReportOnProductSize(IndexSearch search)
    {

        var whereString = SGetWhereStringSearchIndex(search);

        if (!string.IsNullOrEmpty(whereString))
            whereString = (" WHERE " + whereString);

        var cmd = $@" SELECT        COALESCE (tbl_Products.ProductSize, N'نامشخص') AS ProductSize, COUNT(tbl_Tags.ProductSerial) AS CountSerial, SUM(tbl_Tags.ProductCount) AS SumValue, SUM(tbl_Tags.ProductCount) * 100 /
                             (SELECT        SUM(ProductCount) AS Expr1
                               FROM            tbl_Tags AS tbl_Tags_1) AS [Percent]
FROM            tbl_Tags LEFT OUTER JOIN
                         tbl_Products ON tbl_Tags.ProductCode = tbl_Products.ProductCode
{whereString}
GROUP BY tbl_Products.ProductSize ";

        return dataAccess
            .SqlDataAdapter(cmd);
    }

