    #region Freeze Tags
    public int SSaveFreeze(FreezeSaveDto freeze)
    {
        string userId = httpContext.User.GetUserId();

        FreezeHeader freezeHeader = new()
        {
            UserId = userId,
            Description = freeze.Description,
            Status = freeze.Status,
            FreezeItems = new List<FreezeItem>()
        };

        string serialString = string.Empty;

        foreach (string serial in freeze.Serials)
        {
            freezeHeader.FreezeItems.Add(new()
            {
                ProductSerial = serial,
                FreezeHeader = freezeHeader
            });

            serialString += $",N'{serial}'";
        }

        serialString = serialString.Remove(0, 1);

        apiContext.FreezeHeaders.Add(freezeHeader);

        string commandTags = $" UPDATE tbl_Tags SET Freeze = {(freeze.Status ? 1 : 0)} WHERE ProductSerial IN ({serialString}) ";

        if (dataAccess.CmdSqlExecuteNonQuery(commandTags) > 0)
        {
            if (apiContext.SaveChanges() > 0)
            {
                return int.Parse(GetLatestIdOfIdentityTable("tbl_FreezeHeader"));
            }
        }

        return 0;
    }

    public DataTable SGetFreezeHeaderReport(GetFreezeHeaderReportDto search)
    {
        string where = string.Empty;

        if (search.ProductSerial.NotEquals("-1"))
        {
            if (where.HasValue())
            {
                where += " AND ";
            }

            where += $" tbl_FreezeItem.fld_FreezeProductSerial= N'{search.ProductSerial}' ";
        }

        if (search.FromDate.NotEquals("-1"))
        {
            if (where.HasValue())
            {
                where += " AND ";
            }

            where += $" dbo.GeorgianDateToJalaliDate(tbl_FreezeHeader.fld_FreezeSaveDateTime) >= N'{search.FromDate}' ";
        }

        if (search.ToDate.NotEquals("-1"))
        {
            if (where.HasValue())
            {
                where += " AND ";
            }

            where += $" dbo.GeorgianDateToJalaliDate(tbl_FreezeHeader.fld_FreezeSaveDateTime) <= N'{search.ToDate}' ";
        }

        if (search.UserId.NotEquals("-1"))
        {
            if (where.HasValue())
            {
                where += " AND ";
            }

            where += $" tbl_FreezeHeader.fld_FreezeUserId = N'{search.UserId}' ";
        }

        if (search.ProductCode.NotEquals("-1"))
        {
            if (where.HasValue())
            {
                where += " AND ";
            }

            where += $" tbl_Tags.ProductCode = N'{search.ProductCode}' ";
        }

        if (search.TechnicalCode.NotEquals("-1"))
        {
            if (where.HasValue())
            {
                where += " AND ";
            }

            if (!search.TechnicalCodeLike)
            {
                where += $" tbl_Tags.RegCode = N'{search.TechnicalCode}' ";
            }
            else
            {
                where += $" tbl_Tags.RegCode Like N'%{search.TechnicalCode}%' ";
            }
        }

        if (where.HasValue())
        {
            where = $" WHERE {where}";
        }

        string command = $@"SELECT DISTINCT	COALESCE(tbl_FreezeHeader.fld_FreezeHeaderId,N'') as HeaderId,
                                    CASE tbl_FreezeHeader.fld_FreezeResult WHEN 1 THEN N'فریز' ELSE N'عدم فریز' END as FreezeStatus,
                                    tbl_FreezeHeader.fld_FreezeSaveDateTime AS DateTime,
                                    COUNT(tbl_FreezeItem.fld_FreezeProductSerial) AS [Count],
                                    COALESCE((SELECT tbl_User.[Name] FROM tbl_User WHERE tbl_User.Id = tbl_FreezeHeader.fld_FreezeUserId),N'') AS UserName
                            FROM tbl_FreezeHeader 
						    INNER JOIN tbl_FreezeItem ON tbl_FreezeHeader.fld_FreezeHeaderId = tbl_FreezeItem.fld_FreezeHeaderId 
                            LEFT JOIN tbl_Tags ON tbl_Tags.ProductSerial = tbl_FreezeItem.fld_FreezeProductSerial
                            {where}
                            GROUP BY tbl_FreezeHeader.fld_FreezeHeaderId ,tbl_FreezeHeader.fld_FreezeResult 
                                    ,tbl_FreezeHeader.fld_FreezeSaveDateTime , tbl_FreezeHeader.fld_FreezeUserId";

        return dataAccess.SqlDataAdapter(command);
    }

    public DataTable SGetFreezeItemReport(GetFreezeItemReportDto search)
    {
        string where = $@" WHERE tbl_FreezeItem.fld_FreezeHeaderId = {search.HeaderId} ";

        if (search.ProductSerial.NotEquals("-1"))
        {
            where += $" AND tbl_Tags.ProductSerial = N'{search.ProductSerial}' ";
        }

        if (search.FromDate.NotEquals("-1"))
        {
            where += $" AND dbo.GeorgianDateToJalaliDate(tbl_FreezeHeader.fld_FreezeSaveDateTime) >= N'{search.FromDate}' ";
        }

        if (search.ToDate.NotEquals("-1"))
        {
            where += $" AND dbo.GeorgianDateToJalaliDate(tbl_FreezeHeader.fld_FreezeSaveDateTime) <= N'{search.ToDate}' ";
        }

        if (search.UserId.NotEquals("-1"))
        {
            where += $" AND tbl_FreezeHeader.fld_FreezeUserId = N'{search.UserId}' ";
        }

        if (search.ProductCode.NotEquals("-1"))
        {
            where += $" AND tbl_Tags.ProductCode = N'{search.ProductCode}' ";
        }

        if (search.TechnicalCode.NotEquals("-1"))
        {
            if (!search.TechnicalCodeLike)
            {
                where += $" AND tbl_Tags.RegCode = N'{search.TechnicalCode}' ";
            }
            else
            {
                where += $" AND tbl_Tags.RegCode Like N'%{search.TechnicalCode}%' ";
            }
        }

        string command = $@"SELECT	COALESCE(tbl_FreezeItem.fld_FreezeProductSerial,N'') AS ProductSerial,
									COALESCE(tbl_Tags.ProductCode,N'') AS ProductCode,
									COALESCE(tbl_Tags.RegCode,N'') AS TechnicalCode,
									COALESCE(tbl_Tags.ProductName,N'') AS ProductName,
									COALESCE(tbl_Tags.ProductCount,N'') AS [Count]
                            FROM tbl_FreezeItem LEFT OUTER JOIN
							tbl_Tags ON tbl_FreezeItem.fld_FreezeProductSerial = tbl_Tags.ProductSerial LEFT OUTER JOIN
							tbl_FreezeHeader ON tbl_FreezeItem.fld_FreezeHeaderId = tbl_FreezeHeader.fld_FreezeHeaderId
                            {where}";

        return dataAccess.SqlDataAdapter(command);
    }

    public List<GetFreezeHeaderBySerialDto> SGetFreezeHeadersBySerial(string serial)
    {
        List<FreezeHeader> result = apiContext.FreezeItems
                               .Include(p => p.FreezeHeader.User)
                               .Where(p => p.ProductSerial == serial)
                               .Select(p => p.FreezeHeader)
                               .ToList();

        return mapper.Map<List<GetFreezeHeaderBySerialDto>>(result);
    }

    public DataTable SGetFreezeProducts(List<ReportFilter> filters)
    {
        string whereString = " Where Tags.Freeze = 1 ";

        List<KeyValuePair<string, object>> parameters = new();

        foreach (ReportFilter filter in filters)
        {
            whereString += " AND ";

            if (filter.FieldName.Equals("tbl_FreezeHeader.FromDate"))
            {
                whereString += $" tbl_FreezeHeader.fld_FreezeSaveDateTime >= @FromDate ";

                parameters.Add(new("FromDate", PersianCalendarTools.PersianToGregorian(filter.Value)));
            }
            else if (filter.FieldName.Equals("tbl_FreezeHeader.ToDate"))
            {
                whereString += $" tbl_FreezeHeader.fld_FreezeSaveDateTime < @ToDate ";

                parameters.Add(new("ToDate", PersianCalendarTools.PersianToGregorian(filter.Value)));
            }
            else
            {
                whereString += $"{filter.FieldName} = N'{filter.Value}'";
            }
        }

        var cmd = $"""
            SELECT        COALESCE (Tags.ProductSerial, N'') AS ProductSerial, COALESCE (Tags.ProductCode, N'') AS ProductCode, COALESCE (Tags.RegCode, N'') AS Regcode, COALESCE (Tags.ProductName, N'') AS ProductName, 
                                     COALESCE (Tags.ProductCount, 0) AS ProductCount, COALESCE (Qc.ProductStatusTitle, N'') AS Qc, COALESCE (Size.fld_ProductPropertyCTitle, N'') AS Size, COALESCE (Line.fld_ProductPropertyATitle, N'') AS Line, 
                                     COALESCE
                                         ((SELECT        TOP (1) tbl_User.Name
                                             FROM            tbl_User RIGHT OUTER JOIN
                                                                      tbl_FreezeHeader ON tbl_User.Id = tbl_FreezeHeader.fld_FreezeUserId RIGHT OUTER JOIN
                                                                      tbl_FreezeItem ON tbl_FreezeHeader.fld_FreezeHeaderId = tbl_FreezeItem.fld_FreezeHeaderId
                                             WHERE        (tbl_FreezeItem.fld_FreezeProductSerial = Tags.ProductSerial)
                                             ORDER BY tbl_FreezeItem.fld_FreezeHeaderId DESC), N'') AS [User],
                                         (SELECT        TOP (1) tbl_FreezeHeader_2.fld_FreezeSaveDateTime
                                           FROM            tbl_FreezeItem AS tbl_FreezeItem_2 LEFT OUTER JOIN
                                                                     tbl_FreezeHeader AS tbl_FreezeHeader_2 ON tbl_FreezeItem_2.fld_FreezeHeaderId = tbl_FreezeHeader_2.fld_FreezeHeaderId
                                           WHERE        (tbl_FreezeItem_2.fld_FreezeProductSerial = Tags.ProductSerial)
                                           ORDER BY tbl_FreezeItem_2.fld_FreezeHeaderId DESC) AS DateTime, COALESCE
                                         ((SELECT        TOP (1) tbl_FreezeHeader_1.fld_FreezeDesc
                                             FROM            tbl_FreezeItem AS tbl_FreezeItem_1 LEFT OUTER JOIN
                                                                      tbl_FreezeHeader AS tbl_FreezeHeader_1 ON tbl_FreezeItem_1.fld_FreezeHeaderId = tbl_FreezeHeader_1.fld_FreezeHeaderId
                                             WHERE        (tbl_FreezeItem_1.fld_FreezeProductSerial = Tags.ProductSerial)
                                             ORDER BY tbl_FreezeItem_1.fld_FreezeHeaderId DESC), N'') AS [Desc]
            FROM            tbl_ProductPropertyC AS Size RIGHT OUTER JOIN
                                     tbl_Tags AS Tags ON Size.fld_ProductPropertyCId = Tags.fld_ProductPropertyCId LEFT OUTER JOIN
                                     tbl_ProductStatus AS Qc ON Tags.ProductStatus = Qc.ProductStatusCode LEFT OUTER JOIN
                                     tbl_ProductPropertyA AS Line ON Tags.fld_ProductPropertyAId = Line.fld_ProductPropertyAId
             {whereString}
            """;

        return dataAccess.SqlDataAdapter(cmd);
    }


