    #region Api Sync
    public DataTable SSearchApiSync(SearchApiSyncSto request)
    {
        string[] StartShiftTime = new string[3];
        DataTable shiftList = SPGetShiftStartENDList();
        foreach (DataRow dr in shiftList.Rows)
        {
            string Temp = dr["fld_ProductPropertyBDesc"].ToString().Split('-')[0];
            StartShiftTime[Convert.ToInt32(dr["fld_ProductPropertyBId"].ToString()) - 1] = Temp;
        }
        var whereString = $@"WHERE tbl_TagsMovement.ProductCode IS NOT NULL AND tbl_Products.ProductTitle IS NOT NULL ";
        var whereStringSubQuery = $@"WHERE tbl_TagsMovement_1.ProductCode=tbl_TagsMovement.ProductCode ";

        if (request.ProductCode.HasValue())
        {
            whereString += string.IsNullOrEmpty(whereString) ? "" : " AND ";
            whereString += $" tbl_TagsMovement.ProductCode = N'{request.ProductCode}' ";

            whereStringSubQuery += string.IsNullOrEmpty(whereStringSubQuery) ? "" : " AND ";
            whereStringSubQuery += $" tbl_TagsMovement_1.ProductCode = N'{request.ProductCode}' ";
        }

        if (request.Date.HasValue())
        {


            whereString += string.IsNullOrEmpty(whereString) ? "" : " AND ";
            whereString += $" tbl_TagsMovement.RTagsMovementDateTime >= dbo.JalaliDateToGeorgianDate(N'{request.Date}', N'06:00') ";

            whereString += string.IsNullOrEmpty(whereString) ? "" : " AND ";
            whereString += $" tbl_TagsMovement.RTagsMovementDateTime < DATEADD(day,1,dbo.JalaliDateToGeorgianDate(N'{request.Date}', N'06:00')) ";


            whereStringSubQuery += string.IsNullOrEmpty(whereStringSubQuery) ? "" : " AND ";
            whereStringSubQuery += $" tbl_TagsMovement_1.RTagsMovementDateTime >= dbo.JalaliDateToGeorgianDate(N'{request.Date}', N'06:00') ";

            whereStringSubQuery += string.IsNullOrEmpty(whereStringSubQuery) ? "" : " AND ";
            whereStringSubQuery += $" tbl_TagsMovement_1.RTagsMovementDateTime < DATEADD(day,1,dbo.JalaliDateToGeorgianDate(N'{request.Date}', N'06:00')) ";
        }

        if (request.ProductQc.HasValue())
        {
            whereString += string.IsNullOrEmpty(whereString) ? " " : " AND ";
            whereString += $" tbl_Products.ProductStatus  = N'{request.ProductQc}' ";

            whereStringSubQuery += string.IsNullOrEmpty(whereStringSubQuery) ? "" : " AND ";
            whereStringSubQuery += $" (tbl_Products_1.ProductStatus = N'{request.ProductQc}') ";
        }

        if (request.ProductSize.HasValue())
        {
            whereString += string.IsNullOrEmpty(whereString) ? " " : " AND ";
            whereString += $" tbl_Products.ProductSize  = N'{request.ProductSize}' ";

            whereStringSubQuery += string.IsNullOrEmpty(whereStringSubQuery) ? "" : " AND ";
            whereStringSubQuery += $" (tbl_Products_1.ProductSize = N'{request.ProductSize}') ";
        }

        if (request.RegCode.HasValue())
        {

            whereString += string.IsNullOrEmpty(whereString) ? "" : " AND ";
            whereString += $" tbl_Products.ProductTechnicalCode  = N'{request.RegCode}' ";

            whereStringSubQuery += string.IsNullOrEmpty(whereStringSubQuery) ? "" : " AND ";
            whereStringSubQuery += $" tbl_Products_1.ProductTechnicalCode  = N'{request.RegCode}' ";

        }

        if (request.WarehouseCode.HasValue())
        {
            whereString += string.IsNullOrEmpty(whereString) ? " " : " AND ";
            whereString += $@"  tbl_TagsMovement.RMovementActionDestinationId = N'{request.WarehouseCode}'";

            whereStringSubQuery += string.IsNullOrEmpty(whereStringSubQuery) ? "" : " AND ";
            whereStringSubQuery += $"  (tbl_TagsMovement_1.RMovementActionDestinationId = N'{request.WarehouseCode}')";
        }

        if (request.ProductType.HasValue())
        {
            whereString += string.IsNullOrEmpty(whereString) ? "" : " AND ";
            whereString += $" tbl_Products.ProductType  = N'{request.ProductType}' ";

            whereStringSubQuery += string.IsNullOrEmpty(whereStringSubQuery) ? "" : " AND ";
            whereStringSubQuery += $" tbl_Products_1.ProductType  = N'{request.ProductType}' ";
        }


        if (request.ActionType is not null)
        {
            whereString += string.IsNullOrEmpty(whereString) ? " " : " AND ";
            whereString += $@"  tbl_TagsMovement.RMovementActionType = {request.ActionType} ";

            whereStringSubQuery += string.IsNullOrEmpty(whereStringSubQuery) ? "" : " AND ";
            whereStringSubQuery += $" (tbl_TagsMovement_1.RMovementActionType = {request.ActionType} )";
        }

        var cmd = $@" 
        SELECT [NESTED].ProductCode,[NESTED].ProductTypeCode,[NESTED].ProductTypeTitle,[NESTED].RegCode,
        [NESTED].ProductTitle,[NESTED].Size,[NESTED].Qc,[NESTED].StoreCode,[NESTED].Count,
        CASE WHEN [NESTED].ProductValue = 0 THEN 0 ELSE CAST([NESTED].SumCount / [NESTED].ProductValue AS decimal(18,2)) END AS ProductCountInPack,[NESTED].AvgApiSendStatus,[NESTED].SumCount
        FROM(
                SELECT Distinct   COALESCE (tbl_TagsMovement.ProductCode, N'') AS ProductCode,
                COALESCE (tbl_Products.ProductType, N'0') AS ProductTypeCode, 
                COALESCE (tbl_ProductType.ProductTypeTitle, N'') AS ProductTypeTitle ,
                COALESCE (tbl_Products.ProductTechnicalCode, N'') AS RegCode, 
                COALESCE (tbl_Products.ProductTitle, N'') AS ProductTitle, 
                COALESCE (tbl_Products.ProductSize, N'') AS Size, COALESCE (tbl_Products.ProductStatus, N'') AS Qc,
                COALESCE (tbl_TagsMovement.RMovementActionDestinationId, N'') AS StoreCode,
                COUNT(Distinct tbl_TagsMovement.ProductSerial) AS Count, COALESCE (tbl_Products.ProductValue, 0) AS ProductValue, SUM(COALESCE(tbl_TagsMovement.ApiSendStatus,0)) AvgApiSendStatus,
                COALESCE
                                    ((SELECT        SUM(ProductCount) AS Expr1
                                        FROM            tbl_Tags
                                        WHERE        (ProductSerial IN
                                                                    (SELECT DISTINCT tbl_TagsMovement_1.ProductSerial
                                                                    FROM            tbl_TagsMovement AS tbl_TagsMovement_1 LEFT OUTER JOIN
                                                                                                tbl_Products AS tbl_Products_1 ON tbl_TagsMovement_1.ProductCode = tbl_Products_1.ProductCode LEFT OUTER JOIN
                                                                                                tbl_MovementActions AS tbl_MovementActions_1 ON tbl_TagsMovement_1.RMovementActionId = tbl_MovementActions_1.MovementActionId
                                                                {whereStringSubQuery}       ))), 0) AS SumCount
                FROM            tbl_ProductType RIGHT OUTER JOIN
                                tbl_Products ON tbl_ProductType.ProductTypeCode = tbl_Products.ProductType RIGHT OUTER JOIN
                                tbl_TagsMovement ON tbl_Products.ProductCode = tbl_TagsMovement.ProductCode LEFT OUTER JOIN
                                tbl_MovementActions ON tbl_TagsMovement.RMovementActionId = tbl_MovementActions.MovementActionId
                {whereString}
                GROUP BY tbl_TagsMovement.ProductCode, tbl_Products.ProductTitle, tbl_Products.ProductTechnicalCode, tbl_Products.ProductSize, tbl_Products.ProductStatus, tbl_TagsMovement.RMovementActionDestinationId, tbl_Products.ProductType, 
                tbl_ProductType.ProductTypeTitle, tbl_Products.ProductValue 
        ) AS [NESTED] order by [NESTED].RegCode";


        logger.LogInformation("SSearchApiSync" + " command: " + cmd
    , new KeyValuePair<string, object>("Command", cmd)
    );


        return dataAccess.SqlDataAdapter(cmd, 120);
    }

    public DataTable SSearchApiSyncDetails(SearchApiSyncSto request)
    {
        string[] startShiftTime = new string[3];
        DataTable shiftList = SPGetShiftStartENDList();
        foreach (DataRow dr in shiftList.Rows)
        {
            string Temp = dr["fld_ProductPropertyBDesc"].ToString().Split('-')[0];
            startShiftTime[Convert.ToInt32(dr["fld_ProductPropertyBId"].ToString()) - 1] = Temp;
        }

        string whereString = "";

        if (request.ProductType.HasValue())
        {
            whereString += $"AND tbl_ProductType.ProductTypeCode = N'{request.ProductType}' ";
        }

        if (request.ProductCode.HasValue())
        {
            whereString += $"AND Tags.ProductCode = N'{request.ProductCode}' ";
        }

        if (request.WarehouseCode.HasValue())
        {
            whereString += $"AND tbl_MovementActions.MovementActionStore = N'{request.WarehouseCode}' ";
        }



        if (request.Date.HasValue())
        {


            whereString += $"AND tbl_MovementActions.MovementActionDateTime >= dbo.JalaliDateToGeorgianDate(N'{request.Date}', N'06:00') ";

            whereString += $"AND tbl_MovementActions.MovementActionDateTime < DATEADD(day,1,dbo.JalaliDateToGeorgianDate(N'{request.Date}', N'06:00')) ";


        }

        if (request.RegCode.HasValue())
        {
            whereString += $"AND Tags.RegCode = N'{request.RegCode}' ";
        }

        if (request.GateCode.HasValue())
        {
            whereString += $"AND tbl_MovementActions.MovementActionUHFLogGate = N'{request.GateCode}' ";
        }

        if (request.ProductSize.HasValue())
        {
            whereString += $"AND Tags.fld_ProductPropertyCId = N'{request.ProductSize}' ";
        }

        if (request.ProductQc.HasValue())
        {
            whereString += $"AND Tags.ProductStatus = N'{request.ProductQc}' ";
        }

        if (whereString != "")
            whereString = " where " + whereString.Substring(4);

        string command =
    $"""
       SELECT   DISTINCT      Tags.ProductSerial, Tags.ProductName AS ProductTitle, Tags.TagRegisterShamsiUnixDate AS RegisterDateTime, Tags.TagZone
       FROM            
                                tbl_MovementActions   RIGHT OUTER JOIN
                                tbl_ProductType RIGHT OUTER JOIN
                                tbl_Products ON tbl_ProductType.ProductTypeCode = tbl_Products.ProductType RIGHT OUTER JOIN
                                tbl_TagsMovement LEFT OUTER JOIN
                                tbl_Tags AS Tags ON tbl_TagsMovement.ProductSerial = Tags.ProductSerial ON tbl_Products.ProductCode = Tags.ProductCode ON 
                                tbl_MovementActions.MovementActionId = tbl_TagsMovement.RMovementActionId LEFT OUTER JOIN
                                tbl_ProductStatus ON tbl_Products.ProductStatus = tbl_ProductStatus.ProductStatusCode
                {whereString}
       """;
        logger.LogInformation("SSearchApiSyncDetails" + Environment.NewLine +
                      JsonConvert.SerializeObject(request) + Environment.NewLine + " Command : " + command);

        return dataAccess.SqlDataAdapter(command);
    }

    public bool SUpdateProductCodeForSendToApi(SearchApiSyncSto request, string newCode)
    {




        string OldProductCode = request.ProductCode.ToString();

        logger.LogInformation("SUpdateProductCodeForSendToApi" + Environment.NewLine +
                   "OldProductCode : " + OldProductCode + Environment.NewLine +
                      "NewProductCode : " + newCode);

        var childrenCommands = new List<KeyValuePair<string, KeyValuePair<string, object>[]>>();
        var childrenCommandsProduct = new List<KeyValuePair<string, KeyValuePair<string, object>[]>>();


        string commandCheckProductCode = $" Select * From tbl_Products where ProductCode = '{newCode}'";

        var _dtCheckProductCode = dataAccess.SqlDataAdapter(commandCheckProductCode);

        if (_dtCheckProductCode.Rows.Count == 0)
        {
            var commandProducts = $"UPDATE tbl_Products SET ProductCode = @NewCode WHERE (ProductCode = @OldCode)";
            var parametersProducts = new List<KeyValuePair<string, object>>();
            parametersProducts.Add(new("NewCode", newCode));
            parametersProducts.Add(new("OldCode", OldProductCode));
            childrenCommandsProduct.Add(new(commandProducts, parametersProducts.ToArray()));
            dataAccess.CmdSqlExecuteNonQueryWithTransaction(childrenCommandsProduct);

        }



        var commandTagsMovement = $"UPDATE tbl_TagsMovement SET ProductCode = @NewCode WHERE (ProductCode = @OldCode)";
        var parametersTagsMovement = new List<KeyValuePair<string, object>>();
        parametersTagsMovement.Add(new("NewCode", newCode));
        parametersTagsMovement.Add(new("OldCode", OldProductCode));

        childrenCommands.Add(new(commandTagsMovement, parametersTagsMovement.ToArray()));

        var commandTags = $@"UPDATE tbl_Tags  SET ProductCode = @NewCode, ProductName=(select ProductTitle from tbl_Products where ProductCode=@NewCode), ProductType=(select ProductType from tbl_Products where ProductCode=@NewCode), RegCode=(select ProductTechnicalCode from tbl_Products where ProductCode=@NewCode), fld_ProductGroup=(select fld_ProductGroup from tbl_Products where ProductCode=@NewCode), fld_ProductBrand=(select fld_ProductBrand from tbl_Products where ProductCode=@NewCode), ProductStatus=(select ProductStatus from tbl_Products where ProductCode=@NewCode), fld_ProductPropertyCId=(select ProductSize from tbl_Products where ProductCode=@NewCode) WHERE(ProductCode = @OldCode)";
        var parametersTags = new List<KeyValuePair<string, object>>();
        parametersTags.Add(new("NewCode", newCode));
        parametersTags.Add(new("OldCode", OldProductCode));

        childrenCommands.Add(new(commandTags, parametersTags.ToArray()));



        var commandPrint = $@"UPDATE tbl_Print  SET ProductCode = @NewCode, ProductName=(select ProductTitle from tbl_Products where ProductCode=@NewCode), ProductType=(select ProductType from tbl_Products where ProductCode=@NewCode), ProductRegCode=(select ProductTechnicalCode from tbl_Products where ProductCode=@NewCode), fld_ProductGroup=(select fld_ProductGroup from tbl_Products where ProductCode=@NewCode), fld_ProductBrand=(select fld_ProductBrand from tbl_Products where ProductCode=@NewCode), ProductStatus=(select ProductStatus from tbl_Products where ProductCode=@NewCode), ProductSize=(select ProductSize from tbl_Products where ProductCode=@NewCode) WHERE(ProductCode = @OldCode)";
        var parametersPrint = new List<KeyValuePair<string, object>>();
        parametersPrint.Add(new("NewCode", newCode));
        parametersPrint.Add(new("OldCode", OldProductCode));

        childrenCommands.Add(new(commandPrint, parametersPrint.ToArray()));

        dataAccess.CmdSqlExecuteNonQueryWithTransaction(childrenCommands);

        return true;
    }

    public bool SSendActionToApi(SearchApiSyncSto request, SendActionToApiDto save)
    {
        var whereString = $@"WHERE tbl_TagsMovement.ProductCode IS NOT NULL AND tbl_Products.ProductTitle IS NOT NULL ";

        if (request.ProductCode.HasValue())
        {
            whereString += string.IsNullOrEmpty(whereString) ? "" : " AND ";
            whereString += $" tbl_TagsMovement.ProductCode = N'{request.ProductCode}' ";
        }

        if (request.Date.HasValue())
        {


            whereString += string.IsNullOrEmpty(whereString) ? "" : " AND ";
            whereString += $" tbl_MovementActions.MovementActionDateTime >= dbo.JalaliDateToGeorgianDate(N'{request.Date}', N'06:00') ";

            whereString += string.IsNullOrEmpty(whereString) ? "" : " AND ";
            whereString += $" tbl_MovementActions.MovementActionDateTime < DATEADD(day,1,dbo.JalaliDateToGeorgianDate(N'{request.Date}', N'06:00')) ";


        }


        if (request.ProductQc.HasValue())
        {
            whereString += string.IsNullOrEmpty(whereString) ? " " : " AND ";
            whereString += $" tbl_Products.ProductStatus  = N'{request.ProductQc}' ";
        }

        if (request.ProductSize.HasValue())
        {
            whereString += string.IsNullOrEmpty(whereString) ? " " : " AND ";
            whereString += $" tbl_Products.ProductSize  = N'{request.ProductSize}' ";
        }

        if (request.RegCode.HasValue())
        {

            whereString += string.IsNullOrEmpty(whereString) ? "" : " AND ";
            whereString += $" tbl_Products.ProductTechnicalCode  = N'{request.RegCode}' ";

        }

        if (request.WarehouseCode.HasValue())
        {
            whereString += string.IsNullOrEmpty(whereString) ? " " : " AND ";
            whereString += $@"  tbl_MovementActions.MovementActionStore = N'{request.WarehouseCode}'";
        }

        var cmd = $"""
            SELECT Distinct   COALESCE (tbl_TagsMovement.TagsMovementId, N'') AS ProductCode
            FROM            tbl_ProductType RIGHT OUTER JOIN
                         tbl_Products ON tbl_ProductType.ProductTypeCode = tbl_Products.ProductType RIGHT OUTER JOIN
                         tbl_TagsMovement ON tbl_Products.ProductCode = tbl_TagsMovement.ProductCode LEFT OUTER JOIN
                         tbl_MovementActions ON tbl_TagsMovement.RMovementActionId = tbl_MovementActions.MovementActionId
            {whereString} 
            """;

        var data = dataAccess.SqlDataAdapter(cmd).Select();

        List<string> updateCommands = new();

        foreach (var row in data)
        {
            updateCommands.Add($"UPDATE tbl_TagsMovement SET ApiSendStatus =1, ApiSendUser= N'{httpContext.User.GetUserId()}', ApiSendDateTime = Getdate(), ApiSendData = N'{JsonConvert.SerializeObject(save)}' WHERE TagsMovementId = {row.ItemArray[0]} ");
        }

        return dataAccess.CmdSqlExecuteNonQueryWithTransaction(updateCommands) == 1;
    }

    public int SCountProductCode(string productCode)
    {
        string command =
            $"""
            SELECT Count(ProductSerial)
            FROM tbl_Tags
