    #region Action Types
    public List<ActionType> SGetActionTypes()
    {
        string command = """
        SELECT 
            Id,
            fld_ActionTypeId AS Code,
            fld_ActionTypeFromDestinationType AS [From],
            fld_ActionTypeToTypeDestinationType AS [To],
            fld_ActionTypeTitle AS Title,
            fld_ActionTypePermitedDocStatus AS DocStatusPermitted,
            fld_ActionTypeChangeDocStatus AS DocStatusChange,
            fld_ActionTypeActiveControls AS ActiveControls,
            Coalesce(fld_ActionTypeRFIDPower,100) as RFIDPower,
            Coalesce(fld_ActionTypeChangeTagLocation,0) as ChangeTagLocation,
            Coalesce(fld_ActionTypeProductType,'0') as ProductType
        
        FROM tbl_ActionTypes
        """;

        DataRow[]? dt = dataAccess.SqlDataAdapter(command).Select();

        var actionTypes = new List<ActionType>();

        foreach (var row in dt)
        {
            var actionType = new ActionType
            {
                Id = row.Field<int>("Id"),
                Code = row.Field<int?>("Code"),
                From = row.Field<string>("From"),
                To = row.Field<string>("To"),
                Title = row.Field<string>("Title"),
                DocStatusPermitted = row.Field<string>("DocStatusPermitted"),
                DocStatusChange = row.Field<string>("DocStatusChange"),
                ActiveControls = row.Field<string>("ActiveControls"),
                RFIDPower = row.Field<int>("RFIDPower"),
                ChangeTagLocation= row.Field<int?>("ChangeTagLocation"),
                ProductType = row.Field<string?>("ProductType")
            };

            actionTypes.Add(actionType);
        }

        return actionTypes;
    }

    public ActionType SGetActionTypeBySourceAndDestination(string fromWarehouse, string toWarehouse)
    {
        var actionTypeCode = GetActionType(fromWarehouse, toWarehouse);

        string command = $"""
                SELECT 
                    Id,
                    fld_ActionTypeId AS Code,
                    fld_ActionTypeFromDestinationType AS [From],
                    fld_ActionTypeToTypeDestinationType AS [To],
                    fld_ActionTypeTitle AS Title,
                    fld_ActionTypePermitedDocStatus AS DocStatusPermitted,
                    fld_ActionTypeChangeDocStatus AS DocStatusChange,
                    fld_ActionTypeActiveControls AS ActiveControls,
                    Coalesce(fld_ActionTypeRFIDPower,100) as RFIDPower,
                    Coalesce(fld_ActionTypeChangeTagLocation,0) as ChangeTagLocation,
                    Coalesce(fld_ActionTypeProductType,'0') as ProductType
                FROM tbl_ActionTypes
                WHERE fld_ActionTypeId = N'{actionTypeCode}'
                """;

        DataRow[]? dt = dataAccess.SqlDataAdapter(command).Select();

        if (dt == null || dt.Length == 0)
        {
            return null;
        }

        var row = dt.First();

        var actionType = new ActionType
        {
            Id = row.Field<int>("Id"),
            Code = row.Field<int?>("Code"),
            From = row.Field<string>("From"),
            To = row.Field<string>("To"),
            Title = row.Field<string>("Title"),
            DocStatusPermitted = row.Field<string>("DocStatusPermitted"),
            DocStatusChange = row.Field<string>("DocStatusChange"),
            ActiveControls = row.Field<string>("ActiveControls"),
            RFIDPower = row.Field<int>("RFIDPower"),
            ChangeTagLocation = row.Field<int?>("ChangeTagLocation"),
            ProductType = row.Field<string?>("ProductType")
        };

        return actionType;
    }

