    public bool SRecalMovementActionType()
    {
        var tps = SGetActionTypes();

        string movementActionCommand = "SELECT tbl_MovementActions.MovementActionId, tbl_MovementActions.MovementActionDestinationId FROM tbl_MovementActions";

        var dt = dataAccess.SqlDataAdapter(movementActionCommand).Select();

        List<string> updateCommands = new();

        foreach (var row in dt)
        {
            var tp = -1;
            foreach (var type in tps)
            {
                var tos = type.To.Split(',');

                if (tos.Any(p => p.Equals(row.ItemArray[1].ToString())))
                {
                    tp = type.Code.Value;
                }
            }

            if (tp == -1)
            {
                continue;
            }

            updateCommands.Add($"""
                    UPDATE tbl_MovementActions SET tbl_MovementActions.MovementActionTp = {tp} 
                    WHERE tbl_MovementActions.MovementActionId = {row.ItemArray[0]} 
                """);
        }

        return dataAccess.CmdSqlExecuteNonQueryWithTransaction(updateCommands) == 1;
    }
