    public DataTable SGetProductBySerial(string serial)
    {
        string command = $"""
            SELECT  tbl_Tags.ProductSerial,
            		tbl_Tags.ProductCode,
            		tbl_Tags.ProductName,
            		tbl_Tags.RegCode,
                    tbl_Tags.TagEpc,
            		tbl_Tags.ProductCount as [Count],
            		tbl_Tags.TagRegisterShamsiUnixDate as [ProductDate],
            		COALESCE(CASE WHEN TRY_CONVERT(UNIQUEIDENTIFIER, tbl_Tags.Username) IS NOT NULL THEN  (SELECT [InnerUser].Username FROM tbl_User as [InnerUser] WHERE [InnerUser].Id = tbl_Tags.Username)
            					  ELSE COALESCE(tbl_Tags.Username,N'') END , N'') AS [User],
            		CASE WHEN tbl_Tags.Freeze = 0 THEN N'عدم فریز' WHEN tbl_Tags.TagStatus = 1 THEN N'فریز شده' ELSE N'-' END AS FreezeStatus,
            		CASE WHEN (tbl_Tags.Lock = 0 AND fld_LastInspectResult = N'[]') THEN N'بازرسی نشده' WHEN (tbl_Tags.Lock = 0 AND fld_LastInspectResult <> N'[]') THEN N'بازرسی تأیید' WHEN (tbl_Tags.Lock = 1 AND fld_LastInspectResult <> N'[]') THEN N'بازرسی مردود' ELSE N'-' END AS InspectStatus,
            		COALESCE(tbl_ProductGroup.fld_ProductGroupTitle,N'') as [ProductGroup],
            		COALESCE(tbl_ProductBrand.fld_ProductBrandCode,N'') as [ProductBrand],
            		tbl_ProductStatus.ProductStatusTitle as [Qc],
            		tbl_ProductPropertyC.fld_ProductPropertyCTitle as [Size],
                    COALESCE(tbl_Destination.DestinationTitle,N'') as [Warehouse]
            FROM tbl_Tags LEFT JOIN tbl_ProductType ON tbl_Tags.ProductType = tbl_ProductType.ProductTypeCode
            LEFT JOIN tbl_ProductBrand ON tbl_ProductBrand.fld_ProductBrandCode = tbl_Tags.fld_ProductBrand
            LEFT JOIN tbl_ProductGroup ON tbl_ProductGroup.fld_ProductGroupCode = tbl_Tags.fld_ProductGroup
            LEFT JOIN tbl_ProductStatus ON tbl_ProductStatus.ProductStatusCode = tbl_Tags.ProductStatus
            LEFT JOIN tbl_ProductPropertyC ON tbl_ProductPropertyC.fld_ProductPropertyCId = tbl_Tags.fld_ProductPropertyCId
            LEFT JOIN tbl_Destination ON tbl_Destination.DestinationCode = tbl_Tags.TagInDestinationId
            WHERE tbl_Tags.ProductSerial = N'{serial}' OR tbl_Tags.TagEpc = N'{serial}'
            """;

        return dataAccess.SqlDataAdapter(command);
    }

    public bool SCancelRegisterTag(string TagEpc, string username, string deviceId, string deviceIp)
    {
        if (username.HasNoValue())
        {
            username = httpContext.User.GetUserId();
        }

        try
        {
            if (TagEpc != "")
            {
                var childrenCommands = new List<KeyValuePair<string, KeyValuePair<string, object>[]>>();


                var sqlCommand = $@" DELETE FROM tbl_Tags  WHERE       (tbl_Tags.ProductSerial = N'{TagEpc}') OR
                                     (tbl_Tags.TagEpc = N'{TagEpc}')  "
                ;
                childrenCommands.Add(new(sqlCommand, new KeyValuePair<string, object>[]
                {
                new KeyValuePair<string, object>("TagEpc", TagEpc),
                }));

                var sqlCommandTagMovement = $@"DELETE   
                        FROM            tbl_TagsMovement
                        where  (ProductSerial = N'{TagEpc}') OR
                                     (TagEpc = N'{TagEpc}')  ";
                childrenCommands.Add(new(sqlCommandTagMovement, new KeyValuePair<string, object>[]
                {
                new KeyValuePair<string, object>("TagEpc", TagEpc),
                }));

                var sqlCommandPlacementMissions = @" DELETE
                    FROM            tbl_ProductPlacementMissions
                    where fld_PPMProductEPC = @TagEpc ";
                childrenCommands.Add(new(sqlCommandPlacementMissions, new KeyValuePair<string, object>[]
                {
                new KeyValuePair<string, object>("TagEpc", TagEpc),
                }));

                var sqlCommandPrint = $@" UPDATE        tbl_Print SET SoftDelete = '1', SoftDeleteUser = @UserName, SoftDeleteDate = @Date    where  (ProductSerial = N'{TagEpc}') OR
                                     (TagEpc = N'{TagEpc}')  ";
                var parameters = new List<KeyValuePair<string, object>>();
                parameters.Add(new("TagEpc", TagEpc));
                parameters.Add(new("UserName", username));
                parameters.Add(new("Date", DateTimeTools.GetPersianDate()));

                childrenCommands.Add(new(sqlCommandPrint, parameters.ToArray()));

                bool Result = dataAccess.CmdSqlExecuteNonQueryWithTransaction(childrenCommands) > 0;

                return Result;
            }
            else
            {
                return false;
            }
        }
        catch (Exception exception)
        {
            logger.LogWarning(exception, exception.Message);
            return false;
        }
    }

