    #region Private methods
    private string GetExitAgeAnalysis(string unixProductDate, string exitDate)
    {
        string normalProductDate =
            $"{unixProductDate.Substring(0, 4)}/{unixProductDate.Substring(4, 2)}/{unixProductDate.Substring(6, 2)}";

        double diff = (PersianCalendarTools.PersianToGregorian(exitDate) - PersianCalendarTools.PersianToGregorian(normalProductDate)).TotalDays;

        string ageAnalysis = string.Empty;

        switch (diff)
        {
            case <= 31:
                ageAnalysis = "تا یک ماه";
                break;
            case <= 93:
                ageAnalysis = "یک تا سه ماه";
                break;
            case <= 186:
                ageAnalysis = "سه تا شش ماه";
                break;
            case > 186 and <= 366:
                ageAnalysis = "شش ماه تا یک سال";
                break;
            case > 366:
                ageAnalysis = "بالای یک سال";
                break;
            default:
                ageAnalysis = "";
                break;
        }

        return ageAnalysis;
    }
    private string SGetWhereStringSearchIndex(IndexSearch search)
    {
        var whereString = string.Empty;

        if (!search.FromDate.Equals("-1"))
        {
            search.FromDate.Replace("/", "");
            search.FromDate = search.FromDate.Replace("/", ""); ;
            search.FromDate += "060101";

            if (!string.IsNullOrEmpty(whereString))
                whereString += " AND ";
            var date = search.FromDate.Replace("/", "");
            whereString += $" SUBSTRING(TagRegisterShamsiUnixDate,0,9) >= N'{date}' ";
        }

        if (!search.ToDate.Equals("-1"))
        {
            search.ToDate = search.ToDate.Replace("/", ""); ;
            search.ToDate += "060101";

            if (!string.IsNullOrEmpty(whereString))
                whereString += " AND ";
            var date = search.ToDate.Replace("/", "");
            whereString += $" SUBSTRING(TagRegisterShamsiUnixDate,0,9) <= N'{date}' ";
        }

        if (!search.Pl.Equals("-1"))
        {
            if (!string.IsNullOrEmpty(whereString))
                whereString += " AND ";
            whereString += $" tbl_ProductPropertyA.fld_ProductPropertyATitle LIKE N'%{search.Pl}%' ";
        }

        if (!search.Regcode.Equals("-1"))
        {
            if (!string.IsNullOrEmpty(whereString))
                whereString += " AND ";
            whereString += $" RegCode LIKE N'%{search.Regcode}%' ";
        }

        if (!search.Shift.Equals("-1"))
        {
            if (!string.IsNullOrEmpty(whereString))
                whereString += " AND ";
            whereString += $" tbl_ProductPropertyB.fld_ProductPropertyBTitle LIKE N'%{search.Shift}%' ";
        }

        return whereString;
    }

    private string SGetWhereStringSearchIndexForSubQuery(IndexSearch search, string tblName)
    {

        if (!search.FromDate.Equals("-1")
            && !search.ToDate.Equals("-1"))
            if (search.FromDate == search.ToDate)
                search.ToDate = PersianCalendarTools.GregorianToPersian(PersianCalendarTools.PersianToGregorian(search.ToDate).AddDays(1));


        var whereString = string.Empty;
        if (!search.FromDate.Equals("-1"))
        {
            search.FromDate.Replace("/", "");
            search.FromDate = search.FromDate.Replace("/", ""); ;
            search.FromDate += "060101";

            if (!string.IsNullOrEmpty(whereString))
                whereString += " AND ";

            whereString += $"  {tblName}.TagRegisterShamsiUnixDate  >= N'{search.FromDate}' ";
        }
        if (!search.ToDate.Equals("-1"))
        {
            search.ToDate = search.ToDate.Replace("/", ""); ;
            search.ToDate += "060101";

            if (!string.IsNullOrEmpty(whereString))
                whereString += " AND ";

            whereString += $"  {tblName}.TagRegisterShamsiUnixDate <  N'{search.ToDate}' ";
        }

        return whereString;
    }

