    public bool SSaveNdfLog(List<SaveNonDocFileCommand> commands)
    {
        string userId = httpContext.User.GetUserId();

        int type = -1;

        if (SaveLogs())
        {
            if ((NonDocFileTypeEnum)type == NonDocFileTypeEnum.CustomerAccountingData)
            {
                return SaveAccounting();
            }

            if ((NonDocFileTypeEnum)type == NonDocFileTypeEnum.CustomerRealityCountData)
            {
                return SaveRealityCountData();
            }

            if ((NonDocFileTypeEnum)type == NonDocFileTypeEnum.ProductData)
            {
                return SaveProduct();
            }
        }

        return false;

        bool SaveLogs()
        {
            List<NonDocFileLog> logs = new();

            foreach (SaveNonDocFileCommand command in commands)
            {
                if (type == -1)
                {
                    type = command.Type;
                }

                logs.Add(new()
                {
                    Type = command.Type,
                    Data = command.Data,
                    DateTime = DateTime.Now,
                    FileName = command.FileName,
                    User = userId
                });
            }

            apiContext.AddRange(logs);

            return apiContext.SaveChanges() > 0;
        }

        bool SaveAccounting()
        {
            int max = 0;

            try
            {
                max = apiContext.CustomerAccountingDatas.Max(p => p.OpCode) + 1;
            }
            catch
            {
                max++;
            }

            List<CustomerAccountingData> datas = new();

            foreach (SaveNonDocFileCommand command in commands)
            {
                var data = JToken.Parse(command.Data);
                int inventoryHeaderId = (int)data["inventoryHeaderId"];
                string productCode = data["productCode"].ToString();
                decimal sumCount = (decimal)data["sumCount"];
                decimal realityCount = (decimal)data["realityCount"];

                var existingData = apiContext.CustomerAccountingDatas
                    .FirstOrDefault(x => x.InventoryHeaderId == inventoryHeaderId && x.ProductCode == productCode);

                if (existingData != null)
                {
                    existingData.ProductCount = sumCount;
                }
                else
                {
                    datas.Add(new()
                    {
                        DateTime = DateTime.Now,
                        User = userId,
                        FileName = command.FileName,
                        ProductCode = productCode,
                        ProductCount = sumCount,
                        RealityCount = 0,
                        InventoryHeaderId = inventoryHeaderId,
                        OpCode = max
                    });
                }
            }

            if (datas.Any())
            {
                apiContext.CustomerAccountingDatas.AddRange(datas);
            }

            return apiContext.SaveChanges() > 0;
        }

        bool SaveRealityCountData()
        {
            int max = 0;

            try
            {
                max = apiContext.CustomerAccountingDatas.Max(p => p.OpCode) + 1;
            }
            catch
            {
                max++;
            }

            List<CustomerAccountingData> datas = new();

            foreach (SaveNonDocFileCommand command in commands)
            {
                var data = JToken.Parse(command.Data);
                int inventoryHeaderId = (int)data["inventoryHeaderId"];
                string productCode = data["productCode"].ToString();
                decimal sumCount = (decimal)data["sumCount"];
                decimal realityCount = (decimal)data["realityCount"];

                var existingData = apiContext.CustomerAccountingDatas
                    .FirstOrDefault(x => x.InventoryHeaderId == inventoryHeaderId && x.ProductCode == productCode);

                if (existingData != null)
                {
                    existingData.RealityCount = realityCount;
                }
                else
                {
                    datas.Add(new()
                    {
                        DateTime = DateTime.Now,
                        User = userId,
                        FileName = command.FileName,
                        ProductCode = productCode,
                        ProductCount = 0,
                        RealityCount = realityCount,
                        InventoryHeaderId = inventoryHeaderId,
                        OpCode = max
                    });
                }
            }

            if (datas.Any())
            {
                apiContext.CustomerAccountingDatas.AddRange(datas);
            }

            return apiContext.SaveChanges() > 0;
        }

        bool SaveProduct()
        {
            List<SaveProductCommand> saveProductCommand = new();

            foreach (var item in commands)
            {
                saveProductCommand.Add(System.Text.Json.JsonSerializer.Deserialize<SaveProductCommand>(item.Data));
            }

            return SSaveProductBatch(saveProductCommand) > 0;
        }
    }

    public bool SCheckCustomerProducts(string key)
    {
        DataTable _dtResult = new();

        DateTime? lastLog = null;

        var jobLogRows = dataAccess.SqlDataAdapter($" SELECT TOP(1) fld_JobLogValue FROM tbl_JobLog WHERE fld_JobLogType = 4 AND fld_JobLogValue IS NOT NULL AND fld_JobLogEventId = N'{key}' ORDER BY fld_JobLogId DESC ")
                                            .Select();

        if (jobLogRows.Any())
        {
            try
            {
                lastLog = DateTime.Parse(jobLogRows.First().ItemArray[0].ToString());
            }
            catch (Exception ex)
            {
                lastLog = null;
            }
        }

        var section = configuration.GetSection("ProjectConfigs")
                                                     .GetSection("WmsConfigs")
                                                     .GetSection("CustomerProductData")
                                                     .GetSection(key);

        string command = section["Command"];

        if (command.HasNoValue())
        {
            return false;
        }

        string whereClause = "";

        if (lastLog.HasValue)
        {
            whereClause = $" WHERE {section["Field_Check"]} > CAST(N'{lastLog.Value.AddSeconds(1)}' AS DATETIME)";
        }

        command = command + whereClause;

        command += $" ORDER BY {section["Field_Order"]} DESC";

        try
        {
            _dtResult = dataAccess.SqlDataAdapter(command,
                        configuration.GetConnectionString(key));
        }
        catch (Exception ex)
        {
            logger.LogError($"SCheckCustomerProducts - Error executing query: {ex.Message}");

            return false;
        }

        List<string> usedProductCodes = new();

        var rows = _dtResult.Select();

        string maxCheckValue = "0";

        int successCount = 0;
        int totalCount = rows.Length;

        var originalFileName = $"CustomerProducts_{key}_{PersianCalendarTools.GregorianToPersianWithManualSeprator(DateTime.Now, "")}";

        List<SaveNonDocFileCommand> ndfCommands = new();

        foreach (DataRow row in _dtResult.Rows)
        {
            string productCode = "";
            string rowCheckValue = "0";

            foreach (DataColumn column in _dtResult.Columns)
            {
                if (column.ColumnName == section["Field_Key"])
                {
                    productCode = row[column].ToString();
                }

                if (column.ColumnName == section["Field_Check"])
                {
                    rowCheckValue = row[column].ToString();
                }
            }

            if (maxCheckValue == "0")
            {
                maxCheckValue = rowCheckValue;
            }

            if (string.IsNullOrWhiteSpace(productCode))
            {
                continue;
            }

            if (usedProductCodes.Any(p => p.Equals(productCode)))
            {
                continue;
            }

            usedProductCodes.Add(productCode);

            // Map directly from the row since we already have all data
            var productCommand = MapDataRowToSaveProductCommand(row, productCode);

            ndfCommands.Add(new SaveNonDocFileCommand
            {
                Type = (int)NonDocFileTypeEnum.ProductData,
                FileName = originalFileName,
                Data = System.Text.Json.JsonSerializer.Serialize(productCommand)
            });
        }

        if (ndfCommands.Any())
        {
            bool ndfResult = SSaveNdfLog(ndfCommands);

            if (!ndfResult)
            {
                logger.LogError($"SCheckCustomerProducts - Failed to save NonDocFile logs");
                return false;
            }
        }

        string commandJobLog = string.Empty;

        logger.LogInformation($"SCheckCustomerProducts - Key: {key}, MaxCheckValue: {maxCheckValue}, Processed: {successCount}/{totalCount}");

        if (maxCheckValue == "0")
        {
            commandJobLog = @$" INSERT INTO tbl_JobLog (fld_JobLogType,fld_JobLogDateTime,fld_JobLogDate,fld_JobLogTime,fld_JobLogValue,fld_JobLogEventId) 
                           VALUES (4,GETDATE(),dbo.GeorgianDateToJalaliDate(GETDATE()),FORMAT(GETDATE(), 'HH:mm'),NULL,N'{key}')";
        }
        else
        {
            commandJobLog = @$" INSERT INTO tbl_JobLog (fld_JobLogType,fld_JobLogDateTime,fld_JobLogDate,fld_JobLogTime,fld_JobLogValue,fld_JobLogEventId) 
                           VALUES (4,GETDATE(),dbo.GeorgianDateToJalaliDate(GETDATE()),FORMAT(GETDATE(), 'HH:mm'),GetDate(),N'{key}')";
        }

        bool resultSaveJobLog = dataAccess.CmdSqlExecuteNonQuery(commandJobLog) > 0;

        logger.LogInformation("SCheckCustomerProducts" + Environment.NewLine
                            + "resultSaveJobLog:" + resultSaveJobLog);

        return true;

        SaveProductCommand MapDataRowToSaveProductCommand(DataRow row, string productCode)
        {
            SaveProductCommand command = new()
            {
                ProductCode = productCode,
                ProductTitle = row.Table.Columns.Contains("ProductTitle") ? row["ProductTitle"]?.ToString() ?? "" : "",
                ProductENTitle = row.Table.Columns.Contains("ProductENTitle") ? row["ProductENTitle"]?.ToString() : null,
                ProductType = row.Table.Columns.Contains("ProductType") ? row["ProductType"]?.ToString() : null,
                ProductTechnicalCode = row.Table.Columns.Contains("ProductTechnicalCode") ? row["ProductTechnicalCode"]?.ToString() : null,
                ProductSize = row.Table.Columns.Contains("ProductSize") ? row["ProductSize"]?.ToString() : null,
                ProductStatus = row.Table.Columns.Contains("ProductStatus") ? row["ProductStatus"]?.ToString() : null,
                ProductUnit = row.Table.Columns.Contains("ProductUnit") ? row["ProductUnit"]?.ToString() : null,
                ProductBrand = row.Table.Columns.Contains("ProductBrand") ? row["ProductBrand"]?.ToString() : null,
                ProductGroup = row.Table.Columns.Contains("ProductGroup") ? row["ProductGroup"]?.ToString() : null,
                ProductSubGroup = row.Table.Columns.Contains("ProductSubGroup") ? row["ProductSubGroup"]?.ToString() : null,
                ProductClass = row.Table.Columns.Contains("ProductClass") ? row["ProductClass"]?.ToString() : null,
                IsActive = true
            };

            if (row.Table.Columns.Contains("ProductPackValue") && decimal.TryParse(row["ProductPackValue"]?.ToString(), out decimal packValue))
            {
                command.ProductPackValue = packValue;
            }

            if (row.Table.Columns.Contains("ProductValue") && decimal.TryParse(row["ProductValue"]?.ToString(), out decimal productValue))
            {
                command.ProductValue = productValue;
            }

            if (row.Table.Columns.Contains("ProductPackWeight") && decimal.TryParse(row["ProductPackWeight"]?.ToString(), out decimal packWeight))
            {
                command.ProductPackWeight = packWeight;
            }

            if (row.Table.Columns.Contains("ProductPackVolume") && decimal.TryParse(row["ProductPackVolume"]?.ToString(), out decimal packVolume))
            {
                command.ProductPackVolume = packVolume;
            }

            if (row.Table.Columns.Contains("ProductCountInPack") && decimal.TryParse(row["ProductCountInPack"]?.ToString(), out decimal countInPack))
            {
                command.ProductCountInPack = countInPack;
            }

            return command;
        }
    }

    public List<CustomerAccountingData> SGetLastCAD()
    {
        int max = apiContext.CustomerAccountingDatas.Max(p => (int?)p.OpCode) ?? 0;

        return apiContext.CustomerAccountingDatas.Where(p => p.OpCode == max).ToList();
    }

    public bool SFixInventoryConflicts(SaveFixedConflictsCommand command)
    {
        string userId = httpContext.User.GetUserId();

