        bool uhfLogResult = SSaveGateLog(userId, invCod.ToString(), "WEB APP", command.Serials.Select(p => p.Epc).ToList(), null, "0");

        logger.LogInformation("SFixInventoryConflicts" + Environment.NewLine +
