        return false;
    }

    public GetWarehouseProductsListsVm SGetFreezedTagProductsBeforeMovements(GetInventoryConflictsQuery search)
    {
        #region Filters

        string[] StartShiftTime = new string[3];
        DataTable shiftList = SPGetShiftStartENDList();

        foreach (DataRow dr in shiftList.Rows)
        {
            string Temp = dr["fld_ProductPropertyBDesc"].ToString().Split('-')[0].Split(':')[0] + dr["fld_ProductPropertyBDesc"].ToString().Split('-')[0].Split(':')[1] + "01";
            StartShiftTime[Convert.ToInt32(dr["fld_ProductPropertyBId"].ToString()) - 1] = Temp;
        }

        List<string> productFilters = new();

        List<string> enterFilters = new();

        List<string> exitFilters = new();

        List<string> tagsMainWhere = new();

        List<string> tagsAllSubWhere = new();

        if (search.ProductCode.NotEquals("-1"))
        {
            productFilters.Add($"Tags.ProductCode = N'{search.ProductCode}' ");
        }

        if (search.FromDate.NotEquals("-1"))
        {
            string dateTimeFilter =
                PersianCalendarTools.PersianToGregorian(search.FromDate).ToShortDateString() + " " +
                StartShiftTime[0].Substring(0, 2) + ':' + StartShiftTime[0].Substring(2, 2) + ':' + StartShiftTime[0].Substring(4, 2);

            exitFilters.Add($"(ExitTags.RTagsMovementDateTime >= N'{dateTimeFilter}')");
            enterFilters.Add($"(EnterTags.RTagsMovementDateTime >= N'{dateTimeFilter}')");
        }

        if (search.ToDate.NotEquals("-1"))
        {
            string dateTimeFilter =
                PersianCalendarTools.PersianToGregorian(search.ToDate).ToShortDateString() + " " +
                StartShiftTime[0].Substring(0, 2) + ':' + StartShiftTime[0].Substring(2, 2) + ':' + StartShiftTime[0].Substring(4, 2);

            exitFilters.Add($"(ExitTags.RTagsMovementDateTime <= N'{dateTimeFilter}')");
            enterFilters.Add($"(EnterTags.RTagsMovementDateTime <= N'{dateTimeFilter}')");
        }

        if (search.TechnicalCode.NotEquals("-1"))
        {
            if (search.TechnicalCodeLike)
            {
                productFilters.Add($"(Tags.RegCode  Like N'%{search.TechnicalCode}%')");
            }
            else
            {
                productFilters.Add($"Tags.RegCode = N'{search.TechnicalCode}' ");
            }
        }

        if (search.Warehouse.NotEquals("-1"))
        {
            var warehouseValues = string.Join(",", search.Warehouse.Split(',').Select(w => $"N'{w.Trim()}'"));

            tagsMainWhere.Add($"(Tags.TagInDestinationId IN ({warehouseValues}))");
            tagsAllSubWhere.Add($"(TagsAll.TagInDestinationId IN ({warehouseValues}))");
            exitFilters.Add($"(tbl_MovementActions.MovementActionStore IN ({warehouseValues}))");
            exitFilters.Add($"(tbl_MovementActions.MovementActionDestinationId NOT IN ({warehouseValues}))");
            enterFilters.Add($"(tbl_MovementActions.MovementActionDestinationId IN ({warehouseValues}))");
            enterFilters.Add($"(tbl_MovementActions.MovementActionStore NOT IN ({warehouseValues}))");
            enterFilters.Add($"(Tags1.TagInDestinationId IN ({warehouseValues}))");
        }

        if (search.Type.NotEquals("-1"))
        {
            productFilters.Add($"Tags.ProductType = N'{search.Type}' ");
        }

        if (search.Qc.NotEquals("-1"))
        {
            productFilters.Add($"Tags.ProductStatus = N'{search.Qc}' ");
        }

        if (search.Size.NotEquals("-1"))
        {
            productFilters.Add($"Tags.fld_ProductPropertyCId = N'{search.Size}' ");
        }

        if (productFilters.Any())
        {
            tagsMainWhere.AddRange(productFilters);
        }
        #endregion

        #region Commands
        string mainCommand = $"""
            SELECT 
             COALESCE(Tags.ProductCode, N'')				 AS ProductCode
            ,COALESCE(Tags.ProductName, N'')				 AS ProductTitle
            ,COALESCE(Tags.RegCode, N'')					 AS RegCode
            ,COALESCE((SELECT TblStatus.ProductStatusTitle 
            		   FROM tbl_ProductStatus AS TblStatus 
            		   WHERE TblStatus.ProductStatusCode = Tags.ProductStatus),N'') AS ProductStatus
            ,COALESCE((SELECT TblSize.fld_ProductPropertyCTitle 
            		   FROM tbl_ProductPropertyC AS TblSize 
            		   WHERE TblSize.fld_ProductPropertyCId = Tags.fld_ProductPropertyCId),N'') AS ProductSize
            ,COALESCE(Tags.ProductSerial		,N'')		 AS ProductSerial
            ,COALESCE(Tags.TagEpc	,N'')					 AS Epc
            ,COALESCE(SUM(Tags.ProductCount),0)              AS ProductCount
            ,COALESCE(Tags.TagZone,'') as [ThisTagZone]
            ,COALESCE(( SELECT STRING_AGG( TagZone, ' | ') WITHIN GROUP (ORDER BY  TagZone) AS NewField 
            			FROM (
            					SELECT DISTINCT  ProductCode,[SubTag1].TagZone FROM [dbo].[tbl_Tags]   AS [SubTag1]  
            					WHERE [SubTag1].ProductCode = Tags.ProductCode  ) x GROUP BY  ProductCode),'0') as [Zones]
            ,0 AS [TagStatus]
            ,COALESCE(Tags.ContractStatus,N'') AS [ContractStatus]
            ,COALESCE((SELECT tbl_Destination.DestinationTitle
            FROM tbl_Destination RIGHT OUTER JOIN tbl_Tags AS Tags1 ON tbl_Destination.DestinationCode = Tags1.TagInDestinationId
            WHERE Tags.ProductSerial = Tags1.ProductSerial
            ),N'') AS [DestinationTitle]
            ,COALESCE(Tags.TagInDestinationId,N'') AS PLace
            FROM   tbl_Tags as Tags 
            {(tagsMainWhere.Any() ? " WHERE " + string.Join(" AND ", tagsMainWhere) : "")}

            GROUP BY Tags.ProductCode, Tags.ProductName, Tags.RegCode, Tags.ProductStatus,
            Tags.fld_ProductPropertyCId,Tags.TagZone,Tags.ProductSerial,Tags.TagEpc,
            Tags.ContractStatus,Tags.TagInDestinationId
            """;

        string exitedCommand = $"""
            SELECT 
             COALESCE(Tags.ProductCode, N'')				 AS ProductCode
            ,COALESCE(Tags.ProductName, N'')				 AS ProductTitle
            ,COALESCE(Tags.RegCode, N'')					 AS RegCode
            ,COALESCE((SELECT TblStatus.ProductStatusTitle 
            		   FROM tbl_ProductStatus AS TblStatus 
            		   WHERE TblStatus.ProductStatusCode = Tags.ProductStatus),N'') AS ProductStatus
            ,COALESCE((SELECT TblSize.fld_ProductPropertyCTitle 
            		   FROM tbl_ProductPropertyC AS TblSize 
            		   WHERE TblSize.fld_ProductPropertyCId = Tags.fld_ProductPropertyCId),N'') AS ProductSize
            ,COALESCE(Tags.ProductSerial		,N'')		 AS ProductSerial
            ,COALESCE(Tags.TagEpc	,N'')					 AS Epc
            ,COALESCE(SUM(Tags.ProductCount),0)              AS ProductCount
            ,COALESCE(Tags.TagZone,'') as [ThisTagZone]
            ,COALESCE(( SELECT STRING_AGG( TagZone, ' | ') WITHIN GROUP (ORDER BY  TagZone) AS NewField 
            			FROM (
            					SELECT DISTINCT  ProductCode,[SubTag1].TagZone FROM [dbo].[tbl_Tags]   AS [SubTag1]  
            					WHERE [SubTag1].ProductCode = Tags.ProductCode  ) x GROUP BY  ProductCode),'0') as [Zones]
            ,1 AS [TagStatus]
            FROM   tbl_Tags as Tags 
            WHERE  Tags.ProductSerial IN(
            										(
            											SELECT DISTINCT ExitTags.ProductSerial
            											FROM            tbl_TagsMovement as ExitTags INNER JOIN
            															tbl_MovementActions ON ExitTags.RMovementActionId = tbl_MovementActions.MovementActionId 
                                                        {(exitFilters.Any() ? " WHERE " + string.Join(" AND ", exitFilters) : "")}

            											EXCEPT

            											SELECT  TagsAll.ProductSerial
            											FROM    tbl_Tags as TagsAll
            									        {(tagsAllSubWhere.Any() ? " WHERE " + string.Join(" AND ", tagsAllSubWhere) : "")}
            										)

            								)
            {(productFilters.Any() ? string.Join(" AND ", productFilters) : "")}
            GROUP BY Tags.ProductCode, Tags.ProductName, Tags.RegCode, Tags.ProductStatus, Tags.fld_ProductPropertyCId,Tags.TagZone,Tags.ProductSerial,Tags.TagEpc
                                                
            """;

        string enteredCommand = $"""
            SELECT 
             COALESCE(Tags.ProductCode, N'')				 AS ProductCode
            ,COALESCE(Tags.ProductName, N'')				 AS ProductTitle
            ,COALESCE(Tags.RegCode, N'')					 AS RegCode
            ,COALESCE((SELECT TblStatus.ProductStatusTitle 
            		   FROM tbl_ProductStatus AS TblStatus 
            		   WHERE TblStatus.ProductStatusCode = Tags.ProductStatus),N'') AS ProductStatus
            ,COALESCE((SELECT TblSize.fld_ProductPropertyCTitle 
            		   FROM tbl_ProductPropertyC AS TblSize 
            		   WHERE TblSize.fld_ProductPropertyCId = Tags.fld_ProductPropertyCId),N'') AS ProductSize
            ,COALESCE(Tags.ProductSerial		,N'')		 AS ProductSerial
            ,COALESCE(Tags.TagEpc	,N'')					 AS Epc
            ,COALESCE(SUM(Tags.ProductCount),0)              AS ProductCount
            ,COALESCE(Tags.TagZone,'') as [ThisTagZone]
            ,COALESCE(( SELECT STRING_AGG( TagZone, ' | ') WITHIN GROUP (ORDER BY  TagZone) AS NewField 
            			FROM (
            					SELECT DISTINCT  ProductCode,[SubTag1].TagZone FROM [dbo].[tbl_Tags]   AS [SubTag1]  
            					WHERE [SubTag1].ProductCode = Tags.ProductCode  ) x GROUP BY  ProductCode),'0') as [Zones]
            ,2 AS [TagStatus]
            FROM   tbl_Tags as Tags 
            WHERE  Tags.ProductSerial IN(
            								SELECT DISTINCT EnterTags.ProductSerial
            								FROM            tbl_TagsMovement as EnterTags INNER JOIN
            												tbl_MovementActions ON EnterTags.RMovementActionId = tbl_MovementActions.MovementActionId 
            												INNER JOIN
            												tbl_Tags as Tags1 ON EnterTags.ProductSerial = Tags1.ProductSerial
            								{(enterFilters.Any() ? " WHERE " + string.Join(" AND ", enterFilters) : "")}
            							)
            {(productFilters.Any() ? string.Join(" AND ", productFilters) : "")}
            GROUP BY Tags.ProductCode, Tags.ProductName, Tags.RegCode, Tags.ProductStatus, Tags.fld_ProductPropertyCId,Tags.TagZone,Tags.ProductSerial,Tags.TagEpc
                                                
            """;
        #endregion

        #region Convert to List

        List<GetWarehouseProductsVm> mainList =
            dataAccess.SqlDataAdapter(mainCommand)
            .Select()
            .Select(rw =>
            new GetWarehouseProductsVm()
            {
                ProductCode = Convert.ToString(rw["ProductCode"]),
                ProductTitle = Convert.ToString(rw["ProductTitle"]),
                RegCode = Convert.ToString(rw["RegCode"]),
                Qc = Convert.ToString(rw["ProductStatus"]),
                ProductSize = Convert.ToString(rw["ProductSize"]),
                ProductSerial = Convert.ToString(rw["ProductSerial"]),
                ProductCount = Convert.ToDecimal(rw["ProductCount"]),
                Epc = Convert.ToString(rw["Epc"]),
                Zones = Convert.ToString(rw["Zones"]),
                ThisTagZone = Convert.ToString(rw["ThisTagZone"]),
                TagStatus = Convert.ToInt32(rw["TagStatus"])
            }).ToList();

        List<GetWarehouseProductsVm> exitList =
            dataAccess.SqlDataAdapter(exitedCommand)
            .Select()
            .Select(rw =>
            new GetWarehouseProductsVm()
            {
                ProductCode = Convert.ToString(rw["ProductCode"]),
                ProductTitle = Convert.ToString(rw["ProductTitle"]),
                RegCode = Convert.ToString(rw["RegCode"]),
                Qc = Convert.ToString(rw["ProductStatus"]),
                ProductSize = Convert.ToString(rw["ProductSize"]),
                ProductSerial = Convert.ToString(rw["ProductSerial"]),
                ProductCount = Convert.ToDecimal(rw["ProductCount"]),
                Epc = Convert.ToString(rw["Epc"]),
                Zones = Convert.ToString(rw["Zones"]),
                ThisTagZone = Convert.ToString(rw["ThisTagZone"]),
                TagStatus = Convert.ToInt32(rw["TagStatus"])
            }).ToList();

        List<GetWarehouseProductsVm> enterList =
            dataAccess.SqlDataAdapter(enteredCommand)
            .Select()
            .Select(rw =>
            new GetWarehouseProductsVm()
            {
                ProductCode = Convert.ToString(rw["ProductCode"]),
                ProductTitle = Convert.ToString(rw["ProductTitle"]),
                RegCode = Convert.ToString(rw["RegCode"]),
                Qc = Convert.ToString(rw["ProductStatus"]),
                ProductSize = Convert.ToString(rw["ProductSize"]),
                ProductSerial = Convert.ToString(rw["ProductSerial"]),
                ProductCount = Convert.ToDecimal(rw["ProductCount"]),
                Epc = Convert.ToString(rw["Epc"]),
                Zones = Convert.ToString(rw["Zones"]),
                ThisTagZone = Convert.ToString(rw["ThisTagZone"]),
                TagStatus = Convert.ToInt32(rw["TagStatus"])
            }).ToList();

        #endregion

        return new(mainList, exitList, enterList);
    }

