            else
            {
                productFilters.Add($"Tags.RegCode = N'{search.TechnicalCode}' ");
            }
        }

        if (search.Warehouse.NotEquals("-1"))
        {
            var warehouseValues = string.Join(",", search.Warehouse.Split(',').Select(w => $"N'{w.Trim()}'"));

            invTagMainWhere.Add($"(InvTagsMain.fld_InventoryStoreCode IN ({warehouseValues}))");
            invTagAllSubExitWhere.Add($"(InvTags1.fld_InventoryStoreCode IN ({warehouseValues}))");
            invTagAllSubEnterWhere.Add($"(InvTags2.fld_InventoryStoreCode IN ({warehouseValues}))");
            exitFilters.Add($"(tbl_MovementActions.MovementActionStore IN ({warehouseValues}))");
            exitFilters.Add($"(tbl_MovementActions.MovementActionDestinationId NOT IN ({warehouseValues}))");
            enterFilters.Add($"(tbl_MovementActions.MovementActionDestinationId IN ({warehouseValues}))");
            enterFilters.Add($"(tbl_MovementActions.MovementActionStore NOT IN ({warehouseValues}))");
        }

        if (search.Type.NotEquals("-1"))
        {
            productFilters.Add($"Tags.ProductType = N'{search.Type}' ");
        }

        if (search.Desc.NotEquals("-1"))
        {
            invTagMainWhere.Add($"(InvTagsMain.fld_InventoryProductDesc  Like N'%{search.Desc}%')");
            invTagAllSubExitWhere.Add($"(InvTags1.fld_InventoryProductDesc  Like N'%{search.Desc}%')");
            invTagAllSubEnterWhere.Add($"(InvTags2.fld_InventoryProductDesc  Like N'%{search.Desc}%')");
        }

        if (search.Place.NotEquals("-1"))
        {
            invTagMainWhere.Add($"(InvTagsMain.fld_InventoryPlace  = N'{search.Desc}')");
            invTagAllSubExitWhere.Add($"(InvTags1.fld_InventoryPlace  = N'{search.Desc}')");
            invTagAllSubEnterWhere.Add($"(InvTags2.fld_InventoryPlace  = N'{search.Desc}')");
        }

        if (search.Qc.NotEquals("-1"))
        {
            productFilters.Add($"Tags.ProductStatus = N'{search.Qc}' ");
        }

        if (search.Size.NotEquals("-1"))
        {
            productFilters.Add($"Tags.fld_ProductPropertyCId = N'{search.Size}' ");
        }

        if (search.User.NotEquals("-1"))
        {
            invTagMainWhere.Add($"(InvTagsMain.fld_InventoryUser = N'{search.User}') ");
            invTagAllSubExitWhere.Add($"(InvTags1.fld_InventoryUser  = N'{search.User}')");
            invTagAllSubEnterWhere.Add($"(InvTags2.fld_InventoryUser  = N'{search.User}')");
        }


        if (productFilters.Any())
        {
            invTagMainWhere.AddRange(productFilters);
        }

        if (invTagAllSubEnterWhere.Any())
        {
            enterFilters.AddRange(invTagAllSubEnterWhere);
        }

        #endregion

        #region Commands

        string mainInvCommand = $"""
            SELECT COALESCE(Tags.ProductCode, N'')				  AS ProductCode
            ,COALESCE (Tags.ProductName, N'')					  AS ProductName
            ,COALESCE (Tags.RegCode, N'')						  AS RegCode
            ,COALESCE(Tags.ProductSerial, N'')       		      AS ProductSerial
            ,COALESCE(Tags.TagEpc ,N'')	    					  AS Epc
            ,COALESCE(SUM(Tags.ProductCount),0)					  AS ProductCount
            ,COALESCE('','')	  AS [InventoryZone]
            ,N'{search.InventoryHeaderId}'		  AS [InventoryHeaderId]
            ,N''		  AS [Date]
            ,0 AS [TagStatus]
            ,COALESCE(Tags.ContractStatus,N'') AS [ContractStatus]
            ,COALESCE((SELECT tbl_Destination.DestinationTitle
            FROM tbl_Destination RIGHT OUTER JOIN tbl_Tags AS Tags1 ON tbl_Destination.DestinationCode = Tags1.TagInDestinationId
            WHERE Tags.ProductSerial = Tags1.ProductSerial
            ),N'') AS [DestinationTitle]
            ,COALESCE(Tags.TagInDestinationId,N'') AS Place

            FROM   tbl_Tags as Tags WHERE Tags.tagepc IN (SELECT distinct InvTagsMain.fld_InventoryTagEPC FROM tbl_InventoryTags AS InvTagsMain
            {(invTagMainWhere.Any() ? " WHERE " + string.Join(" AND ", invTagMainWhere) : "")})

            GROUP BY Tags.ProductCode, Tags.ProductName, Tags.RegCode,
                     Tags.ProductStatus, Tags.fld_ProductPropertyCId,Tags.TagZone, Tags.ProductSerial, Tags.TagEpc,
                     Tags.ContractStatus, Tags.TagInDestinationId
            """;

        string exitedCommand = $"""
            SELECT COALESCE(Tags.ProductCode, N'')				  AS ProductCode
            ,COALESCE (Tags.ProductName, N'')					  AS ProductName
            ,COALESCE (Tags.RegCode, N'')						  AS RegCode
            ,COALESCE(Tags.ProductSerial, N'')       		      AS ProductSerial
            ,COALESCE(Tags.TagEpc ,N'')	    					  AS Epc
            ,COALESCE(SUM(Tags.ProductCount),0)					  AS ProductCount
            ,COALESCE(InvTagsMain.fld_InventoryStoreCode,'')	  AS [InventoryZone]
            ,COALESCE(InvTagsMain.fld_InventoryHeaderId,'')		  AS [InventoryHeaderId]
            ,COALESCE(InvTagsMain.fld_InventoryDate,'')			  AS [Date]
            ,1 AS [TagStatus]
            ,COALESCE(Tags.ContractStatus,N'') AS [ContractStatus]
            ,COALESCE((SELECT tbl_Destination.DestinationTitle
            FROM tbl_Destination RIGHT OUTER JOIN tbl_Tags AS Tags1 ON tbl_Destination.DestinationCode = Tags1.TagInDestinationId
            WHERE Tags.ProductSerial = Tags1.ProductSerial
            ),N'') AS [DestinationTitle]
            ,COALESCE(Tags.TagInDestinationId,N'') AS Place

            FROM   tbl_Tags as Tags LEFT JOIN tbl_InventoryTags AS InvTagsMain ON Tags.TagEpc = InvTagsMain.fld_InventoryTagEPC
            WHERE  Tags.ProductSerial IN(
            								SELECT DISTINCT ExitTags.ProductSerial
            								FROM            tbl_TagsMovement as ExitTags INNER JOIN
            												tbl_MovementActions ON ExitTags.RMovementActionId = tbl_MovementActions.MovementActionId 
                                            {(exitFilters.Any() ? " WHERE " + string.Join(" AND ", exitFilters) : "")}

            								EXCEPT

            								SELECT  Tags2.ProductSerial
            								FROM    tbl_InventoryTags as InvTags1 INNER JOIN
            													tbl_Tags as Tags2 ON InvTags1.fld_InventoryTagEPC = Tags2.TagEpc
                                            {(invTagAllSubExitWhere.Any() ? " WHERE " + string.Join(" AND ", invTagAllSubExitWhere) : "")}
                        					)

            {(productFilters.Any() ? " AND " + string.Join(" AND ", productFilters) : "")}
            GROUP BY Tags.ProductCode, Tags.ProductName, Tags.RegCode,
                     Tags.ProductStatus, Tags.fld_ProductPropertyCId,Tags.TagZone, Tags.ProductSerial, Tags.TagEpc,
            		 InvTagsMain.fld_InventoryStoreCode, InvTagsMain.fld_InventoryHeaderId, InvTagsMain.fld_InventoryDate,
                     Tags.ContractStatus,Tags.TagInDestinationId
            """;

        string enteredCommand = $"""
            SELECT COALESCE(Tags.ProductCode, N'')				  AS ProductCode
            ,COALESCE (Tags.ProductName, N'')					  AS ProductName
            ,COALESCE (Tags.RegCode, N'')						  AS RegCode
            ,COALESCE(Tags.ProductSerial, N'')       		      AS ProductSerial
            ,COALESCE(Tags.TagEpc ,N'')	    					  AS Epc
            ,COALESCE(SUM(Tags.ProductCount),0)					  AS ProductCount
            ,COALESCE(InvTagsMain.fld_InventoryStoreCode,'')	  AS [InventoryZone]
            ,COALESCE(InvTagsMain.fld_InventoryHeaderId,'')		  AS [InventoryHeaderId]
            ,COALESCE(InvTagsMain.fld_InventoryDate,'')			  AS [Date]
            ,2 AS [TagStatus]
            ,COALESCE(Tags.ContractStatus,N'') AS [ContractStatus]
            ,COALESCE((SELECT tbl_Destination.DestinationTitle
            FROM tbl_Destination RIGHT OUTER JOIN tbl_Tags AS Tags1 ON tbl_Destination.DestinationCode = Tags1.TagInDestinationId
            WHERE Tags.ProductSerial = Tags1.ProductSerial
            ),N'') AS [DestinationTitle]
            ,COALESCE(Tags.TagInDestinationId,N'') AS Place

            FROM   tbl_Tags as Tags LEFT JOIN tbl_InventoryTags AS InvTagsMain ON Tags.TagEpc = InvTagsMain.fld_InventoryTagEPC
            WHERE  Tags.ProductSerial IN(
            								SELECT DISTINCT EnterTags.ProductSerial
                                            FROM            tbl_TagsMovement as EnterTags 
            				                                INNER JOIN tbl_InventoryTags AS InvTags2 ON EnterTags.TagEpc = InvTags2.fld_InventoryTagEPC
            				                                INNER JOIN tbl_MovementActions ON EnterTags.RMovementActionId = tbl_MovementActions.MovementActionId 
                                            {(enterFilters.Any() ? " WHERE " + string.Join(" AND ", enterFilters) : "")}
            							)

            {(productFilters.Any() ? " AND " + string.Join(" AND ", productFilters) : "")}
            GROUP BY Tags.ProductCode, Tags.ProductName, Tags.RegCode,
                     Tags.ProductStatus, Tags.fld_ProductPropertyCId,Tags.TagZone, Tags.ProductSerial, Tags.TagEpc,
            		 InvTagsMain.fld_InventoryStoreCode, InvTagsMain.fld_InventoryHeaderId, InvTagsMain.fld_InventoryDate,
                     Tags.ContractStatus,Tags.TagInDestinationId
            """;

        #endregion

        #region Convert to List

        List<GetInventoryResultTagVm> mainList =
            dataAccess.SqlDataAdapter(mainInvCommand)
            .Select()
            .Select(rw =>
            new GetInventoryResultTagVm()
            {
                InventoryHeaderId = Convert.ToInt32(rw["InventoryHeaderId"]),
                InventoryZone = Convert.ToString(rw["InventoryZone"]),
                InventoryDate = Convert.ToString(rw["Date"]),
                ProductCode = Convert.ToString(rw["ProductCode"]),
                ProductName = Convert.ToString(rw["ProductName"]),
                ProductSerial = Convert.ToString(rw["ProductSerial"]),
                Epc = Convert.ToString(rw["Epc"]),
                ProductCount = Convert.ToDecimal(rw["ProductCount"]),
                TagStatus = Convert.ToInt32(rw["TagStatus"]),
                ContractStatus = Convert.ToString(rw["ContractStatus"]),
                DestinationTitle = Convert.ToString(rw["DestinationTitle"]),
                Place = Convert.ToString(rw["Place"])
            }).ToList();

        List<GetInventoryResultTagVm> exitInvList =
            dataAccess.SqlDataAdapter(exitedCommand)
            .Select()
            .Select(rw =>
            new GetInventoryResultTagVm()
            {
                InventoryHeaderId = Convert.ToInt32(rw["InventoryHeaderId"]),
                InventoryZone = Convert.ToString(rw["InventoryZone"]),
                InventoryDate = Convert.ToString(rw["Date"]),
                ProductCode = Convert.ToString(rw["ProductCode"]),
                ProductName = Convert.ToString(rw["ProductName"]),
                ProductSerial = Convert.ToString(rw["ProductSerial"]),
                Epc = Convert.ToString(rw["Epc"]),
                ProductCount = Convert.ToDecimal(rw["ProductCount"]),
                TagStatus = Convert.ToInt32(rw["TagStatus"]),
                ContractStatus = Convert.ToString(rw["ContractStatus"]),
                DestinationTitle = Convert.ToString(rw["DestinationTitle"]),
                Place = Convert.ToString(rw["Place"])
            }).ToList();

        List<GetInventoryResultTagVm> enterInvList =
            dataAccess.SqlDataAdapter(enteredCommand)
            .Select()
            .Select(rw =>
            new GetInventoryResultTagVm()
            {
                InventoryHeaderId = Convert.ToInt32(rw["InventoryHeaderId"]),
                InventoryZone = Convert.ToString(rw["InventoryZone"]),
                InventoryDate = Convert.ToString(rw["Date"]),
                ProductCode = Convert.ToString(rw["ProductCode"]),
                ProductName = Convert.ToString(rw["ProductName"]),
                ProductSerial = Convert.ToString(rw["ProductSerial"]),
                Epc = Convert.ToString(rw["Epc"]),
                ProductCount = Convert.ToDecimal(rw["ProductCount"]),
                TagStatus = Convert.ToInt32(rw["TagStatus"]),
                ContractStatus = Convert.ToString(rw["ContractStatus"]),
                DestinationTitle = Convert.ToString(rw["DestinationTitle"]),
                Place = Convert.ToString(rw["Place"])
            }).ToList();

        #endregion

        return new(mainList, exitInvList, enterInvList);
    }
    #endregion

    #region OtherDeviceUHFLog
    public bool SSaveOtherDeviceUHFLog(List<string> EpcList, string DeviceType, string UserId)
    {
        var commandCheck = " SELECT Max(Coalesce(fld_OtherDeviceUHFLogActionCode,0))+1 FROM tbl_OtherDeviceUHFLog ";

        var command = "";

        var OtherDeviceUHFLogActionCode = (int)dataAccess.SqlDataAdapter(commandCheck).Select()
             .First().ItemArray.First();
        var childrenCommands = new List<KeyValuePair<string, KeyValuePair<string, object>[]>>();

        foreach (string Epc in EpcList)
        {
            var parameters2 = new List<KeyValuePair<string, object>>();

            command = @" INSERT INTO tbl_OtherDeviceUHFLog
                         (fld_OtherDeviceUHFLogActionCode, fld_OtherDeviceUHFLogDeviceType, fld_OtherDeviceUHFLogTagEpc, fld_OtherDeviceUHFLogUserId)
VALUES        (@fld_OtherDeviceUHFLogActionCode,@fld_OtherDeviceUHFLogDeviceType,@fld_OtherDeviceUHFLogTagEpc,@fld_OtherDeviceUHFLogUserId)";


            parameters2.Add(new("fld_OtherDeviceUHFLogActionCode", OtherDeviceUHFLogActionCode));
            parameters2.Add(new("fld_OtherDeviceUHFLogDeviceType", DeviceType));
            parameters2.Add(new("fld_OtherDeviceUHFLogUserId", UserId));
            parameters2.Add(new("fld_OtherDeviceUHFLogTagEpc", Epc));
            childrenCommands.Add(new(command, parameters2.ToArray()));
        }

        if (childrenCommands.Count > 0)
        {
            if (dataAccess.CmdSqlExecuteNonQueryWithTransaction(childrenCommands) > 0)
            {
                return true;

            }
            else
                return false;
        }
        else
            return false;


    }


    public DataTable SSearchOtherDeviceUHFLog(string UserToken)
    {
        var cmdData = @$"  SELECT  Top(10)   fld_OtherDeviceUHFLogActionCode as ActionCode,    dbo.GeorgianDateToJalaliDate( Max(fld_OtherDeviceUHFLogDateTime)  )+'_'+ ( SUBSTRING((SELECT  CONVERT(VARCHAR,  Max(fld_OtherDeviceUHFLogDateTime), 8) ),0,6))      + N' - '+Cast(Coalesce(Count(Distinct  fld_OtherDeviceUHFLogTagEpc ),0) as nvarchar(50))As ActionDesc 
FROM            tbl_OtherDeviceUHFLog
group by fld_OtherDeviceUHFLogActionCode
order by fld_OtherDeviceUHFLogActionCode desc ";
        var mainData = dataAccess.SqlDataAdapter(cmdData);
        if (mainData.Select().Any())
        {
            return mainData;
        }
        return null;
    }

