    #region ProductGuarantee
    public GetCustomerGuaranteeVm SGetCustomerGuarantee(CheckCustomerGuaranteeQuery search)
    {
        var command =
            $"""
            SELECT 
            COALESCE((SELECT ProductName FROM tbl_Tags WHERE ProductSerial = Guarantee.fld_ProductGuaranteeProductSerial),N'') AS ProductTitle,
            COALESCE(Guarantee.fld_ProductGuaranteeStartDate,N'') AS GuaranteeStartDate,
            COALESCE(CheckLog.fld_CGCLogDateTime,N'') AS GuaranteeCheckDateTime,
            COALESCE(Guarantee.fld_ProductGuaranteeActivationType, -1) AS [GuaranteeActivationType],
            COALESCE(fld_CGCLogProductSerial, N'' ) AS ProductSerial
            
            FROM tbl_CustomerGuaranteeCheckLog AS CheckLog LEFT OUTER JOIN tbl_ProductGuarantee AS Guarantee 
            ON CheckLog.fld_CGCLogProductSerial = Guarantee.fld_ProductGuaranteeProductSerial 
            
            WHERE fld_CGCLogDeviceIp = @deviceIp 
              AND fld_CGCLogRegCode = @regCode
            """;

        KeyValuePair<string, object>[] parameters = new[]
        {
            new KeyValuePair<string, object>("deviceIp", search.DeviceIp),
            new KeyValuePair<string, object>("regCode", search.RegCode)
        };

        var sqlData = dataAccess.SqlDataAdapter(command, parameters).Select();

        if (sqlData.Any())
        {
            GetCustomerGuaranteeVm result = new()
            {
                ProductTitle = sqlData.First().ItemArray[0].ToString(),
                GuaranteeStartDate = sqlData.First().ItemArray[1].ToString(),
                GuaranteeCheckDateTime = (DateTime)sqlData.First().ItemArray[2],
                ActivationType = (GuaranteeTypes)sqlData.First().ItemArray[3],
                ProductSerial = sqlData.First().ItemArray[4].ToString()
            };

            return result;
        }

        return null;
    }
