    public int SSaveLine(CreateLineCommand command)
    {
        if (command == null)
            throw new ArgumentNullException(nameof(command));


        bool exists = apiContext.Lines.Any(l => l.Id == command.Code);
        if (exists)
            return -1;
        bool titleExists = apiContext.Lines.Any(l => l.Title == command.Title);
        if (titleExists)
            return -2;

        var line = new Line
        {
            Id = command.Code,
            Title = command.Title,
            Desc = command.Desc,
            Data = string.Empty
        };

        apiContext.Lines.Add(line);

        return apiContext.SaveChanges();
    }




    public int SRemoveLine(string lineId)
    {
        string checkCommand = @"SELECT COUNT(*) FROM tbl_ProductPropertyB WHERE fld_ProductPropertyAId = @LineId";
        var checkResult = dataAccess.SqlDataAdapter(checkCommand,
            new KeyValuePair<string, object>("LineId", lineId)).Select();

        if ((int)checkResult[0].ItemArray[0] == 0)
        {
            var removeCommand = "DELETE FROM tbl_ProductPropertyA WHERE fld_ProductPropertyAId = @LineId";
            return dataAccess.CmdSqlExecuteNonQuery(removeCommand,
                new KeyValuePair<string, object>("LineId", lineId));
        }

        return -1;
    }

