    #region Print
    public List<string> SGetPrintFileNamesByMajorAndMinor(string major, string minor)
    {
        string folderPath = Path.Combine(Directory.GetCurrentDirectory(), "wwwroot", "Report");

        string searchPattern = $"{major}_{minor}_*.mrt";

        List<string> fileNames = new List<string>();

        if (Directory.Exists(folderPath))
        {
            var files = Directory.GetFiles(folderPath, searchPattern);

            foreach (var file in files)
            {
                string fileName = Path.GetFileNameWithoutExtension(file);

                var parts = fileName.Split('_');

                if (parts.Length >= 3)
                {
                    string namePart = string.Join("_", parts.Skip(2));
                    fileNames.Add(namePart);
                }
            }
        }

        return fileNames;
    }
