    public bool SSyncData(List<AndroidSyncDataDto> code)
    {
        foreach (var item in code)
        {
            if (item.OpType == AndroidSyncOpTypes.IdentifyPallet)
            {
                try
                {
                    foreach (var doc in item.Data)
                    {
                        string invCod = SCreateNewUHFReaderLogHeader(new() { StationCode = "0" }).ToString();

                        var data = doc.ToObject<Dictionary<string, object>>();

                        string deviceId = data["deviceId"]?.ToString() ?? "";
                        List<string> listTags = JsonConvert.DeserializeObject<List<string>>(data["listTags"].ToString());
                        string desc = data["desc"]?.ToString();
                        string gateType = data["GateType"]?.ToString();
                        string docId = data["doc"]?.ToString();
                        string destinationCode = data["DestinationCode"]?.ToString() ?? "";
                        string userToken = data.ContainsKey("userToken") ? data["userToken"]?.ToString() ?? "" : "";
                        string actionActiveControls = data.ContainsKey("ActionActiveControls") ? data["ActionActiveControls"]?.ToString() ?? "" : "";
                        string truckCrossId = data.ContainsKey("truckCrossId") ? data["truckCrossId"]?.ToString() ?? "" : "";
                        string saveDateTime = data.ContainsKey("saveDateTime") ? data["saveDateTime"]?.ToString() ?? DateTime.Now.ToString() : DateTime.Now.ToString();

                        JToken? actionDynamicData = data.ContainsKey("ActionDynamicData")
                            ? JToken.Parse(data["ActionDynamicData"].ToString())
                            : null;

                        SGetProductsInfoByEpcsForAction(listTags,
                            null,
                            userToken,
                            invCod,
                            gateType,
                            deviceId,
                            true,
                            false,
                            DateTime.Parse(saveDateTime));

                        SIdentifyPallets(
                            deviceId,
                            listTags,
                            desc,
                            gateType,
                            invCod,
                            docId,
                            destinationCode,
                            userToken,
                            actionDynamicData,
                            actionActiveControls,
                            truckCrossId
                        );
                    }
                }
                catch (Exception ex)
                {
                    logger.LogWarning(ex, ex.Message);
                    return false;
                }
            }
            else if (item.OpType == AndroidSyncOpTypes.RegisterByCountSerial)
            {
                List<RegisterByCodeSerialCountCommand> listBatch = new();

                foreach (var batchRegister in item.Data)
                {
                    var register = batchRegister.ToObject<RegisterByCodeSerialCountCommand>();

                    listBatch.Add(register);
                }

                SRegisterByCodeSerialCountBatch(listBatch);
            }
            else if (item.OpType == AndroidSyncOpTypes.RegisterOffline)
            {
                try
                {
                    List<RegisterOfflineTagsCommand>? listOffline = new();

                    foreach (var registerOffilne in item.Data)
                    {
                        var offline = registerOffilne.ToObject<RegisterOfflineTagsCommand>();


                        listOffline.Add(offline);
                    }

                    SProductRegisterOffline(listOffline);
                }
                catch (Exception ex)
                {
                    logger.LogWarning(ex, ex.Message);
                    return false;
                }
            }
            else if (item.OpType == AndroidSyncOpTypes.RegisterByCount)
            {
                List<RegisterByCodeCountCommand> listBatch = new();

                foreach (var batchRegister in item.Data)
                {
                    var register = batchRegister.ToObject<RegisterByCodeCountCommand>();

                    listBatch.Add(register);
                }

                SRegisterByCodeCountBatch(listBatch);
            }
            else if (item.OpType == AndroidSyncOpTypes.Inventory)
            {
                foreach (var inv in item.Data)
                {
                    var dict = inv.ToObject<Dictionary<string, object>>();

                    var header = dict["header"]?.ToString() ?? "";
                    var store = dict["store"]?.ToString() ?? "";
                    var deviceId = dict["deviceId"]?.ToString() ?? "";
                    var data = JsonConvert.DeserializeObject<string[]>(dict["data"].ToString());
                    var desc = dict["desc"]?.ToString() ?? "";

                    SSaveInventoryWithDesc(int.Parse(header), store, deviceId, data, desc);
                }

            }
        }

        return true;
    }

    public bool SRegisterByCodeSerialCountBatch(List<RegisterByCodeSerialCountCommand> commands)
    {
        using var transaction = apiContext.Database.BeginTransaction();

        try
        {
            int successCount = 0;
            foreach (var cmd in commands)
            {
                var result = SRegisterByCodeSerialCount(
                    cmd.Serial,
                    cmd.ProductCode,
                    cmd.RefCode,
                    cmd.Count,
                    cmd.Epc,
                    cmd.Zone,
                    cmd.UserToken,
                    cmd.Line,
                    cmd.Shift,
                    cmd.DestinationCode,
                    cmd.Properties
                );
                if (result != 1)
                {
                    transaction.Rollback();

                    return false;
                }

                successCount++;
            }

            transaction.Commit();

            return true;
        }
        catch (Exception ex)
        {
            logger.LogWarning(ex, ex.Message);

            transaction.Rollback();

            return false;
        }
    }

