    public DataTable SGetAggOfPrintByManuf(string manufacturer)
    {
        string query = $"""
                        SELECT        ProductCode AS ProductCode, COALESCE (SUM(ProductCountInPack), 0) AS Count
            FROM            tbl_Print
            WHERE        (DocumentId = N'{manufacturer}')
            GROUP BY ProductCode
            """;

        return dataAccess.SqlDataAdapter(query);
    }


    public DataTable SGetRemainRegisterByDoc(string DocumentId)
    {
        string query = $"""
                        SELECT        tbl_DocumentItem.fld_DocumentItemProductCode as ProductCode,(Cast(tbl_DocumentItem.fld_DocumentItemCount as decimal) - COALESCE (SUM(tbl_Print.ProductCountInPack), 0)) AS [Count]
            FROM            tbl_DocumentItem LEFT OUTER JOIN
                                     tbl_Print ON tbl_DocumentItem.fld_DocumentItemProductCode = tbl_Print.ProductCode AND tbl_DocumentItem.fld_DocumentKey = tbl_Print.DocumentId
            WHERE        (tbl_DocumentItem.fld_DocumentKey = N'{DocumentId}')
            GROUP BY tbl_DocumentItem.fld_DocumentItemProductCode,tbl_DocumentItem.fld_DocumentItemCount
            """;

        return dataAccess.SqlDataAdapter(query);
    }

    public bool PrintUpdatePrintStatus(string productSerial)
    {
        string command = """
                UPDATE tbl_Print SET RegisterFlag = 1
                WHERE ProductSerial = @productSerial
        """;
        int result = dataAccess.CmdSqlExecuteNonQuery(command, new KeyValuePair<string, object>("productSerial", productSerial));
        return result > 0;
    }

    public bool SEditProductInformation(string serial
        , string productCode
        , string line
        , string shift
        , string tagZone
        , string refCode
        , string desc
        , string properties
        , string userToken)
    {
        var tagRow = dataAccess.SqlDataAdapter(
            "SELECT TagInDestinationId, ProductSerial FROM tbl_Tags WHERE ProductSerial = @serial",
            new KeyValuePair<string, object>("serial", serial));

        if (tagRow.Rows.Count == 0)
            return false;

        string tagInDestinationId = tagRow.Rows[0]["TagInDestinationId"]?.ToString();

        var warehouseRow = dataAccess.SqlDataAdapter(
            "SELECT DestinationEpc FROM tbl_Destination WHERE DestinationCode = @code",
            new KeyValuePair<string, object>("code", tagInDestinationId));

        if (warehouseRow.Rows.Count > 0)
        {
            string warehousePermissions = warehouseRow.Rows[0]["DestinationEpc"]?.ToString();

            if (warehousePermissions.HasValue())
            {
                var json = JToken.Parse(warehousePermissions);

                var isEditAllowed = bool.Parse(json.Value<string>("AllowEditInformation"));

                if (!isEditAllowed)
                {
                    logger.LogInformation($"Cannot edit tag with serial of '{serial}'");

                    return false;
                }
            }
        }

        var commands = new List<KeyValuePair<string, KeyValuePair<string, object>[]>>();

        var printSets = new List<string>();
        var printParams = new List<KeyValuePair<string, object>>();
        printParams.Add(new("serial", serial));

        if (productCode.NotEquals("-1"))
        {
            printSets.Add("ProductCode = @productCode");
            printParams.Add(new("productCode", productCode));
        }
        if (line.NotEquals("-1"))
        {
            printSets.Add("ProductProductionLine = @line");
            printParams.Add(new("line", line));
        }
        if (shift.NotEquals("-1"))
        {
            printSets.Add("ProductProductionShift = @shift");
            printParams.Add(new("shift", shift));
        }
        if (tagZone.NotEquals("-1"))
        {
            printSets.Add("Location = @tagZone");
            printParams.Add(new("tagZone", tagZone));
        }
        if (refCode.NotEquals("-1"))
        {
            printSets.Add("DocumentId = @refCode");
            printParams.Add(new("refCode", refCode));
        }
        if (properties.NotEquals("-1"))
        {
            printSets.Add("ProductProperties = @properties");
            printParams.Add(new("properties", properties));
        }

        if (printSets.Count > 0)
        {
            string printCmd = $"UPDATE tbl_Print SET {string.Join(", ", printSets)} WHERE ProductSerial = @serial";
            commands.Add(new(printCmd, printParams.ToArray()));
        }

        var tagSets = new List<string>();
        var tagParams = new List<KeyValuePair<string, object>>();
        tagParams.Add(new("serial", serial));

        if (productCode.NotEquals("-1"))
        {
            tagSets.Add("ProductCode = @productCode");
            tagParams.Add(new("productCode", productCode));
        }
        if (line.NotEquals("-1"))
        {
            tagSets.Add("fld_ProductPropertyAId = @line");
            tagParams.Add(new("line", line));
        }
        if (shift.NotEquals("-1"))
        {
            tagSets.Add("fld_ProductPropertyBId = @shift");
            tagParams.Add(new("shift", shift));
        }
        if (tagZone.NotEquals("-1"))
        {
            tagSets.Add("TagZone = @tagZone");
            tagParams.Add(new("tagZone", tagZone));
        }
        if (properties.NotEquals("-1"))
        {
            tagSets.Add("ProductProperties = @properties");
            tagParams.Add(new("properties", properties));
        }

        if (tagSets.Count > 0)
        {
            string tagCmd = $"UPDATE tbl_Tags SET {string.Join(", ", tagSets)} WHERE ProductSerial = @serial";
            commands.Add(new(tagCmd, tagParams.ToArray()));
        }

        if (commands.Count == 0)
            return true;

        try
        {
            return dataAccess.CmdSqlExecuteNonQueryWithTransaction(commands) > 0;
        }
        catch (Exception ex)
        {
            logger.LogWarning(ex, ex.Message);

            return false;
        }
    }

    public PrintReportVm? SGetRevokedPrint(string serial)
    {
        var result = apiContext.Prints
                               .Include(p => p.SoftDeleteUser)
                               .FirstOrDefault(p => p.ProductSerial == serial && p.SoftDelete == 1);

        return mapper.Map<PrintReportVm>(result);
    }
